local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:92466"] = {n="大地的召唤",s="大地的召唤是一项元素试炼，灵性修行的初学者借此证明自己的坚定。求道者取回导师要求的材料，以此向导师展现自己的坚韧与决心。成功经受这项考验，便证明他们已准备好进入下一阶段的训练。",h="大地的召唤是一项元素试炼，灵性修行的初学者借此证明自己的坚定。求道者取回导师要求的材料，以此向导师展现自己的坚韧与决心。成功经受这项考验，便证明他们已准备好进入下一阶段的训练。",kw={"大地的召唤","决心","大地","元素","萨满祭司","诸灵","试炼"},ang={["class:Shaman"]="大地的召唤标志着初学者踏上与岩石和泥土之灵沟通的旅程，只有证明自己的决心，才能获得更深的领悟。",["faction:Horde"]="在部落各族之中，大地的召唤这类萨满试炼是灵性修行者的基础仪式。"},sec={{t="决心的考验",b="大地的召唤是有志于驾驭元素之人的基础试炼。初学者必须满足特定的要求，以检验自己的耐心、韧性，以及与大地顽强持久的本性之间的联系。完成这些要求，便能证明冒险者拥有与原始力量沟通所需的内在毅力。"},{t="下一步",b="求道者带着所需的供品归来时，导师便会认可他们毋庸置疑的坚韧与决心。初学者在元素的要求面前证明了自己的坚定，从而赢得认可，被视为已准备好迈出灵性旅程的下一步。"}},faq={{q="什么是大地的召唤？",a="大地的召唤是灵性修行初学者的入门仪式，要求求道者收集指定物品，证明自己的毅力与坚定，才能进入下一阶段的训练。",al={"什么是大地的召唤","大地的召唤任务"}},{q="完成这项试炼能证明什么？",a="完成这项任务，便能展现你的坚韧与毫不动摇的决心，让导师看到你有足够坚定的心志，能够承担更重的灵性职责。",al={"我证明了什么","坚韧与决心"}},{q="完成大地的召唤之后会怎样？",a="证明自己的决心后，导师便会认定你已准备好在与元素沟通的道路上迈出下一步。",al={"接下来做什么","下一个任务"}},{q="初学者为何必须与大地沟通？",a="大地代表着稳固、坚定的意志和不屈的力量。初学者必须证明自己的耐力，才能真正与大地之灵沟通。",al={"为何选择大地","大地之灵的含义"}},{q="谁负责指导大地的召唤？",a="灵性导师或萨满祭司导师会引导初学者完成试炼，检验他们的自律，以及是否已准备好与诸灵建立联系。",al={"谁给予这个任务","大地的召唤训练师"}},{q="谁有资格接受这项试炼？",a="大地的召唤与元素调和直接相关，是踏上元素之道的人在成长过程中必须经历的考验。",al={"任何人都能接受大地的召唤吗","大地的召唤是萨满祭司的试炼吗"}}},fp="13,139,17.238.0,13.185.0,26.123.0,43.147.0,48.110.0,40.111.0,31.139.0,40.72.0"}
P.entries["quest:92467"] = {n="大地的召唤",s="“大地的呼唤”是一项神圣的试炼，元素学徒需要在众灵高地饮用大地萨普塔，以穿透世界之间的帷幕。在一位元素之灵的指引下，寻求者将学习大地的坚韧与坚定不移的决心，并将其作为重燃他们与风之羁绊的基础。",h="“大地的呼唤”是一项神圣的试炼，元素学徒需要在众灵高地饮用大地萨普塔，以穿透世界之间的帷幕。在一位元素之灵的指引下，寻求者将学习大地的坚韧与坚定不移的决心，并将其作为重燃他们与风之羁绊的基础。",kw={"大地的召唤","大地萨普塔","元素","四风","众灵高地","萨满祭司","灵体"},ang={["class:Shaman"]="与元素的沟通始于像萨普塔这样强效的灵药，它能让萨满祭司的灵魂沉淀下来，从而与元素之灵直接交流。",["race:Skyborne"]="即使漂流在无尽云海的高处，与四风之灵渐行渐远，大地依然能为理解提供第一个坚实的立足点。"},sec={{t="萨普塔的本质",b="为了感知不可见的元素世界，萨满祭司会使用萨普塔——这是一种强大的魔法药剂，专门用于使凡人的灵魂与特定的元素位面达成共识。当意志坚定者饮下它时，萨普塔会开启他们的灵视，使那些凡人肉眼无法察觉的元素显现出来。由于其深奥的本质，这些药剂的配方是严密保守的秘密，只有少数修行者知晓。"},{t="众灵高地",b="仪式传统严令要求萨普塔只能在圣地饮用。为了与大地沟通，学徒们被指引穿过一条山口，向东北方向前往众灵高地。在这片神圣的土地上饮下药剂，寻求者便能穿透帷幕，看见灵体们想要展示的一切。"},{t="大地的力量",b="饮下大地萨普塔后，学徒会遇见一位元素向导，它将学徒认作是寻求探究“风为何离去”的四风之子。虽然大地之灵无法解释风之灵那难以捉摸的动机，但它提供了关于大地那坚定不移的决心与力量的教诲。即便身处无尽云海的高空之上，扎根于大地也是再次与风对话所必需的第一步。"}},faq={{q="什么是大地萨普塔？",a="萨普塔是一种特殊的魔法药剂，用于将萨满祭司的灵魂与特定的元素绑定。当意志坚定者服下它时，它会显现出普通感官无法察觉的隐藏元素之灵。",al={"什么是大地萨普塔","萨普塔的解释","萨普塔的作用"}},{q="在哪里饮用大地萨普塔？",a="大地萨普塔必须在众灵高地饮用，那是一处神圣的地点，位于任务给予者东北方的山口之上。萨普塔必须在圣地而不是普通地点饮用。",al={"在哪里饮用大地萨普塔","众灵高地的位置","众灵高地在哪里"}},{q="为什么萨普塔只能在圣地饮用？",a="萨普塔是一种强效的仪式药剂，旨在将凡人的灵魂直接与元素相连。根据萨满教义，必须在指定的圣地内饮用，才能与灵体进行正确的沟通。",al={"为什么要在圣地饮用萨普塔","可以随处饮用萨普塔吗"}},{q="为什么灵体会称寻求者为“四风之子”？",a="众灵高地上的元素之灵迎接学徒时，称其为四风之子，因为这位学徒正在寻找关于风为何离去以及如何挽回它们眷顾的答案。",al={"谁是四风之子","为什么叫四风之子"}},{q="风之灵为何离去？",a="风之灵已经变得疏远，但即使是众灵高地上的大地之灵，也不清楚它们确切的动机和去向。",al={"风为什么离开了","风去了哪里"}},{q="与大地沟通如何帮助人们重新连接风？",a="大地代表着不屈的力量与决心。即使置身于无尽的云海之中，所有生物依然与大地相连，掌握它的稳定是重新获得与四风沟通的第一步。",al={"为什么首先是大地","大地如何帮助与风沟通"}}},fp="13,133,23.267.0,19.241.0,21.381.1,23.161.0,39.114.0,47.154.0,70.111.0,39.123.0,72.194.0"}
P.entries["quest:92468"] = {n="大地的召唤",s="“大地的召唤”是一项神圣的交流试炼，修行者从土元素灵那里获得一块粗石英。这块矿石碎片被带到森达尔林地的塑风者博罗斯手中，成为了修行者第一个大地图腾的核心，以此巩固他们与元素力量的羁绊。",h="“大地的召唤”是一项神圣的交流试炼，修行者从土元素灵那里获得一块粗石英。这块矿石碎片被带到森达尔林地的塑风者博罗斯手中，成为了修行者第一个大地图腾的核心，以此巩固他们与元素力量的羁绊。",kw={"大地的召唤","大地图腾","元素","粗石英","萨满","森达尔林地","塑风者博罗斯"},ang={["class:Shaman"]="获得你的第一个图腾标志着与元素力量交流的开始。它作为一种必不可少的物理焦点，用于引导大地属性的法术和仪式。",["race:Skyborne"]="对于寻求重连风之力的逐天者来说，掌握大地是至关重要的第一步。通往聆听风声的道路，始于将自己扎根于大地的坚实基础之上。"},sec={{t="大地的馈赠",b="当土元素灵授予修行者一块粗石英碎片，作为他们交流的活生生的证明时，任务便开始了。元素灵指引持有者将此信物带给森达尔林地的塑风者博罗斯，并解释说即使是最微小的碎片也蕴含着持久的力量。元素灵在给予恩惠与尊重之前，会考验修行者的耐心、韧性和智慧。"},{t="四种元素与图腾",b="塑风者博罗斯利用粗石英作为核心来制作大地图腾。他提醒修行者，元素之道是多层面的：虽然他们最终的愿望可能是聆听和吟唱风之歌，但真正的精通需要理解所有四种元素力量，而这必须从脚下坚实的大地开始。"}},faq={{q="塑风者博罗斯是谁？",a="塑风者博罗斯（简称博罗斯）居住在森达尔林地。作为一名资深的修行者和工匠，他引导修行者了解元素灵，并用元素馈赠塑造他们的图腾媒介。",al={"博罗斯是谁","塑风者博罗斯位置","森达尔林地在哪里"}},{q="粗石英的用途是什么？",a="粗石英是由土元素灵直接授予的元素碎片，作为你们相遇和交流的证明。塑风者博罗斯将其用作你所制作的大地图腾的基础核心与心脏。",al={"什么是粗石英","大地碎片","石英用途"}},{q="为什么需要大地图腾？",a="大地图腾是与大地元素灵沟通并引导大地法术所必需的个人媒介。除了象征修行者的身份外，它还将修行者锚定在世界的基础元素之上。",al={"大地图腾的作用","图腾目的","为什么需要图腾"}},{q="为什么在与风交流之前必须先与大地沟通？",a="虽然修行者可能渴望聆听和吟唱风之歌，但风只代表了世界元素平衡的一个方面。修行者必须首先学习并掌握所有四种元素，从大地的稳定性、耐心和力量开始。",al={"为什么从大地开始","追寻风之力","四种元素"}},{q="森达尔林地在哪里？",a="森达尔林地是一处圣所，塑风者博罗斯在那里处理元素事务，并指导踏上萨满之旅的新手。",al={"森达尔林地坐标","森达尔林地区域"}},{q="大地元素灵传授了什么智慧？",a="大地元素灵教导说，大小并不重要，因为即使是最小的石头也能在更伟大的事物崩塌后长久存在。它要求用耐心、内在力量和对智慧的追求，来换取相互的尊重与和谐。",al={"元素的要求","大地哲学"}}},fp="13,200,16.270.0,31.290.0,24.205.0,40.156.0,32.191.0,63.180.0,31.136.0,41.202.0"}
P.entries["quest:92469"] = {n="Return to Rorian",s="“回到罗瑞安”是一项任务，需要将前线的紧急报告送回泽风岛的森达尔林地。在帮助亚拉·风语者对抗入侵的势力后，一名冒险者被派遣去通知Rorian the Dayseeker，奥拉凯斯教派已经通过扰乱当地的风之精魂升级了他们的行动。",h="“回到罗瑞安”是一项任务，需要将前线的紧急报告送回泽风岛的森达尔林地。在帮助亚拉·风语者对抗入侵的势力后，一名冒险者被派遣去通知Rorian the...",kw={"奥拉凯斯","教派","罗瑞安","立石","森达尔林地","风之精魂","亚拉·风语者","泽风岛"},ang={["class:Druid"]="保卫森达尔林地并维护泽风岛神圣土地内的宁静与和谐，这自然与德鲁伊的誓言相符。",["class:Shaman"]="奥拉凯斯蓄意煽动风之精魂的发现，直击萨满维护元素平衡职责的核心。"},sec={{t="一份紧急报告",b="在扰乱了骚扰泽风岛的煽动者之后，亚拉·风语者留下来清理剩余的敌对势力，同时交给你一项重要职责：传递情报。森达尔林地需要知道神秘的奥拉凯斯已经不再仅仅是在暗中活动了。"},{t="立石处的升级",b="收到报告后，Rorian the Dayseeker承认森达尔林地的领袖们早已在远处观察该教派的动向。然而，教徒们在立石附近煽动当地的风之精魂，标志着这一大胆且令人不安的升级，林地领导层已无法再坐视不管。"}},faq={{q="是谁派你与罗瑞安交谈的？",a="在你帮助压制了威胁当地的敌对煽动者后，亚拉·风语者派你去向罗瑞安报告。",al={"任务给予者","谁开启回到罗瑞安","亚拉·风语者"}},{q="寻日者罗瑞安在哪里？",a="寻日者罗瑞安位于森达尔林地，那是林地领袖们监督泽风岛事务的定居点。",al={"罗瑞安在哪里","罗瑞安位置","森达尔林地罗瑞安"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是一个在泽风岛活动的教派。虽然之前在远处默默监视，但他们最近在立石附近煽动元素风之精魂的行为使他们成为了一个现实的威胁。",al={"什么是这个教派","谁是奥拉凯斯","奥拉凯斯教派"}},{q="为什么罗瑞安对这个消息并不感到惊讶？",a="罗瑞安和林地领导层早已知晓该教派在岛上的动向，尽管他们之前选择静观其变，而不是直接对抗。",al={"罗瑞安知道吗","罗瑞安反应","为什么不意外"}},{q="向罗瑞安报告后会发生什么？",a="在确认你的报告并感谢你对森达尔林地的帮助后，罗瑞安会派你去找烈风使者艾瑟恩，他是长老议会的一员，一直在注视着你。",al={"后续任务","回到罗瑞安之后是什么","回到罗瑞安之后"}},{q="为什么亚拉留在了后面？",a="亚拉·风语者选择留在冲突地点清理任何残余的落单者，同时让你带着紧急情报先行一步。",al={"为什么亚拉留下","亚拉去哪里了","亚拉·风语者职责"}}},fx={aa0b8ee2={q="雅拉·捕风者为什么派你去找罗里安？",a="雅拉需要立即通知森达尔林地的领导者，奥拉凯斯邪教已确认现身。她会留在原地处理战场上的残余敌人，而逐日者罗里安必须获知邪教的行动升级及其对当地灵体造成的影响，以便林地协调应对。",al={"为什么要向罗里安报告","雅拉·捕风者的动机","雅拉为什么要通知罗里安"}}},fp="16,202,13.176.0,33.264.1,35.115.0,38.100.0,21.192.0,41.160.0,44.171.1,25.117.0"}
P.entries["quest:92470"] = {n="Foul Matriarch",s="“Foul Matriarch”是Aetheen of the Gales指派给森达尔村初出茅庐的新手的生存试炼。任务要求深入南部的洞穴，扑杀以食腐为生的ursera，并击杀它们凶残的巢母Urs'anah。完成这次狩猎证明冒险者拥有了面对泽风岛更广阔天地中巨大危险所需的决心。",h="“Foul Matriarch”是Aetheen of the...",kw={"疾风之艾希恩","邪恶的族母","森达尔洞穴","森达尔林地","森达尔村","乌尔萨娜","乌瑟拉","泽风岛"},ang={["class:Hunter"]="追踪像Urs'anah这样凶猛的穴居巢母，对于初出茅庐的猎人来说，是对比野兽知识和战斗决心的基本测试。",["race:Skyborne"]="对于天裔的新手来说，证明对Urs'anah这种陆地掠食者的掌控能力，展现了在地面上的自给自足能力，以及走出封闭的起点、踏上冒险旅程的准备。"},sec={{t="决心的考验",b="Aetheen of the Gales一直在关注那些在森达尔村周围站稳脚跟的新人。一旦新手表现出初步的能力，Aetheen就会发布一项危险的成人礼：直接攻击威胁周边地区的掠食性野生生物。新手不会仅仅在大路上战斗，而是被直接派往南部的黑暗洞穴，以削减当地ursera族群的数量，并对抗它们的巢母。"},{t="Urs'anah的威胁",b="当地的游侠们早就注意到了ursera的凶猛，但没有哪一个像它们强大的巢母Urs'anah那样对避难所构成如此大的威胁。她潜伏在森达尔洞穴的深处，指挥着她的食腐同类，并极具侵略性地守卫着自己的巢穴。带回她的头颅，是冒险者有能力对付凶猛野兽，并准备好前往起始林地之外冒险的明确证明。"}},faq={{q="是谁指派了击杀乌尔斯阿娜的任务？",a="烈风使者艾瑟恩在森达尔村发布了这项试炼。她会密切关注那些引起了罗瑞安等当地人物注意的优秀新人，然后用这次危险的狩猎来测试他们的勇气。",al={"谁发布了邪恶的母兽任务","邪恶的母兽任务发布者","谁是疾风使者艾瑟恩"}},{q="在哪里可以找到乌尔斯阿娜和乌瑟拉熊食腐者？",a="乌尔斯阿娜和乌瑟拉熊食腐者栖息在森达尔村南部和西南部的洞穴中，位于森达尔林地的山丘里。巢母本人在洞穴的深处筑巢。",al={"乌尔萨娜位置","乌尔萨娜在哪里","泽风岛的乌瑟拉洞穴","森达尔洞穴位置"}},{q="什么是乌瑟拉熊？",a="乌瑟拉熊是泽风岛荒野峭壁上原生的极具侵略性的熊类掠食者。如果不加控制，它们的食腐群落会在靠近森达尔村等居民点的地方筑巢，造成危险。",al={"什么是乌瑟拉","乌瑟拉背景故事","乌瑟拉是熊吗"}},{q="完成这次狩猎对冒险者意味着什么？",a="击杀乌尔萨娜是一次关键的成人礼。通过克服邪教入侵者和林地中最危险的野生生物，猎人证明了他们已经准备好离开森达尔村的庇护，并承担起泽风岛上更广泛的责任。",al={"为什么要杀乌尔萨娜","邪恶的母兽的重要性"}}},fx={["03aee340"]={q="疾风使者艾瑟恩为什么派你去对付这位首领？",a="疾风使者艾瑟恩一直在关注你的进展，并要求考验你的决心。她需要知道你是否拥有足够的力量和坚韧，能够在泽风岛应对远为严峻的危险。击败这位凶险的首领，证明你有能力走出森达尔村的庇护，为岛屿经受更艰难、更危险的考验。",al={"艾瑟恩为什么要杀死乌尔萨娜","艾瑟恩的动机","为什么要杀乌尔萨娜"}},["30b9798a"]={q="乌尔萨娜之首有什么用？",a="这颗头颅是首领已被杀死的确凿证据。乌尔萨娜是当地游侠熟知的恶名昭彰的母兽，艾瑟恩只接受她被砍下的头颅，以确认这头危险的野兽确实已被除掉。",al={"乌尔萨娜之首有什么用","为什么要留下乌尔萨娜的头","乌尔萨娜头颅的用途"}},a1adff34={q="乌尔萨娜是谁？",a="乌尔萨娜是当地熊怪的凶猛首领和母兽，栖居在森达尔村南面的洞穴中。她为岛上的游侠所熟知，也令他们畏惧；她统领着食腐兽群，是林地掠食性野兽中最大的威胁。",al={"乌尔萨娜是谁","乌尔萨娜是什么","乌尔萨娜的背景"}}},fp="14,220,17.293.0,22.297.0,38.181.0,54.169.0,18.178.0,57.242.0"}
P.entries["quest:92471"] = {n="Aetheen of the Gales",s="这个任务标志着泽风岛上年轻冒险者的一场成年仪式，指引他们向岛上的一位主要权威汇报。在完成了Rorian the Dayseeker布置的初步试炼后，表现优异的年轻人会被派往森达尔林地，去见Aetheen of the Gales。作为一名能够解读风语的长者，她负责评估下一代人的能力。",h="这个任务标志着泽风岛上年轻冒险者的一场成年仪式，指引他们向岛上的一位主要权威汇报。在完成了Rorian the Dayseeker布置的初步试炼后，表现优异的年轻人会被派往森达尔林地，去见Aetheen of the...",kw={"疾风之艾希恩","长老议会","寻日者罗里安","申多雷","森达尔林地","泽风岛"},sec={{t="潜力的衡量",b="泽风岛上的见习者们在早期面临的任务并非琐碎的杂事；它们是考察这些正在崛起的年轻人是否具备保卫家园所需的坚韧与精神的非正式测试。认识到岛上的生活正面临越来越多的考验，像Rorian the Dayseeker这样的导师会密切关注那些展现出足以承担更大责任能力的候选者。"},{t="森达尔林地的风语者",b="在森达尔林地的深处坐着Aetheen of the Gales，她是治理泽风岛的长老议会中受人尊敬的一员。Aetheen将时间花在解读气流和评估那些成年的年轻shen'dorei身上。站在她的面前，意味着一名初学者已经超出了边缘巡逻任务的范畴，准备好去应对社区面临的直接威胁。"}},faq={{q="疾风使者艾瑟恩是谁？",a="疾风使者艾瑟恩是泽风岛的一位领袖，也是长老议会的席位成员。她监测着森达尔林地的风向，并亲自评估那些成年的年轻申多雷，以确保他们做好了保卫家园的准备。",al={"艾瑟恩是谁","疾风使者艾瑟恩的角色","泽风岛的艾瑟恩"}},{q="为什么罗瑞安会派玩家去见艾瑟恩？",a="逐日者罗瑞安通过早期的任务来评估见习冒险者。一旦冒险者证明了自己的能力和韧性，罗瑞安就会指引他们去找艾瑟恩，以便他们的技能得到评判，并被引导去应对岛上面临的更高级别的挑战。",al={"为什么要去见艾瑟恩","罗里安将玩家引向艾瑟恩","任务目的"}},{q="疾风使者艾瑟恩在哪里可以找到？",a="她居住在泽风岛的森达尔林地中，在那里研究风的流动并监管当地年轻人的成年试炼。",al={"艾瑟恩的位置","艾瑟恩在哪里","森达尔林地的艾瑟恩"}},{q="什么是长老议会？",a="长老议会是指导泽风岛上申多雷的行政机构。像艾瑟恩这样的领袖在议会中任职，以监管社区的生存、领导力以及备战情况。",al={"泽风岛的长老议会","谁统治泽风岛"}},{q="向艾瑟恩汇报后会发生什么？",a="在确认了一名年轻冒险者为泽风岛服务的意愿后，艾瑟恩会指派严肃的任务来处理当地荒野的危险，首先从像具有攻击性的野生动物和邪恶的族群首领这样的威胁开始。",al={"见完艾瑟恩后的下一个任务","艾瑟恩想要什么"}},{q="'成年'对于泽风岛上的申多雷意味着什么？",a="对于泽风岛上的年轻人来说，成年意味着通过身体和魔法试炼来证明自己。这不仅仅是一场仪式，更要求年轻的申多雷在踏入服役行列之前，向像艾瑟恩这样的岛屿长者展示其实际能力。",al={"申多雷的成年仪式","泽风岛的成年仪式"}}},fx={d6e78b3c={q="罗里安为什么非要你去和艾瑟恩谈谈？",a="你在岛上早期承担的任务，实际上一直被悄悄视作对你胆识的考验。泽风岛正面临严峻挑战，岛上的领袖需要有能力、有朝气、即将成年的年轻辛多雷挺身而出，帮助族人。你已经证明了自己的能力，因此罗里安选中了你，认为你已准备好接受长老艾瑟恩的直接考核。",al={"为什么要找疾风使者艾瑟恩","罗里安为什么选中我","为什么派我去找艾瑟恩"}}},fp="20,159,22.226.0,32.303.0,28.215.0,45.180.0,40.145.0,30.160.0,40.184.0,62.200.0"}
P.entries["quest:92472"] = {n="下一步",s="随着森达尔村附近的野兽威胁得到解决，Aetheen of the Gales指引旅行者前往南方的申达尔村。这趟旅程标志着从清除野生动物转向对抗崇拜风领主奥拉凯斯的奥拉凯斯教派的狂热分子。",h="随着森达尔村附近的野兽威胁得到解决，Aetheen of the Gales指引旅行者前往南方的申达尔村。这趟旅程标志着从清除野生动物转向对抗崇拜风领主奥拉凯斯的奥拉凯斯教派的狂热分子。",kw={"疾风之艾希恩","奥拉凯斯教派","奥拉凯斯","康斯塔布·奥恩达","申达尔村","天空之墙","森达尔村","泽风岛"},ang={["class:Shaman"]="萨满祭司会意识到盲目崇拜像奥拉凯斯这样的元素领主的危险性，因为其反复无常的本性往往要求的是奴役而非平衡。",["race:Skyborne"]="对于天空之子来说，对抗奥拉凯斯教派就是直接反击那些威胁泽风岛各家园定居点安全的元素狂热。"},sec={{t="离开森达尔村",b="在证明了自己有能力对付泽风岛北部荒野的掠食者和那些祸害当地的母兽之后，冒险者们肩负起了更广泛的职责。Aetheen of the Gales认识到，简单的除害工作与岛上正在滋生的真正危险相比微不足道。为了保护岛上的居民，必须派遣能干的防卫者前往支援边远定居点。"},{t="邪教笼罩的阴影",b="泽风岛南部面临的主要危险是奥拉凯斯教派。这些教徒被描述为残酷的狂热分子，他们致力于侍奉天空之墙元素位面的统治者——风领主奥拉凯斯。他们日益增长的力量对申达尔村构成了直接威胁。因此，Aetheen派遣旅行者向南沿路而行，越过高地中潜伏的伏击者，去支援康斯塔布·奥恩达的当地守卫队。"}},faq={{q="这趟旅程通往何处？",a="道路从森达尔村向南延伸至申达尔高地，最终抵达申达尔村，康斯塔布·奥恩达在那里负责当地的防御工作。",al={"我该去哪","下一个据点","目的地"}},{q="康斯塔布·奥恩达是谁？",a="康斯塔布·奥恩达是申达尔村的民事和军事长官，负责维持秩序，目前正致力于保护城镇免受不断升级的邪教威胁。",al={"康斯塔布·奥恩达","奥恩达是谁"}},{q="什么是奥拉凯斯教派？",a="奥拉凯斯教派是泽风岛上一群残忍的狂热分子，他们崇拜天空之墙的元素领主风领主奥拉凯斯。他们咄咄逼人的扩张对岛上的定居点构成了直接威胁。",al={"奥拉凯斯教派是谁","奥拉凯斯教派背景","邪教徒"}},{q="奥拉凯斯是谁？",a="风领主奥拉凯斯是天空的元素统治者，也是天空之墙的主宰，深受风元素崇拜，并被奥拉凯斯教派疯狂供奉。",al={"奥拉凯斯是谁","风领主","天空之墙统治者"}},{q="为什么艾瑟恩要让旅行者离开森达尔？",a="随着森达尔周边的直接威胁得到处理，艾瑟恩将久经考验的防卫者派往申达尔村，那里奥拉凯斯教派的咄咄逼人对整个岛屿构成了更大的危险。",al={"为什么离开森达尔","艾瑟恩的目标"}},{q="前往申达尔村的路上有什么危险？",a="向南的道路穿过申达尔高地，奥拉凯斯伏击者和流氓教徒会在那里骚扰往返于岛上各定居点的旅行者。",al={"道路危险","前往南方","高地危险"}}},fp="13,134,23.226.0,30.315.0,29.140.0,23.152.0,26.157.0,15.133.0,56.194.0,52.145.0"}
P.entries["quest:92473"] = {n="Aggressive Encroachment",s="Aggressive Encroachment 是由 Valreaa Valewind 发出的任务，旨在保护当地定居点免受走投无路的野生动物的侵害。附近巢穴的厄尔瑟拉兽变得越来越大胆，开始闯入村庄并威胁村民。",h="Aggressive Encroachment 是由 Valreaa Valewind 发出的任务，旨在保护当地定居点免受走投无路的野生动物的侵害。附近巢穴的厄尔瑟拉兽变得越来越大胆，开始闯入村庄并威胁村民。",kw={"爪子","古树","侵扰","瘦弱的厄尔瑟拉兽","森达尔林地","厄尔瑟拉兽","瓦蕾娅·谷风"},ang={["class:Druid"]="德鲁伊们会意识到林地的微妙平衡正在被破坏，并指出当地厄尔瑟拉兽突然的攻击性和营养不良，预示着当地生态系统存在未被察觉的扰动。",["class:Hunter"]="猎人们会立刻理解饥饿的掠食者所带来的危险，因为当受到饥荒驱使时，绝望的野兽会抛弃对类人定居点天然的警惕。"},sec={{t="绝望的掠食者",b="在村庄西南方筑巢的厄尔瑟拉兽群体已经成为一个紧迫的安全隐患。最近，一只饥饿的幼兽径直游荡到村庄中央的古树下，险些抓伤了在附近玩耍的幼童。定居点的游侠被迫在悲剧发生前将这只野兽击毙。"},{t="清理林地",b="游侠们意识到饥饿和匮乏正在驱使这些掠食者袭击文明地带，因此下令清理森达尔林地中瘦弱的厄尔瑟拉兽。通过清除在巢穴外徘徊的绝望且营养不良的野兽，林地游侠希望在查明是什么在扰乱当地野生动物之前阻止进一步的侵扰。"}},faq={{q="谁提供了 咄咄逼人的侵占？",a="该任务由 瓦蕾娅·谷风 提供，她是游侠中的领袖，负责看守林地并保护附近的定居点免受掠食野兽的侵扰。",al={"谁给予 咄咄逼人的侵占","任务发布者","瓦尔蕾娅·谷风 任务"}},{q="为什么厄尔瑟拉兽会游荡到如此靠近村庄的地方？",a="厄尔瑟拉兽正遭受饥饿与绝望的折磨，这驱使它们远离正常的狩猎场，深入到定居点的中心地带。",al={"为什么厄尔瑟拉兽会攻击","厄尔瑟拉兽的攻击性","为什么厄尔瑟拉兽发狂"}},{q="在哪里可以找到瘦弱的厄尔瑟拉兽？",a="瘦弱的厄尔瑟拉兽在村庄西南方的森达尔林地出没，它们徘徊在巢穴入口周围，而不是深入洞穴内部。",al={"瘦弱的厄尔瑟拉兽在哪里","厄尔瑟拉兽位置","森达尔林地的熊"}},{q="是什么险些发生的悲剧促成了这次清理行动？",a="一只未成年的厄尔瑟拉兽径直游荡到了村庄中心的古树旁，并试图袭击附近玩耍的幼童。游侠们及时杀死了这只野兽，保住了孩子的性命。",al={"厄尔瑟拉兽攻击男孩","村庄里发生了什么","古树旁的男孩"}},{q="为什么厄尔瑟拉兽的行为如此反常？",a="游侠们注意到最近厄尔瑟拉兽变得异常具有攻击性，但导致它们突然食物短缺和行为改变的根本原因仍是一个未解之谜。",al={"厄尔瑟拉兽发生了什么变化","为什么厄尔瑟拉兽挨饿"}},{q="瓦蕾娅·谷风 需要什么证据？",a="瓦蕾娅 要求从在林地徘徊的营养不良的野兽身上收集六只瘦弱的厄尔瑟拉兽爪，以确保这些危险的掠食者已被解决。",al={"我要收集什么","咄咄逼人的侵占 目标"}}},fp="23,153,19.242.0,17.281.0,35.147.0,53.121.0,38.116.0,37.164.0,43.126.0,41.156.0"}
P.entries["quest:92474"] = {n="Falling With Style",s="“Falling With Style”是森达尔村年轻天裔的入门成人礼。恶作剧的Myriaal Mistwake会在当地的瞭望塔顶端提出挑战，要求新手从平台上跳向下方的Rorian the Dayseeker，以测试他们与生俱来的缓落能力。",h="“Falling With Style”是森达尔村年轻天裔的入门成人礼。恶作剧的Myriaal Mistwake会在当地的瞭望塔顶端提出挑战，要求新手从平台上跳向下方的Rorian the...",kw={"优雅地坠落","米莉娅尔·雾醒","寻日者罗里安","缓落","森达尔村","凌空行走","瞭望塔","泽风岛"},ang={["race:Skyborne"]="这项早期的考验向天裔新手介绍了他们天生的御风魔法所涉及的实际机制和文化争论。"},sec={{t="塔顶一跃",b="Myriaal Mistwake栖身于泽风岛上森达尔村的高处，邀请年轻的天裔通过一场大胆的游戏来考验他们的血统。Myriaal并没有将他们天生的魔法天赋视为需要严格束缚的神圣遗物，而是鼓励新手从瞭望塔的边缘跃入空中。此举既实用又有趣：在走出丛林、面对危险境地之前，先掌握凌空行走的本能艺术。"},{t="性情之差",b="这项练习生动地展示了天裔的两种截然不同的态度。虽然Myriaal以突然降落并惊吓旁观者为乐，但Rorian the Dayseeker却代表了传统的谨慎。当新手滑翔降落到他面前时，Rorian会告诫这种鲁莽的行为，警告说轻率地耗尽自己的魔法天赋可能会让旅行者在危险来临时陷入无助。尽管如此，他也承认在村庄的安全范围内进行受控练习有其必要性。"}},faq={{q="这个任务的目的是什么？",a="该任务旨在教授新手天裔如何运用他们天生的“凌空行走”能力，让他们熟悉如何从高处控制缓慢降落。",al={"这个任务有什么作用","优雅坠落的目的","为什么要完成这个任务"}},{q="谁提供这个任务，在哪里提供？",a="该任务由米莉娅尔·雾醒提供，她正守候在泽风岛上俯瞰森达尔村的木制瞭望塔顶端。",al={"任务发布者","在哪里开始优雅坠落","谁发布了优雅坠落"}},{q="你会降落在谁面前？",a="你会降落在逐日者罗瑞安附近，米莉娅尔希望通过这一跳吓他一跳。",al={"应该降落在谁附近","罗里安是谁","优雅坠落交任务地点"}},{q="为什么罗瑞安会对这一跳感到不满？",a="罗瑞安认为天生的魔法天赋应该妥善保存并以纪律来对待，而不是浪费在惊吓他人的恶作剧上。",al={"为什么罗里安很生气","罗里安的反应","为什么罗里安会责备你"}},{q="正在练习什么能力？",a="该任务教授使用“凌空行走”，这是一种天生的天裔能力，可以减缓角色的下落速度并防止跌落伤害。",al={"使用了什么能力","凌空行走任务","天生御空种族能力"}},{q="这件事发生在哪里？",a="这项练习发生在森达尔村，该村位于天裔的先祖发源地——泽风岛。",al={"任务地点","森达尔村在哪里","这是什么区域"}}},fx={fb92945d={q="米莉娅尔·雾醒为什么让你从瞭望塔上跳下去？",a="米莉娅尔·雾醒把这次跳跃当作一场有趣的挑战，帮助你练习与生俱来的踏空能力；不过她也另有顽皮的打算：她想吓逐日者罗里安一跳，再看他气急败坏的样子取乐。",al={"米莉娅尔为什么想这么做","米莉娅尔·雾醒的动机","为什么要从塔上跳下去"}}},fp="18,151,21.318.0,27.303.0,34.105.0,30.91.0,28.80.0,32.125.0,32.95.0,27.103.0"}
P.entries["quest:92479"] = {n="A Scribbled Letter",s="“潦草的信件”是一封在冒险者与附近的狗头人发生初步冲突后，送达北郡修道院的征召令。它盖有托德林·刃茎的印章，指引有前途的新兵去寻求他的训练和指导。这封信标志着为保卫暴风城王国而培养防御者的关键一步。",h="“潦草的信件”是一封在冒险者与附近的狗头人发生初步冲突后，送达北郡修道院的征召令。它盖有托德林·刃茎的印章，指引有前途的新兵去寻求他的训练和指导。这封信标志着为保卫暴风城王国而培养防御者的关键一步。",kw={"潦草的信件","猎人训练师","狗头人营地","北郡修道院","北郡山谷","托德林·刃茎"},ang={["class:Hunter"]="托德林·刃茎在北郡修道院指导猎人，他注意到随着新的种族拿起弓箭来保卫暴风城免受野兽和害虫的侵害，时代已经变了。",["faction:Alliance"]="在北郡修道院训练熟练的防御者有助于保护艾尔文森林，使其免受日益严重的狗头人入侵和其他对暴风城王国的威胁。"},sec={{t="北郡的征召",b="当冒险者从困扰着山谷的狗头人营地的战斗中归来时，北郡修道院的人会收到一封匆忙写就的信件。这封信盖着托德林·刃茎的印章，要求收信人在处理其他事务前立即关注此事。这封信是一份紧急征召令，旨在将初露锋芒的勇士与修道院保护范围内的正规导师联系起来。"},{t="危难时刻的指引",b="当收到这封信时，托德林·刃茎感叹世道变了，并观察到陌生的面孔纷纷拿起武器来保卫王国。他承认周边的荒野日益凶险，因此邀请旅行者们无论昼夜都能来寻求他的建议，磨练技能并协助暴风城饱受困扰的人民。"}},faq={{q="什么是“潦草的信件”？",a="“潦草的信件”是一封冒险者从狗头人营地归来后，在北郡修道院收到的信件。信上带有托德林·刃茎的印章，指引收信人前往山谷寻找他进行指导和训练。",al={"什么是潦草的信件","潦草的信件任务","托德林的来信"}},{q="谁寄出了这封信？",a="这封信是由托德林·刃茎撰写并封缄的，他是一位驻扎在北郡修道院的当地训练师，为学习技艺的初出茅庐的冒险者提供指导。",al={"谁寄出的信","谁写的信","潦草的信件作者"}},{q="在哪里可以找到托德林·刃茎？",a="托德林·刃茎位于北郡山谷的北郡修道院。他昼夜驻扎在那里，随时准备为旅行者提供指导和建议。",al={"托德林·刃茎在哪里","托德林位置","寻找托德林·刃茎"}},{q="托德林·刃茎为什么要寄这封信？",a="在冒险者证明了自己对抗当地狗头人的能力后，托德林会派人传话，以确保他们接受适当的训练。他的目标是让他们为威胁北郡居民和更广阔的暴风城王国的日益严重的危险做好准备。",al={"托德林为什么寄信","托德林·刃茎的目的","为什么要征召"}},{q="目前有哪些威胁影响着北郡？",a="北郡山谷面临着好战的狗头人营地以及在周边森林游荡的危险食人猛兽的入侵，促使当地导师集结并训练有能力的战士。",al={"北郡有什么威胁","北郡修道院的危险","北郡的狗头人"}},{q="收到信后，托德林·刃茎提供什么？",a="在与他见面后，托德林提供持续的训练和指导，敦促冒险者熟悉地形，并协助当地民众解决王国面临的种种麻烦。",al={"托德林提供什么","托德林训练","见到托德林后会发生什么"}}},fp="18,193,23.303.0,26.296.0,27.177.0,20.140.0,37.153.0,42.232.0,48.187.0,61.156.0"}
P.entries["quest:92481"] = {n="A Student of the Arcane",s="“A Student of the Arcane”是泽风岛上针对新手施法者的入门试炼与召唤任务。在新人证明了其基础实力后，由Rorian the Dayseeker发起，引导初出茅庐的法师查看闪光回溯水晶，并向当地导师Dorii Brightwhisper汇报。",h="“A Student of the Arcane”是泽风岛上针对新手施法者的入门试炼与召唤任务。在新人证明了其基础实力后，由Rorian the...",kw={"多莉·明语","闪光回溯水晶","法师任务","寻日者罗里安","奥术学徒","森达尔林地","沃尔德伦","泽风岛"},ang={["class:Mage"]="这项任务标志着法师在Dorii Brightwhisper指导下正式学徒生涯的开端，将你的魔法旅程定位为努力恢复长期失落的云端奥术秘密的过程。",["race:Skyborne"]="Dorii强调，数千年的云端与世隔绝导致奥术传统衰微，这使得年轻学徒成为振兴文化遗产的关键。"},sec={{t="水晶中的讯息",b="在协助处理了盘踞在森达尔林地附近的麻烦的vuldren之后，初级法师会被托付一件奇特的文物：闪光回溯水晶。这件水晶由该岛的驻地奥术导师Dorii Brightwhisper留下，它作为一个经过魔法录制的讯息，旨在测试学徒的能力并欢迎他们进行更深层次的神秘研究。"},{t="重新发现奥术",b="根据Dorii Brightwhisper的说法，他们的族人在云端高处隐居了数千年，在此期间，奥术的造诣已逐渐衰退。Dorii不仅将每一位新晋修行者视为学生，更视其为旨在寻回失落知识并恢复族人曾经强大的魔法传承的重要先驱。"}},faq={{q="什么是闪光回溯水晶？",a="闪光回溯水晶是一件由多莉·明语托付给逐日者罗瑞安的小型奥术焦点。它承载着一段刻写好的讯息，旨在向年轻的学徒介绍奥术交流的基础知识。",al={"回溯水晶","水晶讯息","水晶有什么用"}},{q="多莉·明语是谁？",a="多莉·明语是位于泽风岛森达尔林地中逐日者罗瑞安身后建筑物内的驻地法师训练师。多莉负责指导那些寻求重拾族人古老奥术传统的年轻法师。",al={"谁是多莉","泽风岛法师训练师","多莉位置"}},{q="为什么奥术魔法在泽风岛的人民中逐渐衰落？",a="正如多莉所解释的那样，在他们族人于云端隐居的数千年里，奥术技艺逐渐走向衰落。因此，像多莉这样的导师迫切地想要训练新的新手，去寻找并恢复那些失落的东西。",al={"为什么魔法会衰退","云端奥术知识","失落的奥术魔法"}},{q="谁发布了这个任务？",a="一旦有志向的法师完成了前置任务“平衡中的和谐”，逐日者罗瑞安便会在泽风岛的森达尔林地提供该任务。",al={"任务发布者","谁开启奥术学徒","罗里安任务"}},{q="我在哪里可以找到多莉·明语？",a="多莉·明语居住在森达尔林地内，位于逐日者罗瑞安正后方的建筑物中。",al={"多莉·明语位置","法师训练师在哪里","寻找多莉"}},{q="在开始此任务前必须完成什么前提条件？",a="你必须首先完成“平衡中的和谐”，其中包括为逐日者罗瑞安处理当地的沃尔德伦问题。",al={"前置条件","前提条件","之前的任务是什么"}}},fx={["1ed09f17"]={q="逐日者罗里安为什么派你去找多莉？",a="罗里安只是在转交一则急需送达给你的消息。你处理附近的沃尔德伦威胁时，多莉·明语特意留下了一块刻有你名字的回溯水晶。罗里安确保你收到水晶，并直接指引你去林地的法师训练师那里，好让你的奥术潜能不被埋没。",al={"罗里安为什么派你去","逐日者罗里安的动机","为什么要找多莉·明语谈话"}},ab250928={q="多莉·明语为什么特别想训练你？",a="你的族人在云端隐居数千年间，奥术技艺日渐衰微。多莉·明语看到你已证明自己能够应对当地威胁，认为你具备帮助族人重拾失落传承的潜力。她希望找到有志成为法师的人，主动探索并掌握奥术，而不是任由古老知识逐渐被遗忘。",al={"为什么要成为奥术学徒","为什么要训练我","多莉为什么想要我"}}},fp="23,217,20.301.0,24.270.0,35.210.0,27.215.0,55.213.0,21.118.0,37.101.0,63.111.0"}
P.entries["quest:92482"] = {n="The Way of the Hunter",s="The Way of the Hunter是为泽风岛上的森达尔林地的猎人新手准备的入门训练任务。在向当地的vuldren威胁证明了自己的实力后，年轻的追踪者会被Rorian the Dayseeker指引去向Tai'ree Farsight报到，开始正式的教导。",h="The Way of the Hunter是为泽风岛上的森达尔林地的猎人新手准备的入门训练任务。在向当地的vuldren威胁证明了自己的实力后，年轻的追踪者会被Rorian the...",kw={"猎人训练师","寻日者罗里安","潦草的便笺","泰莉·远视","猎人之道","森达尔林地","沃尔德伦","泽弗拉斯"},ang={["class:Hunter"]="此任务是泽风岛猎人新手的必要成年礼，正式确立了他们在Tai'ree Farsight指导下的训练。"},sec={{t="狩猎的召唤",b="在从清理森达尔林地外围骚扰不断的vuldren回来后，年轻的猎手们发现他们的实战技巧已经引起了当地人的注意。Rorian the Dayseeker转交了一张来自Tai'ree Farsight的潦草的便笺，她是该林地的驻地猎人训练师。对于那些准备踏入泽风岛广阔荒野的新手游侠来说，这标志着从简单的岛屿防御向真正的武艺与生存指导的转变。"},{t="Tai'ree的教导",b="Tai'ree Farsight位于村庄中心附近，她以严厉且务实的态度欢迎有前途的学生。她强调在原始自然中生存需要敏锐的感官和闪电般的反应能力，并根据她多年的经验提供指导。她的教导为任何希望磨练箭术和生存技能的岛屿追踪者奠定了基础。"}},faq={{q="谁提供此任务？",a="在完成任务“平衡中的和谐”并协助他处理了当地的沃尔德伦入侵后，逐日者罗瑞安会在泽风岛的森达尔林地提供此任务。",al={"谁给予猎人之道","任务起始","罗里安任务"}},{q="泰莉·远视是谁？",a="泰莉·远视是森达尔林地的驻地猎人训练师，驻扎在村庄中心附近。她负责监督有抱负的神射手和岛屿追踪者的训练与纪律。",al={"泰瑞在哪里","森达尔林地猎人训练师","泰瑞·远视位置"}},{q="潦草的便笺有什么用？",a="潦草的便笺是你在处理沃尔德伦时泰莉·远视留下的信息。它指示你直接在村广场找到她，开始高级训练。",al={"潦草的便笺","便笺内容","猎人便笺"}},{q="此任务在哪里进行？",a="此任务完全在森达尔林地进行，这是一个位于泽风岛的前哨定居点。",al={"任务区域","猎人任务地点","森达尔林地在哪里"}},{q="此任务需要完成什么前置条件？",a="你必须首先为逐日者罗瑞安完成“平衡中的和谐”，通过处理林地附近具有攻击性的沃尔德伦来证明你的初步能力。",al={"猎人之道前置任务","如何解锁","上一个任务"}},{q="泰莉·远视教导新猎人什么？",a="泰莉·远视担任你的职业训练师。与她交谈将介绍岛屿追踪的核心理念，并解锁基础猎人技能和战斗技巧。",al={"泰瑞做什么","为什么要和泰瑞交谈"}}},fx={bb563a7d={q="逐日者罗里安为什么派你去找泰莉·远视？",a="你外出处理沃尔德伦威胁时，村里的猎人训练师泰莉·远视特意留下字条，说想和你谈谈。罗里安只是在转达消息，并指引你前往她在森达尔林地的等候之处，让你开始磨炼武技。",al={"罗瑞安为什么派你去","罗瑞安让你走猎人之道的动机","为什么要拜访泰瑞·远视"}}},fp="21,173,21.403.0,23.307.0,21.153.0,24.164.0,42.181.0,33.86.0,54.184.0,45.185.0"}
P.entries["quest:92483"] = {n="At Home in the Shadows",s="\"At Home in the Shadows\" 是泽风岛的一项盗贼入门任务。在森达尔林地帮助 Rorian the Dayseeker 后，初出茅庐的盗贼会被指引去阅读一份传唤，并会见当地的职业导师 Akeri Duskblade。该任务标志着年轻的盗贼们从处理村庄琐事转向严肃的潜行与战斗训练的时刻。",h="\"At Home in the Shadows\" 是泽风岛的一项盗贼入门任务。在森达尔林地帮助 Rorian the Dayseeker 后，初出茅庐的盗贼会被指引去阅读一份传唤，并会见当地的职业导师 Akeri...",kw={"阿凯莉·暮刃","如归暗影","盗贼任务","盗贼训练师","寻日者罗里安","简单字条","森达尔林地","泽风岛"},ang={["class:Rogue"]="这项任务确立了你在泽风岛的正式盗贼训练，并将你引向森达尔林地瞭望塔中的 Akeri Duskblade。"},sec={{t="一封可疑的邀请函",b="在森达尔林地处理基本威胁时，年轻的盗贼引起了该林地常驻盗贼训练师 Akeri Duskblade 的注意。Akeri 并没有在定居点公开露面，而是通过 Rorian the Dayseeker 递交了一张简单的字条。Rorian 意识到，尽管 Akeri 行事可疑，但这位导师确实掌握着在林地庇护范围之外生存所需的实用技能。"},{t="瞭望塔中的课程",b="躲在村庄瞭望塔里的 Akeri Duskblade 说话从不拐弯抹角。他会在新人抵达时立即评估其步伐和感知能力，并警告说在森达尔林地外步法草率只会让人早早送命。通过 Akeri 的审查，盗贼迈出了在泽风岛掌握潜行、精准度和生存能力的第一步。"}},faq={{q="谁发放 \"暗影中的归宿\" 任务？",a="在完成 \"平衡中的和谐\" 之后，罗里安·寻日者 会在泽风岛的森达尔林地提供该任务。",al={"谁开启 暗影如家","暗影如家 任务发布者","罗瑞安 任务"}},{q="我在哪里可以找到 阿凯里·暮刃？",a="阿凯里·暮刃 位于泽风岛森达尔林地的村庄瞭望塔内。",al={"阿凯莉·暮刃 位置","阿凯莉·暮刃 在哪里","寻找 阿凯莉"}},{q="任务中给出的简单字条是什么？",a="简易便笺是 阿凯里·暮刃 留下的一条消息，请求与有前途的盗贼会面。你必须在与 阿凯里 交谈前阅读它，才能完成你的目标。",al={"泽风岛简单字条","字条是什么","阅读简单字条"}},{q="所有职业都可以接这个任务吗？",a="不，这个任务专为在森达尔林地学习技艺的盗贼设计。",al={"非盗贼可以做这个任务吗","暗影如家 是盗贼专属吗","职业要求"}},{q="阿凯里·暮刃 教什么？",a="阿凯里·暮刃 是森达尔林地的当地盗贼训练师，为开始在泽风岛踏上旅程的新手提供潜行、狡诈和刃术方面的指导。",al={"阿凯莉·暮刃 的职责","阿凯莉 是谁","森达尔林地盗贼训练师"}},{q="必须先完成什么前置任务？",a="你必须先为 罗里安·寻日者 完成 \"平衡中的和谐\"，他才会将 阿凯里 的字条交给你。",al={"暗影如家 前置要求","上一个任务","解锁 暗影如家"}}},fx={["776f9cb3"]={q="逐日者罗里安为什么派你去找阿克莉·暮刃？",a="你处理当地沃尔德伦威胁，证明了自己的能力之后，罗里安只是在转达一份召唤。林地里的潜行者训练师阿克莉·暮刃特意留下字条，想见你。罗里安知道初出茅庐的潜行者需要由适合这门技艺的人悉心教导，还打趣说你和这位行事隐秘的暮刃大概会相处得来。",al={"罗瑞安的动机","为什么派我去找阿凯莉","为什么要和阿凯莉·暮刃谈话"}},["4629917d"]={q="罗里安为什么不亲自处理阿克莉的事，而要你去？",a="阿克莉·暮刃点名要见你，而不是罗里安或林地的守卫。你选择了潜行者之道，而阿克莉正是负责训练暗影行者的本地导师。这次召见是为了考验你的警觉，磨炼你的直觉，并让你做好准备，在离开森达尔林地的庇护后也能生存下去。",al={"为什么要找我，阿凯莉·暮刃","阿凯莉为什么想见我","潜行者训练师为什么找我"}}},fp="22,157,18.326.0,25.286.0,43.118.0,33.85.0,47.101.0,39.69.0,32.135.0,48.91.0"}
P.entries["quest:92484"] = {n="Embracing the Elements",s="“Embracing the Elements”是森达尔林地（位于泽风岛）的一项萨满入门任务。该任务由Rorian the Dayseeker发起，引导年轻的修行者前往当地的萨满训练师Windshaper Boro处。任务向玩家介绍了当地居民与风之元素之灵之间沉默的裂痕。",h="“Embracing the Elements”是森达尔林地（位于泽风岛）的一项萨满入门任务。该任务由Rorian the Dayseeker发起，引导年轻的修行者前往当地的萨满训练师Windshaper...",kw={"拥抱元素","嗡鸣回溯水晶","寻日者罗里安","萨满","四风之灵","森达尔林地","塑风者波罗","泽风岛"},ang={["class:Shaman"]="这项任务代表了修行者与Windshaper Boro的首次正式接触，概述了元素之风的悲剧性沉默，以及为恢复交流而进行的终身追求。",["faction:Horde"]="对于前往泽风岛的部落旅行者来说，该任务介绍了岛上元素呼唤者与大陆传统的大地与灵魂传统相比所面临的独特挑战。"},sec={{t="元素的召唤",b="在帮助解决了村庄周围的vuldren虫害问题后，满怀抱负的萨满学徒会受到Rorian the Dayseeker的接见。在他们外出期间，Windshaper Boro留下了一块嗡鸣回溯水晶，象征着在林地中心开始正式元素教导的时机已经成熟。"},{t="沉默之风",b="见到Windshaper Boro后，他解释了当地萨满教义面临的困境。四风之灵在多年前突然断绝了沟通，抛弃了此前的交流。泽风岛的萨满们现在致力于对自然世界的深入研究，通过刻苦的训练努力填补这片寂静，并再次诱导元素之灵与他们对话。"}},faq={{q="谁发布了“拥抱元素”任务？",a="该任务由位于泽风岛森达尔林地的罗里安·寻日者发布，前提是你刚刚帮助解决了当地的沃德伦问题。",al={"拥抱元素 任务发布者","谁开启 拥抱元素"}},{q="塑风者波罗在哪里？",a="塑风者波罗位于泽风岛森达尔林地的中心附近，担任该定居点的常驻萨满训练师。",al={"塑风者博罗 位置","博罗 在哪里","寻找 塑风者博罗"}},{q="为什么这里的元素之灵不再与人们交流了？",a="根据塑风者波罗的说法，元素之灵在多年前突然终止了所有对话并离开了人们。当地的萨满并不完全理解这种断绝发生的原因，但他们仍在继续研究，希望能恢复那段失去的联系。",al={"为什么风是沉默的","四风之灵沉默","风之灵发生了什么"}},{q="什么是嗡鸣回溯水晶？",a="嗡鸣回溯水晶是塑风者波罗在你外出帮助定居点时留下的一件物品。检查它标志着你已准备好在波罗的指导下开始元素训练。",al={"嗡鸣回溯水晶","泽风岛 回溯水晶"}},{q="“拥抱元素”的前置任务是什么？",a="它紧随“平衡中的和谐”任务之后，在该任务中你需要处理周围地区肆虐的沃德伦。",al={"拥抱元素 前置任务","拥抱元素 之前有什么任务"}},{q="塑风者波罗在森达尔林地扮演什么角色？",a="塑风者波罗是该社区的萨满训练师，指导新入行的修行者进行元素沟通以及对自然世界的研究。",al={"博罗 是做什么的","塑风者博罗 职责"}}},fx={["52185878"]={q="逐日者罗里安为什么派你去找塑风者波罗？",a="你外出处理林地的沃尔德伦麻烦时，塑风者波罗特意留下一块回溯水晶，交由罗里安保管并转交给你。罗里安只是在转交水晶，并指引你去村中心附近找波罗，让你开始学习如何踏上元素之道。",al={"罗瑞安为什么要我去办这件事","罗瑞安的博罗任务为什么","为什么要查看嗡鸣回溯水晶"}}},fp="22,190,25.245.0,16.285.0,43.113.0,33.100.0,63.180.0,35.179.0,56.90.0,53.126.0"}
P.entries["quest:92485"] = {n="A Student of Nature",s="“A Student of Nature”标志着一位初出茅庐的德鲁伊在泽风岛(Zephras Isle)开始正式训练。在帮助恢复当地的和谐之后，新手德鲁伊们会受到赛托恩·银风(Xyton Silverwind)的传唤，前往森达尔林地(Thendal Grove)的枝叶下。这是开启了解岛上动植物之间更深层平衡的门户。",h="“A Student of Nature”标志着一位初出茅庐的德鲁伊在泽风岛(Zephras Isle)开始正式训练。在帮助恢复当地的和谐之后，新手德鲁伊们会受到赛托恩·银风(Xyton...",kw={"德鲁伊","折叠的羊皮纸","rorian the dayseeker","森达尔林地","vuldren","xyton silverwind","泽风岛"},ang={["class:Druid"]="这次成年礼直接将你与赛托恩·银风联系在一起，开启了你对荒野、尖牙和枝叶艺术的终身训练。"},sec={{t="来自林地的召唤",b="在解决了由过度活跃的野生动物引起的地方动乱后，罗里安·寻日者(Rorian the Dayseeker)会将一份个人的召唤函交给年轻的初学者。这份由当地导师赛托恩·银风留下的折叠的羊皮纸，邀请有志成为德鲁伊的学员们站出来，投身于荒野更深奥的神秘领域。这标志着初学者的天赋已经引起了林地长者的注意。"},{t="织锦的守护者",b="在森达尔林地的大树底层见到赛托恩·银风，这让初学者找到了归属。银风将泽风岛上充满活力的动植物视为一幅错综复杂的生命织锦，这幅织锦需要不断的保护和警惕的平衡。踏上尖牙、利爪、羽翼和枝叶的道路需要长期的指导，而这次会面标志着这种终身管理的真正开始。"}},faq={{q="是谁把玩家派去见赛托恩·银风的？",a="在你帮助解决了林地周边的vuldren问题后，罗里安·寻日者会将那份折叠的羊皮纸交给你，指引你去找赛托恩·银风。",al={"谁给予a student of nature","任务发布者","rorian"}},{q="赛托恩·银风在哪里？",a="赛托恩·银风居住在森达尔林地大树的一楼，就在泽风岛罗里安·寻日者的身后。",al={"xyton silverwind位置","xyton在哪里","德鲁伊训练师位置"}},{q="这个任务的目的是什么？",a="这个任务向新手德鲁伊介绍了他们的职业训练师赛托恩·银风，他是他们在维持泽风岛自然平衡方面的主要导师和向导。",al={"为什么要做这个任务","任务目标","德鲁伊训练开始"}},{q="赛托恩·银风教导新手德鲁伊关于泽风岛的什么知识？",a="银风教导说，岛上的植物和动物生命构成了一种微妙、相互关联的织锦，需要通过尖牙、利爪、羽翼和枝叶的修行来进行积极的照料和平衡。",al={"xyton说了什么","zephras自然平衡","zephras德鲁伊角色"}},{q="在收到这次召唤之前必须完成什么先决条件？",a="学员必须首先为罗里安·寻日者完成“Harmony in Balance”，处理好那些不受管束的vuldren群体，然后才能收到银风的便条。",al={"前置任务","先前的任务","在student of nature之前"}},{q="折叠的羊皮纸里写了什么？",a="折叠的羊皮纸是赛托恩·银风留下的一张直接便条，指示这位有前途的年轻德鲁伊去大树的树冠下寻找他进行进一步的训练。",al={"折叠的羊皮纸便条","silverwind的便条","羊皮纸上有什么"}}},fx={caa97f7a={q="Rorian the Dayseeker为什么派你去找Xyton Silverwind？",a="你外出处理当地沃尔德伦威胁时，常驻的德鲁伊训练师Xyton Silverwind特意给你留了消息。Rorian充当中间人，确保有潜力的学徒得到恰当的指导，并敦促你听从Silverwind的教诲，以便精通德鲁伊技艺、守护自然平衡。",al={"rorian的动机","为什么派我去找silverwind","rorian为什么给你折叠的羊皮纸"}}},fp="19,323,24.408.0,22.428.0,41.149.0,34.139.0,34.175.0,66.196.0,66.153.0,46.175.0"}
P.entries["quest:92489"] = {n="Power Overwhelming",s="Power Overwhelming是暴风城的高阶法师安多玛斯发布的一项任务，旨在援助与世隔绝的肯瑞托。玩家被派遣至沦陷的达拉然城，平息一场因奥术能量失控而引发的危机，这场危机已显化为一个法力元素。",h="Power Overwhelming是暴风城的高阶法师安多玛斯发布的一项任务，旨在援助与世隔绝的肯瑞托。玩家被派遣至沦陷的达拉然城，平息一场因奥术能量失控而引发的危机，这场危机已显化为一个法力元素。",kw={"奥术能量","阿克蒙德","达拉然","高阶法师安多玛斯","肯瑞托","法力元素","势不可挡","暴风城"},ang={["class:Mage"]="法师们与肯瑞托有着天然的亲缘关系，他们能够认识到在达拉然肆虐的不稳定奥术现象所构成的严重威胁。",["faction:Alliance"]="肯瑞托是联盟的历史盟友，暴风城渴望在达拉然脆弱的重建阶段通过援助来巩固这些盟约。"},sec={{t="隐居的城市",b="在第三次战争期间，达拉然在恶魔领主阿克蒙德手中遭受了毁灭性的打击，此后肯瑞托便退居于此。曾经欢迎来自世界各地的学者和法师的达拉然，在幸存的法师们为了重建家园而在封闭的边界后辛勤工作时，变得愈发神秘、避世，且对外界深怀戒心。"},{t="失控的奥术力量",b="近期为恢复达拉然昔日荣光所做的重建工作遇到了严重阻碍。不稳定的奥术能量发生危险泄漏，并已失去控制，聚合成纯粹的法力生物。高阶法师安多玛斯担心达拉然会因内部动荡而陷落，或是放弃其与联盟的历史盟约，因此派遣暴风城的勇士前去平息法力元素，并提醒肯瑞托他们还有可靠的盟友。"}},faq={{q="什么是力量无穷任务？",a="力量无穷是暴风城的高阶巫师安多玛斯发布的一项任务，要求前往达拉然，通过击败一个狂暴的法力元素来援助正在重建中的肯瑞托。",al={"什么是压倒性的力量","压倒性的力量任务","达拉然法力元素任务"}},{q="谁发布了这个任务？",a="高阶法师安多玛斯，暴风城的一位著名法师，他将此任务提供给愿意前往达拉然援助肯瑞托的勇士。",al={"谁发布压倒性的力量","安多玛斯任务","如何开始压倒性的力量"}},{q="为什么达拉然会避世并对人怀有戒心？",a="达拉然在第三次战争期间被恶魔领主阿克蒙德摧毁。尽管肯瑞托正在努力重建家园，但这场灾难使幸存的法师们变得避世，并对外界心存戒备。",al={"为什么达拉然避世","达拉然发生了什么","为什么达拉然的法师们怀有戒心"}},{q="是什么引起了达拉然的混乱？",a="在城市重建过程中，肯瑞托开始难以抑制失控的奥术能量爆发，这些能量聚合成了充满敌意的法力元素。",al={"达拉然奥术爆发","为什么达拉然有法力元素","达拉然发生了什么"}},{q="什么是法力元素？",a="法力元素是纯粹、不受控制的奥术力量的显化。它的出现表明，威胁达拉然的潜在奥术紊乱远比最初报告中提到的更加严重。",al={"什么是法力元素","达拉然元素背景","纯粹法力生物"}},{q="为什么暴风城要向达拉然提供援助？",a="肯瑞托长期以来一直是联盟的重要盟友。高阶法师安多玛斯希望确保达拉然在脆弱时期不会陷入混乱，或脱离联盟。",al={"为什么暴风城帮助达拉然","为什么联盟关心达拉然"}}},fp="18,189,19.248.0,21.415.0,37.155.0,21.101.0,41.133.0,43.118.0,27.156.0,41.171.0"}
P.entries["quest:92514"] = {n="Welcome to Shen'dar Village",s="Welcome to Shen'dar Village 向旅行者介绍了申达尔村的关键人物和当地动态。抵达后，新来者会被指引去咨询当地的塑风者长者和村里的旅店老板，然后再协助处理诸如区域土匪之类的紧迫威胁。",h="Welcome to Shen'dar Village 向旅行者介绍了申达尔村的关键人物和当地动态。抵达后，新来者会被指引去咨询当地的塑风者长者和村里的旅店老板，然后再协助处理诸如区域土匪之类的紧迫威胁。",kw={"土匪","科莉艾拉·静风","高阶会","伊拉雅·琥珀之风","申达尔村","受灵性触动","欢迎来到申达尔村","塑风者"},ang={["class:Shaman"]="作为一名与灵魂和元素协调一致的人，你很快会注意到申达尔村里像 Illaya Amberwind 这样的受灵性触动塑风者周围那种微妙的静电空气。"},sec={{t="申达尔的初步探索",b="抵达申达尔村后，建议旅行者在承担当地任务之前先熟悉一下定居点的关键居民。展现出受灵性触动特质的新来者会被指引去村广场附近拜访长者 Illaya Amberwind，以及前往村里的旅店找 Coriella Calmbreeze 获取住宿和补给。这种问候确保了游客在拿起武器之前能够了解定居点微妙的社会动态。"},{t="阵营与边境困扰",b="在申达尔村平静的外表下，受灵性触动的塑风者与高阶会之间存在着政治摩擦。尽管这两个阵营之间的意识形态纠纷在整个地区都很激烈，但申达尔的居民们在处理分歧时保持克制。双方都认识到，琐碎的争吵必须让位于紧迫的生存问题，其中最重要的是威胁该地区的土匪危机。"}},faq={{q="欢迎来到申达尔村 任务的目的是什么？",a="欢迎来到申达尔村 是一个引导任务，旨在让新抵达者熟悉申达尔村社区的关键人物。在安排旅行者处理诸如土匪困扰之类的当地问题之前，当地领导层会指引他们去见当地的塑风者长者和村里的旅店老板。",al={"申达尔村任务说明","欢迎来到申达尔村 任务概述","申达尔村活动指南"}},{q="伊拉娅·琥珀之风 是谁？",a="伊拉娅·琥珀之风 是申达尔村的塑风者长者。她位于城镇中心附近，在广泛的政治摩擦中，为那些拥有受灵性触动感知能力的人提供指导。",al={"伊拉雅·琥珀之风 是谁","伊拉雅·琥珀之风 位置","申达尔塑风者长者"}},{q="科瑞莉娅·静风 是谁？",a="科瑞莉娅·静风 经营着申达尔村内的当地旅店。她为旅行者、冒险者和当地居民提供必要的住宿、休息和补给。",al={"科莉艾拉·静风 是谁","申达尔村旅店老板","申达尔村旅店在哪里"}},{q="塑风者是谁？",a="塑风者是受灵性触动的修行者，其特征是周围空气中有着明显的静电荷。虽然塑风者与高阶会之间的紧张局势不断加剧，但面对更大的威胁，两个阵营在申达尔村内仍保持着文明的共存。",al={"什么是塑风者","受灵性触动塑风者背景","高阶会与塑风者"}},{q="高阶会与塑风者之间的紧张关系是什么？",a="高阶会是一个目前正与塑风者经历政治摩擦的当地势力或阵营。尽管存在意识形态上的纠纷，但申达尔村的代表和居民们保持着和平关系，以应对更紧迫的共同关切。",al={"什么是高阶会","申达尔村冲突","高阶会与塑风者紧张关系"}},{q="申达尔村目前面临什么问题？",a="除了塑风者和高阶会之间令人不安的哲学纠纷外，该定居点还面临着来自周边地区活动的当地土匪的直接、实际的危险。",al={"申达尔村麻烦","申达尔村面临什么威胁","申达尔村土匪"}}},fp="27,136,23.361.0,29.291.0,61.234.0,24.155.0,27.112.0,24.221.0,63.168.0,51.146.0"}
P.entries["quest:92515"] = {n="The Problem With Prideclaws",s="“The Problem With Prideclaws”旨在解决申达尔高地日益严重的骄爪兽威胁。由于当地定居点已经在应付土匪和邪教徒，捕杀这些入侵的野兽既保护了脆弱的村民，又能为社区提供有用的毛皮。",h="“The Problem With Prideclaws”旨在解决申达尔高地日益严重的骄爪兽威胁。由于当地定居点已经在应付土匪和邪教徒，捕杀这些入侵的野兽既保护了脆弱的村民，又能为社区提供有用的毛皮。",kw={"扑杀","骄爪兽毛皮","骄爪兽","申达尔","申达尔高地","傲爪的麻烦","村庄边界"},ang={["class:Hunter"]="追踪并扑杀入侵定居点的掠食性野兽是老练猎人的基本功，尽管面对如此数量的骄爪兽仍需保持敬畏。"},sec={{t="日益严重的野生威胁",b="环绕申达尔高地的山丘充满了危险，不仅有流窜的土匪和疯狂的邪教徒，还有不断入侵的骄爪兽群。这些凶猛的野兽开始向村庄周边渗透，随着领地扩张，它们变得越来越大胆，对当地居民构成了迫在眉睫的威胁。"},{t="守卫边界",b="为了在宠物或儿童被这些游荡的掠食者叼走之前避免灾难，村民们组织了一次扑杀行动。猎杀骄爪兽有双重目的：既能将掠食者驱逐出定居点边界，又能提供坚韧的毛皮，供工匠制作村庄必需的物品。"}},faq={{q="什么是骄爪兽？",a="骄爪兽是栖息在申达尔山丘和高地上的掠食性野兽。它们以性情凶猛和毛皮珍贵而闻名，当种群数量失控时，会对附近的定居点构成日益严重的威胁。",al={"什么是骄爪兽","骄爪兽背景","骄爪兽"}},{q="骄爪兽出没在哪里？",a="骄爪兽游荡在申达尔高地的山丘中。它们不断增长的种群已经开始侵扰当地村庄的边界，使它们离居住区危险地近了。",al={"这个任务在哪里","骄爪兽栖息地","骄爪兽位置"}},{q="为什么村庄需要扑杀骄爪兽？",a="由于土匪和疯狂的邪教徒已经在威胁该地区，骄爪兽的过度繁殖进一步威胁到了村庄的边界。此次扑杀旨在作为一种预防措施，防止儿童或家畜成为这些入侵掠食者的牺牲品。",al={"为什么要杀骄爪兽","为什么要扑杀骄爪兽","村庄危险"}},{q="骄爪兽的毛皮有什么用？",a="收集到的毛皮会被村里的工匠重新加工成实用的商品和补给品，将必要的扑杀转化为定居点的有用资源。",al={"毛皮会怎样","骄爪兽毛皮用途","毛皮目的"}},{q="还有什么威胁困扰着周边的山丘？",a="除了在山丘上徘徊的野生骄爪兽外，当地定居点还面临着流窜的土匪和不稳定的邪教徒的威胁，这使当地的安全和防御捉襟见肘。",al={"申达尔的其他威胁","还有什么威胁村庄","当地威胁"}},{q="当地人如何看待骄爪兽？",a="负责这项任务的村民在武装守卫的保护下，觉得骄爪兽还有点可爱，但也认识到在悲剧发生前维护村庄安全的严酷必要性。",al={"谁发布了傲爪之患","任务发布者想法"}}},fp="27,188,21.276.0,20.237.0,20.157.0,33.131.0,48.159.0,43.74.0,48.109.0,38.162.0"}
P.entries["quest:92516"] = {n="Hippogryph Harassment",s="Hippogryph Harassment是一项当地任务，要对付在申达尔村东南方筑巢的一群凶猛的野生角鹰兽。途经附近道路的旅人频繁遭到这些栖息在申达尔高地、领地意识极强的野兽袭击。为确保道路畅通，冒险者受命削减这群角鹰兽中的幼兽和护卫，并除掉统领它们的族母。",h="Hippogryph...",kw={"角鹰兽","角鹰兽的骚扰","角鹰兽族母","角鹰兽护卫","角鹰兽幼兽","卡利姆多","族母","申达尔高地","申达尔村"},ang={["class:Druid"]="德鲁伊致力于维持与荒野的和谐，在他们看来，这场猎杀并非出于恶意，而是在野兽开始捕食旅人之后，为恢复平衡而不得不采取的无奈之举。",["class:Hunter"]="猎人了解飞行野兽的捕食本能，也熟悉野生兽群的等级秩序，因此明白，除掉族母是瓦解兽群攻势最有效的办法。",["race:NightElf"]="暗夜精灵将角鹰兽视为Elune的神圣伙伴，对它们怀有深切的精神敬意，因此，当荒野与旅人的安全发生冲突时，即使猎杀的是凶猛的野生兽群，也是一项沉重的任务。"},sec={{t="道路上的危机",b="行走在申达尔村附近道路上的旅人，正面临日益严重的空中威胁。一群野生角鹰兽最近占据了村落东南方的崎岖地带，在申达尔高地开辟巢区，繁衍生息。在卡利姆多各地，角鹰兽素以高贵著称，有时还会与精灵骑手结下羁绊，但未经驯服的兽群会极其凶猛地捍卫自己的领地。任何行经下方道路的货车或独行旅人，都成了空中伏击的目标，重要通道因此受阻，若任由这些生物肆虐，村庄便可能陷入孤立。"},{t="削减兽群",b="要消除眼前的威胁，就必须直捣申达尔高地的角鹰兽巢区。要让高地道路恢复安宁，就得在幼兽成年之前将其消灭，遏制兽群的迅速扩张，同时突破守卫巢区外围的警觉的角鹰兽护卫。然而，真正的祸患来自兽群的族母，正是她指挥着对过往旅人的袭击。唯有进攻巢穴并击杀族母，才能让旅人再次安全通行。"}},faq={{q="角鹰兽为什么袭击申达尔村附近的旅人？",a="这些角鹰兽最近在申达尔村东南方的申达尔高地建立了巢区，繁衍生息。由于兽群就栖息在主要道路旁边，这些领地意识极强的生物会凶猛地袭扰任何靠近者，保护新近占据的繁殖地和猎场。",al={"角鹰兽为何袭击","角鹰兽为何敌对","角鹰兽的骚扰起因"}},{q="这群角鹰兽在哪里？",a="这群角鹰兽在申达尔村东南方的申达尔高地筑巢。它们的栖息地和领地内的猎场俯瞰着穿过这片地区的道路，幼兽、护卫和兽群的族母聚集在悬崖与山脊之间。",al={"角鹰兽在哪里","角鹰兽位置","申达尔高地位置"}},{q="完成任务需要击杀哪些角鹰兽？",a="要平息兽群的攻击行为，让道路恢复安全，冒险者必须在申达尔高地击杀八只角鹰兽幼兽、六只强壮的角鹰兽护卫，以及统领巢区的强大角鹰兽族母。",al={"需要击杀哪些角鹰兽","角鹰兽的骚扰目标","角鹰兽任务目标"}},{q="谁是这群角鹰兽的首领？",a="这群角鹰兽由一只栖居在申达尔高地的强大角鹰兽族母统领。她掌管巢区，负责守卫申达尔村东南方的筑巢地，因此，只有除掉她，才能打破兽群对道路的控制。",al={"谁统领角鹰兽","角鹰兽族母","角鹰兽首领"}},{q="为什么必须削减角鹰兽幼兽的数量？",a="角鹰兽幼兽意味着这群新近定居的角鹰兽将继续成长、扩张。冒险者同时削减幼兽和成年护卫的数量，就能确保巢区无法迅速恢复实力，也无法长期以恐怖笼罩当地道路。",al={"为何击杀角鹰兽幼兽","为何以角鹰兽幼兽为目标","削减角鹰兽幼兽"}},{q="这些角鹰兽经过驯服，或与谁结盟了吗？",a="没有，它们是完全未经驯服的野生生物，自行在申达尔高地建立了栖息地。暗夜精灵精心养育的坐骑训练有素，而这群野生角鹰兽会将任何途经的人形生物视为侵入领地的闯入者或猎物。",al={"角鹰兽是否经过驯服","这些是否是暗夜精灵的角鹰兽","友善的角鹰兽"}},{q="这些角鹰兽给当地村落带来了什么危险？",a="兽群的巢穴紧邻申达尔村通往东南方的道路，从高处俯瞰着路面。这些凶猛的野兽俯冲而下，袭扰补给车、信使和往来旅人，威胁着陆路通行的安全，可能使村庄与周边地区隔绝。",al={"角鹰兽构成什么威胁","申达尔村面临的危险","角鹰兽为何成为祸患"}}},fp="21,267,17.465.0,17.357.0,66.235.0,38.181.0,53.165.0,42.231.0,41.232.0,49.257.0,62.250.0"}
P.entries["quest:92517"] = {n="The Criminal Element",s="The Criminal Element 涉及打击 Highlands Bandits 及其首领 \"Badwind\" Bennic，他们盘踞在申达尔高地一处瀑布后方隐蔽的洞穴中。由于当地势力因近期出现的一个威胁性邪教而疲于奔命，因此需要外部力量来除掉 Bennic 并瓦解这个强盗团伙。",h="The Criminal Element 涉及打击 Highlands Bandits 及其首领 \"Badwind\"...",kw={"恶风本尼克","本尼克","邪教","高地强盗","申达尔高地","犯罪分子","瀑布洞穴"},ang={["class:Rogue"]="在隐蔽的瀑布洞穴中活动是强盗的典型行径，但 \"Badwind\" Bennic 和他的手下缺乏足够的技巧和谨慎，无法避免招致当地的报复。"},sec={{t="瀑布后的法外狂徒",b="在申达尔高地，一群被称为 Highlands Bandits 的亡命之徒在北部瀑布后方的一个隐蔽洞穴中安营扎寨。在臭名昭著的 \"Badwind\" Bennic 的领导下，这群恶棍在神秘邪教抵达高地之前就已经是当地人挥之不去的梦魇，而邪教到来后，他们的无法无天更是变本加厉，演变成了彻底的恐怖威胁。由于当地防卫力量捉襟见肘，无法抽调人手，探险者们受命潜入这座瀑布堡垒，击溃该团伙并除掉 Bennic。"},{t="阴影中的变动",b="虽然除掉 \"Badwind\" Bennic 成功瓦解了强盗巢穴并带来了暂时的缓解，但这引出了一个新的战略难题。当地当局担心，失去首领后，幸存的强盗会去寻求附近邪教的庇护。将这些走投无路的亡命之徒吸纳进邪教，可能会使这个已经令人担忧的区域威胁进一步壮大。"}},faq={{q="谁是 \"恶风\" 本尼克？",a="\"恶风\" 本尼克 是 高地强盗 的首领，他们在申达尔高地一处瀑布后的隐蔽洞穴中进行活动。他的团伙长期困扰着该地区，在近期区域动荡中更是变得愈发猖獗。",al={"谁是 恶风本尼克","本尼克","恶风"}},{q="高地强盗 藏在哪里？",a="强盗们在申达尔高地北部的一处瀑布后方隐藏着他们的巢穴。",al={"强盗在哪里","强盗洞穴位置","瀑布洞穴"}},{q="该地区提到的邪教是什么？",a="该邪教是一个较新的、令人担忧的派系，其追随者聚集在南部的 法拉斯村，且人数在不断增加。虽然强盗在该邪教到来之前就已经在此活动，但邪教的出现加剧了当地的危险。人们一直担心，一旦强盗的首领被除掉，幸存的强盗可能会寻求避难并壮大邪教的势力。",al={"什么邪教","邪教关联","邪教是什么"}},{q="为什么当地势力无法自行处理强盗？",a="当地势力在应对新出现的邪教时，缺乏足够的人手来自行清理强盗。除掉 本尼克 并驱散他的团伙可以消除一个正在掠夺该地区的直接威胁。",al={"为什么要杀死强盗","强盗问题"}},{q="本尼克 被击败后，强盗们会怎样？",a="尽管 本尼克 倒下了，他的巢穴也被摧毁，但人们依然担心幸存的强盗会向附近的邪教寻求保护，从而增加邪教徒那本已令人担忧的人数。",al={"幸存的强盗会怎样","所有强盗都死了吗"}},{q="这场冲突发生在哪里？",a="申达尔高地是 高地强盗 漫游并维护其隐蔽瀑布堡垒的崎岖地区。",al={"申达尔高地在哪里","申达尔高地"}}},fp="20,221,24.398.0,22.278.1,24.206.0,39.95.0,39.323.0,53.187.0,53.159.0,36.100.0"}
P.entries["quest:92519"] = {n="Ward Restocking",s="Ward Restocking是阿拉希高地的一项任务，旅行者们可以在此协助落锤镇的格里高利·维克托医生。由于哨所的医务室急需关键的药剂，信使们被派遣前往格沙克农场的药剂师乔瑞尔的实验室取回被遗忘的物资。",h="Ward Restocking是阿拉希高地的一项任务，旅行者们可以在此协助落锤镇的格里高利·维克托医生。由于哨所的医务室急需关键的药剂，信使们被派遣前往格沙克农场的药剂师乔瑞尔的实验室取回被遗忘的物资。",kw={"药剂师乔瑞尔","阿拉希高地","格里高利·维克托医生","格沙克农场","落锤镇","包装好的补剂","补充结界"},ang={["faction:Horde"]="落锤镇哨所依靠稳定的补剂和药物供应，以维持其士兵、防御者和旅行者在阿拉希高地抵御威胁的能力。",["race:Undead"]="药剂师乔瑞尔代表着皇家药剂师学会在阿拉希的偏远存在，尽管他在格沙克农场的怪异行为和有毒实验甚至让他的盟友感到沮丧。"},sec={{t="医务室物资短缺",b="在阿拉希高地的部落定居点落锤镇，格里高利·维克托医生负责照看哨所医务室里的伤员和病人。维持医务室的正常运作需要定期供应药物、解毒剂和药剂，这些通常由驻扎在附近的被遗忘者药剂师提供。当这些补给中断时，维克托必须征募有能力的旅行者来顶替，以确保诊所的库存充足。"},{t="格沙克农场的隐士",b="药剂师乔瑞尔在落锤镇西南方的格沙克农场的一间狭窄且通风不良的棚屋里进行他的炼金实验。据格里高利·维克托医生说，药剂师乔瑞尔的失踪并不罕见；这位古怪的被遗忘者化学家因无视职责或意外死于自己调制的有毒混合物而臭名昭著。被派去取回包装好的补剂的信使们，无论药剂师乔瑞尔是否在场，都应该能找到所需的药物。"}},faq={{q="谁提供了补充结界这个任务？",a="落锤镇负责管理创伤病房和医务室的创伤外科医生格里高利·维克托医生将这项任务交给可靠的旅行者。当常规渠道中断时，他需要可靠的信使来取回医疗物资。",al={"谁发布病房补给任务","病房补给任务发布者","格里高利·维克托医生任务"}},{q="药剂师乔瑞尔在哪里？",a="药剂师乔瑞尔在格沙克农场的一间小屋里工作，那里位于阿拉希高地，落锤镇的西南方，路边不远处。",al={"药剂师乔瑞尔的位置","药剂师乔瑞尔的实验室位置","到哪里寻找补剂"}},{q="格里高利·维克托医生为什么派你去格沙克农场？",a="格里高利·维克托医生派遣旅行者前往格沙克农场，因为药剂师乔瑞尔没有将急需的解毒剂和药剂板条箱送到落锤镇医务室。",al={"为什么要前往格沙克农场","格沙克农场有什么"}},{q="医务室需要什么物资？",a="你必须收集一箱包装好的补剂，其中包含由药剂师乔瑞尔准备的解毒剂和药剂，以补充落锤镇医务室日益减少的库存。",al={"什么是包装好的补剂","需要拾取什么物品"}},{q="为什么药剂师乔瑞尔没有亲自运送物资？",a="格里高利·维克托医生怀疑药剂师乔瑞尔不是又在通风不良的工作棚里调制药剂时毒死了自己，就是直接忽视了他对医务室的义务。",al={"药剂师乔瑞尔发生了什么事","药剂师乔瑞尔死了吗","为什么药剂师乔瑞尔没有送货"}},{q="物资必须送到哪里？",a="从格沙克农场收集到补剂后，必须将这箱补剂带回落锤镇医务室交给格里高利·维克托医生。",al={"补剂要送到哪里","向谁交付病房补给任务"}}},fp="15,140,22.273.0,27.333.0,37.154.0,35.137.0,56.170.0,38.166.0,60.161.0,37.102.0"}
P.entries["quest:92528"] = {n="Among the Faithful",s="Among the Faithful讲述了一项针对驻扎在申达尔高地Falaath Village的奥拉基尔信徒的秘密调查。通过伪装成一名准新兵，冒险者得知邪教的高层正在秘密集结，准备对当地的定居点和哨所发动即将来临的攻势。",h="Among the Faithful讲述了一项针对驻扎在申达尔高地Falaath...",kw={"奥拉基尔","信徒之中","法拉斯村","洛尔苏娜","申达尔高地","天空祭司安德斯","西部瞭望塔","风领主"},ang={["class:Priest"]="虽然神圣牧师和暗影牧师遵循着熟悉的信仰，但Falaath Village的邪教徒是由致力于侍奉风领主奥拉基尔的Skypriests领导的，他们引导着风暴的原始力量。",["class:Shaman"]="对奥拉基尔的崇拜以及邪教对风暴能量的掌控，直接与萨满祭司所尊崇和沟通的元素力量产生了交集。"},sec={{t="渗透进Falaath Village",b="作为一名热切的新兵混入奥拉基尔信徒中，一名渗透者进入了申达尔高地的Falaath Village。邪教徒们公开庆祝他们日益壮大的队伍，吹嘘说他们的集体虔诚赋予了风暴本身以形态和愤怒。新来者通常会被直接送往Skypriest Aanders处接受审查，但当地旅店里的一场意外会面打乱了常规程序。"},{t="神秘访客",b="Aanders正在城镇北侧接待一位尊贵的客人，这让新兵可以在不受监视的情况下在营地中随意游荡。通过保持低调并窃听定居点领导层的谈话，侦察兵揭开了邪教当前野心的真正规模：在申达尔高地全境进行协调一致的军事推进。"},{t="Lorthuna的计划",b="旅店里的神秘客人原来就是整个邪教的最高指挥官Lorthuna本人。她的直接出现预示着一场旨在攻击申达尔村以及西部瞭望塔的激进打击。虽然村庄是一个明显的人口中心，但针对偏远瞭望塔的攻击让当地侦察兵感到困惑，这表明邪教在他们以风暴为驱动的攻势之下还隐藏着别的动机。"}},faq={{q="谁是奥拉基尔的信徒？",a="奥拉基尔的信徒是一个供奉风领主奥拉基尔的邪教组织。他们以申达尔高地的法拉斯村为基地，成员们驾驭着风暴魔法，并在名为洛尔苏娜的人物领导下行动。",al={"谁是奥拉基尔的信徒","这是什么邪教","奥拉基尔邪教"}},{q="谁是天空祭司安德斯？",a="天空祭司安德斯是法拉斯村邪教组织中的高级官员，负责评估和招募新兵。在渗透行动期间，他正忙于在村里的旅店接待一位重要客人。",al={"谁是天空祭司安德斯","安德斯","邪教评估人员"}},{q="谁是洛尔苏娜？",a="洛尔苏娜是整个奥拉基尔邪教的最高领袖。她直接而隐秘地出现在法拉斯村的旅店中，这表明邪教正在高地策划一场即将来临的高级别攻势。",al={"谁是洛尔苏娜","邪教领袖洛尔苏娜","旅店里的客人"}},{q="邪教为什么要攻击西部瞭望塔？",a="邪教正密谋同时对申达尔村和西部瞭望塔发动袭击。虽然攻击村庄在战略上讲得通，但针对瞭望塔这个小型哨所的行为对于高地的守卫者来说仍是一个令人费解的谜团。",al={"为什么要攻击瞭望塔","西部瞭望塔邪教","邪教目标"}},{q="这件事发生在什么地方？",a="法拉斯村是一个位于申达尔高地的定居点，目前作为奥拉基尔信徒及其新兵的主要基地和集结地。",al={"法拉斯村在哪里","法拉斯村位置"}},{q="邪教在申达尔高地有什么意图？",a="邪教试图扩大其影响力，并在申达尔高地释放风暴魔法。在洛尔苏娜的领导下，他们的直接目标是对申达尔村和西部瞭望塔发动攻击。",al={"邪教在申达尔高地的目标","邪教在申达尔的计划"}}},fp="18,227,28.348.0,16.267.1,17.364.2,32.176.0,25.204.0,16.188.0,49.208.0,27.137.0,57.197.0"}
P.entries["quest:92529"] = {n="Falaath Village",s="Falaath Village是忏悔的shen'dorei寻求赢回风领主奥拉基尔恩宠的聚集地。带有标记的新兵从申达尔村出发，前往向传教士贾萨恩报到，并加入他们的信徒同伴。",h="Falaath Village是忏悔的shen'dorei寻求赢回风领主奥拉基尔恩宠的聚集地。带有标记的新兵从申达尔村出发，前往向传教士贾萨恩报到，并加入他们的信徒同伴。",kw={"奥拉基尔","法拉斯村","阿基尔印记","传教士贾萨恩","萨尼娅·银溪","申达尔村","申多雷","风领主"},ang={["class:Shaman"]="虽然萨满寻求与元素之灵和谐共处，但忠于风领主的邪教徒通过忏悔和宗教奉献来接近奥拉基尔，以收回被抛弃的风。",["race:Skyborne"]="对于寻求恢复与风之联系的shen'dorei来说，加入Falaath Village的信徒行列代表了一种集体忏悔的行为，以重新获得奥拉基尔失去的恩宠。"},sec={{t="为风领主忏悔",b="在申达尔村，萨尼娅·银溪哀叹她的人民变得傲慢，视风的恩赐为理所当然，直到风之灵抛弃他们，让他们陷入停滞。为了弥补这一堕落，忏悔的新兵会被打上标记并被送往Falaath Village，与坚信只有忏悔行为才能恢复风之恩宠的shen'dorei同伴寻求共融。"},{t="Falaath的任务",b="当带着阿基尔印记抵达Falaath Village郊区时，入门者会受到传教士贾萨恩的迎接。贾萨恩将新侍僧的到来视为来自四风的祝福征兆，欢迎所有前来寻求沐浴在奥拉基尔元素恩典中的人。"}},faq={{q="任务法拉斯村是什么？",a="法拉斯村是一个介绍性任务，受萨尼娅·银溪标记的新兵从申达尔村出发，前往向传教士贾萨恩报到，寻求与风领主的忠诚信徒共融。",al={"法拉斯村任务是什么","法拉斯村概览","法拉斯村任务"}},{q="传教士贾萨恩是谁？",a="传教士贾萨恩是一位驻扎在法拉斯村入口附近的侍僧，他欢迎由萨尼娅·银溪姐妹派来的新兵，让他们沐浴在奥拉基尔的祝福中。",al={"传教士贾萨恩是谁","贾萨恩背景故事","法拉斯传教士"}},{q="萨尼娅·银溪是谁？",a="萨尼娅·银溪是申达尔村的一名信徒，她引导潜在的追随者前往法拉斯村，并为新兵赐予阿基尔印记。",al={"萨尼娅·银溪是谁","萨尼娅背景故事","萨尼娅姐妹"}},{q="为什么申多雷要崇拜奥拉基尔？",a="信徒们认为他们的人民变得自满和傲慢，视风的恩赐为理所当然，直到风之灵抛弃了他们。他们通过忏悔行为崇拜风领主奥拉基尔，以重新获得风的祝福。",al={"为什么要崇拜奥拉基尔","风领主奥拉基尔崇拜","谁是风领主"}},{q="阿基尔印记是什么？",a="阿基尔印记是萨尼娅·银溪在申达尔村赐予的标志，用于在入门者进入法拉斯村之前将其识别为信徒的新兵。",al={"阿基尔印记是什么","丢失的阿基尔印记","新兵印记"}},{q="任务中提到的申多雷是谁？",a="萨尼娅提到的申多雷是由于风之灵收回恩宠而与精神停滞作斗争的精灵，这促使一些人寻求通过元素奉献来赎罪。",al={"谁是申多雷","申多雷背景故事"}}},fp="15,158,27.338.0,22.204.0,34.143.0,25.150.0,26.139.0,43.190.0,25.162.0,46.157.0"}
P.entries["quest:92532"] = {n="The Warrior's Path",s="The Warrior's Path 是一项在泽风岛上为初出茅庐的战士提供的入门级战斗任务。根据 Rorian the Dayseeker 传达的指示，年轻的战士们会被指引去见森达尔村瞭望塔内的 Blademaster Ren。Ren 已做好准备，为那些准备好守护自己人民的人提供战斗指导和纪律训练。",h="The Warrior's Path 是一项在泽风岛上为初出茅庐的战士提供的入门级战斗任务。根据 Rorian the Dayseeker 传达的指示，年轻的战士们会被指引去见森达尔村瞭望塔内的 Blademaster...",kw={"剑圣雷恩","皱巴巴的便笺","寻日者罗里安","森达尔村","战士之路","瞭望塔","泽风岛"},ang={["class:Warrior"]="此任务代表了你在森达尔村武艺教育的正式开端，并向你引荐了你的导师 Blademaster Ren。"},sec={{t="瞭望塔的召唤",b="在附近恢复平衡后回到森达尔村的 Rorian the Dayseeker 处，满怀抱负的战士们会得到消息：村里的剑圣已经注意到了他们。Rorian 递给玩家一张由 Ren 亲手写下的皱巴巴的便笺，要求这位新手直接去寻找她。Ren 位于村庄内的瞭望塔高处，时刻观察着岛屿的边界以及那些终有一天会保卫这里的征募新兵。"},{t="守护的责任",b="到达瞭望塔后，战士们将接触到 Blademaster Ren 的战斗哲学。对 Ren 而言，武艺精通不仅仅是蛮力的锻炼，更是一种在日益动荡的世界中领导、忍受并保护人民的关键职责。她承诺在学徒磨练技能时给予指导，并通过严格的训练帮助他们变得足够强大，以面对威胁家园的巨大危险。"}},faq={{q="是谁指引我去找 剑圣蕾恩？",a="在你完成森达尔村的任务后，罗里安·逐日者 会指引你去找 剑圣蕾恩。在你离开期间，蕾恩 特意要求 罗里安 在你回来后将你送到她的瞭望塔。",al={"谁开启此任务","任务发布者","罗瑞安 的作用"}},{q="我可以在哪里找到 剑圣蕾恩？",a="剑圣蕾恩 位于泽风岛上森达尔村的瞭望塔内，她在那里监视着村庄并训练新晋的战斗人员。",al={"剑圣雷恩 在哪里","雷恩 的位置","森达尔 瞭望塔"}},{q="什么是“皱巴巴的便笺”？",a="“皱巴巴的便笺”是一封由 罗里安 代表 剑圣蕾恩 递交给你的个人召唤信，指示你阅读它并前往森达尔村瞭望塔接受正式的武艺训练。",al={"皱巴巴的便笺","便笺上写了什么","雷恩 的便笺"}},{q="剑圣蕾恩 教授年轻战士什么？",a="剑圣蕾恩 强调警惕、领导力和保护。她提醒受训者，随着世界变迁和危机加剧，战士们必须拥有立足于危险与人民之间的意志。",al={"雷恩 的教导","雷恩 训练什么","战士的目标"}},{q="在泽风岛接受战士训练需要完成这个任务吗？",a="这是你与森达尔村职业训练师的正式介绍，它直接将你引向 剑圣蕾恩，让你知道将来从哪里学习武艺技巧。",al={"我必须做这个任务吗","战士训练师介绍","是强制性的吗"}},{q="蕾恩 所说的“愿风指引你”是什么意思？",a="这一传统的祝福反映了泽风岛的岛屿文化，祝愿旅者在踏入陌生和危险的领地时能平安通途、保持专注并获得好运。",al={"愿风指引你的含义","风的引用","雷恩 的告别"}}},fx={["2d8c1194"]={q="逐日者罗里安为什么派我去找剑圣任？",a="你一回到森达尔村，剑圣任便亲自请求罗里安指引你前往瞭望塔。世界正风云变幻，前方还有险恶考验，任明白，年轻的战士需要专门的战斗训练和领导指引，族人才能在未来的危险中生存下来。罗里安只是应任之请，确保你得到所需的训练。",al={"罗瑞安为什么派我去","罗瑞安的动机","为什么要找剑圣雷恩"}}},fp="18,146,27.382.0,24.302.0,37.160.0,33.138.0,26.167.0,47.165.0,60.128.0,48.140.0"}
P.entries["quest:92544"] = {n="Al'Aketh Thugs",s="一伙凶暴的奥拉凯斯教徒占据了附近的神殿废墟，威胁着森达尔林地周边原本宁静的道路。这些狂热分子奉命从阿基尔神殿前来，骚扰过路旅人，强迫他们入教，对当地行人构成了迫在眉睫的威胁。Hanaa Nightwind 委托冒险者瓦解他们的控制，并杀死他们凶残的指挥官。",h="一伙凶暴的奥拉凯斯教徒占据了附近的神殿废墟，威胁着森达尔林地周边原本宁静的道路。这些狂热分子奉命从阿基尔神殿前来，骚扰过路旅人，强迫他们入教，对当地行人构成了迫在眉睫的威胁。Hanaa Nightwind...",kw={"奥拉凯斯暴徒","奥拉凯斯新信徒","哈娜·夜风","高阶女祭司 洛尔苏娜","马尔杜科·碎云","阿基尔神殿","森达尔林地"},sec={{t="废墟中的教徒恶棍",b="森达尔林地西南方不远处有一片古老的神殿废墟，本应为旅人提供安静的栖身之所。然而，这里却被奥拉凯斯占据了，这是一个野心狂热、行事凶暴的教派。这些教徒绝非平和的信众，而是充当拦路强盗和打手，劫掠林地边缘的过往行人。驻守附近的 游侠 怀疑，这些恶棍是高阶女祭司 洛尔苏娜 直接从阿基尔神殿派来的，目的是威吓民众，迫使他们屈从于教派的势力。"},{t="Malduko Cloudcrush",b="神殿废墟中这群乌合之众的头目是 Malduko Cloudcrush，一个依靠暴力与恐惧，让新入教者和毫无戒心的旅人俯首听命的残暴首领。一群暴徒和刚被灌输教义的新信徒听从 Malduko 的号令，让他得以在森达尔林地的门口建立起一处充满敌意的前哨。Hanaa Nightwind 希望通过击杀 Cloudcrush、驱散其爪牙，重挫教派的信心，并发出明确警告：这片土地绝不容忍狂热与胁迫。"}},faq={{q="奥拉凯斯是什么组织？",a="奥拉凯斯是在 泽风 活动的一个狂热教派。他们由阿基尔神殿的高阶女祭司 洛尔苏娜 等人领导，使用强硬手段、恐吓和暴力，强迫当地旅人和居民加入他们。",al={"奥拉凯斯是什么","奥拉凯斯教派","奥拉凯斯是谁"}},{q="教徒为什么袭击森达尔林地？",a="他们在森达尔林地西南方的神殿废墟中建立了营地，伏击离开这一带的旅人。他们希望通过恐吓路上的行人，向当地民众施压，迫使他们屈从于教派。",al={"教徒为何在这里","为何选择森达尔林地","教徒的动机"}},{q="马尔杜科·碎云 是谁？",a="马尔杜科·碎云 是一个凶暴的恶徒，统领着神殿废墟中的奥拉凯斯营地。哈娜·夜风 称他为怪物，他指挥着那些在附近道路上劫掠行人的暴徒和新信徒。",al={"马尔杜科","碎云","马尔杜科·碎云 是谁"}},{q="哈娜·夜风 是谁？",a="哈娜·夜风 是守卫森达尔林地的 游侠 成员之一。她坚守在路旁的岗位上，警告旅人提防附近教徒的伏击，并依靠有能力的冒险者清除这一威胁。",al={"哈娜","哈娜·夜风","任务发布者"}},{q="是谁把这些教徒派到废墟来的？",a="哈娜 怀疑，是在阿基尔神殿主持教派活动的高阶女祭司 洛尔苏娜 派遣了他们。",al={"谁指挥他们","教派首领","谁派来了 玛尔杜科"}},{q="神殿废墟附近还能找到什么？",a="除了奥拉凯斯营地，这一带西南端的古老废墟中还有一条活跃的 魔网能量线。",al={"废墟 魔网能量线","神殿废墟的秘密","西南方的废墟"}}},fx={b63e8692={q="哈娜·夜风为什么想清除奥拉凯斯暴徒？",a="奥拉凯斯邪教徒在森达尔林地附近扎营，位置十分危险，他们沿路骚扰旅人，还试图胁迫当地人加入狂热的教团。游侠哈娜·夜风想要瓦解他们对西南废墟的控制，并以血腥而明确的方式警告幸存的邪教徒，迫使他们离开此地。",al={"为什么要杀奥拉凯斯暴徒","哈娜·夜风的动机","为什么要清理神庙废墟"}},b6ccde37={q="哈娜·夜风为什么不能亲自对付邪教徒？",a="哈娜必须坚守岗位，密切监视局势，并警告那些离开森达尔林地、还未察觉危险的旅人，以免他们误入邪教徒的伏击圈。尽管她强忍着没有亲自冲进废墟，但她不能擅离林地边缘的职责。",al={"哈娜为什么需要我","哈娜为什么不亲自对付他们","为什么找我对付奥拉凯斯暴徒"}}},fp="14,276,29.322.0,18.370.0,21.201.0,45.206.0,26.168.0,23.188.0,37.122.0,45.117.0"}
P.entries["quest:92550"] = {n="Havoc in the Highlands",s="“Havoc in the Highlands”是代表申达尔村发起的一次先发制人的打击，旨在瓦解奥拉凯斯狂热者即将到来的袭击。通过在Falaath Village的废墟中打击他们的先遣部队并消灭指挥官Cyclas，守卫者们在邪教徒冲进高地之前扭转了局势。",h="“Havoc in the Highlands”是代表申达尔村发起的一次先发制人的打击，旨在瓦解奥拉凯斯狂热者即将到来的袭击。通过在Falaath...",kw={"奥拉凯斯","指挥官赛克拉斯","法拉斯村","高地浩劫","活体闪电","萨妮娅·银溪","申达尔村","唤雷者"},ang={["class:Shaman"]="奥拉凯斯邪教徒通过他们的唤雷者和召唤的活体闪电驾驭元素，将风暴扭曲为狂热侵略的工具。"},sec={{t="先发制人的打击",b="面对狂热邪教徒即将到来的入侵，申达尔村的领导层认为，迅速发起先发制人的进攻是生存的最佳机会。冒险者没有在脆弱的防御工事后坐以待毙，而是被派往Falaath Village的废墟，在敌对的奥拉凯斯部队发动袭击前对其进行突袭，打他们一个措手不及。"},{t="袭击Falaath Village",b="Falaath Village的集结地到处都是挥舞着混乱元素之力的危险狂热者。打击这些集结的部队需要除掉奥拉凯斯唤雷者、击碎被召唤出的活体闪电，并追踪指挥官Cyclas本人，砍下这位远征军首领的头颅。"},{t="保卫高地",b="随着指挥官Cyclas被杀，其先遣部队遭到重创，申达尔村获得了一次至关重要的喘息机会。然而，在武装平民的混乱中，一个名叫Sania Silverstream的人在无人注意的情况下溜出了城镇，就在当地防御力量集结时逃离了村庄。"}},faq={{q="什么是“高地浩劫”？",a="“高地浩劫”是申达尔村的守卫者针对聚集在法拉斯村废墟中的奥拉凯斯邪教徒所发起的一次先发制人的打击，旨在阻止他们发动袭击。",al={"高地之乱任务","什么是高地之乱","高地任务"}},{q="是谁在威胁申达尔村？",a="这个定居点面临着来自奥拉凯斯的危险，这是一个狂热的元素风暴崇拜邪教，他们拥有唤雷者、受束缚的活体闪电，以及他们的领袖指挥官塞克拉斯。",al={"敌人是谁","这是什么邪教","谁在攻击申达尔"}},{q="邪教徒在哪里集结？",a="这次打击发生在法拉斯村的废墟，指挥官塞克拉斯和他的奥拉凯斯追随者在那里建立了他们的集结地。",al={"指挥官塞克拉斯在哪里","法拉斯村废墟","去哪里"}},{q="指挥官塞克拉斯是谁？",a="指挥官塞克拉斯是带领奥拉凯斯部队的军事指挥官，他们聚集在法拉斯村的废墟中，准备进军申达尔。",al={"谁是指挥官塞克拉斯","塞克拉斯背景故事","塞克拉斯邪教"}},{q="萨尼娅·银溪为什么要逃离申达尔村？",a="萨尼娅·银溪在村庄守卫者集结前夕偷偷溜出了申达尔村，很可能是在意识到当地民众开始拿起武器组织防御后选择逃离。",al={"萨妮娅·银溪逃跑","萨妮娅为什么离开","谁是萨妮娅·银溪"}},{q="这次打击是否成功保卫了申达尔村？",a="通过击溃邪教徒的前线部队并取下指挥官塞克拉斯的首级，申达尔村击退了眼前的威胁，并向任何返回的狂热者证明，高地不会轻易陷落。",al={"申达尔幸存了吗","袭击的后果","申达尔安全吗"}}},fp="22,163,19.185.0,26.214.0,22.231.1,31.145.0,36.153.0,31.128.0,24.119.0,49.163.0,53.179.0"}
P.entries["quest:92551"] = {n="Stolen Supplies",s="Stolen Supplies任务要求冒险者从Falaath Village的奥拉凯斯手中找回被掠夺的高地物资。商队遭到伏击，切断了低地与申达尔高地之间重要的食物和风之石运输线，导致当地空裔社区处于饥饿边缘。",h="Stolen Supplies任务要求冒险者从Falaath Village的奥拉凯斯手中找回被掠夺的高地物资。商队遭到伏击，切断了低地与申达尔高地之间重要的食物和风之石运输线，导致当地空裔社区处于饥饿边缘。",kw={"奥拉凯斯","商队","治安官","法拉斯村","申达尔高地","空裔","被盗的补给","风之石"},ang={["race:Skyborne"]="袭击直接打击了连接高地与低地的生命线，使空裔城镇居民在失去了定期的食物和风之石补给后，陷入了饥饿与绝望之中。"},sec={{t="袭击高地生命线",b="几个月来，往返于低地和申达尔高地之间的商队在贸易路线上一直面临持续不断的袭击。这些货物运输着包括食物和风之石在内的重要必需品，以维持高地定居点的生存。由于缺乏稳定的物资供应，当地城镇居民被逼到了饥饿的边缘，随着该地区物资的枯竭，他们难以维持生计。"},{t="Falaath补给点",b="虽然奥拉凯斯公开指责普通强盗袭击了商队，但失踪的货物却说明了另一回事。被盗的申达尔物资成批地运往了Falaath Village，奥拉凯斯将这些补给藏匿在那里。找回这些物资可以让当地政府和治安官直接将急需的维持生存的补给重新分发给最脆弱的空裔居民。"}},faq={{q="从商队中被盗的是什么物资？",a="往返于高地和低地之间的商队携带的是重要货物，特别是食物补给和风之石。这些定期的运输保证了当地城镇居民的食物和物资供应。",al={"被偷的东西","被拿走的补给","被偷走的货物"}},{q="谁应对劫掠商队负责？",a="奥拉凯斯几个月来一直在劫掠补给商队。尽管他们试图将失踪的货物归咎于普通强盗，但众所周知，被盗的补给最终直接进入了他们位于法拉斯村的领地。",al={"谁偷了补给","谁袭击了商队","商队袭击者"}},{q="被盗的补给物资被存放在哪里？",a="被盗的补给包被储存在法拉斯村，这是一个位于申达尔高地内的奥拉凯斯定居点。",al={"补给在哪里","在哪里寻找补给","被盗藏匿点位置"}},{q="为什么这些补给商队会成为目标？",a="这些物资包括食物等基本生存资料，以及在低地之间往来运输的风之石。劫掠这些商队不仅剥夺了当地空裔民众的资源，还为法拉斯村储备了关键的高地资源。",al={"为什么要偷风之石和食物","为什么袭击商队"}},{q="物资被找回后会发生什么？",a="从法拉斯村找回物资后，我们会与当地治安官协调，将这些物资直接重新分发给最急需食物和救济的城镇居民。",al={"谁取回补给","补给再分配","找回后会发生什么"}},{q="为什么奥拉凯斯将袭击归咎于强盗？",a="奥拉凯斯将流窜的强盗作为替罪羊以推卸失踪贸易货物的责任，尽管被盗的货物始终被囤积在他们法拉斯村的定居点内。",al={"为什么要责怪强盗","奥拉凯斯的强盗借口"}}},fp="15,213,30.272.0,17.274.0,44.135.0,44.138.0,46.93.0,45.171.0,53.144.0,48.134.0"}
P.entries["quest:92553"] = {n="Restocking the Larders",s="“Restocking the Larders”是申达尔高地的一项物资补给任务。由于荒野中日益严重的威胁让村民们无法外出觅食，一位冒险者受邀前去收集鸟蛋和陆行鸟肉以维持定居点的补给。",h="“Restocking the Larders”是申达尔高地的一项物资补给任务。由于荒野中日益严重的威胁让村民们无法外出觅食，一位冒险者受邀前去收集鸟蛋和陆行鸟肉以维持定居点的补给。",kw={"烹饪","补充粮仓","申达尔高地","小型鸟蛋","陆行鸟肉","乌瑟拉牛脂","泽弗拉斯"},ang={["profession:Cooking"]="收集陆行鸟肉和小型鸟蛋等当地原料可以提供实践经验，并获得适应Zephras野生环境的烹饪食谱。"},sec={{t="高地中的危险",b="随着动荡与日益增长的危险蔓延至整个申达尔高地，Zephras的日常生活变得愈发艰难。普通的村民们无法再安全地进入荒野觅食或狩猎，导致社区的粮食储备严重不足。为了让定居点有饭吃，当地的厨师必须求助于那些拥有足够的实力和技巧去闯荡荒野小径的旅行冒险者。"},{t="补给与慰藉",b="这项任务需要追踪高地上的原生野生动物，以获取陆行鸟肉和新鲜的小型鸟蛋。对于那些提供补给的人，厨师非常乐意分享烹饪知识，传授以当地猎物为基础精炼出的食谱和烹饪技巧，包括用浓郁的ursera牛脂煎炸的鸟蛋，以及饭后一支宁静的干燥宁神花烟斗。"}},faq={{q="“补充储粮”需要什么物资？",a="当地的一位厨师需要3个小型鸟蛋和8块陆行鸟肉，用以帮助在危险阻止普通觅食者外出期间为村庄提供食物。",al={"补充食物储备目标","补充食物储备收集物品"}},{q="去哪里寻找这些原料？",a="陆行鸟肉和小型鸟蛋来自在泽风岛上的申达尔高地各处游荡的野生生物。",al={"如何在泽弗拉斯获得陆行鸟肉","申达尔鸟蛋位置"}},{q="为什么村庄的食物短缺？",a="该地区不断升级的危险使得普通村民外出狩猎或觅食变得太危险，导致粮食储备耗尽。",al={"为什么泽弗拉斯需要食物","为什么申达尔村庄饥饿"}},{q="厨师为这些食物提供什么奖励？",a="作为带回新鲜补给的交换，任务发布者会提供烹饪建议、烹饪技巧，并传授当地的食谱。",al={"任务发布者提供什么","烹饪训练任务"}},{q="什么是申达尔高地和泽风？",a="申达尔高地坐落于泽风，当地居民在努力维持日常生活的同时，还要应对日益增加的威胁。",al={"什么是泽弗拉斯","申达尔高地在哪里"}},{q="厨师是如何烹制鸟蛋的？",a="厨师极力推崇用乌瑟拉牛脂煎炸刚收集来的新鲜小型鸟蛋，称这种组合是泽风上无与伦比的慰藉。",al={"牛脂烹饪秘诀","泽弗拉斯如何烹饪鸟蛋"}}},fp="22,187,24.271.0,22.247.0,52.134.0,35.100.0,39.111.0,45.106.0,44.116.0,35.82.0"}
P.entries["quest:92579"] = {n="To Valanaar",s="“To Valanaar”是一项岛屿任务，冒险者在任务中需要将一份紧急军情报告从Shen'dar的Aonda手中送交给维和者领袖Valennia Stormfist。这则消息旨在提醒位于该岛东南边缘的定居点：一个激进的邪教组织正在迅速扩张，双方的直接冲突已不可避免。",h="“To Valanaar”是一项岛屿任务，冒险者在任务中需要将一份紧急军情报告从Shen'dar的Aonda手中送交给维和者领袖Valennia...",kw={"奥恩达","邪教","维和者","申达尔","前往瓦拉纳尔","瓦拉纳尔","瓦蕾妮娅·风暴之拳"},sec={{t="紧急公文",b="在成功保卫了Shen'dar及其塔塔后，高地人Aonda派遣一名值得信赖的旅人携带紧急消息前往岛上的瓦拉纳尔。瓦拉纳尔位于该岛的东南边缘，是岛上维和者总部的所在地，由Valennia Stormfist指挥。这项任务肩负着一个重要的警告：岛上的平静时光即将结束，Valennia必须让她的人民为与一个不断扩张的激进邪教组织之间不可避免的冲突做好准备。"},{t="酝酿中的风暴",b="在此次警告之前，当地的维和者设法避免了与这个神秘邪教组织的直接冲突。然而，该邪教组织的激进入侵已将局势推向了崩溃的边缘。在审阅了Aonda的书面报告后，Valennia意识到，维和者必须立即召集剩余的兵力并制定防御策略，以免该邪教组织将目标转向瓦拉纳尔本身。"}},faq={{q="谁派遣你前往瓦拉纳尔？",a="这项任务由申达尔的高地人奥恩达发布。在你帮助当地村庄和塔塔免受迫在眉睫的邪教威胁后，她对你的援助印象深刻，并将一份紧急书面报告托付给你，让你带往岛的另一端。",al={"谁发布了前往瓦拉纳尔任务","前往瓦拉纳尔任务发布者","谁派我去瓦拉纳尔"}},{q="谁是瓦伦妮娅·风暴之拳？",a="瓦伦妮娅·风暴之拳领导着驻扎在该岛上的维和者，总部设在瓦拉纳尔定居点。她负责当地的防御和秩序，并负责协调应对诸如邪教激进扩张等区域性威胁。",al={"谁是瓦伦妮娅·风暴之拳","瓦伦妮娅领袖","瓦伦妮娅"}},{q="什么是瓦拉纳尔？",a="瓦拉纳尔是一个位于岛屿东南边缘的定居点。它是岛上由瓦伦妮娅·风暴之拳领导的维和者的基地，同时也作为镇民的避难所和社区中心。",al={"什么是瓦拉纳尔","瓦拉纳尔在哪里","瓦拉纳尔位置"}},{q="奥恩达报告的目的是什么？",a="奥恩达的报告详细描述了日益严重的邪教威胁以及围绕申达尔及其塔塔安全所发生的事件。虽然维和者过去一直避免直接冲突，但报告警告说，该邪教组织的迅速扩张使得最终的冲突不可避免，这要求瓦拉纳尔必须为防御做好准备。",al={"为什么要递送报告","什么是奥恩达的报告","信里写了什么"}},{q="该邪教组织对岛屿构成了什么威胁？",a="这份报告警告说，有一个未具名的邪教组织正在全岛范围内迅速扩张。尽管维和者此前保持距离以避免公开战争，但该邪教组织近期针对申达尔等地的激进举动表明，冲突已无法避免。",al={"前往瓦拉纳尔的邪教组织","邪教组织是谁","邪教对岛屿的威胁"}},{q="当你到达瓦拉纳尔后会发生什么？",a="在收到这些严峻的消息后，瓦伦妮娅必须与她剩下的维和者商议，制定针对未来邪教袭击的防御策略。在协调计划的同时，她也会邀请旅人们去帮助那些在瓦拉纳尔周围需要援手的镇民。",al={"递送报告后要做什么","前往瓦拉纳尔的后续"}}},fp="11,206,18.368.0,19.279.1,26.207.0,26.191.0,17.167.0,38.241.0,45.248.0,37.226.0"}
P.entries["quest:92595"] = {n="The Windshapers",s="“塑风者”是一个任务，在任务中Illaya Amberwind向玩家介绍了塑风者以及他们的精神使命。为了重新与风之灵建立联系，该组织努力保护Zephras，并确保Shen'dorei在天空之墙的威胁中生存下来。",h="“塑风者”是一个任务，在任务中Illaya Amberwind向玩家介绍了塑风者以及他们的精神使命。为了重新与风之灵建立联系，该组织努力保护Zephras，并确保Shen'dorei在天空之墙的威胁中生存下来。",kw={"奥拉凯斯","伊拉雅·琥珀之风","申多雷","天视","天空之墙","塑风者","泽弗拉斯"},ang={["class:Shaman"]="Illaya指出，虽然受过训练的萨满祭司自然能与元素沟通，但天视的天赋也可以在其他人身上显现，这凸显了塑风者与元素召唤者共同承担的灵性职责。",["race:Skyborne"]="塑风者在天空之墙和Zephras岌岌可危的高度之上，为Shen'dorei的生存和家园而战。"},sec={{t="塑风者的职责",b="塑风者是一个致力于与风之灵沟通并保护Shen'dorei的组织。他们欢迎那些拥有与生俱来的灵性感知能力的人，并试图弥合他们的人民与维持其空中领土的元素力量之间日益扩大的裂痕。Illaya Amberwind引导新兵了解该组织所肩负的沉重负担。"},{t="Zephras的试炼",b="在天空之墙的生存绝非易事。塑风者必须应对由奥拉凯斯引起的内部动荡，同时还要承受元素位面带来的更广泛的危险。如果Zephras想要延续，且Shen'dorei想要度过这场风暴，重新与风之灵建立对话被认为是至关重要的。"}},faq={{q="谁是塑风者？",a="塑风者是一个致力于与风之灵沟通并保护其人民申多雷的组织。在像伊拉雅·琥珀之风这样的领袖的指导下，他们寻找拥有天视能力的人，以恢复与风之灵的对话，并保护他们岌岌可危的家园。",al={"谁是塑风者","塑风者阵营","塑风者的职责"}},{q="什么是天视？",a="天视是一种与生俱来的灵性敏感度或天赋，使个体能够与空中元素建立联系。正如伊拉雅所解释的，一个人不需要经过萨满祭司的正式训练也能拥有天视，尽管掌握这种能力对于联络风之灵至关重要。",al={"什么是天视","天视背景故事"}},{q="谁是伊拉雅·琥珀之风？",a="伊拉雅·琥珀之风是一位塑风者导师，她能识别出旅行者身上的灵性天赋。她欢迎那些拥有天视的人，并解释塑风者的职责、泽风所面临的危险以及申多雷所面对的试炼。",al={"谁是伊拉娅","伊拉娅·琥珀之风"}},{q="什么是泽风？",a="泽风是一片正在经受严重苦难和内部动荡的空中土地或定居点。塑风者正在积极努力保护泽风，并为他们的人民在那里保留一份未来。",al={"什么是泽弗拉斯","泽弗拉斯背景故事"}},{q="谁是奥拉凯斯？",a="奥拉凯斯是一个困扰着塑风者和申多雷的内部敌对派系或威胁，加剧了在天空之墙内生存的危险。",al={"谁是奥拉凯斯","奥拉凯斯的威胁"}},{q="谁是申多雷？",a="申多雷是塑风者所代表的族群。面对像奥拉凯斯这样的内部威胁以及在天空之墙的岌岌可危的生存条件，他们的生存取决于塑风者能否恢复与风之灵的平衡。",al={"谁是申多雷","申多雷背景故事"}}},fp="15,176,26.326.0,17.239.0,24.217.0,17.209.0,24.217.0,16.171.0,21.150.0,23.209.0"}
P.entries["quest:92596"] = {n="The High Order",s="“高阶会”是塞弗拉斯（Zephras）的一项入门任务，拉希里尔·日矛（Rathiril Sunlance）在任务中向玩家讲述了辛多雷（shen'dorei）的困境。在失去了元素恩主的援助后，这些居住在埃雷萨拉斯的上层精灵后裔必须运用他们古老的奥术魔法来保障自身的生存。",h="“高阶会”是塞弗拉斯（Zephras）的一项入门任务，拉希里尔·日矛（Rathiril...",kw={"奥拉凯斯","奥术","埃雷萨拉斯","上层精灵","拉希里尔·日矛","辛多雷","高阶会","塞弗拉斯"},ang={["class:Mage"]="拉希里尔指出，即使是那些未经过正规法师训练的冒险者身上也带有强烈的奥术光环，这强调了他们所共享的魔法是一种与生俱来的遗产，而不仅仅是一门需要研习的学科。",["race:Skyborne"]="作为埃雷萨拉斯古老上层精灵的后裔，辛多雷必须掌握他们古老的奥术天赋，以便在元素恩主离去后能够独立自强。"},sec={{t="自力更生的人民",b="“高阶会”代表了塞弗拉斯的辛多雷为重拾力量并规划未来所付出的竭诚努力。长期以来，他们的人民一直依赖于元素恩主的庇护与恩泽。随着这些元素守护者的离去，辛多雷发现自己孤立无援，容易受到内部纷争和周围险境的威胁。像拉希里尔·日矛这样的领袖正致力于寻找具有奥术天赋的个体，让他们加入到维护生存与自力更生的使命中来。"},{t="埃雷萨拉斯的遗产",b="肩负着先祖家园埃雷萨拉斯的遗产，辛多雷共享着一股与生俱来的奥术能量源泉，即便是那些尚未正式接受法术训练的人也被这股力量所环绕。高阶会将运用这些古老的魔法天赋视为他们作为上层精灵后裔的共同命运。通过这样做，他们希望能够抵御诸如奥拉凯斯之类的内部威胁，并挺过塞弗拉斯家园所面临的诸多安全危机。"}},faq={{q="什么是高阶会？",a="高阶会是辛多雷内部的一个组织，致力于保障其族人的生存。该组织由埃雷萨拉斯上层精灵的后裔创立，旨在利用他们古老的奥术天赋，确保他们的社会能够在塞弗拉斯独立防御并繁衍下去。",al={"谁是高阶会","什么是高阶会","高阶会目标"}},{q="拉希里尔·日矛是谁？",a="拉希里尔·日矛是一位与塞弗拉斯的高阶会有关联的精灵。他负责向新成员传授有关当地奥术能量的本质、辛多雷面临的困境，以及高阶会在失去昔日元素恩主后继续生存的决心。",al={"拉希里尔是谁","拉希里尔·日矛背景故事","日矛"}},{q="什么是塞弗拉斯？",a="塞弗拉斯是天空之墙内的一座浮空岛，拉希里尔·日矛和他的族人现居于此。这里充斥着奥术能量，辛多雷在此既面临内部的险境，也对自身的安全状况感到外部的不确定性。",al={"高阶会在哪里","什么是塞弗拉斯","塞弗拉斯背景故事"}},{q="谁是辛多雷？",a="辛多雷是源自埃雷萨拉斯祖居地的上层精灵后裔。如今他们定居在塞弗拉斯，拥有与奥术魔法天生的联系，并努力实现自力更生。",al={"谁是辛多雷","辛多雷","辛多雷背景故事"}},{q="谁是元素恩主？",a="元素恩主是曾经援助并庇护辛多雷的强大元素实体。然而，它们如今已离去，迫使塞弗拉斯的居民完全依靠自己的魔法造诣和足智多谋来生存。",al={"元素领主是谁","元素守护者","元素恩主"}},{q="什么是奥拉凯斯？",a="奥拉凯斯是一个内部派系或威胁，挑战着塞弗拉斯辛多雷的安全。应对此类内部对手是高阶会组织防御力量的核心关切之一。",al={"什么是奥拉凯斯","奥拉凯斯威胁","塞弗拉斯内部威胁"}},{q="高阶会与埃雷萨拉斯之间有什么联系？",a="辛多雷的先祖起源于埃雷萨拉斯，这是一座位于卡利姆多（在黑暗之门开启后25年时，许多人将其称为厄运之槌）的古老上层精灵城市。高阶会通过维护并运用他们古老的奥术天赋来尊崇这一祖传遗产。",al={"与埃雷萨拉斯的联系","他们来自厄运之槌吗","上层精灵起源"}}},fp="14,225,21.364.0,22.360.0,23.242.0,25.214.0,16.225.0,23.168.0,35.191.0,22.164.0,63.241.0"}
P.entries["quest:92597"] = {n="Reading the Ley Lines",s="“Reading the Ley Lines”是年轻的天裔发掘其上层精灵魔法传承的成人礼。在泽风岛受到Falorne Fallwind的委托后，初学者们前往森达尔林地的立石处，去感知并汲取在那片元素地形中涌动的原始奥术能量。",h="“Reading the Ley Lines”是年轻的天裔发掘其上层精灵魔法传承的成人礼。在泽风岛受到Falorne...",kw={"奥拉凯斯","法洛恩·秋风","上层精灵","地脉","解读魔网","天裔","森达尔林地","森达尔立石","塑风者","泽风岛"},ang={["class:Mage"]="对于奥术修行者来说，暴露的地脉在元素风暴肆虐的环境中代表着一个极其宝贵的未受束缚的力量源泉。",["race:Skyborne"]="这一仪式唤醒了你与生俱来的上层精灵血统，教导你将地下的地脉能量直接引导至你的施法过程中。"},sec={{t="元素位面的奥术能量",b="即使在风暴肆虐的元素位面，地表之下也流动着潜在的奥术导管。当奇怪的元素生物和充满敌意的奥拉凯斯在泽风岛游荡时，地下的地脉已经开始向地表涌动。对于魔法修习者来说，这些裂隙提供了直接接触未受束缚的奥术源泉的途径，为任何拥有血统和知识来引导这些力量的人提供增益。"},{t="上层精灵的遗产",b="Falorne Fallwind敦促初学者拥抱他们的上层精灵血统，而不是像当地的塑风者或奥拉凯斯的狂热者那样向风之灵乞求。在Fallwind看来，要在元素位面严酷的力量下生存，不取决于向外来生物乞求怜悯，而在于掌握脚下流动的内在奥术力量。"},{t="森达尔立石",b="在定居点东北方是森达尔林地，古老的立石标志着地脉汇聚的强大能量点。在这个被翻腾的风暴和奥拉凯斯的皈依者包围的裸露能量点上，初学者可以校准他们的感官，与地脉的脉动产生共鸣，并释放他们天生种族能力的全部潜能。"}},faq={{q="是谁发布了“解读地脉”任务？",a="该任务由泽风岛的法洛恩·秋风提供给那些正在学习驾驭祖传奥术能力的年轻天裔。",al={"任务发布者","法洛恩·风落","谁开启解读魔网能量线"}},{q="地脉位于何处？",a="地脉位于东北方向的森达尔立石，坐落在森达尔林地，周围环绕着敌对的元素生物和奥拉凯斯的皈依者。",al={"地脉位置","森达尔林地在哪里","森达尔立石位置"}},{q="为什么元素位面会出现地脉？",a="即使在元素位面，潜在的奥术导管也在地表下流动。最近，这些地脉开始冲破地表，为天裔提供了直接接触强大能量流的机会。",al={"元素位面的奥术","地脉元素位面传说"}},{q="法洛恩·秋风如何看待塑风者？",a="法洛恩对塑风者不屑一顾，认为他们对风之灵的崇拜是对漠不关心的元素实体的一种软弱恳求，与奥拉凯斯的崇拜没有什么两样。",al={"法洛恩对塑风者的看法","塑风者传说","塑风者与上层精灵"}},{q="引导地脉需要什么能力？",a="该任务需要在站在立石处的能量汇聚点时，使用天裔种族技能“解读地脉”。",al={"解读魔网能量线技能","如何阅读地脉","使用的种族技能"}},{q="利用地脉能带来什么好处？",a="与暴露的地脉交流会将原始奥术能量引导至使用者体内，提升他们的魔法能力，并根据导管的性质提供不同的效果。",al={"地脉的作用","地脉的好处"}}},fx={e5a629f0={q="法洛恩·风落为什么要你解读 地脉？",a="法洛恩认为，重拾你的上层精灵传承并直接汲取奥术能量脉线的力量，是你们在元素位面中唯一的救赎之路。他鄙夷塑风者和奥拉凯斯等团体，认为他们在冷漠无情的元素实体面前自甘堕落。在他看来，要想生存，就必须掌握潜藏的魔法，而不能依赖反复无常的灵体。",al={"法洛恩·风落的动机","为什么解读 魔网能量线","法洛恩·风落为什么要 魔网能量线"}}},fp="21,171,38.291.0,16.349.0,23.302.0,42.118.0,30.142.0,49.174.0,47.161.0,49.114.0,49.147.0"}
P.entries["quest:92598"] = {n="The Gift of Skysight",s="The Gift of Skysight 是年轻的塑风者学习驾驭其与灵界内在联系的一项早期试炼。在 Ventaari Brightwish 的指导下，入门者需前往一处元素汇聚点，以觉醒他们的感知，直接聆听灵魂的低语。",h="The Gift of Skysight 是年轻的塑风者学习驾驭其与灵界内在联系的一项早期试炼。在 Ventaari Brightwish 的指导下，入门者需前往一处元素汇聚点，以觉醒他们的感知，直接聆听灵魂的低语。",kw={"元素汇聚点","元素之灵","天空之眼","立石","森达尔林地","文塔里·明愿","塑风者","泽风"},ang={["class:Shaman"]="萨满祭司会认出元素汇聚点是神圣之地，在这里，凡人意志与元素位面之间的界限变得最为薄弱。",["faction:Horde"]="作为泽风岛上的盟友，部落依赖塑风者超自然的预见能力来规避岛上未知的危险。",["race:Skyborne"]="对于天裔来说，Skysight 不仅仅是一种不可思议的技巧，更是由元素守护者赋予的天赋权利，是他们文化和精神认同的基石。"},sec={{t="神圣感知",b="塑风者与塑造世界的元素力量有着与生俱来的羁绊，这种羁绊体现为被称为“Skysight”的神圣天赋。这项天赋使凡人的感官能够与灵界的波长相调和，在生者与不可见之物之间架起桥梁。虽然塑风者可以在荒野各处调用这种内在视野，但在聚集着强大力量的地点使用则能深化这种联系，从而解锁共鸣的恩惠并从风中获知隐藏的智慧。"},{t="森达尔林地的汇聚点",b="在定居点东北方，古老的立石之中，坐落着森达尔林地的元素汇聚点。像这样的地点是原始能量聚集、灵体徘徊的焦点。Ventaari Brightwish 派遣新手前往这处神圣之地，不仅是为了完成一项任务，更是为了考验他们的精神体质。正如任何身心的天赋一样，Skysight 需要刻意的锻炼才能成熟，以确保成长的塑风者能够解读元素的变幻预兆，而他们族人的生存正依赖于此。"}},faq={{q="这项任务的目的是什么？",a="这项任务旨在教导新手塑风者如何实际运用他们的 天视 能力。文塔里·明愿 指导入门者前往元素汇聚点，体验环境能量如何放大他们的精神感官。",al={"天空视界的恩赐 目的","为何进行此任务","天空视界 训练"}},{q="文塔里·明愿 是谁？",a="文塔里·明愿 是一位灵性向导和导师，负责监督泽风岛上塑风者的早期训练，教导他们尊重并磨练自己的元素传承。",al={"文塔里","文塔里·明愿 是谁","明愿"}},{q="什么是元素汇聚点？",a="元素汇聚点是精神能量高度集中的焦点，通常以古老的立石作为标记。这些地点自然地吸引元素之灵，并放大像 天视 这类能力。",al={"什么是元素汇聚点","元素汇聚点背景","森达尔林地汇聚点"}},{q="元素汇聚点位于何处？",a="该汇聚点位于森达尔林地的立石群中，就在泽风岛定居点的东北方。",al={"汇聚点在哪里","森达尔林地位置","立石位置"}},{q="天视 可以随处使用吗？",a="可以。塑风者可以在任何地方调用 天视，但在元素汇聚点内，它能带来更强大的增益，并引导出附近灵魂的额外启示。",al={"我可以在任何地方使用 天空视界 吗","汇聚点之外的 天空视界","在哪里使用 天空视界"}},{q="为什么 天视 被认为对生存至关重要？",a="天视 在凡人与元素之灵之间架起了桥梁。根据 文塔里 的说法，感知并留意元素的警告对于规避即将来临的危险和保护族人至关重要。",al={"为什么 天空视界 很重要","天空视界 生存","元素生存"}}},fx={d2ee972c={q="文塔莉·明愿为什么要你在汇聚点使用天视？",a="文塔莉·明愿希望训练你发掘与生俱来的塑风者传承。天视就像肌肉一样，需要在元素汇聚点这类力量之地不断锻炼，这样你才能学会跨越凡俗与灵界之间的距离。她认为，与灵体交流并聆听元素对你们的启示，对你们的生存至关重要。",al={"文塔里为什么想要这样做","文塔里·明愿的动机","为什么在这里使用天视"}}},fp="20,163,19.399.0,32.398.0,34.114.0,27.131.0,33.163.0,43.119.0,30.136.0,50.163.0"}
P.entries["quest:926"] = {n="有瑕疵的能量石",s="在贫瘠之地那干旱广袤的土地深处，充满奥术能量的神秘石头静静地放置在奥术祭坛上。这些不稳定的遗物被刻意设计了致命的缺陷，一旦脱离其源头，它们就会迅速消耗自身的能量。",h="在贫瘠之地那干旱广袤的土地深处，充满奥术能量的神秘石头静静地放置在奥术祭坛上。这些不稳定的遗物被刻意设计了致命的缺陷，一旦脱离其源头，它们就会迅速消耗自身的能量。",kw={"奥术","贫瘠之地","瑕疵能量石","能量石","仪式祭坛","不稳定的魔法"},ang={["faction:Horde"]="部落时刻警惕着散落在贫瘠之地各处的奥术异常，以防这些失控的魔法威胁到他们的补给线。"},sec={{t="不稳定的工艺",b="在贫瘠之地四处散落的瑕疵能量石是奇特的魔法异常现象。尽管它们无疑蕴含着奥术精华，但其结构在制造时就被刻意破坏了。无论是什么人制造了它们，其目的都是确保它们保持极度不稳定，并在被触碰后片刻之内就会退化为惰性物质。"},{t="自我消耗的能量",b="这些石头并不能作为稳定的储能器或催化剂，它们一旦从放置它们的仪式祭坛上被拿走，就会立即开始燃烧其内部的能量。这种自我消耗的特性使得任何人无法将其带到远方。"}},faq={{q="什么是瑕疵能量石？",a="瑕疵能量石是一种充斥着原始魔法能量的不稳定物体。它是被刻意制造出缺陷的，导致其在移动后会迅速烧尽能量并自我消耗。",al={"瑕疵能量石","这是什么石头","能量石背景知识"}},{q="这些石头可以永久保存吗？",a="不能。一旦脱离它们赖以维持稳定的祭坛，其魔法矩阵就会崩溃，并迅速耗尽自身的能量储备。",al={"保存瑕疵能量石","可以存储它吗","保存石头"}},{q="谁在使用这些石头？",a="这些石头是由兽人阿克泽洛斯准备的，他指派部落的冒险者将它们送到鬼雾峰的火焰祭坛，以此切断恶魔之种与燃烧军团的联系。",al={"谁制造了能量石","谁制作了它们","石头制造者"}},{q="为什么部落会对这些石头感兴趣？",a="这些石头是部落在此对抗燃烧军团的武器。阿克泽洛斯受尼鲁·火刃之命准备了这些石头，只要将其带到鬼雾峰的火焰祭坛，就能切断恶魔之种与军团的联系。",al={"部落的兴趣","为什么部落想要这个"}}},fp="18,171,22.187.0,21.150.0,29.102.0,40.128.0,22.182.0,35.206.0"}
P.entries["quest:9260"] = {n="调查暴风城的天灾入侵",s="天灾军团的入侵将巫妖王的恐怖直接带到了暴风城的门口。在首都的城墙外，通灵塔笼罩着大地，亡灵憎恶和邪教徒正在施展黑暗魔法。奥林中尉征召有能力的保卫者去消灭入侵者，收集坏死之石，并破解那些在营地中跳动的邪恶符文圆阵。",h="天灾军团的入侵将巫妖王的恐怖直接带到了暴风城的门口。在首都的城墙外，通灵塔笼罩着大地，亡灵憎恶和邪教徒正在施展黑暗魔法。奥林中尉征召有能力的保卫者去消灭入侵者，收集坏死之石，并破解那些在营地中跳动的邪恶符文圆阵。",kw={"银色黎明","入侵","巫妖王","奥林中尉","通灵塔","坏死之石","符文圆阵","天灾军团","暴风城"},ang={["class:Paladin"]="在暴风城外直面天灾军团，圣骑士有义务释放神圣愤怒，摧毁这些死灵圆阵，并保护王国的子民。",["class:Priest"]="入侵符文中扭曲的低语让牧师能够直接洞察那些束缚着天灾前线部队的腐化暗影魔法。",["faction:Alliance"]="在暴风城大门抵御天灾入侵关乎联盟的生死存亡，这证明了即便是他们南方的堡垒也在巫妖王的掌握之中。"},sec={{t="首都门前的亡灵",b="天灾军团如此靠近暴风城，这让整个王国感到震惊和不安。浮空城在头顶徘徊，蹒跚的亡灵和邪恶的教徒在人类最伟大的堡垒门口建立了立足点。奥林中尉在城外集结保卫者，要在这些入侵的恐怖威胁到首都防线之前将他们击退。"},{t="低语符文",b="除了单纯地击退行尸走肉，这项任务还需要调查刻在敌方营地周围泥土中的发光符文圆阵。这些神秘的圆阵闪烁着与上方通灵塔所散发的同样的邪恶魔法。走进它们的光芒中，空气中回荡着诡异的低语声——那些不自然的声音暗示这些圆阵是某种黑暗通讯的渠道，尽管奥林中尉也只能猜测它们在联系谁。"}},faq={{q="奥林中尉是谁？",a="奥林中尉是一位在暴风城外协调防御工作的军官。他与银色黎明并肩作战，组织当地的战士收集情报，并捣毁威胁着这座城市的天灾军团立足点。",al={"奥林","奥林中尉","任务给予者是谁"}},{q="为什么天灾军团要攻击暴风城？",a="巫妖王已经在艾泽拉斯各地派遣了空中通灵塔和入侵部队，旨在散布恐惧并壮大亡灵的队伍。暴风城作为活人抵抗势力的主要据点，自然成为了这些袭击的首要目标。",al={"为什么天灾军团会在这里","暴风城天灾入侵","为什么要攻击暴风城"}},{q="那些发光的符文圆阵是什么？",a="符文圆阵是天灾军团在他们的前进营地附近建立的仪式阵列。它们脉动着黑暗的死灵能量，并发出不自然的声音，充当着入侵者进行神秘通讯的魔法中继站。",al={"符文圆阵","发光的符文","圆阵的作用"}},{q="黯淡的坏死之石是什么？",a="黯淡的坏死之石是天灾入侵部队中低阶士兵携带的魔法焦点。它们散发出残留的死灵能量，既是消灭入侵者的证明，也是银色黎明感兴趣的研究对象。",al={"黯淡的坏死之石","坏死之石","坏死之石是什么"}},{q="银色黎明在这次任务中扮演什么角色？",a="银色黎明是一个致力于在天灾军团出现的地方将其根除的独立组织。奥林中尉代表他们行事，通过获取情报和坏死之石来协助他们对抗巫妖王大军的全面战争。",al={"银色黎明","与银色黎明的联系"}},{q="靠近这些符文圆阵危险吗？",a="虽然这些圆阵散发出令人不安的能量并发出不和谐的低语，但小心接近它们的侦察兵可以在不丧失理智的情况下，深入了解天灾军团的通讯情报。",al={"符文是否安全","符文中的低语"}}},fx={c2a78be7={q="奥林中尉为什么要调查此事？",a="巫妖王已将亡灵大军直接派到暴风城门外，集结在一座不祥的浮空大墓地下方。奥林中尉知道，入侵者正在家门口聚集，城中绝不能坐视不理。他迫切需要弄清那些发光符文法阵背后的诡异魔法，并削减敌军数量，阻止亡灵在王国城墙外建立稳固的据点。",al={"奥林为何要做此事","奥林中尉的动机","为何调查天灾军团"}},["9cb0511c"]={q="你被派去对付暴风城外的什么敌人？",a="你要对抗的是集结在城外大墓地下方的天灾军团入侵部队。这些亡灵突击部队和畸怪已在暴风城门外扎营，奉巫妖王之命制造混乱，威胁王国。",al={"交战对象是谁","暴风城外的敌人是谁","外面有哪些天灾军团"}}},fp="36,219,33.265.0,20.249.0,24.195.0,39.206.0,35.155.0,29.139.0,52.202.0,44.164.0"}
P.entries["quest:9261"] = {n="调查铁炉堡的天灾入侵",s="当亡灵天灾直接降临在铁炉堡大门外时，银色黎明的奈维尔中尉发出了集结勇敢保卫者的号召。在巨大的浮空城笼罩下，亡灵部队和不祥的符文法阵正在威胁着丹莫罗雪白的山口。保卫者的任务是消灭那些行尸走肉，并破译这些散发着诡异光芒的符文背后的意图。",h="当亡灵天灾直接降临在铁炉堡大门外时，银色黎明的奈维尔中尉发出了集结勇敢保卫者的号召。在巨大的浮空城笼罩下，亡灵部队和不祥的符文法阵正在威胁着丹莫罗雪白的山口。保卫者的任务是消灭那些行尸走肉，并破译这些散发着诡异光芒的符文...",kw={"银色黎明","暗淡的死灵之石","丹莫罗","调查铁炉堡的天灾军团","铁炉堡","巫妖王","奈维尔中尉","浮空城","符文法阵","天灾军团"},ang={["class:Paladin"]="天灾军团是圣光的对立面。调查巫妖王的符文恶意并净化他那些盲目的爪牙，完全属于圣骑士神圣天职的范畴。",["class:Priest"]="在符文法阵中低语的心灵回响对普通士兵的理智构成了明显的威胁，需要精神坚韧方能抵御。",["faction:Alliance"]="铁炉堡是联盟至关重要的经济和军事支柱；在它的大门外建立亡灵据点威胁着整个东部王国的后勤补给线。",["race:Dwarf"]="丹莫罗洁白的雪地被腐烂的怪物玷污，这对每一位矮人来说都是一种冒犯。保卫山门就是保卫家园。"},sec={{t="山门之死",b="亡灵天灾的入侵并没有在洛丹伦或是北方的瘟疫之地停止。浮空城在艾泽拉斯投下了阴森的阴影，这其中也包括了铁炉堡山门外寒冷的丹莫罗高地。银色黎明已经在当地派驻了观察员，比如奈维尔中尉，旨在监视并反击这种不断蔓延的凋零，以防它突破铜须矮人的堡垒。"},{t="邪恶铭文",b="在浮空城的阴影下，亡灵设立了营地，周围环绕着发光的符文法阵和脉动着的死灵之石。站在这些不祥的法阵旁，侦察兵能发现黑暗且低语的声音在环境魔法中回荡。奈维尔中尉推断这些法阵是某种黑暗的通讯渠道，但他尚不清楚天灾军团究竟在与谁联系。"}},faq={{q="奈维尔中尉是谁？",a="奈维尔中尉是银色黎明的一名军官，驻扎在铁炉堡，负责协调针对天灾入侵的防御工作。他派遣冒险者去收集死灵之石，并探索入侵者营地周围那些邪恶符文的用途。",al={"奈维尔","奈维尔中尉","任务发布者"}},{q="为什么天灾军团要攻击铁炉堡？",a="这项任务关注的是驻扎在铁炉堡外浮空城下的天灾部队。奈维尔中尉要求保卫者削减他们的数量，并调查附近那些奇怪的符文法阵。",al={"铁炉堡外的天灾军团","为什么亡灵在丹莫罗","铁炉堡入侵"}},{q="暗淡的死灵之石是什么？",a="暗淡的死灵之石是从天灾入侵者身上搜集到的，它们被带回银色黎明作为击杀亡灵的凭证。",al={"死灵之石","暗淡的死灵之石","天灾石"}},{q="那些发光的符文法阵有什么用途？",a="发光的符文法阵出现在天灾入侵部队的附近。奈维尔中尉要求你去调查它们的用途。",al={"符文法阵","发光的法阵","符文是什么"}}},fx={["4916b51d"]={q="奈维尔中尉为什么要调查此事？",a="天灾军团已兵临铁炉堡城下，一座大墓地高悬头顶，奈维尔中尉和银色黎明决意采取行动。城门外的亡灵营地附近出现了奇怪的符文法阵，闪烁着邪恶魔法的光芒。奈维尔知道这些仪式预示着凶险，需要你赶在城市遭遇更大灾难之前，查明入侵者正在引导何种邪恶力量。",al={"奈维尔的动机","为何调查铁炉堡的天灾军团","奈维尔为何要做此事"}},f222933f={q="你被派去对抗铁炉堡外的什么敌人？",a="你被派去对付在铁炉堡大门外扎营的天灾军团先锋部队。这些恐怖的亡灵奉巫妖王之命而来，有一座浮空大墓地作为后援，企图在丹莫罗散播恐惧，围攻矮人王国。",al={"该与谁交战","铁炉堡的天灾军团目标","交战对象是谁"}}},fp="36,188,27.275.0,19.288.1,25.231.0,39.162.0,29.120.0,49.110.0"}
P.entries["quest:9262"] = {n="调查达纳苏斯的天灾入侵",s="调查达纳苏斯的亡灵天灾是贝萨中尉代表银色黎明发布的一项紧急任务。一座浮空城笼罩在亡灵天灾的营地上空，联盟的守卫者们接到任务，需要摧毁入侵的亡灵，并解读在城市大门外出现的黑暗符文圆环。",h="调查达纳苏斯的亡灵天灾是贝萨中尉代表银色黎明发布的一项紧急任务。一座浮空城笼罩在亡灵天灾的营地上空，联盟的守卫者们接到任务，需要摧毁入侵的亡灵，并解读在城市大门外出现的黑暗符文圆环。",kw={"银色黎明","贝萨","达纳苏斯","巫妖王","浮空城","死灵石","符文圆环","亡灵天灾","泰达希尔","亡灵"},ang={["class:Druid"]="通灵术在泰达希尔土地上的蔓延以及血肉的腐烂，代表着一种每一位荒野保护者都发誓要根除的不自然枯萎。",["class:Priest"]="牧师们面临着检验腐化通灵符文的严峻考验，他们利用自己的精神纪律和信仰来抵御天灾黑暗网络中低语的疯狂。",["faction:Alliance"]="达纳苏斯的防御彰显了联盟团结一致，共同对抗巫妖王入侵部队所构成的全球性威胁的决心。",["race:NightElf"]="对于卡多雷来说，腐烂的浮空城和亵渎的亡灵如此靠近泰达希尔的圣地，是一种必须立即清除的粗鄙暴行。"},sec={{t="世界之树上的瘟疫",b="亡灵天灾的入侵已经蔓延到了泰达希尔的庇护枝叶下。浮空城出现在天空中，不断向达纳苏斯城外倾吐着食尸鬼、骷髅和通灵恐怖怪物。银色黎明的贝萨中尉挺身而出，负责协调这座首都的防御工作，招募志愿者来削弱敌人的先锋部队，并在亡灵淹没暗夜精灵家园之前收集情报。"},{t="符文中的低语",b="除了简单地消灭亡灵并收集它们身上黯淡的死灵石外，侦察兵还被要求检查入侵营地附近地面上闪烁着诡异光芒的符文阵列。靠近这些圆环会让守卫者接触到令人不安的超自然低语，这表明这些符文是某种不自然的通信中继站，尽管贝萨中尉并不知道天灾军团正在与谁联系。"}},faq={{q="贝萨中尉是谁？",a="贝萨中尉是一位代表银色黎明驻扎在达纳苏斯的军官。她组织当地力量抵抗亡灵天灾的入侵，分派任务以遏制亡灵数量并研究其通灵装置。",al={"谁发布了调查达纳苏斯的亡灵天灾任务","贝萨任务发布者","贝萨中尉背景故事"}},{q="为什么亡灵天灾要袭击达纳苏斯？",a="这项任务关注的是达纳苏斯城外浮空城下驻扎的天灾部队。贝萨中尉请求守卫者们削减它们的数量，并调查附近奇怪的符文圆环。",al={"为什么亡灵在达纳苏斯","泰达希尔入侵","巫妖王袭击暗夜精灵"}},{q="城外的发光符文圆环是什么？",a="发光的符文圆环出现在亡灵天灾入侵部队附近。贝萨中尉请求你调查它们的用途。",al={"达纳苏斯天灾符文","达纳苏斯外的符文圆环","入侵符文是什么"}},{q="黯淡的死灵石是什么？",a="黯淡的死灵石是从天灾入侵者身上回收的，它们被带给银色黎明作为击杀亡灵的凭证。",al={"死灵石","死灵石有什么用","黯淡的死灵石背景"}},{q="谁在资助或领导达纳苏斯的防御响应？",a="银色黎明正通过贝萨中尉协调这项调查。该组织致力于对抗亡灵天灾。",al={"谁领导达纳苏斯防御","达纳苏斯银色黎明"}},{q="聆听符文圆环会造成伤害吗？",a="它们的确切影响尚不明确。贝萨请求守卫者们调查圆环周围的奇异能量。",al={"符文圆环低语","符文圆环声音危险"}}},fp="36,187,26.352.0,21.290.1,25.185.0,39.160.0,52.111.0,29.113.0,52.118.0,44.109.0"}
P.entries["quest:9263"] = {n="调查奥格瑞玛的天灾入侵",s="天灾军团竟然在奥格瑞玛的大门外，在一座浮空死灵要塞的阴影下建立了一座营地，此举简直是狂妄至极。达格尔中尉正在召集守卫者们击退这些亡灵，回收死灵石，并调查那些嗡嗡作响、散发着死灵能量的神秘符文圆环。这次突如其来的入侵，标志着巫妖王的势力已经直接深入到了杜隆塔尔的核心区域。",h="天灾军团竟然在奥格瑞玛的大门外，在一座浮空死灵要塞的阴影下建立了一座营地，此举简直是狂妄至极。达格尔中尉正在召集守卫者们击退这些亡灵，回收死灵石，并调查那些嗡嗡作响、散发着死灵能量的神秘符文圆环。这次突如其来的入侵，标志...",kw={"银色黎明","达格尔","杜隆塔尔","入侵","巫妖王","死灵石","奥格瑞玛","符文圆环","天灾军团"},ang={["faction:Horde"]="一支入侵部队在奥格瑞玛的塔楼视野内安营扎寨，这对部落来说是不可容忍的侮辱。保卫杜隆塔尔、对抗巫妖王的爪牙，是任何宣誓勇士的重要职责。",["race:Orc"]="杜隆塔尔那干燥的红土地是靠苦难和鲜血赢来的。兽人们绝不会允许这些无脑的怪物践踏他们亲手开拓的家园。",["race:Undead"]="对于被遗忘者来说，天灾军团是他们曾经被奴役的痛苦回忆。粉碎这些入侵者是对巫妖王那不断延伸的魔爪的一次个人复仇。"},sec={{t="大门外的亡灵",b="天灾军团的威胁已不再局限于洛丹伦那些荒废的王国或北方的冰封荒原。一座座浮空死灵要塞出现在艾泽拉斯各地，连杜隆塔尔上空也笼罩在黑暗的阴影之中。在奥格瑞玛的门槛之上，亡灵部队已经集结，建立起营地，威胁着部落的首都。达格尔中尉和银色黎明正在协调防御工作，号召当地的勇士们在入侵者建立起无法攻破的包围圈之前将他们击退。"},{t="死灵遗物与黑暗低语",b="除了仅仅是屠杀这些逼近的怪物并收集它们身上暗淡的死灵石之外，防御战的关键还在于了解入侵者的手段。在他们的营地周围环绕着发光的符文印记，这些印记与上方死灵要塞中散发的黑暗力量产生了共鸣。那些勇敢步入符文之中的人会听到以太中回荡着非自然的低语——这暗示着某种形式的交流，尽管达格尔并不知道这些声音在与谁联络。"}},faq={{q="天灾军团为什么要攻击奥格瑞玛？",a="这项任务涉及驻扎在奥格瑞玛外、死灵要塞下的天灾军团。达格尔中尉请求守卫者们削减他们的数量，并调查附近奇怪的符文圆环。",al={"为什么天灾军团攻击奥格瑞玛","奥格瑞玛外的亡灵","巫妖王攻击奥格瑞玛"}},{q="达格尔中尉是谁？",a="达格尔中尉是一位与银色黎明配合行动的军官，负责召集守卫者抵抗入侵。达格尔驻扎在威胁附近，指挥战士们消灭亡灵并检查他们在战场上使用的奥术工具。",al={"达格尔中尉","达格尔任务发布者","达格尔是谁"}},{q="暗淡的死灵石是什么？",a="暗淡的死灵石是从天灾入侵者身上回收的战利品，交给银色黎明作为已击杀亡灵的证据。",al={"死灵石","什么是暗淡的死灵石","暗淡的石头"}},{q="城外的发光符文圆环是什么？",a="这些发光的圆环携带着与附近的亡灵和死灵要塞相同的奇异能量。达格尔请求守卫者们调查它们的用途。",al={"符文圆环","奥格瑞玛的发光符文","天灾圆环"}},{q="银色黎明为什么会出现在杜隆塔尔？",a="银色黎明是一个独立的组织，致力于在天灾军团出现的所有地方消灭它们。由于这次入侵威胁到了每一个文明生灵，该组织正在与部落守卫者合作，以保卫奥格瑞玛的边境。",al={"银色黎明在奥格瑞玛","为什么银色黎明在这里","银色黎明与部落"}},{q="头顶的死灵要塞对城市有危险吗？",a="这座死灵要塞笼罩在天灾营地上空，并与之共享着那种奇异的能量。它的存在使得附近的亡灵威胁成了城市的一大忧患。",al={"奥格瑞玛的浮空城堡","杜隆塔尔上空的死灵要塞"}}},fp="36,274,19.396.0,33.327.1,39.164.0,24.201.0,33.120.0,52.136.0,43.181.0,49.135.0"}
P.entries["quest:92640"] = {n="Desperate Times",s="Desperate Times任务要求玩家向瓦拉纳尔的Valennia Stormfist报道，以计划对一个危险教派的神龛进行直接打击。由于在开阔地带与该教派对抗并不可行，在神龛处击败其领袖Lorthuna至关重要，但这需要弥合塑风者与高阶会之间深重的分歧。",h="Desperate Times任务要求玩家向瓦拉纳尔的Valennia...",kw={"教派","绝望时刻","高阶会","洛尔苏娜","神龛","瓦拉纳尔","瓦伦妮娅·风暴之拳","塑风者"},sec={{t="直接打击",b="面对一个无法在开阔地带安全对抗的教派，守卫者必须转向更大胆的策略。与其在不利的地形上进行持久战，该计划主张利用机会直接突袭教派的神龛。通过在Lorthuna完成其宏大计划中的角色之前将其消灭，可以从源头上消除威胁。"},{t="团结分裂的派系",b="在瓦拉纳尔，Valennia Stormfist长期以来一直在制定突袭神龛的作战策略。然而，如果没有大量的增援和统一的兵力，这次突袭就无法成功。发起进攻需要调和严重的政治摩擦，因为塑风者和高阶会之间挥之不去的紧张关系威胁到了执行此次攻击所需的联盟。"}},faq={{q="瓦伦妮娅·风暴之拳是谁？",a="瓦伦妮娅·风暴之拳是一位驻扎在瓦拉纳尔的领袖或战略家。她花费时间制定了一项突袭该教派所在神龛的战术计划，尽管执行该计划需要弥合敌对派系之间的分歧。",al={"瓦伦妮娅是谁","瓦伦妮娅·风暴之拳","瓦伦妮娅在哪里"}},{q="洛尔苏娜是谁？",a="洛尔苏娜是敌对教派中的关键人物。她目前正在神龛策划一项关键阴谋，这使她成为此次提议的先发制人打击的首要目标。",al={"洛尔苏娜是谁","洛尔苏娜背景故事","教派领袖洛尔苏娜"}},{q="为什么要直接攻击神龛？",a="在开阔地带直接与该教派交战被认为是不可行或自杀性的行为。直接突袭他们的神龛提供了最佳的战略窗口，可以在洛尔苏娜的阴谋实现之前将其消灭。",al={"为什么要攻击神龛","攻击教派的原因"}},{q="塑风者和高阶会之间有什么问题？",a="塑风者和高阶会之间目前的局势非常紧张。尽管存在摩擦，但瓦伦妮娅指出，如果没有双方的合作，任何一个派系都不可能单独完成对神龛的突袭。",al={"高阶会与塑风者的紧张关系","为什么派系之间在战斗","塑风者纠纷"}},{q="瓦拉纳尔在哪里？",a="瓦拉纳尔是瓦伦妮娅·风暴之拳协调战略并召集必要盟友以准备即将对教派神龛进行的打击的集结地。",al={"瓦拉纳尔在哪里","瓦拉纳尔位置"}},{q="这项任务的总体目标是什么？",a="目标是找到瓦拉纳尔的瓦伦妮娅·风暴之拳，了解她计划的针对神龛的突袭作战细节，并帮助确保分裂的派系之间达成必要的合作。",al={"危急时刻目标","危急时刻计划是什么"}}},fp="15,195,15.304.0,24.282.0,26.153.0,16.140.0,41.140.0,61.148.0,18.121.0,41.150.0"}
P.entries["quest:92642"] = {n="Disrupting Logistics",s="“Disrupting Logistics”任务要求冒险者挫败奥拉凯斯邪教徒在阵风浆果低地发动的全面进攻。通过消灭那些维持前线斗士战力的敌方治疗者，玩家将帮助陷入苦战的当地守军在防线崩溃前扭转战局。",h="“Disrupting Logistics”任务要求冒险者挫败奥拉凯斯邪教徒在阵风浆果低地发动的全面进攻。通过消灭那些维持前线斗士战力的敌方治疗者，玩家将帮助陷入苦战的当地守军在防线崩溃前扭转战局。",kw={"奥拉凯斯","斗士","邪教徒","扰乱补给","阵风浆果低地","治疗者","瓦伦尼亚"},ang={["class:Priest"]="牧师们深知治疗支援对于维持进攻战线的重要性，这也使得奥拉凯斯的治疗者成为了邪教徒进攻的核心。",["class:Rogue"]="潜入敌后消灭高优先级的治疗者并扰乱前锋增援，这是潜行者标准的战术破坏手段。"},sec={{t="绝望的防御",b="一场激烈的突袭正威胁着阵风浆果低地上方的守军。随着敌军集结完毕，当地防线已到崩溃边缘，前线指挥官们陷入了绝望。守军原本期待着来自瓦伦尼亚的强力援军，但现在却只能依靠任何能提供帮助的人手，并祈祷针对敌方后勤支援网络的精确打击能阻止即将到来的溃败。"},{t="击溃邪教徒防线",b="奥拉凯斯的攻势依赖于紧密协作的凶猛斗士阵列，而专门负责治疗伤口和维持前线推进的治疗者则是他们的中坚力量。在阵风浆果低地消灭这些治疗者，就能瓦解邪教徒进攻的脊梁，切断其后勤补给，从而让守军有机会重整旗鼓，击退入侵者。"}},faq={{q="什么是“破坏后勤”任务？",a="“破坏后勤”是一项紧急防御任务，旨在挫败奥拉凯斯邪教徒在阵风浆果低地发动的全面进攻。一名坚守阵地的孤军守卫需要立即得到支援，以在防线彻底崩溃前除掉敌军的前线后续力量。",al={"什么是扰乱后勤","扰乱后勤任务","阵风浆果低地任务"}},{q="攻击低地的奥拉凯斯邪教徒是谁？",a="攻击者是奥拉凯斯邪教徒，他们由好斗的斗士和提供支援的治疗者组成，正对阵风浆果低地发动积极进攻。他们有组织的攻势高度依赖专门的治疗支援来保持对当地守军的持续压制。",al={"谁是奥拉凯斯","谁在攻击阵风浆果低地","这些邪教徒是谁"}},{q="为什么要专门针对奥拉凯斯的治疗者？",a="奥拉凯斯的治疗者提供了持续的恢复支援，使前锋战士能够不间断地发起冲锋。通过切断这些治疗者，守军希望能打破对方的进攻势头，并创造反击机会，将邪教徒击退。",al={"为什么要杀掉治疗者","为什么要针对奥拉凯斯治疗者"}},{q="这场突袭发生在什么地方？",a="阵风浆果低地位于邪教徒围攻的防御哨所下方的山坡处。目前那里已被奥拉凯斯的斗士和治疗者占领，他们正在推进前线攻势。",al={"阵风浆果低地在哪里","阵风浆果低地位置"}},{q="瓦伦尼亚是谁？",a="瓦伦尼亚似乎是一位负责组织援助和增援的领导者或协调员，尽管那位守卫对瓦伦尼亚在面对大规模进攻时仅派出一名冒险者感到气愤。",al={"谁是瓦伦尼亚","瓦伦尼亚增援"}},{q="是谁在指挥对抗奥拉凯斯的防御？",a="该任务由一名陷入困境的守卫发布，他的人民正处于被奥拉凯斯邪教徒淹没的边缘。该守卫对“风”表达了崇敬，并迫切需要任何战斗力量来扭转战局。",al={"谁发布了扰乱后勤","我的人民在坚守什么"}}},fp="20,178,19.351.0,25.239.0,39.198.0,53.171.0,51.183.0,35.192.0,16.146.0,46.183.0"}
P.entries["quest:92643"] = {n="The Turncoat",s="“变节者”讲述了一名奥拉凯斯邪教徒试图投诚，并用他所知的邪教对这座岛屿的真实意图作为筹码，换取避难所的故事。旅行者们受命前往瓦拉纳尔西北部高地的一处隐秘住所营救他，必须查明这次秘密会面究竟是真正的突破口，还是一个致命的陷阱。",h="“变节者”讲述了一名奥拉凯斯邪教徒试图投诚，并用他所知的邪教对这座岛屿的真实意图作为筹码，换取避难所的故事。旅行者们受命前往瓦拉纳尔西北部高地的一处隐秘住所营救他，必须查明这次秘密会面究竟是真正的突破口，还是一个致命的陷...",kw={"奥拉凯斯","邪教徒","叛逃者","高地","叛徒","变节者","瓦拉纳尔"},ang={["class:Rogue"]="潜入、叛逃和伏击，这些都是司空见惯的事。背叛邪教的人预料到会遭遇沉默或利刃，而等候在屋外的刺客证明了，在这片高地上，秘密往往是双刃剑。"},sec={{t="破碎的誓言",b="一名来自奥拉凯斯内部的秘密线人提供了一个难得的机会，可以揭开这个邪教的神秘面纱。这名邪教徒声称掌握了该组织对这座岛屿的真实意图，他背弃了信仰并提出投诚，要求以他所掌握的情报为交换，获得明确的保护承诺。鉴于该邪教的计划守卫森严，任何能深入了解其内部运作的线索都值得冒着危险去接触。"},{t="高地藏身处",b="叛逃者逃往瓦拉纳尔西北部高地的一处隐秘住所，独自等待着秘密接应。接近他需要极度小心地在山中穿行，因为这次会面极有可能是奥拉凯斯为了引诱那些爱管闲事的对手而设下的伏击。"},{t="高地上的死寂",b="当抵达这处偏僻的高地房屋时，任何和平接应的希望都破灭了。在接应人员赶到之前，刺客们就已经追踪到了叛逃者并将他杀害。在余波和屋外倒下的刺客中，这名已死的变节者身上反射出的微光表明，他可能依然留下了一些线索。"}},faq={{q="变节者是谁？",a="变节者是奥拉凯斯邪教的前成员，他声称掌握了关于该邪教对这座岛屿的真实意图的关键情报。为了换取保护，他提出投诚并透露他所知的一切。",al={"变节者是谁","叛逃者是谁","变节者身份"}},{q="什么是奥拉凯斯？",a="奥拉凯斯是一个在该地区活动的神秘邪教。他们针对岛屿的秘密计划和最终目标被重重迷雾和狂热信仰所掩盖，导致当地当局甘冒重险，试图引诱任何愿意开口的逃兵。",al={"谁是奥拉凯斯","奥拉凯斯邪教","什么是奥拉凯斯"}},{q="叛逃者躲在哪里？",a="叛逃者躲藏在瓦拉纳尔西北部高地的一处隐秘住所中。他选择了这处偏远的房屋作为藏身之所，等待着承诺提供保护的接应人员。",al={"变节者躲在哪里","变节者位置","在哪里寻找变节者"}},{q="叛逃者发生了什么事？",a="当有人赶到那处高地隐秘住所时，刺客已经追踪到了叛逃者并将其杀害。在屋内发现他的尸体后，任何活捉他进行审问的希望都落空了。",al={"变节者发生了什么","叛逃者死了吗","谁杀死了变节者"}},{q="变节者留下了什么？",a="在处理完屋外的刺客并检查死去的叛逃者遗体时，一道微弱的反射光映入眼帘。他身上携带的某个闪亮物品被留了下来，暗示着他的秘密并没有随他完全消逝。",al={"什么闪亮的物体","变节者闪亮物品","尸体上的闪光反射"}},{q="邪教徒为何决定投诚？",a="这名邪教徒声称掌握奥拉凯斯对这座岛屿的真实意图，并且只有在获得保护承诺的情况下才会出来。任务中并未说明他投诚的原因。",al={"为什么邪教徒叛逃","变节者动机","为什么背叛奥拉凯斯"}}},fp="12,206,13.233.0,20.213.0,24.246.1,20.188.0,21.197.0,29.147.0,30.166.0,35.168.0,37.171.0"}
P.entries["quest:92644"] = {n="Unfortunate News",s="你发现叛逃者已经身亡，没能留下任何话语。尸体下留着一块受损的蓝色水晶，你将它带给了瓦拉纳尔的大长老Talanaanis 影歌。",h="你发现叛逃者已经身亡，没能留下任何话语。尸体下留着一块受损的蓝色水晶，你将它带给了瓦拉纳尔的大长老Talanaanis 影歌。",kw={"邪教徒","发光的水晶","影歌","塔拉纳尼斯·影歌","叛逃者","不幸的消息","瓦拉纳尔"},ang={["class:Mage"]="身为法师，你或许能认出那块受损、发光的蓝色水晶是一件法器。大长老影歌正在调查邪教徒，并收下水晶加以研究。"},sec={{t="未能赴约",b="你抵达会面地点，发现那名叛逃的邪教徒已经被杀。尸体尚有余温。尸体下有一块小小的蓝色水晶，散发着光芒，虽已受损，却仍在嗡嗡作响。你将它带给了瓦拉纳尔的大长老Talanaanis 影歌。"},{t="影歌的调查",b="你独自返回瓦拉纳尔，告诉大长老Talanaanis 影歌，叛逃者还没来得及作证就死了。失去这名活着的线人，是一次严重的挫折。然而，那块受损的蓝色水晶引起了大长老的注意。他觉得它很有意思，便从你手中接过了水晶。"}},faq={{q="不幸的消息是什么任务？",a="你发现那名叛逃的邪教徒已经身亡，没能留下任何话语。尸体下有一块受损的蓝色水晶，散发着光芒，你将它带给了大长老塔拉纳尼斯 影歌。",al={"不幸的消息是什么","不幸的消息任务","不幸的消息 魔兽世界永恒"}},{q="那个叛逃的邪教徒是谁？",a="叛逃者是一名邪教徒，你受命前去与其会面。此人还没来得及开口或逃走就被杀了，只留下尚有余温的尸体和一块受损的水晶。",al={"死去的叛逃者是谁","不幸的消息中谁死了","叛逃的邪教徒"}},{q="大长老影歌是谁？",a="塔拉纳尼斯·影歌是一名精灵，也是瓦拉纳尔的大长老。他指挥对邪教徒的调查，并收下了在叛逃者尸体下发现的受损水晶。",al={"瓦拉纳尔的影歌是谁","塔拉纳尼斯·影歌在哪里","塔拉纳尼斯·影歌"}},{q="受损的蓝色水晶是什么？",a="受损的蓝色水晶是一块散发着光芒的小水晶，在死去的叛逃者身下被发现。大长老影歌觉得它很有意思，便从你手中接过了水晶。",al={"发光的水晶是什么","邪教徒的蓝色水晶","受损的水晶 不幸的消息"}},{q="这个任务发生在哪里？",a="瓦拉纳尔是大长老塔拉纳尼斯·影歌的居所。你带着调查结果和找回的水晶返回那里。",al={"瓦拉纳尔在哪里","瓦拉纳尔位置","交付不幸的消息"}},{q="这个任务与叛逃者有什么关联？",a="这个任务接续叛逃者，在那个任务中，你动身寻找叛逃的邪教徒。你来得太晚，没能救下此人。",al={"不幸的消息的前置任务是什么","不幸的消息前置任务","叛徒任务"}}},fp="16,164,19.232.0,26.275.1,35.166.0,29.160.0,29.166.0,33.153.0,33.120.0,44.112.0"}
P.entries["quest:92645"] = {n="Breaking the Breaker",s="“击碎者”是一次针对指挥官贝尔吉洛斯的孤注一掷的军事打击，这位令人胆寒的前维和人员现在正领导着一场发生在阵风浆果低地的危险邪教袭击。在她的山坡别墅处除掉她，是那些苦苦支撑的守卫者们唯一真正的生存机会。",h="“击碎者”是一次针对指挥官贝尔吉洛斯的孤注一掷的军事打击，这位令人胆寒的前维和人员现在正领导着一场发生在阵风浆果低地的危险邪教袭击。在她的山坡别墅处除掉她，是那些苦苦支撑的守卫者们唯一真正的生存机会。",kw={"贝尔吉洛斯","击败破坏者","贝尔吉洛斯指挥官","邪教指挥官","阵风浆果低地","维和人员","击碎者","别墅"},ang={["class:Warrior"]="直面贝尔吉洛斯指挥官，意味着要与一位强硬的前维和人员正面对抗，她赢得了“击碎者”这一令人恐惧的称号。",["race:Skyborne"]="祈求四风祝福英雄，呼应了天裔文化在低地面对危险邪教徒时的传统与信仰。"},sec={{t="绝望的防御",b="阵风浆果低地正遭受激进邪教徒的猛烈攻击，当地守卫者们已退无可退。如果不直接打击行动的头目——也就是被所有人畏称为“击碎者”的贝尔吉洛斯指挥官，击退这次袭击几乎是不可能的。在她的基地别墅处除掉她是一项极其危险、近乎自杀的任务，但坐以待毙只会让守卫者们走向毁灭。"},{t="堕落的维和人员",b="在统领这群邪教徒大军很久之前，贝尔吉洛斯曾是一名秩序的执行者，担任维和人员。然而即使在那时，她身边的人就察觉到她举止中有些极其令人不安的地方。当邪教的影响力失控蔓延时，她完全拥抱了其中的极端主义，现在她已是邪教的指挥官，一位名副其实的恐怖人物。"}},faq={{q="谁是击碎者贝尔吉洛斯？",a="被称为“击碎者”的贝尔吉洛斯是一位强悍的指挥官，她正指挥着一场邪教徒袭击。在加入邪教之前，她曾是一名维和人员，尽管同时代的人记得她那时就已经非常令人不安，且倾向于暴力。",al={"谁是贝尔吉洛斯","谁是击碎者","邪教指挥官"}},{q="在哪里可以找到贝尔吉洛斯指挥官？",a="贝尔吉洛斯指挥官驻扎在位于阵风浆果低地山脚下的别墅里。她在那里坐镇，协调邪教徒针对当地守卫者们的进攻。",al={"贝尔吉洛斯在哪里","贝尔吉洛斯位置","哪里寻找击碎者"}},{q="为什么要除掉贝尔吉洛斯？",a="当地守卫者正面临邪教徒的猛烈进攻，只要贝尔吉洛斯还在指挥，就几乎不可能击退他们。除掉她就能瓦解邪教的领导层，让守卫者们获得真正的生存机会。",al={"为什么杀掉贝尔吉洛斯","邪教袭击原因","为什么击碎者很危险"}},{q="贝尔吉洛斯在加入邪教之前的过往如何？",a="在邪教彻底失控之前，贝尔吉洛斯曾担任过维和人员。然而，了解她的人都指出，即使在担任秩序执行者期间，她就显得有些“不正常”，所以她后来成为一名残暴的邪教领袖并不让人意外。",al={"贝尔吉洛斯过去是谁","贝尔吉洛斯曾经善良吗","维和人员邪教徒"}},{q="四风祝福的意义是什么？",a="这项祝福祈求四风的庇佑，是守卫者在得知可怕的邪教指挥官被彻底终结后，表达深深的解脱与感激的一种传统用语。",al={"四风含义","谁说四风保佑你"}},{q="什么是阵风浆果低地？",a="阵风浆果低地包含了邪教袭击展开的争议地区，山脚下的别墅就是贝尔吉洛斯指挥官所在的地方。",al={"什么是阵风浆果低地","击碎者任务在哪里"}}},fp="20,195,19.329.0,22.276.0,29.175.0,39.158.0,33.180.0,50.158.0,59.166.0,32.144.0"}
P.entries["quest:92646"] = {n="Confront Lorthuna",s="Confront Lorthuna标志着对高阶女祭司Lorthuna的关键追击，她通过一道传送门逃往Zephras上方的罗哈什尖塔。The Adventurer们受命前往支援Elaadrin Evengale和Ayessa Dawnsinger，在岛屿高空进行一场绝望的战斗。战斗结束后，关键的防御者身受重伤，Zephras未来的安全也画上了问号。",h="Confront Lorthuna标志着对高阶女祭司Lorthuna的关键追击，她通过一道传送门逃往Zephras上方的罗哈什尖塔。The Adventurer们受命前往支援Elaadrin...",kw={"艾耶莎·晨歌","直面洛尔苏娜","艾拉德林·暮风","高阶女祭司洛尔苏娜","洛尔苏娜","穆尔恩","罗哈什尖塔","瓦伦妮娅","塑风者","泽弗拉斯"},ang={["class:Priest"]="高阶女祭司Lorthuna代表了尖塔中被腐蚀的精神领袖，这使得针对她的战斗对于那些抵御黑暗教义的牧师来说尤其具有共鸣。",["class:Shaman"]="随着Muln和塑风者指导着Zephras上的元素平衡，萨满祭司在确保岛屿的元素和谐免受Lorthuna威胁方面有着强烈的精神利害关系。"},sec={{t="追击尖塔",b="高阶女祭司Lorthuna通过一道神秘的传送门退回到了上方的罗哈什尖塔。由于一名盟友在传送门入口处受伤，Elaadrin Evengale和Ayessa Dawnsinger立即追入高处，并呼吁任何有能力的勇士穿过传送门前去支援，以免Lorthuna逃脱制裁或巩固她的力量。"},{t="战斗的代价",b="在尖塔中经历危险的冲突后，防御者们付出了沉重的代价。Valennia和她幸存的部队需要治疗师的立即救治，并被护送回高阶长老的住所进行休养。尽管Lorthuna已被正面交锋，但此次行动使联盟受到重创，资源也显得捉襟见肘。"},{t="一座脆弱的岛屿",b="随着当下的战斗结束，Muln在商讨了塑风者的未来及其正在进行的任务后，启程返回艾泽拉斯大陆。然而，胜利并未带来和平：冲突过后的Zephras岛变得极其脆弱，迫使剩余的领导层必须紧急规划防御措施，以应对接下来的威胁。"}},faq={{q="谁是高阶女祭司洛尔苏娜？",a="高阶女祭司洛尔苏娜是一位强大的敌人，她利用传送门退往泽弗拉斯上方的罗哈什尖塔。她的行为构成了严重的威胁，以至于包括艾耶莎·晨歌和埃拉德琳·暮风在内的关键防御者们不得不对她展开追击，以将其击败。",al={"谁是洛尔苏娜","洛尔苏娜是什么","高阶女祭司洛尔苏娜背景故事"}},{q="什么是罗哈什尖塔？",a="罗哈什尖塔是矗立在泽弗拉斯岛上空的险峻高地。可以通过传送门到达，那里是高阶女祭司洛尔苏娜逃亡并负隅顽抗的战场。",al={"什么是罗哈什尖塔","传送门通往哪里","罗哈什尖塔位置"}},{q="谁追随洛尔苏娜进入了传送门？",a="当高阶女祭司洛尔苏娜逃往上方尖塔时，埃拉德琳·暮风和艾耶莎·晨歌是第一批冲过传送门立即对她进行追击的人。她们请求了增援，促使冒险者跟了上去。",al={"谁去追击洛尔苏娜了","艾耶莎和埃拉德林","谁进入了传送门"}},{q="瓦伦妮娅和她的部队发生了什么？",a="瓦伦妮娅在对峙期间指挥部队，并在战斗中受了重伤。冲突结束后，治疗师被派遣以确保她安全返回，随后她被送往高阶长老的住所休息。",al={"谁是瓦伦妮娅","瓦伦妮娅怎么了","瓦伦妮娅的部队"}},{q="穆尔恩在这些事件中扮演了什么角色？",a="穆尔恩是一位与塑风者有关的盟友，他在返回艾泽拉斯大陆之前曾协助泽弗拉斯。在离开之前，他讨论了塑风者的未来计划及其更宏大的使命。",al={"谁是穆尔恩","穆尔恩离开泽弗拉斯","穆尔恩去了哪里"}},{q="在与洛尔苏娜对峙后，泽弗拉斯岛安全了吗？",a="即使在与高阶女祭司洛尔苏娜对峙之后，泽弗拉斯仍处于危险的状态。这座岛屿变得比以往任何时候都更加脆弱，要求防御者们制定新的计划，以保护它免受迫在眉睫的威胁。",al={"泽弗拉斯发生了什么","泽弗拉斯现在安全吗","泽弗拉斯岛的状态"}}},fp="17,204,23.295.0,22.248.1,25.257.1,31.169.0,28.138.0,37.141.0,41.156.0,36.134.0,59.146.0"}
P.entries["quest:92679"] = {n="Blood Tithe",s="\"Blood Tithe\"是由一位受病痛折磨的天裔农民Alvarion Windfield发起的一项任务，他正在瓦拉纳尔的定居点寻求帮助。为了保护他的生计，他迫切地招募冒险者前往西部的低地果园，协助他的妻子Aamelia。",h="\"Blood Tithe\"是由一位受病痛折磨的天裔农民Alvarion...",kw={"阿梅莉亚·荒原","阿尔瓦里昂·荒原","鲜血贡赋","凌空者","瓦拉纳尔","风野果园"},ang={["race:Skyborne"]="Alvarion Windfield是一位天裔农民，他的身体痛苦和绝望的求援突显了普通天裔在瓦拉纳尔定居点之外所面临的困境。"},sec={{t="瓦拉纳尔的求援",b="在瓦拉纳尔定居点，一位名叫Alvarion Windfield的受伤天裔人正在绝望地寻找有能力的冒险者。忍受着肉眼可见的剧痛，Alvarion从自己的农庄来到镇上，试图雇佣战士来拯救他的生计。他并没有当场给旅行者下达任务，而是恳求愿意帮忙的人前往西部的低地，那里他的妻子Aamelia正在照看他们的家庭果园。"},{t="低地的麻烦",b="风野果园位于瓦拉纳尔以西的低地。由于Alvarion因剧痛而丧失了行动能力，维持农场的重担落在了Aamelia Windfield肩上。接受Alvarion提议的冒险者必须前往西部的山谷，查明是什么威胁了果园，并向这户陷入困境的家庭伸出援手。"}},faq={{q="阿尔瓦里昂·荒原是谁？",a="阿尔瓦里昂·荒原是一位翔空者农民，他来到瓦拉纳尔，寻找有能力的战士来帮助保护他的家园。尽管承受着严重的身体疼痛，他还是设法指引冒险者去往果园寻找他的妻子阿梅莉娅。",al={"阿尔瓦里昂是谁","阿尔瓦里昂·荒原背景故事","谁发布血税"}},{q="风野果园在哪里？",a="风野果园位于瓦拉纳尔以西的低地。阿尔瓦里昂派遣冒险者前往那里会见他的妻子阿梅莉娅 荒原，她正在负责农场的紧急防御工作。",al={"风野果园在哪里","阿梅莉亚·荒原位置","如何找到果园"}},{q="阿尔瓦里昂为什么感到痛苦？",a="虽然在见到他时并未说明具体的病痛，但阿尔瓦里昂在交谈时显然正承受着剧烈且令人虚弱的疼痛，这使得他的求援更加紧迫。",al={"阿尔瓦里昂为何痛苦","阿尔瓦里昂出了什么问题","阿尔瓦里昂的伤痛"}},{q="阿梅莉娅·荒原是谁？",a="阿梅莉娅·荒原是阿尔瓦里昂的妻子，驻守在瓦拉纳尔以西的家庭果园。阿尔瓦里昂指引愿意帮忙的冒险者去往她那里，组织对他们土地的防御。",al={"阿梅莉亚是谁","阿梅莉亚·荒原背景故事","阿尔瓦里昂的妻子"}},{q="\"鲜血贡品\"的任务内容是什么？",a="\"鲜血贡品\"始于阿尔瓦里昂·荒原在瓦拉纳尔招募旅行者以协助他陷入困境的农场。冒险者必须听取他的请求，并在他们的低地果园寻找他的妻子阿梅莉娅。",al={"血税任务概述","血税的内容","瓦拉纳尔遭受袭击的农场"}},{q="瓦拉纳尔在这里有什么意义？",a="瓦拉纳尔是旅行者和翔空者聚集的定居点。阿尔瓦里昂特地来到这个中心寻找雇佣帮手和有能力的冒险者，以将他的果园从危险中解救出来。",al={"瓦拉纳尔背景故事","血税的发生地点","什么是瓦拉纳尔"}}},fp="11,208,18.270.0,23.239.0,26.183.0,39.163.0,24.149.0,25.143.0,32.131.0,37.139.0"}
P.entries["quest:92682"] = {n="Make Yourself Useful",s="“Make Yourself Useful”是风野果园的一项任务，探险者们将在那里保护风暴苹果作物，抵御缺乏纪律的强盗。一名叫作Ferauu的勒索者本应定期前来收取他的那份收成，但饥肠辘辘的歹徒们私自脱离队伍，提前潜入果园偷盗。解决这些不听指挥的窃贼会赢得警惕的果园管理员的尊重。",h="“Make Yourself...",kw={"强盗","费劳","饥饿的强盗","发挥你的用处","果园","成熟的风暴苹果","风暴苹果","风野果园"},ang={["class:Rogue"]="当这些背叛了自己团伙只为抢先偷吃一口风暴苹果的强盗们忙碌时，经验丰富的盗贼一眼就能看出这些业余窃贼身上那种典型的缺乏纪律的表现。"},sec={{t="风野果园的麻烦",b="在风野果园，勒索行为让农耕变得十分复杂。一名叫作Ferauu的强盗头目和他的手下已经建立了一套定期收取水果收成的“规矩”。然而，强盗团伙内部纪律松散，意味着一些小毛贼总是等不及老板预定的来访时间，便偷偷潜入果园提前采摘。"},{t="贼中之贼",b="为了不让这些纪律涣散的窃贼在风暴苹果树丛中肆意妄为，果园管理员在Ferauu预定抵达之前，让雄心勃勃的后来者们去干活。探险者们的任务是保护成熟的风暴苹果收成，并清理那些潜入树丛中的饥饿强盗。管理员提到，如果Ferauu发现这些人背着他私自篡改分成，很可能会亲手处决这些不听话的流氓。"}},faq={{q="费劳是谁？",a="费劳是一名勒索风野果园的强盗头目，他要求对方定期缴纳贡品，即所谓“收成”的一部分。他对自己的手下维持着残暴的纪律，但显然这还不足以阻止一些饥饿的喽啰背着他偷偷溜进果园。",al={"费劳是谁","费劳背景故事","费劳强盗头目"}},{q="什么是风野果园？",a="风野果园是一个以出产风暴苹果而闻名的当地农耕地。果园在强权之下运作，被迫向费劳的强盗团伙支付部分水果收成以维持安宁。",al={"什么是风野果园","风野果园背景故事","风暴苹果果园"}},{q="为什么会有饥饿的强盗潜伏在风暴苹果树丛中？",a="隶属于费劳的饥饿强盗们抢先下手，在预定的收成时间之前溜进果园，想为自己偷盗风暴苹果。由于他们违反纪律并且私自盗取作物，果园管理员便派遣探险者去清理他们。",al={"为什么要杀死饥饿的强盗","为什么果园里会有强盗","饥饿的强盗背景故事"}},{q="什么是风暴苹果？",a="风暴苹果是风野果园培育的一种水果。它们既是日常的口粮，也是当地犯罪团伙（如费劳的团伙）所要求的勒索赎金。",al={"什么是风暴苹果","成熟的风暴苹果"}},{q="费劳知道他的手下潜入果园了吗？",a="不知道，费劳并不知道这些特定的强盗提前行动了。正如果园管理员所指出的，这些歹徒背离了组织，如果被费劳抓到他们在自己抵达之前就私吞收成，很可能会被他亲手处决。",al={"费劳知道这些强盗吗","费劳的背叛者"}},{q="是谁委托你执行“发挥你的作用”的？",a="这个任务由风野果园的管理员提供，他正从附近的窗户注视着果园。面对寻找工作或食物的大胆新来者，管理员通过派他们去对付入侵的强盗来考验他们的胆量。",al={"谁发布了发挥你的作用","发挥你的作用任务发布者"}}},fp="20,208,28.224.0,21.298.0,14.193.0,26.153.0,53.219.0,21.125.0,59.175.0,40.230.0"}
P.entries["quest:92683"] = {n="Flutterfly Dust",s="Flutterfly Dust是阵风浆果低地的一项本地任务，需要从巨大的、带翅膀的Flutterfly身上采集粉末。虽然这些昆虫通常很温顺，但由于流窜的强盗带来的持续威胁，独居的农户不得不依靠旅行者来采集这种粘糊糊的物质。",h="Flutterfly...",kw={"强盗","振翅蝶","振翅蝶粉尘","扑翼蝶拍","阵风浆果低地","果园","翅膀粉尘"},sec={{t="阵风浆果的巨人",b="阵风浆果低地的外围田野和果园是巨大Flutterfly的家园，这些风景如画的有翼昆虫在乡村景观中懒洋洋地飞来飞去。虽然它们温和的外表为该地区增添了一抹田园风情，但它们扑扇的翅膀会抖落一种细小且无处不在的粉尘，可以大量采集。尽管它们主要是野生昆虫，但它们的存在吸引了附近农户的注意，这些人试图采集这种空中副产品以满足实际的家庭需求。"},{t="拍打与摇晃",b="采集Flutterfly Dust需要一种出人意料的简单粗暴的方法：用扑翼蝶拍击打这些大型昆虫。大多数Flutterfly在受到击打时只会惊慌失措地飞走，摇动屁股并撒下一堆散落的粉末。然而，偶尔也会有被激怒的Flutterfly在受到挑衅后回击，证明即使是温顺的园林昆虫在被拍打时也有它们的底线。"},{t="秘而不宣的用途",b="收集这种粉尘是一项凌乱且粘人的工作，往往会让衣服和装备在几周内都沾满粉末。虽然当地的委托人急切地等待着交付，因为潜伏的强盗使得独自进入田野变得太过危险，但粉尘的最终用途却被严密地掩盖了起来。当被追问用途时，农户只会用诸如“弄些东西”之类的借口来搪塞。"}},faq={{q="翩翩蝶粉尘有什么用？",a="据收集它的当地居民说，巨大翩翩蝶抖落的翅膀粉尘在大量收集后有实际的家庭用途。然而，具体的用途仍然故意含糊其辞，因为任务发布者用“弄些东西”之类的说法来回避问题。",al={"什么是扑翼蝶粉尘","扑翼蝶粉尘的用途","粉尘是做什么用的"}},{q="在哪里可以找到翩翩蝶？",a="可以在当地果园附近的外围田野，特别是阵风浆果低地四处飞舞的地方找到巨大的翩翩蝶。它们与附近的强盗威胁共享这些田野，这使得独居的居民采集变得危险。",al={"扑翼蝶在哪里","扑翼蝶的位置","阵风浆果低地的虫子"}},{q="翩翩蝶具有攻击性吗？",a="翩翩蝶通常是温顺、平静的生物，受到惊扰时通常会逃跑。然而，如果被拍打或挑衅，一些翩翩蝶会感到被冒犯，并在释放翅膀粉尘前出人意料地进行防御。",al={"扑翼蝶有危险吗","扑翼蝶会攻击人吗","扑翼蝶的行为习性"}},{q="如何收集翩翩蝶粉尘？",a="冒险者使用特制的扑翼蝶拍用力拍打这些大型昆虫。受到惊吓或激怒的生物在反应时会摇动屁股，将一堆可采集的翅膀粉尘散落在地上。",al={"如何获取粉尘","扑翼蝶拍","收集扑翼蝶粉尘"}},{q="为什么居民需要别人帮忙采集粉尘？",a="需要粉尘的农户独居，无法轻易离开家去采集，因为潜伏在周围低地的强盗构成了太大的威胁，冒险深入田野非常危险。",al={"为什么需要帮助","阵风浆果的强盗威胁","为什么任务发布者提出请求"}},{q="为什么居民对粉尘的真正用途讳莫如深？",a="任务发布者拒绝透露这种脏兮兮的粉尘的具体家庭用途，只是用“弄些东西”来紧张地推托。这究竟是令人尴尬的私人杂务，一种非主流的手工艺，还是纯粹的私人事务，目前仍未可知。",al={"为什么如此保密","秘密粉尘配方"}}},fp="15,184,23.244.0,19.200.0,21.277.0,33.122.0,29.170.0,28.135.0,33.151.0,59.169.0,58.144.0"}
P.entries["quest:92684"] = {n="Ornery Ornery Galestriders",s="“Ornery Ornery Galestriders”讲述了一位阵风浆果低地的果园农夫正因这个季节收成惨淡而苦苦挣扎的故事。当地的低地疾风陆行鸟——比它们高地的同类体型更大、更凶猛——一直潜入果园偷食风暴苹果，威胁着农场的生计。猎杀这些好斗的鸟类不仅能保住剩余的果实，还能为晚餐提供急需的新鲜里脊肉。",h="“Ornery Ornery...",kw={"疾风陆行鸟","阵风浆果低地","低地疾风陆行鸟","果园","暴躁的疾风陆行鸟","风暴苹果","里脊肉"},ang={["class:Hunter"]="在阵风浆果低地追踪野生动物的猎人们应该注意，与高地的同类相比，当地的低地疾风陆行鸟拥有更强有力的踢击和更暴躁的脾气。",["profession:Cooking"]="低地疾风陆行鸟提供的丰盛里脊肉是一顿扎实的热餐，这对于长期面对匮乏的收成和果实的人们来说，是一种受欢迎的改善生活的方式。"},sec={{t="保卫果园",b="在阵风浆果低地，当地农夫在经历了一个季节收成惨淡的年份后，正面临着严峻的考验。更糟糕的是，野生的疾风陆行鸟入侵了果园，它们剥光了枝头成熟的风暴苹果，使本就所剩无几的果实岌岌可危。想要维持农场的生计，就必须在所有庄稼被毁掉之前，赶走或清理掉那些最肆无忌惮的鸟儿。"},{t="低地恐怖",b="与它们在高地那些体型较小、相对温顺的亲戚不同，低地的疾风陆行鸟是巨大的、脾气暴躁的野兽。低地的旅行者必须格外小心地靠近它们，因为它们那强有力的腿部只要踢中一脚，就足以让粗心大意的战士重伤甚至丧命。击杀它们可以获得巨大的里脊肉，为饥饿的当地人提供稀有而丰盛的餐食。"}},faq={{q="为什么疾风陆行鸟给农夫造成了麻烦？",a="当地的疾风陆行鸟一直潜入果园偷吃农夫的风暴苹果。由于这个季节的收成已经非常稀少，这些偷窃果实的行为直接威胁到了当地的粮食供应。",al={"疾风陆行鸟偷什么","为什么要杀疾风陆行鸟","风暴苹果果园"}},{q="低地疾风陆行鸟有多危险？",a="低地疾风陆行鸟比高地的同类体型更大、攻击性更强。它们强有力且时机精准的踢击，如果不小心防备，很容易就能将旅行者彻底踢倒。",al={"疾风陆行鸟有多危险","疾风陆行鸟袭击","疾风陆行鸟强吗"}},{q="农夫想要从疾风陆行鸟身上得到什么？",a="农夫请求旅行者猎杀那些好斗的低地疾风陆行鸟，并从这些倒下的野兽身上收集里脊肉。在长时间没有新鲜肉食之后，这些肉能提供一顿急需的热餐。",al={"疾风陆行鸟肉","疾风陆行鸟掉落什么","里脊肉任务"}},{q="这些疾风陆行鸟在哪里可以找到？",a="暴躁的低地疾风陆行鸟出没于整个阵风浆果低地，特别是在它们觅食风暴苹果的农庄和果园附近。",al={"疾风陆行鸟在哪里找到","疾风陆行鸟位置","阵风浆果低地"}},{q="低地疾风陆行鸟与高地疾风陆行鸟相比如何？",a="低地疾风陆行鸟与它们高地的同类主要在体型和性情上有所不同：低地品种体型明显更大，性情也凶残得多，并且能踢出极具破坏力的一脚。",al={"高地与低地疾风陆行鸟对比","疾风陆行鸟种类"}},{q="什么是风暴苹果？",a="风暴苹果是该地区种植的一种果园作物。由于本季的产量已经很稀少，保护剩余的果树免受疾风陆行鸟的觅食破坏至关重要。",al={"什么是风暴苹果","果园收成"}}},fp="26,213,21.253.0,15.241.0,57.126.0,40.136.0,48.109.0,35.132.0,63.120.0,21.141.0"}
P.entries["quest:92685"] = {n="The Hills Have Eyes",s="“The Hills Have Eyes”是阵风浆果低地的一项任务，身陷困境的农民Aamelia决定反抗拦路强盗。冒险者会对北部山丘上的一个营地发动先发制人的打击，以在强盗首领Ferauu发起袭击之前削弱他们的力量。",h="“The Hills Have Eyes”是阵风浆果低地的一项任务，身陷困境的农民Aamelia决定反抗拦路强盗。冒险者会对北部山丘上的一个营地发动先发制人的打击，以在强盗首领Ferauu发起袭击之前削弱他们的力量。",kw={"阿梅莉亚","强盗面具","血迹斑斑的强盗面具","费劳","阵风浆果低地","拦路强盗","隔山有眼"},ang={["profession:Tailoring"]="Aamelia阴森地开着玩笑，说要为Ferauu缝制一条用血迹斑斑的强盗面具做成的毯子，这展现了她对针线活某种令人毛骨悚然的鉴赏力。"},sec={{t="先发制人的打击",b="在阵风浆果低地，一位名叫Aamelia的农民正面临Ferauu领导的一伙亡命之徒即将发动的袭击。她没有坐以待毙，而是敦促旅行者对北面山丘上的强盗营地发动先发制人的打击。她希望能在拦路强盗集结进攻前消灭他们，从而减少他们的人数并争取宝贵的时间。"},{t="重燃希望与复仇",b="作为伏击的证明，Aamelia要求得到从阵亡的拦路强盗身上剥下的血迹斑斑的面具。她冷酷地开着玩笑，说要把这些面具缝成一条毯子送给Ferauu，并因为得知折磨她的人遭到了猛烈的抵抗而感到快意。摧毁北部营地终结了她数周以来绝望的等待，给了她在Ferauu和他的主力部队最终抵达时挺身抗争的勇气。"}},faq={{q="什么是“群山有眼”？",a="“群山有眼”是阿梅莉亚在她的农场发布的一项防御任务。面对费劳的拦路强盗团伙即将发动的袭击，她指引冒险者前往北部的山丘伏击强盗，并在他们发起攻击前夺取他们的血迹斑斑的面具。",al={"群山有眼任务","这个任务是什么","什么是群山有眼"}},{q="谁发布了“群山有眼”任务？",a="阿梅莉亚是一位农场守卫者，她已经在恐惧中度过了数周，担心强盗会占领她的家园。反击拦路强盗给了她重燃希望，去面对费劳即将到来的袭击。",al={"谁发布了群山有眼","阿梅莉亚是谁","任务发布者阿梅莉亚"}},{q="费劳是谁？",a="费劳是在阵风浆果低地一带活动的拦路强盗的首领。他和他的暴徒一直在威胁阿梅莉亚的农场，并且正准备发动袭击。",al={"费劳是谁","头目费劳","强盗首领费劳"}},{q="拦路强盗位于何处？",a="拦路强盗在阵风浆果低地各处都设有营地，包括阿梅莉亚农场正北面山丘上的一个小营地。",al={"阵风浆果低地强盗","强盗在哪里","山丘强盗营地"}},{q="为什么阿梅莉亚想要血迹斑斑的强盗面具？",a="阿梅莉亚要求这些血迹斑斑的面具作为证明，表明强盗们受到了惩罚并被打了个措手不及。提前消灭他们有助于在面对费劳即将到来的袭击时扳回局面。",al={"为什么收集面具","为什么是血迹斑斑的面具","面具有什么用"}},{q="任务完成后会发生什么？",a="在摧毁了山丘营地后，阿梅莉亚感到希望重新回到了她的农场。然而，费劳和他的残余暴徒随时都可能抵达，为最终的决战拉开了序幕。",al={"群山有眼之后会发生什么","阿梅莉亚后续任务","费劳袭击"}}},fp="19,175,19.295.0,28.357.1,28.177.0,40.136.0,14.130.0,41.136.0,49.140.0,40.161.0"}
P.entries["quest:92693"] = {n="Standing Our Ground",s="“Standing Our Ground”是一个关键任务，冒险者将与Aamelia Windfield并肩作战，在绝望的对峙中对抗一名穷凶极恶的强盗首领。在帮助守卫们做好战斗准备后，你将面对一场看似必败无疑的战斗，以确保大家免受强盗的侵害。",h="“Standing Our Ground”是一个关键任务，冒险者将与Aamelia...",kw={"阿梅莉亚·荒原","强盗首领","强盗","必败的战斗","坚守阵地","瓦拉纳尔"},sec={{t="孤注一掷的背水一战",b="“Standing Our Ground”标志着与一伙强盗殊死搏斗的高潮。在帮助当地守卫为不可避免的冲突做好准备后，你获得了最后一次机会，可以选择撤离并安全返回瓦拉纳尔，而不是投身于这场看似注定失败的背水一战。"},{t="对抗强盗首领",b="当你示意准备就绪时，你将与Aamelia Windfield一同上前，直面强盗首领。击败这名歹徒将解除迫在眉睫的威胁，Aamelia会因他们孤注一掷的赌博竟然成功而感到震惊与如释重负。"}},faq={{q="谁发布了“坚守阵地”任务？",a="该任务由阿梅莉亚·荒原发布，她正准备迎接即将到来的强盗袭击，并向你提供了在面对其首领之前退出的最后机会。",al={"谁发布了坚守阵地","坚守阵地任务发布者","坚守阵地 任务人物"}},{q="在“坚守阵地”中你与谁战斗？",a="对峙的目标是威胁当地守卫的入侵强盗首领。阿梅莉亚·荒原鼓起最后的决心，准备挺身而出直接面对这个首领。",al={"坚守阵地的强盗首领是谁","坚守阵地首领","坚守阵地强盗首领"}},{q="瓦拉纳尔在这个任务中是什么地位？",a="瓦拉纳尔是阿梅莉亚·荒原提到的附近定居点，也是撤退的目的地。她明确表示，如果你不想在战斗中冒生命危险，可以选择撤退到瓦拉纳尔。",al={"瓦拉纳尔在哪里 坚守阵地","坚守阵地撤退城镇","瓦拉纳尔任务"}},{q="为什么阿梅莉亚将这场战斗描述为必败无疑？",a="阿梅莉亚和她的同伴认为敌我悬殊，将这场对峙视为一场绝望的背水一战，如果没有外援，想要幸存下来几乎是不可能的。",al={"为什么坚守阵地是必败的战斗","坚守阵地剧情","阿梅莉亚·荒原的挣扎"}},{q="对峙结束后会发生什么？",a="出人意料的是，强盗首领被击败了。任务完成后，阿梅莉亚·荒原对于苦难终于结束感到震惊与如释重负，平复着剧烈的心跳。",al={"击败坚守阵地的强盗首领后会发生什么","坚守阵地任务提交","阿梅莉亚会存活吗"}},{q="是什么导致了这场最后的决战？",a="在此任务之前，你曾协助守卫们进行了准备工作，这让他们在面对强盗威胁时有了一线生机，也为这场关键的对决铺平了道路。",al={"坚守阵地前置任务","坚守阵地之前的任务"}}},fp="19,181,22.219.0,29.228.1,40.89.0,40.122.0,43.129.0,53.169.0,44.139.0,34.117.0"}
P.entries["quest:92698"] = {n="What Is My Purpose?",s="“What Is My Purpose?”是一个任务，围绕着一个在农田中漫无目的徘徊的巨型故障旋风构装体展开。这台古老的机器在装甲板下反复念叨着破碎的言语，在风元素离去后的几十年荒废中，它已经忘记了自己的职责。冒险者在调查该构装体时，会去请教当地果园主Aamelia 荒原，以了解它神秘的过去和曾经的看护者。",h="“What Is My...",kw={"阿梅莉亚·荒原","阿尔瓦里昂","构装体","旋风构装体","故障旋风构装体","果园","我的使命是什么?","风元素","塑风者"},ang={["class:Shaman"]="萨满祭司可能会对构装体的操作衰退产生特殊的兴趣，因为当地的记载将它的废弃和故障直接与风元素从该地区的离去联系在了一起。",["profession:Engineering"]="工程师会发现故障旋风构装体是一个有趣的古代自动化案例，并注意到尽管经过了几个世纪的磨损且完全缺乏技术维护，它的内部逻辑循环依然存在。"},sec={{t="游荡的构装体",b="在农田深处站立着一个高耸的旋风构装体，它被困在一个损坏的操作循环中，在土地上漫无目的地徘徊。那些接近这个装甲巨兽的人可以听到沉重的金属板下传出低沉、破碎的振动声，它无休止地重复着错误，并质疑着自己的基本功能。几十年的与世隔绝使这台机器失去了目标，其内部指令也被损坏或遗忘。虽然外表高大且令人生畏，但这台自动机对路人并不构成主动威胁，只是作为一个旧时代的忧郁遗迹存在，其声音已化为回荡在土壤之上的静态查询。"},{t="被遗忘的劳作与塑风者",b="当被问及这台机器时，当地居民Aamelia Windfield透露，这台自动机已经在周围的田野里游荡了几十年，似乎是从风元素离去后就开始了。一位名叫Alvarion的当地人推测，这台机器在几个世纪前，也就是这片土地被改造成果园很久之前，曾负责将丰收的作物运往遥远的集市，或是照看牲畜。在过去，一个被称为“塑风者”的群体制造并维护着这些旋风构装体。虽然果园工人们偶尔会讨论是否要请求塑风者来修理这台机器，但这事儿从来都不紧急，于是这台构装体就一直无人打扰，基本被忽视了。"}},faq={{q="什么是故障旋风构装体？",a="故障旋风构装体是一台古老的装甲自动机，在当地的田野中漫无目的地游荡。它曾经由塑风者维护，但在几十年的疏于照料下已经破败不堪。它在装甲板下无休止地重复着破碎的语音片段，质疑着自己的目的，并报告操作错误。",al={"什么是构装体","旋风构装体","田野中的巨型构装体"}},{q="谁是阿梅莉亚 荒原？",a="阿梅莉亚·荒原是住在故障构装体游荡的果园附近的一位当地居民。她掌握着关于这台机器历史的知识，她解释说，自从风元素离去后，它已经在田野里徘徊了几十年，而且它的创造者——塑风者，过去曾负责照料此类装置。",al={"阿梅莉亚·荒原","谁是阿梅莉亚","果园任务人物"}},{q="构装体最初的目的是什么？",a="构装体最初的准确用途已湮没在时间长河中。据阿梅莉亚·荒原说，一位名叫阿尔瓦里昂的居民认为，在现在的果园存在之前，它可能在几个世纪前运送过收获的作物到集市或照看牲畜，其历史甚至可能追溯到一千年前。",al={"构装体目的","构装体做了什么","构装体工作"}},{q="谁是塑风者？",a="塑风者是一个古老的群体，以制造和维护旋风构装体而闻名。在早期的时代，他们负责维修这些自动化机器，尽管当地的农场工人因为没有紧迫的危险或必要，在现代并未请求他们的协助。",al={"塑风者","谁制造了构装体","谁维护旋风构装体"}},{q="为什么构装体在重复破碎的词句？",a="构装体遭受了严重的机械或操作故障，很可能是由于风元素离去后几十年的无人维护造成的。当接近它时，它会发出诸如“功能错误”和“什么是功能”之类的脱节短语，这表明它的指令处理程序陷入了一个无法解决的质疑循环中。",al={"为什么构装体会说话","功能错误构装体","它在说什么"}},{q="为什么当地人没有修理或拆除这个构装体？",a="这个构装体对居民或他们的果园不构成威胁，只是在树木和庄稼间平静地游荡。虽然像阿梅莉亚·荒原这样的居民曾谈到要请求塑风者进行维护，但这个问题从未紧急到需要采取行动的地步，导致当地人只是对其置之不理。",al={"为什么忽视构装体","为什么不修理构装体","构装体危险吗"}},{q="谁是阿尔瓦里昂？",a="阿尔瓦里昂是阿梅莉亚·荒原提到的一位当地人，他调查过这个游荡构装体的历史。他推测这台机器最初执行的是农业劳作，要么是在周围地形被改造成果园之前，负责将采集的作物运往集市，要么是放牧牲畜。",al={"阿尔瓦里昂","谁是阿尔瓦里昂","阿尔瓦里昂的理论"}}},fp="19,220,23.373.0,35.470.0,45.276.0,25.191.0,42.187.0,24.182.0,48.216.0,60.264.0,16.201.0"}
P.entries["quest:92699"] = {n="The Supreme Magister",s="The Supreme Magister会指引刚抵达瓦拉纳尔的冒险者前往高阶会领袖Elaadrin Evengale处。该组织在定居点东南部的一座小屋内运作，他们正在寻找有能力的盟友，同时还要应对与塑风者之间的尖锐矛盾以及当地邪教带来的迫在眉睫的威胁。",h="The Supreme Magister会指引刚抵达瓦拉纳尔的冒险者前往高阶会领袖Elaadrin...",kw={"奥术","邪教","艾拉德林·暮风","高阶会","拉希里尔","至高魔导师","瓦拉纳尔","塑风者"},ang={["class:Mage"]="Elaadrin注意到奥术使用者周围散发着充满活力的奥术光辉，他珍视掌握奥术并保卫家园所需的罕见天赋与意志。"},sec={{t="瓦拉纳尔的高阶会",b="当有潜力的初来者抵达瓦拉纳尔时，他们会被指引前往高阶会。该组织由The Supreme Magister Elaadrin Evengale领导，在定居点最东南角的区域设有小屋。Elaadrin会密切关注新来者，寻找那些拥有力量、决心以及足以面对家园周边险境所需的奥术光辉之人。"},{t="敌对派系与潜伏的邪教",b="瓦拉纳尔内部的和平十分脆弱。高阶会与塑风者之间积怨已深，因此当地人警告新来者要对塑风者敬而远之，以免在街头引发暴力冲突。由于附近有危险的邪教出没，当地领导人必须避免在外部威胁迫在眉睫之时，内部先发生流血冲突。"}},faq={{q="艾拉德林·暮风是谁？",a="艾拉德林·暮风是高阶会现任的至高魔导师。他在瓦拉纳尔东南部的一座小屋内指挥组织的行动，寻找那些具备奥术天赋与决心，能够保卫家园的人。",al={"埃拉德林·暮风是谁","埃拉德林·暮风","至高魔导师是谁"}},{q="在哪里可以找到艾拉德林·暮风？",a="艾拉德林·暮风和他的追随者在瓦拉纳尔最东南方的一座小屋内运作。",al={"至高魔导师在哪里","在哪里可以找到埃拉德林·暮风","瓦拉纳尔小屋位置"}},{q="什么是高阶会？",a="高阶会是一个在至高魔导师艾拉德林·暮风领导下，在瓦拉纳尔内运作的奥术组织。尽管成员日渐减少且当地局势紧张，他们仍专注于运用奥术力量保卫家园。",al={"什么是高阶会","高阶会背景"}},{q="高阶会与塑风者之间为何存在冲突？",a="高阶会与塑风者在瓦拉纳尔有着激烈的竞争。当地领导层坚持要求双方保持距离，以防止在街头发生公开的派系暴力，特别是在邪教活动威胁到定居点安危的情况下。",al={"为什么高阶会和塑风者会战斗","塑风者冲突","瓦拉纳尔紧张局势"}},{q="拉希里尔是谁？",a="拉希里尔是一名准成员或相关人员，他通过魔法信函将有前途的冒险者指引给瓦拉纳尔的高阶会，向艾拉德林·暮风告知那些具备显著潜力的人选。",al={"拉希里尔是谁","拉希里尔的信函"}},{q="是什么邪教威胁着瓦拉纳尔？",a="一个神秘的邪教活跃在瓦拉纳尔周边，其危险性足以让当地权威部门主动压制高阶会与塑风者等团体之间的内斗，以确保定居点的安全。",al={"瓦拉纳尔有什么邪教","瓦拉纳尔邪教威胁"}}},fp="20,192,26.282.0,32.298.0,25.178.0,37.84.0,23.227.0,65.198.0,16.163.0,29.190.0"}
P.entries["quest:927"] = {n="布满苔藓的心脏",s="“布满苔藓的心脏”是从可怕的树苗怪“腐臭的黑苔”身上获取的一颗奇怪的腐化核心。这颗心脏被油腻、黑暗的苔藓所覆盖，并令人不安地自主跳动着，这引起了奥拉密斯湖的植物学家德纳兰的调查兴趣。",h="“布满苔藓的心脏”是从可怕的树苗怪“腐臭的黑苔”身上获取的一颗奇怪的腐化核心。这颗心脏被油腻、黑暗的苔藓所覆盖，并令人不安地自主跳动着，这引起了奥拉密斯湖的植物学家德纳兰的调查兴趣。",kw={"腐臭的黑苔","枯萎","腐化","德纳兰","奥拉密斯湖","布满苔藓的心脏","泰达希尔","树苗怪"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊们对这种跳动的、枯萎的心脏等异常现象非常感兴趣，他们试图诊断这种腐化是否可以被净化，或者它是否预示着更深层次的腐朽。",["profession:Herbalism"]="任何植物学研究者都能看出这颗核心上油腻的生长物完全是不自然的，它通过让一颗离体的心脏保持活力，违背了标准的植物学特征。",["race:NightElf"]="对于卡多雷来说，看着年轻的世界之树泰达希尔滋生出像“腐臭的黑苔”这样被污染且具有攻击性的树苗怪，是一个令人警醒的信号，表明他们的家园正受到蔓延病痛的困扰。"},sec={{t="跳动的心脏",b="这颗树苗怪心脏是从“腐臭的黑苔”的残骸中挖出来的，在厚厚的黑暗、油腻苔藓覆盖下几乎无法辨认。唯一能显露出其本质特征的，是即便在脱离躯体后依然保持着缓慢而有节奏的搏动。这种反常的生命力暗示了泰达希尔野生植物群中蔓延的腐化程度远比一般的腐烂更为深远。"},{t="德纳兰的研究",b="德纳兰是驻扎在奥拉密斯湖附近的一位敏锐的当地植物研究者，他立刻认出了这件文物的严峻本质。树苗怪本应是与世界之树枝干紧密相连的温和生物，但这颗心脏却展现出了一种恶毒的枯萎影响。出于好奇和担忧，德纳兰决定种植并研究这颗腐化的器官，以了解正在岛屿土壤中扎根的污秽苔藓。"}},faq={{q="“布满苔藓的心脏”来自哪里？",a="这颗心脏取自“腐臭的黑苔”，它是游荡在泰达希尔荒野中一只巨大且被严重腐化的树苗怪。",al={"心脏哪里掉落","布满苔藓的心脏掉落","腐臭的黑苔心脏"}},{q="为什么这颗心脏还在跳动？",a="侵蚀树苗怪的黑暗油腻苔藓似乎通过反常的生命力维持着它的运转。即使被从生物体上切除，心脏依然保持着缓慢而持久的律动。",al={"心脏为何跳动","仍在跳动的心脏","树苗怪心脏搏动"}},{q="德纳兰是谁？",a="德纳兰是一位暗夜精灵自然学家，在奥拉密斯湖岸边照料着一片苗圃。他致力于研究泰达希尔的植物、幼苗以及影响岛上树苗怪的蔓延腐化。",al={"德纳兰是谁","德纳兰在哪里","德纳兰位置"}},{q="德纳兰要用这颗心脏做什么？",a="德纳兰决定将这颗心脏种在一个附魔花盆中，使其发芽并隔离那些污秽的苔藓，希望能找出导致枯萎生长的根本原因。",al={"心脏会发生什么","种植心脏任务","德纳兰心脏研究"}},{q="树苗怪本应是什么样的生物？",a="树苗怪是诞生于森林的天然和平的植物元素。然而，在泰达希尔各地，黑暗力量和不自然的污秽驱使它们中的许多变得疯狂而充满攻击性。",al={"什么是树苗怪","树苗怪背景","树苗怪是邪恶的吗"}},{q="这种心脏上的腐化是魔法造成的还是自然形成的？",a="这些苔藓看起来肮脏油腻而非健康，这表明泰达希尔的原生生态遭受了非自然的枯萎感染，而非正常的荒野腐烂。",al={"苔藓是魔法吗","污秽苔藓来源","泰达希尔苔藓枯萎"}}},fp="21,166,14.241.0,21.405.0,43.120.0,31.138.0,15.184.0,36.156.0,36.158.0,50.119.0"}
P.entries["quest:92700"] = {n="The Grand Skyseer",s="The Grand Skyseer是进入瓦拉纳尔核心地带的入门之旅，指引旅行者前往塑风者旅店拜访Ayessa Dawnsinger。随着当地各派系之间的紧张局势不断升温，加之一个阴暗的教派威胁着该地区，塑风者们急切地寻找那些拥有灵视天赋的人。",h="The Grand Skyseer是进入瓦拉纳尔核心地带的入门之旅，指引旅行者前往塑风者旅店拜访Ayessa...",kw={"艾耶莎·晨歌","琥珀之风长者是谁","高阶会","申达尔村","灵视","大天空先知","瓦拉纳尔","塑风者","泽弗拉斯"},ang={["class:Druid"]="那些对灵魂光环和大自然无形流动敏感的人，会在塑风者中找到志同道合的哲学理念，他们观察着天空中细微的变化。",["class:Shaman"]="Ayessa Dawnsinger能立即认出那些与灵魂产生共鸣并拥有精神天赋的旅行者，这使得塑风者成为那些与元素力量调和的萨满祭司的重要联络点。"},sec={{t="抵达瓦拉纳尔",b="抵达瓦拉纳尔镇后，旅行者会被指引前往中央旅店，那里是塑风者在The Grand Skyseer Ayessa Dawnsinger的领导下集会的地方。由于在申达尔村的卓越事迹引起了Elder Amberwind的注意，新来者受到了那些与灵魂调和之人的欢迎。然而，瓦拉纳尔仍然充满内忧外患，要求新来者谨慎地处理当地脆弱的政治关系。"},{t="竞争与潜伏的教派",b="瓦拉纳尔的和平十分脆弱。塑风者与高阶会之间保持着公开的敌意，各派系在街头的冲突威胁着定居点的稳定。随着一个阴暗的教派在地区内积极活动，当地领袖已下令双方保持距离，将对抗共同敌人的生存需求置于痛苦的领土纷争之上。"},{t="日渐衰微的灵视",b="The Grand Skyseer Ayessa Dawnsinger观察到，被称为灵视的灵魂感知能力在Zephras的人民中正变得越来越罕见。那些展现出强大光环和灵魂和谐的人被视为至关重要的盟友，塑风者急需他们的帮助来度过这片土地所面临的艰难时期。"}},faq={{q="谁是大观天者？",a="大观天者就是艾耶莎·晨歌，她是瓦拉纳尔塑风者中一位杰出的精神领袖。她在定居点中心附近的旅店开展工作，接待那些与灵魂产生共鸣并拥有稀有天赋“灵视”的旅行者。",al={"谁是大观天者","艾耶莎·黎明歌唱者是谁","艾耶莎是谁"}},{q="在哪里可以找到艾耶莎·晨歌？",a="艾耶莎·晨歌居住在位于瓦拉纳尔定居点中心附近的塑风者旅店。她正在等待从申达尔村赶来的旅行者，这些旅行者会带来琥珀风长者关于近期事迹的消息。",al={"去哪里找艾耶莎·黎明歌唱者","大观天者的旅店在哪里","艾耶莎在瓦拉纳尔的位置"}},{q="谁是塑风者？",a="塑风者是一个存在于瓦拉纳尔的精神集体，在当地由大观天者艾耶莎·晨歌领导。他们的成员研究天空并与灵魂交流，尽管他们目前与另一个名为高阶会的当地组织处于尖锐的对立状态。",al={"什么是塑风者","瓦拉纳尔的塑风者派系"}},{q="为什么塑风者会与高阶会发生冲突？",a="这两个组织在风之灵魂的问题上产生了分歧。高阶会开始警惕灵魂的动机，并希望亲自探究天空之墙的力量，而塑风者则信任元素，并将这种质疑视为一种冒犯。这种摩擦非常深，以至于在瓦拉纳尔街头的派系暴力行为是不可容忍的，尤其是考虑到该地区正受到教派的威胁。",al={"塑风者与高阶会的冲突","为什么高阶会会对塑风者不满","瓦拉纳尔的高阶会"}},{q="什么是灵视天赋？",a="灵视是泽风极少数人拥有的一种罕见精神感知能力，使他们能够感知灵魂光环并与不可见的力量交流。艾耶莎·晨歌指出，最近拥有这种天赋的人越来越少，这使得拥有灵视的人对于度过当前的困境至关重要。",al={"什么是灵视","泽弗拉斯的灵视天赋"}},{q="谁是琥珀风长者？",a="琥珀风长者是驻扎在申达尔村的一位受人尊敬的长者，负责评估旅行者，并将关于他们事迹和灵魂共鸣的消息提前传达给瓦拉纳尔，从而将值得信赖的人引荐给大观天者艾耶莎·晨歌。",al={"谁是琥珀风长者","琥珀风与申达尔村"}}},fp="17,185,19.340.0,27.313.0,19.244.0,25.226.0,37.185.0,24.199.0,49.292.0,29.232.0,23.222.0"}
P.entries["quest:92701"] = {n="To Valanaar",s="“To Valanaar”是一个运送任务，旨在将来自Shen'dar村庄的紧急消息传达给瓦拉纳尔的维和者驻军。这标志着岛上局势的重大升级，提醒Valennia Stormfist指挥官，维和者已无法避免与迅速扩张的邪教发生正面冲突。",h="“To Valanaar”是一个运送任务，旨在将来自Shen'dar村庄的紧急消息传达给瓦拉纳尔的维和者驻军。这标志着岛上局势的重大升级，提醒Valennia...",kw={"奥恩达","邪教","维和者","塔架","申达尔","前往瓦拉纳尔","瓦拉纳尔","瓦伦妮娅·风暴之拳"},sec={{t="来自Shen'dar的快讯",b="在保卫了Shen'dar村庄及其关键塔架后，高地人Aonda派遣了一名可信的信使横穿岛屿。目的地是位于岛屿东南边缘的定居点瓦拉纳尔，当地维和者指挥官必须在那里得到关于邪教迅速扩张的警告。"},{t="风暴将至",b="一段时间以来，在Valennia Stormfist领导下的维和者一直试图避免与侵入岛屿的神秘邪教发生公开冲突。然而，Shen'dar发生的事件标志着一个转折点。随着邪教势力的激增，Valennia不得不承认避战的时代已经结束，她那支日益缩减的维和者队伍必须为即将到来的袭击守卫瓦拉纳尔。"}},faq={{q="瓦伦妮娅·风暴之拳是谁？",a="瓦伦妮娅·风暴之拳是驻扎在岛上的维和者指挥官，在瓦拉纳尔定居点开展行动。她负责保护当地居民，但随着该地区邪教活动的升级，她发现自己手下的小规模驻军已捉襟见肘。",al={"瓦伦妮娅·风暴之拳是谁","瓦伦妮娅","维和者领袖"}},{q="奥恩达是谁？",a="奥恩达是一位驻扎在申达尔村庄的机敏高地人。在成功保卫了当地一座塔架并抵御了邪教徒的入侵后，她委托旅行者将她的书面报告送往岛上的瓦伦妮娅处。",al={"谁发送了报告","机敏的高地人","奥恩达"}},{q="什么是瓦拉纳尔？",a="瓦拉纳尔是位于岛屿东南边缘的一个定居点。它是瓦伦妮娅·风暴之拳和当地维和者的主要基地，也是岛上居民的防御堡垒。",al={"什么是瓦拉纳尔","瓦拉纳尔在哪里","瓦拉纳尔位置"}},{q="威胁岛屿的邪教是什么？",a="岛屿正面临着一个迅速增长的邪教威胁，该邪教已经开始侵入当地的定居点和神圣的塔架。虽然维和者此前避免正面冲突，但邪教的扩张现在迫使瓦拉纳尔及其守卫者为不可避免的战斗做好准备。",al={"什么邪教","谁在攻击","邪教扩张"}},{q="什么是申达尔？",a="申达尔是位于岛上一座重要塔架附近的村庄。在最近击退了邪教徒的攻击以确保村庄和塔架的安全后，其领导层与驻扎在瓦拉纳尔的维和者部队保持着密切联系。",al={"什么是申达尔","申达尔","塔架村庄"}},{q="奥恩达的报告里包含什么内容？",a="这份书面报告详细记录了围绕保卫申达尔及其塔架的近期事件，并警告瓦伦妮娅，邪教领土的迅速扩张意味着直接冲突已无法避免。",al={"奥恩达的报告里有什么","书面报告内容","信里说了什么"}}},fp="11,154,22.249.0,19.303.0,26.173.0,13.170.0,17.143.0,40.200.0,17.194.0,36.162.0"}
P.entries["quest:92703"] = {n="Deliver the News",s="Deliver the News 是一项任务，为天空之墙的风野果园的困境画上了句号。在帮助 Aamelia 守住农场后，The Adventurer 前往瓦拉纳尔，向焦虑的 Alvarion Windfield 传达他们平安的消息。",h="Deliver the News 是一项任务，为天空之墙的风野果园的困境画上了句号。在帮助 Aamelia 守住农场后，The Adventurer 前往瓦拉纳尔，向焦虑的 Alvarion Windfield...",kw={"阿梅莉亚","阿尔瓦里昂·荒原","构造体","传递消息","果园","天空之墙","瓦拉纳尔","荒原","塑风者"},ang={["race:Skyborne"]="Alvarion 讲述了在族人抵达天空之墙前故事里的真正英雄，提醒天裔冒险者们在迁移之前的根源和文化遗产。"},sec={{t="果园的慰藉",b="Deliver the News 标志着风野果园一场磨难的终结。在挺身而出将农场从迫在眉睫的危机中拯救出来后，The Adventurer 收到了 Aamelia 的诚挚感谢，她已准备好将危险抛诸脑后。随着果园转危为安，当务之急变成了安抚 Alvarion Windfield，他此前逃往瓦拉纳尔定居点寻求援助。"},{t="未来的秘密",b="在送旅行者前往瓦拉纳尔之前，Aamelia 要求 Alvarion 在康复后招募一位熟练的 windshaper。果园里还留有一个构造体，她希望专家能对其进行彻底检查，以确保它不会造成任何威胁。她还分享了一个温柔的秘密：她怀孕了，她希望在 Alvarion 安全到家之前，先对他隐瞒这个消息。"},{t="瓦拉纳尔的英雄",b="在瓦拉纳尔，Alvarion Windfield 得知家人和家园平安的消息后，情绪激动不已。他离开前往城市时，以为寻找帮助只是一种绝望而近乎徒劳的希望，而旅行者的成功让他想起了在族人抵达天空之墙前就已传颂的传奇英雄。随着家园获救，荒原一家向他们的救命恩人表示了永恒的欢迎。"}},faq={{q="什么是 传递消息 任务？",a="传递消息 是在解决风野果园的危机后由 阿梅莉娅 给予的一项任务。她请求 冒险者 前往瓦拉纳尔城，告知她的伴侣 阿尔瓦里昂·荒原 危险已经过去，她很安全。",al={"传递消息 任务","什么是 传递消息","谁发布 传递消息"}},{q="阿尔瓦里昂·荒原 是谁？",a="阿尔瓦里昂·荒原 是天空之墙的居民，目前正在瓦拉纳尔休养。他前往城市是为了寻求帮助以解决家族果园的麻烦，在遇到玩家之前，他担心一切希望都已破灭。",al={"阿尔瓦里昂·荒原 是谁","阿尔瓦里昂 在哪里","阿尔瓦里昂 位置"}},{q="阿梅莉娅 是谁？",a="阿梅莉娅 是风野家园的居民，与 阿尔瓦里昂 一起照料果园。她对玩家的介入心存感激，便委托他们将成功的消息带给身在瓦拉纳尔的 阿尔瓦里昂。",al={"阿梅莉亚 是谁","任务发布者 阿梅莉亚"}},{q="阿梅莉娅 对 阿尔瓦里昂 隐瞒了什么秘密？",a="阿梅莉娅 静静地向 冒险者 透露她怀孕了，她轻轻抚摸着自己的肚子，请求在 阿尔瓦里昂 康复并回家之前，对此消息保密。",al={"阿梅莉亚 的秘密是什么","阿梅莉亚 抚摸肚子","阿梅莉亚 怀孕了吗"}},{q="为什么 阿梅莉娅 想要带一名 塑风者 到果园？",a="阿梅莉娅 希望 阿尔瓦里昂 在康复后能带一名 塑风者 回到果园。她希望这位专家能检查房产上的一个构造体，以确保它对他们日益壮大的家庭不会构成任何危险。",al={"为什么需要 塑风者 构造体","阿梅莉亚 提到了什么构造体","荒原 构造体"}},{q="这个任务发生在什么地方？",a="该任务连接了风野果园和瓦拉纳尔定居点，它们位于天空之墙的元素位面，这些定居者在那里安了家。",al={"传递消息 在哪里进行","瓦拉纳尔 天空之墙 任务"}}},fp="16,125,21.196.0,23.287.1,18.337.0,35.135.0,26.168.0,15.161.0,44.134.0,58.181.0,33.126.0"}
P.entries["quest:92706"] = {n="WANTED: Bruuz",s="WANTED: Bruuz 是加兹鲁维在棘齿城这一地精港口发布的赏金任务。一条巨大的掠食性鲨鱼在港口码头附近安了家，威胁着海上交通和沿海贸易，直到有人能终结它为止。",h="WANTED: Bruuz 是加兹鲁维在棘齿城这一地精港口发布的赏金任务。一条巨大的掠食性鲨鱼在港口码头附近安了家，威胁着海上交通和沿海贸易，直到有人能终结它为止。",kw={"贫瘠之地","赏金","布鲁兹","背鳍","加兹鲁维","棘齿城","鲨鱼","热砂港"},ang={["class:Hunter"]="击败像 Bruuz 这样的水下顶级掠食者是对耐心和准头的独特考验。",["profession:Cooking"]="虽然加兹鲁维只关心背鳍作为击杀证明，但像 Bruuz 这样体型的鲨鱼对于有商业头脑的厨师来说，代表着堆积如山的新鲜沿海肉类。"},sec={{t="港湾之患",b="棘齿城依靠商船航运繁荣发展，是连接卡利姆多和东部王国的主要中立门户。稳定的商业往来使得码头周围的水域繁忙而混乱，但最近它引来了一位更加危险的访客。一条被惊恐的码头工人戏称为“Bruuz”的巨大鲨鱼开始在海湾徘徊。这头野兽没有待在深水区，而是频繁袭击小艇、当地水手和卸载的货物，扰乱了港口的运营。"},{t="加兹鲁维的赏金",b="加兹鲁维无法承受船只因害怕被海洋生物伤害而避开他的港口。因此，他发布了一则公开的悬赏令，呼吁所有垂钓者，并承诺提供丰厚的报酬。要领取奖励，猎人必须杀死 Bruuz 并带回这头掠食者的背鳍作为任务证明。"}},faq={{q="布鲁兹 是谁？",a="布鲁兹 是一条以体型巨大、性格凶猛而闻名的鲨鱼，它在棘齿城的航运码头附近占据了狩猎场。在发生多起针对水手和小船的袭击事件后，码头工人们给这头怪物起了这个绰号。",al={"什么是 布鲁兹","布鲁兹 鲨鱼","布鲁兹 鲨鱼是谁"}},{q="加兹鲁维为什么要悬赏 布鲁兹？",a="布鲁兹 扰乱了维持棘齿城经济的海上交通。加兹鲁维依靠稳定的贸易和运作正常的码头，因此一条骚扰水手、破坏船只的巨型鲨鱼严重损害了商业利益，足以让他为杀死这头野兽悬赏现金。",al={"为什么要杀 布鲁兹","加兹鲁维鲨鱼任务","为什么要 布鲁兹 的鳍"}},{q="布鲁兹 通常在哪里出没？",a="布鲁兹 在贫瘠之地棘齿城沿岸的水域潜行，经常在主航运码头和港口入口附近游弋。",al={"布鲁兹 位置","布鲁兹 在哪","找到 布鲁兹"}},{q="加兹鲁维要求什么样的击杀证明？",a="加兹鲁维要求以 布鲁兹 的背鳍作为这头巨型掠食者确实已被杀死的实物证据，才会支付赏金。",al={"布鲁兹 任务提交","给加兹鲁维带什么","布鲁兹 的背鳍"}},{q="联盟和部落的冒险者都能接取这个赏金任务吗？",a="是的。棘齿城在热砂港的中立管理下运营，这意味着加兹鲁维欢迎任何来自任一派系、有能力潜入水中并解决鲨鱼问题的冒险者。",al={"通缉: 布鲁兹 是中立任务吗","部落可以做 通缉: 布鲁兹 吗","联盟可以做 布鲁兹 任务吗"}},{q="为什么悬赏令特别点名要求垂钓者？",a="告示上没写原因。它只是以“召集所有垂钓者！”开头，并承诺给任何带回鲨鱼鳍的人丰厚的报酬。",al={"召集所有垂钓者 布鲁兹","这是钓鱼任务吗"}}},fp="13,145,19.347.0,16.231.0,13.141.0,39.144.0,29.107.0,45.101.0,57.140.0,50.139.0"}
P.entries["quest:92708"] = {n="A Grand Adventure",s="A Grand Adventure标志着天空之墙内部泽风岛危机的转折点。在Ayessa Dawnsinger和塑风者的领导下，该任务概述了一个大胆的计划：通过前往艾泽拉斯的凡人领域，为他们的家园寻求拯救。",h="A Grand Adventure标志着天空之墙内部泽风岛危机的转折点。在Ayessa Dawnsinger和塑风者的领导下，该任务概述了一个大胆的计划：通过前往艾泽拉斯的凡人领域，为他们的家园寻求拯救。",kw={"宏大的冒险","艾耶莎·晨歌","艾泽拉斯","天空之墙","风之灵","塑风者","泽风岛"},ang={["race:Skyborne"]="对于天空之墙的空裔来说，这代表着观念上的重大转变：离开他们家园的元素领域，前往艾泽拉斯，为泽风岛寻找救赎。"},sec={{t="泽风岛的危机",b="泽风岛正面临日益严重的危机，因为风之灵已莫名消失。作为回应，塑风者一直在调查这些干扰，揭开了关于失踪同胞以及他们元素家园命运的意想不到的真相。Ayessa Dawnsinger正在寻找有能力的冒险者来倾听他们的发现，并为一项前所未有的任务做好准备。"},{t="天空之墙之外的冒险",b="在吐露了她的发现后，Ayessa Dawnsinger揭示了一个大胆而不同寻常的结论：单凭天空之墙本身，并没有拯救泽风岛所需的力量或知识。相反，救赎存在于下方的艾泽拉斯凡人世界。冒险走出他们的家园代表着对传统的背离，需要冒险者踏入未知的领域，以确保岛屿的未来。"}},faq={{q="任务“一场伟大的冒险”是什么？",a="“一场伟大的冒险”是艾耶莎·晨歌在泽风岛发布的一项关键任务。在任务中，她分享了塑风者的结论，即拯救他们的家园需要走出天空之墙，进入艾泽拉斯世界。",al={"这是什么任务","伟大的冒险任务","什么是伟大的冒险"}},{q="艾耶莎·晨歌是谁？",a="艾耶莎·晨歌是泽风岛塑风者的核心成员，她正在调查岛屿面临的危机，并提议从艾泽拉斯寻求帮助和力量。",al={"艾耶莎是谁","晨歌","艾耶莎·晨歌是谁"}},{q="泽风岛正在发生什么危机？",a="泽风岛正遭受严重的危机，涉及风之灵的失踪。塑风者一直在调查它们的消失，以寻找拯救家园的方法。",al={"什么是泽风岛危机","泽风岛发生了什么","泽风岛的问题"}},{q="谁是塑风者？",a="塑风者是泽风岛上的一个组织，致力于调查和解决威胁该岛的元素干扰和风之灵失踪事件。",al={"谁是塑风者","塑风者泽风岛"}},{q="为什么塑风者需要前往艾泽拉斯？",a="艾耶莎·晨歌认为，解决泽风岛危机所需的知识、潜力和力量无法仅在天空之墙内找到，必须在下方的艾泽拉斯世界中去寻求。",al={"为什么要去艾泽拉斯","为什么离开天空之墙","救赎之路"}},{q="什么是天空之墙？",a="天空之墙是塑风者和泽风岛的元素家园，位于艾泽拉斯凡人世界的上方。",al={"什么是天空之墙","天空之墙在哪里"}}},fp="17,165,26.318.0,24.283.1,36.158.0,25.150.0,44.145.0,24.95.0,49.142.0,16.107.0"}
P.entries["quest:92709"] = {n="A Grand Adventure",s="Elaadrin Evengale请你在瓦拉纳尔听取高阶会的计划。重寻古老魔法，关系到泽风岛的未来。",h="Elaadrin Evengale请你在瓦拉纳尔听取高阶会的计划。重寻古老魔法，关系到泽风岛的未来。",kw={"宏大的冒险","古老魔法","艾拉德林·暮风","高阶会","上层精灵","肯瑞托","瓦拉纳尔","泽风岛"},sec={{t="失落的传承",b="Elaadrin谈起你的上层精灵血统，以及那些或许能帮助拯救家园的年轻人。高阶会正寻求重获先祖的古老魔法，以及数千年来失落的一切。"},{t="前方之路",b="Elaadrin说，艾泽拉斯是这场探寻的关键，肯瑞托将为高阶会指引道路。成员们正准备离开，你可以和瓦拉纳尔的其他人谈谈，他们中许多人需要协助完成手头的工作。"}},faq={{q="是谁请我听听？",a="瓦拉纳尔的艾拉德林·暮风请你听取高阶会的计划。",al={"谁是埃拉德林","埃拉德林·晚风","谁想交谈"}},{q="高阶会想要重寻什么？",a="高阶会正寻求重获先祖的古老魔法，以及数千年来失落的一切。",al={"他们在寻找什么","古老魔法","高阶会计划"}},{q="高阶会为何寻求古老魔法？",a="艾拉德林说，重寻古老魔法是揭开泽风岛秘密、确保其未来的关键。",al={"为何要古老魔法","拯救泽风岛","岛屿未来"}},{q="谁会为他们指引道路？",a="艾拉德林说，肯瑞托将为高阶会指引道路。",al={"肯瑞托","谁为他们指引","艾泽拉斯计划"}},{q="他们准备离开时，我能做什么？",a="你可以去看看瓦拉纳尔的其他高阶会成员；他们大多有需要你帮忙的事。",al={"在瓦拉纳尔帮忙","其他高阶会成员","接下来做什么"}}},fp="17,139,15.193.0,13.195.1,27.72.0,44.90.0,43.111.0,27.61.0,42.124.0"}
P.entries["quest:92727"] = {n="The Missing Scholar",s="“The Missing Scholar”讲述了来自高阶会的学者菲利恩·焰风失踪的故事，他被派往Zephras研究大气魔法。追踪他沿瓦拉纳尔和申达尔高地之间道路的足迹，揭示了在这座岛屿上进行学术考察的危险性。",h="“The Missing Scholar”讲述了来自高阶会的学者菲利恩·焰风失踪的故事，他被派往Zephras研究大气魔法。追踪他沿瓦拉纳尔和申达尔高地之间道路的足迹，揭示了在这座岛屿上进行学术考察的危险性。",kw={"血迹斑斑的挎包","菲利恩·焰风","高阶会","申达尔高地","失踪的学者","瓦拉纳尔","风载魔法","泽弗拉斯"},ang={["class:Mage"]="调查Zephras自然异常现象的法师们与焰风一样，对聚集在高地的风载奥术流充满好奇。",["race:Skyborne"]="Zephras的风和大气魔法是天空之子（天裔）最关心的课题，尽管该地形隐藏的危险对学者来说也是致命的。"},sec={{t="高阶会的任务",b="追求知识是学术组织高阶会的核心使命，但在Zephras各地进行学术实地考察已变得危机四伏。当学者菲利恩·焰风出发前往申达尔高地研究大气奥术现象时，他没能按时报告，这引发了同僚们的担忧，他们担心沿途的危险已经危及了他的生命。"},{t="西路上的痕迹",b="焰风从瓦拉纳尔定居点出发向西行进，冒险前往申达尔高地的崎岖地带，以收集关于聚集在山峰间随风飘散的魔法的经验数据。他在旅途中失踪了。对旅行路线的搜寻只发现了被遗弃在泥土中的个人挎包，上面沾有干涸的血迹，这让他最终的生存状况变得岌岌可危。"}},faq={{q="菲利恩·焰风是谁？",a="菲利恩·焰风是一位隶属于泽风岛高阶会的学者。他被派往申达尔高地调查聚集在那里的神秘风载魔法，随后在道路上神秘失踪。",al={"菲利恩·焰风是谁","菲利恩·焰风背景故事","失踪的学者是谁"}},{q="菲利恩·焰风发生了什么事？",a="菲利恩从未到达目的地。在通往申达尔高地的西路上，只留下了他被丢弃的挎包，上面绣着名字，还有不祥的干涸血迹，表明他遭到了伏击或袭击。",al={"菲利恩发生了什么","菲利恩死了吗","菲利恩·焰风的命运"}},{q="高阶会是什么？",a="高阶会致力于在泽风岛各地收集和保护知识。尽管有学术使命在身，但由于狂野的魔法现象和道路威胁，在岛上开展工作已变得越来越危险。",al={"高阶会使命","高阶会做什么","高阶会 泽弗拉斯"}},{q="为什么菲利恩要去申达尔高地？",a="焰风前往申达尔高地是为了记录和收集关于在该高地部分地区聚集和流动的异常风载魔法的数据。",al={"菲利恩要去哪里","风魔法 申达尔","他为什么去高地"}},{q="菲利恩·焰风最后一次出现是在哪里？",a="这位学者的血迹斑斑的挎包位于从瓦拉纳尔出发向西通往申达尔高地的道路上。",al={"挎包在哪里","菲利恩挎包位置","从瓦拉纳尔出发的道路"}},{q="申达尔高地的风载魔法是什么？",a="风载魔法是指自然聚集在泽风岛特定高海拔地区的大气奥术流，特别是在申达尔高地，这使它们成为奥术研究的主要课题。",al={"泽弗拉斯的风载魔法是什么","高地风魔法"}}},fp="19,224,24.308.0,26.321.1,27.158.0,37.214.0,23.152.0,53.139.0,40.129.0,54.177.0"}
P.entries["quest:92741"] = {n="Unwelcome Visitors",s="Unwelcome Visitors是瓦拉纳尔的一项任务，由高阶会的伊阿达莉亚·苦风（Iaadaria Bitterwind）委托。影风森林中尖啸幼兽（shriekling）的数量激增，不仅造成了巨大危害，还威胁要蔓延到周边地区。冒险者需要深入这片禁区，清理这些野兽并收集它们的尖啸幼兽的利爪，以用于学术和炼金研究。",h="Unwelcome Visitors是瓦拉纳尔的一项任务，由高阶会的伊阿达莉亚·苦风（Iaadaria...",kw={"炼金特性","伊阿达莉亚·苦风","影风森林","尖啸幼兽","尖啸幼兽的利爪","高阶会","不速之客","瓦拉纳尔"},ang={["class:Druid"]="尖啸幼兽突如其来的数量爆发和领地扩张，标志着影风森林出现了生态紊乱，需要迅速干预以恢复自然平衡。",["class:Hunter"]="猎人非常适合追踪并减少影风森林中泛滥的尖啸幼兽，他们承担起了高阶会所鄙夷的守林人和捕兽人的职责。"},sec={{t="尖啸幼兽的激增",b="影风森林长期以来一直被视为一片禁止普通冒险者进入的危险区域。然而最近，这个界限开始变得模糊。森林中原生的尖啸幼兽数量出现了前所未有的激增，将这些生物推向了外围，威胁着要将它们的狩猎范围扩张到林冠之外。如果不加遏制，这些掠食性野兽就有可能侵入定居点和交通要道，将这片隐蔽的威胁变成周边地区切实存在的危险。"},{t="学术性清理",b="在瓦拉纳尔，高阶会的伊阿达莉亚·苦风意识到了这次虫害所带来的危险与科研机遇。虽然高阶会通常不屑于从事琐碎的虫害防治工作，也不愿充当普通的捕兽人，但尖啸幼兽的利爪所蕴含的独特炼金特性使得这次例外变得物有所值。通过雇佣经验丰富的冒险者深入影风森林并带回八只利爪，高阶会不仅为社区提供了必要的保护，还为他们的学术研究获取了稀有的生物试剂。"}},faq={{q="谁发布了不速之客任务？",a="不速之客由高阶会的研究员伊阿达莉亚·苦风发布，她驻扎在瓦拉纳尔。她委托有能力的旅行者在附近的荒野中猎杀尖啸幼兽，为她的炼金研究收集材料。",al={"谁发布了不速之客","不速之客任务发布者","在哪里接取不速之客"}},{q="高阶会对尖啸幼兽有什么兴趣？",a="虽然高阶会通常认为捕猎和虫害防治有失身份，但伊阿达莉亚·苦风从中看到了学术收获的契机。尖啸幼兽的利爪具有独特的炼金特性，这让高阶会能够打着为地区提供社区服务的幌子，去研究宝贵的试剂。",al={"为什么高阶会想要利爪","高阶会 尖啸幼兽","伊阿达莉亚·苦风的动机"}},{q="为什么要清理尖啸幼兽的数量？",a="近几个月来，栖息在影风森林里的尖啸幼兽数量呈爆发式增长。随着数量的增加，这些野兽开始侵入森林之外的常规领地。如果不积极加以遏制，它们极有可能对邻近地区构成迫在眉睫的威胁。",al={"为什么要猎杀尖啸幼兽","尖啸幼兽的威胁","为什么尖啸幼兽是个问题"}},{q="影风森林在哪里？",a="影风森林是一片坐落在瓦拉纳尔附近的险恶林地。众所周知，这片森林非常危险，由于其中潜藏着凶猛的野生动物，通常被划为禁止普通旅行者和缺乏经验的冒险者进入的区域。",al={"影风森林在哪里","影风森林位置","如何前往影风森林"}},{q="什么是尖啸幼兽？",a="尖啸幼兽是影风森林原生的一种凶猛掠食性野兽。这些生物长有锋利且具有炼金效力的爪子，近几个月来数量激增，表现出极强的侵略性，甚至突破了森林的边界，威胁到栖息地之外的土地。",al={"什么是尖啸幼兽","尖啸幼兽背景故事","尖啸幼兽是什么样的野兽"}},{q="完成不速之客需要什么物品？",a="承担不速之客任务的冒险者必须深入影风森林的险恶深处，猎杀泛滥的野兽，并寻回八只尖啸幼兽的利爪。这些战利品将直接交给瓦拉纳尔的伊阿达莉亚·苦风，以协助她的学术和炼金研究。",al={"不速之客任务目标","完成不速之客需要什么","需要尖啸幼兽的利爪"}},{q="为什么影风森林禁止普通冒险者进入？",a="由于致命的野生动物和凶险的环境，影风森林被认为极其危险，并被正式列为禁止普通冒险者进入的区域。只有那些做好了应对严重危险准备的人，比如受雇清理泛滥成灾的尖啸幼兽的人，才敢涉足这片森林。",al={"为什么影风森林是禁区","影风森林的危险","任何人都可以进入影风森林吗"}}},fp="18,160,20.339.0,17.417.0,39.185.0,53.263.0,45.190.0,35.171.0,21.215.0,55.162.0,58.217.0"}
P.entries["quest:92742"] = {n="Testing the Wells",s="Testing the Wells是一项由阿尔芭·月痕委派的调查任务，旨在查明在西部荒野土壤中蔓延的毒素源头。冒险者们将携带取样工具，前往贾森农场和摩尔森农场的水井采集地下水样本。",h="Testing the Wells是一项由阿尔芭·月痕委派的调查任务，旨在查明在西部荒野土壤中蔓延的毒素源头。冒险者们将携带取样工具，前往贾森农场和摩尔森农场的水井采集地下水样本。",kw={"阿尔芭·月痕","地下水","贾森农场","摩尔森农场","毒素","检测水井","水样","西部荒野"},ang={["class:Druid"]="通过土壤和新鲜地下水渗出的反常毒素，预示着土地平衡遭到了严重的创伤，必须加以补救。",["faction:Alliance"]="恢复西部荒野的粮食生产对于暴风城的生存至关重要，因此，这些农场水井的健康状况关乎整个王国的安危。"},sec={{t="含水层中的枯萎病",b="西部荒野那广阔的平原历经了严重的忽视与匪患，但如今，地表下潜藏的阴险污染正威胁着此地仅存的农业。为了弄清农田是如何被污染的，阿尔芭·月痕指示调查员们直接对地下水进行检测。通过从定居的农场中提取水样，调查员们希望能识别出正在侵蚀该地区土壤与生物的毒素本质。"},{t="边境农场",b="这项调查聚焦于两个关键地点：贾森农场和摩尔森农场。这两处地块都坐落在散落的宅基地中，极易受到游荡的迪菲亚强盗和野生野兽的侵害。从它们的井口提取样本，可以为判断这种枯萎病原体是自然产生的、魔法诱发的，还是被蓄意投放到滋养该地区的地下水层中提供基准依据。"}},faq={{q="测试水井的目的是什么？",a="阿尔芭·月痕试图揭开困扰西部荒野的毒素源头及其成分。从农场水井采集新鲜的地下水样本，可以为分析污染情况提供所需的原材料。",al={"为什么要测试水井","测试水井的目标","这个任务是为了什么"}},{q="是谁指派了这项任务？",a="这项任务由阿尔芭·月痕发布，她正在调查困扰西部荒野农耕地带的蔓延腐化与反常毒素。",al={"谁发布了检测水井","阿尔芭·月痕的任务","任务发布者"}},{q="需要采集哪些地点的样本？",a="必须从西部荒野的贾森农场和摩尔森农场的正常运作的水井中提取水样。",al={"我该去哪里","哪些水井","水井位置"}},{q="是什么在威胁西部荒野的水源和土壤？",a="一种不明的枯萎病或毒素正在积极地腐蚀这片土地。检测当地的井水是评估当地宅基地下的含水层是否受到破坏的第一步。",al={"为什么西部荒野被污染了","什么在污染土地","毒素来源"}},{q="这种污染是自然的还是人为的？",a="这仍是调查的核心问题。来自贾森农场和摩尔森农场的样本旨在揭示这种腐烂究竟源于自然产生的地下水污染，还是蓄意的破坏行为。",al={"水源是否被蓄意投毒","谁污染了水井"}},{q="为什么要重点关注贾森农场和摩尔森农场？",a="这两个宅基地代表了平原上已建立的、汲取地下水层的民用水井，这使它们成为了测试腐化范围究竟有多广的最佳采样点。",al={"为什么要选贾森和摩尔森农场","为什么是这些农场"}}},fx={["40e3ab69"]={q="阿尔巴·皎月为什么要做这件事？",a="阿尔巴·皎月正在查明侵蚀西部荒野土壤和地下水的毒素究竟来自何处，又有何具体性质。她希望直接分析仍在耕作的农庄井水，赶在污染蔓延到无法挽回之前，查明究竟是什么在荼毒这片土地。",al={"阿尔芭为何需要水样","阿尔芭·皎月的动机","为何检测井水"}},d6dffc38={q="贾森农场水样有什么用？",a="这份样本为阿尔芭·皎月提供了直接取自贾森农场的地下水。将其与其他农场的样本一同检验，她就能查明疫病是否正渗入西部荒野各处的深层地下含水层，还是源于某一处局部污染源的泄漏。",al={"贾森农场水样的用途","为何取贾森农场的水","贾森农场样本的作用"}},fcb7e3cb={q="摩尔森农场水样 有什么用途？",a="这份水样取自摩尔森农场的水井，能让 阿尔芭·皎月 检测西部荒野各片农田受到污染的程度。将它的纯净程度与当地其他水井的水样进行比较，有助于她判断毒素扩散的路径和强度。",al={"摩尔森农场水样 用途","为什么采集摩尔森农场水样","摩尔森农场井水用途"}}},fp="17,131,21.270.0,21.268.0,41.155.0,22.110.0,35.65.0,46.164.0,43.167.0,42.182.0"}
P.entries["quest:92744"] = {n="Murloc Gills",s="Murloc Gills是Alba Fairmoon在西部荒野发布的一项联盟任务。由于担心作物枯萎病可能会污染沿海渔场，探险者们被派往长滩收集Murloc Gills以进行生态分析。由于鱼人的生理机能对海洋污染物极其敏感，它们的鳃可以揭示毒素是否已经渗入海洋。",h="Murloc Gills是Alba Fairmoon在西部荒野发布的一项联盟任务。由于担心作物枯萎病可能会污染沿海渔场，探险者们被派往长滩收集Murloc...",kw={"阿尔巴·皎月","枯萎病","饥荒","长滩","鱼人的鳃","海水","暴风城","毒素","西部荒野"},ang={["class:Druid"]="内陆枯萎病蔓延至沿海生态系统，威胁着腐化当地野生动物，这使得对鱼人等指标物种进行生物监测成为了一项必要的保障措施。",["faction:Alliance"]="由于瓦里安国王失踪，粮食短缺已经引发了动荡，保护西部荒野剩余的食物供应对于保持暴风城的稳定至关重要。",["race:Human"]="对于暴风城的人民来说，西部荒野的衰败直接威胁着他们的家园、农田和餐桌的生存。"},sec={{t="沿海地区的威胁",b="由于大范围的作物歉收、流离失所的农民和强盗横行，西部荒野已濒临崩溃。Alba Fairmoon担心会有更致命的情况发生：困扰内陆作物的腐化已经开始流入无尽之海。如果西部荒野的沿海水域受到污染，那些养活平民并供应暴风城餐桌的鱼类资源可能会彻底消失，使这个处境艰难的王国陷入彻底的饥荒。"},{t="水质的哨兵",b="虽然鱼人以顽固和暴力著称，但它们的两栖生物特性使它们成为天然的生物指标。鱼人的呼吸系统会不断过滤海水，这使得它们的鳃组织对外部毒素、枯萎病和非自然污染物极其敏感。通过研究从长滩徘徊的潮汐居民身上新鲜获取的鳃，Fairmoon希望能够测定入侵污染的准确严重程度。"}},faq={{q="阿尔芭·皎月为什么要收集鱼人的鳃？",a="阿尔芭·皎月正在调查摧毁西部荒野作物的枯萎病是否已经渗入海洋。鱼人对水生污染物高度敏感，这意味着它们的鳃充当了生物过滤器，可以迅速显示海水中存在的任何微量毒素或污染。",al={"为什么要收集鱼人鳃","阿尔芭·皎月与鱼人","任务目的"}},{q="在这个任务中，鱼人位于何处？",a="这些鱼人栖息在长滩，即西部荒野西海岸那片漫长的沙滩。它们在断崖外侧的浅滩和潮汐滩上徘徊。",al={"鱼人在哪里","长滩鱼人位置","鱼人鳃采集点"}},{q="如果海洋受到污染，会有什么更广泛的危险？",a="西部荒野是暴风城王国的主要粮仓。随着内陆作物歉收，沿海捕鱼提供了关键的食物来源。如果毒素污染了岸边的海洋生物，王国可能会陷入一场无法逃避的饥荒。",al={"为什么这很重要","西部荒野的饥荒危险","对暴风城的威胁"}},{q="鱼人特别容易患病吗？",a="鱼人是在恶劣环境中顽强生存的幸存者，但它们的两栖呼吸系统会对水中的化学或魔法杂质做出立即反应，这使它们成为研究水体污染的理想对象。",al={"鱼人的生理结构","鱼人会生病吗"}},{q="这个任务与迪菲亚潜行者有关吗？",a="虽然迪菲亚潜行者对西部荒野各处的大部分混乱和荒废的农田负有责任，但这项调查专门关注生态枯萎病以及为王国保护食物来源。",al={"迪菲亚关联","这与迪菲亚有关吗"}},{q="阿尔芭·皎月是谁？",a="阿尔芭·皎月是驻扎在西部荒野的一名联盟研究员，负责监测威胁该地区农业生存能力的枯萎病和环境恶化问题。",al={"皎月是谁","阿尔芭·皎月背景故事"}}},fx={["853673a8"]={q="长滩鱼人的鳃 有什么用途？",a="鱼人在沿海水域游荡时通过鳃呼吸，因此它们的呼吸组织对海中的污染物十分敏感。阿尔芭·皎月 将这些鳃用作生物检测样本。通过检查组织中的毒素，她可以判断，那股使西部荒野土壤贫瘠、庄稼枯萎的诡异污染是否也开始毒害海洋。",al={"鱼人鳃用途","为什么收集鱼人鳃","长滩鱼人鳃"}},["4abd0ea3"]={q="为什么要猎杀长滩的鱼人？",a="这些鱼人栖息在西部荒野的西海岸，时刻接触着潮水和浪花。它们适应水生的身体会直接通过鳃过滤沿岸海水，因此，从它们身上采集样本，就能获得直接的生物证据，判断污染物是否已经从受损的农田渗入大海。",al={"为什么选鱼人","长滩鱼人是谁","为什么以鱼人为目标"}}},fp="12,190,25.325.0,26.319.0,41.169.0,44.133.0,53.215.0,42.192.0,50.195.0,21.137.0"}
P.entries["quest:92745"] = {n="The State of the Mines",s="“矿坑状况”是阿尔芭·月痕交给冒险者的一项任务，旨在解决西部荒野各地的环境污染问题。在水井样本中检测出有毒金属后，阿尔芭怀疑是迪菲亚潜行者占领的矿坑导致了这一切，并警告说这些农田可能会因此荒废数十年。为了阻止这场生态灾难，冒险者被派往破坏迪菲亚潜行者在詹戈洛德矿洞和金海岸矿洞的挖掘活动。",h="“矿坑状况”是阿尔芭·月痕交给冒险者的一项任务，旨在解决西部荒野各地的环境污染问题。在水井样本中检测出有毒金属后，阿尔芭怀疑是迪菲亚潜行者占领的矿坑导致了这一切，并警告说这些农田可能会因此荒废数十年。为了阻止这场生态灾难...",kw={"阿尔芭·月痕","迪菲亚","金海岸矿洞","詹戈洛德矿洞","狗头人挖掘工","采矿","河爪","有毒径流","西部荒野"},ang={["class:Druid"]="渗出的金属毒素对西部荒野的平原和海岸生态系统构成了紧迫的生态威胁，需要立即进行遏制。",["faction:Alliance"]="西部荒野对于养活暴风城的人口至关重要；任由迪菲亚潜行者破坏其耕地，将使整个王国面临长期的饥荒威胁。",["profession:Mining"]="看到詹戈洛德矿洞和金海岸矿洞混乱、粗糙的作业方式，很明显迪菲亚潜行者看重的是快速开采，而非安全或结构完整性。"},sec={{t="污染土地",b="西部荒野曾是暴风城的主要粮仓，但最近从当地水井中提取的水样显示，其中含有危险浓度的有毒金属。阿尔芭·月痕首先怀疑是迪菲亚潜行者在这一地区占领的各个矿坑所为。如果这种污染不加遏制地持续下去，周围的土地将变得贫瘠，数十年内无法耕种作物。"},{t="强制和征召劳工",b="迪菲亚潜行者并不只依赖自己的劫掠者，而是利用当地生物种群作为劳动力，榨取西部荒野的自然财富。河爪豺狼人在金海岸矿洞从事着繁重的挖掘石料和矿脉的工作，而狗头人挖掘工则被派往詹戈洛德矿洞的深处开凿隧道。削减他们的劳动力储备能直接打击其加工和分销受污染矿物的能力。"}},faq={{q="为什么西部荒野的矿坑会泄漏有毒金属？",a="水井样本显示西部荒野的地下水中含有有毒金属，阿尔芭·月痕怀疑是迪菲亚潜行者占领了这些矿坑，并利用奴役的生物进行采矿作业。干扰他们的矿工是她对抗这种腐化的第一步行动。",al={"西部荒野水污染原因","西部荒野矿坑污染","西部荒野有毒径流"}},{q="谁在幕后操纵西部荒野的采矿作业？",a="迪菲亚潜行者控制着这些作业。他们占领了王国原有的基础设施，并组织了顺从的生物——主要是河爪豺狼人和狗头人——来处理提取矿物这种危险的体力劳动。",al={"谁在经营矿坑","谁控制了西部荒野的矿坑","迪菲亚采矿"}},{q="河爪豺狼人和狗头人在哪里工作？",a="河爪豺狼人在西海岸的金海岸矿洞充当矿工，而狗头人挖掘工则驻扎在北部的詹戈洛德矿洞内。",al={"矿工在哪里","金海岸矿洞位置","詹戈洛德矿洞位置"}},{q="阿尔芭·月痕是谁？",a="阿尔芭·月痕是西部荒野的一位忧心忡忡的调查员和盟友，她负责检测当地的水源供应，并试图阻止该地区农业景观的长期毁灭。",al={"谁发布了矿坑状况任务","阿尔芭·月痕背景故事","任务发布者"}},{q="为什么豺狼人和狗头人会为迪菲亚潜行者工作？",a="迪菲亚潜行者利用这些生物作为劳动力，从占领的矿坑中榨取资源。阿尔芭并没有说明这些劳工是如何被招募来的。",al={"为什么迪菲亚雇佣豺狼人","为迪菲亚工作的狗头人"}},{q="西部荒野的土地能从这种污染中恢复吗？",a="据阿尔芭·月痕所言，只有迅速切断毒源，土壤才有可能恢复。如果采矿作业不中断地持续下去，土地在未来几十年内都将保持贫瘠和荒芜。",al={"西部荒野土壤会恢复吗","农作物能再次生长吗"}}},fx={f9d72c87={q="阿尔芭·皎月 为什么要杀死那些矿工？",a="当地水井的水样表明，危险的有毒金属正在渗入西部荒野的土壤。阿尔芭·皎月 知道，除非立即停止这种掠夺式的露天开采，否则毒素就会长期残留在环境中，让这片土地荒芜，数十年都无法种植庄稼。",al={"为什么杀矿工","阿尔芭·皎月 的动机","为什么阻止采矿"}},["23ba5f2a"]={q="詹戈洛德矿洞和金海岸矿洞里的矿工是谁？",a="你奉命对付的是詹戈洛德矿洞里的 狗头人挖掘工，以及金海岸矿洞里的 河爪矿工。这些生物并非为自己干活，而是被迪菲亚潜行者用作劳工。迪菲亚潜行者占据了矿洞，肆无忌惮地掠夺西部荒野的矿产。",al={"矿工是谁","奉命杀谁","狗头人挖掘工 河爪矿工"}}},fp="22,240,18.325.0,25.320.0,51.182.0,48.160.0,50.136.0,21.107.0,50.113.0,57.169.0"}
P.entries["quest:92747"] = {n="Moonbrook Espionage",s="“Moonbrook Espionage”是联盟的一项任务，由阿尔巴·月风委派，旨在侦察已被占领的月溪镇定居点。调查人员认为某种神秘的毒素并非来自西部荒野的其他小型挖掘场，因此将注意力转向了镇下方那座古老且早已废弃的死亡矿井，试图寻找那里存在工业活动的证据。",h="“Moonbrook...",kw={"阿尔巴·月风","死亡矿井","间谍活动","工业补给品","矿井","月溪镇","毒素","西部荒野"},ang={["class:Rogue"]="潜行者如果能在不被发现的情况下潜入月溪镇，将获得一个极佳的收集情报的机会，从而在不惊动敌人的情况下探查迪菲亚的行动。",["faction:Alliance"]="揭露月溪镇活跃的工业活动，意味着对西部荒野这个粮仓以及暴风城自身的安全构成了直接威胁。",["profession:Mining"]="矿工比任何人都更清楚隐藏在月溪镇深处那些坑道里的巨大财富和后勤规模。"},sec={{t="毒素的踪迹",b="在调查了西部荒野各地的矿井后，调查人员陷入了死胡同：困扰该地区的毒素似乎并非源自任何已知的地表挖掘作业。这使得只剩下一处主要的挖掘点尚未探索——即位于月溪镇废墟正下方、那庞大而幽深的死亡矿井。"},{t="死亡矿井的秘密",b="官方记录声称死亡矿井在第一次战争后，当部落横扫该地区时就被废弃了。然而，在月溪镇各处散落的现代工业装备和补给品有力地表明，有人正以这座荒废鬼镇作为掩护，秘密进行着大规模的采矿和制造作业。"}},faq={{q="谁委派了“月溪镇谍报”任务？",a="该任务由阿尔巴·月风委派，她一直在调查西部荒野这一争议领土上出现的各类可疑毒素和工业活动。",al={"任务发布者","谁发布了月溪镇谍报","阿尔巴·月风"}},{q="为什么阿尔巴要调查月溪镇？",a="其他的当地矿井并未显示出生产调查中那种毒素的迹象。由于月溪镇正好位于死亡矿井的正上方，阿尔巴怀疑有人在该镇下方隐藏着非法作业。",al={"为什么是月溪镇","月溪镇里有什么","调查月溪镇"}},{q="死亡矿井是什么？",a="死亡矿井是该地区最深、规模最大的金矿。自暴风城陷落后的第一次战争以来，矿井一直被废弃，长期以来人们认为那里只是被害虫和强盗占据的空旷废墟。",al={"死亡矿井背景故事","什么是死亡矿井","死亡矿井历史"}},{q="在此次侦察任务中需要收集什么物品？",a="侦察兵被派去回收散落在月溪镇各处的可疑的工业补给品，以证明在矿井通道附近确实存在积极的工业工作和提炼活动。",al={"可疑的工业补给品","月溪镇谍报任务物品"}},{q="目前有哪些威胁盘踞在月溪镇？",a="月溪镇目前被迪菲亚潜行者占领，他们利用这些废弃的建筑作为前进基地，并守卫着通往地下网络的地表入口。",al={"月溪镇的敌人","谁控制了月溪镇"}},{q="发现这些补给品证明了什么？",a="在一个所谓的废弃城镇中出现现代重型工业设备，证实了有一个协同行动的派系正在进行大规模的制造作业，并刻意躲避着暴风城当局的窥探。",al={"补给品意味着什么","迪菲亚工业"}}},fp="19,209,13.271.0,24.282.1,32.144.0,36.181.0,23.198.0,53.167.0,40.161.0,39.175.0"}
P.entries["quest:92748"] = {n="Explosive Consultation",s="Explosive Consultation 是一项起源于西部荒野的联盟任务，旨在对抗潜藏在死亡矿井深处的有毒工业作业。在发现重型机械正在毒害当地农田的线索后，冒险者们被派往暴风城的矮人区，以招募一位能够提供重型爆炸物的工程学专家。",h="Explosive Consultation...",kw={"阿尔巴·皎月","死亡矿井","矮人区","工程学","爆破咨询","斯普莱特","暴风城","毒素","西部荒野"},ang={["faction:Alliance"]="这项任务展示了西部荒野苦苦挣扎的边境社区与暴风城矮人区繁忙作坊之间的相互依赖关系。",["profession:Engineering"]="工程师们会明白，蛮力无法解决西部荒野的生态困境；摧毁大规模的地下机械需要专门的弹药和精湛的技术能力。",["race:Gnome"]="侏儒的科技才智对于消除联盟正规军无法解决的地下工业威胁至关重要。"},sec={{t="毒素之源",b="尽管西部荒野正受流离失所的流浪者以及迪菲亚潜行者的匪帮活动困扰，但该地区收集到的证据显示，在地表之下还有着更具组织性、更机械化的威胁在蔓延。工业废料和腐蚀性毒素正渗入周围的土壤，这些痕迹直接指向了死亡矿井中如迷宫般的隧道，表明有一个组织严密的机构正在地下不知疲倦地运作。"},{t="寻求暴风城的专业知识",b="常规武器不足以破坏加固的地下设施。要阻止西部荒野遭受的毒害，需要进行工业爆破，因此必须紧急前往暴风城的矮人区。在那里，在轰鸣的熔炉、修补匠和炸药商人之间，必须招募一位名叫斯普莱特的工程学天才，以设计出一种爆炸性的解决方案。"}},faq={{q="为什么我们在死亡矿井需要爆炸物？",a="在西部荒野搜集到的证据表明，死亡矿井内隐藏着一个庞大的工业作业基地，它正在持续制造毒素，污染周围的农田。仅靠人力摧毁加固的机械并不现实，需要重型军火才能将其破坏。",al={"为什么死亡矿井需要爆炸物","为什么需要炸弹","死亡矿井毒素原因"}},{q="谁发布了这个任务？",a="阿尔芭·皎月 将这项任务交给调查西部荒野非自然污染物和动乱的英雄们。",al={"谁发布 炸药咨询","炸药咨询 起始"}},{q="斯普莱特是谁？",a="斯普莱特是一位居住在暴风城矮人区的侏儒工程师。她以擅长处理复杂的机械装置和挥发性化合物而闻名，人们寻求她的帮助以制造大威力的爆破装置。",al={"斯普莱特的位置","斯普莱特是谁"}},{q="为什么要前往矮人区寻求帮助？",a="矮人区是暴风城的工业中心，这里汇集了王国最顶尖的铁匠、修补匠以及炸药和工程组件供应商。",al={"为什么去 矮人区","暴风城 矮人区 的联系"}},{q="暴风城政府是否协助这项工作？",a="随着瓦里安·乌瑞恩国王失踪，且贵族议会不愿向西部荒野派遣正式的军事驻军，当地的防卫者只能依靠独立的志愿者和首都的私人匠人，而不是正规军团。",al={"军队是否提供帮助","为什么需要暴风城的工程师"}}},fx={fe11cddb={q="阿尔芭·皎月 为什么要你寻找炸药？",a="阿尔芭·皎月 发现了证据，表明死亡矿井深处隐藏着一处规模庞大的工业设施。她查明，正是这些地下机械产生的污毒在毒害土壤，摧残上方的农田。她知道，如此规模的设施无法单靠人力拆除，因此需要威力强大的炸药，在损害无法挽回之前，彻底摧毁那些污染乡野的肮脏机械。",al={"阿尔芭·皎月 为什么要炸药","阿尔芭·皎月 的动机","阿尔芭 为什么需要炸药"}}},fp="22,216,14.261.0,29.256.0,43.169.0,22.101.0,27.174.0,44.171.0,52.231.0"}
P.entries["quest:92749"] = {n="A Dynamite Plan",s="A Dynamite Plan是一项任务，由暴风城矮人区内富有创造力的工匠斯普莱特提供。她对工业破坏的传闻感到兴奋，并寻求储备大量的粗制炸药来启动这项计划。冒险者们必须制造或收集弹药来支持她的阴谋。",h="A Dynamite Plan是一项任务，由暴风城矮人区内富有创造力的工匠斯普莱特提供。她对工业破坏的传闻感到兴奋，并寻求储备大量的粗制炸药来启动这项计划。冒险者们必须制造或收集弹药来支持她的阴谋。",kw={"粗制炸药","矮人区","工程学","爆炸物","破坏","斯普莱特","暴风城"},ang={["faction:Alliance"]="斯普莱特在联盟首都城墙内的矮人区执行她的爆炸计划。",["profession:Engineering"]="工程师可以使用粗制爆破粉和亚麻布制作粗制炸药，使这项任务成为早期工程学手艺的一次直接测试。",["race:Gnome"]="斯普莱特体现了经典的侏儒冲动：用巧妙、易燃的装置来解决复杂的工业问题。"},sec={{t="矮人区的火花",b="在暴风城矮人区的嘈杂声和烟雾中，侏儒工程师斯普莱特从来都不是那种回避激进解决方案的人。当谈话转向工业破坏时，她的第一直觉不是谨慎，而是热情。作为第一步，她招募过往的雇佣兵为她提供一捆粗制炸药。"},{t="侏儒的野心",b="获取这些爆炸物需要精通工程学工作台，或者在城市工匠之间具备贸易头脑。十根粗制炸药足以提供足够的火力来扰乱周边地区正在发生的任何工业阴谋，这展示了侏儒在解决机械和政治混乱时偏好的实用但危险的方法。"}},faq={{q="斯普莱特是谁？",a="斯普莱特是一位工程师，在暴风城矮人区的铁匠铺和工作室中工作。她以追求大胆且不稳定的工程项目而闻名。",al={"斯普莱特","斯普莱特是谁","任务发布者"}},{q="斯普莱特完成这项任务需要什么？",a="她需要十根粗制炸药。这些炸药可以通过工程学技术制造，也可以通过与其他工匠的交易以及拍卖行获得。",al={"炸药计划物品","我需要什么","所需物品"}},{q="为什么斯普莱特想要粗制炸药？",a="工业破坏的前景引起了斯普莱特的注意，她打算用可靠的基础爆破炸药储备来开始这项工作。",al={"为什么需要炸药","炸药用途","破坏动机"}},{q="我在哪里交任务？",a="斯普莱特位于暴风城内的矮人区。",al={"在哪里交任务","交任务地点","斯普莱特位置"}},{q="完成这个任务需要工程学吗？",a="不，并不严格需要工程学。虽然工程师可以自己制作粗制炸药，但任何冒险者都可以与其他玩家交易或从拍卖行购买所需的炸药。",al={"我需要工程学吗","工程学要求","非工程师可以做吗"}},{q="这与暴风城周围更广泛的麻烦有什么关系？",a="斯普莱特从未说明她的破坏目标是什么。她透露的只有她的急切：一旦提到工业破坏，她就想用炸药开始。",al={"暴风城的麻烦","西部荒野的破坏","工业破坏背景"}}},fx={dd094caa={q="粗制炸药 有什么用途？",a="斯普莱特迫不及待地想进行一场工业破坏，而爆炸的威力正是这个计划的关键。粗制炸药 能提供她所需的强劲冲击力，破坏机械运转，或为她接下来的行动炸开建筑障碍。",al={"粗制炸药 用途","斯普莱特要炸药做什么","为什么要 粗制炸药"}}},fp="15,158,30.184.0,17.309.0,27.155.0,36.130.0,37.112.0,29.60.0,47.130.0,58.129.0"}
P.entries["quest:92750"] = {n="Detonation at a Distance",s="“远距离引爆”任务派遣一位冒险者前往暴风城，寻求专业的爆炸物技术支持。在古怪的侏儒技师斯普莱特的启发下，你被指引前往暴风城军情七处获取一个遥控引爆器。",h="“远距离引爆”任务派遣一位冒险者前往暴风城，寻求专业的爆炸物技术支持。在古怪的侏儒技师斯普莱特的启发下，你被指引前往暴风城军情七处获取一个遥控引爆器。",kw={"远程引爆","贾斯伯·菲尔","遥控引爆器","军情七处","斯普莱特","暴风城情报部门","西部荒野"},ang={["class:Rogue"]="拜访贾斯伯·菲尔意味着要进入旧城区军情七处行动的核心，那是人类隐秘贸易技艺的中心。",["profession:Engineering"]="虽然工程师经常自己制造引信和炸药，但获得军用级的遥控触发器通常需要那些擅长悄无声息地进行破坏工作的联系人。",["race:Gnome"]="斯普莱特体现了侏儒对工程学问题经典的钻研精神，即使她为了特定的间谍弹药而转而求助于人类情报部门。"},sec={{t="可控爆炸",b="虽然地精和侏儒都以在使用挥发性化学品时极其鲁莽而臭名昭著，但并非所有的爆破任务都需要站在有效载荷旁边。当标准引信危及生命时，遥控引爆就成了绝对的必需品。斯普莱特意识到，可控爆炸需要普通技师在日常剩余物资中不会携带的特殊触发装置。"},{t="求助军情七处",b="斯普莱特没有求助于当地的矮人爆破工或标准工程学供应商，而是将搜索目标指向了在旧城区活动的暴风城军情七处。该王国的秘密特工网络通常被称为军情七处，专门负责敏感的破坏活动、潜行渗透和定点爆破。贾斯伯·菲尔，一位潜伏在首都的特工，正是那种能搞到此类隐秘且危险设备的影子联系人。"}},faq={{q="是谁派遣你执行此任务？",a="该任务由斯普莱特发放，这是一位隶属于联盟的侏儒技师，位于暴风城的矮人区。",al={"任务发放者","谁开启远距离引爆","斯普莱特任务"}},{q="你在暴风城需要与谁交谈？",a="你需要与贾斯伯·菲尔交谈，他是暴风城军情七处的成员，驻扎在暴风城。",al={"去哪里交任务","军情七处联系人","贾斯伯·菲尔位置"}},{q="为什么斯普莱特需要遥控引爆器？",a="斯普莱特指出，虽然遥控引爆可能缺乏失控爆炸带来的那种混乱刺激，但为了在处理危险爆炸物时保全肢体，远程触发器显然更加实用。",al={"为何需要遥控引爆器","引爆目的"}},{q="为什么要联系军情七处而不是工程师？",a="军情七处拥有普通城市商人或野外技师不会公开储备或分发的秘密物资和专业破坏装备。",al={"为何选择军情七处","为何选择暴风城情报部门"}},{q="贾斯伯·菲尔在暴风城的什么位置？",a="贾斯伯·菲尔位于旧城区的军情七处总部内，那是暴风城的间谍和秘密特工进行行动的地方。",al={"贾斯伯·菲尔暴风城","贾斯伯·菲尔房间"}},{q="哪个阵营可以执行此任务？",a="此任务仅限于联盟成员，因为它依赖于与暴风城皇家情报部门的合作。",al={"这是否仅限联盟","部落可以做吗"}}},fx={be1ed035={q="斯普莱特为什么派你去找 SI:7，而不亲自去？",a="斯普莱特自己没有遥控引爆器。既然你想在引爆时控制好爆炸，保住自己的四肢，她就让你去找暴风城的情报机构那些行事隐秘的家伙，她相信他们能弄到一个。任务并没有说明她为什么不亲自去。",al={"斯普莱特为什么选我","为什么派玩家去 si:7","斯普莱特为什么不能去暴风城"}}},fp="24,124,18.229.0,21.299.0,30.108.0,40.84.0,53.136.0,59.133.0,41.95.0,37.125.0"}
P.entries["quest:92751"] = {n="Detonation at a Distance",s="Detonation at a Distance是联盟的一项任务，由暴风城情报圈内的贾斯伯·菲尔发起。在得知月溪镇地下有危险行动后，这位军情七处联络人提供了一种专门的远程引爆器，以便在不炸伤友方人员的情况下安全处理爆破作业。",h="Detonation at a...",kw={"死亡矿井","矮人区","贾斯伯·菲尔","月溪镇","远程引爆器","军情七处","斯普莱特","西部荒野"},ang={["class:Rogue"]="与贾斯伯·菲尔直接接触突显了军情七处庞大的秘密网络，展示了王国的间谍大师们是如何监控外勤特工并悄悄为他们提供合适的工具。",["faction:Alliance"]="这项任务反映了暴风城在收复西部荒野过程中的挣扎，他们使用的是隐蔽的工程技术和情报手段，而不是公开的军事部署。",["profession:Engineering"]="工程学玩家会喜欢这种原型远程引爆器，它旨在取代复杂的洞穴爆破中高风险的手动导火索。",["race:Gnome"]="送货给斯普莱特的过程展示了侏儒在暴风城的聪明才智，他们为王国的间谍提供了尖端的原型产品。"},sec={{t="阴影之眼",b="贾斯伯·菲尔和军情七处的特工们监视着暴风城领土内发生的几乎一切事情，尤其是像西部荒野这样混乱的边境地区。当菲尔收到关于月溪镇爆炸行动的消息时，他早就清楚这片乡村地下的废弃矿道里正在酝酿着什么。"},{t="原型解决方案",b="在封闭的洞穴系统中引爆大规模炸药存在明显的危险。菲尔提供了一套由联盟工程人员开发的远程引爆器工具包原型，确保西部荒野地下的任何爆破都能从外部安全触发。他指示信使将这些硬件送到矮人区的斯普莱特手中，同时低声提醒他们不要向精灵同伴提起军情七处参与其中。"}},faq={{q="谁是贾斯伯·菲尔？",a="贾斯伯·菲尔是一名隶属于暴风城情报机构军情七处的特工。他在阴影中工作，监控王国各地的隐蔽威胁，并提供专门的工具来处理这些威胁。",al={"贾斯伯·菲尔","谁给予远程引爆任务","任务发布者"}},{q="为什么军情七处会关注月溪镇？",a="月溪镇已经落入强盗和歹徒之手，成为了死亡矿井的地面入口。在西部荒野深处的任何活动或爆破都会立即引起暴风城内部情报网的注意。",al={"为什么关注月溪镇","迪菲亚兄弟会关联","西部荒野洞穴"}},{q="谁是斯普莱特？",a="斯普莱特是暴风城矮人区的一名侏儒工程师，他正在组装用于爆破的炸药。",al={"斯普莱特","谁接收引爆器","任务交付非玩家角色"}},{q="贾斯伯·菲尔提到的“精灵朋友”是谁？",a="贾斯伯·菲尔指的是奥尔芭·月痕，那位正在调查西部荒野毒素并派你寻找炸药的精灵。军情七处倾向于在保密和合理的推诿中行动，不让外部盟友知道他们提供了直接支持。",al={"精灵朋友","不要告诉精灵","贾斯伯·菲尔与精灵"}},{q="远程引爆器工具包有什么用？",a="这是一种工程原型，旨在从安全距离触发爆破炸药，使特工能够在不被困在里面的情况下坍塌或清理地下通道。",al={"远程引爆器","引爆器工具包","工具包的作用"}},{q="这个任务会把你带到哪里？",a="任务要求你将引爆器工具包直接送到暴风城矮人区交给斯普莱特。",al={"我要去哪里","任务路线","交付地点"}}},fx={dd5ef9f7={q="贾斯伯·菲尔为什么要帮忙提供遥控引爆器？",a="贾斯伯·菲尔为斯普莱特提供了一套先进的原型引爆器套件。他帮助筹备这次爆破，同时要求你别让那位精灵朋友知道他参与了此事。",al={"贾斯伯·菲尔的动机","为什么帮忙提供引爆器","贾斯伯·菲尔为什么给套件"}},["2c859344"]={q="贾斯伯·菲尔为什么把这件事交给你，而不亲自处理？",a="贾斯伯·菲尔将给斯普莱特的原型引爆器套件托付给你，同时要求你别让那位精灵朋友知道他参与了此事。他没有解释为什么不能亲自送去。",al={"为什么派我去","贾斯伯·菲尔为什么不亲自送","为什么不派 si7 特工"}}},fp="24,179,19.243.0,20.334.1,18.154.0,35.165.0,27.120.0,44.162.0,42.162.0,31.88.0"}
P.entries["quest:92752"] = {n="Explosive Consultation",s="Explosive Consultation是西部荒野的一项任务，涉及侏儒技师斯普莱特和Alba Fairmoon。在获得了一批极不稳定的货物后，斯普莱特委托一名信使安全地运送这批已装填引信的炸药，以免不小心引爆雷管。",h="Explosive Consultation是西部荒野的一项任务，涉及侏儒技师斯普莱特和Alba Fairmoon。在获得了一批极不稳定的货物后，斯普莱特委托一名信使安全地运送这批已装填引信的炸药，以免不小心引爆雷管。",kw={"阿尔巴·皎月","雷管","爆破咨询","炸药","侏儒工程学","斯普莱特","西部荒野"},ang={["faction:Alliance"]="西部荒野各地的联盟特工依靠非常规武器来对抗固守阵地的强盗营地和失控的机械。",["profession:Engineering"]="任何有经验的工程师都会明白侏儒武器的典型风险：极高的威力配合触敏雷管。",["race:Gnome"]="斯普莱特代表了诺莫瑞根那种爆炸式的解决问题方式，为西部荒野动荡的前线带来了高威力的技术解决方案。"},sec={{t="一次危险的运送",b="侏儒工程学向来以激进著称，斯普莱特在西部荒野的手艺也名副其实。在完成调配后，斯普莱特提供了一捆专门给Alba Fairmoon的“强效炸药”。在战时的西部荒野从事跑腿工作，还要躲避迪菲亚强盗和野兽，这本来就已经够危险了，而携带一枚随时可能爆炸的触敏武器更是增添了额外的风险。"},{t="小心搬运",b="斯普莱特在交付货物时给出了简单但至关重要的建议：注意雷管。这批不稳定的货物旨在摧毁死亡矿井中正在毒害西部荒野农田的隐秘工业设施，必须完好无损地送达，Alba Fairmoon才能使用它。"}},faq={{q="谁发布了爆破咨询任务？",a="该任务由斯普莱特发布，他是暴风城矮人区的一位侏儒技师，专门提供特种炸药。",al={"谁发布炸药咨询任务","炸药咨询任务发布者","斯普莱特任务"}},{q="任务最后由谁接收炸药？",a="成品“强效炸药”必须直接送到西部荒野的阿尔芭·皎月手中。",al={"炸药送到哪里","谁接收炸药咨询任务","阿尔芭·皎月炸药"}},{q="你的运输任务是什么物品？",a="斯普莱特委托你运送一包“强效炸药”，里面还包含了一个已激活且极其脆弱的雷管。",al={"斯普莱特移交了什么","炸药咨询物品","这是什么炸弹"}},{q="为什么西部荒野需要炸药？",a="阿尔芭·皎月追踪到毒害西部荒野农田的毒素源自死亡矿井中隐藏的一个大型工业设施。无论那下面是什么，都很难摧毁，所以她寻找了一位能提供炸药来终结此事的工程师。",al={"为什么需要炸弹","西部荒野炸药的用途","为什么在西部荒野进行爆破"}},{q="部落冒险者可以接这个任务吗？",a="不可以。斯普莱特和阿尔芭·皎月支持联盟的行动，因此该任务仅限联盟玩家。",al={"部落能做炸药咨询吗","部落 炸药咨询"}},{q="斯普莱特是否警告过你特定的危险？",a="斯普莱特明确警告说炸弹已经装填了引信，你在旅途中必须极其小心地处理雷管。",al={"斯普莱特的警告","西部荒野炸弹警告"}}},fx={bb434565={q="斯普莱特为什么要把炸药送给 阿尔芭？",a="斯普莱特已经组装好了强效炸药，这是为支持 阿尔芭·皎月 在西部荒野的行动而受托制作的。制成这批危险的炸药后，斯普莱特需要一名冒险者，小心地承担运回 阿尔芭 那里的危险差事，让炸弹按计划派上用场。",al={"为什么给 阿尔芭 送炸药","斯普莱特的动机","斯普莱特为什么制造炸弹"}}},fp="22,151,19.237.0,18.246.0,44.105.0,52.68.0,43.86.0,38.190.0,45.117.0,60.121.0"}
P.entries["quest:92753"] = {n="Destruction in Deadmines",s="“死亡矿井的破坏”是一项由奥尔巴·月影协调的秘密破坏任务，旨在打击迪菲亚潜行者的工业行动核心。在月溪镇下方错综复杂的隧道深处，迪菲亚潜行者经营着一座巨大的冶金锻炉，据怀疑它正在污染周围的土地。冒险者需要渗透进该设施，在铸造厂附近放置强效炸药，以此摧毁迪菲亚的战争机器。",h="“死亡矿井的破坏”是一项由奥尔巴·月影协调的秘密破坏任务，旨在打击迪菲亚潜行者的工业行动核心。在月溪镇下方错综复杂的隧道深处，迪菲亚潜行者经营着一座巨大的冶金锻炉，据怀疑它正在污染周围的土地。冒险者需要渗透进该设施，在铸...",kw={"奥尔巴·月影","死亡矿井","迪菲亚潜行者","强效炸药","冶金锻炉","月溪镇","破坏行动","西部荒野"},ang={["faction:Alliance"]="摧毁迪菲亚的锻炉可以直接打击那些在西部荒野内部威胁暴风城主权的机械和武器。",["profession:Engineering"]="针对重工业基础设施使用专业的强效炸药，是奥尔巴·月影提议的清除疑似污染源的破坏方法。",["profession:Mining"]="死亡矿井曾是暴风城最赚钱的金矿和铁矿，现在却被迪菲亚改造成了一座污染大地的防御型冶炼综合体。"},sec={{t="破坏铸造厂",b="死亡矿井里不仅仅只有金矿脉和扒手；在月溪镇尘土飞扬的地面下，坐落着一座为迪菲亚潜行者提供能源的防御森严的工业综合体。在他们的地下工程中，有一座用于熔炼金属和组装机械的大型冶金锻炉。奥尔巴·月影认为这座锻炉很可能是导致该地区环境污染的罪魁祸首，因此将其炸毁至关重要。"},{t="决定性的一爆",b="想要到达死亡矿井的中心，必须突破路障，击败那些暴徒和地精工程师。携带强效炸药的特工必须将炸药直接放置在锻炉旁边，然后迅速撤离到月溪镇上方的高地，奥尔巴·月影在那里等待，他们将引爆炸药，希望能让这片土地得到恢复。"}},faq={{q="这项任务的目标是什么？",a="任务目标是渗透进月溪镇下方的死亡矿井，找到迪菲亚潜行者的冶金锻炉，并在附近放置强效炸药，然后撤离到出口与奥尔巴·月影汇合。",al={"任务目标","我该做什么","什么是死亡矿井的破坏"}},{q="奥尔巴·月影是谁？",a="奥尔巴·月影是在西部荒野行动的一名联盟特工，她认为毒害和污染该地区的根源在于死亡矿井内部沉重的熔炼和工业运作。",al={"奥尔巴是谁","奥尔巴·月影背景故事","任务发布者"}},{q="为什么迪菲亚的锻炉被认为如此危险？",a="奥尔巴怀疑死亡矿井里的一座大型冶金锻炉是毒源所在。她希望将其摧毁后，土地能够开始自我修复。",al={"为什么要摧毁锻炉","锻炉有什么用途","锻炉污染"}},{q="玩家在放置炸药后去哪里与奥尔巴汇合？",a="奥尔巴·月影在月溪镇后方的高地、矿井上层出口附近等待，一旦特工安全撤出，她随时准备引爆炸药。",al={"奥尔巴在哪里等待","死亡矿井出口位置","任务交付地点"}},{q="锻炉位于死亡矿井的什么位置？",a="锻炉位于死亡矿井副本的深处，穿过采矿隧道，位于由迪菲亚劳工和地精监工把守的工业铸造区域内。",al={"锻炉在哪里","死亡矿井锻炉位置","寻找锻炉"}},{q="摧毁锻炉能让土地立即恢复吗？",a="奥尔巴希望消除繁重的熔炼作业能让月溪镇周边的土地最终得以恢复，尽管多年的迪菲亚工业运作和忽视所造成的破坏还需要时间来消除。",al={"土地会恢复吗","污染会停止吗","锻炉的后果"}}},fx={cfdfebff={q="阿尔芭·皎月 为什么要摧毁熔炉？",a="阿尔芭 认为，死亡矿井深处的迪菲亚熔炉才是污毒渗入周围土地的真正源头。她希望通过安放炸药，炸毁这处庞大的冶炼设施，从根源上切断污染，让西部荒野饱受摧残的土壤终于能够开始恢复。",al={"阿尔芭·皎月 的动机","为什么摧毁死亡矿井熔炉","阿尔芭 为什么要做这件事"}}},fp="24,177,22.263.0,16.278.1,33.180.0,21.167.0,48.146.0,62.163.0,48.141.0,52.146.0"}
P.entries["quest:928"] = {n="大地之冠",s="“大地之冠”是一段过渡性的旅程，引领年轻的暗夜精灵走出幽影谷，迈向泰达希尔更广阔的领域。旅行者们需要携带在奥达希尔顶端受过祈福的圣洁月井之水，沿着森林之路南下，前往多兰纳尔拜见科瑞萨斯·月怒。它标志着从封闭式的训练正式走向为了维护伟大的世界之树而进行的紧急生态保卫战。",h="“大地之冠”是一段过渡性的旅程，引领年轻的暗夜精灵走出幽影谷，迈向泰达希尔更广阔的领域。旅行者们需要携带在奥达希尔顶端受过祈福的圣洁月井之水，沿着森林之路南下，前往多兰纳尔拜见科瑞萨斯·月怒。它标志着从封闭式的训练正式走...",kw={"奥达希尔","科瑞萨斯·月怒","大地之冠","多兰纳尔","月井","装着半瓶水的瓶子","幽影谷","泰达希尔","特纳隆·雷拳"},ang={["class:Druid"]="运送这些圣洁的水，将年轻的德鲁伊与为了培育和平衡泰达希尔新兴生态系统而进行的持续且脆弱的努力联系了起来。",["class:Priest"]="携带由艾露恩的恩典所祝圣的月井之水，代表了她的祭司们维护社区精神健康的圣洁职责。",["race:NightElf"]="跨出幽影谷的边界，是每一位年轻的卡多雷为了服务他们的人民而必须经历的成人礼。"},sec={{t="离开林地",b="在通过取用幽影谷月井的附魔之水证明了自己的虔诚后，新兵们会被召集到奥达希尔之冠的特纳隆·雷拳面前。特纳隆认可了他们的准备工作，将收集到的水封入一个更大的容器中，并命令他们走出这片庇护的丛林。通往多兰纳尔的南行之路是走出幽影谷的主要动脉，道路蜿蜒穿过变得愈发难以预测且充满敌意的森林。"},{t="通往多兰纳尔的路",b="多兰纳尔是旅行者离开起始山谷后遇到的第一个主要村庄。这个定居点坐落在泰达希尔中部弯曲的鹅卵石小径旁，村子围绕着属于他们自己的纯净月井而建。科瑞萨斯·月怒在此等候，作为一名长者，他负责监督在这片枝叶间开展的更广泛的保护工作。交到他手中的容器，将这名初出茅庐的冒险者与世界之树广阔而多舛的命运紧紧联系在了一起。"}},faq={{q="我带去多兰纳尔的是什么？",a="你携带的是装着半瓶水的瓶子，其中盛有从幽影谷月井中汲取的圣洁之水。特纳隆·雷拳将你最初提供的水合并到了这个容器中，以便科瑞萨斯·月怒能在泰达希尔各地继续进行仪式工作。",al={"这个容器是什么","装着半瓶水的瓶子背景故事","这是什么水"}},{q="科瑞萨斯·月怒是谁？",a="科瑞萨斯·月怒是一位暗夜精灵长者，驻守在多兰纳尔的月井旁。他指导前来报到的冒险者，继续进行维持这棵新生的世界之树所必需的重要仪式和调查。",al={"科瑞萨斯是谁","科瑞萨斯·月怒的职责","科瑞萨斯在哪里"}},{q="为什么特纳隆要让我离开幽影谷？",a="幽影谷提供基础训练，但泰达希尔面临的挑战需要整棵大树枝叶范围内的援助。既然你已经证明了自己有能力处理当地的威胁并向月井致敬，特纳隆就会派你前往多兰纳尔，那里有更广泛的任务在等着你。",al={"为什么要离开幽影谷","为什么要前往多兰纳尔","特纳隆让我离开"}},{q="通往多兰纳尔的路在哪里？",a="沿着奥达希尔南侧的鹅卵石小径走，经过幽影谷的大门。沿着鹅卵石路继续向南和向西蜿蜒，直到你抵达多兰纳尔村。",al={"如何前往多兰纳尔","通往多兰纳尔的路径","走出幽影谷的道路"}},{q="为什么特纳隆要警告那些危险的野兽？",a="特纳隆只是说最近森林里出现了危险的野兽。即使在泰达希尔神圣的枝叶间，野生动物也变得极具攻击性，所以偏离铺设好的道路是非常危险的。",al={"为什么野兽变得危险","泰达希尔受腐蚀的野兽","远离道路的警告"}},{q="到达多兰纳尔后会发生什么？",a="科瑞萨斯·月怒会收下容器，并派遣你去泰达希尔各地的月井灌注药剂，让你在旅途中继续书写关于这棵树的故事。",al={"完成“大地之冠”后做什么","多兰纳尔的后续任务","科瑞萨斯做什么"}}},fp="18,172,17.281.0,20.317.0,31.196.0,26.161.0,46.219.0,30.160.0,45.177.0,37.142.0"}
P.entries["quest:92812"] = {n="Economic Warfare",s="一名吉尔吉斯半人马请你收集其他氏族的雕刻图腾。这些图腾承载着故事，也能让吉尔吉斯在与玛格拉姆谈判时更有筹码。",h="一名吉尔吉斯半人马请你收集其他氏族的雕刻图腾。这些图腾承载着故事，也能让吉尔吉斯在与玛格拉姆谈判时更有筹码。",kw={"易物","半人马","凄凉之地","经济战","吉尔吉斯","玛格拉姆","图腾","交易"},sec={{t="以故事换取交易",b="吉尔吉斯遵循着半人马古老的习俗：各氏族交换雕刻图腾，讲述某个人或氏族的伟大功绩。尽管氏族间仍有冲突，他们依然尊重这种交易方式。你可以把从其他氏族的阵亡半人马身上取得的图腾带给吉尔吉斯，让他们在易物时有更多筹码。"},{t="吉尔吉斯的收藏",b="吉尔吉斯将你带来的图腾收入收藏，实力也随之增强。可他们要想击败玛格拉姆氏族，还有很长的路要走。"}},faq={{q="半人马交易什么？",a="半人马氏族交换雕刻图腾，以此纪念个人或氏族的伟大成就。",al={"半人马交易物品","交易内容"}},{q="图腾对吉尔吉斯为何重要？",a="吉尔吉斯用图腾作为易物的筹码，收藏越丰富，他们就越强大。",al={"吉尔吉斯图腾","图腾价值"}},{q="半人马交战时还会交易吗？",a="会。尽管氏族间冲突不断，他们仍尊重这一传统，只是交易的机会已经少之又少。",al={"半人马氏族交易","冲突期间交易"}},{q="吉尔吉斯希望击败哪个氏族？",a="吉尔吉斯希望击败玛格拉姆氏族。",al={"吉尔吉斯的敌人","玛格拉姆氏族"}}},fp="16,152,16.298.0,13.152.1,26.99.0,43.99.0,42.113.0,42.44.0"}
P.entries["quest:92819"] = {n="Destruction in Deadmines",s="Destruction in Deadmines是一项由西部荒野的Alba Fairmoon负责监督的秘密任务。随着炸药被安放在死亡矿井深处的迪菲亚潜行者熔炉旁，特工会回到月溪镇后方的山丘与Alba汇合，并在安全距离外引爆炸药。",h="Destruction in Deadmines是一项由西部荒野的Alba...",kw={"阿尔巴·皎月","死亡矿井","迪菲亚潜行者","死亡矿井的毁灭","引爆器","炸药","破坏行动","西部荒野"},ang={["class:Rogue"]="潜入敌后安放炸药并在爆炸前撤离，使这项任务成为了隐秘破坏行动的经典案例。",["faction:Alliance"]="每一次对死亡矿井中迪菲亚据点的打击，都有助于保护西部荒野那些挣扎求生的农场和暴风城的南部边境。",["profession:Engineering"]="拆除工程和远程触发引爆器是这项任务的核心，这非常吸引那些欣赏受控结构坍塌艺术的工程师们。"},sec={{t="西部荒野下的破坏行动",b="死亡矿井长期以来都是迪菲亚潜行者的核心力量所在，作为西部荒野地下的一座据点和工业中心。Alba Fairmoon并没有依靠通过每个设防走廊的直接强攻，而是指挥了一场决定性的破坏行动。通过在地下设施内安放炸药并将其引爆，联盟特工旨在摧毁其关键基础设施，并挫败兄弟会在暗中策划的任何阴谋。"},{t="引爆器",b="执行这项任务需要稳健的双手和精准的时机。炸药已经放置在死亡矿井中隐藏的熔炉旁，远程引爆器可以让你在洞穴外将其引爆。Alba希望随着熔炉的消失，西部荒野那片被污染的土地能够开始恢复。"}},faq={{q="是谁提供了死亡矿井的毁灭这个任务？",a="这项任务由阿尔芭·皎月提供，她是一位驻扎在西部荒野的特工，负责指挥联盟冒险者直接打击迪菲亚潜行者的据点。",al={"谁给予死亡矿井的破坏行动任务","死亡矿井引爆任务发布者","阿尔芭·皎月任务"}},{q="这项任务的主要目标是什么？",a="你使用引爆器来引爆安放在死亡矿井中迪菲亚潜行者熔炉旁的炸药，在与阿尔芭·皎月汇合后，从矿井外将它们引爆。",al={"在死亡矿井的破坏行动中做什么","死亡矿井的破坏行动目标","如何完成死亡矿井的破坏行动"}},{q="为什么要用炸药攻击死亡矿井？",a="阿尔芭·皎月追踪到污染西部荒野农田的毒素源自隐藏在死亡矿井中的大型冶金熔炉。摧毁它，是她让这片土地开始恢复的希望。",al={"为什么要炸毁死亡矿井","死亡矿井破坏行动背景","为什么要使用死亡矿井引爆器"}},{q="这个任务发生在哪里？",a="它发生在西部荒野，即死亡矿井外月溪镇后方的山丘上，安放好炸药后，阿尔芭·皎月会在那里等你。",al={"死亡矿井的破坏行动地点","死亡矿井的破坏行动在哪里","死亡矿井引爆器位置"}},{q="部落玩家可以接取这个任务吗？",a="不能。阿尔芭·皎月只与联盟特工合作，共同防卫西部荒野，抵御迪菲亚潜行者日益增长的威胁。",al={"死亡矿井的破坏行动是联盟专属吗","部落可以做死亡矿井的破坏行动吗"}},{q="迪菲亚潜行者在西部荒野构成了什么威胁？",a="迪菲亚潜行者驱逐了农民，袭击了定居点，并占领了西部荒野废弃的矿井。他们在死亡矿井深处活动，正在集结武装叛乱，直接威胁着暴风城王国。",al={"迪菲亚西部荒野背景","为什么要对抗迪菲亚","迪菲亚在死亡矿井做什么"}}},fp="24,158,25.344.0,13.261.0,46.95.0,46.145.0,41.169.0,33.115.0,43.99.0,57.209.0"}
P.entries["quest:92834"] = {n="Avenged Tenfold",s="Avenged Tenfold的核心人物是高阶会的学者Elaadrin，他曾试图通过和平谈判解决一场邪教暴力事件。在他的特使兼挚友Belathaan Brightwish被奥拉凯斯邪教残忍杀害后，Elaadrin放弃了外交手段，转而对瓦拉纳尔以北的邪教徒展开了迅速而猛烈的魔法报复。",h="Avenged Tenfold的核心人物是高阶会的学者Elaadrin，他曾试图通过和平谈判解决一场邪教暴力事件。在他的特使兼挚友Belathaan...",kw={"奥拉凯斯","十倍奉还","贝拉萨恩·明愿","艾拉德林","古斯贝里田野","高阶会","阿基尔神殿","塑风者","风石护符"},ang={["class:Mage"]="Elaadrin在受到挑衅时会引导噼啪作响的奥术力量，这强调了高阶会对逻辑的执着背后有着强大的魔法力量支持。"},sec={{t="外交提议",b="当奥拉凯斯邪教发动暴力活动时，像维和者（Peacekeepers）和塑风者这样的势力纷纷采取了武装姿态。代表高阶会的Elaadrin认为这种咄咄逼人的表现是愚蠢的升级行为。秉持高阶会务实和避免冲突的原则，Elaadrin认为理性的对话仍有可能，于是派遣了他的挚友Belathaan Brightwish前往阿基尔神殿进行和平谈判。"},{t="残忍的拒绝",b="邪教徒以恐怖的残暴行径回应了Elaadrin的外交提议。一个包裹被送了过来，里面装着Belathaan被割下的舌头，上面涂满了银色颜料。惊恐万分且背负着愧疚的Elaadrin意识到，保持高姿态反而害死了他的挚友。他承认塑风者拒绝谈判的决定是正确的，于是彻底放弃了外交手段，并命令旅行者们前往古斯贝里田野（Gustberry Fields）和阿基尔神殿猎杀邪教徒，收集他们的奥拉凯斯风石护符（Al'Aketh Windstone Charms）。"},{t="审慎与奥术之怒",b="高阶会推崇逻辑胜过情感，认为避免流血冲突几乎总是审慎的途径。然而，Elaadrin证明了当对手将克制误认为是软弱时，这种冷静的逻辑同样会带来反噬。他身上闪烁着噼啪作响的奥术能量，明确表示虽然高阶会更倾向于和平，但那些残杀他们特使的人必将面对毁灭性的报复。"}},faq={{q="艾拉德林是谁？",a="艾拉德林是高阶会的一名代表，最初试图与奥拉凯斯邪教寻求和平的外交解决方案。在特使兼挚友贝拉萨恩·明愿被谋杀后，艾拉德林放弃了外交手段，并下令消灭这些邪教徒。",al={"埃拉德林是谁","任务提供者 十倍奉还","谁发布了这个任务"}},{q="贝拉萨恩·明愿发生了什么事？",a="贝拉萨恩·明愿是艾拉德林的挚友，被派往阿基尔神殿作为特使，与奥拉凯斯邪教开启和平对话。邪教徒残忍地谋杀了他，并将一个装有他被割下的舌头（涂有银色颜料）的盒子送还给了艾拉德林。",al={"贝拉萨恩发生了什么","贝拉萨恩·明愿是谁","为什么贝拉萨恩死了"}},{q="奥拉凯斯邪教徒是什么人？",a="奥拉凯斯是一个在瓦拉纳尔以北活动的暴力邪教，活跃于古斯贝里田野和阿基尔神殿周围。他们随身携带被称为奥拉凯斯风石护符的祈祷护身符，并暴力拒绝外界的和平提议。",al={"谁是奥拉凯斯","谁是邪教徒","奥拉凯斯邪教"}},{q="什么是高阶会？",a="高阶会是一个以务实、智慧和逻辑为傲的组织。他们通常认为避免冲突和维护生命是最审慎的道路，尽管在遭到冒犯时，他们也有能力施展猛烈的魔法报复。",al={"什么是高阶会","高阶会信仰"}},{q="谁是塑风者？",a="塑风者和维和者是最初对奥拉凯斯邪教的暴力行为做出武力展示和姿态回应的势力。虽然艾拉德林最初批评他们的反应是鲁莽的升级行为，但他最终承认他们拒绝外交呼吁是正确的。",al={"谁是塑风者","塑风者 维和者"}},{q="奥拉凯斯邪教徒在哪里可以找到？",a="奥拉凯斯邪教徒聚集在瓦拉纳尔以北，特别是古斯贝里田野和阿基尔神殿周围，那里正是贝拉萨恩·明愿在遇害前被派往的地方。",al={"阿基尔神殿在哪里","古斯贝里田野在哪里","邪教徒在哪里"}}},fp="15,227,23.376.0,20.443.1,25.341.0,16.209.0,38.249.0,30.223.0,23.186.0,24.239.0,38.164.0"}
P.entries["quest:92840"] = {n="Catching Wind",s="Catching Wind是高阶会前往申达尔高地瞰台立石的一次探险。一名特工携带秘典目录，在传统主义者塑风者的激烈、暴力反对下，被派往从古代风石构造中提取元素能量读数。",h="Catching Wind是高阶会前往申达尔高地瞰台立石的一次探险。一名特工携带秘典目录，在传统主义者塑风者的激烈、暴力反对下，被派往从古代风石构造中提取元素能量读数。",kw={"奥拉凯斯","捕风","菲利昂","高阶会","秘典目录","瞰台立石","申达尔高地","瓦拉纳尔","塑风者","风石构造","泽弗拉斯"},ang={["class:Mage"]="奥术学者和法师们很欣赏秘典目录的分析功能，他们将元素现象视为奥术研究中可测量的领域。",["class:Shaman"]="萨满祭司可能会发现自己在塑风者对元素洪流的崇敬与高阶会对原始元素力量的临床式提取之间感到左右为难。"},sec={{t="测量狂风",b="高阶会试图测量并理解在申达尔高地奔涌的混乱元素流。为了揭开瞰台立石内蕴藏的秘密，研究人员制造了秘典目录，这是一种旨在从巨大的风石构造中提取数据的精密工具。虽然高阶会将他们的工作描述为拯救Zephras所必需的重要研究，但当地的传统主义者将这些学术探测视为对风的亵渎与冒犯。"},{t="教条与探究的碰撞",b="高阶会的探险队与塑风者在这些立石处迅速爆发了紧张局势。塑风者将对元素能量的研究与提取视为对他们神圣传统的公然亵渎。高阶会认为塑风者和暴力的奥拉凯斯一样，在教条上狭隘固执，他们拒绝让当地人的抵抗阻碍自己拯救国度的任务。"},{t="立石大屠杀",b="当高阶会在瞰台立石的工作遭遇敌对抵抗时，武力便不可避免。随之而来的冲突导致风石间血流成河。尽管高阶会利用秘典目录成功获取了读数，但塑风者谴责这一事件为大屠杀，加剧了笼罩在瓦拉纳尔城上的激烈宿怨。"}},faq={{q="任务捕风的内容是什么？",a="捕风是一项代表高阶会执行的任务，旨在研究申达尔高地瞰台立石周围的元素能量。冒险者受命携带秘典目录，尽管面临塑风者的敌对阻挠，仍需从巨大的风石构造中提取关键数据。",al={"什么是捕风","捕风任务"}},{q="什么是秘典目录？",a="秘典目录是高阶会使用的一种专业测量仪器。它旨在直接从瞰台立石发现的巨大风石构造中提取、测量并记录元素能量数据。",al={"什么是秘典目录","秘典目录装置"}},{q="塑风者是谁？",a="塑风者是一个极力保护其圣地以及有关元素魔法的传统信仰的派系。他们将高阶会的学术研究和技术设备视为亵渎，并积极防御风石构造，抵御外部入侵。",al={"谁是塑风者","塑风者背景"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是一个被高阶会与塑风者一同提及的极端暴力组织。高阶会称奥拉凯斯是两者中更为暴力的一方，但他们将这两个派系都视为受困于错误且僵化教条的危险狂热分子。",al={"谁是奥拉凯斯","奥拉凯斯"}},{q="瞰台立石位于何处？",a="瞰台立石位于申达尔高地内。该地点以拥有引导强大元素洪流的巨大风石构造而闻名，使其成为高阶会的一个关键研究地点。",al={"瞰台立石在哪里","瞰台立石位置"}},{q="菲利恩是谁？",a="菲利恩是高阶会的一名特工或研究员，最初被派往瞰台立石测量和研究元素能量。由于与塑风者的冲突，必须派遣一名带着秘典目录的冒险者来获取数据。",al={"菲利昂发生了什么","谁是菲利昂"}},{q="高阶会为何需要风石数据？",a="高阶会认为，理解这个国度的元素力量对于他们拯救泽风岛的宏大任务至关重要。他们认为科学探究对于克服传统信仰无法解决的元素威胁是必不可少的。",al={"高阶会为何需要数据","拯救泽弗拉斯"}}},fp="13,177,19.306.0,26.322.0,27.272.1,38.234.0,26.168.0,24.199.0,21.205.0,47.183.0,15.231.0,48.184.0"}
P.entries["quest:92849"] = {n="The Missing Scholar",s="“失踪的学者”讲述了寻找Fillion Flamebreeze的任务，这是一名研究员，在从瞰台立石执行完任务返回的途中失踪了。对小径的调查将线索指向了附近北部的一个洞穴，Fillion在那里被一只掠食性的带翼野兽拖走。",h="“失踪的学者”讲述了寻找Fillion Flamebreeze的任务，这是一名研究员，在从瞰台立石执行完任务返回的途中失踪了。对小径的调查将线索指向了附近北部的一个洞穴，Fillion在那里被一只掠食性的带翼野兽拖走。",kw={"菲利昂","菲利昂·焰风","瞰台立石","失踪的学者","塑风者","带翼野兽"},sec={{t="失踪的研究员",b="小径上不幸的迹象表明，学者Fillion Flamebreeze在旅途中遭遇了不测。顺着他失踪的线索向北追踪，可以通向一个黑暗洞穴的入口，失踪的研究员或许还在那里苟延残喘，等待着救援。"},{t="塑风者的伏击",b="Fillion Flamebreeze当时正从瞰台立石的学术任务中返回，却遭到了敌对的塑风者的伏击。袭击者对他进行了无情的殴打，然后将他拖到洞穴入口并弃之不顾，任由他流血不止，让他对潜伏在其中的任何威胁都毫无还手之力。"},{t="带翼野兽的巢穴",b="当Fillion在洞穴边缘奄奄一息时，一只巨大的带翼野兽从黑暗中出现，并将他拖了进去。那生物把他带到了巢穴深处，作为其幼崽的食物，若非及时的救援，他将难逃一死的厄运。"}},faq={{q="菲利恩·焰风是谁？",a="菲利恩·焰风是一名学者，他在从瞰台立石完成任务返回时遭到了敌对的塑风者的伏击。他被扔在附近的一个洞穴外流血昏迷，随后被一只巨大的带翼掠食者拖入洞中。",al={"菲利昂是谁","菲利昂·焰风","失踪的学者非玩家角色"}},{q="菲利恩在瞰台立石做什么？",a="瞰台立石是菲利昂·焰风在遭到伏击前进行学术任务的地点。虽然他在那里进行的研究的具体性质尚不明确，但他在从立石返回的途中直接陷入了塑风者的伏击。",al={"什么是瞰台立石","瞰台立石任务","菲利昂的任务"}},{q="是谁袭击了菲利昂·焰风？",a="菲利昂遭到了被称为塑风者的袭击者的伏击并被殴打。他们并没有直接杀死他，而是将他拖到附近一个洞穴的洞口，在他流血且几乎失去意识时将他弃之不顾。",al={"谁袭击了菲利昂","什么是塑风者","塑风者伏击"}},{q="是什么生物把菲利昂带进了洞穴？",a="一只筑巢在伏击点北侧洞穴中的巨大带翼野兽，从洞口抓走了昏迷的菲利昂。它将他拖入巢穴深处，作为自己和饥饿幼崽的食物。",al={"什么洞穴野兽","带翼怪物 菲利昂","是什么带走了菲利昂"}},{q="在哪里可以找到菲利昂·焰风？",a="在他遭遇不幸的地点留下的线索指向了位于正北方向的一个洞穴。在洞穴内搜寻可以发现菲利昂被困在野兽的筑巢地，等待着在被吞噬前获得救援。",al={"如何找到菲利昂","失踪的学者在哪里","菲利昂洞穴位置"}},{q="失踪学者的结局是什么？",a="多亏了洞穴内及时的干预，菲利昂才幸免于难。如果冒险者没有追踪到他并介入，他本会成为那只带翼野兽及其后代的盘中餐。",al={"菲利昂幸存了吗","菲利昂·焰风发生了什么","拯救失踪的学者"}}},fp="19,179,23.215.0,25.234.1,24.217.1,27.237.0,55.204.0,33.144.0,41.165.0,39.186.0,41.190.0"}
P.entries["quest:92850"] = {n="The Missing Scholar",s="The Missing Scholar是一个任务，在这个任务中，冒险者将在危险的巢穴附近找到学者Fillion Flamebreeze并为他提供援助。虽然Fillion安全返回了瓦拉纳尔，但他委托旅行者消灭威胁到定居点的附近的尖啸者巢穴主母。",h="The Missing Scholar是一个任务，在这个任务中，冒险者将在危险的巢穴附近找到学者Fillion...",kw={"菲利昂·焰风","尖啸者","尖啸者巢穴","尖啸者巢穴主母","至高魔导师","失踪的学者","瓦拉纳尔"},ang={["class:Mage"]="Fillion Flamebreeze依靠自己在奥术方面的训练来恢复并安全旅行，这显示了他与同行魔法使用者之间的相互情谊。"},sec={{t="危险的巢穴",b="在从掠食性野兽巢穴附近的苦难中恢复过来后，学者Fillion Flamebreeze发现自己可以动身返回安全的瓦拉纳尔。然而，迫在眉睫的威胁不容忽视：一窝尖啸者在距离定居点非常近的地方筑了巢。Flamebreeze不愿让这些野兽徘徊在城镇门口，于是请求有能力的旅行者进入尖啸者巢穴，杀死尖啸者巢穴主母。"},{t="向大魔导师汇报",b="一旦主母被杀，并将她的头颅带回瓦拉纳尔交给Fillion，学者表示了感谢，但他忧心忡忡地指出，这些尖啸者只不过是他们麻烦中最小的一个。在将注意力转向更大的问题之前，Flamebreeze准备直接向The Supreme Magister提交关于他的任务和周边地区的完整报告。"}},faq={{q="菲利昂·焰风是谁？",a="菲利昂·焰风是一位精通奥术的学者，他在瓦拉纳尔附近执行任务时，发现自己被困在了一窝危险野兽的巢穴附近。",al={"谁是菲利昂·焰风","谁是那位学者","谁发布了失踪的学者任务"}},{q="什么是尖啸者？",a="尖啸者是敌对的野兽，它们在距离瓦拉纳尔定居点危险地近的地方筑了巢。菲利昂·焰风警告说，它们的接近使它们对该地区的任何旅行者都构成了直接威胁。",al={"什么是尖啸者","尖啸者在哪里筑巢","尖啸者威胁"}},{q="至高魔导师是谁？",a="至高魔导师是瓦拉纳尔的地区权威，菲利昂·焰风必须向其汇报关于巢穴事件和其任务状态的情况。",al={"谁是至高魔导师","菲利昂的报告","菲利昂向谁负责"}},{q="什么是瓦拉纳尔？",a="瓦拉纳尔是菲利昂·焰风驻扎的附近定居点或前哨站，他在恢复到可以独自旅行后回到了那里。",al={"什么是瓦拉纳尔","瓦拉纳尔在哪里"}},{q="什么是尖啸者巢穴主母？",a="尖啸者巢穴主母是筑巢在尖啸者巢穴内的尖啸者的首领。菲利昂委托冒险者杀死她并带回她的头颅，以消除对瓦拉纳尔的直接威胁。",al={"尖啸者巢穴主母目标","在尖啸者巢穴中要杀谁"}},{q="为什么菲利昂认为尖啸者是他们麻烦中最小的一个？",a="虽然菲利昂·焰风认为尖啸者因其接近而对瓦拉纳尔构成了直接威胁，但当您回来时，他意味深长地指出，它们终究只是他们麻烦中最小的一个。",al={"为什么是最小的麻烦","瓦拉纳尔更大的危险"}}},fp="19,163,25.263.0,25.226.1,27.156.0,21.128.0,28.157.0,17.118.0,33.171.0,70.152.0"}
P.entries["quest:92860"] = {n="In Service of Zephras",s="“In Service of Zephras”是一个任务，任务中冒险者受高阶会之托，传达他们对瓦拉纳尔的全力军事和外交支持，以对抗奥拉凯斯邪教。岛上不断升级的敌对行动迫使高阶会放弃了避免与邪教徒直接对抗的方针。在将消息传达给瓦伦妮亚·风拳（Valennia Stormfist）时，特使还带来了一个关于她表亲贝拉森（Belathaan）去世的噩耗，这巩固了双方保护泽风岛人民的共同决心。",h="“In Service of...",kw={"奥拉凯斯","贝拉森","奥拉凯斯邪教","高阶会","为泽弗拉斯效力","风拳","瓦拉纳尔","瓦伦妮亚·风拳","泽风岛"},sec={{t="日益增长的威胁",b="曾几何时，高阶会试图最大限度地减少与神秘的奥拉凯斯邪教之间的公开敌对，试图防止整个岛屿爆发全面战争。但随着邪教表现出毫无疑问的敌意，加上大规模部队调动的惊人报告，这种脆弱的立场随之崩溃。高阶会意识到邪教徒正在集结力量进行一项威胁到每个定居点和平与安全的行动，因此决定采取果断措施。与其坐视不管，他们决定将自己的力量投入到积极的联盟中，并派遣一名特使在奥拉凯斯发动袭击之前与当地防御者进行协调。"},{t="与瓦拉纳尔结盟",b="为了应对日益严重的邪教威胁，特使被派往瓦伦妮亚·风拳处，正式提出高阶会将无条件协助瓦拉纳尔抵御奥拉凯斯。双方的联络在两个派系之间建立了统一的防御阵线，为整个地区的联合军事行动铺平了道路。然而，这项任务也带来了沉重的个人代价：在抵达后，旅行者必须传达关于贝拉森（瓦伦妮亚的表亲，也是泽风岛的忠实仆人）去世的消息。在哀悼他的离去时，瓦伦妮亚发誓要复仇，将共同的悲痛转化为对即将到来的战役的即时准备。"}},faq={{q="任务“为泽弗拉斯效力”是关于什么的？",a="“为泽弗拉斯效力”任务要求玩家代表高阶会向瓦伦妮亚·风拳报告。高阶会此前曾试图避免与奥拉凯斯邪教发生直接暴力冲突，但不断升级的敌意和关于岛上大规模邪教部队调动的报告迫使他们出手。该任务确立了高阶会对瓦拉纳尔防御的正式支持，同时也传达了关于贝拉森命运的庄严消息。",al={"为泽弗拉斯效力 概览","为泽弗拉斯效力 剧情","为泽弗拉斯效力 任务"}},{q="瓦伦妮亚·风拳是谁？",a="瓦伦妮亚·风拳是瓦拉纳尔负责协调抵御奥拉凯斯防御工作的领袖。当高阶会派遣特使承诺效忠时，瓦伦妮亚接受了相互援助的提议。她也是贝拉森（一名牺牲的泽风岛仆人）的表亲，在这次交流中传达了贝拉森的死讯，促使她发誓要向威胁他们人民的邪教徒复仇。",al={"瓦伦妮亚·风拳背景","瓦伦妮亚是谁","瓦伦妮亚·风拳"}},{q="贝拉森是谁？",a="贝拉森是瓦伦妮亚·风拳的表亲，也是一位尽职尽责的泽风岛仆人，他在本次任务事件发生前已经牺牲。瓦伦妮亚将他铭记为一位光荣的仆人和事业的捍卫者。当冒险者向瓦伦妮亚报告时，他的死讯被正式确认，加深了冲突的个人风险，并巩固了为他复仇的誓言。",al={"贝拉森是谁","贝拉森背景","贝拉森发生了什么"}},{q="奥拉凯斯是什么？",a="奥拉凯斯是一个活跃在岛上的敌对邪教，其侵略性的调动威胁到了泽风岛的人民。尽管高阶会最初试图避免挑起与他们的直接对抗，但最近的敌对表现和关于广泛邪教活动的令人担忧的报告使得战争不可避免。他们的扩张迫使当地势力和高阶会结成武装联盟以击退他们。",al={"奥拉凯斯是谁","奥拉凯斯邪教","什么是奥拉凯斯"}},{q="高阶会在这次冲突中扮演什么角色？",a="高阶会最初试图避免与奥拉凯斯邪教进行直接战争，倾向于采取克制的方法。然而，侵略性的行动和关于大规模邪教动员的谣言使他们的领导层确信中立已不再可行。通过派遣一名信使给瓦伦妮亚·风拳，高阶会正式承诺投入全部力量支持瓦拉纳尔抵御邪教的军事抵抗。",al={"高阶会参与","高阶会为什么战斗","高阶会与泽风岛"}},{q="泽风岛是什么？",a="泽风岛是高阶会、瓦拉纳尔及其防御者共同奋力保卫的岛屿。高阶会明确警告说，日益增长的邪教活动对泽风岛人民来说是一个不祥之兆，而像贝拉森这样的牺牲英雄被铭记为泽风岛忠诚的仆人。保护其民众是结盟对抗奥拉凯斯的主要理由。",al={"泽风岛在哪里","泽风岛是谁","泽风岛背景"}}},fp="21,194,20.378.0,22.413.1,46.324.0,26.251.0,18.227.0,21.223.0,47.266.0,16.284.0"}
P.entries["quest:92867"] = {n="Ground to Keep",s="园丁 Lomar 请你将入侵者赶出激流堡。王国仅存的雕像和神圣墓地需要保护。",h="园丁 Lomar 请你将入侵者赶出激流堡。王国仅存的雕像和神圣墓地需要保护。",kw={"石拳","墓地","守护土地","园丁 lomar","雕像","激流堡","辛迪加","枯木"},sec={{t="王国的遗存",b="在激流堡，园丁 Lomar 请你击退石拳、辛迪加和枯木入侵者。他说激流堡还有更多储备，必须将其藏起来以保护自身。如今，越来越多人支持保护王国仅存的雕像和神圣墓地。"}},faq={{q="谁在寻求帮助？",a="园丁 Lomar 请你将石拳、辛迪加和枯木入侵者赶出激流堡。",al={"谁需要帮助","园丁 lomar","谁发布了任务"}},{q="为什么应该保护激流堡的遗存？",a="越来越多人支持保护激流堡仅存的雕像和神圣墓地。",al={"为何保护激流堡","需要保护什么","保护雕像"}},{q="哪些入侵者占据了激流堡？",a="石拳、辛迪加和枯木已在激流堡安家。",al={"谁在堡内","激流堡的敌人","石拳辛迪加枯木"}},{q="什么必须藏起来？",a="Lomar 说激流堡还有更多储备，必须将其藏起来以保护自身。",al={"隐藏了什么","激流堡的储备","什么必须保密"}}},fp="14,149,19.307.0,23.112.0,47.96.0,39.86.0,24.92.0"}
P.entries["quest:92871"] = {n="In Service of Zephras",s="Zephras各地传来消息，奥拉凯斯教团正集结力量，准备迎接一场重大冲突。为加强岛上的防御，一名使者奉命前往安抚Valennia Stormfist，告知她塑风者已准备好支援维和者。",h="Zephras各地传来消息，奥拉凯斯教团正集结力量，准备迎接一场重大冲突。为加强岛上的防御，一名使者奉命前往安抚Valennia Stormfist，告知她塑风者已准备好支援维和者。",kw={"奥拉凯斯","为泽弗拉斯效力","瓦拉纳尔","瓦伦妮娅·风暴之拳","塑风者","泽弗拉斯"},sec={{t="岛上传闻",b="Zephras岛上的局势日益紧张，各方报告显示教团活动遍及全岛。Valennia Stormfist麾下的维和者长期守卫着这片土地，但奥拉凯斯似乎正在为一场更大规模的冲突做准备。为确保岛屿安全，塑风者已承诺，一旦爆发敌对行动，便会坚定地与瓦拉纳尔的部队并肩作战。"},{t="承诺支援",b="你奉命前去会见Valennia Stormfist，确认塑风者已做好充分准备，随时可以援助她的维和者。得知盟友已准备就绪后，Valennia欣然接受这份及时的承诺，并准备商讨教团日益恶化的局势。"}},faq={{q="瓦伦妮亚·风拳是谁？",a="瓦伦妮亚·风拳领导着负责守护泽弗拉斯的维和者。她统筹岛上的防御，包括瓦拉纳尔对抗敌对教团奥拉凯斯的行动。",al={"瓦伦尼娅·风暴之拳是谁","瓦蕾妮娅·风暴之拳"}},{q="塑风者是谁？",a="塑风者是泽弗拉斯上的盟友团体，他们协助瓦伦妮亚·风拳及其维和者。他们全力支持瓦拉纳尔的部队，共同对抗日益加剧的奥拉凯斯威胁。",al={"塑风者是什么","塑风者背景"}},{q="奥拉凯斯是什么？",a="奥拉凯斯是一个在泽弗拉斯全岛活动的教团。有报告称，他们正在扩大行动规模，并为即将到来的冲突做准备。",al={"奥拉凯斯是谁","奥拉凯斯是什么","奥拉凯斯教团"}},{q="泽弗拉斯是什么？",a="泽弗拉斯是一座由瓦伦妮亚·风拳及其维和者守卫的岛屿，塑风者在此协助抵御奥拉凯斯教团带来的威胁。",al={"泽风是什么","泽风岛"}},{q="瓦拉纳尔是什么？",a="瓦拉纳尔是泽弗拉斯上的一处定居点，也是瓦伦妮亚·风拳麾下维和者的驻地。塑风者全力支持这里对抗奥拉凯斯。",al={"瓦拉纳尔是什么","瓦拉纳尔是谁"}}},fp="21,167,20.279.0,16.208.0,26.148.0,24.175.0,22.115.0,16.125.0,17.144.0"}
P.entries["quest:92872"] = {n="Dutiful Steps",s="看护者奥拉瑞克请你把墓尘从激流堡墓穴带到海边。这场仪式让对阵亡者的纪念循环得以延续。",h="看护者奥拉瑞克请你把墓尘从激流堡墓穴带到海边。这场仪式让对阵亡者的纪念循环得以延续。",kw={"看护者奥拉瑞克","仪式","墓穴","尽忠职守","阵亡者","无尽之海","装着墓尘的袋子","激流堡","墓尘"},sec={{t="奔向大海",b="你返回阳光世界的旅程，从一个小袋子开始。看护者奥拉瑞克请你把它带到激流堡后方的悬崖，将里面的东西撒入无尽之海。墓尘取自堡垒下方的墓穴，那里的守墓者守护着纪念阵亡者的仪式。每个季节，都会有一些墓尘撒入艾泽拉斯的海洋，象征着记忆循环的延续。"}},faq={{q="是谁请我运送墓尘？",a="看护者奥拉瑞克请你把墓尘从激流堡墓穴带到海边。",al={"谁给了我这个","奥拉瑞克的请求"}},{q="袋子里装着什么？",a="袋子里装着激流堡下方墓穴中的墓尘。",al={"袋子里有什么","墓尘"}},{q="为什么要把墓尘撒入海中？",a="每个季节，都会有一些墓尘撒入艾泽拉斯的海洋，象征着循环的延续。",al={"为什么把尘土撒进海里","这些尘土有什么用"}},{q="我应该在哪里撒下袋子里的东西？",a="看护者奥拉瑞克请你从激流堡后方的悬崖上，将墓尘撒入无尽之海。",al={"该在哪里撒下它","激流堡后方的悬崖"}},{q="墓穴的守墓者守护着什么？",a="墓穴的守墓者守护着用于纪念阵亡者的仪式知识。",al={"墓穴里有什么","仪式"}}},fp="13,142,14.371.0,35.91.0,23.61.0,43.101.0,37.106.0,40.87.0"}
P.entries["quest:92880"] = {n="Return to Valanaar",s="“Return to Valanaar”是一个任务，要求冒险者将尤娜关于东部哨塔防御情况的报告送回瓦拉纳尔，交给瓦蕾妮亚·风拳。这份报告确认了防线已经稳固，残余的敌军正在被肃清，这为该定居点的领导层带来了极大的宽慰。",h="“Return to Valanaar”是一个任务，要求冒险者将尤娜关于东部哨塔防御情况的报告送回瓦拉纳尔，交给瓦蕾妮亚·风拳。这份报告确认了防线已经稳固，残余的敌军正在被肃清，这为该定居点的领导层带来了极大的宽慰。",kw={"东部哨塔","四风","返回瓦拉纳尔","瓦拉纳尔","瓦蕾妮亚·风拳","尤娜","尤娜的报告"},ang={["race:Skyborne"]="这种祈求四风祝福的行为反映了瓦拉纳尔的守卫者和领导者之间常见的文化和精神纽带。"},sec={{t="来自哨所的消息",b="在哨所遭遇猛烈袭击后，守卫者尤娜向瓦拉纳尔定居点发出了消息。随着进攻部队溃败，剩余的敌对势力正在被清理，一名冒险者受命带着“尤娜的报告”前往，以安抚在镇中焦急等待消息的领导层。"},{t="瓦拉纳尔的宽慰",b="这份急报直接传达给瓦拉纳尔的瓦蕾妮亚·风拳，说明了东部哨塔的情况。在确认哨塔守住了阵地且防线稳固后，瓦蕾妮亚明显松了一口气，感谢风神的庇佑，使得他们关键的前哨阵地得以保全。"}},faq={{q="是谁派你去瓦拉纳尔的？",a="该任务由尤娜在经历了一场艰难的防守战并击退敌对袭击者后发布，要求你将一份状态报告送回给领导层。",al={"谁发布返回瓦拉纳尔任务","谁派你回瓦拉纳尔","尤娜任务发布者"}},{q="你在瓦拉纳尔向谁报告？",a="瓦蕾妮亚·风拳驻守在瓦拉纳尔，等待着关于外围守卫者安全和作战状态的消息。",al={"谁是瓦蕾妮亚·风拳","瓦蕾妮亚·风拳在哪里","返回瓦拉纳尔交任务"}},{q="什么是“尤娜的报告”？",a="“尤娜的报告”包含了一份最新进展，确认了守卫者们已经稳固了防线，抵御了袭击，并正在清理残余的敌军。",al={"什么是尤娜的报告","尤娜的报告说了什么"}},{q="哪座哨塔受到了攻击？",a="尤娜及其部队所防守的哨所是东部哨塔，这是一个俯瞰瓦拉纳尔进军路线的关键防御阵地。",al={"哪座塔受到了攻击","尤娜在哪个哨塔"}},{q="东部哨塔目前的状况如何？",a="虽然还需要对残留的袭击者进行清剿，但守卫者们已经确保了阵地安全，哨塔局势被认为是稳定的。",al={"哨塔安全吗","守卫者赢了吗"}},{q="为什么守卫者会提到四风？",a="“愿四风指引你”这句话以及瓦蕾妮亚“感谢风神”的惊叹，表明了瓦拉纳尔的守卫者们对风和元素的文化崇敬。",al={"四风的含义","愿四风指引你"}}},fp="18,153,21.219.0,18.204.0,26.128.0,33.105.0,23.112.0,34.105.0,45.130.0,45.135.0"}
P.entries["quest:92881"] = {n="The High Elder's Request",s="“大长老的请求”派遣冒险者前往瓦拉纳尔咨询大长老塔拉尼斯·影歌，此前该地区的瞭望塔遭到了协同攻击。来自西侧瞭望塔的报告表明，一个敌对邪教正在以当地的锚点塔为目标。",h="“大长老的请求”派遣冒险者前往瓦拉纳尔咨询大长老塔拉尼斯·影歌，此前该地区的瞭望塔遭到了协同攻击。来自西侧瞭望塔的报告表明，一个敌对邪教正在以当地的锚点塔为目标。",kw={"锚点塔","东侧瞭望塔","影歌","空祭司","塔拉尼斯·影歌","大长老的请求","瓦拉纳尔","西侧瞭望塔"},ang={["class:Priest"]="邪教对锚点塔的兴趣，以及一名神秘的空祭司出现在西侧瞭望塔，这对研究神圣或仪式操纵的祭司来说是一个令人不安的事态发展。"},sec={{t="瞭望塔的麻烦",b="最近针对西侧和东侧瞭望塔的协同攻击揭示了一种令人不安的模式。起初看起来像是分散的小规模冲突，现在却指向了针对当地锚点塔的蓄意攻势。在西侧瞭望塔与一名空祭司的交锋中，报告首次揭露了该邪教对这些建筑的兴趣，促使当局将保卫瞭望塔视为当务之急。"},{t="瓦拉纳尔的觐见",b="意识到锚点塔面临的威胁正在升级，领导层指引冒险者直接前往瓦拉纳尔与大长老塔拉尼斯·影歌交谈。大长老掌握着关于该邪教动向的线索，正在寻求经验丰富的盟友准备追踪敌人，并挫败他们意图引发的任何仪式或破坏活动。"}},faq={{q="谁是大长老影歌？",a="大长老塔拉尼斯·影歌是一位位于瓦拉纳尔的领袖。面对该地区瞭望塔遭受的协同邪教活动，他正在寻求有能力的冒险者去追踪关于邪教真实意图的线索。",al={"谁是塔拉尼斯·影歌","大长老影歌","影歌在哪里"}},{q="瓦拉纳尔在哪里？",a="瓦拉纳尔是驻扎大长老塔拉尼斯·影歌的定居点或圣所，他在此协调防御并调查针对当地锚点塔和瞭望塔的邪教入侵。",al={"什么是瓦拉纳尔","瓦拉纳尔位置"}},{q="为什么瞭望塔会遭到攻击？",a="协同攻击同时打击了西侧和东侧瞭望塔。防卫者怀疑这些攻击并非随机的突袭，而是旨在针对或操纵附近锚点塔的蓄意行动。",al={"为什么瞭望塔会遭到攻击","西侧和东侧瞭望塔","瞭望塔袭击"}},{q="什么是锚点塔？",a="锚点塔是关键的防御性或区域性建筑。从西侧瞭望塔的袭击中收集的情报表明，一个敌对邪教正试图专门干扰或颠覆它们。",al={"什么是锚点塔","邪教锚点塔","为什么针对锚点塔"}},{q="西侧瞭望塔的空祭司是谁？",a="一名空祭司参与了西侧瞭望塔的事件。从那次遭遇中报告的细节让领导层推断出了该邪教关于锚点塔的更大阴谋。",al={"空祭司是谁","西侧瞭望塔空祭司","空祭司职责"}},{q="哪个邪教在针对瞭望塔？",a="一个激进的邪教策划了针对该地区瞭望塔的同步袭击。随着大长老影歌致力于揭开他们的计划，这些人的确切性质和更深层的动机仍在调查中。",al={"这是什么邪教","谁袭击了瞭望塔"}}},fp="24,213,26.339.0,20.266.0,29.188.0,18.159.0,34.160.0,27.166.0,48.177.0,39.179.0"}
P.entries["quest:929"] = {n="大地之冠",s="大地之冠是一项神圣的任务，由多兰纳尔的科瑞萨斯·月怒委派，要求从星风村附近的月亮井中汲取圣水。作为补充达纳苏斯水源的交换，年轻的暗夜精灵们将了解那段导致他们的人民培育泰达希尔巨枝的悲惨历史。",h="大地之冠是一项神圣的任务，由多兰纳尔的科瑞萨斯·月怒委派，要求从星风村附近的月亮井中汲取圣水。作为补充达纳苏斯水源的交换，年轻的暗夜精灵们将了解那段导致他们的人民培育泰达希尔巨枝的悲惨历史。",kw={"科瑞萨斯·月怒","大地之冠","多兰纳尔","翡翠瓶","月亮井","诺达希尔","星风村","泰达希尔"},ang={["class:Druid"]="月亮井是自然与星界魔法的重要管道，作为活体水库，将你们教派在达纳苏斯的职责与泰达希尔的根系紧密联系在一起。",["race:NightElf"]="每一位暗夜精灵都必须面对失去永生和玛法里奥·怒风失踪的事实，这使得这项神圣的收集仪式成为你们种族近期悲伤史中不可或缺的一课。"},sec={{t="维持月亮井",b="达纳苏斯中央那座宏伟的月亮井需要时刻与世界之树树冠上散布的较小源泉保持联通。德鲁伊们专门制作了精致的翡翠瓶，用于汲取和运送这些发光的圣水，同时不破坏其纯净。通过派遣新兵徒步前往星风村，长者们不仅确保了市政喷泉始终盈满艾露恩的恩泽，也确保了年轻一代了解培育泰达希尔所需的艰辛劳动。"},{t="海加尔山之战的回响",b="完成这项琐事会获得口述历史作为奖励。科瑞萨斯·月怒会讲述海加尔山之战结束后卡多雷所经历的绝望。先祖之树诺达希尔的牺牲剥夺了暗夜精灵宝贵的永生。在废墟之中，伊利丹·怒风被释放，而珊蒂斯·玛法里奥·怒风却失踪了。这种悲伤与孤立的氛围，为后来饱受争议的泰达希尔种植计划奠定了基础。"}},faq={{q="汲取月亮井水的目的是什么？",a="居住在达纳苏斯的德鲁伊们会定期使用从周围森林神龛收集的水来补充城市的主要月亮井，从而维持泰达希尔上神圣的魔法网络。",al={"为什么要取月亮井水","月亮井水的用途","翡翠瓶的作用"}},{q="这项任务的月亮井位于何处？",a="月亮井坐落在星风村外，位于多兰纳尔以东，沿着森林小径即可到达。",al={"月亮井在哪里","星风村月亮井位置","星风村之井"}},{q="谁是科瑞萨斯·月怒？",a="科瑞萨斯·月怒是一位驻扎在多兰纳尔的暗夜精灵，他指引年轻的冒险者们完成与泰达希尔健康状况相关的仪式职责，并向他们传授相关历史。",al={"谁发布了任务","科瑞萨斯·月怒的背景故事"}},{q="科瑞萨斯在返回时传授什么历史？",a="他解释了海加尔山之战后的灾难性后果，回述了诺达希尔如何被焚毁，卡多雷的永生如何消失，伊利丹如何被释放，以及珊蒂·玛法里奥·怒风如何失踪。",al={"科瑞萨斯说了什么","大地之冠背景文本"}},{q="为什么暗夜精灵在海加尔山之后感到迷茫？",a="诺达希尔曾赋予暗夜精灵永恒的生命与庇护。牺牲这棵树的力量来消灭阿克蒙德摧毁了他们永恒的存在，使他们变得终有一死、迷失方向且极度脆弱。",al={"精灵为什么失去永生","海加尔山之后发生了什么"}},{q="什么是珊蒂（珊多）？",a="珊蒂（珊多）是达纳苏斯语中的一个尊称，意为“受人尊敬的导师”，此处用于称呼德鲁伊的最高领袖玛法里奥·怒风。",al={"珊蒂是什么意思","珊蒂的含义"}}},fp="18,215,24.445.0,23.359.0,46.138.0,44.90.0,26.151.0,46.194.0,47.202.0,18.122.0"}
P.entries["quest:92909"] = {n="Harvesting the Harvesters",s="Harvesting the Harvesters是西部荒野的一项当地任务，玩家需要协助被困在萨丁农场一处马厩里的到访侏儒修补匠奥兹温·铁轮。在低估了该地区失控的收割机傀儡的凶猛程度后，奥兹温需要回收一些机械零件来制造一个逃生装置。",h="Harvesting the...",kw={"傀儡等压弹簧","收割机傀儡","收割机陀螺稳定器","收割收割者","铁炉堡","奥兹温·铁轮","萨丁农场","西部荒野"},ang={["faction:Alliance"]="前往萨丁农场的联盟旅行者可以帮助一位到访的侏儒学者，他因误判而试图解决西部荒野的机械瘟疫，结果却被困在了那里。",["profession:Engineering"]="从失控的收割机傀儡身上收割等压弹簧和陀螺稳定器等复杂零件，是发明功能性逃生装置所需的关键原材料。",["race:Gnome"]="奥兹温·铁轮体现了侏儒对修补复杂机械的典型雄心，尽管低估了机械的攻击性导致他被困在农场马厩中。"},sec={{t="一次误判的努力",b="西部荒野的农业平原已经陷入混乱，不仅被亡命之徒占领，还遭到了失控的机械收割机的蹂躏。关于这些失控自动机械的消息传到了铁炉堡的技术工坊，激励了侏儒工程师奥兹温·铁轮南下。奥兹温对自己精湛的技艺充满信心，他相信自己能够诊断并重新校准这些误入歧途的农用机械，从而让该地区饱受蹂躏的农田恢复平静。"},{t="困在马厩",b="在抵达萨丁农场周围的田野后，奥兹温很快发现收割机傀儡远比理论图纸上描述的更加不稳定和暴力。机器锋利的刀片和不规则的挥舞迫使这位侏儒逃命到附近的马厩中。由于被困住无法进入田野，奥兹温只能依靠勇敢的冒险者从这些机械恐怖中回收可用的等压弹簧和陀螺稳定器，以便组装一个装置来安全逃脱。"}},faq={{q="奥兹温·铁轮是谁？",a="奥兹温·铁轮是一位从铁炉堡前往西部荒野的侏儒修补匠，他怀揣着校准失控收割机傀儡的雄心壮志。然而，这些傀儡极度的敌意迫使他在萨丁农场的马厩里躲避。",al={"奥兹温·铁轮是谁","奥兹温","任务发布者"}},{q="为什么收割机傀儡如此具有攻击性？",a="徘徊在西部荒野废弃田野上的机械收割机傀儡变得极其狂暴，对路人充满敌意。虽然奥兹温希望通过常规校准来修复它们的故障，但它们的凶猛程度远超出了他的计算。",al={"为什么收割机会攻击","为什么傀儡具有攻击性","收割机出了什么问题"}},{q="在哪里可以找到奥兹温·铁轮？",a="奥兹温·铁轮躲在西部荒野萨丁农场的一个马厩里，躲避着附近田野中徘徊的危险收割机傀儡。",al={"奥兹温·铁轮在哪里","收割收割者交任务地点","奥兹温位置"}},{q="奥兹温打算用收集的零件制造什么？",a="奥兹温需要傀儡等压弹簧和收割机陀螺稳定器来制造一个紧急机械装置，这将为他安全逃离马厩提供足够的掩护。",al={"奥兹温需要零件做什么","为什么要收集等压弹簧","逃生装置零件"}},{q="奥兹温为什么要从铁炉堡前往西部荒野？",a="被失控机械在西部荒野乡间肆虐的消息所吸引，奥兹温从矮人首都铁炉堡长途跋涉而来，相信他精湛的修补技艺能够成功校准这些失控的自动机械。",al={"奥兹温为何来到西部荒野","为何离开铁炉堡"}},{q="所需的傀儡零件从哪里获得？",a="等压弹簧和陀螺稳定器直接从徘徊在萨丁农场周围西部荒野农田里的敌对收割机傀儡和收割机身上回收。",al={"零件掉落位置","如何获得等压弹簧和陀螺稳定器"}}},fp="25,156,24.307.0,20.345.0,26.178.0,41.190.0,38.124.0,57.134.0,48.158.0,44.135.0"}
P.entries["quest:92910"] = {n="Harvesting the Harvesters",s="从收割机上回收的零件可能会让研究麦田傀儡的人感兴趣。你被要求将它带给萨丁农场的Ozwin Ironsprocket。",h="从收割机上回收的零件可能会让研究麦田傀儡的人感兴趣。你被要求将它带给萨丁农场的Ozwin Ironsprocket。",kw={"麦田傀儡","收割机","harvesting the harvesters","ozwin ironsprocket","precessive autocognition assembly","萨丁农场","回收的零件"},sec={{t="回收的零件",b="萨丁农场或许有人想检查你从收割机上回收的零件。它看起来大体完好，Ozwin Ironsprocket正等着查看它。"}},faq={{q="我要给Ozwin带去什么？",a="你要将Precessive Autocognition Assembly带给Ozwin Ironsprocket，这是从收割机上回收的一个零件。",al={"收割机零件","什么物品","autocognition assembly"}},{q="我要把回收的零件带到哪里？",a="将Precessive Autocognition Assembly带给萨丁农场的Ozwin Ironsprocket。",al={"ozwin在哪里","萨丁农场","带到哪里"}},{q="为什么会有人想要这个零件？",a="回收的零件看起来大体完好，对麦田傀儡感兴趣的人或许想看看它。",al={"为什么是收割机","谁想要这个","对收割机的兴趣"}}},fp="25,141,15.156.0,24.101.0,35.84.0,32.101.0"}
P.entries["quest:92911"] = {n="Harvesting the Harvesters",s="在萨丁农场，Ozwin Ironsprocket需要一些零件，用来制作能短暂接管收割机系统的装置。你收集他所需的零件时，他会继续组装。",h="在萨丁农场，Ozwin Ironsprocket需要一些零件，用来制作能短暂接管收割机系统的装置。你收集他所需的零件时，他会继续组装。",kw={"copper modulators","crude scope","装置","golem isosprings","收割机","harvesting the harvesters","ozwin ironsprocket"},sec={{t="Ozwin所需的零件",b="萨丁农场的Ozwin Ironsprocket正在研究收割机的运作原理。他相信自己能短暂接管它们的系统。你正在为他的装置收集零件，而他则继续埋头组装。"},{t="完工的装置",b="Ozwin完成了装置，请你试用。他留在农场，这里开始让他有了家的感觉。"}},faq={{q="谁在征集零件？",a="萨丁农场的Ozwin Ironsprocket需要一些零件来制作装置。",al={"谁需要零件","ozwin零件"}},{q="Ozwin在制造什么？",a="Ozwin正在制造一种装置，打算用它短暂接管收割机的系统。",al={"什么装置","收割机装置"}},{q="Ozwin需要哪些零件？",a="Ozwin需要Golem Isosprings、Copper Modulators和一个Crude Scope。",al={"零件清单","ozwin需要什么"}},{q="Ozwin在哪里工作？",a="Ozwin Ironsprocket正在萨丁农场工作。",al={"ozwin在哪里","ozwin位置"}}},fp="25,182,15.218.0,19.117.1,24.62.0,23.80.0,27.67.0,23.48.0"}
P.entries["quest:92914"] = {n="Strange Pylons",s="在辛德拉，一座能量耗尽的水晶塔用途不明。你受命在附近寻找其他水晶塔。",h="在辛德拉，一座能量耗尽的水晶塔用途不明。你受命在附近寻找其他水晶塔。",kw={"水晶","精灵遗迹","宝石","法力元素","水晶塔","辛德拉","奇异的水晶塔"},sec={{t="遗迹之中",b="一块奇异的水晶静置在辛德拉精灵遗迹中的古老基座上。就在片刻之前，枯瘦的法力元素还守卫着它。宝石已经碎裂，魔力几乎耗尽，令它的用途成谜。你在附近寻找其他类似的水晶塔。"}},faq={{q="这座奇异的水晶塔是什么？",a="这是一块碎裂的宝石，镶嵌在辛德拉的一座古老基座上。魔力已经耗尽，令它的用途不明。",al={"奇异的水晶塔","水晶塔","这是什么水晶"}},{q="水晶为何发出嗡鸣？",a="碎裂的宝石散发出微弱的力量嗡鸣，尽管其中的魔力已所剩无几。",al={"水晶嗡鸣","为何发出嗡鸣","微弱的嗡鸣"}},{q="是什么守卫着水晶？",a="就在片刻之前，枯瘦的法力元素还守卫着水晶。",al={"法力元素","是什么守卫着它","水晶塔旁的元素"}},{q="其他水晶塔在哪里？",a="你受命在辛德拉寻找其他与发现的那座相似的水晶塔。",al={"其他水晶塔","寻找更多水晶塔","水晶塔位置"}}},fp="14,109,15.269.0,26.116.0,27.92.0,30.63.0,27.76.0"}
P.entries["quest:92947"] = {n="Making Our Move",s="Making Our Move是一次针对驻扎在阿基尔神殿内的敌对奥拉凯斯的协调战术突袭。通过利用正面佯攻和侧翼机动，突击部队试图突破防线并接近高阶女祭司。",h="Making Our Move是一次针对驻扎在阿基尔神殿内的敌对奥拉凯斯的协调战术突袭。通过利用正面佯攻和侧翼机动，突击部队试图突破防线并接近高阶女祭司。",kw={"奥拉凯斯","奥拉凯斯剑圣","奥拉凯斯卫士","奥拉凯斯缚灵者","高阶女祭司","修萨·疾风","展开行动","阿基尔神殿"},ang={["class:Priest"]="这次突袭的重点是奥拉凯斯的领导层，特别是针对坐镇阿基尔神殿的敌对高阶女祭司及其缚灵者。"},sec={{t="协调的钳形攻势",b="对阿基尔神殿的突袭依赖于精确的时间把控和兵力分配。一小队精英战士冲锋正门以引起警报并引出守军，同时指挥官率领主力突击队从侧翼包抄。这次协同推进旨在分散守军的注意力，从而开辟一条直通神殿领导层的道路。"},{t="突破奥拉凯斯防线",b="阿基尔神殿由强大的奥拉凯斯守卫，他们的队伍中包括重甲卫士、神秘的缚灵者和武艺高强的剑圣。突破外围需要冲破这些前线阵型，为前往内殿清出一条道路，高阶女祭司就在那里指挥她的追随者。一旦外围抵抗被击溃，部队将在神殿台阶处与副指挥官Hyusaa Quickbreeze会合。"}},faq={{q="展开行动中突袭的目标是什么？",a="展开行动是一次针对占据阿基尔神殿的敌对势力的协调战术突袭。通过发动正面佯攻吸引敌人注意力，同时主力突击队从侧翼包抄，以突破神殿并消灭高阶女祭司。",al={"采取行动","任务 采取行动","阿基尔神殿任务"}},{q="希尤萨·迅风是谁？",a="希尤萨·迅风担任突击部队的副指挥官。在削减了阿基尔神殿的奥拉凯斯守军后，你被要求前往神殿台阶附近与迅风会合。",al={"修萨是谁","修萨·迅风","修萨在哪里"}},{q="袭击中作为目标的高阶女祭司是谁？",a="高阶女祭司是坐镇阿基尔神殿的指挥官。整个多管齐下的侧翼机动旨在迅速穿透敌方防线，以便突击部队能够接近并击败她。",al={"高阶女祭司是谁","高阶女祭司 奥拉凯斯","目标高阶女祭司"}},{q="什么是阿基尔神殿？",a="阿基尔神殿是奥拉凯斯占据的一处坚固的宗教场所。这里由武装卫士、缚灵者和剑圣严密把守，保护着他们的领导层所在的中心圣所。",al={"什么是阿基尔神殿","阿基尔神殿背景","阿基尔神殿在哪里"}},{q="占据神殿的奥拉凯斯势力是谁？",a="奥拉凯斯是占据阿基尔神殿的敌对守军。他们的部队由坚定的前线卫士、施法的缚灵者以及敏捷的剑圣组成，他们守卫着通往高阶女祭司的必经之路。",al={"奥拉凯斯是谁","奥拉凯斯守军","奥拉凯斯怪物"}},{q="为什么在突袭中使用了正面佯攻？",a="一小队经验丰富的战士被直接派往神殿正门，以吸引守军并制造混乱。这种佯攻使主力作战单位能够从侧翼包抄营地，并向内部神殿挺进。",al={"为什么要佯攻","神殿攻击计划","采取行动攻击策略"}}},fp="15,179,20.338.0,27.359.0,56.171.0,26.156.0,49.132.0,27.174.0,47.195.0,49.203.0"}
P.entries["quest:93"] = {n="黑蟹蛋糕",s="夜色镇血鸦旅店的厨师格鲁奥对他那著名的黑蟹蛋糕有一个秘密：它们根本不含蟹肉。为了帮助饥肠辘辘且神经紧张的基特斯，冒险者们受命去采集暮色森林北部游荡的致命蛛形纲生物的蛛腿，以烹制小镇的这种挚爱零食。",h="夜色镇血鸦旅店的厨师格鲁奥对他那著名的黑蟹蛋糕有一个秘密：它们根本不含蟹肉。为了帮助饥肠辘辘且神经紧张的基特斯，冒险者们受命去采集暮色森林北部游荡的致命蛛形纲生物的蛛腿，以烹制小镇的这种挚爱零食。",kw={"厨师格鲁奥","夜色镇","暮色森林","黑蟹蛋糕","基特斯","血鸦旅店","蜘蛛腿","毒网蜘蛛"},ang={["faction:Alliance"]="这道菜展示了联盟南部边境的危险处境，像夜色镇这样的城镇由于基础设施被忽视和补给线中断，被迫依靠巨型害虫来维持生存。",["profession:Cooking"]="厨师格鲁奥展示了边境厨师所需的勇气，证明了即使是像巨型毒蜘蛛这样可怕的荒野掠食者，也能被变成小镇珍贵的区域美食。"},sec={{t="一份有疑问的美味",b="暮色森林长期饱受与世隔绝、暗影魔法和补给线中断的困扰，迫使夜色镇的居民不得不改良他们的菜肴。血鸦旅店的常驻厨师厨师格鲁奥发明了黑蟹蛋糕，解决了肉类短缺的问题。尽管名字听起来像是来自遥远海岸的海鲜，但格鲁奥坦承，这道菜独特的浓郁风味完全来自于当地巨型蜘蛛多汁的腿部。"},{t="猎杀毒网蜘蛛",b="为了完成订单，格鲁奥指引猎人前往北部的山脚和河岸，那里是毒网蜘蛛结网的地方。在这片爬满亡灵和野兽的阴郁森林中，采集新鲜的蜘蛛肉是一项危险的工作，但它仍然是这片被诅咒的森林中少数易于获取的蛋白质来源之一。格鲁奥将调好味的蛛肢放在热煎锅上油炸，直到它们变得焦脆。"},{t="安慰受诅咒的灵魂",b="这项烹饪差事源于对基特斯的担忧，这是一个躲在暮色森林西部乌鸦岭废弃村庄里的焦虑流浪汉。由于无意中在这片地区释放了恐怖怪物，基特斯深受负罪感和颤抖的恐惧所折磨，他除了饥饿的胃几乎想不了别的。格鲁奥的一份热腾腾的美味蜘蛛蛋糕，成了他悲惨流亡生活中难得的、虽然有些怪异的慰藉。"}},faq={{q="黑蟹蛋糕真的是用蟹做的吗？",a="不。厨师格鲁奥向冒险者公开承认，黑蟹蛋糕完全是用多汁的蜘蛛腿制成的。夜色镇无法接触到海洋或新鲜螃蟹，所以格鲁奥依靠当地的巨型蜘蛛来模仿口感，并提供一种辛辣、浓郁的零食。",al={"它是真的蟹肉吗","蟹肉蛋糕秘密","蟹肉蛋糕是用什么做的"}},{q="厨师格鲁奥从哪里弄到蜘蛛腿？",a="格鲁奥依靠冒险者去采集毒网蜘蛛身上多汁的腿。这些具有攻击性的蛛形纲生物主要栖息在暮色森林北部，在森林山脚和河流之间。",al={"哪里找蜘蛛腿","暮色森林蜘蛛位置","毒网蜘蛛位置"}},{q="这些蟹肉蛋糕是为谁做的？",a="虽然格鲁奥在夜色镇为顾客提供这种蛋糕，但这批蛋糕是专门为基特斯订制的。基特斯是一个躲在暮色森林西部乌鸦岭鬼镇的受惊隐士，急需食物来填饱他那咕咕叫的肚子。",al={"谁想要蟹肉蛋糕","谁吃蟹肉蛋糕","为什么要制作蟹肉蛋糕"}},{q="厨师格鲁奥会教我怎么做黑蟹蛋糕吗？",a="厨师格鲁奥对黑蟹蛋糕的具体配方守口如瓶，拒绝分享他的招牌调料配方。不过，他确实会用他烹饪菜谱中的另一种配方来奖励有用的冒险者。",al={"我可以学习蟹肉蛋糕配方吗","蟹肉蛋糕烹饪配方"}},{q="为什么夜色镇要靠吃蜘蛛维生？",a="暮色森林的道路受到亡灵、夜之魇狼人和敌对生物的围困，严重阻碍了贸易商队和农业发展。由于新鲜牲畜和进口商品稀缺，夜色镇的居民只能想方设法利用他们能捕获到的任何野生动物。",al={"为什么在夜色镇吃蜘蛛","暮色森林食物短缺"}},{q="基特斯知道蛋糕是用蜘蛛做的吗？",a="基特斯特别渴望格鲁奥那著名的蟹肉蛋糕，并不关心配料。由于在森林中受到恐惧和饥饿的折磨，他渴望从夜色镇吃到任何熟悉的食物，无论它有着多么令人毛骨悚然的来源。",al={"基特斯知道蜘蛛的事吗","基特斯对蜘蛛肉的反应"}}},fp="16,156,23.300.0,22.309.0,25.320.1,43.216.0,42.166.0,40.196.0,54.184.0,44.236.0,48.213.0"}
P.entries["quest:930"] = {n="发光的水果",s="“发光的水果”是泰达希尔的一个任务，任务的开启方式是在野外发现一株结着奇异果实的植物。年轻的冒险者怀疑其中有诈，便将这枚发光的样本带给奥拉密斯湖的草药师德纳兰进行研究。",h="“发光的水果”是泰达希尔的一个任务，任务的开启方式是在野外发现一株结着奇异果实的植物。年轻的冒险者怀疑其中有诈，便将这枚发光的样本带给奥拉密斯湖的草药师德纳兰进行研究。",kw={"沼泽行者","德纳兰","发光的水果","草药学","奥拉密斯湖","奇异的果实植物","泰达希尔","树苗怪"},ang={["class:Druid"]="对于致力于维护自然平衡的德鲁伊来说，发现外来的、不稳定的植物在泰达希尔的神圣枝干上非自然地生长，是一个迫在眉睫的危险信号。",["profession:Herbalism"]="草药师们会欣赏德纳兰的植物学见解，了解外来种子是如何跨越大陆，并在接触到受魔法影响的土壤后发生突变的。",["race:NightElf"]="卡多雷的年轻人通过德纳兰了解到，即使是他们新家园泰达希尔那年轻的土壤，也容易受到无法预料的外来枯萎病的影响。"},sec={{t="不自然的收成",b="当探险者穿行在泰达希尔那雾气缭绕的枝干间时，偶尔会偶然发现一些奇特的、会发光的植物，上面结着又大又圆的果实。考虑到世界之树的脆弱平衡，以及岛上野生动物近来出现的各种怪异行为，任何不寻常的植物样本都需要仔细调查。冒险者坚信这种奇怪的植物不容忽视，于是便采摘了这诱人的果实，带给一位精通野外植被的专家。"},{t="德纳兰的调查",b="在奥拉密斯湖，博学的园丁兼草药师德纳兰既着迷又忧虑地收下了这枚发光的果实。他指出这个样本看起来非常奇特，推测其种子可能是从海对岸的遥远大陆，甚至可能是从东部王国漂洋过海而来的。让德纳兰更为不安的是，这种外来的种子在泰达希尔的土壤中会产生怎样的反应——当他把种子种进准备好的土壤里时，敌对的沼泽行者竟然从土里钻了出来。"}},faq={{q="在哪里可以找到奇异的果实植物？",a="这种奇异的果实植物生长在泰达希尔的野外，隐藏在远离主要定居点的灌木丛中。与植物互动即可获得“发光的水果”并开启任务。",al={"我在哪里可以找到这株植物","奇异的果实植物位置","如何开始发光的水果任务"}},{q="德纳兰是谁？",a="德纳兰是一位暗夜精灵草药师和植物学家，驻扎在奥拉密斯湖岸边。他每天都在照料土地、研究区域植被，并监测影响泰达希尔的异常环境干扰。",al={"德纳兰在哪里","德纳兰非玩家角色","谁来交付发光的水果"}},{q="为什么果实会发光？",a="果实发光的原因尚无定论。德纳兰认为这是一个不寻常的样本，并计划对其进行研究。",al={"为什么水果会发光","水果有什么问题"}},{q="把果实交给德纳兰会发生什么？",a="将发光的水果带给奥拉密斯湖的德纳兰进行鉴定。当你返回时，他的研究结果和交付的后果便会揭晓。",al={"任务后会出现什么","沼泽行者伏击"}},{q="德纳兰认为这种植物来自哪里？",a="德纳兰怀疑这种植物的种子可能起源于无尽之海那边的遥远彼岸，从艾泽拉斯东部的遥远大陆带到了卡利姆多。",al={"种子来自哪里","水果起源"}},{q="这个任务是否与其他生态问题有关？",a="是的。它与德纳兰更广泛的研究有关，他正在调查为什么泰达希尔的枝干以及像树苗怪这样的当地林地生物变得越来越暴躁且不自然。",al={"泰达希尔腐蚀","奥拉密斯湖的问题"}}},fx={a8a1e1a2={q="为什么要把发光的水果带给德纳兰？",a="这种奇异果实植物没有心智，但它诡异的光芒和古怪的外形，与泰达希尔的天然植物格格不入。你意识到这种反常现象值得调查，便主动把样本送到奥拉密斯湖畔交给德纳兰，因为这位植物学家正在研究岛上异常的生态变化。",al={"为什么要给德纳兰送水果","奇异果实植物的缘由","为什么采摘发光的水果"}}},fp="17,185,20.306.0,23.373.1,41.158.0,15.190.0,24.85.0,48.147.1,46.137.0,67.161.0"}
P.entries["quest:93016"] = {n="A Brief History Lesson",s="你被派往辛德拉，了解你修复的水晶。水晶发出的光引起了众人的担忧，答案也正等着你去揭晓。",h="你被派往辛德拉，了解你修复的水晶。水晶发出的光引起了众人的担忧，答案也正等着你去揭晓。",kw={"简史课","水晶之光","水晶","异象频现的天空","莫尔登·伊文夏德","辛德拉","神殿"},sec={{t="辛德拉的疑问",b="你修复的水晶引起了诸多疑问，于是你被派去辛德拉寻找莫尔登·伊文夏德，听他解答。天空异象频现，让人们对先前那些请求更加不安。"},{t="计划中的拜访",b="莫尔登说，他先前没有说明情况，是因为看到水晶再次发光时太过激动。他希望能拜访辛德拉的神殿，却没有勇气与那里的辛德拉交谈。"}},faq={{q="谁来解释水晶的事？",a="有人请辛德拉的莫尔登·伊文夏德解释你修复的水晶。",al={"谁解释水晶","莫尔登信息","水晶说明"}},{q="为什么先前那些请求显得可疑？",a="那些请求来得毫无缘由，天空也出现了异象。",al={"为何可疑","有什么奇怪之处","为何没有缘由"}},{q="为什么莫尔登没有说明情况？",a="莫尔登说，他急着看水晶再次发光，一开始没能解释清楚情况。",al={"为何没有解释","莫尔登的缘由","他为何等着"}},{q="莫尔登打算去神殿吗？",a="莫尔登很期待再次拜访辛德拉的神殿，不过他说，自己可能还需要一些时间，才能与那里的辛德拉交谈。",al={"拜访神殿","莫尔登会去那里吗","辛德拉神殿"}}},fp="22,132,24.211.0,15.191.1,40.79.0,45.84.0,42.117.0,38.140.0"}
P.entries["quest:93036"] = {n="Infiltrating the Cult",s="“Infiltrating the Cult”是申达尔村的一个任务，要求一位陌生的冒险者去接近当地一位名叫Sania Silverstream的传教士。在温和的宗教外表下，Sania正在为奥拉凯斯招募追随者，这是一个致力于崇拜风领主奥拉基尔的邪教。该任务旨在揭开该邪教对该定居点的真实企图，以防脆弱的和平被打破。",h="“Infiltrating the Cult”是申达尔村的一个任务，要求一位陌生的冒险者去接近当地一位名叫Sania...",kw={"奥拉凯斯","奥拉基尔","潜入教派","萨妮娅·银溪","申达尔村","风领主"},ang={["class:Priest"]="Sania Silverstream自称是一名初级女祭司，但她的信仰是效忠于一位元素领主，而不是圣光或艾露恩。真正的牧师会认出她那令人愉悦的宗教外衣，其实是掩盖对元素的崇拜。",["class:Rogue"]="通过一个毫无戒心的招募者潜入敌对邪教，正好发挥了潜行者在敌后进行间谍、欺骗和侦察的才能。"},sec={{t="岌岌可危的和平",b="在申达尔村，一场不安的休战正在瓦解。一段时间以来，地方当局一直容忍着Sania Silverstream的存在，她自称是一名居住在当地的传教士。她代表着奥拉凯斯教派，该组织披着温和宗教运动的外衣，同时派遣温柔的招募者来吸引毫无戒心的追随者。村领导人允许她的招募工作，仅仅是为了避免激怒邪教并引发直接冲突，但这种相互共存的伪装已难以为继。"},{t="传教士的面纱之下",b="在外交姿态和温和的传教工作之下，隐藏着对一股古老而危险力量的崇拜：风领主奥拉基尔，风元素之主。当有人接近时，Sania会公开介绍自己是奥拉凯斯教派的初级女祭司，邀请潜在的新手了解他们的君主，并承诺给他们提供一席之地。由于现有居民对她太熟悉，无法安全地调查她，因此来到村庄的新人被委派去获得她的信任，以揭开该邪教对申达尔的真正企图。"}},faq={{q="谁是萨妮娅·银溪？",a="萨妮娅·银溪是居住在申达尔村的一名初级女祭司，声称是一个名为奥拉凯斯的宗教教派的传教士。事实上，她扮演着一名友善、毫无威胁的招募者，引诱当地人崇拜风领主奥拉基尔。",al={"谁是萨妮娅","萨妮娅·银溪背景故事","女祭司萨妮娅"}},{q="什么是奥拉凯斯教派？",a="奥拉凯斯是一个伪装成传统宗教运动的邪教。在他们外在的传教活动之下，他们崇拜风领主奥拉基尔（风元素之主），并试图通过悄悄地在附近定居点招募皈依者来扩大他们的影响力。",al={"谁是奥拉凯斯","什么是奥拉凯斯","奥拉凯斯教派"}},{q="为什么申达尔村会容忍萨妮娅·银溪？",a="村领导人一直容忍萨妮娅·银溪的传教存在，是为了维持一种脆弱的和平假象，并避免与该邪教引发公开冲突。然而，那场不安的休战正在迅速破裂，促使人们决定秘密调查她。",al={"为什么要让萨妮娅留下","为什么不杀死萨妮娅","为什么萨妮娅在村子里"}},{q="谁是风领主奥拉基尔？",a="风领主奥拉基尔是天空、风暴和空气的元素领主。奥拉凯斯教派尊奉他为他们的神圣君主，并承诺给予任何忏悔并加入他们事业的人一席之地。",al={"谁是风领主","奥拉基尔背景故事","谁是奥拉基尔"}},{q="为什么要求你潜入邪教，而不是当地人？",a="因为你是来到申达尔村的陌生新人，萨妮娅和奥拉凯斯不会怀疑你是受村领导层指使的。你的匿名身份使你能够以感兴趣的新手的幌子接近她，而不引起怀疑。",al={"为什么是我","为什么要派一名冒险者","潜入任务的原因"}},{q="奥拉凯斯对申达尔村有什么计划？",a="当地领导层怀疑奥拉凯斯的招募工作掩盖了对申达尔村更广泛、更具侵略性的野心。潜入邪教的主要目的是在村庄脆弱的和平彻底崩溃之前，揭开这些秘密计划。",al={"邪教对村庄的计划","奥拉凯斯想要什么","奥拉凯斯的意图"}}},fp="21,204,18.424.0,29.388.1,26.197.0,34.244.0,54.210.0,28.192.0,60.218.0,52.181.0"}
P.entries["quest:93065"] = {n="Prepare for Battle",s="Prepare for Battle标志着治安官部队的动员，他们集结起兵力准备从城镇出发。冒险者们被召唤去完成最后的准备工作，并在部队出发前与阵风浆果低地的Valennia Stormfist会合。",h="Prepare for Battle标志着治安官部队的动员，他们集结起兵力准备从城镇出发。冒险者们被召唤去完成最后的准备工作，并在部队出发前与阵风浆果低地的Valennia Stormfist会合。",kw={"东侧道路","阵风浆果低地","动员","治安官","准备战斗","瓦伦妮娅·风暴之拳"},ang={["class:Warrior"]="对于前线战士而言，这次动员是战斗至关重要的序曲，检查装备并与盟友并肩列阵决定了即将到来的战斗态势。"},sec={{t="集结的号角",b="随着地区局势日益紧张，被称为治安官的当地防御部队已经吹响了战斗的号角。部队和志愿者们接到命令，必须确保装备妥当，武器就位，并整队集合，以便组织有序地向周边地区进军。"},{t="在阵风浆果低地集结",b="此次远征的集结区位于城镇向北延伸的东侧道路沿线，直通阵风浆果低地。组织者Valennia Stormfist将在那里进行最后的检查和点名，确保每一名战士在部队进入危险区域前都做好了充分准备。"}},faq={{q="谁是瓦伦妮亚·风拳？",a="瓦伦妮亚·风拳是一位协调治安官部队在阵风浆果低地集结的组织者。她在城镇北向的东侧道路上负责监督最后的准备工作，确保部队能够顺利出发。",al={"谁是瓦蕾妮娅·风暴之拳","瓦蕾妮娅·风暴之拳","风暴之拳"}},{q="谁是治安官？",a="治安官是一支有组织的当地军事或防御部队，目前正集结兵力以应对城镇外迫在眉睫的威胁。",al={"谁是治安官","治安官","治安官部队"}},{q="阵风浆果低地在哪里？",a="阵风浆果低地是当地防御部队的区域性集结地，具体位于城镇向北延伸的道路沿线。",al={"阵风浆果低地在哪里","阵风浆果低地的位置","阵风浆果低地"}},{q="治安官在为什么做准备？",a="治安官部队正准备全军出击，他们呼吁所有有能力的盟友完成装备检查，并在远征开始前在城镇外围集合。",al={"他们在为什么做准备","为什么要为战斗做准备","战斗是什么"}},{q="远征的集合点在哪里？",a="集结点位于城镇向北延伸的东侧道路沿线，选择该位置是为了让部队在进军战场前能够整队集合。",al={"集结点在哪里","去哪里见瓦蕾妮娅","会合点"}},{q="当所有人都集结完毕后会发生什么？",a="报到后，瓦伦妮亚·风拳将对集结的队伍进行最后的检查，确认部队已做好一切准备，将进军危险之中。",al={"集结是如何结束的","瓦蕾妮娅说了什么","我们已经做好了一切准备"}}},fp="18,208,16.240.0,35.213.0,26.187.0,25.115.0,33.128.0,40.160.0,44.142.0,40.102.0"}
P.entries["quest:93089"] = {n="What Comes Next",s="高阶会在与肯瑞托盟友离开泽风岛前，寻求你的祝福。他们的远征能否成功，取决于能否找到解决岛屿动荡的奥术方法。",h="高阶会在与肯瑞托盟友离开泽风岛前，寻求你的祝福。他们的远征能否成功，取决于能否找到解决岛屿动荡的奥术方法。",kw={"安斯雷姆","达拉然","艾拉德林·暮风","高阶会","肯瑞托","天空切割者","接下来会怎样","泽风岛"},sec={{t="启程",b="高阶长老影歌已为远征祝福，准备工作也已就绪。安斯雷姆一直在筹备连接达拉然与泽风岛的天空切割者航线。先锋队即将启程，你准备离岛时可以去找Elaadrin Evengale。"}},faq={{q="离开泽风岛前，我该找谁？",a="准备离开泽风岛时，去找艾拉德林·暮风。",al={"找谁谈","离开泽风岛","艾拉德林启程"}},{q="高阶会要去哪里？",a="高阶会正准备远征，并安排天空切割者往返达拉然与泽风岛。",al={"他们要去哪里","高阶会目的地","下一站"}},{q="谁在帮助高阶会？",a="肯瑞托正在帮助高阶会，安斯雷姆也一直在筹备往返达拉然与泽风岛的天空切割者航线。",al={"盟友是谁","肯瑞托帮助","高阶会的同伴"}},{q="远征要寻找什么？",a="远征希望找到一种奥术方法，让泽风岛恢复稳定。",al={"他们在寻找什么","奥术方法","为何离开岛屿"}},{q="邪教怎么样了？",a="艾拉德林说，邪教已被击败，远征的准备工作也已完成。",al={"邪教状况","邪教是否被击败","邪教怎么样了"}}},fp="15,179,13.274.0,48.70.0,30.101.0,30.117.0,31.83.0,26.91.0"}
P.entries["quest:93090"] = {n="What Comes Next",s="What Comes Next 标志着泽风岛上事件的终结，旅行者们正准备启程，跨越天空。随着当地邪教威胁的平息以及获得了 High Elder Shadowsong 的祝福，连接该岛与莫高雷平原的裂天者航线现已开通。",h="What Comes Next 标志着泽风岛上事件的终结，旅行者们正准备启程，跨越天空。随着当地邪教威胁的平息以及获得了 High Elder Shadowsong 的祝福，连接该岛与莫高雷平原的裂天者航线现已开通。",kw={"艾耶莎·晨歌","大地之环","大长老影歌","莫高雷","穆尔恩","裂天者","接下来会怎样","泽风岛"},ang={["class:Shaman"]="此次探险建立了前往莫高雷的直航，以联络大地之环，这是一个致力于安抚艾泽拉斯元素之灵的受人尊敬的萨满组织。",["race:Tauren"]="跨越天空的目的地是莫高雷，那里是牛头人的祖居之地，也是大地之环维持其运作的地方。"},sec={{t="离开泽风岛",b="随着当地邪教被击败，泽风岛恢复了安宁，High Elder Shadowsong 已经准许了后续的旅程。探险队现在将目光投向了岛屿之外，将重心转向横跨广阔天空，前往卡利姆多大陆。Ayessa Dawnsinger 正在为那些准备离开该岛的人统筹最后的离岛事宜。"},{t="前往莫高雷的裂天者",b="建立离岛交通需要稳定的筹备工作。Muln 勤勉工作，确保了泽风岛与莫高雷之间稳定的裂天者航行。在成功的试航之后，一支先遣队已经跨越海洋，在另一端等待，准备与大地之环的萨满取得联系。"}},faq={{q="什么是任务 接下来呢？",a="接下来呢 是一个过渡任务，标志着离开泽风岛。在获得 大长老影歌 的祝福并确保邪教问题得到解决后，旅行者们准备搭乘裂天者前往卡利姆多大陆。",al={"什么是 接下来怎么办","接下来怎么办 任务","这个任务是什么"}},{q="探险队要去哪里？",a="裂天者航线连接了泽风岛与莫高雷，那是位于卡利姆多中部的一片草原台地，也是大地之环的所在地，探险队的先遣成员已经在那里等候。",al={"我们要去哪里","裂天者目的地","裂天者飞往哪里"}},{q="艾耶莎·晨歌 是谁？",a="艾耶莎·晨歌 是负责监督离开泽风岛的统筹人员。她确认各项准备工作已经就绪，试飞已经成功，并且探险队已经获得了 大长老影歌 的祝福可以出发。",al={"艾耶莎·晨歌 是谁","艾耶莎·晨歌","艾耶莎"}},{q="穆恩 是谁？",a="穆恩 是一位盟友，他勤勉工作，在泽风岛和莫高雷之间建立了稳定的裂天者交通，并进行了多次试航以确保空中航线的安全。",al={"穆恩 是谁","穆恩 裂天者","穆恩 泽风"}},{q="什么是大地之环？",a="大地之环是一个致力于维护元素之灵和谐的萨满组织。在这次探险中，他们作为接待方与联络人，欢迎抵达莫高雷的旅行者。",al={"什么是大地之环","大地之环莫高雷","谁是大地之环"}},{q="为什么探险队要离开泽风岛？",a="随着当地邪教被击败且获得了 大长老影歌 的祝福，继续在泽风岛上孤立存在的目的已经达成，探险队得以向大陆进行后续的扩展。",al={"为什么离开泽风岛","泽风岛的任务结束了吗","为什么要前往莫高雷"}}},fp="15,214,27.332.0,21.231.0,34.191.0,33.185.0,25.184.0,12.149.0,25.166.0,43.176.0"}
P.entries["quest:931"] = {n="发光的树叶",s="在泰达希尔的根系与树冠间发现了一种奇特的植物，它散发着超凡脱俗的微光。旅行者们意识到此物的稀有，便将其样本带给了奥拉密斯湖的植物学家德纳兰，以查明其起源。",h="在泰达希尔的根系与树冠间发现了一种奇特的植物，它散发着超凡脱俗的微光。旅行者们意识到此物的稀有，便将其样本带给了奥拉密斯湖的植物学家德纳兰，以查明其起源。",kw={"植物学","德纳兰","奥拉密斯湖","发光的树叶","嫩芽","奇异的蕨类植物","悲伤沼泽","泰达希尔"},ang={["class:Druid"]="关注着世界之树平衡的德鲁伊们，注意到了引入泰达希尔脆弱的幼苗树冠中的非原生植物生命。",["profession:Herbalism"]="草药师和植物爱好者们将会欣赏这种在距离原生生态系统数千英里外茁壮成长的沼泽植物所带来的植物学奥秘。",["race:NightElf"]="对于照顾他们新家园的暗夜精灵来说，德纳兰的实验提供了关于泰达希尔土壤韧性有多强的至关重要的见解。"},sec={{t="奇异的光芒",b="在泰达希尔翠绿的枝叶间漫步时，细心的旅行者可能会偶然发现一种奇特的蕨类植物。不同于寻常的森林植被，它的叶片会捕捉光线，散发出脉动、扭曲的光芒。这种反常的景象吸引了任何关注这座岛屿脆弱、萌芽中生态系统的目光。"},{t="德纳兰的发现",b="将这株切片带给奥拉密斯湖的植物学家德纳兰，揭示了一个意想不到的事实。德纳兰认出这种植物并非卡利姆多北部的原生品种，他上一次见到同类还是几十年前去东部王国的悲伤沼泽旅行时。对于这种种子如何跨越海洋并在这棵世界之树上长到如此惊人的规模，德纳兰感到非常着迷，他立即着手培育并测试这个样本。"}},faq={{q="这种奇怪的植物最初来自哪里？",a="据植物学家德纳兰所说，这种植物原产于东部王国东南部的一片阴暗湿地——悲伤沼泽。自几十年前访问过那片沼泽地后，他便再也没见过活体样本。",al={"蕨类起源","蕨类产地","沼泽植物"}},{q="德纳兰是谁？",a="德纳兰是一位好奇心旺盛的暗夜精灵植物学家兼草药师，常驻于泰达希尔的奥拉密斯湖畔。他致力于研究和培育泰达希尔蓬勃发展的植物生命，经常用外来的种子和花盆进行实验。",al={"德纳兰背景故事","德纳兰是谁"}},{q="为什么这种植物会长在泰达希尔？",a="这仍然是一个生态之谜。德纳兰对这种种子如何从东部王国跨越无尽之海，又如何在泰达希尔肥沃的土壤中扎根并长成如此巨大的植株感到惊叹。",al={"它是如何来到泰达希尔的","为什么蕨类会在这里"}},{q="把蕨类植物交给德纳兰后会发生什么？",a="德纳兰立即将样本放入他位于奥拉密斯湖的花盆中进行测试。他的培育很快使几片嫩芽绽放，从而引向了对这种外来植物的进一步研究。",al={"后续任务","德纳兰的测试","嫩芽"}},{q="这种植物会导致泰达希尔受到腐蚀吗？",a="不会。虽然泰达希尔的许多野生生物面临着邪恶力量带来的微妙腐蚀，但这种植物看起来只是一种不同寻常、被移居他处的外来品种，而非腐蚀的媒介。",al={"蕨类是否受到腐蚀","腐蚀植物"}}},fp="20,168,14.188.0,19.318.1,50.139.0,15.180.0,40.174.0,47.151.1,47.107.0"}
P.entries["quest:93159"] = {n="The Strange Hermit",s="The Strange Hermit 是影风森林的一项入门任务，讲述了一位住在远离文明社会的害羞兜帽隐士的故事。在长期的与世隔绝后，为了寻求交谈，这位隐士分享了他简单的手工生活片段，以及他与当地森林歌唱之灵的羁绊。",h="The Strange Hermit 是影风森林的一项入门任务，讲述了一位住在远离文明社会的害羞兜帽隐士的故事。在长期的与世隔绝后，为了寻求交谈，这位隐士分享了他简单的手工生活片段，以及他与当地森林歌唱之灵的羁绊。",kw={"森林之灵","手工制作","隐士","兜帽人","独行者","影风森林","奇怪的隐士"},ang={["class:Druid"]="崇尚自然的德鲁伊或许能理解隐士与当地森林之灵的互动，尽管他无法真正与它们对话，这与德鲁伊深层次的沟通有着鲜明的对比。",["profession:Engineering"]="修补匠和工匠们或许能理解隐士在手工建造物品来布置他那孤独住所时所获得的慰藉。"},sec={{t="林中的隐士",b="在影风森林幽深的林冠之下，住着一位神秘的兜帽隐士，人们只知道他叫 The Strange Hermit。他远离城镇和常规商路，在树林中过着平静而孤独的日子。当你接近他时，他笨拙的谈吐和紧张的举止显露出他已经多久没有与人交往了，甚至连基本的问候对他来说都是一种陌生的挑战。"},{t="灵魂与简单的生活",b="尽管形单影只，隐士坚持认为他拥有所需的一切陪伴和物资。他透露自己曾在别处居住，之后才定居于此，选择与手工制作的小玩意儿和当地的森林之灵为伴。虽然野生的灵魂经常为他歌唱，但他承认，悦耳的合唱并不能完全取代与能真正回应自己的人交谈。"}},faq={{q="奇怪的隐士 是谁？",a="奇怪的隐士 是一位住在影风森林中的古怪兜帽人。他不习惯常规的社交互动，比起与人往来，他更喜欢花时间打理自己手工制作的物品，并与当地的林地之灵交流。",al={"奇怪的隐士","隐士身份","谁是隐士"}},{q="隐士住在哪里？",a="这位隐士将家安在影风森林深处人迹罕至的地方，居住在极少有旅人踏足的幽僻之所。",al={"隐士在哪里","影风森林位置","隐士区域"}},{q="为什么隐士独自居住？",a="他承认在退隐到森林之前，他曾在完全不同的地方生活过。虽然他对自己的过去含糊其辞，但他选择了只与自己制造的物品和森林中的野生之灵为伴，过着平静的生活。",al={"为什么隐士是独自一人","隐士的孤立","隐士背景故事"}},{q="隐士能与森林之灵交谈吗？",a="他将当地的森林之灵视为同伴，尽管它们并不会进行正常的交谈。相反，它们会为他歌唱，他觉得这很令人愉悦，即使这种交流无法提供与凡人交谈时那种深层的互动。",al={"隐士与灵魂交谈","影风森林的森林之灵","隐士的朋友"}},{q="隐士在森林里建造了什么？",a="隐士提到他有一些手工制作的物品和建筑可以用来打发时间，他从这些简单的手工制品中找到了安慰和满足感。",al={"隐士的手工艺品","隐士建造了什么"}},{q="在任务“奇怪的隐士”中会发生什么？",a="该任务涉及在影风森林中接近紧张的隐士，展开一段友好的对话，并倾听他愿意分享的关于其隐居生活的那一点点信息。",al={"奇怪的隐士 任务","与隐士交谈"}}},fp="18,192,22.261.0,25.245.0,26.194.0,27.117.0,36.180.0,41.148.0,40.140.0,51.115.0"}
P.entries["quest:93160"] = {n="The Forest's Bounty",s="The Forest's Bounty 是影风森林的一个当地任务，一位胆小的采集者请求帮助收集掉落的橡果。凶猛的掠食性猛禽潜伏在更深的林地中，使得在没有冒险者保护的情况下进行采集变得过于危险。收集到的橡果随后会被烘烤成美味的森林餐点。",h="The Forest's Bounty...",kw={"橡果","烹饪","采集","猛禽","影风橡果","影风森林","森林的馈赠"},ang={["profession:Cooking"]="收集影风橡果展示了当地的野生坚果如何被烘烤成简单的森林餐点，这引起了烹饪采集者们的浓厚兴趣。"},sec={{t="危险的采集行动",b="一位谨慎的采集者在影风森林寻找食物时陷入了困境。虽然橡果散落在林地的地面上，但周围的树林中潜伏着凶猛的猛禽类生物。在收集完靠近安全地带的橡果后，采集者只能指望路过的旅行者深入野外更深处，以免两人都挨饿。"},{t="烘烤收获",b="影风橡果为那些懂得如何准备的人提供了充足的养分。虽然生吃又苦又硬，但在噼啪作响的火堆上烘烤能将这些野外收获变成美味的烤制佳肴。冒着危险在树林中面对那些掠食性鸟类，将一次简单的森林拾荒变成了一顿在荒野中分享的温热餐点。"}},faq={{q="谁让你去收集橡果？",a="一位在影风森林附近休息的紧张的采集者请求协助。由于已经收集完附近所有安全的橡果，他们需要一位坚毅的冒险者深入森林，那里有危险的野生动物在游荡。",al={"谁发布了森林的馈赠任务","谁想要橡果","森林的馈赠任务发布者"}},{q="橡果在哪里可以找到？",a="影风橡果散落在影风森林的树冠下。采集者必须搜索森林地面，同时警惕潜伏在树林中的敌对掠食者。",al={"影风橡果在哪里","橡果位置","影风森林橡果"}},{q="为什么在这里收集橡果很危险？",a="森林地面上有掠食性的猛禽类鸟类出没。这些好斗的生物使得那些缺乏自卫武技的普通人远离营地变得极其危险。",al={"为什么影风森林危险","什么是猛禽","为什么收集橡果很危险"}},{q="橡果是用来做什么的？",a="橡果是一种充饥的野外食物来源。一旦收集起来，它们就会被放在火上烘烤，变成温热、香脆的零食，与那些愿意冒着危险面对森林野兽的人分享。",al={"影风橡果有什么用","烤橡果","为什么要收集橡果"}},{q="森林里提到的猛禽类生物是什么？",a="任务发布者将它们描述为在影风森林狩猎的危险的“猛禽类怪物”。这些鸟类或爬行类掠食者体型庞大且极其凶残，会将毫无防备的旅行者视为下一顿美餐。",al={"什么是猛禽怪物","影风森林里的猛禽","森林猛禽"}},{q="橡果是如何准备食用的？",a="虽然刚从地上捡起来时又硬又苦，但采集者特别提到，影风橡果在火上适当烘烤后会变成美味的佳肴。",al={"影风橡果可以生吃吗","如何烹饪影风橡果","食用森林橡果"}}},fp="19,164,23.292.0,20.236.0,34.162.0,27.132.0,40.133.0,29.128.0,59.181.0,39.99.0"}
P.entries["quest:93165"] = {n="Mercy Falls on Deaf Ears",s="“Mercy Falls on Deaf Ears”是一项悬赏任务，由一个悲愤交加的聚居地发出，他们正寻求对奥拉凯斯教派展开血腥的复仇。在经历了教徒们造成的惨剧后，该聚居地承诺，只要能带回被击杀敌人的战利品，就给予金币奖励，并允许对方接触Nightclaw隐藏的知识。接受这项任务将直接把旅行者卷入这场蔓延在影风森林及周边地区的冲突之中。",h="“Mercy Falls on Deaf...",kw={"奥拉凯斯","血海深仇","教徒","耳朵","阵风浆果低地","仁慈无人理会","夜爪","影风森林","阿基尔神殿"},sec={{t="以血还血",b="Nightclaw聚居地与奥拉凯斯教徒之间的宿怨极其痛苦且毫不留情。在遭遇了一场并未说明但摧毁一切的惨剧后，幸存者们已经放弃了和平和解的希望。为了替死去的亲族复仇，他们向过往的冒险者和雇佣兵寻求帮助，要求进行残酷的报复。作为砍下教徒首级并带回他们的耳朵作为残酷证明的交换，聚居地提供金币奖励以及建立更深层信任的机会。"},{t="奥拉凯斯的威胁",b="奥拉凯斯在多个荒野地区活动，将其影响力散布至阵风浆果低地、阴暗的影风森林以及古老的阿基尔神殿。他们邪恶的行径和狂热的本质引来了当地居民的仇恨。通过打击他们这些地区的营地，旅行者不仅能削弱教派的势力，还能获得隐秘的Nightclaw的好感——Nightclaw会对自己的秘辛守口如瓶，直到外来者证明自己的忠诚。"}},faq={{q="“仁慈无人听”是什么任务？",a="“仁慈无人听”是一项任务，冒险者受雇去对奥拉凯斯教徒进行报复，此前教徒们对当地一个聚居地发动了灾难性的袭击。委托人寻求复仇，要求冒险者杀死教徒并交还他们被割下的耳朵作为不可否认的击杀证明，以换取金币和信任。",al={"无人理会的仁慈任务","这个任务是什么","任务概述"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是一个被诅咒的教派，因给邻近定居点带来毁灭和悲剧而闻名。他们在阵风浆果低地、影风森林和阿基尔神殿保持着敌对势力，并与周边地区的居民引发了公开的血海深仇。",al={"奥拉凯斯是谁","奥拉凯斯教徒背景知识","关于奥拉凯斯"}},{q="在哪里可以找到奥拉凯斯教徒？",a="可以在三个不同的区域遇到奥拉凯斯教徒：影风森林茂密的树冠下、阿基尔神殿周围的神圣土地上，以及整个阵风浆果低地。在这些地区中任何一处击杀教徒都能获得悲愤的聚居地所要求的证明。",al={"奥拉凯斯教徒在哪里","奥拉凯斯位置","去哪里寻找教徒"}},{q="为什么任务发布者要收集教徒的耳朵？",a="在这场残酷的荒野冲突中，割下的耳朵是死亡的实体且不可否认的证明，必须以血偿血。由于该聚居地在遭受严重惨剧后对奥拉凯斯怀有深仇大恨，他们要求获得实体的战利品，以确保每一笔付出的悬赏都对应着一个死去的教徒。",al={"为什么要耳朵","他们为什么要教徒的耳朵","作为证明的耳朵"}},{q="夜爪是谁？",a="夜爪代表着一个隐秘的聚居地，他们因奥拉凯斯教派的掠夺而蒙受了沉重的损失。虽然他们对陌生人保持警惕，但他们掌握着严密守护的秘密和知识，只要外来者通过消灭他们的教派敌人证明自己的忠诚，最终便能获准接触他们的内在奥秘。",al={"夜爪阵营","夜爪是谁","夜爪秘密知识"}},{q="奥拉凯斯造成了什么惨剧？",a="任务发布者提到，奥拉凯斯直接对夜爪聚居地施加了一场巨大的惨剧，这引发了毫不妥协的血海深仇。虽然悬赏本身并未详述具体的伤亡人数和细节，但该事件的恐怖程度足以让幸存者要求进行毫无慈悲的彻底复仇。",al={"奥拉凯斯做了什么","聚居地发生了什么","奥拉凯斯惨剧"}},{q="夜爪的秘密是什么？",a="夜爪秘密的具体性质在聚居地内部受到保护，不会立即向外人披露。任务发布者承诺，只要冒险者持续协助他们对抗奥拉凯斯并证明自己是真正的盟友，最终将被获准接触这些隐藏的知识。",al={"夜爪秘密","夜爪有什么秘密","夜爪揭示了什么"}}},fp="24,329,15.361.0,19.392.0,33.168.0,21.257.0,37.169.0,46.180.0,22.231.0,36.206.0,33.234.0"}
P.entries["quest:93172"] = {n="Free the Hollows",s="“Free the Hollows”是影风森林中的一个任务，风之空灵（wind hollows）这种幽灵般的生物徘徊在古老的废墟之中。它们被一场古老的悲剧所困，忧伤的歌声萦绕在周围的树林里，直到有人能给予它们解脱。",h="“Free the Hollows”是影风森林中的一个任务，风之空灵（wind hollows）这种幽灵般的生物徘徊在古老的废墟之中。它们被一场古老的悲剧所困，忧伤的歌声萦绕在周围的树林里，直到有人能给予它们解脱。",kw={"解放谷地","幽灵","空灵","废墟","影风","影风森林","风之空灵"},ang={["class:Druid"]="徘徊在影风森林中的不安灵魂代表了一种不自然的荒野骚乱，需要寻求平衡与解脱。",["class:Priest"]="风之空灵是因悲剧而受困的忧伤幻影，消灭它们是一种仁慈的行为，能让这些灵魂从永恒的苦难中解脱。",["race:NightElf"]="岛上的当地精灵长期以来一直感觉到影风森林闹鬼，他们为那些被束缚在古老废墟中的灵魂所产生的悲剧性残留而感到不安。"},sec={{t="影风的幽魂",b="岛上的精灵长久以来一直视影风森林为一处闹鬼的林地，而他们的迷信并非空穴来风。在树林东北部的深处，坐落着古老的石质废墟，被称为风之空灵的幻影无休止地在杂草丛中游荡。这些灵魂并没有表现出敌意，而是散发着一种深沉的悲伤，仿佛被过去某个时代的灾难所禁锢。"},{t="忧伤之歌",b="在寂静的夜晚，废墟附近的旅人常听到风中传来阵阵怪异而空灵的歌声。那不像任何已知的凡人歌谣，带着一种强烈的忧郁，令所有听到的人感到不安。充满同情的旅人们认为，让这些幽魂永远陷于这种悲叹之中是一种折磨，因此他们会去寻找风之空灵，打破它们的灵体束缚，赐予它们安宁。"}},faq={{q="什么是风之空灵？",a="风之空灵是忧伤的、幽灵般的精魂，它们出没于影风森林东北部的古老精灵废墟中。它们被某种古代的悲剧所困，在夜晚会发出诡异、忧伤的歌声，在树林间回荡。",al={"什么是风之空灵","空灵背景故事","什么是空灵"}},{q="为什么要解脱风之空灵？",a="任务发布者认为，这些灵魂在经历了一场可怕的灾难后陷入了永恒的悲伤之中。消灭风之空灵被视为一种释放和仁慈的行为，将它们从受困于废墟的状态中解脱出来。",al={"为何解脱空灵","为何消灭空灵","解脱空灵的目的"}},{q="这些精魂在哪里？",a="影风森林是一座有精灵居住的岛屿林地，东北部有着古老的废墟，那里聚集着幽灵般的空灵。",al={"影风森林在哪里","影风废墟","废墟位置"}},{q="树林里听到的奇怪歌声是什么？",a="风之空灵的歌声被描述为一种不同于普通曲调、异常忧伤的旋律，被认为是源于它们悲剧性的消亡以及被无休止地禁锢在岛屿废墟中的状态。",al={"空灵的歌声","幽灵之歌","为什么幽灵在唱歌"}},{q="谁让你去解脱这些空灵？",a="这项任务是由岛上的一位观察者提出的，他同情那些受困的灵魂，并注意到当地的精灵对这片闹鬼的树林怀有戒心。",al={"谁发布了解放空洞者任务","解放空洞者任务发布者"}},{q="废墟里发生了什么导致了空灵的出现？",a="虽然确切的细节已湮没在时间的长河中，但当地人知道东北部的废墟曾发生过一场可怕的事件，将这些灵魂束缚在那个地方，陷入无休止、悲痛的循环之中。",al={"影风废墟发生了什么","为什么废墟闹鬼"}}},fp="16,173,23.290.0,17.315.0,26.184.0,41.184.0,28.125.0,47.176.0,33.121.0,49.152.0"}
P.entries["quest:93176"] = {n="My Little Friends",s="一位饲养者送给你一份包裹，让你开始研究三种小生物。Entomology Starter Kit 里装着研究所需的笔记和材料。",h="一位饲养者送给你一份包裹，让你开始研究三种小生物。Entomology Starter Kit 里装着研究所需的笔记和材料。",kw={"arbor tarantula","昆虫学","flesh picker","hay weevil specimen","动物收藏","我的小伙伴","入门工具包"},sec={{t="饲养者的提议",b="一位饲养者花了许多时间研究一小群动物，如今想与你分享这项爱好。包裹里有供你入门的笔记和材料。借助 Entomology Starter Kit，你可以寻找 Arbor Tarantula、Hay Weevil Specimen 和 Flesh Picker。"}},faq={{q="饲养者希望我做什么？",a="使用 Entomology Starter Kit，找到并捕捉 Arbor Tarantula、Hay Weevil Specimen 和 Flesh Picker。",al={"我的小伙伴任务","要收集什么"}},{q="包裹里有什么？",a="包裹里有笔记和材料，能让你开始这项饲养者的爱好。",al={"入门工具包内容","包裹里有什么"}},{q="饲养者在研究什么？",a="饲养者研究这群小动物的身体结构、食性和社交习惯。",al={"小型动物收藏","他在研究什么"}},{q="如果我弄丢了工具包，会怎么样？",a="饲养者说，你需要花一小笔钱再买一份。",al={"弄丢入门工具包","补购工具包"}}},fp="17,141,18.256.0,35.111.0,23.86.0,28.96.0,31.74.0"}
P.entries["quest:932"] = {n="扭曲的仇恨",s="扭曲的仇恨是泰达希尔的塔隆凯·捷根发出的一项秘密任务。他要求受信任的勇士深入地狱石洞穴，处决梅兰纳斯勋爵。这名萨特正在将当地的格瑞尔集结成一股有组织且具有腐蚀性的力量，这对暗夜精灵的定居点构成了危险的威胁。",h="扭曲的仇恨是泰达希尔的塔隆凯·捷根发出的一项秘密任务。他要求受信任的勇士深入地狱石洞穴，处决梅兰纳斯勋爵。这名萨特正在将当地的格瑞尔集结成一股有组织且具有腐蚀性的力量，这对暗夜精灵的定居点构成了危险的威胁。",kw={"地狱石","格瑞尔","梅兰纳斯勋爵","萨特","塔隆凯·捷根","泰达希尔","扭曲的仇恨"},ang={["class:Druid"]="梅兰纳斯和他手下受腐蚀的格瑞尔在地狱石的邪恶存在，正在毒害泰达希尔新生长出的荒野那脆弱的平衡。",["race:NightElf"]="每一个萨特都是对你祖先堕落于恶魔野心这一事实的古老提醒；将梅兰纳斯勋爵处死，既是对世界之树的责任，也是一种对祖先罪孽的忏悔。"},sec={{t="苦涩的耻辱",b="对于暗夜精灵来说，萨特代表着远古背叛的活生生的记忆。这些羊头恶魔由在上古之战中投靠燃烧军团的上层精灵所生，是卡多雷历史上一个痛苦且持久的污点。而这样一个萨特竟然在泰达希尔——这棵本应是避难所的年轻世界之树中——建立了一个邪恶的立足点，这被塔隆凯·捷根这样的当地防御者视为一种极大的羞辱。"},{t="地狱石的威胁",b="在附近道路的北面坐落着地狱石，这是一个充斥着野性格瑞尔的受腐蚀洞穴系统。梅兰纳斯勋爵在他的黑暗意志下将这些天性混乱的生物集结成了一支敌对的、有组织的军队。塔隆凯担心这名萨特会对世界之树的枝干造成不可预知的破坏，因此要求必须迅速、安静且果断地消灭梅兰纳斯，并带回他被割下的头颅。"}},faq={{q="梅兰纳斯勋爵是谁？",a="梅兰纳斯勋爵是一个占据了泰达希尔北部地狱石洞穴的萨特。他统领着一群好战的格瑞尔战士，并企图在整个世界之树散布腐化。",al={"梅兰纳斯勋爵","梅兰纳斯是谁","地狱石首领"}},{q="我能在哪里找到梅兰纳斯勋爵？",a="他潜伏在泰达希尔多兰纳尔以北的一处崎岖洞穴系统——地狱石的深处，周围环绕着格瑞尔和其他受腐蚀的生物。",al={"梅兰纳斯的位置","梅兰纳斯在哪里","如何找到地狱石"}},{q="为什么塔隆凯·捷根想要保密？",a="萨特代表了暗夜精灵历史上一个可怕的远古篇章，他们在上古之战中背叛了自己的族人。让一个萨特如此肆无忌惮地潜伏在刚刚种植的世界之树中心，被认为是一种极大的耻辱，塔隆凯希望能在不引起大规模恐慌的情况下解决这个问题。",al={"为什么要保密","为什么这件事必须保密","塔隆凯的秘密"}},{q="萨特和格瑞尔之间是什么关系？",a="格瑞尔是分布在泰达希尔各地、体型娇小、顽皮且天生带有腐蚀性的野生生物。萨特生性狡诈且本质邪恶，很容易欺凌或驱使这些低等生物为他们邪恶的野心服务。",al={"格瑞尔与萨特","为什么格瑞尔会追随梅兰纳斯","萨特与格瑞尔的联系"}},{q="为什么泰达希尔会有萨特？",a="泰达希尔才刚刚种植几年。尽管德鲁伊们希望这里是一片纯净的避难所，但腐化和黑暗生物很快就潜入了岛上，萨特也潜入其中，在地狱石这样阴暗的地方建立了立足点。",al={"泰达希尔的萨特","萨特是怎么来到这里的","泰达希尔的腐化"}},{q="塔隆凯·捷根是谁？",a="塔隆凯·捷根是一名驻扎在多兰纳尔附近的暗夜精灵守卫，他时刻监视着针对泰达希尔的新兴威胁，并派遣冒险者去清除附近的腐化源。",al={"塔隆凯","谁发布了扭曲的仇恨任务"}}},fp="14,179,17.327.0,22.331.0,20.167.0,30.123.0,51.210.0,50.167.0,54.221.0,27.165.0"}
P.entries["quest:93224"] = {n="Carved Centaur Totems",s="尼耶尔前哨站的本迪加斯上尉想要雕刻的半人马图腾，以仿制它们的样式。他希望这些仿制品能帮助他在半人马氏族之间换取优势。",h="尼耶尔前哨站的本迪加斯上尉想要雕刻的半人马图腾，以仿制它们的样式。他希望这些仿制品能帮助他在半人马氏族之间换取优势。",kw={"本迪加斯上尉","雕刻的半人马图腾","木雕","半人马","半人马氏族","凄凉之地","尼耶尔前哨站","图腾"},sec={{t="木雕换来的筹码",b="尼耶尔前哨站的本迪加斯上尉想从半人马氏族的木雕中寻找获得优势的办法。两个氏族都不愿接受外来者的帮助，尤其是非半人马。他请你带回一些样品，好安排人雕刻类似的作品。"}},faq={{q="本迪加斯上尉为什么想要这些图腾？",a="他希望安排人雕刻类似的作品，以便在半人马氏族之间换取优势。",al={"图腾的用途","本迪加斯的计划"}},{q="半人马氏族为什么不愿接受帮助？",a="两个氏族都不愿接受氏族之外的援助，尤其是来自非半人马的帮助。",al={"半人马为何不接受援助","半人马不信任外来者"}},{q="半人马图腾是什么材料做的？",a="当地的半人马用木雕物品进行交易。",al={"图腾的材料","木雕"}},{q="本迪加斯上尉在哪里等候？",a="本迪加斯上尉在尼耶尔前哨站。",al={"本迪加斯在哪里","尼耶尔前哨站的上尉"}}},fp="21,158,17.267.0,43.81.0,50.88.0,36.42.0,34.38.0"}
P.entries["quest:93225"] = {n="Carved Centaur Totems",s="古尔达·蛮鬃相信，雕刻图腾或许能帮她赢得吉尔吉斯或玛格拉姆的好感。她需要从凄凉之地各半人马氏族那里收集真正的图腾。",h="古尔达·蛮鬃相信，雕刻图腾或许能帮她赢得吉尔吉斯或玛格拉姆的好感。她需要从凄凉之地各半人马氏族那里收集真正的图腾。",kw={"雕刻半人马图腾","半人马货币","凄凉之地","吉尔吉斯","幽灵岗哨","古尔达·蛮鬃","玛格拉姆"},sec={{t="一种半人马货币",b="古尔达·蛮鬃在幽灵岗哨见过半人马氏族离开聚居地碰面交易。她见过他们用雕刻图腾充当货币。如今她认为，一大捆图腾或许能打动吉尔吉斯或玛格拉姆，但她自己雕刻的图腾可能会被看出是假的。因此，她请你带来真正的图腾。"}},faq={{q="古尔达想要什么？",a="古尔达·蛮鬃请你为她带来真正的雕刻半人马图腾。",al={"古尔达的请求","蛮鬃需要什么"}},{q="她为什么需要雕刻图腾？",a="古尔达相信，一大捆图腾或许能帮她赢得吉尔吉斯或玛格拉姆的好感。",al={"图腾有何用处","为什么要图腾"}},{q="半人马在哪里使用这些图腾？",a="古尔达见过不同氏族的半人马离开聚居地碰面交易，用雕刻图腾充当货币。",al={"半人马交易","图腾用途"}},{q="我在哪里能找到古尔达·蛮鬃？",a="古尔达·蛮鬃在幽灵岗哨。",al={"古尔达的位置","蛮鬃在幽灵岗哨"}},{q="涉及哪些半人马氏族？",a="古尔达希望一捆图腾能为她赢得吉尔吉斯或玛格拉姆的好感。",al={"吉尔吉斯和玛格拉姆","哪些氏族"}}},fp="21,157,18.320.0,21.69.0,32.79.0,32.118.0,32.39.0,33.84.0"}
P.entries["quest:933"] = {n="大地之冠",s="大地之冠是多兰纳尔的科瑞萨斯·月怒所给予的一项联盟任务。他指引你从阿里斯瑞恩之池附近的月井中取水，那片区域正日益受到疯狂的木喉熊怪的威胁。完成这项任务将揭示大德鲁伊范达尔·鹿盔是如何在玛法里奥·怒风失踪后，号召暗夜精灵种下泰达希尔的。",h="大地之冠是多兰纳尔的科瑞萨斯·月怒所给予的一项联盟任务。他指引你从阿里斯瑞恩之池附近的月井中取水，那片区域正日益受到疯狂的木喉熊怪的威胁。完成这项任务将揭示大德鲁伊范达尔·鹿盔是如何在玛法里奥·怒风失踪后，号召暗夜精灵种...",kw={"科瑞萨斯·月怒","多兰纳尔","范达尔·鹿盔","木喉熊怪","玛法里奥·怒风","阿里斯瑞恩之池","红玉瓶"},ang={["class:Druid"]="随着科瑞萨斯讲述关于找回古老不朽的绝望举动，塞纳里奥议会在范达尔·鹿盔领导下的分裂变得愈发清晰。",["race:NightElf"]="你旅程的这一部分解释了在玛法里奥突然失踪后，促成泰达希尔诞生的那些充满争议的政治动向。"},sec={{t="危险的月井",b="科瑞萨斯·月怒指派你去将一只红玉瓶带到位于达纳苏斯入口东南方、阿里斯瑞恩之池岸边的一口月井处。这段旅程绝非安稳。曾经爱好和平的木喉熊怪陷入了突如其来的暴力狂怒之中，它们在整个地区伏击过往的旅人，并不断袭扰哨兵巡逻队。起初被认为是孤立的小规模冲突，如今已经升级为笼罩着暗夜精灵新家园的普遍威胁。"},{t="范达尔·鹿盔的野心",b="在收到装满水的瓶子后，科瑞萨斯向你讲述了关于泰达希尔建立的关键历史。第三次战争之后，珊多玛法里奥·怒风神秘失踪，留下了群龙无首且分崩离析的塞纳里奥德鲁伊。在他缺席期间，大德鲁伊范达尔·鹿盔夺取了领导权。鹿盔说服了黑海岸的远古议会，声称暗夜精灵不能沉溺于无谓的哀悼，他们需要种下一棵巨大的新世界之树来找回失去的不朽，并以此重振他们的文明。"}},faq={{q="这个任务的月井在哪里？",a="这口月井位于达纳苏斯主入口的东南方，坐落在阿里斯瑞恩之池的南岸边。",al={"阿里斯瑞恩月井","月井位置","哪里装瓶子"}},{q="为什么木喉熊怪会发起攻击？",a="木喉熊怪原本是爱好和平的熊怪一族，但最近一股黑暗且盲目的狂怒席卷了泰达希尔全境的熊怪。哨兵起初将早期的袭击视作孤立事件，但这种腐化传播迅速，使它们成为了附近定居点和巡逻队的持续威胁。",al={"熊怪发狂","木喉熊怪攻击性","为什么熊怪攻击"}},{q="玛法里奥·怒风发生了什么事？",a="珊多玛法里奥·怒风在第三次战争后失踪，没有任何解释。时至今日，无论是塞纳里奥的德鲁伊还是暗夜精灵的领导层，都不知道他究竟去了哪里。",al={"玛法里奥在哪里","怒风发生了什么","玛法里奥失踪"}},{q="是谁决定种下泰达希尔的？",a="在玛法里奥失踪后，大德鲁伊范达尔·鹿盔站出来领导德鲁伊们。他说服了黑海岸的远古议会支持培育一棵新的世界之树，并主张这对卡多雷重建家园、找回在诺达希尔被毁时失去的不朽至关重要。",al={"谁制造了泰达希尔","鹿盔世界之树","为什么要种泰达希尔"}}},fp="18,201,19.359.0,27.473.0,37.111.0,41.247.0,37.151.0,32.269.0"}
P.entries["quest:93317"] = {n="Crab Season",s="Crab Season是Zephras的一项紧急觅食任务，主要内容是在一年一度短暂的窗口期内捕捉稀有的风歌蟹。由于最近的邪教徒活动使风歌湖岸边变得危机四伏，冒险者们受命前去应对那些怀有敌意的入侵者和极具攻击性的甲壳类生物。",h="Crab...",kw={"螃蟹季节","螃蟹","邪教活动","风歌蟹肉","风歌蟹","风歌湖","泽弗拉斯"},ang={["profession:Cooking"]="虽然采集时令风歌蟹肉对于Zephras的当地储藏室至关重要，但鉴于这些生物的攻击性，处理新鲜的湖中捕获物需要格外小心。"},sec={{t="稍纵即逝的收获",b="在Zephras的风歌湖岸边，每年只会开启为期几周的短暂季节性收获窗口。本地的风歌蟹会在淡水河岸和支流沿线大量出现，为任何敢于在年度机会溜走前去收集它们的人提供珍贵的蟹肉。"},{t="水畔的危机",b="近期Zephras周围邪教徒活动的激增扰乱了人们的日常生活，也危及了当地的采集者。随着敌对的邪教徒在荒野中巡逻，前往风歌湖对单独的采集者来说变得过于危险，如果能干的冒险者不挺身而出保护岸边并对付这些暴躁的螃蟹，这一短暂的螃蟹季节可能会白白浪费。"}},faq={{q="什么是风歌蟹？",a="风歌蟹是一种具有攻击性的螃蟹，仅栖息于泽风岛屿或陆地上的风歌湖。它们的特点是只能在每年为期几周的短暂季节性窗口期内进行采集。",al={"什么是风歌蟹","风歌螃蟹","泽风的湖蟹"}},{q="为什么现在必须采集这些螃蟹？",a="这些螃蟹只能在每年仅持续几周的短暂季节性窗口期内采集。如果不能在这个狭窄的时间范围内完成采集，那么在今年剩下的时间里，收集它们蟹肉的机会就将失去。",al={"为何现在采集螃蟹","螃蟹季节窗口期","为何螃蟹限时"}},{q="为什么当地采集者不能自己去采集螃蟹？",a="周边地区近期的邪教徒活动使得前往风歌湖的旅程对于常规觅食来说太过危险，导致当地采集者无法在短暂的收获窗口关闭前抵达岸边。",al={"为何当地人无法采集螃蟹","泽风的邪教徒","风歌湖邪教活动"}},{q="风歌蟹在哪里可以找到？",a="风歌蟹栖息于泽风的风歌湖沿岸，以及附近相互连接的河岸边。",al={"风歌蟹位置","泽风的螃蟹在哪里","风歌湖岸"}},{q="捕捉风歌蟹有危险吗？",a="尽管风歌蟹看起来只是普通的淡水甲壳类生物，但它们极其好斗，远比看起来凶猛得多，会毫不犹豫地夹住任何试图收集它们蟹肉的人。",al={"风歌蟹危险吗","螃蟹习性","凶猛的螃蟹"}},{q="风歌蟹的蟹肉有什么用途？",a="采集到的蟹肉是螃蟹活跃的几周内从湖中捕获的珍贵时令食物，正因为邪教徒阻断了道路，当地人才会雇佣冒险者来完成采集。",al={"风歌蟹肉用途","为何收集蟹肉","蟹肉有什么用"}}},fp="11,149,18.180.0,19.235.0,27.135.0,48.144.0,58.125.0,34.105.0,40.74.0,39.163.0"}
P.entries["quest:93318"] = {n="WANTED: Vulgara the Insatiable",s="WANTED: Vulgara the Insatiable 是治安官的一项悬赏任务，旨在清除一头恐吓申达尔高地的巨大翼兽。该契约由安达警官发出，要求冒险者击杀这头贪婪的沃德伦并将她的头颅交给达纳里·贝洛维尔。",h="WANTED: Vulgara the Insatiable 是治安官的一项悬赏任务，旨在清除一头恐吓申达尔高地的巨大翼兽。该契约由安达警官发出，要求冒险者击杀这头贪婪的沃德伦并将她的头颅交给达纳里·贝洛维尔。",kw={"悬赏","安达警官","达纳里·贝洛维尔","治安官","申达尔高地","申达尔村","沃德伦","沃尔加拉","贪得无厌的沃尔加拉"},sec={{t="高地灾星",b="治安官安达发布了一份正式悬赏，将 Vulgara the Insatiable 列为对高地的直接威胁。这头巨大的带翼沃德伦一直在申达尔村西南方的巢穴中恐吓过往旅客和当地定居点，促使当地当局呼吁冒险赏金猎人结束她的统治。"},{t="受压迫的保护者",b="治安官们目前已是四面楚歌，疲于应对区域土匪和一个在该地区活动的神秘教派的威胁。消灭 Vulgara 将极大缓解当地民众的压力，确保申达尔上空的安全，让保卫者能专注于民防工作。"}},faq={{q="谁是 贪得无厌的沃尔加拉？",a="贪得无厌的沃尔加拉 是一头恐吓申达尔高地的巨大带翼沃德伦。她被当地当局视为高地的灾星，其贪婪的食欲和暴力的存在对旅客和附近定居点构成了严重危险。",al={"沃尔加拉 是谁","沃尔加拉 背景故事","沃尔加拉 是什么怪物"}},{q="是谁悬赏了 沃尔加拉？",a="当地治安官安达发布了针对 沃尔加拉 的正式悬赏以保护当地居民，并指示猎人将野兽死亡的证明交给达纳里·贝洛维尔。",al={"谁发布了 沃尔加拉 的悬赏","谁想杀死 沃尔加拉","安达警官"}},{q="在哪里可以找到 贪得无厌的沃尔加拉？",a="众所周知，沃尔加拉 在申达尔高地中申达尔村西南方的一处小高地上游荡。",al={"沃尔加拉 位置","沃尔加拉 在哪里刷新","找到 沃尔加拉"}},{q="谁是达纳里·贝洛维尔？",a="达纳里·贝洛维尔是负责处理悬赏完成情况的顾问。受到周边土匪和邪教徒的压迫，达纳里负责查验 沃尔加拉 的头颅并分发承诺的奖励。",al={"谁是达纳里·贝洛维尔","达纳里交任务"}},{q="沃德伦是什么生物？",a="沃德伦是一种生活在高地上的危险掠食性翼兽。沃尔加拉 是其中体型特别巨大且凶残的个体，其无尽的捕食威胁着当地的定居点。",al={"什么是沃德伦","沃德伦野兽"}},{q="申达尔高地还有什么其他威胁？",a="除了像 沃尔加拉 这样的掠食野兽外，申达尔高地的治安官们还疲于应付一个盘踞在此的教派以及劫掠当地居民的高地土匪所带来的活跃威胁。",al={"申达尔高地有什么威胁","申达尔的教派和土匪"}}},fp="30,204,20.264.0,20.212.0,30.207.0,33.155.0,42.81.0,26.180.0,35.164.0,49.174.0"}
P.entries["quest:93319"] = {n="Pilfered Windstones",s="“失窃的风石”是Zephras当地的一个任务，玩家需要从高地强盗手中收回重要的失窃资源。这些风石作为应急储备，对日常生活至关重要，但当地的治安官因受邪教徒威胁而分身乏术，无法亲自清除这些盗贼。",h="“失窃的风石”是Zephras当地的一个任务，玩家需要从高地强盗手中收回重要的失窃资源。这些风石作为应急储备，对日常生活至关重要，但当地的治安官因受邪教徒威胁而分身乏术，无法亲自清除这些盗贼。",kw={"奥恩达","强盗洞穴","法拉斯村","高地强盗","被盗的风石","申达尔高地","风石","泽弗拉斯"},ang={["class:Rogue"]="虽然高地强盗依靠粗劣的潜行手段来窃取储存的风石，但技艺高超的潜行者会意识到，这些盗贼正是在利用定居点因受邪教徒威胁而兵力吃紧的机会进行投机。",["race:Skyborne"]="Zephras的生活与风石息息相关，这使得这些物资的防御和回收对于维持当地定居点的生存至关重要。"},sec={{t="Zephras的失窃物资",b="在Zephras岛上，风石不仅仅是新奇的工艺品——它们是日常生活所必需的重要资源。各个定居点都留有应急补给箱，以确保在危机时刻能够生存下去。然而，村庄的储备开始持续短缺，直到人们发现从北部的申达尔高地抓获的强盗身上携带着这些石头，真相才大白。显然，这些潜行盗贼几个月来一直在潜入当地仓库，利用薄弱的防守搜刮他们能带走的任何物资。"},{t="防守吃紧与迫在眉睫的威胁",b="虽然清除北部的洞穴看起来是个显而易见的解决方案，但定居点的领导层却面临着艰难的抉择。负责村庄防御的Aonda拒绝批准反击突袭，因为社区仅有的几名治安官人手不足，无法调离。在南方，Falaath Village的邪教徒人数正在迅速增加，构成了严重的威胁，迫使守卫坚守岗位。由于治安官被邪教徒的威胁牵制，找回失窃风石的任务就落到了愿意直接面对强盗的独立冒险者身上。"}},faq={{q="泽风的风石有什么用？",a="在泽风，居民依赖风石进行日常生活和生存。因为它们对日常生活至关重要，当地定居点会尝试留出一部分应急补给箱进行储存。",al={"风石的用途","为什么需要风石","风石的作用"}},{q="是谁偷走了风石？",a="风石是被盘踞在申达尔高地一个洞穴中的高地强盗偷走的。在从被抓获的强盗身上发现这些石头后，当地人才意识到这些小偷可能已经潜入村庄仓库好几个月了。",al={"是谁偷了风石","谁拿走了风石","风石盗贼"}},{q="高地强盗在哪里？",a="高地强盗在定居点北部的申达尔高地内的一个洞穴中建立了营地，并将从村庄仓库偷来的物资囤积在那里。",al={"强盗洞穴在哪里","高地强盗的位置","申达尔强盗"}},{q="为什么村庄还没有清除强盗的洞穴？",a="负责定居点防御的安达选择不组织对北部洞穴的突袭，因为村庄的治安官人数非常少。将他们调走会使定居点容易受到南部法拉斯村日益增多的邪教徒的攻击。",al={"为什么不攻击强盗洞穴","为什么奥恩达不发起进攻","村庄防御强盗"}},{q="法拉斯村有什么威胁？",a="法拉斯村位于南方，目前那里的邪教徒数量正在令人担忧地激增。这种不断增长的威胁迫使当地治安官不得不留下来保卫家园，而不是去追捕强盗。",al={"法拉斯村有什么威胁","法拉斯的邪教徒","法拉斯邪教徒"}},{q="收回风石能解决定居点的短缺问题吗？",a="收回失窃的风石可以为应急储备提供暂时的缓解，但当地居民指出，更广泛的补给路线中断仍然是一个紧迫的问题。如果补给线不能尽快得到保障，短缺问题将继续威胁到定居点。",al={"风石现在安全了吗","泽风补给路线","风石短缺解决了吗"}}},fp="19,184,28.354.0,38.379.0,40.117.0,25.210.0,40.137.0,51.254.0,38.159.0,63.194.0"}
P.entries["quest:93320"] = {n="Tower Defense",s="“Tower Defense”标志着在加固阵地上针对压倒性敌军的绝望坚守。尽管前线守军勉强维持着暂时的僵局，但不断增加的疲劳感正威胁着防线的崩溃，急需迅速的干预。",h="“Tower Defense”标志着在加固阵地上针对压倒性敌军的绝望坚守。尽管前线守军勉强维持着暂时的僵局，但不断增加的疲劳感正威胁着防线的崩溃，急需迅速的干预。",kw={"守军","疲劳","防御工事","哨所","围攻","僵局","防御哨塔"},ang={["class:Warrior"]="针对数量上占优的敌军进行的防御性坚守，不仅考验技能，更考验耐力，需要训练有素的前线战士来防止全线崩溃。"},sec={{t="困守的防线",b="“Tower Defense”的核心是在重重围攻之下于加固阵地进行的绝望坚守。守军设法阻挡了最初的猛攻，但敌军拥有数量优势，并持续施加压力。随着幸存战士们陷入疲惫，生存与失败之间那道暂时的屏障正变得愈发脆弱。"},{t="消耗战的威胁",b="尽管维持着防御圈，但时间对守军不利。面对数量占优的敌军进行旷日持久的遭遇战，守军的体力正在稳步消耗，使战斗变成了艰苦的消耗战。为了在围攻中幸存，守军迫切需要采取决定性行动来打破僵局，防止防线崩溃。"}},faq={{q="什么是“高塔防御”？",a="“高塔防御”是一场紧急防御行动，守军正在竭力坚守阵地以抵御压倒性的敌军。虽然目前防线尚存，但消耗与疲劳正威胁着防御的瓦解，除非能找到决定性的反制手段。",al={"什么是防御哨塔","防御哨塔任务","这个任务是什么"}},{q="守军在与谁作战？",a="相较于守军，进攻方拥有数量优势，他们施加的压力足以逐渐磨损守军的体力，迫使双方进入紧张的僵局。除了这些危险的敌军数量外，其具体的所属势力尚无记录。",al={"防御哨塔中谁在攻击","我们在与谁作战","防御哨塔的敌人"}},{q="守军目前的状况如何？",a="在无情的猛攻下，经过长时间的战斗，守军开始感到疲惫。在缺乏增援的情况下直面占据数量优势的敌军，除非迅速采取行动打破僵局，否则守军有失守的风险。",al={"为什么守军很疲惫","塔楼处的僵局","战斗的状态"}},{q="坚守阵地能解决战斗吗？",a="击退进攻只是暂时的喘息，而非最终的胜利。地面部队意识到，除非能有打破僵局的即时计划，否则疲劳最终会压垮他们。",al={"我们赢了防御哨塔吗","防御哨塔如何结束","击退他们后会发生什么"}},{q="这场防御战发生在什么地方？",a="防御战发生在一处被围困的加固哨所，防御部队因遭受大量敌方战斗人员的持续压制而兵力捉襟见肘。",al={"防御哨塔位于何处","防御哨塔区域","这是哪座塔楼"}},{q="需要什么来扭转战局？",a="守军必须设计出快速的战略来打破围攻，在筋疲力尽的前线于敌军数量重压下崩溃之前扭转战局。",al={"接下来需要做什么","如何赢得围攻战","打破僵局"}}},fp="13,156,21.221.0,23.219.0,28.152.0,31.143.0,44.155.0,41.131.0,35.135.0,32.94.0"}
P.entries["quest:93394"] = {n="Meeting the Magister",s="一位辛德拉联络人请你前往辛德拉神殿，寻找Magister Kirandis。你们将谈及修复好的圣柱，以及你在那些心存戒备的居民中的处境。",h="一位辛德拉联络人请你前往辛德拉神殿，寻找Magister Kirandis。你们将谈及修复好的圣柱，以及你在那些心存戒备的居民中的处境。",kw={"kirandis","magister kirandis","会见法师","圣柱","辛德拉","神殿"},sec={{t="神殿之中",b="宏伟的建筑吸引了你的目光，一位辛德拉联络人指引你去找Magister Kirandis。这位法师是派你前来的那人的老朋友，或许会欢迎你的到来。辛德拉可能心存戒备，因此对他们务必以礼相待。"},{t="圣柱",b="找到Kirandis后，这位法师看到圣柱的力量再次闪耀。圣柱重现，使辛德拉与辛德拉完全紧密相连。Kirandis劝你去结识神殿里的居民，他们的戒心或许会随时间消退。"}},faq={{q="我要找谁？",a="请你前往辛德拉神殿寻找Magister Kirandis。",al={"寻找kirandis","法师会面","kirandis神殿"}},{q="Magister Kirandis在哪里？",a="Magister Kirandis在辛德拉神殿里。",al={"kirandis位置","法师在哪里","神殿kirandis"}},{q="Kirandis和派我来的人是什么关系？",a="Kirandis是那位派你前来的辛德拉联络人的老朋友。",al={"kirandis朋友","法师的老朋友"}},{q="辛德拉会欢迎我吗？",a="辛德拉可能对你的到来心存戒备，但请你谨慎行事，以礼相待。",al={"辛德拉戒备","他们会喜欢我吗","辛德拉是否欢迎"}},{q="圣柱怎么样了？",a="圣柱的力量再次闪耀，Kirandis说，这使辛德拉与辛德拉完全紧密相连。",al={"圣柱力量","神殿圣柱","圣柱修复"}},{q="见过Kirandis之后，我该做什么？",a="Kirandis鼓励你去结识神殿里的居民，他们起初可能会心存戒备。",al={"结识居民","见过kirandis之后做什么","辛德拉居民"}}},fp="20,180,13.266.0,10.221.0,26.75.0,27.54.0,42.66.0,32.86.0,32.92.0,40.88.0"}
P.entries["quest:934"] = {n="大地之冠",s="大地之冠是多兰纳尔任务线中的关键一步，旨在调查困扰泰达希尔的种种病态。科瑞萨斯·月怒要求冒险者从神谕林地的神圣月井中汲取泉水，并借此旅程揭露世界之树创造背后的令人不安的真相。",h="大地之冠是多兰纳尔任务线中的关键一步，旨在调查困扰泰达希尔的种种病态。科瑞萨斯·月怒要求冒险者从神谕林地的神圣月井中汲取泉水，并借此旅程揭露世界之树创造背后的令人不安的真相。",kw={"阿莱克丝塔萨","紫水晶瓶","科瑞萨斯·月怒","范达尔·鹿盔","永生","月井","诺兹多姆","神谕林地","神谕之树","泰达希尔"},ang={["class:Druid"]="对于塞纳里奥议会而言，拜访神谕之树突显了范达尔·鹿盔激进的野心与玛法里奥·怒风传统所维护的自然平衡之间的意识形态分歧。",["faction:Alliance"]="了解泰达希尔脆弱的状态，有助于解释困扰联盟这片最新首都领地的持续枯萎病和生物疯狂现象。",["race:NightElf"]="这段旅程触及了暗夜精灵在第三次战争中牺牲诺达希尔后，对泰达希尔所寄予的希望。"},sec={{t="神谕林地",b="科瑞萨斯·月怒指引旅行者前往泰达希尔的西北方，那里坐落在神谕林地宏伟的树冠之下。在神谕之树巨大的枝干下方，静静地躺着这座岛屿上第一口、也是最强大的月井。从它那波光粼粼的井水中取出一瓶紫水晶瓶，让探寻者们得以亲眼见证德鲁伊和世界之树本身用以监测其新家园健康状况的核心圣所。"},{t="被拒绝的祝福",b="在将紫水晶瓶交还给多兰纳尔后，科瑞萨斯揭示了大德鲁伊范达尔·鹿盔宏伟计划中的阴暗缺陷。在海加尔山的诺达希尔被牺牲后，鹿盔试图通过种植泰达希尔并请求龙王赐福来恢复暗夜精灵的永生。然而，永恒者诺兹多姆拒绝了请求，并斥责鹿盔极其狂妄自大。阿莱克丝塔萨紧随其后，拒绝给予生命缚誓者的重要祝福，使得泰达希尔的生长变得不稳定、不完美，并极易受到深层腐蚀的影响。"}},faq={{q="神谕林地的月井在哪里？",a="该月井位于泰达希尔西北部，坐落在通往达纳苏斯主路的正北方。它位于神谕之树巨大的枝干下方。",al={"神谕林地在哪里","神谕林地月井位置","神谕月井"}},{q="科瑞萨斯·月怒是谁？",a="科瑞萨斯·月怒是一位驻扎在多兰纳尔的暗夜精灵守望者。他指引年轻的保卫者们穿越泰达希尔的枝干去取用其月井之水，并传授关于这棵树那充满缺陷的开端的历史。",al={"科瑞萨斯","科瑞萨斯·月怒是谁"}},{q="泰达希尔恢复了暗夜精灵的永生吗？",a="没有。虽然泰达希尔为暗夜精灵提供了一个新的家园，但他们在第三次战争中牺牲诺达希尔之后，其永恒的生命并未得到恢复。",al={"暗夜精灵永生吗","泰达希尔永生","精灵能再次长生不老吗"}},{q="从神谕林地取水的目的是什么？",a="神谕之树下方的月井是岛上第一口、也是最强大的水井。汲取其泉水可以让科瑞萨斯评估泰达希尔内在的精神和自然健康状况。",al={"为什么要获取神谕之水","紫水晶瓶用途"}}},fp="18,174,16.321.0,19.520.1,43.152.0,26.190.0,45.139.0,62.156.0"}
P.entries["quest:93461"] = {n="Welcome to Shen'dar Village",s="\"Welcome to Shen'dar Village\"向旅行者介绍了一处偏僻的避难所，这里由古老的上层精灵血统和暗流涌动的阵营竞争塑造而成。虽然高阶会和塑风者在定居点内保持着表面的休战，但苦涩的紧张气氛在村庄边界之外挥之不去。",h="\"Welcome to Shen'dar...",kw={"科莉艾拉·静风","高阶会","上层精灵","主旅店","拉希里尔·阳矛","申达尔村","塑风者"},ang={["class:Mage"]="与上层精灵传统有渊源的法师会在高阶会中找到熟悉的血统，像Rathiril Sunlance这样的长者在申达尔享有崇高的声望。",["race:NightElf"]="申达尔村沉浸在古老上层精灵的遗产和血统中，这让它成为了一个令人不安的提醒，让人想起那段分裂了精灵社会的骄傲与奥术传承。"},sec={{t="脆弱的家园",b="申达尔村是一处脆弱的避难所，不同的精灵阵营在紧张的休战中并存。表现出上层精灵血统痕迹的新来者会被迅速引导去向高阶会的长者Rathiril Sunlance致意，地点就在定居点的主旅店，并向当地旅店老板Coriella Calmbreeze安排住宿。"},{t="野外的竞争",b="在平淡的住宿和零工琐事之下，两个显赫团体之间潜藏着摩擦：高阶会和塑风者。虽然在村庄广场的安全范围内严格遵守礼仪，但在周围的荒野中敌意却肆无忌惮，旧日的恩怨在那里远离窥探的目光得以解决。"}},faq={{q="任务“欢迎来到申达尔村”的目的是什么？",a="“欢迎来到申达尔村”是一个引导任务，让刚抵达的冒险者了解定居点的关键人物和脆弱的和平。你会被引导去见驻扎的高阶会长者拉希里尔·阳矛，以及在村庄旅店的科莉艾拉·静风，然后再接受当地的任务。",al={"这个任务是什么","欢迎来到申达尔村信息","申达尔村介绍"}},{q="拉希里尔·阳矛是谁？",a="拉希里尔·阳矛是居住在申达尔村的一位高阶会长者。他驻扎在村庄的主旅店中，就在初始任务发放者的拐角处，是那些带有上层精灵血统或与高阶会有往来的人员的主要联络人。",al={"拉希里尔·阳矛是谁","高阶会长者","拉希里尔在哪里"}},{q="科莉艾拉·静风是谁？",a="科莉艾拉·静风经营着申达尔村的当地旅店。她为旅行者提供必要的接待，为准备前往周围荒野的人们提供食物、住宿和补给。",al={"科莉艾拉·静风是谁","申达尔旅店老板","在申达尔哪里住宿"}},{q="高阶会和塑风者之间有什么紧张关系？",a="由于传统和抱负的差异，高阶会和塑风者之间的关系高度紧张。虽然这两个阵营设法在申达尔村的边界内维持着文明的共存，但这种克制在村庄边缘就结束了，冲突往往会演变成荒野中的暴力。",al={"高阶会与塑风者","为什么存在紧张关系","村庄冲突"}},{q="任务发放者提到的“高阶会气质”是什么？",a="那些源自上层精灵的后裔以眼中独特的光芒而著称，这是一种奥术传承，让敏锐的当地人能立刻辨认出他们具有高阶会的气质。",al={"高阶会气质","上层精灵之眼","上层精灵之光"}},{q="申达尔村免受冲突之扰吗？",a="在申达尔村内，高阶会和塑风者等敌对阵营之间严格执行着礼仪。然而，在定居点之外，这种和平并不存在，公开的敌意往往在远离注视目光的地方爆发。",al={"申达尔安全吗","申达尔外的暴力","荒野危险"}}},fp="27,199,16.267.0,22.230.0,61.211.0,25.249.0,27.156.0,63.230.0,56.157.0,39.171.0"}
P.entries["quest:93464"] = {n="The Visiting Mage",s="避难营的一名draenei请你去凄凉之地寻找人类法师Azore。他对draenethyst的了解，或许能帮助那些尚未完全理解其力量的人。",h="避难营的一名draenei请你去凄凉之地寻找人类法师Azore。他对draenethyst的了解，或许能帮助那些尚未完全理解其力量的人。",kw={"azore","凄凉之地","draenei","draenethyst","避难营","人类法师"},sec={{t="一位法师的往事",b="在避难营，一名draenei回忆起Azore从凄凉之地来访时，自己曾将他赶走。这位人类法师惧怕draenethyst的力量，并警告说不能让它落入坏人之手。如今，他的知识似乎值得寻求，尽管这名draenei承认这里的人并未完全理解这块水晶。你受托前往凄凉之地寻找Azore。"}},faq={{q="Azore是谁？",a="Azore是来自凄凉之地的人类法师，曾到访避难营。他惧怕draenethyst的力量。",al={"azore是谁","来访的法师","draenethyst法师"}},{q="draenethyst是什么？",a="draenethyst对避难营的draenei而言是圣物，能帮助他们保持理智，尽管他们并未完全理解它。",al={"draenethyst","draenei水晶","draenethyst是什么"}},{q="我为什么要找Azore？",a="避难营的draenei认为，Azore对draenethyst的了解可能很有价值。",al={"寻找azore","为何寻找法师","凄凉之地的法师"}},{q="Azore去了哪里？",a="Azore在凄凉之地。",al={"azore的位置","法师在哪里","寻找来访的法师"}},{q="draenei为什么要赶走Azore？",a="他们赶走Azore，是为了保护属于自己的东西。",al={"为何赶走azore","azore被赶走","避难营的法师"}}},fp="17,159,17.336.0,13.98.0,20.119.0,27.88.0,19.21.0,37.49.0"}
P.entries["quest:93465"] = {n="Notes on Draenethyst",s="阿佐尔·奥达蒙特派你去取回 Gimashi 关于 draenethyst 的笔记。火刃氏族的术士正在研究这种来自黑暗之门另一边的物质。",h="阿佐尔·奥达蒙特派你去取回 Gimashi 关于 draenethyst 的笔记。火刃氏族的术士正在研究这种来自黑暗之门另一边的物质。",kw={"阿佐尔·奥达蒙特","火刃氏族","黑暗之门","draenethyst","gimashi","笔记","术士"},sec={{t="Gimashi 的笔记",b="阿佐尔·奥达蒙特说，Gimashi 的笔记或许能说明火刃氏族对 draenethyst 有何发现。Gimashi 是一名术士，她的高塔矗立在东南方的一处峡谷中。你需要在火刃氏族利用他们对这种物质的了解作恶之前，将她的笔记带回给阿佐尔。"}},faq={{q="draenethyst 是什么？",a="draenethyst 是一种来自黑暗之门另一边的物质。",al={"draenethyst 的含义","什么是 draenethyst","draenethyst 石"}},{q="Gimashi 是谁？",a="Gimashi 是一名研究 draenethyst 的火刃氏族术士。",al={"gimashi 是谁","术士 gimashi","gimashi 的笔记"}},{q="阿佐尔为什么想要 Gimashi 的笔记？",a="阿佐尔想通过 Gimashi 的笔记了解火刃氏族对 draenethyst 知道些什么。",al={"为什么要笔记","阿佐尔 draenethyst","阿佐尔需要什么"}},{q="Gimashi 在哪里？",a="在东南方一处峡谷里的高塔顶端可以找到 Gimashi。",al={"gimashi 的位置","高塔在哪里","东南方峡谷"}},{q="draenethyst 来自哪里？",a="draenethyst 来自黑暗之门另一边。",al={"draenethyst 的来源","黑暗之门的物质","draenethyst 来自哪里"}}},fp="20,157,15.300.0,20.55.0,15.56.0,36.84.0,17.65.0,32.45.0"}
P.entries["quest:935"] = {n="大地之冠",s="“大地之冠”标志着泰达希尔各地月亮井仪式的终点。将收集到的井水交给达纳苏斯的大德鲁伊范达尔·鹿盔，凸显了人们对于世界之树因缺乏祝福而存在缺陷这一事实日益增长的焦虑。",h="“大地之冠”标志着泰达希尔各地月亮井仪式的终点。将收集到的井水交给达纳苏斯的大德鲁伊范达尔·鹿盔，凸显了人们对于世界之树因缺乏祝福而存在缺陷这一事实日益增长的焦虑。",kw={"阿莱克丝塔萨","塞纳里奥区","科瑞萨斯·月怒","大地之冠","达纳苏斯","范达尔·鹿盔","月亮井","诺兹多姆","泰达希尔"},ang={["class:Druid"]="将月亮井水送到塞纳里奥议会大德鲁伊面前，让你直接面对范达尔·鹿盔，这也展示了在玛法里奥缺席的情况下，德鲁伊领导层内部存在的激烈政治和精神分歧。",["faction:Alliance"]="对于更广泛的联盟来说，达纳苏斯是一座充满古老神秘感的宏伟首都，但其周围被腐蚀的荒野证明，即使是暗夜精灵，在他们自己的神圣土地上也面临着内部危险。",["race:NightElf"]="这一仪式揭示了你新家园之下暗藏的焦虑：泰达希尔是在傲慢中种植的，并未得到守护巨龙的祝福；其日益严重的病症提醒着人们，你们种族的新起点是多么脆弱。"},sec={{t="一个有缺陷的开端",b="泰达希尔在第三次战争后被催生出来，旨在为暗夜精灵提供一个新的家园，并恢复他们失去的永生。然而，巨龙军团的守护巨龙阿莱克丝塔萨和诺兹多姆拒绝给予祝福，不愿认可这棵树的创造。由于缺乏他们的神圣庇护，泰达希尔已成为不断蔓延的病疫的受害者，导致奇异的生物从树枝中涌现，曾经平静的熊怪部族也陷入了疯狂。"},{t="交付给大德鲁伊",b="科瑞萨斯·月怒委派年轻的冒险者收集岛上各处月亮井的井水，以监测和缓解大树的病症。科瑞萨斯将这些样本汇集成一个容器，派送信使深入达纳苏斯的塞纳里奥区。泰达希尔的缔造者——大德鲁伊范达尔·鹿盔就坐在那里，他并不将这种蔓延的腐蚀视为傲慢的预兆，而是将其看作一种他必须独自解决的恼人负担。"}},faq={{q="为什么范达尔·鹿盔需要这些月亮井水？",a="范达尔·鹿盔委托他人收集泰达希尔各处的月亮井水样本，旨在研究并应对正在世界之树中蔓延的腐蚀。作为主张种植这棵树的领袖，他肩负着寻找解决方案的重任，以解决扰乱树冠的奇异野兽和疯狂的熊怪。",al={"范达尔获取水的目的","范达尔为何需要此容器","井水的用途"}},{q="为什么泰达希尔会受到腐蚀和疯狂野兽的困扰？",a="与古老的世界之树诺达希尔不同，泰达希尔在种植时并没有得到生命赐予者阿莱克丝塔萨或永恒者诺兹多姆的祝福。由于缺乏这些原始守护巨龙的庇护，这棵新树的生长从根本上存在缺陷，使得奇异的恶性力量在土壤中扎根，并扭曲了附近的野生动物和熊怪。",al={"泰达希尔为何生病","泰达希尔的腐蚀","熊怪为何疯狂"}},{q="大德鲁伊范达尔·鹿盔在哪里？",a="大德鲁伊范达尔·鹿盔位于达纳苏斯的塞纳里奥区。你可以在俯瞰该区域圣林的中央德鲁伊亭台顶上找到他。",al={"范达尔的位置","范达尔·鹿盔的位置","如何找到范达尔"}},{q="科瑞萨斯·月怒是谁？",a="科瑞萨斯·月怒是一位驻扎在多兰纳尔的暗夜精灵，他指派年轻的冒险者在泰达希尔的月亮井中装满瓶子。他会将他们带来的瓶子倒入一个容器中，并指示信使将其送往达纳苏斯的大德鲁伊范达尔·鹿盔处。",al={"谁提供大地之冠","科瑞萨斯的职责","科瑞萨斯·月怒"}},{q="完成此任务后会发生什么？",a="将装满月亮井水的瓶子交给范达尔·鹿盔，便完成了泰达希尔的“大地之冠”系列任务。鹿盔会相当冷淡地收下井水，随后将注意力转回处理威胁着暗夜精灵家园的更广泛的危机上。",al={"大地之冠后续","大地之冠 6之后的内容","大地之冠后的下一个任务"}},{q="为什么范达尔·鹿盔在收到容器时如此冷淡？",a="范达尔·鹿盔以高傲、急躁著称，并且在玛法里奥·怒风缺席期间，背负着治理塞纳里奥议会的艰巨任务。他蔑视行政上的挫折和缓慢的信使，因为他感到泰达希尔生存的重担完全压在自己肩上。",al={"范达尔为何粗鲁","范达尔的性格","范达尔一直这么暴躁吗"}}},fp="18,209,16.368.0,26.368.1,51.257.0,58.324.0,45.161.0,26.239.0,41.201.1,64.240.0"}
P.entries["quest:93552"] = {n="Harvesting Windstones",s="“收集风石”是一项由森达尔林地的收藏家达莉亚提供的任务。随着维持岛屿的远古元素能量逐渐消散，原始风石已成为一种必不可少的魔法燃料来源。冒险者们被派往林地各地，在风石的力量流失前采集结晶风石簇。",h="“收集风石”是一项由森达尔林地的收藏家达莉亚提供的任务。随着维持岛屿的远古元素能量逐渐消散，原始风石已成为一种必不可少的魔法燃料来源。冒险者们被派往林地各地，在风石的力量流失前采集结晶风石簇。",kw={"大锚柱","达莉亚","收藏家达莉亚","森达尔林地","风元素生物","风石簇","风石","泽风岛"},ang={["class:Mage"]="对于奥术修行者来说，风石中集中的元素力量是一个鲜明的警示，提醒人们当魔法生态系统失去其元素来源时，会变得多么脆弱。",["profession:Mining"]="采集原始风石是了解如何从泽风岛荒野中收集珍贵矿物和水晶的入门途径。"},sec={{t="正在消逝的岛屿",b="泽风岛严重依赖残留的风系魔法来维持自身，但其天然屏障正日益薄弱。几个世纪前，与当地精灵共同居住在岛上的原生风元素生物完全消失了。自它们离去后，维持这片土地和大锚柱的源生魔法便一直处于缓慢而稳定的衰退中。对于森达尔林地的居民来说，想要在这种匮乏中生存下去，就必须尽一切可能储备原始能量。"},{t="风石的价值",b="风石是散布在森达尔林地各处的亮蓝色结晶体。它们脆弱的外壳内蕴含着浓缩的密集风系魔法，这些魔法是往昔留下的遗产。虽然它们并非取之不尽的解决方案，但却为岛上的精灵提供了可靠且不可或缺的奥术维持和效用来源，这使得收集原始结晶成为了一项重要的日常工作。"}},faq={{q="什么是风石？",a="风石是森达尔林地周围发现的蓝色结晶矿床，其中含有浓缩的原始风系能量。泽风岛的精灵们采集它们作为基本的魔法燃料来源。",al={"原始风石","风石簇","蓝色水晶"}},{q="收藏家达莉亚是谁？",a="达莉亚是一位驻扎在泽风岛森达尔林地的精灵收藏家。她负责组织采集重要的原始资源，特别是风石，以帮助支持岛上日益枯竭的魔法储备。",al={"达莉亚","达莉亚 泽风岛","收藏家达莉亚"}},{q="为什么泽风岛上的魔法正在消逝？",a="几个世纪前，与当地精灵共同生活的风元素生物消失了。由于失去了它们的存在，大锚柱注入岛屿的结界正在缓慢流失。",al={"泽风岛魔法流失","泽风岛消逝的魔法","大锚柱"}},{q="风元素生物去了哪里？",a="它们的具体去向仍是一个谜。目前只知道它们在几个世纪前消失了，留下了这座岛屿缓慢消耗其剩余的元素储备。",al={"失踪的元素生物","风元素生物在哪里","元素生物消失"}},{q="什么是大锚柱？",a="大锚柱是泽风岛上的古老建筑，其中注入了维持这片土地的强大魔法。随着元素生物的消失，它们维持性的能量正在逐渐减弱。",al={"大锚柱","大锚柱背景"}},{q="在哪里可以找到原始风石？",a="原始风石散布在泽风岛的森达尔林地各地，外观表现为发光的蓝色结晶露头。",al={"风石位置","森达尔林地水晶"}}},fx={["0a83a06c"]={q="收藏家达莉亚为什么需要风石簇？",a="泽风岛依靠风石簇的魔力维系生机，因此达莉亚才会寻找它们。数百年前风元素消失后，曾经滋养这座岛屿的维系魔法便一直在逐渐衰退。对当地精灵而言，生活和文化都与奥术能量密切相连，收集这些凝结的风能便能提供重要而可靠的能源，弥补日渐失效的锚定水晶柱所无法供应的部分。",al={"达莉亚为什么需要风石","收藏家达莉亚的动机","为什么采集风石"}},["33ac4299"]={q="风石簇有什么用？",a="风石簇蕴含着风本身原始而浓缩的能量。泽风岛上的古老魔法锚定水晶柱正逐渐失去效力，岛民便利用这些凝结的风石簇作为可靠的替代能源，以维持社群运转，并保持与魔法能量的重要联系。",al={"风石簇的用途","风石簇是做什么用的","为什么要风石簇"}}},fp="21,166,15.327.0,23.276.0,20.168.0,27.214.0,40.178.0,33.152.0,27.191.0,33.122.0"}
P.entries["quest:93644"] = {n="Tattered Journal",s="在辛德拉附近发现的一本破损日记，指向了它的作者 Evenshade。残存的字句或许对他仍有意义。",h="在辛德拉附近发现的一本破损日记，指向了它的作者 Evenshade。残存的字句或许对他仍有意义。",kw={"损坏的日记","evenshade","遗失的日记","mordent","修复日记","辛德拉","破损日记"},sec={{t="留下的姓名",b="在辛德拉附近，这本日记的残破纸页上几乎没有可读的内容。模糊的字迹中，只有一个姓氏清晰可辨：Evenshade。作者或许就在附近，日记残存的字句是唯一的线索。"},{t="日记的归宿",b="Mordent认出这本日记是自己的，尽管他遗失它已有数百年。文字已经消失，但他记得日记中写了什么，并将这份记忆藏在心底。如果日记的纸页还在，他允许你尝试修复它。"}},faq={{q="在哪里发现了这本日记？",a="这本日记是在辛德拉附近发现的。",al={"日记在哪里","破损日记位置"}},{q="谁写了这本日记？",a="日记中残存的姓名表明，作者是 Evenshade。",al={"日记作者","evenshade日记"}},{q="为什么要寻找 Evenshade？",a="日记上留有姓氏 Evenshade，作者或许就在辛德拉某处。",al={"寻找evenshade","日记姓氏"}},{q="你能读懂这本日记吗？",a="日记中的大部分内容已经遗失，残存的字迹也难以辨认。",al={"日记无法辨认","日记内容"}},{q="Mordent怎么说这本日记？",a="Mordent认出这是自己遗失的日记，但说上面的文字已经消失。",al={"mordent日记","日记主人"}},{q="Mordent愿意透露日记写了什么吗？",a="Mordent记得日记中写了什么，但不愿说出来。",al={"日记内容","mordent的秘密"}}},fp="16,124,14.231.0,18.250.1,28.39.0,22.71.0,23.88.0,25.96.0,40.72.0,36.85.0"}
P.entries["quest:93663"] = {n="Lost in Transit",s="达尔请你寻找一名失踪的地精信使和他送往避难营的货物。货物丢失会损害达尔的商誉。",h="达尔请你寻找一名失踪的地精信使和他送往避难营的货物。货物丢失会损害达尔的商誉。",kw={"鳄鱼","达尔","德莱尼","地精信使","避难营","失踪的货物","货物","贸易"},sec={{t="失踪的货物",b="达尔用额外的补给品与避难营的德莱尼交换部分渔获。如今，他的地精信使迟迟没有带着货物回来。达尔担心鳄鱼可能杀了信使，但找回货物对他的生意至关重要。你需要在路边的水域附近搜寻，并把货物送到避难营。"}},faq={{q="达尔是谁？",a="达尔用额外的补给品与避难营的德莱尼交换部分渔获。",al={"达尔","谁发出了货物","地精商人"}},{q="失踪的信使是谁？",a="达尔派了一名地精信使运送最新一批货物，但信使一直没有回来。",al={"失踪的地精","信使在哪里","地精信使"}},{q="货物要送到哪里？",a="货物原本要送给避难营的德莱尼。",al={"货物目的地","货物送到哪里","送货到避难营"}},{q="达尔为什么要找回货物？",a="达尔说，如果货物找不回来并送达，他的商誉就会受到影响。",al={"为什么要找货物","达尔的商誉","为什么这很重要"}},{q="我该去哪里找信使？",a="达尔请你去路边的水域附近查看。",al={"搜寻地点","信使位置","失踪的货物在哪里"}}},fp="15,130,18.328.0,11.84.0,27.83.0,29.56.0,37.88.0,36.53.0"}
P.entries["quest:93680"] = {n="城市大门钥匙",s="位于塔伦米尔的大法师沃迪恩·伍德格莱尔想要了解更多关于肯瑞托的信息，他们的城市曾被阿克蒙德摧毁，如今又在黑暗女王的家门口重建了达拉然。你要搜寻肯瑞托的营地，寻找能让部落神不知鬼不觉地进入这座城市的东西。",h="位于塔伦米尔的大法师沃迪恩·伍德格莱尔想要了解更多关于肯瑞托的信息，他们的城市曾被阿克蒙德摧毁，如今又在黑暗女王的家门口重建了达拉然。你要搜寻肯瑞托的营地，寻找能让部落神不知鬼不觉地进入这座城市的东西。",kw={"阿克蒙德","燃烧军团","达拉然","肮脏的钥匙","肯瑞托","下水道钥匙","塔伦米尔","沃迪恩·伍德格莱尔"},sec={{t="重建之城",b="联盟曾经拥有一支法师军队，即肯瑞托，但恶魔燃烧军团证明了他们更强大。恶魔领主阿克蒙德一击就夷平了他们的城市，幸存者沦为无家可归的流浪者。现在，他们在黑暗女王的家门口重建了达拉然。位于塔伦米尔的大法师沃迪恩·伍德格莱尔想要了解更多情况，并派你去搜寻他们的营地，寻找某种东西，比如一本古老的典籍或一件秘密圣物，好让部落能神不知鬼不觉地潜入这座城市。你带回来的是一把肮脏的达拉然下水道钥匙。"},{t="沃迪恩的回答",b="看到下水道钥匙后，沃迪恩说幸好会有别人去使用它。在可以安全使用之前，还有很多工作要做。"}},faq={{q="谁发布了“城市大门钥匙”任务？",a="位于塔伦米尔的大法师沃迪恩·伍德格莱尔。",al={"谁发布城市大门钥匙任务","城市大门钥匙任务给予者","在哪里开始城市大门钥匙任务"}},{q="为什么部落对达拉然感兴趣？",a="肯瑞托的城市曾被阿克蒙德摧毁，如今他们在黑暗女王的家门口重建了达拉然。沃迪恩想要了解更多情况，并需要一条不被察觉的潜入途径。",al={"为什么关注达拉然","为什么要监视达拉然","法师们在做什么"}},{q="你要去寻找什么物品？",a="一把达拉然下水道钥匙，一把肮脏的钥匙，可以在肯瑞托的营地中找到。",al={"我要为沃迪恩获取什么","这把钥匙是什么","城市大门钥匙物品"}}},fp="15,76,16.518.0,16.120.1,42.56.0,39.191.0,31.73.0"}
P.entries["quest:937"] = {n="神谕林地",s="在泰达希尔西北部的神谕林地，哨兵阿瑞尼亚·碎云正竭力保护古老的神谕之树免受好战的血羽鹰身人的侵扰。在一名前往达纳苏斯的信使被杀害后，保卫者们被召集起来反击鹰身人的巢穴，并回收它们的血羽腰带作为证明。",h="在泰达希尔西北部的神谕林地，哨兵阿瑞尼亚·碎云正竭力保护古老的神谕之树免受好战的血羽鹰身人的侵扰。在一名前往达纳苏斯的信使被杀害后，保卫者们被召集起来反击鹰身人的巢穴，并回收它们的血羽腰带作为证明。",kw={"阿瑞尼亚·碎云","血羽","达纳苏斯","鹰身人","神谕林地","神谕之树","哨兵","泰达希尔","被附魔的林地"},ang={["class:Druid"]="德鲁伊非常敬畏这些有知觉的古树；清除威胁神谕之树的鹰身人寄生有助于保护林地的自然平衡。",["faction:Alliance"]="协助哨兵保护泰达希尔的神圣树林，可以加强与附近达纳苏斯的暗夜精灵领导层的联系。",["race:NightElf"]="保卫世界之树的远古灵魂，并守护哨兵免受鹰身人的玷污，是任何卡多雷的神圣职责。"},sec={{t="遭到围困的林地",b="神谕林地是泰达希尔的神圣隐居处之一，以一棵被称为神谕之树的巨大古树为核心。哨兵阿瑞尼亚·碎云率领一队战士被派往此处，守护这根古老的枝干。不幸的是，凶残的血羽鹰身人侵占了这些空洞，在周围的树冠上筑巢，威胁着任何靠近的人。"},{t="通往达纳苏斯的通讯断绝",b="当神谕之树试图派遣一名信使前往首府达纳苏斯递送一份紧急报告时，局势变得极其紧张。信使没能离开树冠；鹰身人在报告离开林地之前就伏击并杀害了这名奔跑者。作为回应，阿瑞尼亚指派当地的冒险者去清除这些鸟群，并回收血羽腰带，以击退这些入侵的群落。"},{t="来自古树的召唤",b="一旦附近巢穴的直接威胁被消除，这棵古树本身就会做出回应。神谕之树剥落了一块带有魔力的树皮碎片，寻求一名特使将它的信息传达给卡多雷的高层领导者手中。"}},faq={{q="鹰身人为何攻击神谕林地？",a="血羽氏族在泰达希尔北部筑有密集的巢穴。在神谕林地，它们包围了神谕之树，凶猛地守卫着它们的栖息地，并攻击任何试图往返于这一圣地的人。",al={"神谕林地的鹰身人","血羽为何攻击","神谕之树的鹰身人"}},{q="谁是哨兵阿瑞尼亚·碎云？",a="阿瑞尼亚·碎云是一位哨兵军官，驻扎在神谕林地，并带有一支小规模的前卫部队。她的主要任务是保护神谕之树免受周围鹰身人的侵害，并重新建立与达纳苏斯的联系。",al={"阿瑞尼亚·碎云","谁给予被附魔的林地","碎云背景故事"}},{q="前往达纳苏斯的信使发生了什么事？",a="那名携带来自神谕之树的报告前往达纳苏斯的信使，在抵达安全地带之前，沿途被血羽鹰身人伏击并杀害。",al={"神谕之树的信使","达纳苏斯死去的信使"}},{q="什么是神谕之树？",a="神谕之树是一棵扎根于神谕林地的巨大且有知觉的古树。它观察着世界之树的枝干，并将它的智慧和警示传达给暗夜精灵的领导层。",al={"泰达希尔的神谕之树","什么是神谕之树"}},{q="哨兵碎云需要什么证明？",a="哨兵碎云需要从被杀死的鹰身人身上取得六条血羽腰带，以此作为它们在林地周围的栖息地已被削弱的确凿证据。",al={"血羽腰带任务","需要多少条腰带","任务证明"}},{q="清除鹰身人后会发生什么？",a="当直接周边的安全得到保障后，神谕之树会剥落一块自己的树皮，开启一条直接通讯线路，供冒险者将它那久拖未决的信息送往达纳苏斯。",al={"被附魔的林地之后的任务","神谕之树接下来做什么"}}},fp="19,252,19.296.0,26.290.0,23.172.1,43.181.0,35.187.0,46.175.0,24.178.0,45.149.0,39.146.1"}
P.entries["quest:93735"] = {n="The Broken Construct",s="“The Broken Construct”涉及协助瓦拉纳尔的一名工匠，他正在努力修复一个稀有且受损的自动机。这些机器最初是由远去的风之灵所赠，并由塑风者精心保存，这使得每一个依然能运转的构装体都成为了岛屿过去无比珍贵的遗物。",h="“The Broken...",kw={"工匠","the broken construct","构装体","riaani nightwind","瓦拉纳尔","风之灵","塑风者"},ang={["class:Mage"]="由塑风者维护的构装体和仪器依靠精密的魔法装置运行，这使得它们的维护工作引起了奥术修行者们的特别关注。",["class:Shaman"]="这些构装体最初由风之灵所赠，凸显了在灵体离去前，当地居民与元素力量之间深厚的历史羁绊。",["profession:Engineering"]="致力于修复古老附魔构装体的工匠们，在没有原先灵体守护的情况下，必须克服重重机械和魔法难题才能让这些遗物继续运作。"},sec={{t="风之灵的赠礼",b="很久以前，风之灵曾赐予岛上居民各种魔法仪器、装置和充满活力的构装体。塑风者的职责是维护这些装置，代代相传地守护着这些元素之礼。然而，在灵体离去后，它们古老的庇护也就此中断，导致大多数奇妙的创造物陷入荒废，直至今日仅剩下寥寥数个尚能运作。"},{t="瓦拉纳尔的危机",b="在瓦拉纳尔城内，最后一个尚能运作的构装体近期受损，这威胁到了岛上本就日益稀少的遗产。一位名叫Riaani Nightwind的工匠被派往城市西缘检查并尝试修复该机器，但这些古老装置的脆弱性意味着她迫切需要额外的援助。"}},faq={{q="谁是塑风者？",a="塑风者是当地的看护人，历来受托维护风之灵所赠的魔法仪器、装置和构装体。随着那些灵体的离去，他们的角色转变为小心翼翼地保存这些依然能够运转的极少数遗物。",al={"谁是塑风者","塑风者背景传说","塑风者做什么"}},{q="这些魔法构装体来自哪里？",a="这些构装体是风之灵赠予岛上居民的，同时还有各种其他魔法仪器和装置。随着风之灵的离去，这些创造物中很少有能够保持运作的。",al={"谁制造了构装体","构装体起源","构装体来自哪里"}},{q="Riaani Nightwind是谁？",a="Riaani Nightwind是一位工匠，她被派往瓦拉纳尔西侧，对该城仅存的少数几个尚能工作的构装体之一进行检查和维修，此前它遭受了损坏。",al={"riaani nightwind是谁","riaani位置","瓦拉纳尔的工匠"}},{q="为什么岛上的大多数构装体都坏了？",a="这些构装体依赖于风之灵赋予的馈赠和附魔。一旦这些灵体离开岛屿，维持它们运作所需的能量和照料便随之减少，导致今天仅剩下极少数能正常工作。",al={"为什么构装体坏了","为什么构装体失效","风之灵离去"}},{q="瓦拉纳尔与这些构装体有什么联系？",a="瓦拉纳尔是一个居住点，这里保留着最后一些由风之灵赠予的构装体。这些尚存的机器中，有一台最近在城市西端受损，亟待修复。",al={"什么是瓦拉纳尔","瓦拉纳尔城","构装体在哪里"}},{q="为了“The Broken Construct”，需要做些什么？",a="你需要前往瓦拉纳尔西侧，找到工匠Riaani Nightwind，并提供任何所需的协助以帮助修复那个受损的构装体。",al={"the broken construct任务目标","the broken construct怎么做","the broken construct去哪里"}}},fp="20,230,25.291.0,20.290.0,24.236.0,43.173.0,24.151.0,47.167.0,48.204.0,47.127.0"}
P.entries["quest:93736"] = {n="Unwelcome Spirits",s="Unwelcome Spirits是一项为塑风者承担的任务，旨在调查影风森林中出现的一种名为‘空洞’的不安风灵。这些奇怪的实体只有在真正的风之灵离开后才显现出来，促使塑风者收集它们的精粹，以了解是什么驱逐了原本的风之灵。",h="Unwelcome Spirits是一项为塑风者承担的任务，旨在调查影风森林中出现的一种名为‘空洞’的不安风灵。这些奇怪的实体只有在真正的风之灵离开后才显现出来，促使塑风者收集它们的精粹，以了解是什么驱逐了原本的风之灵。",kw={"空洞","影风森林","精灵","不受欢迎的幽灵","风之空洞精粹","风之空洞","风之灵","塑风者"},ang={["class:Shaman"]="对于那些与元素力量沟通的人来说，自然风之灵的离去和空洞的到来预示着局部空气平衡的深度紊乱。"},sec={{t="消失的灵体",b="塑风者被一个关键的谜团所困扰：风之灵的突然离去。随着沟通中断，该组织将所有精力集中于探索为何自然风之灵抛弃了他们，并确定什么仪式或行动能引诱它们回归。在它们缺席的情况下，当地的元素氛围留下了一片真空。"},{t="影风之影",b="在风之灵离去后，影风森林北部出现了一种令人不安的新存在。观察者们开始看到一种被称为‘空洞’的奇怪风灵。在风之灵大迁徙之前，塑风者对此一无所知，这些生物似乎与真正的风之灵的突然缺席密切相关。驱散它们并取回它们残留的精粹，是揭开其本质的最佳机会。"}},faq={{q="谁是塑风者？",a="塑风者是一个致力于了解风之灵为何抛弃他们，并探索如何让这些灵体回归的组织。他们的调查集中在灵体消失后立即出现的奇异现象上。",al={"谁是塑风者","塑风者阵营","塑风者的目的"}},{q="什么是空洞？",a="空洞是一种奇特的风灵，只在真正的风之灵离开后才出现在影风森林中。目前关于它们的起源或真实性质所知甚少，促使学者们收集它们的精粹以供进一步研究。",al={"什么是空洞","风之空洞背景","空洞精灵"}},{q="影风森林在哪里？",a="影风森林位于北部。该地区是奇怪的风之空洞大量出现的地方，它们在该地区的元素灵体撤离后占据了那里。",al={"影风森林在哪","影风森林位置"}},{q="风之灵为何离开？",a="风之灵消失的确切原因尚不清楚。查明它们离开的原因并找到恢复与它们沟通的方法，是塑风者研究的核心目的。",al={"风之灵为何离开","灵体去了哪里"}},{q="为什么要收集风之空洞精粹？",a="风之空洞精粹是从被驱散的空洞身上收集的，以便塑风者检查它们的残余物。通过研究留下的物理精粹，他们希望辨别是什么在灵体离去后导致了这些生物的诞生。",al={"为何收集空洞精粹","风之空洞精粹用途"}},{q="空洞被认为是敌对的吗？",a="虽然对它们的了解还很有限，但空洞被视为在自然灵体缺席时出现的不受欢迎的入侵者。它们在影风森林中的泛滥需要被驱散，以保护该地区并获取样本。",al={"空洞危险吗","空洞精灵威胁"}}},fp="17,189,20.204.0,21.273.0,24.207.0,21.195.0,27.122.0,31.122.0,44.168.0,35.202.0"}
P.entries["quest:93737"] = {n="The Broken Construct",s="“破损的构造体”任务涉及协助瑞亚妮·夜风，此时她正埋头钻进一台无法运作的机器内部。作为阿耶莎派来的助手，旅者必须聆听瑞亚妮的计划，以了解如何帮助修复这台装置。",h="“破损的构造体”任务涉及协助瑞亚妮·夜风，此时她正埋头钻进一台无法运作的机器内部。作为阿耶莎派来的助手，旅者必须聆听瑞亚妮的计划，以了解如何帮助修复这台装置。",kw={"阿耶莎","破损的构造体","构造体","工程学","瑞亚妮·夜风","损坏的构造体"},ang={["profession:Engineering"]="地精和工程师们会明白处理一个破损构造体，且其内部机械运作需要繁琐故障排除时的那种挫败感。"},sec={{t="协助技工",b="当冒险者受阿耶莎之托前去帮助瑞亚妮·夜风时，“破损的构造体”任务便开始了。瑞亚妮正全神贯注地试图诊断一台受损的构造体，他的注意力完全集中在机器的内部零件上。尽管他对收到外援感到惊讶，并怀疑未经训练的旅者能否胜任精密的机械工作，但他还是同意在从机器中出来后列出几项必要的任务。"},{t="排除机械故障",b="构造体的组装需要精准和细致的校准，任何故障对工程师来说都是严重的挫折。瑞亚妮·夜风此时正埋首于机械零件之中，急需一双额外的手来收集材料或进行现场测试。仔细聆听瑞亚妮的说明，是让这台休眠机器重新运转的第一步。"}},faq={{q="谁是瑞亚妮·夜风？",a="瑞亚妮·夜风是一位正在努力修复一台废弃机械构造体的技工。虽然起初对派来的新人持怀疑态度，但他确实需要帮助才能使这台机器重新运作。",al={"瑞亚妮·夜风是谁","瑞亚妮","构造体技工"}},{q="谁是阿耶莎？",a="阿耶莎是一位指引冒险者去协助瑞亚妮·夜风处理其机械难题的同僚。正是她的推荐才说服了瑞亚妮考虑让新人参与工作。",al={"谁派我去找瑞亚妮","阿耶莎","阿耶莎是谁"}},{q="什么是破损的构造体？",a="该构造体是一个目前正遭受机械故障的机械造物。瑞亚妮·夜风被发现深陷其内部，试图确定修复它需要哪些零件和任务。",al={"构造体是什么","瑞亚妮在修理什么机器","损坏的机器"}},{q="瑞亚妮需要什么帮助？",a="在阿耶莎的指引下抵达后，你必须先给瑞亚妮一点时间从构造体的内部运作中抽身出来，听他解释情况，以便你获得关于如何提供最佳协助的指示。",al={"瑞亚妮要我做什么","破损的构造体任务","如何帮助瑞亚妮"}},{q="为什么瑞亚妮对你的帮助持怀疑态度？",a="瑞亚妮完全沉浸在技术工作中，被打断时显得有些不耐烦。他视大多数冒险者为未经训练的新手，直到他们证明自己有能力遵循机械指令为止。",al={"为什么瑞亚妮叫我新手","瑞亚妮没礼貌吗","瑞亚妮对话"}}},fp="20,141,21.300.0,25.356.0,24.163.0,14.164.0,29.165.0,32.128.0,37.171.0"}
P.entries["quest:93738"] = {n="The Broken Construct",s="一名塑风者请你将关于破损构造体的调查所得报告给 Ayessa Dawnsinger。高阶会对风之灵魔法的研究引起了担忧。",h="一名塑风者请你将关于破损构造体的调查所得报告给 Ayessa Dawnsinger。高阶会对风之灵魔法的研究引起了担忧。",kw={"艾耶莎·晨歌","贝拉桑","破损构造体","高阶会","瓦拉纳尔","瓦蕾妮娅·风暴之拳","风之灵","塑风者"},sec={{t="返回 Ayessa 身边",b="塑风者希望你将调查所得带给瓦拉纳尔的 Ayessa Dawnsinger。高阶会不断试验风之灵魔法，并触及塑风者职权范围内的知识，令塑风者的耐心备受考验。Ayessa 可以决定接下来该怎么做。"},{t="令人不安的名字",b="Ayessa 认为构造体损坏是高阶会所为。她认识 Belathaan，他是 Valennia Stormfist 的表亲；她还说，他的母亲曾是塑风者。Belathaan 牵涉其中让她很失望，她需要时间仔细想想。"}},faq={{q="我该向谁报告？",a="将调查所得报告给瓦拉纳尔的 艾耶莎·晨歌。",al={"向 艾耶莎 报告","报告给谁","艾耶莎·晨歌"}},{q="塑风者为何担心高阶会？",a="尽管明令禁止，高阶会仍在试验风之灵魔法，并插手塑风者职权范围内的知识。",al={"高阶会的麻烦","塑风者为何生气","高阶会的风之魔法"}},{q="构造体发生了什么事？",a="艾耶莎 认为构造体损坏是高阶会所为。",al={"破损构造体","构造体损坏","构造体为何损坏"}},{q="贝拉萨恩 是谁？",a="贝拉萨恩 是 瓦莱妮娅·风暴之拳 的表亲，他的母亲曾是塑风者。",al={"贝拉萨恩","贝拉萨恩 的家人","贝拉萨恩 的表亲"}}},fp="20,158,16.251.0,16.239.1,23.57.0,55.140.0,31.79.0,17.76.0"}
P.entries["quest:93739"] = {n="Exploring the Horde",s="Exploring the Horde 是一项入门任务，旨在让冒险者们开启一场对部落领导层的广泛访问之旅。玩家需要向索尔的堡垒的纳兹格雷尔报到以开启任务，旅途中，玩家需要觐见沃金、凯恩·血蹄和希尔瓦娜斯·风行者女士。这项任务确立了将兽人、巨魔、牛头人和被遗忘者团结在一起的外交和军事纽带。",h="Exploring the Horde...",kw={"凯恩·血蹄","暗矛","探索部落","被遗忘者","索尔的堡垒","纳兹格雷尔","奥格瑞玛","希尔瓦娜斯·风行者","牛头人","雷霆崖","幽暗城","沃金"},ang={["faction:Horde"]="这趟旅程向冒险者介绍了引领新组建的部落横跨卡利姆多和东部王国的多元化领导层。",["race:Orc"]="纳兹格雷尔是奥格瑞玛大酋长萨尔的直属顾问，也是年轻兽人战士建功立业时的重要军事联络人。",["race:Tauren"]="在雷霆崖觐见大酋长凯恩·血蹄，能让旅行者与牛头人的精神核心及力量之源建立联系。",["race:Troll"]="与暗影猎手沃金交谈加强了暗矛部族与其兽人盟友在精神谷中的纽带。",["race:Undead"]="前往幽暗城拜见黑暗女王希尔瓦娜斯·风行者，突显了被遗忘者与卡利姆多部落之间虽紧张但具有战略意义的联盟。"},sec={{t="来自索尔的堡垒的命令",b="Exploring the Horde 始于索尔的堡垒，这座要塞位于奥格瑞玛的中心地带，纳兹格雷尔和大酋长的顾问团在此监督军事行动。冒险者们会收到前往纳兹格雷尔处的指令，从而接到将他们送往联盟控制的更广阔地区的任务。这项任务不仅仅让玩家局限在杜隆塔尔的红色峡谷中，而是要求玩家走得更远，去了解在红色旗帜下团结起来的各个种族的真正广度。"},{t="生存的联盟",b="这项任务会指引旅行者去与治理联盟种族的主要代表交谈：暗矛巨魔的暗影猎手沃金、牛头人的大酋长凯恩·血蹄，以及被遗忘者的女王希尔瓦娜斯·风行者女士。通过与这些人物面对面交谈，冒险者可以亲身了解将卡利姆多与越过无尽之海、受瘟疫侵袭的洛丹伦土地联系在一起的纽带。"}},faq={{q="什么是 探索部落 任务？",a="探索部落 是一项入门旅程，要求冒险者向索尔的堡垒的纳兹格雷尔报到。此后，指示会引导旅行者穿越部落领地，去寻访并直接与主要种族领导人交谈：沃金、凯恩·血蹄和希尔瓦娜斯·风行者女士。",al={"什么是 探索部落","探索部落 任务","在这个任务中做什么"}},{q="纳兹格雷尔是谁，他在哪里？",a="纳兹格雷尔是一位杰出的兽人战士和备受信任的副官，驻扎在奥格瑞玛的索尔的堡垒内。他在部落的权力中心担任顾问，负责协调任务并指引渴望成为勇士的冒险者前往关键指挥官和地区盟友处。",al={"纳兹格雷尔 是谁","纳兹格雷尔 在哪里","纳兹格雷尔 的职责"}},{q="你需要去见哪些领导人？",a="该任务指引你去会见部落最重要的领导人：暗矛巨魔的暗影猎手沃金、莫高雷牛头人的大酋长凯恩·血蹄，以及统治幽暗城被遗忘者的女妖之王希尔瓦娜斯·风行者女士。",al={"我需要与哪些领导人交谈","需要拜访的领导人","与谁交谈"}},{q="为什么冒险者被指示去拜访每一位领导人？",a="现代部落是一个由不同的民族组成的联盟，他们因共同的生存需求和兄弟盟约而走到一起。拜访沃金、凯恩和 希尔瓦娜斯 可以展示联盟的影响力，并让冒险者熟悉杜隆塔尔、莫高雷和洛丹伦各地不同的权力中心。",al={"为什么要拜访所有领导人","拜访部落领导人的目的","外交原因"}},{q="每一位领导人在哪里可以找到？",a="沃金可以在奥格瑞玛的精神谷里的暗矛巨魔中找到。凯恩·血蹄在莫高雷雷霆崖高耸的平顶山上行使权力。希尔瓦娜斯·风行者女士居住在洛丹伦废墟下方的幽暗城皇家区深处。",al={"领导人位于何处","领导人位置","如何找到 沃金 凯恩 希尔瓦娜斯"}},{q="什么是索尔的堡垒？",a="索尔的堡垒是奥格瑞玛力量谷的中心要塞。它以传奇人物格罗姆·地狱咆哮命名，作为指挥中心，大酋长萨尔和包括纳兹格雷尔在内的主要顾问们在此统筹部落的事务。",al={"什么是 索尔的堡垒","索尔的堡垒 在哪里","奥格瑞玛堡垒"}}},fp="19,164,25.281.0,23.338.0,38.134.0,39.179.0,35.195.0,52.182.0,39.242.0,22.187.0"}
P.entries["quest:93740"] = {n="Blood for Blood",s="在高地发现了数名塑风者新手的尸体，人们立刻怀疑是奥拉凯斯的狂热分子所为。艾耶莎秉持毫不妥协的复仇信条，派冒险者北上阵风浆果低地，击杀那些教徒，并带回他们的风石祈祷符。",h="在高地发现了数名塑风者新手的尸体，人们立刻怀疑是奥拉凯斯的狂热分子所为。艾耶莎秉持毫不妥协的复仇信条，派冒险者北上阵风浆果低地，击杀那些教徒，并带回他们的风石祈祷符。",kw={"奥拉凯斯","艾耶莎","以血还血","教徒","阵风浆果低地","高地","塑风者","风石祈祷符"},sec={{t="骇人的发现",b="这天清晨，塑风者得知了一个骇人的消息：他们有数名新手在高地被杀。尽管确凿证据寥寥无几，人们还是立刻怀疑起奥拉凯斯的教徒，他们持续不断的狂热行径使其成为头号嫌疑人。塑风者奉行以眼还眼的准则，绝不容忍这场流血事件不了了之。"},{t="复仇之责",b="艾耶莎要求对北方阵风浆果低地遇到的任何奥拉凯斯成员直接复仇。为了确保惩罚得以执行，她要求带回从倒下的教徒身上取下的风石祈祷符，以证明他们已被杀死。这次袭击旨在初步回应塑风者眼中长期存在的狂热行径。"}},faq={{q="奥拉凯斯是什么人？",a="在塑风者看来，奥拉凯斯是嗜血的狂热教徒。人们怀疑他们杀害了在高地被发现的塑风者新手。",al={"奥拉凯斯是什么人","奥拉凯斯教徒","我们在和谁战斗"}},{q="塑风者为何寻求复仇？",a="数名塑风者新手在高地被发现死亡，塑风者强烈怀疑这场袭击是奥拉凯斯教徒所为。遵循他们的信条，塑风者要求以复仇回应。",al={"为何击杀奥拉凯斯","塑风者新手遇害","为何复仇"}},{q="艾耶莎是谁？",a="艾耶莎是塑风者的一名代表，她负责指挥针对奥拉凯斯的复仇行动，并收集从倒下的教徒身上找到的祈祷符。",al={"艾耶莎是谁","任务给予者","塑风者艾耶莎"}},{q="风石祈祷符是什么？",a="这些风石祈祷符是奥拉凯斯教徒随身携带的个人物品。艾耶莎要求带回它们，作为杀死那些应为流血事件负责的教徒的确凿证据。",al={"风石祈祷符是什么","祈祷符","行动凭证"}},{q="在哪里可以找到奥拉凯斯？",a="奥拉凯斯教徒在北方的阵风浆果低地活动，并在那里进行他们的仪式。",al={"奥拉凯斯在哪里","教徒在哪里","阵风浆果低地位置"}}},fp="15,228,16.279.0,22.280.0,21.138.0,44.145.0,14.144.0,37.142.0,32.94.0"}
P.entries["quest:93746"] = {n="A Firm Response",s="“A Firm Response”是泽风岛上的一个部落任务，由Ayessa Dawnsinger发布。神秘的“高阶会”侵入了当地“塑风者”的领地和事务，双方局势一触即发。Ayessa下令对前往“阿基尔神殿”路上的Belathaan Brightwish进行先发制人的打击，以武力划清界限。",h="“A Firm Response”是泽风岛上的一个部落任务，由Ayessa...",kw={"坚决的回应","艾耶莎·晨歌","贝拉桑·明愿","高阶会","活体风暴","阿基尔神殿","塑风者","泽风岛"},ang={["class:Shaman"]="道路上与Living Storms的冲突凸显了泽风岛上随处可见的、狂暴且未受驯服的元素风暴魔法。",["faction:Horde"]="部落在泽风岛的驻扎依赖于建立稳固的阵地，并防止像“高阶会”这样的敌对派系侵犯盟友的利益。"},sec={{t="划清界限",b="泽风岛的“塑风者”无法容忍不速之客的窥探，尤其是像“高阶会”这样行事诡秘、工于心计的组织。之前的警告被置若罔闻，迫使Ayessa Dawnsinger升级了事态。为了捍卫他们的利益，她选择在通往“阿基尔神殿”的北部偏僻道路上拦截Belathaan Brightwish，以确保冲突不会被镇上的好事者窥见。"},{t="路上的风暴",b="Belathaan向北前往古老的“阿基尔神殿”的行程令人怀疑，尽管其真实动机尚不明确。在偏僻的道路上被拦截后，双方很快发生敌对冲突，并引来了Living Storms。击败这些躁动的元素并挫败Belathaan，向“高阶会”传递了一个明确的信号：干涉“塑风者”的行为必将遭到武力回应。"}},faq={{q="艾耶莎·晨歌是谁？",a="艾耶莎·晨歌是泽风岛上的一位与部落和“塑风者”结盟的任务发布者。她守护着他们的领地，在处理干涉其事务的入侵者时毫不留情。",al={"艾耶莎·黎明歌者","谁发布了坚决的回应","艾耶莎"}},{q="贝拉萨恩·明愿是谁？",a="贝拉萨恩·明愿是“高阶会”的一名特工。他被发现独自前往“阿基尔神殿”，并因此成为了艾耶莎·晨歌试图威慑其组织的目标。",al={"贝拉萨恩·明愿","贝拉萨恩","贝拉萨恩是谁"}},{q="“高阶会”是什么组织？",a="“高阶会”是一个在泽风岛活动的派系，其行径与当地的“塑风者”背道而驰。尽管受到了明确的警告，他们仍不断探查不属于他们的事务。",al={"高阶会","高阶会背景故事","什么是高阶会"}},{q="“阿基尔神殿”在哪里？",a="“阿基尔神殿”位于泽风岛城镇的北面。贝拉萨恩在通往该地标的偏僻道路上遭到拦截。",al={"阿基尔神殿","阿基尔神殿的位置","泽风岛阿基尔神殿"}},{q="为什么艾耶莎想让贝拉萨恩受挫而不是直接杀掉他？",a="艾耶莎明确表示旨在传达信息，而非引发全面战争。通过重创贝拉萨恩并允许他回到其上级身边，她希望借此灌输恐惧，并让他们敬畏“塑风者”划下的界限。",al={"杀死贝拉萨恩","为什么要放过贝拉萨恩","为什么只是教训一下"}},{q="任务中遇到的活体风暴是什么？",a="活体风暴是在与贝拉萨恩的道路冲突中出现的元素实体，它们反映了泽风岛上极不稳定的元素能量。",al={"活体风暴","什么是活体风暴"}}},fx={["3180a0eb"]={q="为什么 艾耶莎·晨歌 想要对付 贝拉萨恩？",a="高阶会屡次插手塑风者的事务，无视此前尊重其领地和习俗的警告。艾耶莎 认为，光靠外交辞令已经不够了。她希望在路上截住 贝拉萨恩，狠狠教训他一顿，以此向他的上级传达一个明确的信息：必要时，塑风者会用武力维护自己的边界。",al={"为什么要对付 贝拉萨恩","艾耶莎 的动机","为什么要给高阶会送信"}}},fp="15,209,16.292.0,18.327.1,25.168.0,28.169.0,23.169.0,36.118.0,57.176.0,56.160.0"}
P.entries["quest:93786"] = {n="A Message in Blood",s="Krom’rosh派你前往Meadowsbrook的人类农场。他要杀掉农场工人，回应那些叛逃者对这片土地的宣称。",h="Krom’rosh派你前往Meadowsbrook的人类农场。他要杀掉农场工人，回应那些叛逃者对这片土地的宣称。",kw={"血染的讯息","farholde","农场","人类叛逃者","krom'rosh","meadowsbrook farm","meadowsbrook farmhands","小规模冲突"},ang={["faction:Horde"]="身为部落的一员，你奉命对付占据农场的人类叛逃者。"},sec={{t="农场工人",b="Krom’rosh指示你前往Meadowsbrook Farm，那里位于河对岸的西南方。人类叛逃者几年前占据了农场，随后又向东岸的要塞Farholde扩张。Krom’rosh说，早先的几次小规模冲突中，他们人手不足，未能取胜。如今，他要你袭扰农场，不留俘虏。"}},faq={{q="是谁让我去Meadowsbrook？",a="Krom’rosh让你袭击Meadowsbrook Farm，扰乱那里的农事。",al={"谁派我去","krom'rosh的任务","是谁下令"}},{q="Krom’rosh为什么要袭击农场？",a="人类叛逃者占据了农场，并向Farholde扩张。Krom’rosh想让他们记住，他的人就在这里。",al={"为什么袭击农场","为什么去meadowsbrook","为什么与人类交战"}},{q="Meadowsbrook Farm在哪里？",a="Meadowsbrook Farm位于河对岸的西南方。",al={"农场在哪里","meadowsbrook的位置","西南方的农场"}},{q="农场工人是谁？",a="Meadowsbrook Farmhands是Krom’rosh派你去杀掉的人。",al={"农场工人是谁","meadowsbrook的人","农场里的人类"}},{q="早先的几次小规模冲突中发生了什么？",a="Krom’rosh说，如果早先的几次小规模冲突中他们有更多战士，胜利本该属于他们。",al={"早先的战斗","小规模冲突为何失利","kromrosh的小规模冲突"}}},fp="18,136,13.314.0,34.73.0,44.119.0,27.50.0,22.72.0,40.98.0"}
P.entries["quest:93788"] = {n="Borrowed Blades",s="克雷扎·黑棘让你从特纳的伐木场取回伐木工的斧头。斧刃将被用作材料，为洛格玛打造武器。",h="克雷扎·黑棘让你从特纳的伐木场取回伐木工的斧头。斧刃将被用作材料，为洛格玛打造武器。",kw={"借来的刀刃","熔炉","gur'dok","克雷扎·黑棘","伐木工","洛格玛","特纳的伐木场","武器","木匠之斧"},sec={{t="在特纳的伐木场",b="克雷扎·黑棘维持着洛格玛的熔炉运转，Gur'dok则负责拆解斧刃。南面的人类势力和西面的暮光让资源争夺变得艰难。你需要从特纳的伐木场带回伐木工的斧头，好将斧头材料锻造成武器。"}},faq={{q="谁要这些斧头？",a="洛格玛的克雷扎·黑棘让你从特纳的伐木场取回斧头。",al={"谁派我来的","克雷扎的斧头","谁需要斧刃"}},{q="克雷扎为什么要伐木工的斧头？",a="Gur'dok会拆解斧刃，克雷扎则会用这些材料制造武器。",al={"为什么要斧头","斧头有什么用","武器材料"}},{q="特纳的伐木场在哪里？",a="沿河向南走，在磨坊附近就是特纳的伐木场。",al={"伐木场位置","伐木工在哪里","特纳的营地"}},{q="为什么资源难以收集？",a="南面的人类势力和西面的暮光让资源争夺变得艰难。",al={"资源为何难以获取","人类势力","附近的暮光"}}},fp="15,143,19.304.0,19.84.0,42.87.0,31.60.0,41.96.0"}
P.entries["quest:93791"] = {n="Speak with Belann",s="“Speak with Belann”指引渴望成为施法者的人前往瓦拉纳尔，去见大师级工匠贝兰·风林。随着学员对魔法掌握程度的加深，根据高阶会的悠久传统，打造一件个人的法术聚焦物是至关重要的通过仪式。",h="“Speak with Belann”指引渴望成为施法者的人前往瓦拉纳尔，去见大师级工匠贝兰·风林。随着学员对魔法掌握程度的加深，根据高阶会的悠久传统，打造一件个人的法术聚焦物是至关重要的通过仪式。",kw={"贝兰","贝兰·风林","高阶会","法术聚焦物","法杖","瓦拉纳尔","魔杖"},ang={["class:Mage"]="制作个人的法术聚焦物是遵循高阶会古老传统的施法者们的关键通过仪式。"},sec={{t="成长力量的仪式",b="当一名有志向的施法者对魔法的掌控日益纯熟时，高阶会会援引古老的习俗来测试并提升他们的天赋。打造一件个性化的法术聚焦物——无论是魔杖还是法杖——被认为是该组织最持久的传统之一，旨在让学生将他们萌芽的力量与他们亲手制造的器具结合起来。"},{t="瓦拉纳尔的工匠",b="为了进行这种神圣的锻造，学员们会被指引前往瓦拉纳尔，去寻找贝兰·风林。贝兰以投身于为高阶会锻造卓越法杖和魔杖逾一个世纪而闻名，他是一位值得信赖的导师，热切地欢迎专注的学生，并引导他们了解魔法工具错综复杂的制作工艺和历史。"}},faq={{q="贝兰·风林是谁？",a="贝兰·风林是一位居住在瓦拉纳尔的大师级工匠。他致力于为高阶会成员制作法杖和魔杖，并为此贡献了超过一个世纪的技艺。",al={"谁是贝兰","贝兰·风林","贝兰"}},{q="什么是高阶会？",a="高阶会是一个古老的施法者组织，其悠久的传统包括指导年轻的施法者构建和掌握他们自己的法术聚焦物。",al={"什么是高阶会","高阶会背景知识"}},{q="什么是法术聚焦物？",a="法术聚焦物，例如魔杖或法杖，可以引导魔法能量。制作个人的聚焦物被认为是高阶会中针对施法者进阶最古老的通过仪式之一。",al={"什么是法术聚焦物","法术聚焦物的用途"}},{q="瓦拉纳尔在哪里？",a="瓦拉纳尔是贝兰·风林开设工作室并协助高阶会学生制作聚焦物的定居点。",al={"瓦拉纳尔在哪里","瓦拉纳尔位置"}},{q="为什么让你去和贝兰谈谈？",a="作为一名力量正在萌芽、渴望成为施法者的人，你被派往贝兰那里，通过他一个世纪的专业经验来学习，并开始塑造属于你自己的魔法器具的过程。",al={"为什么要拜访贝兰","为什么要制作聚焦物"}},{q="见到贝兰之后会发生什么？",a="在你于瓦拉纳尔向贝兰进行自我介绍后，这位工匠会欢迎你，并准备向你解释组装法术聚焦物所需的后续阶段。",al={"接下来会发生什么","与贝兰交谈后"}}},fp="17,153,23.326.0,25.270.0,23.145.0,23.158.0,22.162.0,28.112.0,38.157.0,35.138.0"}
P.entries["quest:93797"] = {n="Boughs in the Wind",s="“风之树枝”是一项传统的成人礼，学徒需要在Falaath Village附近收集一根注入风之力的树枝来制作法术焦点。在瓦拉纳尔的Belann Windwood的指导下，这一仪式传承着古老的习俗，而此时Zephras的魔法天赋正日益稀缺。",h="“风之树枝”是一项传统的成人礼，学徒需要在Falaath Village附近收集一根注入风之力的树枝来制作法术焦点。在瓦拉纳尔的Belann...",kw={"贝兰·风林","风中的枝桠","法拉斯村","法术焦点","瓦拉纳尔","风之祭坛","注入风之力的树枝","泽弗拉斯"},ang={["class:Mage"]="用注入风之力的树枝制作法术焦点，标志着学习引导元素共鸣的施法者所经历的早期成人礼。",["race:Skyborne"]="随着逐年展现出魔法亲和力的年轻人越来越少，参与制作传统的法术焦点有助于在Zephras延续你们人民的祖传文化。"},sec={{t="成人礼",b="在Zephras这片土地上，展现出魔法天赋的年轻施法者要经历一项传统的成人礼：制作属于他们自己的法术焦点。诸如瓦拉纳尔的Belann Windwood这样的导师会引导学徒完成这一古老的实践，要求他们从该地区最古老的树木上采集掉落的树枝。这些古老的树枝中保留着风元素的残余痕迹，使它们成为引导法术的理想媒介。"},{t="风之祭坛的低语",b="最强大的树枝是在Falaath Village以南的风之祭坛附近收集的，那里自然汇聚着元素流。传统认为，往往是树枝选择了施法者，有时人们说树枝会向那些拥有足够感应力来驾驭其力量的人低声吟唱。对于像Belann这样的长者来说，每一位完成仪式的学生都代表着他们文化的重要延续，特别是在Zephras，逐年拥有魔法天赋的人愈发稀少。"}},faq={{q="任务“风之树枝”是什么？",a="“风之树枝”是一项成人礼任务，有抱负的施法者需要收集一根注入风之力的掉落树枝来制作他们的法术焦点。这是为了保护泽风的魔法遗产而实行的古老习俗。",al={"什么是风之树枝","风之树枝任务","法术焦点任务"}},{q="贝兰·风林是谁？",a="贝兰·风林是一位位于瓦拉纳尔的导师，他指导年轻的施法者完成法术焦点的传统制作。他忧心忡忡地观察到，逐年拥有魔法天赋的人愈发稀少。",al={"贝兰·风林是谁","贝兰任务发布者","贝兰瓦拉纳尔"}},{q="在哪里可以找到注入风之力的树枝？",a="注入风之力的树枝是从位于法拉斯村以南的风之祭坛附近最古老的树木上掉落的。贝兰指引学徒前往这座祭坛，因为那里古老的木材保留了元素流的痕迹。",al={"哪里寻找风之树枝","注入风之力的树枝在哪里","树枝位置"}},{q="为什么年轻的施法者要制作法术焦点？",a="根据当地传统，学徒在展现出魔法能力后会制作自己的法术焦点。焦点可以引导元素能量，既是施法的媒介，也是文化仪式的一种入门方式。",al={"为什么制作法术焦点","法术焦点的用途","法术焦点背景故事"}},{q="为什么贝兰问树枝是否为你吟唱？",a="贝兰·风林指出，传统认为往往是树枝选择了施法者，而非反之。他提到，对于拥有驾驭元素之风感应力的人来说，合适的树枝似乎会向其吟唱。",al={"树枝选择施法者","吟唱的树枝","树枝是否会选择你"}},{q="泽风的魔法发生了什么？",a="泽风是这一传统发生的土地。据贝兰·风林所言，泽风逐年减少天生拥有魔法天赋的人，使得古老仪式的延续变得至关重要。",al={"泽弗拉斯在哪里","泽弗拉斯魔法消逝","泽弗拉斯魔法背景"}}},fp="18,207,17.262.0,27.396.0,37.130.0,23.174.0,41.181.0,47.153.0,46.155.0,38.147.0"}
P.entries["quest:938"] = {n="密斯特",s="“迷雾”是泰达希尔荫蔽枝叶间的一项护送任务。在丛林深处发现一只被遗弃的受伤灰色剑齿猫后，旅行者必须护送她安全回到附近月亮井旁的哨兵阿瑞尼亚·碎云处。",h="“迷雾”是泰达希尔荫蔽枝叶间的一项护送任务。在丛林深处发现一只被遗弃的受伤灰色剑齿猫后，旅行者必须护送她安全回到附近月亮井旁的哨兵阿瑞尼亚·碎云处。",kw={"阿瑞尼亚·碎云","迷雾","月亮井","神谕之树","剑齿猫","哨兵","泰达希尔"},ang={["class:Hunter"]="任何驯兽师都会认出迷雾眼中那炽热的忠诚和智慧的光芒，确保她安全回到主人身边是职业荣耀所在。",["faction:Alliance"]="援助泰达希尔的哨兵巩固了初生的联盟与世界之树的卡多雷保卫者之间至关重要的友好关系。",["race:NightElf"]="哨兵与剑齿猫之间的羁绊是暗夜精灵战争和森林传说的基石；营救迷雾就是在维护那种古老而神圣的伙伴关系。"},sec={{t="受伤的同伴",b="在泰达希尔野生的灌木丛中，隐藏着迷雾，这是一只独特的灰色剑齿猫，她的背部和腹部有着严重的割伤。迷雾并没有表现出野生野兽的狂暴，她异常冷静，蓝色的眼睛里闪烁着智慧的光芒，立刻向友善的旅行者寻求指引和保护。"},{t="伏击的代价",b="迷雾是哨兵阿瑞尼亚·碎云深爱的同伴。在神谕之树附近巡逻巨大的枝干时，阿瑞尼亚被邪恶的女巫伏击，毫无防备的两人被冲散了。阿瑞尼亚以为她忠诚的宠物已经惨遭不测，悲痛欲绝地退到了当地的一口月亮井旁，在那里绝望地祈祷迷雾能活下来。"}},faq={{q="谁是迷雾？",a="迷雾是属于哨兵阿瑞尼亚·碎云的一只忠诚的灰色剑齿猫同伴。她在泰达希尔的森林中被发现时已经受伤，此前在一次猛烈的伏击中与主人走散了。",al={"迷雾 猫","什么是迷雾","谁是那只剑齿猫"}},{q="是谁伤了迷雾？",a="迷雾和她的主人在泰达希尔的树林中遭到了潜伏在此的女巫的伏击。袭击者设法将她们冲散，并在剑齿猫的背部和腹部留下了深深的割伤。",al={"谁伤害了迷雾","为什么迷雾在流血","女巫伏击迷雾"}},{q="应该把迷雾护送到哪里？",a="迷雾需要被安全带到哨兵阿瑞尼亚·碎云那里，她驻扎在神谕之树附近的月亮井旁。",al={"我要把迷雾带到哪里","迷雾任务提交","迷雾的目的地"}},{q="哨兵阿瑞尼亚·碎云是谁？",a="阿瑞尼亚·碎云是一名暗夜精灵哨兵，也是迷雾的同伴。她驻扎在神谕之树附近的月亮井处。",al={"阿瑞尼亚·碎云","碎云","迷雾的主人"}},{q="为什么暗夜精灵哨兵会与剑齿猫结成羁绊？",a="数千年来，暗夜精灵哨兵一直与卡利姆多的巨型猫科动物并肩作战，依靠它们作为战斗中的凶猛伙伴、阴影枝叶间的斥候，以及值得信赖的终身伴侣。",al={"暗夜精灵猫同伴","哨兵剑齿猫","为什么选择剑齿猫"}},{q="神谕之树相对于这次营救在哪里？",a="神谕之树位于泰达希尔西北部，附近有一口提供圣水的月亮井，哨兵阿瑞尼亚·碎云在那里履行职责。",al={"神谕之树位置","月亮井 迷雾"}}},fp="4,154,19.257.0,19.238.1,12.145.0,17.135.0,30.101.0,35.120.0,50.191.0,52.150.0"}
P.entries["quest:93835"] = {n="Confront Lorthuna",s="一名受伤的法师请你穿过传送门，跟上 Ayessa 和 Elaadrin，前往罗哈什尖塔。他们需要帮助对付高阶女祭司 Lorthuna。",h="一名受伤的法师请你穿过传送门，跟上 Ayessa 和 Elaadrin，前往罗哈什尖塔。他们需要帮助对付高阶女祭司 Lorthuna。",kw={"艾耶莎·晨歌","艾拉德林·暮风","高阶会","洛苏娜","传送门","罗哈什尖塔","瓦蕾妮娅","泽弗拉斯"},sec={{t="穿过传送门",b="Lorthuna 刚刚通过传送门逃到了上方的尖塔，Ayessa Dawnsinger 和 Elaadrin Evengale 已经追了过去。他们的同伴伤势过重，无法跟上。穿过传送门与他们会合，共同面对高阶女祭司。"},{t="冲突之后",b="剩下的法师已被派去帮助 Valennia 和她的部队脱身，Valennia 正在高阶长者影歌的居所休养。安斯雷姆与高阶会商讨下一步行动后，已返回艾泽拉斯。Zephras 活了下来，却正处于极度危险的境地，必须为接下来做好计划。"}},faq={{q="是谁让我去追 洛尔苏娜？",a="一名受伤的法师请你穿过传送门，跟上 艾耶莎·晨歌 和 艾拉德林·暮风，帮助他们对付高阶女祭司 洛尔苏娜。",al={"谁派我去","受伤的法师","谁需要帮助"}},{q="洛尔苏娜 去了哪里？",a="洛尔苏娜 通过传送门逃到了上方的罗哈什尖塔。",al={"洛尔苏娜 在哪里","洛尔苏娜 传送门","她逃到哪里了"}},{q="谁去追 洛尔苏娜 了？",a="艾耶莎·晨歌 和 艾拉德林·暮风 穿过传送门追赶 洛尔苏娜。",al={"艾耶莎 和 艾拉德林","谁追了她","谁在上面"}},{q="受伤的法师为什么不能和他们一起去？",a="这名法师受了太多攻击，必须留下。",al={"为什么我独自前往","法师伤得太重","为什么留下"}},{q="瓦莱妮娅 在哪里？",a="剩下的法师帮助 瓦莱妮娅 和她的部队脱身后，她正在高阶长者影歌的居所休养。",al={"瓦伦妮娅 的位置","她去了哪里","瓦伦妮娅 安全吗"}},{q="现在有什么危险？",a="泽风 正处于极度危险的境地，高阶会必须为接下来做好计划。",al={"泽弗拉斯 处境危险","泽弗拉斯 怎么了","高阶会的下一步"}}},fp="17,176,18.239.0,15.311.1,38.137.0,22.62.0,24.79.0,40.49.0,18.116.0,20.84.0"}
P.entries["quest:93836"] = {n="The Fate of Zephras",s="The Fate of Zephras是一项关键任务，发生在击败泽风岛上的邪教领袖Lorthuna之后。随着岛屿的保护性遮蔽结界失效，玩家将奥拉基尔带来的元素威胁以及Ayessa前往艾泽拉斯的提议告知了位于瓦拉纳尔的高阶长者Talaanis 影歌。",h="The Fate of...",kw={"奥拉基尔","艾耶莎","泽弗拉斯的命运","洛苏娜","穆恩","阿基尔神殿","塔拉尼斯·影歌","瓦拉纳尔","泽风岛"},ang={["class:Shaman"]="萨满们认识到风之领主奥拉基尔构成的严重威胁，一旦古老的结界失效，他的元素领地将直接包围泽风岛。",["race:Skyborne"]="该任务标志着泽风岛的天裔一族的一个转折点，他们正在权衡失去保护结界和奥拉基尔威胁所带来的后果，以及他们浮空家园之外的新使命。"},sec={{t="一场岌岌可危的胜利",b="The Fate of Zephras标志着泽风岛居民面临的关键清算。在阿基尔神殿上空的巅峰对决后，邪教领袖Lorthuna已被消灭，但这场胜利代价惨重。将岛屿从奥拉基尔的凝视中隐藏起来的古老结界已经坍塌，使得这座浮空圣所暴露在风之领主的领地中心，毫无防备。作为回应，一名信使被派往岛屿各处，将消息带到瓦拉纳尔。"},{t="To Valanaar",b="该任务需要直接与瓦拉纳尔的高阶长者Talaanis Shadowsong交谈。这位长者不仅获悉了Lorthuna的死亡和结界的破碎，还得知了Ayessa带领探险队前往艾泽拉斯的坚定决心。随着魔法面纱的消失，岛民们决定向外探索，以寻找保护家园的方法。影歌权衡着恐惧与胜利，指出虽然奥拉基尔是一个可怕的威胁，但元素之神在漫长的时间尺度上运作，这可能为他们争取到宝贵的行动时间。"}},faq={{q="泽风的命运任务是关于什么的？",a="泽风的命运是一项关键任务，发生在阿基尔神殿击败洛尔苏娜之后。随着保护泽风岛的结界破碎，玩家将迫在眉睫的元素威胁和艾耶莎前往艾泽拉斯的探险提议直接带给了瓦拉纳尔的高阶长者塔拉尼斯 影歌。",al={"泽弗拉斯的命运任务","泽弗拉斯的命运是什么","泽弗拉斯的命运发生什么"}},{q="为什么泽风岛会受到奥拉基尔的威胁？",a="泽风岛位于风之领主奥拉基尔的元素领地之内。古老的保护结界曾将这座圣所从他的视线中隐藏起来，但随着这些防御措施的失效，如果这位元素领主将他的怒火转向这里，岛屿将变得暴露且脆弱。",al={"为什么泽风岛处于危险之中","为什么攻击泽风岛","泽风岛元素威胁"}},{q="塔拉尼斯·影歌是谁？",a="塔拉尼斯·影歌是泽风岛上天裔社区的高阶长者，驻扎在瓦拉纳尔定居点。他负责监督族人的治理和生存，接收有关元素威胁的报告，并负责做出面临家园的关键决策。",al={"塔拉尼斯·影歌是谁","高阶长者影歌","塔拉尼斯·影歌在哪里"}},{q="艾耶莎的计划是什么？",a="艾耶莎是泽风岛上的一位关键人物，她制定了前往艾泽拉斯的探险计划。她意识到如果没有防御，岛屿无法抵挡奥拉基尔的攻击，因此她在他们的领地之外寻求解决方案和盟友，以确保族人的长期生存。",al={"艾耶莎是谁","艾耶莎的计划","艾耶莎在做什么"}},{q="洛尔苏娜是谁，她发生了什么事？",a="洛尔苏娜是在泽风岛活动的邪教领袖。在此任务之前，她已在阿基尔神殿上空被杀，这摧毁了她组织的领导层，同时也因为那场冲突导致了保护岛屿的魔法结界坍塌。",al={"洛尔苏娜是谁","邪教领袖洛尔苏娜","洛尔苏娜发生了什么"}},{q="穆恩是谁？",a="穆恩是一位了解元素领主的顾问或学者，他曾警告泽风岛的守卫们关于奥拉基尔的强大力量和危险，并确认了他们在失去魔法掩护后的脆弱性。",al={"穆尔恩是谁","穆尔恩背景故事"}}},fp="19,190,20.293.0,20.417.1,44.222.0,43.209.0,27.189.0,22.154.0,42.148.0,12.196.0"}
P.entries["quest:93926"] = {n="The Western Watch",s="The Western Watch是一项紧急任务，旨在召回Peacekeeper Vaaniel及其卫戍部队，他们目前身处西南方向的一座孤立前哨站，正遭到邪教徒的围攻。当地领导层意识到坚守这座防御工事所付出的生命代价得不偿失，因此决定召回守军，以保障主要定居点的安全。",h="The Western Watch是一项紧急任务，旨在召回Peacekeeper...",kw={"邪教","维和者瓦尼尔","维和者","风暴施法者","西部哨岗","岗哨","西方岗哨"},sec={{t="昂贵的前哨站",b="这座西方岗哨位于定居点西南方，是一处守卫边境的前哨站。面对敌对邪教徒的新一轮攻势，当地领导人认为这座孤立的建筑防守代价过大。为了避免在维持这一暴露阵地的过程中牺牲更多生命，他们拟定了召回Peacekeeper的命令，并将所有可用的军事力量集中起来，以保护村庄及其居民。"},{t="撤退为时已晚",b="Peacekeeper Vaaniel率领卫戍部队守卫The Western Watch，以抵御来袭的威胁。不幸的是，撤退指令送达得太晚了。当信使抵达防御工事时，邪教徒中擅长风暴魔法的施法者已经攻占了岗哨，留下了在一片焦石与闪电灼痕中阵亡的Peacekeeper Vaaniel及其部下。"}},faq={{q="谁是维和者瓦尼尔？",a="维和者瓦尼尔是负责驻守西方岗哨的维和者的长官。由于邪教徒正在攻击岗哨，你被派去找到他，并告知他尽快带领卫戍部队撤回村庄。",al={"谁是瓦尼尔","瓦尼尔背景故事","维和者瓦尼尔"}},{q="为什么维和者被下令放弃岗哨？",a="当地领导层意识到，在邪教徒不断的袭击下，坚守偏远的西方岗哨代价过大。因此做出了撤回卫戍部队的决定，以便守军能在村庄集结，并保护那里的平民。",al={"为什么要放弃岗哨","为什么要离开岗哨","西部哨塔命令"}},{q="是什么杀死了维和者瓦尼尔？",a="维和者瓦尼尔是被操纵风暴的邪教施法者杀害的。他身上留下的新鲜烧灼痕迹表明，闪电与原始的元素魔法被用来击杀岗哨的守卫者。",al={"瓦尼尔是怎么死的","谁杀了瓦尼尔","维和者死于什么"}},{q="是谁袭击了西方岗哨？",a="这次袭击是由一个使用破坏性风暴魔法的敌对邪教发起的。当地指挥官尚不清楚他们夺取岗哨的确切动机，但他们的侵略性攻势对附近的定居点构成了直接威胁。",al={"谁在攻击岗哨","邪教徒袭击西方岗哨","这是什么邪教"}},{q="西方岗哨位于何处？",a="这座岗哨位于当地定居点的西南方。它作为守卫西部通道的前哨站发挥作用，但其孤立的地理位置使其容易受到邪教徒协同袭击的影响。",al={"岗哨在哪里","西方岗哨位置"}},{q="驻扎在岗哨的卫戍部队遭遇了什么？",a="当传令兵带着撤回定居点的命令抵达时，岗哨已经陷落了。在援军抵达之前不久，维和者瓦尼尔和他的前哨站守军就被邪教的施法者击溃并杀害了。",al={"岗哨发生了什么","岗哨的结局","有维和者生还吗"}}},fp="17,183,16.329.0,19.264.1,27.189.0,60.173.0,32.152.0,36.180.0,40.148.0,43.184.0"}
P.entries["quest:93927"] = {n="A Last Request",s="A Last Request始于在野外发现一名牺牲维和者的尸体。这名守卫的手中紧紧抓着一张血迹斑斑的字条，上面记录着关于他临终时刻的关键线索。阅读他的临终遗言是完成他未竟使命并终结其命运的唯一途径。",h="A Last Request始于在野外发现一名牺牲维和者的尸体。这名守卫的手中紧紧抓着一张血迹斑斑的字条，上面记录着关于他临终时刻的关键线索。阅读他的临终遗言是完成他未竟使命并终结其命运的唯一途径。",kw={"最后的请求","血色字条","牺牲的维和者","维和者","维和者笔记"},sec={{t="严峻的发现",b="A Last Request始于野外的一项严峻发现：一名牺牲维和者毫无生气的尸体。这名守护者在死亡时身体瘫软，手中仍紧握着一张血迹斑斑的字条，在检查时会滑落出来。在Zephras动荡的岁月里，维和者们为了维持秩序往往付出了终极代价，而找回他们的临终遗言通常是揭开他们遭遇的唯一方法。"},{t="最终的讯息",b="从这名维和者手中强行取下的血色羊皮纸上，记载着他最后的恳求或指令。无论谁终结了这名守卫的生命，都让他的使命未能完成，留给发现尸体的人去解读线索并完成他最后的任务。阅读这张字条能提供前进并响应这名陨落哨兵临终呼唤所需的关键指引。"}},faq={{q="死亡的维和者是谁？",a="这名牺牲维和者的确切身份在最初发现时并未说明。显而易见的是，他作为秩序维护者的职责以暴力告终，只留下紧紧抓在手中的紧急信件。",al={"死亡的维和者是谁","死亡的维和者","维和者身份"}},{q="血迹斑斑的字条上写着什么？",a="这张血迹斑斑的字条是这名维和者的最后陈述。邪教徒突袭了他的哨所：拉尼毫无防备，阿文苏斯腹部中剑，而他自己则被一道闪电击倒并被丢弃在此等死，他预计自己的伤势会让他完成邪教徒未竟之事。",al={"血迹斑斑的字条是什么","字条上写了什么","维和者字条"}},{q="这项请求是如何发现的？",a="这项任务始于发现并检查维和者毫无生气的身体。搜寻这名倒下的保卫者会发现他死气沉沉的手中紧握着血迹斑斑的字条，上面概述了他的最后恳求。",al={"如何开始最后的请求","在哪里找到最后的请求"}},{q="维和者遭遇了什么？",a="邪教徒毫无预警地伏击了他的哨所。他的同僚维和者们倒下了，他自己则被一道闪电击中并被丢弃等死。他勉强支撑着写下了发生的一切，这张字条正是从他手中发现的。",al={"维和者为何被杀","谁杀了维和者"}},{q="维和者的最后请求是什么？",a="这名维和者在完成任务或亲自传达信息前就死去了。通过取回并检查他血迹斑斑的字条，冒险者可以破译他最后的指令并完成他的临终遗愿。",al={"维和者的请求是什么","最后的请求的目的"}},{q="维和者担任什么角色？",a="维和者是肩负着维持秩序、保卫定居点和道路免受危险的守护者。除非有人找回他们最后的报告，否则牺牲在战场上会导致他们的职责未竟，盟友也无法获得警示。",al={"维和者是谁","维和者背景传说"}}},fp="14,146,16.225.0,17.216.0,28.153.0,35.249.0,31.111.0,33.207.0,39.189.0,32.219.0"}
P.entries["quest:93948"] = {n="Deliver the Signet",s="Deliver the Signet 是一项任务，旅行者会将一枚找回的家族戒指送到瓦拉纳尔的高阶长老 Talaanis 影歌手中。这次递送带来了他侄子在泽风岛遇难的悲惨确认，同时也开启了协助当地维和人员的新契机。",h="Deliver the Signet 是一项任务，旅行者会将一枚找回的家族戒指送到瓦拉纳尔的高阶长老 Talaanis 影歌手中。这次递送带来了他侄子在泽风岛遇难的悲惨确认，同时也开启了协助当地维和人员的新契机。",kw={"递送徽记","影歌家族徽记","申多雷","塔拉尼斯 影歌","瓦拉纳尔","瓦蕾妮娅·风暴之拳","泽风岛"},ang={["race:NightElf"]="显赫的影歌家族名号在精灵血统中唤起了深厚的历史，尽管在泽风岛上，高阶长老 Talaanis 和当地的 shen'dorei 正在经历他们自己独特的挣扎。"},sec={{t="一项沉重的差事",b="当冒险者前往瓦拉纳尔定居点时，他们随身携带了从一座孤塔中找回的影歌家族徽记。怀揣着这件阴郁的信物，旅行者们开始寻找泽风岛的高阶长老 Talaanis 影歌。尽管当地普遍存在困境，但 Talaanis 深受族人爱戴，他不得不面对侄子已经遇难的痛苦确认，在收回传家宝的同时也收到了慰问。"},{t="瓦拉纳尔的悲伤与责任",b="在瓦拉纳尔收到这枚徽记戒指后，高阶长老 Talaanis 在深切的悲痛中表达了衷心的感谢。认可了找回遗物的旅行者的能力后，Talaanis 指引他们去找瓦拉纳尔维和部队的领袖、队长 Valennia Stormfist。面对紧张的局势和日益增长的压力，这个定居点欢迎有能力的保卫者提供的任何援助。"}},faq={{q="塔拉尼斯 影歌是谁？",a="塔拉尼斯 影歌担任泽风岛的高阶长老。他深受社区的尊重和爱戴，带领族人渡过动荡时期，并在得知证实其侄子死讯的徽记戒指后，承受着个人的悲剧。",al={"塔拉尼斯 是谁","高阶长老 塔拉尼斯","塔拉尼斯 影歌背景故事"}},{q="什么是影歌家族徽记？",a="这枚徽记是影歌家族徽记，是从一座塔中找回的。它作为悲惨的确认，证实了 塔拉尼斯 影歌的侄子已经遇难，并将一件传家宝归还给了这位悲痛的高阶长老。",al={"什么是徽记戒指","侄子的戒指","影歌徽记"}},{q="瓦拉纳尔位于何处？",a="瓦拉纳尔是位于泽风岛的一个定居点，高阶长老 塔拉尼斯 影歌居住于此，队长 瓦蕾妮娅·风暴之拳 在此负责当地的维和工作。",al={"瓦拉纳尔在哪里","瓦拉纳尔定居点","塔拉尼斯 的位置"}},{q="瓦蕾妮娅·风暴之拳 是谁？",a="瓦蕾妮娅·风暴之拳 是驻扎在瓦拉纳尔的维和部队队长。高阶长老 塔拉尼斯 建议找她寻求工作，并指出定居点急需有能力的人手。",al={"瓦伦妮娅·风暴之拳 是谁","瓦伦妮娅 队长","瓦拉纳尔维和队长"}},{q="塔拉尼斯 提到的 申多雷 是谁？",a="塔拉尼斯 将从高地下来的有能力的年轻旅行者称为 申多雷，强调了在泽风岛上依然存在的精灵存在和遗产。",al={"申多雷 是谁","申多雷 高地"}},{q="塔拉尼斯 影歌的侄子发生了什么事？",a="塔拉尼斯 的侄子死在了一座塔里，他的家族徽记也在那里遗失。将徽记带到瓦拉纳尔通知了高阶长老他侄子的死讯，为这一悲痛的损失带来了终结。",al={"塔拉尼斯 的侄子发生了什么","侄子是怎么死的"}}},fp="18,224,15.334.0,26.329.0,27.145.0,37.142.0,26.140.0,26.153.0,45.151.0,46.143.0"}
P.entries["quest:93949"] = {n="Bugged",s="“Bugged”是瓦拉纳尔的一项任务，讲述了一场由季节性低地昆虫涌入而引发的间谍阴谋。高阶会的法师们发现，当地的邪教徒正在将窃听符咒编织到天跳虫身上以监视该定居点，因此需要采取清除行动来消灭这些被附魔的害虫。",h="“Bugged”是瓦拉纳尔的一项任务，讲述了一场由季节性低地昆虫涌入而引发的间谍阴谋。高阶会的法师们发现，当地的邪教徒正在将窃听符咒编织到天跳虫身上以监视该定居点，因此需要采取清除行动来消灭这些被附魔的害虫。",kw={"出现故障","邪教","被附魔的天跳虫","高阶会","窃听咒语","天跳虫","瓦拉纳尔"},ang={["class:Mage"]="高阶会法师揭开了编织在普通害虫身上的魔法窃听结界，将奥术分析变成了反间谍活动。"},sec={{t="虫群中的窃听者",b="在低地的天跳虫季节，本地昆虫群会在瓦拉纳尔城周围汹涌而至。虽然通常只被视为季节性的困扰，但高阶会法师的检查显示，几只被杀死的样本身上携带了复杂的窃听附魔。当地的一个邪教组织将这些昆虫群武器化，将普通的低地害虫变成了不起眼的监视工具，用以窃听城市。"},{t="清理虫害",b="由于被附魔的天跳虫与它们的普通同类看起来并无区别，瓦拉纳尔的守护者被迫不加区分地扑杀虫群。消灭这些虫子不仅剥夺了敌对邪教获取关键情报的手段，切断了魔法监视，还加强了城市针对内部颠覆活动的防御。"}},faq={{q="什么是天跳虫？",a="天跳虫是瓦拉纳尔周边低地的一种有翅害虫，在季节性爆发期间会成群结队地出现。",al={"什么是天跳虫","天跳虫虫害"}},{q="是谁给昆虫施加了附魔？",a="据怀疑，当地的邪教徒捕捉了天跳虫，并在它们身上施加了魔法窃听咒语，以此窃听定居点。",al={"谁给虫子施加了附魔","邪教窃听虫","谁在瓦拉纳尔进行监视"}},{q="如何辨别哪些天跳虫被附魔了？",a="肉眼看来，被附魔的天跳虫与普通昆虫完全一样。只有通过扑杀虫群，才能发现并消灭这些被魔法浸染的间谍。",al={"如何辨别被附魔的天跳虫","哪些虫子被附魔了"}},{q="这件事发生在哪里？",a="这场虫灾和间谍活动发生在瓦拉纳尔周围，这是一座季节性虫群从邻近低地升起的空中城市。",al={"虫害任务地点","瓦拉纳尔的虫子"}},{q="天跳虫被施加了什么样的附魔？",a="高阶会法师检查了被杀死的昆虫，检测到了一种绑定在它们身上的特殊窃听咒语，实际上是将这些生物变成了移动的监视工具。",al={"虫子身上是什么咒语","天跳虫附魔"}},{q="为什么必须消灭所有的天跳虫？",a="因为被附魔的天跳虫在视觉上无法与普通害虫区分开来，所以清理虫群对于清除邪教的魔法窃听网络并保护瓦拉纳尔是必要的。",al={"为什么要杀天跳虫","虫害任务目标"}}},fp="6,188,26.244.0,16.206.0,20.124.0,26.96.0,47.121.0,27.115.0,54.115.0,50.165.0"}
P.entries["quest:93951"] = {n="A Little Beauty",s="“A Little Beauty”是申达尔高地的一项本地任务，旅行者们会在泽风岛附近收集柔软的角鹰兽绒毛。这些色彩斑斓的羽毛被天裔（天裔）用来装饰发辫，在艰难时期为村庄带来了一丝简单的快乐与美好。",h="“A Little Beauty”是申达尔高地的一项本地任务，旅行者们会在泽风岛附近收集柔软的角鹰兽绒毛。这些色彩斑斓的羽毛被天裔（天裔）用来装饰发辫，在艰难时期为村庄带来了一丝简单的快乐与美好。",kw={"一点美丽","绒毛","羽毛","角鹰兽","申达尔高地","天裔","泽风岛"},ang={["race:Skyborne"]="收集鲜艳的角鹰兽绒毛使泽风岛的天裔能够用柔软的羽毛装饰他们的头发，既保持了他们的文化习俗，又能在苦难中找到小小的快乐。"},sec={{t="高地的羽毛",b="在位于村庄西南方的泽风岛上，野生角鹰兽在申达尔高地筑巢。虽然这些充满领地意识的野兽对附近的旅行者来说是个令人头疼的麻烦，但它们会掉落极其鲜艳且丝般柔软的绒毛。对于当地的天裔来说，收集这些掉落的羽毛是一个绝佳的机会，可以用来制作精美的饰品编入发中。"},{t="在微小事物中发现快乐",b="虽然收集装饰性羽毛来装点头发可能看起来不过是虚荣心作祟，但泽风岛的工匠却认为这是一项至关重要的追求。即使在环境恶劣的时候，寻找并分享生活中的点滴小快乐也有助于维系社区的精神。为村民们的生活带来美感，确保了每一天都有值得庆祝的东西。"}},faq={{q="为什么要收集角鹰兽的羽毛？",a="收集野生角鹰兽的绒毛是为了制作当地天裔的装饰性发饰。尽管定居点附近的角鹰兽可能很麻烦，但它们掉落的羽毛因其异常丝滑柔软且色泽鲜艳而备受珍视。",al={"为什么要收集羽毛","羽毛有什么用","羽毛的用途"}},{q="泽风岛是什么？",a="泽风岛是天裔的岛屿家园，也是本次任务的发生地。当地的工匠用收集到的羽毛制作发饰，试图为住在那里的居民带来快乐和轻松的时刻。",al={"泽风岛是谁","这是什么城镇","这在哪里发生"}},{q="角鹰兽在哪里筑巢？",a="野生角鹰兽在村庄西南方的申达尔高地筑巢。因为野生角鹰兽领地意识极强，绝不容忍不速之客，所以在它们巢穴周围收集掉落的羽毛需要格外小心。",al={"巢穴在哪里","角鹰兽在哪里","申达尔高地位置"}},{q="为什么像发饰这样的小奢侈品在这样的时期很重要？",a="虽然用羽毛装饰头发看起来像是虚荣的琐事，但任务发布者解释说，拥抱微小的快乐和美好是至关重要的，尤其是在困难时期。能为他人带来片刻的幸福，就使得这一切努力变得值得。",al={"羽毛重要吗","为什么要装饰头发","虚荣琐事"}},{q="角鹰兽对访客有敌意吗？",a="居住在村庄西南方的角鹰兽是野生生物。它们将筑巢地视为自己的领地，不会容忍入侵者，这使得在它们附近收集掉落的绒毛对毫无防备的旅行者来说很危险。",al={"为什么角鹰兽很危险","角鹰兽是野生的吗"}},{q="用羽毛装饰头发在天裔中普遍吗？",a="是的，许多天裔喜欢将色彩斑斓的羽毛编入头发作为个人装饰。角鹰兽异常柔软的绒毛是制作这些装饰品的理想材料。",al={"天裔羽毛","天裔会佩戴羽毛吗"}}},fp="15,157,23.241.0,27.222.0,44.173.0,16.159.0,30.152.0,74.139.0,40.161.0,59.131.0"}
P.entries["quest:93958"] = {n="内殿",s="内殿的核心是深入阿基尔神殿最深处的危险侦察任务。在瓦伦妮亚·风拳与其突击小队在激战中突破密室后，该区域陷入了一片诡异的寂静，因此亟需派遣任务去探明是否还有幸存者。",h="内殿的核心是深入阿基尔神殿最深处的危险侦察任务。在瓦伦妮亚·风拳与其突击小队在激战中突破密室后，该区域陷入了一片诡异的寂静，因此亟需派遣任务去探明是否还有幸存者。",kw={"内殿","阿基尔神殿","风拳","瓦伦妮亚","瓦伦妮亚·风拳"},sec={{t="突如其来的寂静",b="在一场激烈的突袭后，瓦伦妮亚·风拳率领她的小队攻破了阿基尔神殿内的密室。最初的冲突从大厅深处传出了激烈且绝望的战斗声，但随后噪音戛然而止，取而代之的是令人不安的、突如其来的寂静，这让外面的盟友们预感到了最坏的结果。"},{t="突破的代价",b="进入寂静的密室后，展现出的是突袭带来的惨重代价。并没有一支胜利的先锋队守住阵地，反而是瓦伦妮亚·风拳在战后被发现身受重伤，而她先锋队的命运则变得岌岌可危，前途未卜。"}},faq={{q="瓦伦妮亚·风拳是谁？",a="瓦伦妮亚·风拳是一位指挥官，负责领导对阿基尔神殿深处的突袭。她率领其部队突破了密室，尽管内部激烈的冲突突然平息，陷入了不祥的寂静。",al={"瓦伦妮亚是谁","瓦伦妮亚·风拳是谁","瓦伦妮亚"}},{q="什么是阿基尔神殿？",a="阿基尔神殿内设有一间目前正遭受攻击的密室。瓦伦妮亚的部队在激战中攻破了其防御，使其成为了这场紧张且致命对峙的中心。",al={"什么是阿基尔神殿","阿基尔神殿背景故事","阿基尔神殿"}},{q="瓦伦妮亚的部队在里面发生了什么？",a="突破后，内部立刻传出了激烈的战斗回响，但战斗声突然停止了。一股令人不安的平静笼罩了密室，让外面的盟友担心瓦伦妮亚的先锋队可能已经全军覆没或被压制。",al={"为什么这里很安静","瓦伦妮亚的部队发生了什么","瓦伦妮亚的士兵"}},{q="瓦伦妮亚·风拳还活着吗？",a="瓦伦妮亚在突袭中幸存了下来，但在战斗平息后，人们发现她身受重伤，被困在阿基尔神殿的密室中。",al={"瓦伦妮亚还活着吗","瓦伦妮亚死了吗","瓦伦妮亚的命运"}},{q="密室内的目标是什么？",a="密室是阿基尔神殿内最深处的厅室。任务指引盟友独自进入该厅室，评估突破后的情况，并与瓦伦妮亚及任何幸存的战士取得联系。",al={"什么是内殿","内殿任务目的"}},{q="是谁派你进入密室的？",a="一位在外围负责后方警戒的盟友派你进去的。在守住外围防线的同时，他们派你前去与瓦伦妮亚的先锋队会合。",al={"谁派你去寻找瓦伦妮亚","内殿任务发布者"}}},fp="17,175,16.262.0,22.139.1,26.177.0,27.173.0,42.173.0,34.123.0,47.158.0,37.156.0"}
P.entries["quest:93963"] = {n="Exploring the Alliance",s="Exploring the Alliance 是一场外交旅程，指引初到暴风城的冒险者们造访联盟的主权首府。通过拜访铁炉堡和达纳苏斯的统治者，旅行者们能在前往西部荒野等周边地区投入战斗之前，对艾泽拉斯的盟国获得至关重要的了解。",h="Exploring the Alliance...",kw={"达拉然","达纳苏斯","探索联盟","大工匠 梅卡托克","铁炉堡","麦格尼·铜须","兰德尔·埃默森","暴风要塞","泰兰德·语风","西部荒野"},ang={["faction:Alliance"]="这场外交旅程向新人介绍了联盟的主要堡垒以及维系这一契约的基础领袖们。",["race:Skyborne"]="作为在艾泽拉斯的客人，并为组织进驻达拉然做准备，天裔被敦促去了解接纳他们的盟国。"},sec={{t="盟国之旅",b="对于初临艾泽拉斯的游客，联盟敞开怀抱邀请他们亲眼见证其辽阔疆域。旅行者们无需仅仅局限于暴风城内，而是被委派前往人类首府之外，去观察定义了伟大盟友种族的不同文化、传统和坚韧。在暴风城南侧前厅的 Randal Emerson 的指引下，冒险者们将开启一场横跨大陆的旅行。"},{t="觐见最高首领",b="这场外交朝圣之旅将指引冒险者们跨越陆地与海洋，觐见联盟的统治首脑：位于铁炉堡地底山脉大厅中的国王麦格尼·铜须、流亡中的侏儒大工匠梅卡托克，以及位于泰达希尔达纳苏斯之巅的大祭司泰兰德·语风。觐见这些统治者，让冒险者们得以一窥将人类、矮人、侏儒和暗夜精灵维系在一起的紧密联盟纽带。"},{t="急需援助的世界",b="在漫长的旅程结束并回到暴风城后，旅行者们将受到欢迎，并被提醒了解艾泽拉斯对于援助他们自己的人民至关重要。随着他们的组织仍在达拉然建立根基，当下的重点转向了首府周边的困境地区，首先便是陷入困境的西部荒野农场。"}},faq={{q="任务 探索联盟 是什么？",a="探索联盟 是一场外交旅程，旨在向新人介绍艾泽拉斯各地联盟的主要权力中心。作为受邀的客人，冒险者被赋予重任，前往世界各地会见铁炉堡、流亡中的诺莫瑞根以及达纳苏斯的领袖。",al={"探索联盟 任务","这个任务是什么"}},{q="兰达尔·艾默生 是谁？",a="兰达尔·艾默生 是一名驻扎在暴风城南侧前厅的侍从。他为旅行者提供初步的旅行方向和指引，并派遣他们前往其他首府城市。",al={"兰德尔·埃默森","谁提供指引"}},{q="在此次旅程中必须拜访哪些领袖？",a="这段旅程要求拜访铁炉堡的国王麦格尼·铜须、大工匠 格尔宾·梅卡托克，以及达纳苏斯的大祭司泰兰德·语风。每一位领袖都代表了联盟内的一个核心种族和权力中心。",al={"需要拜访的领袖","我该和谁对话"}},{q="为什么在完成任务时提到了达拉然？",a="冒险者的组织正在达拉然建立据点。在等待这些安排落实期间，旅行者们被鼓励熟悉艾泽拉斯并向周边地区提供援助。",al={"为什么提到达拉然","在达拉然的组织"}},{q="完成这段旅程后该去哪里？",a="在回到暴风城后，冒险者们会被指引前往首府周边的乡村地区，特别是西部荒野，那里的当地社区正饱受困扰，急需有能力的保卫者。",al={"接下来去哪里","完成 探索联盟 之后"}},{q="为什么冒险者被视为联盟的客人？",a="任务文本将冒险者视为初到艾泽拉斯的外来者，为了保护和帮助自己的人民，他们必须了解更广阔的世界，并体验联盟多样的文化。",al={"联盟的客人","为什么是客人"}}},fp="22,167,22.330.0,29.363.0,22.273.0,41.223.0,22.133.0,50.195.0,51.170.0,55.165.0,57.211.0"}
P.entries["quest:94"] = {n="法师的眼线",s="“警惕之眼”是联盟的一项任务，由位于艾尔文森林阿祖拉之塔的法师塞欧克瑞图斯发布。在建立了针对其竞争对手摩根斯的初步探知链接后，塞欧克瑞图斯指引冒险者向东前往赤脊山，将一枚附魔焦点放置在俯瞰伊尔加拉之塔的一座古老狮子雕像上。",h="“警惕之眼”是联盟的一项任务，由位于艾尔文森林阿祖拉之塔的法师塞欧克瑞图斯发布。在建立了针对其竞争对手摩根斯的初步探知链接后，塞欧克瑞图斯指引冒险者向东前往赤脊山，将一枚附魔焦点放置在俯瞰伊尔加拉之塔的一座古老狮子雕像上...",kw={"艾尔文","阿祖拉的铭文饰品","摩根斯","古老的狮子雕像","赤脊山","塞欧克瑞图斯","阿祖拉之塔","伊尔加拉之塔"},ang={["class:Mage"]="对于奥术修行者来说，这项任务展示了远程占卜和探知中继，并将塞欧克瑞图斯正统的艾尔文学院派方法与摩根斯非法的叛逆术士手段进行了对比。",["faction:Alliance"]="制裁像摩根斯这样的叛逆人类施法者，对于确保艾尔文森林与饱受战争蹂躏的赤脊山定居点之间的边境安全至关重要。"},sec={{t="边境上的竞争",b="塞欧克瑞图斯在他的艾尔文森林东部的塔楼中，时刻警惕地监视着附近山丘中酝酿的黑暗法术。他的主要宿敌摩根斯是一位拥有强大力量的邪恶术士，他占据了位于赤脊山岩脊上的伊尔加拉之塔。为了在摩根斯的险恶野心蔓延到边境之前揭露它们，塞欧克瑞图斯开发了阿祖拉之眼，用于从远处监视这位叛逆法师。"},{t="狮子的守望",b="虽然视觉探知能提供一些信息，但不足以洞察摩根斯更深层的阴谋。塞欧克瑞图斯将阿祖拉的铭文饰品托付给旅行者，命令他们前往伊尔加拉之塔的阴影处。在那里，几十年来孤独伫立着一座古老的狮子雕像。将铭文饰品放入雕像底座一个磨损的凹槽中，可以唤醒一条奥术管道，将这块石头与阿祖拉链接起来，使塞欧克瑞图斯能够直接窥探他竞争对手的思想。"}},faq={{q="谁是塞欧克瑞图斯？",a="塞欧克瑞图斯是一位强大的联盟法师，居住在艾尔文森林东部的阿祖拉之塔顶端。他致力于通过奥术研究来保护该地区免受叛逆魔法威胁，其中最主要的就是邪恶术士摩根斯。",al={"塞欧克瑞图斯","阿祖拉之塔法师","谁给予警惕之眼任务"}},{q="谁是摩根斯？",a="摩根斯是一位心怀恶意的叛逆人类法师，他在赤脊山的伊尔加拉之塔建立了据点。他是塞欧克瑞图斯的死敌，塞欧克瑞图斯非常担心摩根斯正在策划针对周边地区的黑暗阴谋。",al={"摩根斯","谁是摩根斯","敌对法师"}},{q="古老的狮子雕像在哪里？",a="古老的狮子雕像饱经风霜，伫立在俯瞰伊尔加拉之塔的山脊上，位于赤脊山的东部山区。它的底座上有一个浅凹槽，旨在承载像阿祖拉的铭文饰品这样的魔法焦点。",al={"狮子雕像位置","雕像在哪里","阿祖拉的铭文饰品放在哪里"}},{q="阿祖拉的铭文饰品有什么用？",a="阿祖拉的铭文饰品是塞欧克瑞图斯制作的一块附魔石。当它被嵌入伊尔加拉之塔附近的狮子雕像中时，它就充当了一个奥术监听站和思想探测中继站，让塞欧克瑞图斯能够通过雕像进行交流并研究摩根斯的想法。",al={"阿祖拉的铭文饰品","什么是铭文饰品"}},{q="什么是伊尔加拉之塔？",a="伊尔加拉之塔是一座高耸、孤立的石塔，矗立在赤脊山东部的岩脊高处。这是一座法师塔，目前被摩根斯和他的爪牙占据并防守着。",al={"伊尔加拉之塔","伊尔加拉"}},{q="放置铭文饰品后会发生什么？",a="一旦阿祖拉的铭文饰品被固定在雕像上，塞欧克瑞图斯就会通过石头说话，并立即提供后续任务“进一步观察”，因为他开始揭开摩根斯的阴谋。",al={"下一个任务","警惕之眼之后做什么"}}},fx={["0c307b8a"]={q="塞欧克瑞图斯为什么希望完成这件事？",a="莫甘斯是个冷酷无情、实力强大的法师，藏身于伊尔加拉之塔。虽然塞欧克瑞图斯能借助阿祖拉之眼的占卜魔法窥视这名对手，但仅仅看见他已经不够了。塞欧克瑞图斯希望将阿祖拉的铭文饰品固定在附近的狮子雕像上，借此探入莫甘斯的心智，在这个黑暗巫师将阴谋付诸实施、危及这片地区之前，查明他的计划。",al={"塞欧克瑞图斯的动机","为什么放置阿祖拉的铭文饰品","为什么监视莫甘斯"}}},fp="14,186,27.296.0,16.348.0,18.173.0,16.201.0,37.175.0,32.188.0,29.144.0,35.150.0"}
P.entries["quest:940"] = {n="泰达希尔",s="在清除了神谕林地附近的那些堕落鹰身人之后，哨兵阿瑞尼亚·碎云委托你将一份状态报告送往达纳苏斯。这份刻字的树皮是写给大德鲁伊范达尔·鹿盔的，上面记录了这棵世界之树枝桠的状况以及正在侵蚀它的腐化。",h="在清除了神谕林地附近的那些堕落鹰身人之后，哨兵阿瑞尼亚·碎云委托你将一份状态报告送往达纳苏斯。这份刻字的树皮是写给大德鲁伊范达尔·鹿盔的，上面记录了这棵世界之树枝桠的状况以及正在侵蚀它的腐化。",kw={"阿瑞尼亚·碎云","塞纳里奥区","达纳苏斯","范达尔·鹿盔","永生","刻字的树皮","卡多雷","神谕林地","泰达希尔"},ang={["class:Druid"]="从古老的神谕林地带消息直接呈交给塞纳里奥议会的领袖，突显了为了净化泰达希尔的自然平衡所进行的持续斗争。",["faction:Alliance"]="对于在岛上完成初期职责的联盟勇士来说，这个任务提供了对暗夜精灵首都及其严厉领导层的正式引见。",["race:NightElf"]="递交这份报告让你与大德鲁伊鹿盔面对面，揭示了他个人通过泰达希尔这受困的枝桠来恢复卡多雷永生的执念。"},sec={{t="前往石之城的信使",b="在泰达希尔深处的枝桠间，神谕林地守护着整片森林。在清除了神谕林地里鹰身人的巢穴后，哨兵阿瑞尼亚·碎云认为终于可以安全地向卡多雷的领导层传达消息了。她将一块刻字的树皮交给你，让你穿过荒野进入达纳苏斯——那座宏伟的“石之森林”——将神谕林地的报告直接呈交给大德鲁伊范达尔·鹿盔。"},{t="鹿盔的雄心与挫败",b="当范达尔·鹿盔收到这份报告时，心情十分复杂。虽然他对鹰身人被击退的消息感到欣慰，但报告也强调了一个更深层的事实：泰达希尔上的一个威胁刚减弱，另一个威胁又开始滋生。对于这位为了让暗夜精灵重获失去的永生而力主种植新世界之树的鹿盔来说，枝桠上持续不断的灾祸时刻提醒着他，他那宏大的事业还远未完成。"}},faq={{q="任务“泰达希尔”的目的是什么？",a="这个任务起到了叙事桥梁的作用，连接了你在神谕林地周边的荒野冒险与主城。哨兵阿瑞尼亚·碎云指派你将刻有神谕林地报告的刻字的树皮送到达纳苏斯，交给大德鲁伊范达尔·鹿盔。",al={"泰达希尔任务目标","这个任务的作用","泰达希尔送信"}},{q="哨兵阿瑞尼亚·碎云是谁？",a="阿瑞尼亚·碎云是一位驻扎在泰达希尔荒野中神谕林地附近的暗夜精灵哨兵。她负责监视当地的威胁，比如当地的血羽鹰身人，并与达纳苏斯协调森林防御事宜。",al={"阿瑞尼亚·碎云背景故事","谁发布泰达希尔任务"}},{q="为什么阿瑞尼亚称达纳苏斯为“石之森林”？",a="虽然暗夜精灵生活在世界之树的树冠之中，但达纳苏斯城却是由大理石和石头建造的宏伟神殿、桥梁和亭台楼阁组成。与神谕林地周围未受驯化的荒野相比，这座首都就是一座人造的石之森林。",al={"石之森林含义","为什么叫石之森林"}},{q="为什么范达尔·鹿盔对神谕林地的报告如此忧心忡忡？",a="在诺达希尔于第三次战争中受损后，鹿盔带头培育了泰达希尔，希望能借此让卡多雷重获永生。来自神谕林地的消息证实，泰达希尔持续遭受着腐化的蔓延和野生动物动荡的侵扰，这使得他的雄心壮志危在旦夕。",al={"范达尔·鹿盔反应","为什么鹿盔忧虑"}},{q="哪个任务引导至此，后续任务是什么？",a="该任务紧接在“被施了魔法的林地”之后，在那个任务中你处理了威胁神谕林地的鹰身人。将报告交给大德鲁伊鹿盔后，他会派你前往黑海岸，进行后续任务“远古之林”。",al={"泰达希尔任务线","后续任务是什么"}},{q="大德鲁伊范达尔·鹿盔在哪里？",a="大德鲁伊范达尔·鹿盔居住在达纳苏斯，站在塞纳里奥区的顶端，在那里他统领着塞纳里奥议会的德鲁伊们，并指导卡多雷的治理工作。",al={"范达尔在哪里","范达尔·鹿盔位置"}}},fp="10,203,29.359.0,35.336.0,46.188.0,35.219.0,51.210.0,68.276.0,48.200.0,47.172.0"}
P.entries["quest:94003"] = {n="The Skybreaker Bulwark",s="“破天者壁垒”是泽风岛上的一个任务，讲述了破天者家族悲惨的覆灭。冒险者受命前往阿基尔神殿，从邪教徒扎尔·风盾手中夺回一面神圣的家族盾牌。",h="“破天者壁垒”是泽风岛上的一个任务，讲述了破天者家族悲惨的覆灭。冒险者受命前往阿基尔神殿，从邪教徒扎尔·风盾手中夺回一面神圣的家族盾牌。",kw={"奥拉凯斯","阿基尔神殿","破天者","破天者壁垒","破天者防御","扎尔·风盾","泽风岛"},ang={["class:Paladin"]="崇敬神圣遗物的持盾保卫者们一定会乐于从腐化的邪教徒手中夺回这件受祝福的传家宝。",["class:Warrior"]="看重防御能力的战士们将在这里找到志同道合的目标，因为找回祖传之盾将获得“破天者防御”技巧的指导作为奖励。"},sec={{t="陨落的家族",b="在泽风岛上，破天者家族的血脉在奥拉凯斯的屠戮下迎来了悲剧性的终结。整个家族惨遭灭门，只剩下一名幸存者，背负着深重的哀伤和丢失家族至宝的苦涩耻辱。这件珍贵的遗物——破天者壁垒，被一名叫作扎尔·风盾的邪教徒夺走，目前他正潜伏在阿基尔神殿中。"},{t="神圣之盾",b="根据家族传统，破天者壁垒拥有一种守护祝福：任何真正有资格挥舞它的人都不会受到伤害。最后一位破天者确信邪教徒扎尔并不配得到它的神圣眷顾，因此寻找一名冒险者前往阿基尔神殿，击倒这个窃贼，夺回这面祖传之盾，作为交换，他将传授“破天者防御”技巧。"}},faq={{q="谁是破天者？",a="破天者是泽风岛上的一个古老家族，其成员几乎已被悉数消灭。任务发布者是这个家族唯一的幸存者，其余族人皆死于奥拉凯斯之手。",al={"谁是破天者","破天者家族"}},{q="什么是破天者壁垒？",a="破天者壁垒是一面属于泽风岛破天者家族的祖传盾牌。根据家族传统和传说，任何被视为有资格挥舞此盾的人都无法受到伤害。",al={"什么是破天者壁垒","这面盾牌","破天者之盾背景故事"}},{q="谁是奥拉凯斯？",a="奥拉凯斯是导致泽风岛破天者家族灭门的敌对势力，只留下了一名幸存者独自哀悼惨剧。",al={"谁杀了破天者家族","什么是奥拉凯斯","奥拉凯斯"}},{q="扎尔·风盾是谁？",a="扎尔·风盾是一名邪教徒，他在破天者家族覆灭后偷走了破天者壁垒。人们可以在泽风岛的阿基尔神殿找到他，他正带着这件传家宝。",al={"谁拿着盾牌","扎尔","风盾"}},{q="阿基尔神殿在哪里？",a="阿基尔神殿是泽风岛上的一处地点，邪教徒扎尔·风盾带着偷来的破天者壁垒躲藏在那里。",al={"扎尔在哪里","阿基尔神殿位置","去哪找盾牌"}},{q="为什么要夺回壁垒？",a="找回传家宝能洗刷家族的耻辱，并使这件神圣遗物脱离无名之辈的魔掌。作为夺回它的报酬，最后一位破天者将传授“破天者防御”的相关知识。",al={"为什么要找回盾牌","什么是破天者防御","盾牌奖励"}}},fp="22,144,16.273.0,17.345.0,24.143.0,31.153.0,21.98.0,24.166.0,28.103.0,34.187.0"}
P.entries["quest:94006"] = {n="The Great Ursera Spirit",s="一位德鲁伊派你去拜见Urs'endris，他是Zephras的一位精魂，世世代代教导德鲁伊化为ursera形态。他的领地正在枯萎，而Urs'endris能进一步指引你的修行。",h="一位德鲁伊派你去拜见Urs'endris，他是Zephras的一位精魂，世世代代教导德鲁伊化为ursera形态。他的领地正在枯萎，而Urs'endris能进一步指引你的修行。",kw={"德鲁伊","瀑布","阿基尔神殿","精魂","urs'endris","ursera","瓦拉纳尔","zephras"},ang={["class:Druid"]="身为德鲁伊，你的修行引领你前来拜见Urs'endris，他世世代代教导德鲁伊化为ursera形态。"},sec={{t="伟大之灵",b="一位德鲁伊派你前往瓦拉纳尔东北方的瀑布附近，拜见Urs'endris。你在德鲁伊之道上的修行，让你有机会拜见Zephras的一位伟大精魂。Urs'endris世世代代教导德鲁伊化为ursera形态，而他的领地正在枯萎，逐渐没入天空。"}},faq={{q="Urs'endris是谁？",a="Urs'endris是Zephras的一位睿智精魂，世世代代教导德鲁伊化为ursera形态。",al={"urs'endris是谁","伟大精魂urs","ursera精魂"}},{q="在哪里能找到Urs'endris？",a="Urs'endris就在瓦拉纳尔东北方的瀑布附近，靠近阿基尔神殿。",al={"urs'endris位置","urs'endris在哪里","拜见精魂"}},{q="为什么要派我去拜见Urs'endris？",a="你在德鲁伊之道上的修行已足以让你拜见Zephras的一位伟大精魂，而Urs'endris能进一步教导你。",al={"为何拜见urs'endris","德鲁伊精魂任务","ursera修行"}},{q="Urs'endris的领地正在发生什么？",a="Urs'endris的领地已开始枯萎，并坠入天空。",al={"枯萎的领地","zephras坠落","那里出了什么问题"}},{q="什么是ursera形态？",a="ursera形态是Urs'endris世世代代教导德鲁伊变化成的一种形态。",al={"ursera形态","way of the claw","ursera"}}},fp="23,185,16.270.0,18.102.0,28.76.0,34.132.0,41.62.0,25.80.0"}
P.entries["quest:94007"] = {n="Taming the Beast",s="瓦拉纳尔的 Quel'ana Quickgale 可以教你驯服野兽。你在高地的历练已让你做好寻找动物伙伴的准备。",h="瓦拉纳尔的 Quel'ana Quickgale 可以教你驯服野兽。你在高地的历练已让你做好寻找动物伙伴的准备。",kw={"动物伙伴","驯服野兽","高地","奎尔安娜·疾风","瓦拉纳尔"},sec={{t="新的伙伴",b="你在高地渐渐适应了这里的生活，你的主人认为你已准备好寻找动物伙伴。前往瓦拉纳尔，与 Quel'ana Quickgale 谈谈；他会开始教你驯服野兽的技艺。"}},faq={{q="谁教我驯服野兽？",a="奎尔安娜·疾风 会在瓦拉纳尔教你驯服野兽的技艺。",al={"奎尔安娜·疾风 是谁","驯服野兽的导师"}},{q="我在哪里能找到 奎尔安娜·疾风？",a="奎尔安娜·疾风 位于瓦拉纳尔，那是东南方的港口。",al={"奎尔安娜 在哪里","瓦拉纳尔驯兽"}},{q="我为什么要去瓦拉纳尔？",a="你将前往瓦拉纳尔，与 奎尔安娜·疾风 谈谈并开始学习驯服野兽。",al={"为什么去瓦拉纳尔","驯服野兽任务"}},{q="我要学习什么？",a="奎尔安娜·疾风 会教你如何驯服野兽，这样你就能寻找动物伙伴。",al={"什么是驯服野兽","动物伙伴"}}},fp="16,135,15.187.0,25.58.0,35.61.0,27.92.0,19.86.0"}
P.entries["quest:94013"] = {n="Taming the Beast",s="Quel'ana Quickgale为你安排了最后的试炼：驯服一只Vuldren Alpha。掌握这项本领后，你便能学习职业更深奥的技艺。",h="Quel'ana Quickgale为你安排了最后的试炼：驯服一只Vuldren Alpha。掌握这项本领后，你便能学习职业更深奥的技艺。",kw={"动物伙伴","阵风浆果低地","奎尔安娜·疾风","驯兽棒","驯服野兽","瓦拉纳尔","沃尔德伦头领","泽风岛"},sec={{t="最后的试炼",b="Quel'ana交给你一根驯兽棒，并派你前往阵风浆果低地。在那里，你要驯服一只Vuldren Alpha，然后回到瓦拉纳尔把驯兽棒还给他。这堂课旨在证明你的本领，并为你深入学习本职业的知识做好准备。"},{t="新的课程",b="你回来后，Quel'ana说你已经学会了基础知识，并提出教你如何与动物伙伴建立长久的羁绊。他希望你将这份知识传承下去，因为泽风岛需要本职业的力量。"}},faq={{q="奎尔安娜要我驯服什么？",a="奎尔安娜要你用驯兽棒在阵风浆果低地驯服一只沃尔德伦首领。",al={"驯服沃尔德伦首领","什么野兽","驯服首领"}},{q="我在哪里能找到沃尔德伦首领？",a="弗尔德伦头领位于阵风浆果低地。",al={"首领位置","阵风浆果低地","哪里驯服野兽"}},{q="驯兽棒有什么用？",a="奎尔安娜交给你驯兽棒，用来驯服一只弗尔德伦头领。",al={"驯兽棒用途","驯兽棒任务","如何使用驯兽棒"}},{q="我该把驯兽棒交到哪里？",a="把驯兽棒交还给瓦拉纳尔的奎尔安娜·疾风。",al={"归还驯兽棒","奎尔安娜位置","哪里归还驯兽棒"}},{q="完成后我会学到什么？",a="奎尔安娜说，他可以教你如何与动物伙伴建立长久的羁绊。",al={"下一课","动物伙伴羁绊","之后是什么"}}},fp="16,136,15.228.0,12.223.1,34.88.0,34.47.0,27.58.0,33.56.0,29.79.0"}
P.entries["quest:94050"] = {n="Training the Beast",s="一位猎人同伴让你去瓦拉纳尔找 Quel'dora Quickgale，学习如何训练宠物。她的教导让你能更好地照料并引导它。",h="一位猎人同伴让你去瓦拉纳尔找 Quel'dora Quickgale，学习如何训练宠物。她的教导让你能更好地照料并引导它。",kw={"喂养宠物","猎人","宠物训练","奎尔多拉·疾风","复活宠物","驯服宠物","训练野兽","瓦拉纳尔"},ang={["class:Hunter"]="作为一名猎人，你正在学习如何训练并引导自己已经能够驯服的宠物。"},sec={{t="Quel'dora 的教导",b="你的猎人同伴指引你去瓦拉纳尔找他的妹妹，Quel'dora Quickgale。你已经会驯服宠物，但接下来还要学会训练它，才能更好地引导它。Quel'dora Quickgale可以教你训练伙伴。"},{t="猎人的职责",b="Quel'dora 可以教你引导宠物、传授它新的技能、喂养它，并在它战斗中倒下时使它复活。她叮嘱你尊重自然的平衡，并对周遭的自然万物心怀敬畏。"}},faq={{q="奎尔多拉·疾风 是谁？",a="奎尔多拉·疾风 是那位让你去学习宠物训练的猎人的姐妹。",al={"谁是奎尔多拉","奎尔多拉","疾风"}},{q="我在哪里能找到 奎尔多拉？",a="奎尔多拉·疾风 位于瓦拉纳尔。",al={"奎尔多拉在哪里","奎尔多拉的位置","瓦拉纳尔训练师"}},{q="奎尔多拉 会教些什么？",a="奎尔多拉 会教你训练并引导宠物，包括传授它技能、喂养它，以及在它战斗中倒下时使它复活。",al={"宠物训练","训练我的宠物","宠物训练师能教什么"}},{q="我已经能驯服宠物了吗？",a="让你去找 奎尔多拉 的猎人说，你已经拥有驯服宠物的能力。",al={"驯服宠物","猎人能驯服宠物吗","猎人能否驯服"}},{q="猎人让我做什么？",a="猎人让你去瓦拉纳尔与 奎尔多拉·疾风 谈谈。",al={"训练野兽","宠物训练任务","与奎尔多拉交谈"}},{q="奎尔多拉 如何看待自然？",a="奎尔多拉 叮嘱你尊重自然的平衡，并对周遭的自然万物心怀敬畏。",al={"尊重自然","平衡","奎尔多拉的建议"}}},fp="18,119,20.166.0,17.191.0,27.84.0,27.35.0,26.116.0,25.84.0,34.66.0,37.84.0"}
P.entries["quest:941"] = {n="培养心脏",s="“植入心脏”是泰达希尔奥拉密斯湖畔的草药师德纳兰委托的一项任务。在从一个被腐蚀的树苗怪身上取下一颗奇怪的木质心脏，并刮去上面窒息般的苔藓后，德纳兰试图测试他特别调配的肥沃土壤是否能够净化并治愈其中残留的污染。",h="“植入心脏”是泰达希尔奥拉密斯湖畔的草药师德纳兰委托的一项任务。在从一个被腐蚀的树苗怪身上取下一颗奇怪的木质心脏，并刮去上面窒息般的苔藓后，德纳兰试图测试他特别调配的肥沃土壤是否能够净化并治愈其中残留的污染。",kw={"恶臭黑苔","净化后的心脏","德纳兰","奥拉密斯湖","种植箱","被污染的心脏","泰达希尔","树苗怪"},ang={["class:Druid"]="对于一名德鲁伊来说，亲眼目睹被腐蚀的树苗怪核心在肥沃土地中得到净化，是一个令人宽慰的迹象，表明困扰世界之树枝叶的非自然污染仍可通过自然的护理加以扭转。",["profession:Herbalism"]="德纳兰对营养丰富的土壤和植物复苏的掌握，展示了研究大地与修复受损植物生命之间的重要联系。",["race:NightElf"]="修复活木并唤醒陨落森林之灵，反映了卡多雷即便在面对泰达希尔的棘手疾病时，依然致力于守护自然的决心。"},sec={{t="重获新生的机会",b="在检查从名为“恶臭黑苔”的腐蚀树苗怪身上回收的那颗奇怪木质核心时，德纳兰设法刮掉了缠绕在它表面的污秽苔藓。然而尽管他付出了努力，木头深处依然跳动着一股不自然、深沉的污染。德纳兰没有选择焚烧或丢弃它，而是运用他毕生的植物学和土壤培育技艺。他指示旅行者将心脏直接埋入他个人的种植箱中，坚信他混合的丰富养分能够唤回那残存的自然生命力，使其恢复健康。"},{t="肥沃土地的奇迹",b="将那颗发黑的木质心脏放入德纳兰的种植箱中，产生了意想不到的反应。当它接触到肥沃土壤的那一刻，心脏仿佛受原始本能驱使一般钻入了土中。片刻之后，它又重新浮出地面，原本污秽的腐蚀已被清除，现在正散发着一种柔和、亲切的温热。通过净化这颗陨落的被腐蚀生物之种子，德纳兰证明了即使泰达希尔的野生生物沦为了非自然枯萎病的牺牲品，悉心的照料和神圣的土壤依然能够恢复和谐。"}},faq={{q="这颗被污染的心脏从何而来？",a="这颗心脏最初来自“恶臭黑苔”，一种潜伏在奥拉密斯湖岸边的腐蚀树苗怪。在被德纳兰清理干净之前，它被缠绕着的污秽苔藓所覆盖。",al={"心脏来源","心脏从哪里来","黑苔心脏"}},{q="德纳兰是谁？",a="德纳兰是一位暗夜精灵植物学家和草药师，在奥拉密斯湖的东岸照看一个孤立的营地。他每天都在研究泰达希尔的植物生命，调查在枝叶间蔓延的奇怪腐蚀，并调制肥沃的土壤。",al={"德纳兰是谁","德纳兰背景"}},{q="为什么要将心脏种在种植箱里而不是摧毁它？",a="德纳兰相信理解和治愈自然，而非仅仅摧毁被腐蚀的生物。他希望他配制的营养土壤能够清除污染，恢复心脏原本纯净的生命力。",al={"为什么要种植心脏","为什么要治愈心脏"}},{q="埋下心脏后会发生什么？",a="心脏在接触到土壤后会立即钻入土中。几秒钟后，它会扭动着回到地表，原本的污秽污染被完全清除，并轻轻跳动，仿佛一个活生生的同伴。",al={"种植箱里发生了什么","心脏钻入"}},{q="这能治愈树苗怪的腐蚀吗？",a="它只能治愈这颗被抢救出来的心脏。虽然这证明了单个植物精魂可以通过照料和肥沃土壤得到净化，但在泰达希尔蔓延的普遍腐蚀仍然是一个活跃的威胁。",al={"树苗怪是否被治愈","治愈树苗怪"}},{q="德纳兰种植箱里的土壤有什么特别之处？",a="德纳兰在奥拉密斯湖周围花费了大量时间研究堆肥和营养土配方，旨在设计出足以让病弱的植物恢复活力并清除蔓延腐朽的强力土壤。",al={"德纳兰的土壤","种植箱土壤"}}},fp="18,188,23.366.0,29.383.1,40.167.0,15.228.0,56.176.0,37.167.1,49.183.0,45.184.0"}
P.entries["quest:942"] = {n="健忘的勘察员",s="此任务将黑海岸的挖掘之谜跨越无尽之海连接到湿地。首席考古学家杜瑟·灰须委托你携带一块奇异的卡利姆多化石，指引你前往米奈希尔港寻找考古学家弗拉冈特以解开其中的秘密。",h="此任务将黑海岸的挖掘之谜跨越无尽之海连接到湿地。首席考古学家杜瑟·灰须委托你携带一块奇异的卡利姆多化石，指引你前往米奈希尔港寻找考古学家弗拉冈特以解开其中的秘密。",kw={"健忘的勘察员","考古学家弗拉冈特","首席考古学家杜瑟·灰须","黑海岸","深水旅店","探险者协会","米奈希尔港","神秘的化石"},ang={["faction:Alliance"]="这项任务需要利用联盟航线，从卡利姆多乘船前往米奈希尔港，以保持协会各分支机构的联系。",["race:Dwarf"]="对于矮人冒险者来说，这次差事展示了探险者协会的影响力，将偏远卡利姆多的实地考察与驻扎在卡兹莫丹的学者同僚们联系了起来。"},sec={{t="一个奇特的发现",b="在检查黑海岸出土的奇异化石时，首席考古学家杜瑟·灰须注意到它与铁炉堡探险者协会会议上展示的一件遗物惊人地相似。那件早期的展品是由考古学家弗拉冈特展示的，他坚信此类化石蕴含着等待被发掘的潜能。杜瑟·灰须认为弗拉冈特是唯一有能力辨别这件卡利姆多发现为何如此特别的矮人。"},{t="横渡海洋的航程",b="携带这件神秘遗物意味着要从卡利姆多长途跋涉前往东部王国。最后一次见到弗拉冈特时，他正寄宿在米奈希尔港的深水旅店，等待武装护送前往维格尔挖掘场。将化石交到他手中是一个转折点，标志着一次局部的黑海岸考察与一项跨越大陆的考古研究联系在了一起。"}},faq={{q="为什么杜瑟·灰须要派我远赴米奈希尔港？",a="首席考古学家杜瑟·灰须回想起考古学家弗拉冈特曾在铁炉堡举办的探险者协会年度会议上展示过一件一模一样的遗物。杜瑟·灰须相信弗拉冈特拥有解开其隐藏力量的专业知识，因此派遣你去他在米奈希尔港最后已知的地点寻找他。",al={"为什么要去米奈希尔港","杜瑟·灰须的化石差事","为什么去湿地"}},{q="考古学家弗拉冈特是谁？",a="考古学家弗拉冈特是一位驻扎在湿地的探险者协会研究员。他正滞留在米奈希尔港的深水旅店，为前往危险的维格尔挖掘场进行探险做准备。",al={"谁是弗拉冈特","考古学家弗拉冈特的背景故事"}},{q="神秘的化石是什么？",a="这是一件从黑海岸取回的古老且奇特的样本。弗拉冈特此前曾声称，他研究过的一件孪生样本拥有等待被发掘的潜在魔法或历史力量。",al={"化石是什么","神秘化石的起源","雷姆塔维尔的化石"}},{q="当你交付化石时，弗拉冈特说了什么？",a="弗拉冈特惊讶地发现，一件与他自己的研究样本完全相同的遗物竟来自遥远的卡利姆多大陆，这证实了古代历史将这两片大陆联系在了一起。",al={"弗拉冈特的反应","移交化石"}},{q="弗拉冈特接下来想去哪里？",a="弗拉冈特一直在米奈希尔港等待护送人员，以便深入内陆前往位于湿地的主要挖掘点——维格尔挖掘场。",al={"弗拉冈特要去哪里","弗拉冈特的挖掘工作"}},{q="这个任务如何融入“健忘的勘察员”故事情节？",a="这是任务线的过渡阶段。在黑海岸护送并救出勘察员雷姆塔维尔，并与杜瑟·灰须一起分析他挖掘出的遗物后，调查工作直接从卡利姆多北部转向了东部王国的协会专家。",al={"健忘的勘察员第4部分","任务链背景"}}},fp="28,201,19.374.0,23.327.0,60.282.0,31.217.0,30.195.0,52.171.0,37.121.0,68.212.0"}
P.entries["quest:94212"] = {n="工匠文书: Elixir of Wisdom",s="一份可转让的工匠文书要求交付一瓶 Elixir of Wisdom，并注明交付地点和报酬。完成交易时必须持有文书。",h="一份可转让的工匠文书要求交付一瓶 Elixir of Wisdom，并注明交付地点和报酬。完成交易时必须持有文书。",kw={"工匠文书","交付","elixir of wisdom","报酬","可转让","文书"},sec={{t="书面请求",b="一张褪色的便笺名为“工匠文书：Elixir of Wisdom”，请你带来一瓶 Elixir of Wisdom。便笺注明了交付地点和报酬，而且文书可以转交他人。完成交易时，你必须持有文书。"}},faq={{q="文书要求提供什么？",a="它要求提供一瓶 Elixir of Wisdom。",al={"药剂文书","要求提供什么物品"}},{q="我可以把文书转交给别人吗？",a="可以。便笺上写着，这份文书可以转让。",al={"文书能否转让","能否由别人携带"}},{q="完成交易需要什么？",a="你需要持有所要求的物品和文书。便笺注明了交付地点和报酬。",al={"交付需要什么","如何完成文书交易"}}},fp="34,149,17.246.0,27.33.0,36.44.0,40.118.0"}
P.entries["quest:94214"] = {n="工匠文书: Shadow Protection Potion",s="一张可转让的委托单要求提供一瓶 Shadow Protection Potion，并注明了交付地点和付款方式。交易时必须随身携带委托单。",h="一张可转让的委托单要求提供一瓶 Shadow Protection Potion，并注明了交付地点和付款方式。交易时必须随身携带委托单。",kw={"工匠文书","交付","付款","药水","shadow protection potion","可转让","委托单"},sec={{t="书面请求",b="一张褪色的纸条请你提供一瓶 Shadow Protection Potion。纸条还注明了交付地点和付款方式，并说明委托单可以转交他人。完成交易时，你必须随身携带委托单。"}},faq={{q="委托单要求提供什么？",a="委托单要求提供一瓶 Shadow Protection Potion。",al={"他们想要什么","药水请求","委托单物品"}},{q="我该把药水送到哪里？",a="交付地点已在地图上标出。",al={"交付地点","药水送到哪里","标记的地点"}},{q="委托单上写了我会如何获得报酬吗？",a="委托单上写有付款信息。",al={"付款信息","他们付多少钱","委托单付款"}},{q="我可以把委托单交给别人吗？",a="可以。纸条上说这张委托单可以转交他人。",al={"可以转让吗","转交委托单","转让委托单"}},{q="我需要随身携带委托单吗？",a="需要。完成交易时，你必须随身携带委托单。",al={"交付时需要委托单","必须随身携带吗","需要委托单"}}},fp="42,156,17.215.0,27.47.0,22.44.0,37.44.0,36.44.0,35.65.0"}
P.entries["quest:94216"] = {n="工匠文书: Elixir of Lesser Agility",s="一份可转让的委托单要求你为顾客取得一瓶 Elixir of Lesser Agility。单上写有交付地点和付款详情。",h="一份可转让的委托单要求你为顾客取得一瓶 Elixir of Lesser Agility。单上写有交付地点和付款详情。",kw={"敏捷","工匠文书","交付","药剂","elixir of lesser agility","付款","可转让"},sec={{t="顾客的请求",b="一位顾客通过这份墨迹褪色的委托单求购 Elixir of Lesser Agility。你需要取得所求物品，并送到标记的地点；完成交易时必须随身带着委托单。"}},faq={{q="委托单要什么物品？",a="顾客要一瓶 Elixir of Lesser Agility。",al={"什么物品","药剂请求","他们要什么"}},{q="要送到哪里？",a="委托单指明了地图上标记的交付地点。",al={"交付地点","送到哪里","标记地点"}},{q="委托单上写了付款方式吗？",a="委托单上有付款信息。",al={"付款详情","付多少钱","付款内容"}},{q="别人可以带着委托单吗？",a="可以。底部的文字说明这份委托单可以转让。",al={"能否转让","转交给别人","交易委托单"}},{q="交付时需要委托单吗？",a="需要。完成交易时，你必须随身带着委托单。",al={"需要委托单吗","留着这张纸","必须有委托单"}}},fp="42,132,20.209.0,27.51.0,22.58.0,36.44.0,32.54.0,44.68.0"}
P.entries["quest:94219"] = {n="工匠文书: Draught of Water Breathing",s="一份可转让的委托书要求交付一瓶 Draught of Water Breathing，并注明交付地点和报酬。完成交易时必须持有这份委托书。",h="一份可转让的委托书要求交付一瓶 Draught of Water Breathing，并注明交付地点和报酬。完成交易时必须持有这份委托书。",kw={"工匠文书","交付","draught of water breathing","报酬","水下呼吸","委托书"},sec={{t="书面请求",b="这张褪色的便笺向你索要一瓶 Draught of Water Breathing。上面还注明了交付地点和报酬，并且可以转交给他人。"}},faq={{q="委托书要求什么？",a="委托书要求交付一瓶 Draught of Water Breathing。",al={"他们想要什么","药剂请求","委托书物品"}},{q="我该把它交到哪里？",a="委托书注明了交付地点，该地点已在你的地图上标出。",al={"交付地点","交到哪里","委托书位置"}},{q="提供了什么报酬？",a="委托书上写有报酬信息。",al={"报酬多少","委托书报酬","我能得到什么"}},{q="委托书可以转交吗？",a="可以。便笺上说，这份委托书可以转交。",al={"可转让的委托书","别人能帮忙携带吗","转交委托书"}},{q="完成交易时需要委托书吗？",a="需要。完成交易时，你必须随身携带委托书。",al={"需要便笺吗","必须持有委托书","没有委托书能交付吗"}}},fp="44,143,17.146.0,27.43.0,22.55.0,24.44.0,28.47.0,44.65.0"}
P.entries["quest:94220"] = {n="工匠文书: Pearl-Handled Dagger",s="一份可转让的委托文书要求交付 Pearl-Handled Dagger，并注明了交付和付款条件。完成交易时，你必须持有这份文书。",h="一份可转让的委托文书要求交付 Pearl-Handled Dagger，并注明了交付和付款条件。完成交易时，你必须持有这份文书。",kw={"工匠文书","匕首","交付","付款","pearl-handled dagger","委托文书"},sec={{t="委托文书",b="便笺上的字迹已经褪色，其中列出了所需物品 Pearl-Handled Dagger。下方几行注明了交付地点和付款条件。这份文书可以转交他人，但完成交易时你必须持有它。"}},faq={{q="文书要求什么物品？",a="文书要求 Pearl-Handled Dagger。",al={"珍珠匕首委托文书","所需物品"}},{q="我该把物品送到哪里？",a="交付地点已标记在你的地图上。",al={"交付地点","送到哪里"}},{q="委托人提供什么？",a="文书中包含付款信息。",al={"付款条件","支付多少"}},{q="我可以转交这份文书吗？",a="可以。文书上写明它可以转交他人。",al={"转交文书","便笺能否转交"}},{q="我需要留着这份文书吗？",a="需要。完成交易时，你必须持有这份文书。",al={"完成交易是否需要文书","必须持有便笺"}}},fp="38,141,8.243.0,27.41.0,28.44.0,29.44.0,25.41.0,27.70.0"}
P.entries["quest:94222"] = {n="Craftsman's Writ: Iridescent Hammer",s="一张褪色的委托书要求交付一把 Iridescent Hammer，并注明了交货和付款详情。持有人可凭可转让的标记完成交易。",h="一张褪色的委托书要求交付一把 Iridescent Hammer，并注明了交货和付款详情。持有人可凭可转让的标记完成交易。",kw={"工匠委托书","交货","锤子","iridescent hammer","付款","可转让","委托书"},sec={{t="委托书",b="客户要求一把 Iridescent Hammer。你必须随身携带委托书，才能在标记的地点完成交易。"}},faq={{q="客户想要什么？",a="客户要求一把 Iridescent Hammer。",al={"iridescent hammer 委托书","要求的物品"}},{q="我该把它交到哪里？",a="委托书注明了交货详情，地点也已标记在你的地图上。",al={"委托书交货地点","锤子交付地点"}},{q="我需要随身带着委托书吗？",a="需要。你必须持有委托书才能完成交易。",al={"交货是否需要委托书","需要委托书"}},{q="别人能使用这份委托书吗？",a="可以。这份委托书标明可转让。",al={"可转让的委托书","转交委托书"}},{q="委托书说明了付款方式吗？",a="委托书包含付款信息。",al={"锤子付款","付款金额"}}},fp="35,147,8.123.0,28.44.0,22.72.0,33.75.0,30.40.0,36.44.0"}
P.entries["quest:94223"] = {n="工匠文书: Silver Skeleton Key",s="一份可转交的委托书索要一把银色骷髅钥匙，并指明了交付地点。墓穴里有看守留下的便条，还有一只与钥匙有关的箱子。",h="一份可转交的委托书索要一把银色骷髅钥匙，并指明了交付地点。墓穴里有看守留下的便条，还有一只与钥匙有关的箱子。",kw={"看守","工匠文书","墓穴","乌鸦岭墓地","银色骷髅钥匙","箱子","亡灵"},sec={{t="委托书",b="褪色的墨迹写着需要一把银色骷髅钥匙，并注明了交付地点和报酬。这份委托书可以转交他人，但你必须带着它才能完成交易。"},{t="墓穴之中",b="箱子上的便条说，乌鸦岭墓地的看守已经死去。他说，夜色镇的雇主早已大多将他遗忘；他把财物留在箱中，赠予任何能打开箱子的人。附近有亡灵聚集，四下也不见旁人，你便使用了钥匙。箱中所剩无几，不过里面的东西足以抵上一部分花费。"}},faq={{q="委托书索要什么？",a="委托书索要一把银色骷髅钥匙，并注明了交付地点和报酬。",al={"银钥匙委托书","他们要什么钥匙"}},{q="别人可以替我保管委托书吗？",a="可以。委托书上说它可以转交他人，但你必须持有它才能完成交易。",al={"可转交的委托书","可以转交吗"}},{q="委托书让我去哪里？",a="委托书指向你地图上标记的地点。",al={"交付地点","钥匙要交到哪里"}},{q="谁在墓穴里留下了便条？",a="便条是一位乌鸦岭墓地的看守留下的，他说自己已经死去。",al={"看守的便条","谁死了"}},{q="箱子里有什么？",a="箱子几乎是空的，里面的东西足以抵上一部分花费。",al={"空箱子","看守的财物"}}},fp="37,165,8.165.0,12.334.1,27.81.0,32.97.0,28.56.0,31.77.0,22.72.0"}
P.entries["quest:94224"] = {n="工匠文书: Heavy Bronze Mace",s="一份褪色的委托书要求交付一把 Heavy Bronze Mace，并注明了交付和付款条款。完成交易需要这份委托书。",h="一份褪色的委托书要求交付一把 Heavy Bronze Mace，并注明了交付和付款条款。完成交易需要这份委托书。",kw={"工匠文书","交货","heavy bronze mace","锤子","付款","可转让的委托书"},sec={{t="书面请求",b="这张便笺用褪色的墨水写成，顾客要求一把 Heavy Bronze Mace。你要把所需物品送到地图上标记的地点。请随身带好委托书，完成交易时必须出示。"}},faq={{q="委托书要求什么？",a="顾客要求一把 Heavy Bronze Mace。",al={"heavy bronze mace 委托书","需要什么物品"}},{q="我该把锤子送到哪里？",a="地图上标记了交货地点。",al={"锤子交货地点","送到哪里"}},{q="我需要留着委托书吗？",a="需要。完成交易时，你必须持有委托书。",al={"是否需要委托书","需要委托书"}},{q="便笺上关于付款写了什么？",a="便笺上包含付款信息，但所提供的文本没有说明金额。",al={"锤子付款","付款金额"}},{q="别人能使用这份委托书吗？",a="底部的字迹说明这份委托书可以转让。",al={"可转让的委托书","把委托书转交给别人"}}},fp="35,133,17.218.0,27.44.0,28.44.0,27.69.0,37.92.0,30.56.0"}
P.entries["quest:94226"] = {n="工匠文书: Green Iron Gauntlets",s="MacKinley的委托书要求你把 Green Iron Gauntlets 带给他。这张可转让的便条写有交货和付款详情。",h="MacKinley的委托书要求你把 Green Iron Gauntlets 带给他。这张可转让的便条写有交货和付款详情。",kw={"工匠文书","交货","green iron gauntlets","green iron knuckles","mackinley","付款","可转让"},sec={{t="书面委托",b="褪色的委托书写着 Green Iron Gauntlets，并注明交货地点和报酬。完成交易时，你必须带着委托书。MacKinley正等着收货，不过他的问候透露出事情有些不对劲。"},{t="交货时",b="MacKinley说，他要的是 green iron knuckles，不是护手。他先收下护手，等着替换品送来，随后付给你的钱比你预想的少。"}},faq={{q="MacKinley要什么？",a="委托书上要一副 Green Iron Gauntlets，不过MacKinley说他本来想要的是 green iron knuckles。",al={"麦金利要什么","绿铁委托书"}},{q="我该把护手送到哪里？",a="委托书上注明了交货地点，地图上也标出了位置。",al={"交货地点","委托书地点"}},{q="我需要带着委托书吗？",a="需要。完成交易时，委托书必须在你身上。",al={"需要委托书吗","忘带委托书"}},{q="委托书上写了什么付款信息？",a="便条上写有付款信息，但没有注明具体金额。",al={"报酬多少","付款详情"}},{q="别人可以帮忙带委托书吗？",a="可以。便条上说委托书可以转让。",al={"可转让的委托书","可以转交委托书吗"}}},fp="38,123,15.216.0,15.157.1,28.114.0,33.55.0,27.66.0,37.77.0,32.44.0"}
P.entries["quest:94229"] = {n="工匠文书: Ornate Spyglass",s="这份可转让的委托单要求交付一架精致望远镜，并注明了交货和付款细节。等候中的顾客说，工程师还没有交货。",h="这份可转让的委托单要求交付一架精致望远镜，并注明了交货和付款细节。等候中的顾客说，工程师还没有交货。",kw={"工匠文书","交货","工程师","精致望远镜","付款","望远镜","委托单"},ang={["profession:Engineering"]="身为工程师，你与这笔订单有关：等候中的顾客说，工程师还没有交付望远镜。"},sec={{t="等候中的顾客",b="一位顾客正等着工程师交付一架精致望远镜。这张褪色的委托单写明了所需物品、交货地点和付款方式。要完成交易，你必须随身携带委托单。"}},faq={{q="委托单要求什么？",a="委托单要求一架精致望远镜。",al={"精致望远镜委托单","所需物品"}},{q="我该把望远镜送到哪里？",a="委托单注明了交货地点，地图上已作标记。",al={"望远镜交货地点","送到哪里"}},{q="委托单说明了付款方式吗？",a="委托单包含付款信息，但这里没有写明金额。",al={"望远镜付款","报酬多少"}},{q="我为什么要留着委托单？",a="你必须随身携带委托单才能完成交易。",al={"需要委托单吗","忘带委托单"}},{q="谁在等着收货？",a="一位顾客正等着工程师交付这架精致望远镜。",al={"谁要望远镜","等候中的顾客"}}},fp="33,163,18.217.0,27.38.0,32.55.0,36.79.0,31.60.0,29.69.0"}
P.entries["quest:94231"] = {n="工匠文书: Moonsight Rifle",s="一份可转让的委托单索要一支 Moonsight Rifle，并注明交货地点和报酬。买家希望这笔交易不引人注意。",h="一份可转让的委托单索要一支 Moonsight Rifle，并注明交货地点和报酬。买家希望这笔交易不引人注意。",kw={"身份掩护","工匠文书","交叉火力","交货","moonsight rifle","报酬","步枪","萨特"},sec={{t="秘密交易",b="一张褪色的便条请你把一支 Moonsight Rifle送到标记的地点，报酬会在那里安排。委托单可以转手，但你必须亲自携带它才能完成交易。买家警告说，你的接近引起了注意，可能会暴露他们的身份。"},{t="步枪",b="拿出 Moonsight Rifle后，买家称赞它对付萨特时威力强大。他们让你赶紧退到一旁，免得交火开始时被卷入。"}},faq={{q="委托单要什么？",a="委托单要求提供一支 Moonsight Rifle，并送到地图上标记的地点。",al={"moonsight rifle 委托单","他们要什么步枪"}},{q="我能把委托单交给别人吗？",a="可以。便条上说委托单可以转让，但你必须持有它才能完成交易。",al={"委托单能否转让","转交委托单"}},{q="买家为什么要这么隐秘？",a="买家说你的接近引起了注意，可能会暴露他们的身份。",al={"为何如此隐秘","暴露身份"}},{q="这支步枪是用来对付谁的？",a="买家说这支步枪能把萨特的脑袋打飞。",al={"对付萨特的步枪","moonsight rifle 目标"}}},fp="33,127,16.270.0,9.139.1,27.87.0,36.107.0,33.86.0,42.62.0"}
P.entries["quest:94233"] = {n="工匠文书: Practice Lock",s="一份可转让的委托书请你提供一个 Practice Lock。交付地点和报酬条件都标在纸条上。",h="一份可转让的委托书请你提供一个 Practice Lock。交付地点和报酬条件都标在纸条上。",kw={"工匠文书","交付","锁","报酬","practice lock","可转让","委托书"},sec={{t="书面请求",b="一位顾客通过一份褪色的可转让委托书，订购了一个 Practice Lock。请将所需物品送到地图上标记的地点，并随身携带委托书以完成交易。"}},faq={{q="委托书要求提供什么？",a="委托书要求提供一个 Practice Lock。",al={"practice lock 委托","物品是什么","锁具委托书"}},{q="我该把 Practice Lock 送到哪里？",a="交付地点标记在地图上。",al={"交付地点","送到哪里","送往何处"}},{q="我需要留着委托书吗？",a="需要。完成交易时，你必须随身携带委托书。",al={"需要委托书吗","带上纸条","需要委托书"}},{q="委托书可以转让吗？",a="可以。委托书上写明它可以转让。",al={"可以转让吗","可转让纸条","转交委托书"}},{q="纸条上提到报酬了吗？",a="委托书提到了报酬，但所提供的文本中没有写明金额。",al={"报酬条件","报酬多少","报酬"}}},fp="31,122,17.215.0,27.36.0,37.44.0,27.69.0,25.38.0,30.68.0"}
P.entries["quest:94236"] = {n="工匠文书: Big Bronze Bomb",s="一份可转让的委托书要求交付一枚 Big Bronze Bomb，并注明交付地点和报酬。完成交易时，你必须随身携带委托书。",h="一份可转让的委托书要求交付一枚 Big Bronze Bomb，并注明交付地点和报酬。完成交易时，你必须随身携带委托书。",kw={"big bronze bomb","炸弹","工匠文书","交付","报酬","可转让的委托书"},sec={{t="书面委托",b="这张褪色的纸条请你带来一枚 Big Bronze Bomb。上面还注明了交付地点和报酬，并说明委托书可以转交他人。交易时请随身携带。"}},faq={{q="委托书要求交付什么物品？",a="委托书要求交付一枚 Big Bronze Bomb。",al={"所需物品","big bronze bomb 委托书"}},{q="我该把炸弹交到哪里？",a="委托书指向地图上标出的交付地点。",al={"交付地点","交到哪里"}},{q="委托人提供什么报酬？",a="委托书上注明了报酬信息。",al={"报酬金额","报酬信息"}},{q="我可以把委托书交给别人吗？",a="可以。纸条上说委托书可以转交他人。",al={"委托书是否可转让","转交纸条"}},{q="交易时需要委托书吗？",a="需要。完成交易时，委托书必须在你身上。",al={"完成交易是否需要委托书","是否必须携带纸条"}}},fp="33,141,17.181.0,27.38.0,28.60.0,29.44.0,36.44.0,36.70.0"}
P.entries["quest:94238"] = {n="工匠文书: Heavy Leather Ball",s="一份可转让的工匠文书要索取一个重皮球，并注明了顾客。Sos'mol盼球心切，这趟交付对他意义非凡。",h="一份可转让的工匠文书要索取一个重皮球，并注明了顾客。Sos'mol盼球心切，这趟交付对他意义非凡。",kw={"工匠文书","交付","重皮球","食人魔","付款","sos'mol","可转让"},sec={{t="顾客的委托",b="这张褪色的文书要索取一个重皮球，并写明了交付和付款的详情。你带着文书前来完成交易。你到达时，Sos'mol正哼着一支跑调的小曲，抱怨无聊。他还在哼，只是声音小了些，看起来有点不好意思。"},{t="Sos'mol的喜悦",b="Sos'mol问你有没有把球带来。拿到球时，他眼里涌出泪水，称这是食人魔一生中最快乐的一天。这个球对他来说，比他原本想要的其他东西都重要，不过他已经记不起那是什么了。"}},faq={{q="文书索取什么？",a="文书要索取一个重皮球，并附有交付和付款的详情。",al={"重皮球文书","文书要什么物品"}},{q="顾客是谁？",a="交付单上注明的顾客是Sos'mol。",al={"谁想要球","sos'mol文书"}},{q="Sos'mol为什么想要球？",a="Sos'mol说，这个球是他一直梦寐以求的东西。",al={"为什么要球","sos'mol想要球"}},{q="我到达时Sos'mol在做什么？",a="Sos'mol一直在哼一支跑调的歌，唱着无聊；你走近时，他仍在哼，只是声音小了些。",al={"sos'mol在做什么","sos'mol唱歌"}},{q="别人也能使用这份文书吗？",a="可以。文书上说它可以转让。",al={"可转让的文书","能把文书转让吗"}}},fp="36,151,20.284.0,17.252.1,27.88.0,20.46.0,29.60.0,36.99.0,30.44.0"}
P.entries["quest:94242"] = {n="工匠文书: Pilferer's Gloves",s="一份可转让的委托书要求交付一双 Pilferer's Gloves，并注明了交付和付款详情。完成交易时必须持有这份委托书。",h="一份可转让的委托书要求交付一双 Pilferer's Gloves，并注明了交付和付款详情。完成交易时必须持有这份委托书。",kw={"工匠文书","交付","手套","付款","pilferer's gloves","可转让","委托书"},sec={{t="书面委托",b="一张褪色的纸条要求交付一双 Pilferer's Gloves。上面写明了交付地点和付款安排，这份委托书可以转交他人。"},{t="完成交易",b="把所需的手套送到地图上标记的地点时，你必须随身携带这份委托书。纸条将交付和付款详情与这份书面委托联系在一起。"}},faq={{q="委托书要求什么？",a="委托书要求交付一双 Pilferer's Gloves。",al={"pilferer's gloves 委托书","手套订单","所需物品"}},{q="手套要送到哪里？",a="交付地点已在你的地图上标出。",al={"交付地点","手套送往何处","标记地点"}},{q="完成交易需要什么？",a="完成交易时，你必须持有这份委托书。",al={"需要委托书","委托书要求","完成交易"}},{q="委托书上写了付款方式吗？",a="委托书上有付款信息。",al={"付款详情","付款金额","手套付款"}},{q="别人可以携带这份委托书吗？",a="可以。这份委托书可以转交他人。",al={"可转让的委托书","转交纸条","可以转交吗"}}},fp="35,141,15.156.0,15.156.0,27.48.0,30.44.0,43.65.0,36.44.0,32.30.0"}
P.entries["quest:94243"] = {n="Craftsman's Writ: Heavy Quiver",s="一张褪色的委托书要求交付一只重型箭袋，并注明了交付和付款详情。委托书可以转交，但完成交易时必须随身携带。",h="一张褪色的委托书要求交付一只重型箭袋，并注明了交付和付款详情。委托书可以转交，但完成交易时必须随身携带。",kw={"工匠委托书","交付","重型箭袋","付款","箭袋","可转交"},sec={{t="委托书",b="纸条要求你取得指定物品，并将其送到地图上标记的位置。交易时必须随身携带委托书。"}},faq={{q="委托书要求什么？",a="顾客要求一只重型箭袋。",al={"重型箭袋委托","需要什么物品"}},{q="要送到哪里？",a="交付地点已在地图上标出。",al={"交付地点","箭袋送到哪里"}},{q="我需要随身携带委托书吗？",a="是的。完成交易时必须随身携带委托书。",al={"是否需要委托书","必须携带委托书"}},{q="我能把委托书交给别人吗？",a="可以。纸条上说委托书可以转交。",al={"转交委托书","别人能用吗"}},{q="委托书提到付款了吗？",a="纸条中包含付款信息，但没有写明金额。",al={"付款金额","箭袋付款"}}},fp="30,121,8.140.0,27.39.0,22.41.0,28.54.0,37.49.0,30.56.0"}
P.entries["quest:94245"] = {n="工匠文书: Barbaric Gloves",s="一份可转让的委托书请求交付 Barbaric Gloves，并注明了交付地点和付款详情。完成交易时，你必须随身携带这份委托书。",h="一份可转让的委托书请求交付 Barbaric Gloves，并注明了交付地点和付款详情。完成交易时，你必须随身携带这份委托书。",kw={"barbaric gloves","工匠文书","交付","手套","付款","可转让","委托书"},sec={{t="顾客的请求",b="一位顾客通过这份褪色的委托书请求一副 Barbaric Gloves。委托书注明了交付地点和付款详情，而且可以转交他人。交付所请求的物品时，你必须持有这份委托书。"}},faq={{q="委托书请求交付什么？",a="顾客请求一副 Barbaric Gloves。",al={"barbaric gloves 委托书","什么手套","工匠委托书"}},{q="我该把手套送到哪里？",a="交付地点已标记在你的地图上。",al={"交付地点","手套送到哪里"}},{q="我需要随身携带委托书吗？",a="需要。完成交易时，你必须持有这份委托书。",al={"需要随身携带委托书","需要委托书"}},{q="这份委托书可以转交吗？",a="可以。委托书上说它可以转交他人。",al={"转交委托书"}},{q="委托书上关于付款写了什么？",a="委托书上注明了付款信息。",al={"付款详情","付款金额"}}},fp="33,151,20.237.0,27.50.0,30.44.0,28.70.0,28.44.0,37.44.0"}
P.entries["quest:94246"] = {n="工匠文书: Red Whelp Gloves",s="一份可转让的委托书，要求交付一双 Red Whelp Gloves，并注明了交付地点和报酬。",h="一份可转让的委托书，要求交付一双 Red Whelp Gloves，并注明了交付地点和报酬。",kw={"工匠文书","交付","报酬","red whelp gloves","可转让","委托书"},sec={{t="书面委托",b="一张褪色的字条要求交付一双 Red Whelp Gloves，并注明了交付地点和报酬。你必须持有委托书才能完成交易。"}},faq={{q="委托书要求交付什么？",a="委托书要求交付一双 Red Whelp Gloves。",al={"red whelp gloves委托书","要求的物品"}},{q="我该把手套送到哪里？",a="委托书提供了一个标记在你地图上的交付地点。",al={"交付地点","手套送到哪里"}},{q="完成交易需要什么？",a="你必须持有委托书才能完成交易。",al={"需要什么","委托书要求"}},{q="委托书可以转让吗？",a="可以。字条上说这份委托书可以转让。",al={"可转让的委托书","别人能接手吗"}},{q="委托书提到报酬了吗？",a="提到了。委托书中包含报酬信息。",al={"报酬金额","手套的报酬"}}},fp="34,114,17.145.0,27.47.0,30.57.0,40.62.0,28.44.0,30.49.0"}
P.entries["quest:94249"] = {n="工匠文书: Azure Silk Hood",s="一份褪色的工匠文书要求交付一件 Azure Silk Hood，并注明交付与付款条件。完成交易时，你必须持有这份委托书。",h="一份褪色的工匠文书要求交付一件 Azure Silk Hood，并注明交付与付款条件。完成交易时，你必须持有这份委托书。",kw={"azure silk hood","工匠文书","交付","付款","丝绸兜帽","可转让","委托书"},sec={{t="书面条款",b="这张便笺用褪色的墨水写成，只列出一件物品：Azure Silk Hood。便笺还注明了交付地点和付款方式。这份委托书可以转交给他人，但完成交易时你必须随身携带。"}},faq={{q="委托书要求什么？",a="客户要求一件 Azure Silk Hood。",al={"azure silk hood委托书","需要什么物品","工匠文书"}},{q="我该把兜帽送到哪里？",a="交付地点已在你的地图上标出。",al={"交付地点","送到哪里","标记的地点"}},{q="完成交易需要什么？",a="你必须持有指定物品和委托书。",al={"需要带什么","需要委托书吗","完成交易"}},{q="委托书说明了付款方式吗？",a="便笺中包含付款信息，但此处没有注明金额。",al={"付款金额","付款条件","我能得到什么"}},{q="别人可以携带这份委托书吗？",a="可以。这份委托书注明可转让。",al={"可转让的委托书","可以转交吗","谁可以持有"}}},fp="33,144,17.225.0,27.42.0,28.44.0,35.60.0,36.91.0,32.40.0"}
P.entries["quest:94250"] = {n="工匠文书: Small Silk Pack",s="一份可转让的委托书要求交付一个 Small Silk Pack，并说明了交付方式和报酬。完成交易时必须持有这份委托书。",h="一份可转让的委托书要求交付一个 Small Silk Pack，并说明了交付方式和报酬。完成交易时必须持有这份委托书。",kw={"工匠文书","交付","报酬","丝绸","small silk pack","可转让","委托书"},sec={{t="委托书",b="一位顾客留下了一张褪色的便条，向你索要一个 Small Silk Pack。便条上写明了交付地点和报酬方式。这份委托书可以转交他人，但完成交易时你必须持有它。"}},faq={{q="委托书要什么？",a="顾客要一个 Small Silk Pack。",al={"small silk pack 委托书","索要什么物品","丝绸包裹需求"}},{q="我该把包裹送到哪里？",a="委托书上写有交付信息，地图上也标出了地点。",al={"交付地点","送到哪里","交货地点在哪里"}},{q="报酬如何结算？",a="委托书上写有报酬信息。",al={"能拿到多少报酬","报酬详情","报酬是什么"}},{q="我能把委托书转交给别人吗？",a="可以。便条上说这份委托书可以转交他人。",al={"委托书能否转让","转交委托书","转交给别人"}},{q="完成交易时需要委托书吗？",a="需要。完成交易时，你必须持有这份委托书。",al={"交付时需要委托书吗","必须留着便条吗","需要委托书"}}},fp="33,141,8.220.0,27.42.0,28.79.0,23.44.0,40.44.0,44.70.0"}
P.entries["quest:94252"] = {n="工匠文书: Red Woolen Boots",s="一份可转让的委托书要求交付一双 Red Woolen Boots，并注明交付地点和报酬信息。完成交易时，你必须持有这份委托书。",h="一份可转让的委托书要求交付一双 Red Woolen Boots，并注明交付地点和报酬信息。完成交易时，你必须持有这份委托书。",kw={"靴子","工匠文书","交付","报酬","red woolen boots","可转让","委托书"},sec={{t="书面委托",b="一张褪色的纸条请你提供一双 Red Woolen Boots。上面注明了交付地点和报酬安排。委托书可以转让，但完成交易时你必须持有它。"}},faq={{q="委托书要求提供什么？",a="委托书要求提供一双 Red Woolen Boots。",al={"红靴委托书","要求提供什么靴子"}},{q="靴子要交到哪里？",a="委托书注明了交付信息，地图上会显示标记地点。",al={"交付地点","红靴交到哪里"}},{q="报酬如何安排？",a="委托书上注明了报酬信息。",al={"靴子的报酬","报酬是多少"}},{q="我能转让这份委托书吗？",a="可以。纸条上说这份委托书可以转让。",al={"可转让委托书","别人能代为携带吗"}},{q="完成交易时需要持有委托书吗？",a="需要。完成交易时，你必须持有这份委托书。",al={"需要随身携带委托书吗","完成交易"}}},fp="34,143,19.213.0,27.47.0,29.81.0,24.44.0,25.44.0,44.75.0"}
P.entries["quest:94253"] = {n="Craftsman's Writ: Colorful Kilt",s="一位顾客通过可转让的委托书订制多彩褶裙，打算穿上它混入祖尔格拉布。",h="一位顾客通过可转让的委托书订制多彩褶裙，打算穿上它混入祖尔格拉布。",kw={"多彩褶裙","工匠委托书","交付","伪装","祭仪师","祖尔格拉布"},sec={{t="伪装",b="委托书要求你提供一条多彩褶裙，并送到标记的地点。顾客打算穿得像祖尔格拉布的祭仪师一样，偷偷穿过大门，并称这条褶裙很适合伪装。"}},faq={{q="委托书要求提供什么？",a="委托书要求提供一条多彩褶裙，并送到地图上标记的地点。",al={"多彩褶裙委托书","所需物品"}},{q="顾客为什么想要多彩褶裙？",a="顾客打算穿得像祖尔格拉布的祭仪师一样，偷偷潜入其中，并称这条褶裙会派上用场。",al={"褶裙用途","褶裙伪装"}},{q="我可以转让这份委托书吗？",a="可以。委托书上写明它可以转让。",al={"转让委托书","转交委托书"}},{q="我该把褶裙送到哪里？",a="委托书指示你前往地图上标记的地点。",al={"交付地点","送到哪里"}}},fp="31,121,10.206.0,27.88.0,43.104.0,25.38.0,32.56.0"}
P.entries["quest:943"] = {n="健忘的勘察员",s="这个任务标志着勘察员雷姆塔维尔在黑海岸的发掘工作所引发的搜寻行动的最后一章。米奈希尔港的考古学家弗拉冈特试图将雷姆塔维尔的发现与他自己的化石以及丢失的雷鲁之石结合起来，以解开古代遗物隐藏的力量。",h="这个任务标志着勘察员雷姆塔维尔在黑海岸的发掘工作所引发的搜寻行动的最后一章。米奈希尔港的考古学家弗拉冈特试图将雷姆塔维尔的发现与他自己的化石以及丢失的雷鲁之石结合起来，以解开古代遗物隐藏的力量。",kw={"黑海岸","探险者协会","弗拉冈特","化石","米奈希尔","雷姆塔维尔","雷鲁之石","湿地","维尔加"},ang={["faction:Alliance"]="联盟的信使和冒险者经常往来于暗夜精灵领地黑海岸和米奈希尔港周围的矮人定居点之间，跨越海洋的阻隔。",["race:Dwarf"]="这个任务链体现了探险者协会的核心使命，即连接跨越大陆的偏远挖掘点，以拼凑出矮人的遗产和泰坦的奥秘。"},sec={{t="跨大陆考古学",b="最初在黑海岸北部协助心不在焉的勘察员雷姆塔维尔的护送任务，最终演变成了横跨无尽之海、前往湿地的沼泽地的旅程。考古学家弗拉冈特原本的化石由勘察员维尔加在他位于湿地的发掘场保管。考古学家弗拉冈特在审查收集到的发现时意识到，要解开化石中蕴含的神秘力量，需要一件关键文物：雷鲁之石。"},{t="遗失在沼泽中",b="在弗拉冈特与维尔加会合之前，一群斑点迅猛龙在路上伏击了他的商队，并吞下了雷鲁之石。为了拼凑出这个谜团，弗拉冈特需要一名冒险者去猎杀这些掠食野兽，找回被吞下的石头，并从维尔加的营地取回最初的化石。随着化石和关键物品的集齐，这两位矮人研究员希望能够揭开这些遗物的真正起源和力量。"}},faq={{q="为什么黑海岸的任务会以湿地作为终点？",a="探险者协会在卡利姆多和东部王国都保持着活跃的运作。首席考古学家杜瑟·灰须将雷姆塔维尔的化石从黑海岸跨海送到了湿地的考古学家弗拉冈特手中，通过共享研究成果将这两个挖掘点联系在了一起。",al={"为什么黑海岸任务会在湿地结束","米奈希尔港的联系","为什么送到湿地"}},{q="雷鲁之石是什么？",a="雷鲁之石是考古学家弗拉冈特找回的一件古代遗物。他认为它是一种密码或催化剂，能够解开保存在黑海岸和湿地发掘出的化石中的沉睡魔法秘密。",al={"雷鲁之石","雷鲁之石是什么","雷鲁遗物"}},{q="谁是考古学家弗拉冈特？",a="考古学家弗拉冈特是矮人探险者协会的一名成员，常驻于米奈希尔港。他研究从周边挖掘点找回的古代遗物，并希望解开勘察员雷姆塔维尔和维尔加所发现的化石中隐藏的力量。",al={"弗拉冈特","谁是弗拉冈特"}},{q="谁持有最初的化石？",a="勘察员维尔加在他位于湿地的挖掘场持有弗拉冈特的原始化石。你已经将雷姆塔维尔在黑海岸发现的化石交付给了弗拉冈特。",al={"化石在哪里","谁有雷姆塔维尔的化石","维尔加的化石"}},{q="为什么迅猛龙会有雷鲁之石？",a="在前往与勘察员维尔加商讨的湿地路上，弗拉冈特遭到了斑点迅猛龙的伏击。在混乱的袭击中，其中一只掠食野兽将石头整颗吞了下去。",al={"迅猛龙吞下的遗物","为什么迅猛龙有石头"}},{q="矮人们期望化石能起到什么作用？",a="弗拉冈特相信化石中蕴含着隐藏的力量和过去的秘密，而雷鲁之石就是解开它们的关键。",al={"化石的力量","化石有什么作用"}}},fp="28,229,29.366.0,19.376.1,48.246.0,26.221.0,31.241.0,28.162.0,38.172.0,45.133.0"}
P.entries["quest:94369"] = {n="The Fate of Zephras",s="你将泽风岛面临的危险带给瓦拉纳尔的Talaanis 影歌。守护结界已失效，泽风岛暴露在奥拉基尔面前，泽风岛的居民必须决定如何保护家园。",h="你将泽风岛面临的危险带给瓦拉纳尔的Talaanis 影歌。守护结界已失效，泽风岛暴露在奥拉基尔面前，泽风岛的居民必须决定如何保护家园。",kw={"奥拉基尔","艾拉德林","洛苏娜","阿基尔神殿","塔拉尼斯·影歌","瓦拉纳尔","守护结界","风领主","泽风岛"},sec={{t="向Talaanis传达警讯",b="你告诉Talaanis阿基尔神殿上方发生的事，并转达Elaadrin离开泽风岛的计划。影歌大长老需要了解危险，以及你前往艾泽拉斯执行任务的目的；泽风岛的居民则在寻找拯救家园的方法。"},{t="所剩之事",b="Talaanis思索着这个消息。Lorthuna已经不在了，邪教失去了领袖。泽风岛尚未遭到入侵，不过奥拉基尔可能会在数年或数十年后将目光转向这座岛。恐惧与值得庆贺之事如今并存。"}},faq={{q="我该和谁交谈？",a="你在瓦拉纳尔与塔拉尼斯·影歌交谈。",al={"该和谁交谈","塔拉尼斯","该向谁报告"}},{q="我该告诉塔拉尼斯什么？",a="你告诉塔拉尼斯阿基尔神殿上方发生的事，以及艾拉德林离开泽风岛的计划。",al={"神殿发生了什么","该报告什么","阿基尔神殿的消息"}},{q="泽风岛的居民为什么害怕奥拉基尔？",a="隐藏泽风岛的守护结界已经失效，奥拉基尔可能会选择在居民身处他的领地时发动攻击。",al={"为何害怕奥拉基尔","风领主的威胁","奥拉基尔的威胁"}},{q="影歌大长老需要知道什么？",a="他需要了解危险，以及泽风岛的居民打算在前往艾泽拉斯执行任务时做什么。",al={"塔拉尼斯需要知道什么","大长老的消息","前往艾泽拉斯的意图"}}},fp="19,183,22.251.0,12.225.1,20.47.0,24.102.0,48.104.0,45.122.0"}
P.entries["quest:94373"] = {n="Call of Earth",s="大地的召唤是在安威玛尔由 Teo Hammerstorm 监督的一项神圣试炼，旨在考验入门者的耐心和石头的韧性。申请者必须面对南方的冰鬃巨魔，夺回他们的熊挂件，才能获得大地之油。",h="大地的召唤是在安威玛尔由 Teo Hammerstorm 监督的一项神圣试炼，旨在考验入门者的耐心和石头的韧性。申请者必须面对南方的冰鬃巨魔，夺回他们的熊挂件，才能获得大地之油。",kw={"安威玛尔","大地的召唤","寒脊山谷","大地图腾","冰鬃","冰鬃熊挂件","冰爪熊","油","萨满","提奥·锤风"},ang={["class:Shaman"]="大地的召唤标志着与石头和泥土之灵交流的早期入门阶段，最终会制成大地之油。",["faction:Alliance"]="这项仪式考验刚入门的保卫者，让他们对抗盘踞在安威玛尔南部洞穴中的冰鬃巨魔。",["race:Dwarf"]="这项试炼在安威玛尔附近的寒脊山谷提供，将矮人的坚毅和高山遗产与大地本身永恒的耐心联系在一起。"},sec={{t="石头的智慧",b="在寒脊山谷的安威玛尔，导师 Teo Hammerstorm 注视着准备踏上崎岖大地之路的入门者。Teo 将大地视为一种坚固且不可动摇的基础，引导年轻的流浪者聆听高山的智慧。他警告说，虽然石头是坚固的盾牌，但它的恩惠不会轻易给予，只有展现出真正的毅力和深深的敬意，才能分享大地的秘密。"},{t="大兽穴的试炼",b="为了证明自己已经准备就绪，入门者必须面对潜伏在南方洞穴里的冰鬃巨魔。这些巨魔用在该冰冻高地上游荡的凶猛冰爪熊的皮毛制作粗糙的挂件。从巨魔的大兽穴中收回两个这样的熊挂件，便是申请者拥有元素之灵所期望的坚定决心和勇气的有力证明。"},{t="大地之油",b="在将挂件交给 Teo Hammerstorm 后，这位长者会称赞入门者的耐心——这是大地最优秀的品质，它比崩塌的山峰和雕琢的河谷更为长久。为了认可这份已证明的敬意，Teo 开始准备大地之油，这是使入门者能够感知并走上元素真实之路的重要催化剂。"}},faq={{q="谁提供了大地的召唤这个任务？",a="特奥·锤风 是位于寒脊山谷安威玛尔的一位长者向导，他提供了这项试炼。他指导年轻的入门者学习石头的之道，并要求他们在元素之灵面前证明自己的决心。",al={"谁提供大地的召唤","大地的召唤任务发布者","泰奥·锤暴任务"}},{q="特奥·锤风 要求你做什么？",a="你必须冒险前往安威玛尔南部的洞穴，那里住着冰鬃巨魔，你需要回收两个冰鬃熊挂件，那是巨魔用冰爪熊制成的。将它们交给 特奥·锤风 即可完成试炼。",al={"大地的召唤目标","大地的召唤需要什么","冰鬃挂件任务"}},{q="在哪里可以找到冰鬃熊挂件？",a="这些挂件由生活在安威玛尔以南一个洞穴里的冰鬃巨魔携带。这些护身符是用当地的冰爪熊制成的，并由居住在大兽穴里的巨魔佩戴。",al={"哪里有冰鬃熊挂件","如何获得冰鬃熊挂件","安威玛尔冰鬃洞穴"}},{q="完成任务后，特奥·锤风 会准备什么奖励？",a="“油”是一种由精神导师准备的仪式性混合物或药剂，旨在使修行者与元素之灵相协调。完成这项试炼后，特奥 会制作大地之油，让你能够走上大地的真实之路。",al={"什么是油","矮人大地之油","特奥·锤风制作什么"}},{q="为什么入门者必须在这项试炼中面对冰鬃巨魔？",a="与冰鬃巨魔对峙体现了与大地交流所需的身体毅力和精神韧性。通过从敌对巨魔的洞穴中夺取熊挂件，入门者证明了自己配得上大山的永恒恩惠。",al={"为什么要杀冰鬃巨魔","为什么是冰鬃挂件"}},{q="特奥·锤风 教导了关于大地本质的什么道理？",a="特奥 教导说，耐心是大地最伟大的美德，并指出当高山崩塌、河流缓慢切割出河谷时，大地依然长存。他强调石头会保护那些尊重它的人，但警告说，即使是基岩如果受到轻视也会发生位移。",al={"特奥·锤风大地美德","高山的智慧"}}},fp="13,171,19.289.0,26.279.0,17.273.1,35.180.0,40.189.0,46.135.0,57.139.0,60.162.0,58.204.0"}
P.entries["quest:94374"] = {n="大地的召唤",s="“大地之呼”是一项神圣的萨满仪式，它将初学者的凡人之魂与世界不朽的根基相连。在僻静山中的灵石旁，通过饮下名为大地萨普塔的幻象药剂，寻求者能在冰雪与岩石间学会谦卑、耐心和对元素的感知。",h="“大地之呼”是一项神圣的萨满仪式，它将初学者的凡人之魂与世界不朽的根基相连。在僻静山中的灵石旁，通过饮下名为大地萨普塔的幻象药剂，寻求者能在冰雪与岩石间学会谦卑、耐心和对元素的感知。",kw={"大地的召唤","丹莫罗","大地萨普塔","元素仪式","秘道","萨普塔","萨满","灵石"},ang={["class:Shaman"]="这项仪式代表了萨满必不可少的沟通，通过萨普塔的仪式用酒，将灵魂与岩石结合，并赋予了超越凡人感知的视野。",["faction:Alliance"]="在积雪的山崖间出现元素仪式，显示出萨满传统正在联盟的土地上扎根。",["race:Dwarf"]="在冰封的山峰间，用矮人粗犷的语调诉说着这神圣的交流，将与大地的沟通与丹莫罗的雪山之巅直接联系了起来。"},sec={{t="幻象之酒",b="“大地之呼”是一项关于精神调和的神圣试炼，要求初学者在孤立的山间神龛饮用名为大地萨普塔的附魔药剂。萨普塔由古老的元素魔法锻造而成，它能将饮用者的灵魂与世界的基岩结合，赋予凡人之眼以罕见的力量，去洞察那些常人视力所无法触及的元素之灵与细微流向。由于其效力强劲，这种药剂必须在指定的圣地饮用，以确保灵魂与岩石间的联结能够安全建立。"},{t="雪中的灵石",b="在被积雪覆盖的高山上，沿着一条隐秘的秘道走到尽头，便伫立着灵石。初学者们踏上这段充满苦寒与冰雪的旅程，在古老的岩石前谦卑地伫立。他们怀着毫无骄矜之心，饮下萨普塔，便会发现即使是在最严酷的冬季峭壁上，大地依然以其生命力接纳了他们。山脉成为了不朽体魄的基石，而广袤沉稳的平原则教会了他们耐心这种静谧的力量。"},{t="力量与宁静",b="与岩石沟通是通往精神探索之路的基础仪式。与风、火或咆哮的水流那般躁动不安不同，大地教会人们的是不动如山的纪律与沉稳的韧性。为了通过这项仪式，寻求者必须汲取大地静谧的本质，为应对世界上那些更为狂暴的元素所带来的冲突与混沌二元性，磨砺自己的身心。"}},faq={{q="什么是大地萨普塔？",a="大地萨普塔是一种以魔法制作的强效神秘药剂，旨在将修行者的灵魂直接与元素相连。它并非为意志薄弱者所准备，因为饮用它会刺破凡人的视觉，揭示出常人无法感知的精神与元素真相。",al={"什么是萨普塔","大地萨普塔背景故事","萨普塔的作用"}},{q="在哪里饮用萨普塔？",a="这种药剂必须在特定的圣地饮用。在此仪式中，修行者需要向北沿着秘道登山，去寻找隐藏在峭壁之中的古老灵石。",al={"在哪里饮用萨普塔","灵石位置","灵石在哪里"}},{q="“大地之呼”仪式的目的是什么？",a="“大地之呼”是一项关于沟通与谦卑的基础试炼。通过在灵石旁饮下萨普塔，初学者学会了从山脉中汲取力量，从平原中学会耐心，并在面对更狂暴的元素之前，将自己的凡人之魂与充满生机的世界相调和。",al={"为什么要进行这个任务","大地之呼的含义","大地之呼背景故事"}},{q="谁懂得如何酿造大地萨普塔？",a="只有少数被选中的萨满祭司才拥有酿造萨普塔所需的知识与精神准备。它的配方受到严密保护并被尊崇备至，因为这种药剂将凡人的意识直接与原始力量连接在一起。",al={"谁知道萨普塔的配方","谁都能制作萨普塔吗"}},{q="大地元素与其他元素有何不同？",a="当其他元素力量在暴虐的不安中冲突、燃烧、咆哮时，大地元素代表的是坚定、静止、耐心和不可动摇的根基。初学者必须先在岩石面前学会谦卑，才能去面对其他元素那多变的双重本质。",al={"大地与其他元素的区别","大地与火、水、风的比较"}},{q="这项仪式是在什么环境中进行的？",a="这项任务发生在寒冷积雪的高山之巅，初学者沿着蜿蜒在冰雪与岩石间的秘道前行，不顾凛冽的寒霜，与大地的灵魂进行交流。",al={"大地之呼的场景设定","冰封之地的大地任务"}}},fp="13,213,21.300.0,28.300.0,22.330.0,20.259.0,33.174.0,46.264.0,34.232.0,61.242.0,39.178.0"}
P.entries["quest:94375"] = {n="大地的召唤",s="大地的召唤是丹莫罗冰雪覆盖的土地上，年轻萨满必须经历的元素试炼。通过与当地的大地之灵沟通，受试者将获得一块粗石英，并将其带到安威玛尔的特奥·锤风那里。这块普通的石头证明了他们的沟通成果，并作为他们大地图腾的核心。",h="大地的召唤是丹莫罗冰雪覆盖的土地上，年轻萨满必须经历的元素试炼。通过与当地的大地之灵沟通，受试者将获得一块粗石英，并将其带到安威玛尔的特奥·锤风那里。这块普通的石头证明了他们的沟通成果，并作为他们大地图腾的核心。",kw={"安威玛尔","大地的召唤","寒脊山谷","丹莫罗","大地图腾","粗石英","萨满","特奥·锤风","图腾"},ang={["class:Shaman"]="与大地之灵沟通并获得大地图腾，是每一位萨满学徒必经的基础试炼。",["faction:Alliance"]="在安威玛尔周围进行的萨满仪式，标志着元素灵媒在铁炉堡领地内的影响力和引导作用日益增强。",["race:Dwarf"]="矮人与石头和山脉的联系源远流长，在丹莫罗直接与大地之灵沟通，将他们祖传的石匠工艺与萨满之路桥接在了一起。"},sec={{t="低语之石",b="大地的召唤标志着受试者在丹莫罗迈出了通往萨满精神之路的第一步。在冰封的山峰深处，求道者必须寻找大地之灵并聆听它的教诲。这一试炼需要谦卑：大地之灵只会赠予一块粗石英，这块看似平凡的鹅卵石将成为大地图腾跳动的心脏。它提醒求道者，真正的持久并非取决于规模的大小，而是取决于耐心、力量和坚定的决心。"},{t="山的恩赐",b="回到安威玛尔并交出石头后，特奥·锤风会评估受试者的资格。作为一名工匠和向导，特奥需要确凿的证据来证明山灵已经认可了求道者。如果没有粗石英，受试者将无法通过试炼；若有此物，特奥便会将这块原石塑造成大地图腾，将年轻的萨满与大地根基永恒的力量结合在一起。"}},faq={{q="粗石英有什么用？",a="粗石英是由大地元素之灵赐予的，作为沟通的证明。虽然它看起来只是一块普通的鹅卵石，但却是制作大地图腾必不可少的核心。",al={"粗石英用途","什么是粗石英","为什么需要粗石英"}},{q="特奥·锤风是谁？",a="特奥·锤风是位于丹莫罗安威玛尔的一位导师。他负责考验萨满学徒，要求他们在制作神圣图腾前必须先证明自己与元素进行了沟通。",al={"谁是特奥·锤风","特奥·锤风位置","特奥在哪里"}},{q="什么是大地的召唤？",a="大地的召唤是年轻萨满为了寻求与大地之灵的沟通、展示耐心与力量并获得他们第一个大地图腾而进行的神圣试炼。",al={"大地的召唤任务线","什么是大地的召唤","大地图腾任务"}},{q="大地之灵向受试者提出了什么要求？",a="大地之灵要求受试者保持坚强、耐心和寻求智慧。它教导人们，即使是最微小的事物也能比其他事物存续更久，真正的力量源于与大地的相互尊重。",al={"大地之灵的教诲","大地之灵的要求","萨满大地哲学"}},{q="安威玛尔位于哪里？",a="安威玛尔是位于丹莫罗寒脊山谷中的矮人定居点。它是年轻矮人受试者进行训练并与周围山脉沟通的集结地。",al={"什么是安威玛尔","安威玛尔背景","大地的召唤发生地点"}},{q="为什么大地图腾很重要？",a="图腾是萨满与元素之灵之间的神圣媒介。大地图腾将持有者的意志与山脉稳固的力量和韧性连接在一起。",al={"图腾的重要性","萨满图腾背景","大地图腾的作用"}}},fp="13,190,20.342.0,20.329.0,29.111.0,23.159.0,26.107.0,47.186.0,26.129.0,33.140.0"}
P.entries["quest:944"] = {n="主宰之剑",s="这个任务派遣联盟冒险者穿过黑海岸向南，代表知识古树奥努去侦察阴森的主宰之剑。目标是调查邪恶的暮光之锤教派是否已经渗透进了那个陨落的上古恐怖存在的遗骸中。",h="这个任务派遣联盟冒险者穿过黑海岸向南，代表知识古树奥努去侦察阴森的主宰之剑。目标是调查邪恶的暮光之锤教派是否已经渗透进了那个陨落的上古恐怖存在的遗骸中。",kw={"黑海岸","主宰之剑","古老领主","奥努","占卜之水","占卜碗","暮光之锤"},ang={["class:Druid"]="德鲁伊们响应奥努的呼唤，旨在了解深埋于地底的古老休眠污秽是如何扰乱周边土地及其野生动物的。",["faction:Alliance"]="黑海岸的联盟部队必须阻止暮光之锤唤醒那些可能会淹没卡利姆多北部苦苦挣扎的定居点的远古恐怖。",["race:NightElf"]="对于暗夜精灵来说，主宰之剑是一个鲜明的提醒，警示着在他们文明出现之前的原始恐怖，看到疯狂的教徒侵犯黑海岸这片神圣的土地是不可容忍的亵渎。"},sec={{t="不安的征兆",b="在调查黑海岸沿岸残留的腐蚀和流离失所的野生动物时，知识古树奥努注意到了一些令人担忧的线索。沿岸的纳迦已经够让人困扰的了，但暮光之锤教派的出现则更为凶兆。这个狂热的教派崇拜的并非普通的黑暗力量，而是那些在远古时代被推翻的世界古老原始领主。"},{t="陨落的领主",b="向南是主宰之剑，这是一处阴森的挖掘点，中心是一头被巨大的石制武器钉住的庞然大物。奥努提供了一瓶占卜之水，并派遣侦察兵进入坑中确认教徒们是否聚集在那里。正如奥努所警告的那样，尽管这头被钉住的巨兽已经死了数个纪元，但它那古老而腐蚀的力量碎片仍然残留在它的骨骸中——这是暮光之锤无法抗拒的战利品。"}},faq={{q="是谁派遣我执行这个任务的？",a="该任务由奥努发布，他是一棵位于黑海岸南部古树之林附近路边的德高望重的知识古树。",al={"任务发布者","谁给予主宰之剑任务","起始非玩家角色"}},{q="什么是主宰之剑？",a="主宰之剑是位于黑海岸南部的一处古老遗迹，数个纪元前，一位恐怖的远古领主在此陨落，其头颅被一把巨大的石制战刃贯穿。它巨大的石化骨骸至今仍深埋在土地之中。",al={"什么是主宰之剑","主宰之剑的背景故事","黑海岸的巨大头骨"}},{q="为什么暮光之锤教派会对这个地点感兴趣？",a="暮光之锤崇拜古老艾泽拉斯的旧日黑暗力量。尽管被钉在战刃上的泰坦般生物早已死去，但它遗骸中仍残留着其原始力量的休眠痕迹与碎片，而这正是教徒们拼命想要掌控的东西。",al={"黑海岸的暮光教派","暮光教徒为什么在这里","暮光之锤与主宰之剑"}},{q="我该如何向奥努复命？",a="你不必亲自走回奥努所在的位置。一旦你探索了主宰之剑的挖掘坑，使用背包里的占卜之水在地上召唤一个占卜碗，这能让你通过魔法直接与奥努交谈。",al={"在哪里交任务","如何使用占卜之水","占卜碗"}},{q="这次侦察任务之后是什么？",a="在你使用占卜碗确认了教徒的行踪后，奥努会立即引导你前往他们的营地，并在任务“暮光营地”中进一步揭露他们的活动细节。",al={"下一个任务","主宰之剑的后续任务"}}},fp="19,162,21.256.0,15.334.0,29.119.0,28.172.0,57.180.0,28.187.0,32.147.0"}
P.entries["quest:94411"] = {n="Meddlesome Mages",s="Meddlesome Mages主要讲述了申达尔高地不断加剧的矛盾，高阶会的学徒们在神圣的巨石阵附近进行非法闯入。当地守护者必须将他们驱逐，以保护维系岛屿的脆弱神秘力量免受鲁莽的奥术干扰。",h="Meddlesome Mages主要讲述了申达尔高地不断加剧的矛盾，高阶会的学徒们在神圣的巨石阵附近进行非法闯入。当地守护者必须将他们驱逐，以保护维系岛屿的脆弱神秘力量免受鲁莽的奥术干扰。",kw={"奥术干预","高阶会","高阶会学徒","多管闲事的法师","申达尔高地","申多雷","巨石阵"},ang={["class:Mage"]="法师们会注意到对鲁莽施法的严厉批评；高阶会的学徒无视维系岛屿的微妙环境平衡，这表明了肆意操纵奥术的危害。"},sec={{t="巨石阵的入侵",b="申达尔高地村庄北部的局势日益紧张，高阶会的学徒们聚集在古老的巨石阵周围。尽管多次被警告不要干扰这些神圣的地方，法师们仍一意孤行地追求他们的奥术利益。当地领导层虽然不愿伤害同为shen'dorei的族人，但已请求外援驱散这些入侵的学徒，以免他们的干扰造成永久性的伤害。"},{t="脆弱的岛屿",b="驱逐高阶会的紧迫性源于维持岛屿的微妙平衡。维系这片土地的神秘力量非常脆弱，使得家园容易受到鲁莽咒语的破坏。对于巨石阵的保卫者来说，高阶会完全无视了他们干预所带来的危险，这意味着哪怕是一个粗心的咒语，也可能破坏岛屿的束缚，给所有居住在那里的人带来毁灭。"}},faq={{q="多管闲事的法师这个任务是关于什么的？",a="多管闲事的法师是一项要求冒险者对抗并驱散高阶会学徒的任务，这些学徒入侵了申达尔高地村庄北部的神圣巨石阵。",al={"什么是多管闲事的法师","多管闲事的法师任务","这个任务是什么"}},{q="高阶会学徒是谁？",a="高阶会是一个法师派系，被当地人称为申多雷兄弟姐妹，他们的学徒无视警告，闯入神圣的土地并进行魔法实验。",al={"高阶会学徒是谁","什么是高阶会","高阶会法师"}},{q="为什么要驱散高阶会学徒？",a="高阶会一再无视远离巨石阵的警告。他们鲁莽的魔法干预威胁到了维系岛屿的脆弱奥术力量，有可能给当地家园带来灾难性的破坏。",al={"为什么要驱散高阶会","为什么要对抗这些学徒","巨石阵的问题"}},{q="高阶会学徒聚集在哪里？",a="对峙发生在申达尔高地内当地村庄北部的巨石阵处。",al={"这个任务在哪里","申达尔高地的位置","村庄北部的巨石阵"}},{q="任务中提到的申多雷是谁？",a="申多雷是任务发布者族人的亲属。尽管内部冲突削弱了他们共同的社区，但当地领导人感到被迫对高阶会采取果断行动以避免灾难。",al={"谁是申多雷","申多雷兄弟姐妹","什么是申多雷"}},{q="法师们对岛屿构成了什么危险？",a="维系岛屿的力量既微妙又脆弱。奥术修行者未经检查的干预可能会破坏这些束缚，从而有可能彻底摧毁岛屿。",al={"有什么危险","岛屿的脆弱力量","岛屿可能会发生什么"}}},fp="16,168,26.347.0,18.259.0,41.133.0,35.191.0,49.195.0,47.100.0,46.196.0,44.133.0"}
P.entries["quest:94413"] = {n="A Magical Affront",s="“魔力之争”是发生在泽弗拉斯（Zephras）的一个任务，重点围绕近期涌现的能量流展开。当地的一个组织试图驾驭并研究这些暴露的奥术能量，而塑风者则认为这些缺口是大地上的创伤，必须予以治愈，这引发了西南森林中的直接冲突。",h="“魔力之争”是发生在泽弗拉斯（Zephras）的一个任务，重点围绕近期涌现的能量流展开。当地的一个组织试图驾驭并研究这些暴露的奥术能量，而塑风者则认为这些缺口是大地上的创伤，必须予以治愈，这引发了西南森林中的直接冲突。",kw={"魔法的冒犯","奥术","能量流","创伤","塑风者","泽弗拉斯"},ang={["class:Druid"]="德鲁伊可能会发现自己陷入了哲学上的矛盾，因为塑风者认为暴露的能量流是自然景观上需要急切治愈的创伤。",["class:Mage"]="对于奥术修行者来说，泽弗拉斯涌现的能量流提供了极其罕见的、直接接触原始神秘能量的机会，因此保护它们具有重要的学术和魔法价值。",["class:Shaman"]="塑风者致力于平息和治愈泽弗拉斯各处的扰动，这使得他们对自然环境的维护工作与驾驭原始魔法流的组织直接产生了冲突。"},sec={{t="现世洋流",b="在泽弗拉斯的地表上，古老的地下原始魔法通道近期冲破了地表。对于当地组织的学者和修行者来说，这种涌现是无价的馈赠。与能量流的直接、有形接触使他们能够前所未有地洞察渗透在该地区的奥术流动，极大地扩展了他们的魔法造诣。"},{t="创伤与纷争",b="并非所有人都将这些暴露的能量视为奇迹。塑风者认为这些缺口是撕裂泽弗拉斯地表的开放性伤口和破坏性的创伤。他们决心治愈受损的大地，因此聚集在破裂点，试图压制或修补暴露的能量流。对于依赖这些原始力量的组织来说，这种干涉构成了无法容忍的威胁，促使他们派遣冒险者前往西南部的森林，将塑风者驱逐出去。"}},faq={{q="塑风者是什么人？",a="塑风者是活跃在泽弗拉斯的一个组织，他们不认为涌现的能量流是原始能量的馈赠，而将其视为大地上不自然的创伤或疤痕，必须予以治愈。他们的行为使他们与试图研究和引导能量流的组织产生了直接对立。",al={"塑风者是谁","什么是塑风者","塑风者 泽弗拉斯"}},{q="为什么组织想要驱逐塑风者？",a="研究泽弗拉斯能量流的组织需要利用它们涌现出的力量来提升其神秘学理解。由于塑风者积极尝试“治愈”并关闭或修补这些能量流，该组织认为他们的行为是一种不可容忍的冒犯，并要求将其驱逐。",al={"为什么要杀塑风者","为什么要与塑风者战斗","塑风者冲突"}},{q="泽弗拉斯的能量流是什么？",a="能量流是贯穿世界的神秘能量通道。在泽弗拉斯，这些通道近期涌现到了地表，暴露出的直接魔法力量渗透在大地上，使奥术修行者获得了前所未有的研究机会。",al={"什么是泽弗拉斯能量流","泽弗拉斯能量流","地表能量流"}},{q="冲突中的能量流位于何处？",a="本任务中提到的冲突能量流位于泽弗拉斯的西南部森林中，塑风者已经聚集在那里，开始关闭或修补暴露的魔法涌流。",al={"能量流森林在哪里","能量流位置","西南部森林"}},{q="为什么塑风者认为能量流是创伤？",a="塑风者认为原始的地下能量突然破土而出，是在泽弗拉斯地表上留下的剧烈创伤。在他们看来，恢复自然平衡需要修补这些撕裂处，这与希望保持缺口开启的奥术施法者直接对立。",al={"为什么塑风者想要治愈能量流","能量流对泽弗拉斯有害吗","治愈创伤"}},{q="泽弗拉斯在这次冲突中有什么意义？",a="泽弗拉斯是这些暴露的能量流涌现的土地。原始魔法力量在其地表的突然出现，使其成为了试图掌握这些奥术能量的人与将其视为需要恢复的不自然缺口的人之间的爆发点。",al={"什么是泽弗拉斯","魔力之争发生在什么地方","泽弗拉斯传说"}}},fp="17,236,17.287.0,16.313.0,24.195.0,51.208.0,33.200.0,39.139.0,51.254.0,53.214.0"}
P.entries["quest:94414"] = {n="The Anchors of Zephras",s="“泽风之锚”是由泽风岛上的Halaan Hawk-Eye所提供的入门任务。Halaan邀请旅行者借用他那远眺的目光，去观察那些系留并守护着这座浮空岛的古老锚柱。尽管从远处看这些高耸的巨石似乎完好无损，但Halaan警告说，风之灵用来维持稳定的魔法已经开始动摇了。",h="“泽风之锚”是由泽风岛上的Halaan...",kw={"锚柱","泽风之锚","哈兰·鹰眼","地脉","天视","风之灵","泽风岛"},ang={["class:Mage"]="Halaan将他敏锐的视力与那些能够汲取泽风岛下方地脉之力的魔法区分开来。",["class:Shaman"]="锚柱直接依赖于风之灵的祝福，这使得它们魔法中的任何不稳定对于寻求维持平衡的萨满祭司而言，都是一个紧迫的元素问题。"},sec={{t="岛屿的系留",b="泽风岛的锚柱是由风之灵所赐予的古老而高耸的巨石。它们深植于岛屿的神秘基座之中，起到固定、稳定和支撑这片陆地悬浮于动荡天空之中的作用。注视着其中任何一座锚柱，便是见证泽风岛得以漂浮的脆弱平衡，而这一切持续依赖于风之灵的眷顾。"},{t="令人不安的变动",b="尽管锚柱在肉眼看来依然巍然屹立且未受损伤，但它们已经变得不再稳定。Halaan Hawk-Eye指出，维持它们运作的魔法和谐最近变得不稳定且前后不一。在没有明显的物理损伤迹象的情况下，这种微妙的衰退引起了守护林地之人的警觉，暗示着威胁岛屿的深层失衡正在发生。"},{t="Halaan的天赋",b="虽然缺乏能够洞察世界彼端的“天视”或引动泽风岛深层地脉的奥术能力，但Halaan拥有一种更单纯、更敏锐的天赋：在极远距离上拥有清晰明锐的视力。通过借出这种视角，他让其他人能够细致地观察远处的锚柱，鼓励新来者在对当下心存感激的同时，也要警惕家园命运的变迁。"}},faq={{q="泽风岛上的锚柱是什么？",a="锚柱是风之灵所赐予的古老神秘建筑。它们结合、锚定并以魔法支撑着泽风岛，使其在周围的世界之上保持稳定。",al={"什么是锚","泽风岛锚柱","什么是锚柱"}},{q="锚柱出了什么问题？",a="虽然锚柱没有显示出明显的物理损伤或外部衰退，但其维持稳定的魔法近期变得不稳定且前后不一，引发了人们对究竟是什么在悄然干扰它们运作的担忧。",al={"为什么锚失效了","锚柱问题","锚发生了什么"}},{q="哈兰·鹰眼是谁？",a="哈兰·鹰眼是一位居住在泽风岛林地中的守护者。他拥有敏锐且深远的天然视力，监视着这片土地的健康状况，并思考着岛屿的神秘福祉。",al={"哈兰的背景","谁是哈兰"}},{q="哈兰的天赋是什么？",a="哈兰的天赋是极其敏锐的长距离视力。与那些挥舞天视以洞察世界之间，或引导地脉能量的神秘主义者不同，哈兰的力量是自然且平凡的，这使他能够以纯净的清晰度感知遥远的地标。",al={"哈兰的天赋","哈兰如何远视"}},{q="什么是天视？",a="天视是泽风岛上某些修行者所拥有的神秘感知力，它使他们能够穿透面纱，直接洞察世界之间，这远超普通人的肉眼视觉。",al={"什么是天视","天视的含义"}},{q="驱动锚柱的魔法来自哪里？",a="锚柱是由风之灵赐予泽风岛的。哈兰说锚柱负责束缚和维持岛屿，但没有解释它们持续力量的来源。",al={"谁制造了锚柱","锚柱的起源"}}},fx={["61bc2f74"]={q="为什么 哈兰·鹰眼 想让你查看锚桩？",a="哈兰·鹰眼 守望着林地，十分关心 泽风岛 的安危。古老的锚桩是风之精灵的馈赠，能束缚并维系这座岛屿，但它们的魔法最近变得不稳定、不规律。尽管锚桩看起来没有受到物理损坏，哈兰 仍愿意与你分享他那远及千里的视野，让你亲眼看看锚桩，了解故土的微妙处境。",al={"哈兰 的动机","为什么要查看锚桩","哈兰 为什么想要这样做"}}},fp="22,192,19.274.0,18.282.0,13.287.0,38.155.0,37.135.0,23.142.0,22.148.0,17.114.0,51.159.0"}
P.entries["quest:94427"] = {n="A Lesson in Divinity",s="你的教团派你前往幽暗城贸易区寻找 Tanis Alderwood。帮助对方，正是通过善行彰显恩典的机会。",h="你的教团派你前往幽暗城贸易区寻找 Tanis Alderwood。帮助对方，正是通过善行彰显恩典的机会。",kw={"神性之道","神性","恩典","乞讨","塔尼斯·桤木","贸易区","幽暗城"},ang={["class:Priest"]="作为一名牧师，你的教团将神性诠释为为善而行善，并说悲剧可能威胁到你生前所坚守的恩典。"},sec={{t="恩典的召唤",b="你的教团教导说，神性意味着为善而行善，而非追求成神。教团说，悲剧让你来到了这里，并让你去幽暗城贸易区寻找 Tanis Alderwood。Tanis 需要帮助，或许能从你的恩典中受益。"},{t="Tanis 的恳求",b="你走近 Tanis 时，对方担心你会伤害他们。Tanis 说自己与你或你的教团无冤无仇，恳求你不要打扰他们。"}},faq={{q="塔尼斯·桤木 是谁？",a="塔尼斯·桤木 是幽暗城贸易区一位需要帮助的人。",al={"塔尼斯","塔尼斯 是谁","贸易区的人"}},{q="我为何被派去找 塔尼斯？",a="你的教团说，塔尼斯 或许能从你的恩典中受益。",al={"为何找 塔尼斯","帮助 塔尼斯","这意味着什么"}},{q="神性对我的教团意味着什么？",a="这意味着为善而行善，而非追求成神。",al={"神性的含义","为善而行善","什么是神性"}},{q="我在哪里能找到 塔尼斯·桤木？",a="塔尼斯·桤木 在幽暗城贸易区。",al={"塔尼斯 的位置","塔尼斯 在哪里","贸易区"}}},fp="20,127,16.244.0,14.156.1,23.66.0,23.60.0,36.88.0,33.60.0"}
P.entries["quest:94434"] = {n="A Lesson in Divinity",s="Tanis Alderwood在幽暗城向你索要新布料。他的妻子正逐渐散架，他希望用绷带把她包起来，撑到药剂师有空为止。",h="Tanis Alderwood在幽暗城向你索要新布料。他的妻子正逐渐散架，他希望用绷带把她包起来，撑到药剂师有空为止。",kw={"神性之课","药剂师","乞丐","黑暗女王","亚麻布","塔尼斯·桤木","幽暗城","妻子"},sec={{t="乞丐的请求",b="Tanis说，药剂师们正忙于黑暗女王的事务。他请你带些亚麻布来，好在等待救助时把妻子包起来。眼下要紧的是她的状况。"}},faq={{q="谁在寻求帮助？",a="塔尼斯·奥德伍德是幽暗城的一名乞丐，他请求你帮助他的妻子。",al={"塔尼斯是谁","塔尼斯·桤木","乞丐"}},{q="塔尼斯的妻子怎么了？",a="塔尼斯说，她真的快散架了，需要用绷带包起来，才能维持住。",al={"妻子散架","他的妻子出了什么事","塔尼斯的妻子"}},{q="药剂师为什么帮不了忙？",a="塔尼斯说，药剂师们正忙于黑暗女王的事务。",al={"药剂师很忙","为什么没有药剂师","黑暗女王的事务"}},{q="塔尼斯需要什么？",a="塔尼斯请你带些新布料给他，好在等待药剂师救助时把妻子包起来。",al={"他需要什么布料","给塔尼斯的亚麻布","帮助乞丐"}}},fp="20,140,15.175.0,23.70.0,31.84.0,32.71.0,21.97.0"}
P.entries["quest:94435"] = {n="A Lesson in Divinity",s="Tanis Alderwood感谢你帮助了他，并称你为朋友。Danitha Morr认为，这个小小的善举能加强被遗忘者与圣光的联系。",h="Tanis Alderwood感谢你帮助了他，并称你为朋友。Danitha Morr认为，这个小小的善举能加强被遗忘者与圣光的联系。",kw={"神性的一课","danitha morr","黑暗女王","被遗忘者","圣光","不信任","象征","tanis alderwood"},ang={["faction:Alliance"]="作为一名联盟旅人，你听Danitha讲述被遗忘者为帮助族人重新兴盛而付出的努力。",["race:Undead"]="作为被遗忘者，你听Danitha号召大家以勇气和正义帮助族人重新兴盛。"},sec={{t="小小的善举",b="Danitha Morr说，你的帮助或许能加强被遗忘者与圣光的联系。她谈到黑暗女王的追随者之间的不信任与阴谋，以及要以勇气和正义面对这种恐惧。她交给你一个象征，指引接下来的路。"}},faq={{q="谁在感谢我？",a="Tanis Alderwood感谢你帮助了他，并说他会永远是你的朋友。",al={"tanis alderwood","tanis是谁","tanis感谢"}},{q="Danitha说我的帮助意味着什么？",a="Danitha说，即使是小小的善举，也能加强被遗忘者与圣光的联系。",al={"为何帮助danitha","小小善举的意义","与圣光的联系"}},{q="Danitha为什么提到不信任？",a="Danitha说，黑暗女王和她麾下的一些人不信任他们，有些人甚至在暗中谋害他们。",al={"被遗忘者不信任","黑暗女王的恐惧","他们为何遭人猜忌"}},{q="Danitha给了我什么？",a="Danitha交给你一个象征，指引接下来的路。",al={"什么象征","danitha的物品","指引未来的象征"}}},fp="20,167,15.256.0,19.89.0,36.95.0,34.107.0,26.47.0"}
P.entries["quest:94436"] = {n="A Lesson in Divinity",s="Danitha Morr请你用生命符记展示牧师的本领。班达里安堡的Deathguard Billmuth前来寻求帮助，想救助一位朋友。",h="Danitha Morr请你用生命符记展示牧师的本领。班达里安堡的Deathguard Billmuth前来寻求帮助，想救助一位朋友。",kw={"神性之课","班达里安堡","达妮莎·莫尔","亡灵卫兵比尔穆斯","被遗忘者","圣光","牧师","生命符记"},ang={["class:Priest"]="身为牧师，Danitha请你用生命符记展示引导圣光的能力。"},sec={{t="求助",b="Billmuth说，牧师们拒绝了他，而他的朋友可能再也找不到其他人帮忙。他并不情愿向你开口，但他需要为被遗忘者寻求援助。生命符记旨在帮助你展示引导圣光的能力，不过拿着它可能会让你感到不适。即使对被遗忘者而言，它的力量也是盟友与指引；他们的诞生与一种与圣光相对的力量息息相关。"}},faq={{q="谁在寻求帮助？",a="班达里安堡的亡灵卫兵比尔穆斯前来为一位朋友寻求帮助。",al={"帮助比尔穆斯","谁需要帮助"}},{q="比尔穆斯为什么要找牧师？",a="比尔穆斯说，牧师们拒绝了他，而你可能是他朋友唯一的希望。",al={"为什么找牧师","牧师拒绝了他"}},{q="生命符记是什么？",a="这是达妮萨·莫尔交给你的一件圣光护符，用来展示你引导圣光的能力。",al={"生命符记","圣光护符"}},{q="为什么拿着生命符记可能会感到疼痛？",a="达妮萨提醒你，这件护符可能会让人感到不适，因为圣光与创造被遗忘者的力量相对。",al={"符记疼痛","圣光伤人"}},{q="亡灵卫兵 比尔穆斯在哪里？",a="亡灵卫兵 比尔穆斯在班达里安堡的楼下。",al={"比尔穆斯位置","班达里安堡"}}},fp="20,173,14.380.0,23.73.0,31.83.0,27.116.0,44.121.0,37.52.0"}
P.entries["quest:94438"] = {n="A Lesson in Divinity",s="Danitha Morr请你前往毒蛛峡谷寻找死亡卫士Falgan。他和一名同伴发现了血色十字军准备袭击布瑞尔的命令，随后两人失散。",h="Danitha Morr请你前往毒蛛峡谷寻找死亡卫士Falgan。他和一名同伴发现了血色十字军准备袭击布瑞尔的命令，随后两人失散。",kw={"神性启蒙","比尔穆斯","布瑞尔","达妮莎·莫尔","死亡卫士法尔甘","血色十字军","生命符记","毒蛛峡谷"},sec={{t="Falgan的归来",b="Falgan奉命与Billmuth一同前往毒蛛峡谷侦察血色十字军的动向。他说，他们发现血色十字军正计划发动某种袭击，并问你是否愿意继续帮助被遗忘者。"}},faq={{q="是谁要我去寻找法尔甘？",a="达妮萨·莫尔请你寻找死亡卫士法尔甘，并在力所能及的范围内帮助他。",al={"谁派我去","达妮莎·莫尔","任务给予者"}},{q="法尔甘在哪里？",a="法尔甘在毒蛛峡谷。",al={"法尔甘的位置","法尔甘在哪里","寻找死亡卫士"}},{q="法尔甘遭遇了什么？",a="一阵声响惊动了血色十字军，暴露了法尔甘和他的同伴。法尔甘留下断后，他的同伴独自回到了布瑞尔。",al={"法尔甘失踪","发生了什么","救回法尔甘"}},{q="法尔甘和比尔穆斯发现了什么？",a="他们发现血色十字军正计划发动某种袭击。",al={"血色十字军的命令","他们发现了什么","袭击计划"}},{q="生命符记有什么用？",a="生命符记可以让死亡卫士法尔甘起死回生。",al={"复活法尔甘","生命符记","如何救回法尔甘"}},{q="法尔甘回来后提出了什么请求？",a="法尔甘问你是否愿意继续帮助被遗忘者。",al={"帮助被遗忘者","接下来做什么","法尔甘的请求"}}},fp="20,163,15.200.0,32.72.0,16.27.0,24.124.0,38.79.0,31.67.0,37.82.0"}
P.entries["quest:94440"] = {n="A Lesson in Divinity",s="亡灵卫兵 Billmuth 请你从毒蛛峡谷夺回血色十字军的进攻计划。这些计划或许能帮助亡灵卫兵为即将到来的袭击做好准备。",h="亡灵卫兵 Billmuth 请你从毒蛛峡谷夺回血色十字军的进攻计划。这些计划或许能帮助亡灵卫兵为即将到来的袭击做好准备。",kw={"神性的教诲","进攻计划","班达里安堡","亡灵卫兵 比尔穆斯","被遗忘者","血色十字军","毒蛛峡谷"},sec={{t="堡垒的命令",b="血色十字军士兵把部署命令放在挎包里，而亡灵卫兵预料到敌人将要来袭。亡灵卫兵请你把计划副本带回班达里安堡，交给亡灵卫兵 Billmuth，好让他们做好设伏准备。"},{t="救下一位朋友",b="Billmuth 感谢你救了他的朋友，并说他会把计划交给指挥官。他还说，你的所作所为让他看出你彻头彻尾是被遗忘者，尽管他的同僚中有人对你所属的职业心存猜疑。"}},faq={{q="比尔穆斯 需要什么？",a="亡灵卫兵 比尔穆斯 请你从毒蛛峡谷夺回血色十字军的进攻计划。",al={"比尔穆斯 想要什么","比尔穆斯 的计划","给 比尔穆斯 的计划"}},{q="进攻计划在哪里？",a="毒蛛峡谷的血色十字军士兵带着进攻计划。",al={"计划在哪里","血色计划位置","寻找进攻计划"}},{q="亡灵卫兵为什么要这些计划？",a="亡灵卫兵预料到敌人将要来袭，想用这些计划做好设伏准备。",al={"为什么要拿计划","计划有什么用","亡灵卫兵设伏"}},{q="计划应该交给谁？",a="把计划交给班达里安堡的亡灵卫兵 比尔穆斯。",al={"计划交给谁","把计划交还给","比尔穆斯 在哪里"}}},fp="20,172,19.209.0,14.221.1,24.94.0,27.62.0,39.81.0,29.57.0"}
P.entries["quest:94441"] = {n="A Lesson in Divinity",s="一位被遗忘者同伴请你向班达里安堡的 Danitha Morr 转达谢意，感谢那里的圣骑士所提供的帮助。你的付出赢得了亡灵卫兵的感激，也为你带来一份救赎的恩赐。",h="一位被遗忘者同伴请你向班达里安堡的 Danitha Morr 转达谢意，感谢那里的圣骑士所提供的帮助。你的付出赢得了亡灵卫兵的感激，也为你带来一份救赎的恩赐。",kw={"神性启蒙","班达里安堡","达妮莎·莫尔","亡灵卫队","被遗忘者","光明","救赎","生命符记"},sec={{t="堡中的谢意",b="一位被遗忘者同伴请你将他们的谢意转达给班达里安堡的 Danitha Morr。亡灵卫兵的其他成员也会听说你和其他圣骑士所提供的帮助。他们很自豪能与你同为被遗忘者，也相信黑暗女王会守护你。"},{t="光明的恩赐",b="Danitha 说，生命符记可以由一位准备好接受圣光至高恩赐之一的圣骑士使用。她赐予你救赎的恩典，让你能够复活倒下的同伴。你的付出对被遗忘者和班达里安堡的圣骑士都意义重大，亡灵卫兵希望这样的善举能赢得其他被遗忘者的心。"}},faq={{q="我该向谁致谢？",a="有人请你向班达里安堡的 达妮萨·莫尔 致谢，感谢那里的圣骑士所提供的帮助。",al={"达妮莎 是谁","向 达妮莎 致谢","达妮莎·莫尔"}},{q="谁会听说这项服务？",a="亡灵卫兵的其他成员也会听说班达里安堡的圣骑士所提供的帮助。",al={"亡灵卫队的谢意","谁会听说","堡中的服务"}},{q="生命符记有什么用？",a="生命符记是为准备好接受圣光至高恩赐之一的圣骑士准备的。",al={"生命符记","有什么用","有什么作用"}},{q="亡灵卫队为何为我感到骄傲？",a="他们很自豪能与你同为被遗忘者，也重视你与班达里安堡的圣骑士一同做出的贡献。",al={"被遗忘者的骄傲","为何骄傲","亡灵卫队的骄傲"}}},fp="20,178,18.262.0,15.335.1,15.82.0,32.82.0,32.101.0,34.129.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="火焰的召唤是一项萨满祭司的任务，指引学徒们进入丹莫罗高地危险而混乱的火焰领域。在掌握了大地之道的耐心教诲后，修行者会被指引去寻找Bruegs Kindleborn，以测试他们是否准备好接受火焰灵契。",h="火焰的召唤是一项萨满祭司的任务，指引学徒们进入丹莫罗高地危险而混乱的火焰领域。在掌握了大地之道的耐心教诲后，修行者会被指引去寻找Bruegs Kindleborn，以测试他们是否准备好接受火焰灵契。",kw={"布鲁格斯·燃生","火焰的召唤","丹莫罗","大地灵契","火焰图腾","火焰灵契","萨满祭司","南门哨岗"},ang={["class:Shaman"]="这项任务标志着萨满祭司的一次关键精神试炼，是从岩石的忍耐向火焰狂暴、毁灭性力量的过渡。",["faction:Alliance"]="随着试炼在丹莫罗的山脉中展开，联盟的萨满祭司们听从长者的指引，唤醒与火元素的沟通。",["race:Dwarf"]="这项仪式在丹莫罗南门哨岗上方的崇山中进行，测试矮人是否拥有能够抑制火焰燃烧渴望的纪律。"},sec={{t="燃烧试炼",b="在通过大地元素证明了自己的耐心与稳重后，萨满祭司会被指引去面对一种更不稳定的力量：火元素之灵。与稳固而坚毅的岩石不同，火焰带来的召唤充满了混乱、毁灭与狂暴的能量。长者会派遣学徒穿越丹莫罗覆盖着积雪的山峰，在尝试驾驭这股狂野的热量之前去寻求指引。"},{t="山巅隐士",b="在南门哨岗上方的崇山峻岭中，导师Bruegs Kindleborn在一处隐蔽的洞穴中守护着。当携带长者推荐信的学徒抵达时，Bruegs会为他们准备火焰灵契。但他发出了严厉的警告：燃烧与吞噬的渴望极易被唤醒，但想要掌控火焰，就必须准确地知道何时该克制。"}},faq={{q="布鲁格斯·金德尔伯恩是谁？",a="布鲁格斯·金德尔伯恩是一位居住在丹莫罗南门哨岗上方高处山洞里的导师。他会评估由长者派来的萨满祭司，以确定他们是否具备接受火焰灵契所需的成熟度与纪律。",al={"布鲁格斯·燃生是谁","布鲁格斯·燃生背景故事","布鲁格斯在哪里"}},{q="什么是火焰灵契？",a="灵契是一种元素药剂或制剂，允许萨满祭司与该元素的灵魂进行沟通。火焰灵契赋予了与火焰及其原始力量沟通的能力，这需要精神上的专注以及此前在大地之道上的基础。",al={"什么是火焰灵契","火焰灵契","灵契的含义"}},{q="布鲁格斯·金德尔伯恩在哪里？",a="布鲁格斯·金德尔伯恩位于丹莫罗东部遥远的雪山之中，藏身于俯瞰南门哨岗的一处洞穴里。",al={"哪里可以找到布鲁格斯·燃生","南门哨岗洞穴","火焰的召唤在哪里交任务"}},{q="火焰的召唤的目的是什么？",a="火焰的召唤是萨满祭司的成人礼，针对的是那些已经展现出耐心并掌握了大地之道的萨满。它召唤他们去面对毁灭的混乱力量，并在布鲁格斯·金德尔伯恩的注视下进行考验。",al={"什么是火焰的召唤","丹莫罗火焰图腾任务"}},{q="为什么萨满祭司必须在学习火焰之前先学习岩石的教诲？",a="大地代表着坚定的耐心、稳定与控制。如果没有岩石所教授的基础，萨满祭司就有可能被火焰那不稳定的渴望与毁灭性的激情所淹没。",al={"为什么要先学岩石","记住岩石教给你的知识"}},{q="在进行火焰的召唤之前需要什么先决条件？",a="该任务建立在之前的试炼之上，学徒在那些试炼中展现了耐心并将自己扎根于大地。只有当学生的纪律得到充分证明时，长者才会将他们送到布鲁格斯·金德尔伯恩那里。",al={"火焰的召唤先决条件","耐心任务关联"}}},fp="12,175,17.311.0,24.321.0,25.214.0,26.225.0,35.122.0,40.155.0,57.173.0,68.186.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="火焰的召唤是一项神圣的试炼，旨在考验入门者是否有能力驾驭元素之火。祈求者必须手持眠炎火炬，沿着洛克莫丹一条隐蔽的山路前行，在眠炎圣殿寻找Braldir Ashmantle。",h="火焰的召唤是一项神圣的试炼，旨在考验入门者是否有能力驾驭元素之火。祈求者必须手持眠炎火炬，沿着洛克莫丹一条隐蔽的山路前行，在眠炎圣殿寻找Braldir Ashmantle。",kw={"布拉尔迪尔·灰烬斗篷","火焰的召唤","火焰图腾","洛克莫丹","萨满","眠炎圣殿","眠炎火炬","国王谷"},ang={["class:Shaman"]="这项试炼考验着萨满祭司学徒与火焰元素之灵沟通的决心，要求他们将神圣的火炬带到洛克莫丹的一座与世隔绝的山峰上。",["faction:Alliance"]="虽然联盟领地上的普通游客眼中只有荒凉的山石，但圣殿的守护者守卫着不为凡人所知的古老元素秘密。",["race:Dwarf"]="任务对话反映了矮人的语言，并指引入门者越过国王谷，进入卡兹莫丹崎岖的峭壁中。"},sec={{t="国王谷之外的道路",b="获得火焰图腾不仅仅需要强大的体魄。入门者必须携带未点燃的眠炎火炬，攀登至洛克莫丹高耸的峭壁之上。穿过国王谷的石刻，那条艰险的攀登之路通向一座与世隔绝的山峰，那里的元素之力远高于凡人行走的道路。"},{t="眠炎圣殿",b="在风吹过的山峰之巅矗立着Braldir Ashmantle，他是守护眠炎圣殿的守卫。毫无准备的流浪者和寻宝者爬上高处，只会发现寂静与裸露的岩石。对于携带神圣火炬的真正入门者，Braldir会揭示圣殿火盆中沉睡的深层元素力量，等待着被重新点燃。"}},faq={{q="什么是火焰的召唤任务？",a="火焰的召唤是入门者为了获得火焰图腾而必须经历的成人礼。任务指引祈求者进入洛克莫丹的峭壁，向圣山之巅的布拉尔迪尔·灰衣献上眠炎火炬。",al={"火焰的召唤是什么","萨满火焰任务洛克莫丹","火焰图腾任务"}},{q="布拉尔迪尔·灰衣是谁？",a="布拉尔迪尔·灰衣是驻守在洛克莫丹高处峭壁中眠炎圣殿的守护者。他会拒见普通的游客和寻宝者，只欢迎那些携带眠炎火炬的人。",al={"布拉尔迪尔·灰幔是谁","洛克莫丹圣殿守护者"}},{q="眠炎圣殿在哪里？",a="眠炎圣殿坐落在洛克莫丹高耸的峭壁之中，沿着国王谷之外的一条秘道即可到达。",al={"眠炎圣殿在哪里","眠炎位置"}},{q="眠炎火炬的作用是什么？",a="眠炎火炬是入门者携带的仪式信物，用来证明他们沟通元素之火的真诚意图和准备工作。布拉尔迪尔·灰衣要求在接见前先看到火炬。",al={"什么是眠炎火炬","眠炎火炬用途"}},{q="为什么祈求者必须前往洛克莫丹？",a="安置眠炎圣殿的神圣元素之巅俯瞰着国王谷之外的洛克莫丹，这里因远离普通游客而备受青睐。",al={"为什么要去洛克莫丹","为什么火焰圣殿在洛克莫丹"}},{q="如何通过这项试炼获得火焰图腾？",a="在找到布拉尔迪尔·灰衣并用火炬证明意图后，入门者必须在圣殿的火盆中引燃火焰，带着燃烧的火炬返回，从而正式获得火焰图腾。",al={"找到布拉尔迪尔后会发生什么","如何获得火焰图腾"}}},fp="12,157,35.270.0,31.328.0,31.202.0,25.204.0,49.124.0,54.195.0,45.165.0,48.166.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="火焰的召唤是洛克莫丹的一项元素试炼，初学者在这里准备与永恒之火进行沟通，并获得他们的火焰图腾。在Braldir Ashmantle的引导下，候选人必须从当地的狗头人和穴居人那里收集元素试剂，以酿造一种具有约束力的火焰灵契。这次旅程教导人们，火焰不仅是毁灭的工具，更是锻造的源泉和生命的呼吸本身。",h="火焰的召唤是洛克莫丹的一项元素试炼，初学者在这里准备与永恒之火进行沟通，并获得他们的火焰图腾。在Braldir...",kw={"布拉尔迪尔·灰烬斗篷","火焰的召唤","永恒之火","火焰灵契","火焰焦油","火焰图腾","洛克莫丹","石窟预言者","隧道鼠地卜师"},ang={["class:Shaman"]="与火焰沟通需要通过专门的灵契建立元素纽带，从而通向与永恒之火的沟通并获得火焰图腾。",["faction:Alliance"]="这项试炼设定在矮人领地洛克莫丹，将萨满仪式牢牢扎根于联盟土地上，以对抗当地穴居人和狗头人的威胁。",["race:Dwarf"]="Braldir Ashmantle以一种朴实的、矮人的元素火焰视角在洛克莫丹指导初学者，将其视为锻造和创造的呼吸，而非单纯的破坏。"},sec={{t="火焰之路",b="在洛克莫丹崎岖的峭壁中，一位名叫Braldir Ashmantle的元素导师监督着那些寻求火焰力量的初学者的道路。与火灵沟通绝非简单的召唤；凡人的灵魂必须首先通过一种被称为火焰灵契的神圣药剂，与燃烧的元素相调和。没有这种准备，永恒之火的热量只会将人吞噬，而不会带来启迪。Braldir要求请求者从山谷的敌对居民那里收集两种与火焰紧密相连的关键试剂，以证明他们的决心。"},{t="大地与火花的试剂",b="制作火焰灵契需要富含元素共鸣的物质。在北方，隧道鼠地卜师在他们错综复杂的巢穴中采集粘稠的火焰焦油，为他们的地下魔法提供燃料。在南方，被称为石窟预言者的穴居人神秘主义者带着装满原始元素护身符的试剂袋穿过崎岖的丘陵。夺取这些物品需要与洛克莫丹最根深蒂固的两种害虫进行斗争，强行获取将初学者的灵魂与火焰绑定所需的材料。"},{t="智慧的磨砺",b="在收到试剂后，Braldir Ashmantle提供了用耐心来调节原始破坏力的智慧。对于这位经验丰富的导师来说，火焰不仅仅是愤怒和灰烬，它代表着生命、锻造工艺以及创造的呼吸本身。对元素真正的掌握在于平衡：正如阴影赋予光意义一样，火焰阻止石头仅仅成为冰冷的记忆。掌握火焰需要知道何时去融合，而不是仅仅去燃烧。"}},faq={{q="火焰的召唤的目的是什么？",a="火焰的召唤是渴望与永恒之火沟通的萨满祭司候选人的通过仪式。为了与火灵沟通并获得火焰图腾，必须首先准备一份火焰灵契，将他们凡人的灵魂与该元素绑定。",al={"什么是火焰的召唤","这是一个什么任务","火焰的召唤的目的"}},{q="布拉尔迪尔·灰衣是谁？",a="布拉尔迪尔·灰衣是一位居住在洛克莫丹的元素向导。他指导初学者掌握火焰的平衡，并在收集到适当的元素试剂后准备必要的火焰灵契。",al={"谁给予火焰的召唤","布拉尔迪尔·灰幔是谁","布拉尔迪尔·灰幔的位置"}},{q="什么是火焰灵契？",a="火焰灵契是一种由火焰相关试剂制成的元素药剂或制剂。饮用或使用它会使萨满的灵魂与火焰元素位面相协调并绑定，从而实现与永恒之火的视觉沟通。",al={"什么是火焰灵契","火焰灵契有什么作用","为什么要用火焰灵契"}},{q="在哪里可以找到火焰焦油？",a="火焰焦油由居住在洛克莫丹北部狗头人洞穴中的隧道鼠地卜师携带。地卜师们利用这些焦油进行原始的火焰工艺。",al={"在哪里获得火焰焦油","火焰焦油位置","狗头人洞穴的火焰焦油"}},{q="在哪里可以找到石窟试剂袋？",a="试剂袋必须从潜伏在洛克莫丹南部丘陵的石窟预言者身上夺取。这些穴居人神秘主义者使用这些袋子来盛放与元素魔法相关的试剂。",al={"在哪里获得试剂袋","石窟预言者的试剂袋","石窟试剂袋位置"}},{q="布拉尔迪尔·灰衣如何看待火焰元素？",a="布拉尔迪尔并没有将火焰视为盲目的破坏，而是教导说火焰是锻造、生命和创造的呼吸。它与其他力量保持平衡，通过调和冰冷的石头，赋予存在以温暖和意义。",al={"布拉尔迪尔对火焰的看法","洛克莫丹火焰的意义","矮人的火焰哲学"}}},fp="12,263,21.387.0,31.422.0,23.387.0,36.157.0,25.144.0,21.164.0,28.119.0,47.147.0,52.193.0"}
P.entries["quest:94467"] = {n="火焰的召唤",s="火焰的召唤是一项元素试炼，初学者需要饮下调制好的火焰灵契，以感知并面对一个次级火焰显化。通过制服这个灵魂并将余烬置于神圣火盆中，祈求者便能赢得火焰的眷顾。",h="火焰的召唤是一项元素试炼，初学者需要饮下调制好的火焰灵契，以感知并面对一个次级火焰显化。通过制服这个灵魂并将余烬置于神圣火盆中，祈求者便能赢得火焰的眷顾。",kw={"火盆","火焰的召唤","火焰灵契","余烬","次级火焰显化","萨满试炼","永恒火焰神龛"},ang={["class:Shaman"]="这是一项萨满与火焰沟通的基础试炼，需要使用神圣的灵契来感知并对抗火焰之灵。"},sec={{t="火焰仪式",b="火焰的召唤是一项考验精神与勇气的传统试炼。在元素知识的指引下，初学者会获得一种调制好的火焰灵契，用以唤醒对不可见世界的感知。在神龛饮下药水并向山顶攀登时，凡人双眼与原始力量之间的界限会变得模糊，显露出一个等待挑战的沉睡火焰显化。"},{t="面对显化",b="与次级火焰显化的对抗是对决断力和耐力的考验。这个元素灵魂不会主动攻击，但一旦受到挑战，其强度会随着时间的推移而不断攀升。将其击败后会掉落余烬，必须将其带到永恒火焰神龛顶部的火盆中，点燃火炬以确保获得该灵魂持久的眷顾。"}},faq={{q="什么是火焰的召唤？",a="火焰的召唤是一项神圣的成人礼，初学者饮下特制的火焰灵契来感知火焰之灵，在战斗中与它对抗，并将它的余烬献给火盆，从而赢得火焰的眷顾。",al={"什么是火焰的召唤","火焰的召唤任务","火焰图腾试炼"}},{q="火焰灵契的用途是什么？",a="火焰灵契是一种调制好的药水，能够开启初学者的灵视，让他们看到在山顶等待他们的隐形元素之灵。",al={"火焰灵契用途","为什么要喝灵契","灵契有什么用"}},{q="试炼中会出现什么灵魂？",a="这项试炼要求初学者在山顶对抗一个次级火焰显化，它会一直等待直到受到攻击才加入战斗。",al={"我要和什么灵魂战斗","火焰的召唤怪物","火焰显化"}},{q="为什么必须尽快击败火焰之灵？",a="战斗持续的时间越长，元素之灵就会变得越凶猛、越炽热，因此迅速、果断地出击对于在火焰变得势不可挡之前将其制服至关重要。",al={"为什么要快速击杀","火焰的召唤战斗","火焰之灵计时"}},{q="余烬如何处理？",a="在击败次级火焰显化后，将其余烬带到永恒火焰神龛顶部的火盆中，点燃仪式火炬。",al={"余烬交到哪里","火焰的召唤火盆","永恒火焰神龛火盆"}},{q="赢得火焰的眷顾意味着什么？",a="完成仪式并点燃火炬，将赢得火元素直接的眷顾与沟通，与火焰建立起至关重要的联系。",al={"奖励是什么","仪式有什么奖励","火焰眷顾"}}},fp="12,165,17.289.0,24.311.0,25.159.0,38.135.0,37.96.0,45.150.0,37.157.0,40.124.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="火焰的召唤是一项神圣的试炼，学徒需要从俯瞰洛克莫丹的制高点取得恒焰火炬，并将其带到丹莫罗。将火焰带回导师 Bruegs Kindleborn 的身边，既证明了旅行者对元素的掌握，也能赢得属于他们的火焰图腾。",h="火焰的召唤是一项神圣的试炼，学徒需要从俯瞰洛克莫丹的制高点取得恒焰火炬，并将其带到丹莫罗。将火焰带回导师 Bruegs Kindleborn 的身边，既证明了旅行者对元素的掌握，也能赢得属于他们的火焰图腾。",kw={"布鲁格斯·燃生","火焰的召唤","丹莫罗","火焰图腾","烈焰之子","洛克莫丹","萨满祭司","恒焰火炬"},ang={["class:Shaman"]="这项仪式完成了卡兹莫丹萨满学徒的火焰试炼，使他们获得引导火焰并与火元素交流所需的火焰图腾。",["faction:Alliance"]="随着精神召唤在卡兹莫丹的联盟领地中扎根，像 Bruegs Kindleborn 这样的导师会引导新学徒掌握元素艺术。",["race:Dwarf"]="将火焰从洛克莫丹上方的山巅带回丹莫罗，反映了矮人精神追求者与其家园山脉的元素力量之间深厚的联系。"},sec={{t="洛克湖上的火焰",b="火焰的召唤标志着学徒在元素交流道路上的关键时刻。在山脊高处，狂风呼啸而过，学徒点燃了俯瞰洛克莫丹的恒焰火炬。跳动的火焰映照着觉醒的精神，激发起一种元素共鸣，学徒必须悉心呵护，沿着山路将其安全带回丹莫罗的雪谷之中。"},{t="烈焰之子的奖赏",b="在丹莫罗，元素导师 Bruegs Kindleborn 正在等待着旅行者，他将评判旅行者内心的火焰是否真正觉醒。呈上燃烧的火炬证明了请愿者拥有与火焰交流的意志和敬意。Kindleborn 会宣布学徒为“烈焰之子”，并授予火焰图腾，使其成为族群中元素指引的传承者。"}},faq={{q="什么是火焰的召唤？",a="火焰的召唤是卡兹莫丹萨满祭司的一项精神试炼。在俯瞰洛克莫丹的火盆处点燃恒焰火炬后，学徒必须带着燃烧的火焰穿过群山，回到丹莫罗寻找 布鲁格斯·焰生。",al={"什么是 火焰的召唤","火焰的召唤 任务","火焰的召唤 要做什么"}},{q="布鲁格斯·焰生 是谁？",a="布鲁格斯·焰生 是一位居住在丹莫罗的导师和元素向导。他负责监督火焰的元素仪式，并向完成旅程的学徒授予火焰图腾。",al={"布鲁格斯·燃生 是谁","布鲁格斯·燃生 在哪里","布鲁格斯·燃生 位置"}},{q="什么是恒焰火炬？",a="恒焰火炬是一把神圣的仪式火炬，需要在俯瞰洛克莫丹的火盆处点燃。它象征着学徒与元素之火的内在连接，必须安全地带回丹莫罗交给 布鲁格斯·焰生。",al={"什么是恒焰火炬","恒焰火炬","在哪里获取火炬"}},{q="完成这项试炼能得到什么？",a="在安全地将恒焰火炬送到 布鲁格斯·焰生 手中后，这位导师会认可你那燃烧的精神，并授予你火焰图腾，标志着你已成为烈焰之子。",al={"火焰的召唤 的奖励是什么","能获得火焰图腾吗","火焰的召唤 图腾"}},{q="这段旅程发生在什么地方？",a="旅程始于俯瞰洛克莫丹的制高点（在那里点燃火炬），随后沿着山路返回积雪覆盖的丹莫罗领地，与 布鲁格斯·焰生 会合。",al={"火焰的召唤 在哪里进行","火焰的召唤 路径","要把火炬带到哪里"}},{q="为什么 布鲁格斯 会提到玛多兰？",a="布鲁格斯 发誓时所说的“以玛多兰之胡须起誓”，指的是玛多兰·铜须，即在三锤之战中带领铜须部族的受人尊敬的矮人领袖。",al={"为什么提到 玛多兰 的胡须","玛多兰 的含义","布鲁格斯 提到的 玛多兰 是谁"}}},fp="12,162,23.241.0,22.320.0,25.218.0,25.156.0,35.200.0,47.173.0,35.148.0,32.169.0"}
P.entries["quest:94480"] = {n="A Gift From Our Enemies",s="你将偷来的饲料带给洛格玛的Gorg，以便喂饱它的盟友。附近的豺狼人和步步逼近的暮光威胁着这处聚居地。",h="你将偷来的饲料带给洛格玛的Gorg，以便喂饱它的盟友。附近的豺狼人和步步逼近的暮光威胁着这处聚居地。",kw={"盟友","农场","豺狼人","戈尔格","丰盛炖菜","洛格玛","偷来的饲料","暮光"},sec={{t="给洛格玛的食物",b="戈尔格正在洛格玛等你送来收集到的偷来的饲料。附近的威胁不只有人类：豺狼人从山上传来咆哮，暮光势力也在步步逼近。让洛格玛的盟友吃饱，或许能帮助他们保持力量。"},{t="丰盛的炖菜",b="饲料散发着浓烈的土腥味，底下还透着一股令人不快的气息。戈尔格认出这是你从农场偷来的东西，并说它能给盟友做成丰盛的炖菜。"}},faq={{q="戈尔格为什么想要偷来的饲料？",a="戈尔格会用偷来的饲料为洛格玛的盟友做一锅丰盛的炖菜。",al={"饲料用途","戈尔格 饲料","偷来的饲料做什么用"}},{q="洛格玛附近有哪些威胁？",a="人类是一种威胁，附近山上的豺狼人也在咆哮，暮光势力更是步步逼近。",al={"附近的豺狼人","暮光威胁","洛格玛附近有什么"}},{q="戈尔格是谁？",a="戈尔格是在洛格玛接收偷来的饲料，并说这些饲料能做成丰盛炖菜的人。",al={"戈尔格是谁","gorg是谁"}},{q="我该把偷来的饲料送到哪里？",a="把偷来的饲料送给洛格玛的戈尔格。",al={"饲料地点","饲料送到哪里","戈尔格位置"}}},fp="23,134,16.224.0,13.177.1,35.73.0,30.92.0,12.91.0,32.40.0"}
P.entries["quest:94481"] = {n="A Serving of Strength",s="训练师让你把炖肉送到训练场，喂给Rog’mar新兵。守卫补给线愈发艰难，这些炖肉能让他们填饱肚子。",h="训练师让你把炖肉送到训练场，喂给Rog’mar新兵。守卫补给线愈发艰难，这些炖肉能让他们填饱肚子。",kw={"一份力量","rog’mar新兵","炖肉","补给线","新兵","训练场","战士"},sec={{t="给新兵的食物",b="训练场的新兵需要食物，训练师便让你带上丰盛的炖肉。你要去西边喂Rog’mar新兵。他们的抱怨可以先放一边；如今守卫补给线愈发艰难，战士们很感激你带来的食物。"}},faq={{q="谁需要炖肉？",a="训练场的Rog’mar新兵需要炖肉。",al={"谁饿了","谁能吃到食物","新兵的食物"}},{q="我该把炖肉送到哪里？",a="Rog’mar新兵在西边的训练场。",al={"在哪里喂新兵","新兵的位置","炖肉在哪里"}},{q="为什么要给他们炖肉？",a="守卫补给线变得艰难，炖肉能让新兵填饱肚子。",al={"为什么给炖肉","食物有什么用","为什么喂新兵"}},{q="训练师怎么看新兵的抱怨？",a="训练师说，新兵有任何后续抱怨，都可以直接找他们。",al={"新兵的抱怨","他们为什么抱怨","训练师生气了吗"}},{q="训练师感激这些食物吗？",a="是的。尽管战士们嘴上那么说，训练师和战士们都很感激这些食物。",al={"训练师领情吗","感谢炖肉","战士们很感激"}}},fp="21,149,17.274.0,19.57.0,25.63.0,28.86.0,56.80.0,37.91.0"}
P.entries["quest:94483"] = {n="Show Them How It's Done",s="一名指挥官派你前往河流以南，袭击 Farholde 训练营。此番进攻旨在牵制人类，不让他们靠近要塞，为指挥官处理其他事务争取时间。",h="一名指挥官派你前往河流以南，袭击 Farholde 训练营。此番进攻旨在牵制人类，不让他们靠近要塞，为指挥官处理其他事务争取时间。",kw={"farholde","人类","要塞","牧师","河流","斥候","训练营"},sec={{t="河畔",b="指挥官派你前往河流以南的 Farholde 营地，那里有斥候报告称驻有人类部队。你需要击杀 Farholde 牧师和 Farholde 斥候。阻止人类靠近他们的要塞，能为指挥官处理其他事务争取时间。"}},faq={{q="是谁要我袭击营地？",a="一名指挥官收到斥候关于河流以南训练营的报告后，派你去对付 Farholde 部队。",al={"谁下达了命令","指挥官要求"}},{q="Farholde 营地在哪里？",a="训练营位于河流以南。",al={"营地在哪里","farholde 位置"}},{q="我该攻击谁？",a="指挥官指定 Farholde 牧师和 Farholde 斥候为目标。",al={"攻击谁","目标"}},{q="为什么要攻击人类？",a="牵制人类，不让他们靠近要塞，是为了给指挥官处理其他事务争取时间。",al={"为何与人类战斗","目的是什么"}},{q="袭击之后会发生什么？",a="指挥官说行动迅速，并打算继续处理别处的事务。",al={"接下来做什么","袭击营地之后"}}},fp="23,160,12.264.0,37.119.0,29.42.0,28.72.0,22.96.0,30.74.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Unnerving Silence 起因于影风森林东北部一个洞穴内的德鲁伊隐修会突然中断了通讯。随着 Ban'aethall 的毁灭以及该地区日益动荡，一名调查员被派遣前往寻找 Elegael Thornpaw，以评估该隐修会的命运。",h="Unnerving Silence 起因于影风森林东北部一个洞穴内的德鲁伊隐修会突然中断了通讯。随着 Ban'aethall 的毁灭以及该地区日益动荡，一名调查员被派遣前往寻找 Elegael...",kw={"班艾萨尔","德鲁伊","德鲁伊隐修会","艾勒盖尔·棘爪","影风森林","令人不安的寂静"},ang={["class:Druid"]="与影风森林中一个隐居隐修会的联络中断，引起了那些致力于维持荒野平衡的德鲁伊们的直接关注。调查 Elegael Thornpaw 的沉默，是为了保护同胞并查明是什么破坏了他们的沟通。"},sec={{t="树冠下的寂静",b="Ban'aethall 陷落后，一片寂静的忧虑笼罩着荒野。那座村庄化为废墟，且神秘的动荡在领地内蔓延，原本稳固的联络线开始断裂。特别是影风森林东北部一处深藏在洞穴中的德鲁伊隐修会，他们定期的派遣突然中断，令盟友们感到不安。"},{t="寻找隐修会",b="前往影风森林的旅者肩负着寻找 Elegael Thornpaw 的重任，她是这些洞穴德鲁伊中的杰出人物。深入那阴影笼罩的东北部，调查员必须查明该隐修会究竟只是退隐以与自然进行更深层次的沟通，还是已经沦陷于摧毁了 Ban'aethall 的危险之中。"}},faq={{q="令人不安的沉默 这个任务是关于什么的？",a="令人不安的沉默 是一项调查任务，旨在探寻影风森林中一个德鲁伊隐修会突然失联的原因。忧心忡忡的当事人请求途经此地的旅者搜索东北部的一个洞穴，查明那个隐居的组织遭遇了什么。",al={"令人不安的寂静 任务","什么是 令人不安的寂静"}},{q="埃雷加尔·荆爪 在哪里可以找到？",a="埃雷加尔·荆爪 住在影风森林东北部边缘的一处洞穴中。她是驻扎在那里的隐居德鲁伊隐修会的联络人。",al={"艾勒盖尔·棘爪 在哪里","艾勒盖尔·棘爪 位置","寻找 棘爪"}},{q="埃雷加尔·荆爪 是谁？",a="埃雷加尔·荆爪 是居住在影风森林东北部洞穴中的德鲁伊隐修会成员。她长期的沉默和未按时发送联络信息，引发了对该隐修会安全状况的严重担忧。",al={"谁是 艾勒盖尔·棘爪","棘爪 背景故事"}},{q="什么是影风森林？",a="影风森林是一片树木繁茂的区域，其东北部隐藏着一个德鲁伊洞穴隐修会。在广泛的地区动荡和 班艾萨尔 陷落后，与这片森林居住者之间的联络变得极度不稳定。",al={"什么是影风森林","影风森林隐修会"}},{q="什么是 班艾萨尔？",a="班艾萨尔 是影风森林深处的一座村庄，最近已化为废墟。它的毁灭，加上整个领地内更广泛的动荡，加剧了人们的担忧，即像影风森林隐修会这样的附近营地可能也处于危险之中。",al={"班艾萨尔 发生了什么","班艾萨尔 废墟背景故事","班艾萨尔 陷落"}},{q="为什么德鲁伊隐修会没有消息了？",a="影风森林德鲁伊的定期信息和报告已莫名中断。鉴于 班艾萨尔 的毁灭以及地区局势的不断升级，人们严重担心他们可能遭遇了灾难或被敌对势力袭击。",al={"为什么德鲁伊停止发送信息","为什么德鲁伊保持沉默"}}},fp="17,142,21.259.0,19.271.0,42.188.0,36.131.0,24.183.0,26.223.0,20.193.0,39.222.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="Tears of the Lady 是在影风森林中为 Elegael 执行的一项紧急救援任务。为了救治被困在 Nightclaw Den 中的受伤同伴，旅行者必须在当地的树干上搜寻 Lady's Tear，这是一种对于包扎严重伤口至关重要的防腐苔藓。",h="Tears of the Lady 是在影风森林中为 Elegael 执行的一项紧急救援任务。为了救治被困在 Nightclaw Den 中的受伤同伴，旅行者必须在当地的树干上搜寻 Lady's...",kw={"艾勒盖尔","女士之泪","苔藓","夜爪巢穴","药膏","影风森林","女士的眼泪"},ang={["class:Priest"]="虽然牧师们可以引导圣光来治愈凡人的伤势，但在魔法救援力量薄弱时，像 Lady's Tear 这样的天然药膏可以作为受伤幸存者的重要物理敷料。",["profession:Herbalism"]="草药师和战地医疗人员都很看重 Lady's Tear，因为它具有粘性的防腐分泌物，可以在荒野紧急情况下迅速封住伤口并防止感染。"},sec={{t="影风森林的绝望补救措施",b="在影风森林阴影笼罩的深处，Elegael 急需援助来救治被困在 Nightclaw Den 中的同伴。由于身负重伤的盟友正等待救援，且常规补给匮乏，需要直接从周围的荒野中搜寻野外医疗用品。这次行动的关键在于在被遗弃的伤员生命耗尽之前，获取到这些天然药物。"},{t="疗伤苔藓",b="Elegael 计划配制的药膏中，至关重要的成分是 Lady's Tear，这是一种附着在影风森林各处树木根部的细长苔藓。这种植物会分泌出一种粘稠的、具有天然防腐特性的分泌物，能够封住开放性伤口，并保护严重外伤免受潮湿荒野环境的影响而恶化。提供足够的苔藓，Elegael 就能配制出稳定伤者状况所需的敷料。"}},faq={{q="女士之泪 是关于什么的？",a="女士之泪 是由影风森林中的 埃雷加尔 所指导的一项恢复工作。受伤的同伴仍被困在 夜爪巢穴 中，埃雷加尔 需要当地的植物来配制紧急药膏以维持他们的生命。",al={"什么是 女士之泪","女士之泪 任务信息"}},{q="什么是 女士之泪？",a="女士之泪 是一种生长在影风森林各处树木根部的细长苔藓。它会分泌出一种天然的粘性树液，作为强效防腐剂，非常适合用于包扎和封盖开放性伤口。",al={"什么是 女士之泪","女士之泪 苔藓","什么是 女士之泪 苔藓"}},{q="谁是 埃雷加尔？",a="埃雷加尔 是一位组织了影风森林医疗救助工作的幸存者。在将受伤的同伴留在 夜爪巢穴 后，埃雷加尔 正收集医疗物资以配制治疗用品，然后返回营救他们。",al={"谁是 艾勒盖尔","女士之泪 任务发布者"}},{q="什么是 夜爪巢穴？",a="夜爪巢穴 是影风森林附近的一个地点，埃雷加尔 的几名受伤盟友被困在那里。他们的情况岌岌可危，迫使人们必须急切地搜集治疗草药。",al={"什么是 夜爪巢穴","夜爪巢穴 在哪里"}},{q="为什么 埃雷加尔 需要 女士之泪 苔藓？",a="这种苔藓能提供一种重要的防腐分泌物，用于配制医用药膏。这种粘性物质可以封住开放性伤口，并帮助被困在洞穴中的幸存者抵御感染。",al={"为什么需要 女士之泪","这种苔藓有什么作用"}},{q="在哪里可以找到 女士之泪 苔藓？",a="女士之泪 苔藓通常附着在影风森林各处的树木根部。虽然 埃雷加尔 已经收集了触手可及的部分，但还需要从周围的树林中搜寻更多。",al={"女士之泪 在哪里生长","寻找 女士之泪"}}},fp="17,157,32.238.0,16.312.0,42.164.0,20.178.0,15.135.0,26.156.0,39.165.0,32.153.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="\"Feathers for Binding\" 是影风森林中的一项任务，主要目标是从幼年尖叫兽身上收集保温羽毛，用于制作保护性的药膏。虽然这些通常温顺的生物变得极具攻击性，但它们的羽毛对于保护杀菌药膏免受外界环境影响至关重要。冒险者必须勇敢面对这些充满敌意的幼崽，以获取区域护理所需的材料。",h="\"Feathers for Binding\"...",kw={"杀菌树液","束缚用的羽毛","药膏","影风森林","影风森林尖叫兽","尖叫兽"},ang={["class:Druid"]="德鲁伊可能会对猎杀这些幼年林地野兽与任务发布者感同身受，尽管日益增长的攻击性和紧迫的医疗需求让人别无选择。",["profession:Herbalism"]="草药师和自然治疗者能够理解结合苔藓、杀菌树液和隔热羽毛来制作有效的战地敷料或药膏时的精妙平衡。"},sec={{t="森林疗法",b="在影风森林深处，准备战地药物往往需要从土地中寻找资源。在治疗重伤时，草药师和治疗者会使用一种基于苔藓和杀菌树液的特制药膏。为了确保药液不会迅速干涸或在恶劣天气下失去效力，需要耐用的绝缘敷料。影风森林幼年尖叫兽的羽毛提供了一种理想的天然屏障，既能保护伤口，又能封住药物。"},{t="反常的敌意",b="获取这些绒羽变得出乎意料地危险。在通常情况下，影风森林的幼年尖叫兽是温顺的林间居民。然而近来，一股莫名其妙的攻击性浪潮席卷了它们。这些幼年掠食者挥舞着足以造成致命伤的强力爪子，现在会凶猛地攻击路人。收集它们的羽毛需要冒险者面对这些从无害幼崽转变为真正威胁的生物。"},{t="令人遗憾的必要之举",b="要求旅行者猎杀幼年生物让当地的看护者感到沉重，他们公开哀悼这种淘汰的必要性。然而，随着多重紧急情况威胁着该地区，且这些野兽变得越来越危险，减少它们的数量具有双重目的：收集重要的治疗材料，同时压制森林道路上日益增长的威胁。每一根收集到的羽毛都受到尊重，以确保它们的牺牲没有被浪费。"}},faq={{q="为什么药膏需要影风森林尖叫兽的羽毛？",a="幼年影风森林尖叫兽的羽毛具有天然的隔热特性。放在苔藓层上，它们可以作为一种保护性敷料，防止杀菌药液干涸，同时保护伤口免受恶劣环境的影响。",al={"羽毛的用途","为什么使用尖叫兽羽毛","药膏羽毛"}},{q="幼年尖叫兽有多危险？",a="虽然影风森林尖叫兽通常是温顺的生物，但它们最近变得异常具有敌意。尽管它们还很年幼，但却拥有巨大的利爪，足以剖开毫无防备的旅行者的腹部。",al={"尖叫兽的危险性","尖叫兽危险吗","尖叫兽的攻击性"}},{q="为什么要猎杀幼年尖叫兽而不是成年个体？",a="任务发布者对捕杀幼兽表示了由衷的悔意。然而，由于它们突然激增的攻击性，以及需要应对其他相互竞争的荒野紧急情况，在收集所需药物的同时减少它们的数量被认为是一项痛苦的必要之举。",al={"为什么要杀死幼年尖叫兽","杀死幼年尖叫兽"}},{q="在哪里可以找到影风森林尖叫兽？",a="影风森林尖叫兽在影风森林的林冠和灌木丛中游荡，旅行者必须小心穿过树林才能追踪到它们。",al={"影风森林在哪里","尖叫兽位置","尖叫兽在哪里"}},{q="除了这些羽毛外，还使用了哪些其他成分？",a="这种药膏由当地的苔藓和杀菌树液分层组成，然后用从幼年尖叫兽身上采集的绒羽进行包裹和隔热。",al={"药膏成分","药膏里有什么"}},{q="为什么尖叫兽最近变得如此具有敌意？",a="它们突然产生敌意的确切原因尚不清楚，但这些平时温和的幼兽变得异常好斗，这增加了当地看护者所面临的危机。",al={"为什么尖叫兽很愤怒","尖叫兽攻击性的原因"}}},fp="20,179,22.275.0,26.255.0,23.313.0,63.166.0,43.170.0,58.225.0,43.142.0,63.106.0,50.175.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Unwanted and Unworthy是泽弗拉斯（Zephras）上的一个任务，冒险者们将在任务中协助埃雷加尔（Elegael）对奥拉凯斯邪教徒进行报复，此前这些邪教徒在影风森林发动了一场血腥的伏击。玩家通过击杀邪教徒并找回被盗的传家宝，为牺牲的德鲁伊复仇，并为大长老（High Elder）收回神圣的祖传遗物。",h="Unwanted and...",kw={"奥拉凯斯","染血的传家宝","埃雷加尔","步兵","传家宝","影风森林","申多雷","风暴追猎者","泽弗拉斯"},ang={["class:Druid"]="奥拉凯斯邪教徒在对泽弗拉斯的无端袭击中流下了当地德鲁伊的鲜血，使得这次打击成为了一次直接的复仇行动，也是对自然平衡的捍卫。"},sec={{t="影风森林的伏击",b="当奥拉凯斯邪教徒在影风森林对当地德鲁伊发动突然袭击时，泽弗拉斯宁静的平衡被瞬间打破。埃雷加尔曾认为这些狂热者不过是“脑子里塞满云雾”的无害梦想家，却因他们袭击手段的极度残忍而措手不及。这场袭击导致德鲁伊的鲜血洒满了森林，引发了对肇事的步兵和风暴追猎者进行迅速报复的呼声。"},{t="被玷污的传家宝与逝去的青春",b="对埃雷加尔来说，邪教徒的背叛剥夺了他们的传承：他们不再配被称为shen'dorei，他们的遗骸也不配得到故乡之风的吹拂。许多邪教徒是原本拥有光明未来却因狂热而生命过早终结的年轻人。通过找回他们血迹斑斑的传家宝，冒险者们协助确保这些神圣物品被交还给大长老，等待更睿智、更值得拥有的下一代。"}},faq={{q="谁是奥拉凯斯邪教徒？",a="奥拉凯斯邪教徒是一群活跃在泽弗拉斯岛上、痴迷于风暴的狂热信徒。据埃雷加尔所言，他们曾经只被视为愚蠢或“脑子里塞满云雾”，但他们突然对当地德鲁伊转向了残暴的暴力行径。",al={"奥拉凯斯是谁","奥拉凯斯邪教","邪教徒是谁"}},{q="谁是埃雷加尔？",a="埃雷加尔是泽弗拉斯的一位神多雷守护者或德鲁伊，曾遭到奥拉凯斯邪教徒的伏击。由于对年轻生命的背叛和流血事件感到悲痛，埃雷加尔寻求报复并找回被盗的祖传遗物。",al={"埃雷加尔是谁","任务发布者埃雷加尔"}},{q="什么是染血的传家宝？",a="这些染血的传家宝属于那些被卷入奥拉凯斯邪教的年轻神多雷。埃雷加尔收集它们，以便最终能归还给大长老的收藏，并传给未来更值得拥有的后代。",al={"染血的传家宝","为什么要收集传家宝","什么是传家宝"}},{q="什么是申多雷？",a="申多雷是居住在泽弗拉斯的族群。埃雷加尔认为，奸诈的奥拉凯斯邪教徒因其暴力的背叛和对岛屿和谐的亵渎，已经失去了被称为申多雷的权利。",al={"申多雷的含义","什么是申多雷"}},{q="影风森林在哪里？",a="影风森林是位于泽弗拉斯的一片林区，奥拉凯斯步兵和风暴追猎者在此活动，这也是针对德鲁伊的无端伏击发生的地方。",al={"影风森林位置","影风森林在哪里"}},{q="为什么奥拉凯斯邪教徒要伏击德鲁伊？",a="这些邪教徒的具体动机对埃雷加尔来说仍是一个令人不安的谜团。尽管长期以来他们被视为无害的狂热者，但他们突然且恶毒的暴动打破了岛上维持的脆弱平衡。",al={"邪教徒为何攻击","邪教动机","为何伏击德鲁伊"}}},fp="21,124,27.286.0,32.360.0,30.198.0,15.244.0,32.200.0,24.189.0,27.146.0,48.174.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="“The Ties That Bind”是影风森林中的一个任务，其核心在于德鲁伊教团内部的一场痛苦背叛。艾蕾加尔·荆爪发现失踪的教团德鲁伊哈林投靠了入侵的邪教徒并担任指挥官，于是下令将其处决。当亲人背叛了自己的种族时，这个任务揭示了履行职责所要付出的惨痛个人代价。",h="“The Ties That...",kw={"塞纳里奥议会","哈林指挥官","邪教徒","德鲁伊","艾蕾加尔·荆爪","哈林","影风森林","束缚的纽带"},ang={["class:Druid"]="塞纳里奥议会将维护平衡与亲缘视为神圣之事，因此哈林的背叛以及他在教团德鲁伊同僚之间造成的血腥杀戮，被视为对该组织尤为严重的冒犯。"},sec={{t="森林中的背叛",b="在影风森林深处，德鲁伊们遭遇了一群凶残的邪教徒，他们播撒着恐怖与鲜血。对于艾蕾加尔·荆爪来说，这场袭击因为一个痛苦的发现而变得更加沉重：在屠杀现场弥漫着前教团德鲁伊哈林的气息。哈林几个月前就失踪了，但他并没有在荒野中丧生，而是投靠了入侵的邪教徒，指挥他们对昔日的同胞发起了残酷的攻势。"},{t="血缘与羁绊",b="哈林的背叛不仅是违背了对塞纳里奥议会的誓言。当艾蕾加尔呈上这位阵亡指挥官的首级时，她透露哈林其实是她的表亲。尽管她对他的暴行感到愤怒，但亲手处决自己的亲人依然是她独自难以承受的重担。他的死为这个恶行导致无数无辜生命逝去的叛徒画上了一个血腥的句号。"}},faq={{q="谁提供了“羁绊”这个任务？",a="艾蕾加尔·荆爪是一名驻扎在影风森林的德鲁伊。在应对邪教徒入侵的过程中，她在发现哈林指挥官参与了屠杀后，指引冒险者去将他除掉。",al={"谁给予羁绊任务","影风森林任务发布者","谁是艾蕾加尔·荆爪"}},{q="哈林指挥官是谁？",a="哈林指挥官曾是塞纳里奥议会的一名德鲁伊，在邪教徒袭击前几个月失踪。他并没有成为步步逼近的黑暗的受害者，而是主动加入了敌对的邪教徒，并指挥他们的军队对抗自己的同胞。",al={"谁是哈林","哈林指挥官背景故事","哈林背景"}},{q="为什么艾蕾加尔想要哈林指挥官死？",a="哈林背弃了他的德鲁伊教团，指挥邪教徒屠杀无辜生命，并沾染了同僚的鲜血。由于他的所作所为以及对森林构成的威胁，艾蕾加尔下令将他处决。",al={"为什么要杀死哈林","哈林的罪行","哈林做了什么"}},{q="艾蕾加尔·荆爪和哈林之间有什么关系？",a="哈林指挥官是艾蕾加尔·荆爪的表亲。虽然她对他的罪行深感愤怒，但她承认，亲手处决自己的血亲将是一个沉重的负担，因此她决定请求冒险者的帮助。",al={"艾蕾加尔和哈林的关系","艾蕾加尔和哈林是如何认识的"}},{q="为什么邪教徒会出现在影风森林？",a="邪教徒出现在影风森林的确切动机即便是当地德鲁伊也感到困惑。然而，他们的队伍是由像哈林这样的前教团成员带头的，正是他指挥了针对森林守护者的暴力与屠杀。",al={"影风森林的邪教徒","为什么邪教徒在影风森林"}},{q="这个任务发生在什么地方？",a="任务事件发生在影风森林内，艾蕾加尔·荆爪在那里调查邪教徒的入侵，并面对表亲背叛的残酷现实。",al={"羁绊发生在哪里","影风森林位置"}}},fp="18,192,22.310.0,17.349.1,40.171.0,25.191.0,45.206.0,60.166.0,50.198.0,33.133.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="The Wounds of Betrayal 是影风森林中的一个任务，围绕着针对稀有的辛多雷德鲁伊的惨烈袭击后的余波展开。伊莱加尔派遣玩家将紧急草药膏送到夜牙洞穴，救治她受伤的同胞，并寻找失踪的伴侣乔雷尔·风歌。这次任务很快揭示了背叛带来的苦涩代价，并引发了针对奥拉凯斯的复仇冲突。",h="The Wounds of Betrayal...",kw={"奥拉凯斯","德鲁伊","伊莱加尔","乔雷尔·风歌","夜牙洞穴","影风森林","辛多雷","背叛的伤痕"},ang={["class:Druid"]="作为荒野的德鲁伊守护者，目睹同道修行者——特别是稀有的辛多雷德鲁伊——屈服于背叛和重伤，背负着沉重的个人情感负担。",["race:NightElf"]="暗夜精灵崇尚德鲁伊传统，这使得影风森林中同胞德鲁伊的苦难以及与背叛的斗争产生了深刻的共鸣。"},sec={{t="对辛多雷的援助",b="The Wounds of Betrayal 始于伊莱加尔，一位在影风森林中处理毁灭性袭击后果的辛多雷德鲁伊。在匆忙准备了药用草药膏后，她急需一名冒险者将援助送到撤退至附近夜牙洞穴的同胞手中，那里就在穿过空地的北面。辛多雷德鲁伊的人数极其稀少，因此每一位成员的幸存对于他们脆弱的聚居地来说都至关重要。"},{t="寻找乔雷尔·风歌",b="除了为洞穴中七位受伤的德鲁伊提供紧急救治外，伊莱加尔心中还有一个恳求：寻找她的伴侣乔雷尔·风歌。当她为了准备药物而逃离战斗时，乔雷尔已是奄奄一息。冒险深入夜牙洞穴的黑暗深处，揭示了圣地所遭受的真正破坏，以及乔雷尔所面临的残酷命运。"},{t="复仇誓言",b="在得知乔雷尔的悲惨结局以及同胞们遭受的恐怖伤亡后，伊莱加尔的冷静因悲痛与愤怒而崩塌。她咬牙切齿，带着痛苦的咆哮，摒弃了绝望，转而寻求彻底的报复，发誓任何与阴影中的奥拉凯斯结盟的人，都将因屠杀她的族人而遭受她无情的愤怒。"}},faq={{q="是谁发布了 背叛之伤 任务？",a="该任务由伊莱加尔发布，她是一位辛多雷德鲁伊，在影风森林发生暴力袭击后，正绝望地试图救治她受伤的同胞。",al={"谁发布了 背叛之伤","背叛之伤 任务发布者","伊莱加尔是谁"}},{q="夜牙洞穴位于哪里？",a="夜牙洞穴是一个位于影风森林穿过空地北面的洞穴，受伤的辛多雷德鲁伊已撤退至此寻求庇护。",al={"夜牙洞穴在哪里","夜牙洞穴位置","受伤的德鲁伊在哪里"}},{q="乔雷尔·风歌是谁？",a="乔雷尔·风歌是伊莱加尔的伴侣。他在袭击中身受重伤并留在了夜牙洞穴内，玩家会在那里发现他悲惨的命运。",al={"乔雷尔·风歌是谁","乔雷尔·风歌的命运","乔雷尔在哪里"}},{q="什么是辛多雷德鲁伊？",a="辛多雷是一个稀有的群体，其中只有极少数德鲁伊修行者。由于他们人数稀少，伊莱加尔强调，他们当中幸存的每一个生命都极其珍贵。",al={"什么是辛多雷","谁是辛多雷德鲁伊","辛多雷德鲁伊背景故事"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是应对袭击或与袭击德鲁伊者结盟的敌人。在得知乔雷尔的命运和她教派所受的毁灭性打击后，伊莱加尔发誓要向奥拉凯斯及其任何盟友复仇。",al={"谁是奥拉凯斯","奥拉凯斯","伊莱加尔为何憎恨奥拉凯斯"}},{q="在任务中乔雷尔·风歌发生了什么？",a="当你找到夜牙洞穴中的乔雷尔·风歌时，你发现他的情况发生了悲剧性的转变。带着他的命运以及幸存德鲁伊的严峻处境的消息返回找伊莱加尔，使她陷入了悲痛，并立下了愤怒的复仇誓言。",al={"乔雷尔·风歌发生了什么","乔雷尔还活着吗","乔雷尔的结局"}}},fp="22,202,22.265.0,31.307.1,20.247.2,43.111.0,31.123.0,24.120.0,31.101.0,21.214.0,46.206.0"}
P.entries["quest:94490"] = {n="Ripped Missive",s="Ripped Missive是从Haalien身上找回的一封血迹斑斑的信件，它揭示了一场针对影风森林中一座德鲁伊大兽穴的残酷邪教徒袭击。信中的内容揭露了这场屠杀背后冷酷的动机，并暗示了源自瓦拉纳尔内部的危险颠覆活动。",h="Ripped Missive是从Haalien身上找回的一封血迹斑斑的信件，它揭示了一场针对影风森林中一座德鲁伊大兽穴的残酷邪教徒袭击。信中的内容揭露了这场屠杀背后冷酷的动机，并暗示了源自瓦拉纳尔内部的危险颠覆活动。",kw={"邪教徒","德鲁伊大兽穴","艾勒盖尔·棘爪","哈利恩","洛瑟鲁姆","晶塔","撕破的信件","影风森林","瓦拉纳尔"},ang={["class:Druid"]="德鲁伊们会在这封信中发现悲惨的苦果，信中揭露了在大兽穴中被屠杀的德鲁伊仅仅是因为挡了那些寻找远古晶塔的邪教徒的路。"},sec={{t="血迹斑斑的命令",b="这份破损且沾满血迹的文件被塞在Haalien的护腕后面，其中包含有关最近影风森林中发生的暴力事件的严峻情报。在激烈的冲突后找回，这片文字揭示了袭击当地德鲁伊大兽穴的邪教徒的阴暗意图，为那些寻求为死者伸张正义的人提供了重要的线索。"},{t="无谓的屠杀",b="当把这张羊皮纸交给影风森林的Elegael Thornpaw时，这次突袭的可怕真相大白了。邪教徒并非因为与德鲁伊有特定的积怨才发动袭击；他们是为了寻找一座神秘的晶塔，仅仅因为大兽穴的居民挡了他们的路就将其杀害。Elegael对这场无谓的屠杀感到愤怒，誓要向森林中残留的任何邪教徒复仇。"},{t="瓦拉纳尔的背叛",b="除了揭示邪教徒对晶塔的关注外，这封信还带来了一个更令人震惊的消息：指令似乎直接源自瓦拉纳尔。这一严峻的事实指向了在定居点内部活动的叛徒。为了在更多生命逝去之前揭露这个阴谋，必须立即将此信件送到瓦拉纳尔的Lotheluum手中。"}},faq={{q="什么是撕破的信件？",a="撕破的信件是一封在战斗后发现被塞在哈利恩护腕后面的血迹斑斑、破损的信件。它包含揭露邪教徒袭击影风森林德鲁伊大兽穴动机的关键情报。",al={"什么是撕破的信件","撕破的信件任务","血迹斑斑的便条 哈利恩"}},{q="这封信是从哪里找回的？",a="这封信是直接从哈利恩身上找回的，是在一场激烈的对峙后发现被塞在他们的一个护腕后面。信件在战斗中受损并沾染了血迹。",al={"谁掉落了撕破的信件","撕破的信件来自哪里","哈利恩是谁"}},{q="谁应该收到撕破的信件？",a="这封信最初被带给影风森林的埃雷加尔·荆爪。在阅读了这份文件后，埃雷加尔指示将其迅速送到瓦拉纳尔的洛瑟鲁姆手中，以警告潜在的背叛。",al={"谁需要撕破的信件","我应该把撕破的信件交给谁","艾勒盖尔·棘爪 信件"}},{q="为什么邪教徒袭击德鲁伊大兽穴？",a="信件揭示，邪教徒袭击德鲁伊大兽穴并非出于对德鲁伊本身的仇恨，而是为了夺取位于那里的一座晶塔。居住在其中的德鲁伊仅仅因为挡在邪教徒的路上就被无情地杀害了。",al={"为什么邪教徒袭击德鲁伊大兽穴","邪教徒在大兽穴的动机","为什么哈利恩发动袭击"}},{q="袭击命令源自何处？",a="信件表明邪教徒的指令源自瓦拉纳尔，暗示有一名叛徒正隐藏在定居点内部并策划行动。",al={"命令来自哪里","谁派遣了哈利恩","瓦拉纳尔的叛徒"}},{q="洛瑟鲁姆是谁，为什么要通知他们？",a="洛瑟鲁姆是位于瓦拉纳尔的一位联系人。埃雷加尔·荆爪命令冒险者将这封信带给洛瑟鲁姆，提醒他们邪教徒的致命指令可以追溯到隐藏在瓦拉纳尔的某个人。",al={"洛瑟鲁姆是谁","为什么要把信件带给洛瑟鲁姆","洛瑟鲁姆 瓦拉纳尔"}}},fp="14,167,19.240.0,19.260.1,21.250.2,27.155.0,36.126.0,38.158.0,42.114.0,38.96.0,47.166.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="《大兽穴的命运》讲述了邪教徒突袭隐秘德鲁伊大兽穴后的惨烈余波。一位冒险者被派遣将一份寻获的信件送往瓦拉纳尔的洛瑟鲁姆，带去伤亡惨重的消息。这份公文揭露了一个令人深感不安的事实：瓦拉纳尔内部有人一直向敌人提供关键情报。",h="《大兽穴的命运》讲述了邪教徒突袭隐秘德鲁伊大兽穴后的惨烈余波。一位冒险者被派遣将一份寻获的信件送往瓦拉纳尔的洛瑟鲁姆，带去伤亡惨重的消息。这份公文揭露了一个令人深感不安的事实：瓦拉纳尔内部有人一直向敌人提供关键情报。",kw={"邪教徒","德鲁伊大兽穴","大长老","洛瑟鲁姆","信件","大兽穴的命运","叛徒","瓦拉纳尔"},ang={["class:Druid"]="德鲁伊们深刻地感受到了这场悲剧的沉重，因为在大兽穴倒下的是他们的同伴，而他们隐秘的避难所却被背叛给了敌对的邪教徒。"},sec={{t="大兽穴的惨剧",b="在邪教徒对德鲁伊大兽穴发动暴力入侵后，幸存的守卫者们饱受摧残，哀悼着同伴的逝去。尽管在外部援助下，紧迫的危机得到了控制，但无论是肉体上还是精神上的创伤都极其巨大。倒下的人无法复生，而身负重伤的幸存者在附近仍有残留邪教徒徘徊的情况下，也无力进行长途跋涉。"},{t="瓦拉纳尔的背叛",b="一份寻获的信件证实，邪教徒并非随机行事；瓦拉纳尔内有人一直潜伏其中，向他们积极泄露情报。当洛瑟鲁姆看到这份公文时，他对同伴的屠杀以及有人在他们的定居点内逍遥法外这一恐怖暗示感到极其惊恐。他下定决心不能让他们的牺牲被遗忘，于是将证据直接呈交给了大长老。"}},faq={{q="洛瑟鲁姆是谁？",a="洛瑟鲁姆是瓦拉纳尔的一位人物，负责接收有关德鲁伊大兽穴的报告。在得知袭击事件并审阅了那份寻获的信件后，他为阵亡的同伴深感悲痛，并发誓要将背叛的证据直接呈交给大长老。",al={"洛瑟鲁姆","洛瑟鲁姆是谁","洛瑟鲁姆非玩家角色"}},{q="德鲁伊大兽穴发生了什么？",a="德鲁伊大兽穴遭到了敌对邪教徒的毁灭性打击，导致多名守卫者死亡。尽管在一位冒险者的帮助下消除了直接威胁，但幸存的保护者们已伤痕累累，并发现了这次袭击是在内部人员指引下进行的证据。",al={"大兽穴发生了什么","德鲁伊大兽穴袭击","大兽穴的命运背景故事"}},{q="那份寻获的信件揭露了什么？",a="信件揭露，潜伏在瓦拉纳尔定居点内的一名内应一直在秘密向邪教提供情报。这些情报表明，针对大兽穴的致命突袭正是通过当地的破坏活动和间谍行为才得以实现。",al={"信件说了什么","大兽穴信件","背叛信件"}},{q="洛瑟鲁姆提到的大长老是谁？",a="大长老是瓦拉纳尔的一位显赫权威，洛瑟鲁姆向其负责。由于伤亡惨重且面临现行叛徒的威胁，洛瑟鲁姆立即将信件和惨剧的消息上报给了大长老。",al={"大长老是谁","瓦拉纳尔大长老","大长老"}},{q="谁该为袭击德鲁伊大兽穴负责？",a="这次袭击是由在该地区活动的邪教成员执行的。多亏了瓦拉纳尔内部一名内应的指引，邪教徒成功对大兽穴的居民造成了灾难性的损失。",al={"谁袭击了大兽穴","谁袭击了德鲁伊大兽穴","大兽穴邪教徒"}},{q="为什么大兽穴的幸存者不能亲自递送信件？",a="大兽穴的幸存者在袭击后伤势过重，无法承受前往瓦拉纳尔的长途跋涉。除了身体状况不适合赶路之外，幸存者还留下来清除残余的邪教徒，并派出一名冒险者前去报信。",al={"为什么要递送信件","任务发布者受伤","为什么幸存者不能去瓦拉纳尔"}}},fp="19,269,18.340.0,21.379.1,17.202.0,31.204.0,39.171.0,45.194.0,48.164.0,69.180.0"}
P.entries["quest:94493"] = {n="A Sacrifice in Vain",s="Elegael Thornpaw担心奥拉凯斯教徒会击溃她大兽穴中受伤的同伴。原本要送往瓦拉纳尔的消息没有送达，她只得求助。",h="Elegael Thornpaw担心奥拉凯斯教徒会击溃她大兽穴中受伤的同伴。原本要送往瓦拉纳尔的消息没有送达，她只得求助。",kw={"徒劳的牺牲","奥拉凯斯教徒","大兽穴","艾蕾盖尔·棘爪","援军","瓦拉纳尔","伤者"},sec={{t="求援",b="奥拉凯斯教徒几乎毫无预警地袭击了Elegael Thornpaw的同伴。她的巢穴里许多人受了伤，或是濒临死亡，她不知道他们还能撑多久。她曾试着向瓦拉纳尔送信，但消息没能送达。援军迟迟不见踪影，Elegael请求你帮忙。"}},faq={{q="谁在求助？",a="奥拉凯斯教徒正在袭击埃雷加尔·荆爪的同伴，她因此请求援助。",al={"谁需要帮助","艾勒盖尔·棘爪","艾勒盖尔"}},{q="大兽穴里的人遭遇了什么？",a="奥拉凯斯教徒几乎毫无预警地伏击了他们。许多人受了伤，或已奄奄一息。",al={"大兽穴伤者","这里发生了什么","教徒袭击"}},{q="瓦拉纳尔为什么没有派来援军？",a="埃雷加尔的消息没有送达瓦拉纳尔，因此援军尚未抵达。",al={"援军在哪里","瓦拉纳尔来信","致瓦拉纳尔的消息"}},{q="埃雷加尔需要什么？",a="埃雷加尔请求你帮助受伤的同伴，在奥拉凯斯教徒的袭击中活下来。",al={"如何提供帮助","帮助艾勒盖尔","她请求什么"}}},fp="19,163,14.316.0,23.75.0,39.83.0,41.77.0,23.83.0"}
P.entries["quest:94494"] = {n="水之召唤",s="“水之召唤”是一项精神试炼，旨在让萨满祭司能够与水元素的净化本质进行沟通。在与风、地、火元素达成和谐后，受训者将前往洛克莫丹寻找诺里克·洛克塔恩，他会敦促受训者迈出学习水之纯净的第一步。",h="“水之召唤”是一项精神试炼，旨在让萨满祭司能够与水元素的净化本质进行沟通。在与风、地、火元素达成和谐后，受训者将前往洛克莫丹寻找诺里克·洛克塔恩，他会敦促受训者迈出学习水之纯净的第一步。",kw={"水之召唤","元素","大山","纯净","萨满","图腾试炼","水之图腾"},ang={["class:Shaman"]="这项试炼标志着与元素灵魂调谐的基本步骤，从大地和火焰开始，进而理解水的流动性与纯净。",["race:Dwarf"]="导师那粗犷的矮人语调反映了矮人萨满是如何通过崎岖的山路来与自然进行沟通的。"},sec={{t="纯净之道",b="“水之召唤”是萨满祭司元素平衡之旅中至关重要的一步。随着大地让每一步变得扎实，狂风在身后呼啸，心中的火焰熊熊燃烧，旅行者被召唤去领悟水的深层本质。它不仅是一种外部力量，更是纯净与坚韧的精神体现。"},{t="元素的飞升",b="在一位有着山峰般稳重语调的资深导师的指引下，受训者被催促着毫不犹豫地前进。萨满的共鸣从不会轻易授予；它需要肉体的努力、坚韧的精神以及对崎岖地形的攀登。正如导师所警告的那样，大山不会等待任何人，通往真正理解的旅程必须从那决定性的第一步开始。"}},faq={{q="什么是水之召唤？",a="“水之召唤”代表了萨满祭司寻求与水元素沟通的精神洗礼。在已经领悟了大地之稳固、风之疾驰和火焰之火花后，请求者被召唤去学习水之深层真理。",al={"什么是水之召唤","水之召唤任务","这个任务是什么"}},{q="谁指引了这段旅程？",a="铁炉堡的萨满训练师艾尔德兰·风暴断裂者将受训者指引至洛克莫丹的诺里克·洛克塔恩处。诺里克说了这番话，敦促受训者采取果断行动，并提醒旅行者，元素与高地不会等待犹豫不决的人。",al={"谁给予水之召唤","谁说大山不会等待任何人","水之召唤导师"}},{q="“大山不会等待任何人”是什么意思？",a="这是迈出艰苦攀登第一步的号召。萨满的旅程往往通向灵魂居住的高峰和偏远荒野，这需要坚定的决心，而不是徘徊不定的怀疑。",al={"大山不会等待任何人是什么意思","大山不会等待任何人","大山的含义"}},{q="水之纯净的真理是什么？",a="在萨满的修行中，每种元素都提供独特的教导。如果说岩石提供了稳定性，火焰点燃了决心，那么水则体现了净化、流动与纯净——这是平衡内心灵魂的重要智慧。",al={"为什么是水之纯净","水之纯净的真理","水元素的含义"}},{q="在这里水与其他元素有何关联？",a="这段旅程承认大地、风和火是已经在脚步、呼吸和腹中感受到的基础，然后才接触水。与元素和谐共处需要掌握平衡，而不是孤立地追求单一的力量。",al={"哪些元素优先","水的先决条件","水之召唤元素"}},{q="受训者听完这些话后要去哪里？",a="受训者必须迈出第一步。诺里克·洛克塔恩会派他们前往湿地，寻找住在南部瀑布下方洞穴里的赫夫达娜·萨格伦德，以获取水之水塔。",al={"水之召唤下一步会发生什么","我现在要去哪里","水之召唤的下一步"}}},fp="13,164,18.179.0,24.227.0,26.141.0,36.205.0,53.171.0,36.156.0,49.173.0,53.148.0"}
P.entries["quest:94495"] = {n="水之召唤",s="“水之召唤”将精神探索者派遣至湿地，去领悟水的净化之力并寻找水之萨普塔。在南侧瀑布下方的一处隐蔽洞穴中，矮人赫薇达娜·萨格伦德迎接那些勇闯荒野的旅者。",h="“水之召唤”将精神探索者派遣至湿地，去领悟水的净化之力并寻找水之萨普塔。在南侧瀑布下方的一处隐蔽洞穴中，矮人赫薇达娜·萨格伦德迎接那些勇闯荒野的旅者。",kw={"水之召唤","矮人","赫薇达娜·萨格伦德","萨满祭司","南侧瀑布","水之灵契","湿地"},ang={["class:Shaman"]="该任务是学习水的本质并获取水之萨普塔以与水之灵沟通的重要一步。",["faction:Alliance"]="这段旅程将旅者带入危险的湿地深处，远离任何矮人或联盟的巡逻队。",["race:Dwarf"]="赫薇达娜认出这位寻求者是敢于在危险的沼泽地和潜伏的黑铁矮人面前闯荡的同胞。"},sec={{t="水的本质",b="理解水的旅程始于关于其双重本质的简单课程：水象征着重生，在纯净时能切石净污，但一旦被污染，它便会带来毁灭。寻求沟通的初学者被派遣到野外，从那些栖居于水元素旁的人那里获取水之萨普塔。"},{t="瀑布下的庇护所",b="在湿地潮湿的沼泽深处，赫薇达娜·萨格伦德和她的家人居住在一个直接位于南侧瀑布下方的隐蔽洞穴中。他们远离铁炉堡卫兵的保护，忍受着潜伏在周围沼泽中的黑铁矮人的威胁，以维持他们在奔流瀑布旁的隐居生活。"}},faq={{q="赫薇达娜·萨格伦德是谁？",a="赫薇达娜·萨格伦德是一位矮人，她与家人住在湿地南侧瀑布下方的一个洞穴里。她帮助那些寻求与水沟通以及探索水之萨普塔秘密的萨满祭司。",al={"赫薇达娜是谁","赫薇达娜·萨格伦德","赫薇达娜在哪里"}},{q="什么是水之萨普塔？",a="水之萨普塔是萨满祭司用来与水之灵沟通的一种仪式药剂。在东部王国，寻求者会被指引去南侧瀑布附近找赫薇达娜·萨格伦德获取此物。",al={"什么是水之萨普塔","萨普塔含义","为什么要获取水之萨普塔"}},{q="在哪里可以找到赫薇达娜·萨格伦德？",a="赫薇达娜和她的家人隐居在湿地南侧瀑布正下方的一个洞穴里。",al={"赫薇达娜住在哪里","洞穴在哪里","南侧瀑布位置"}},{q="为什么赫薇达娜要住在危险的湿地？",a="尽管沼泽中潜伏着黑铁矮人，且完全没有城市守卫的保护，赫薇达娜和她的族人出于各自的原因，选择了这个瀑布洞穴作为隐居之所。",al={"为什么住在湿地","湿地的危险","湿地的黑铁矮人"}},{q="这里传授的水的课程是什么？",a="水代表着重生，在纯净时可以切开岩石、洗净污垢、安抚疲惫。然而，如果受到腐蚀或污染，它会摧毁所触及的一切。",al={"水意味着什么","水的哲学","水的课程"}},{q="“水之召唤”任务的目的是什么？",a="“水之召唤”是萨满祭司的一项成人仪式，引导初学者理解水元素的本质，并从隐居的向导那里寻找水之萨普塔。",al={"这是什么类型的任务","这是为谁准备的任务","矮人萨满任务"}}},fp="13,172,19.234.0,25.277.0,25.191.0,24.183.0,37.114.0,49.167.0,40.130.0,47.114.0"}
P.entries["quest:94497"] = {n="水之召唤",s="“水之召唤”是在湿地进行的一项精神任务，指引修行者走上获取萨普塔的道路。通过在山间瀑布与海潮交汇的咸淡水入海口收集水源，寻求者在穿越沼泽的危险时，也能领悟到水的生命能量。",h="“水之召唤”是在湿地进行的一项精神任务，指引修行者走上获取萨普塔的道路。通过在山间瀑布与海潮交汇的咸淡水入海口收集水源，寻求者在穿越沼泽的危险时，也能领悟到水的生命能量。",kw={"水之召唤","黑铁矮人","入海口","赫瓦娜","萨普塔","水囊","湿地"},ang={["class:Shaman"]="寻求萨普塔需要理解不同土地上水的本质，使精神与水的各种表现形式相调和。",["race:Dwarf"]="赫瓦娜感叹着矮人氏族之间挥之不去的分裂，尤其是当黑铁矮人甚至入侵到湿地这样偏北的地方时。"},sec={{t="萨普塔之道",b="为了获得萨普塔并与灵魂沟通，修行者必须寻找各种形态的水。赫瓦娜指引寻求者观察水是如何流动、如何改变生命以及滋养大地。这段旅程始于理解入海口的水，那里是大海的潮汐与高地淡水径流汇合之处。"},{t="淡水与咸水交汇之处",b="在赫瓦娜洞穴下方的瀑布底部，高地泉水流入沼泽，与被海潮带入内陆的咸水相撞。海潮携带的沉积物、矿物质和能量与清澈的山间融雪截然不同，这使得入海口成为了自然智慧的源泉。"},{t="沼泽中的阴影",b="在湿地收集水源并非没有危险。除了危险的沼泽生物外，黑铁矮人也已经向北推进，进入了令人不安的距离。赫瓦娜怀着遗憾注视着矮人氏族之间持续不断的敌对状态，并感叹如果他们能放下世仇，矮人一族本可以取得多么伟大的成就。"}},faq={{q="什么是萨普塔？",a="萨普塔是一种用于与元素之灵沟通的神圣饮品。为了获得它，修行者必须寻找各种状态的水，并理解它如何塑造大地以及滋养万物。",al={"什么是萨普塔","萨普塔的含义","为何寻找萨普塔"}},{q="赫瓦娜是谁？",a="赫瓦娜在她位于湿地瀑布上方的洞穴中发布这项任务。她作为向导，指引修行者收集水样，以使他们与元素调和。",al={"谁发布水之召唤","赫瓦娜在哪里","赫瓦娜的洞穴"}},{q="为什么要收集淡水与咸水交汇处的水？",a="入海口的水代表了一种特殊的汇流，高地融雪和淡水泉水在此与海潮混合。这种淡水与富含矿物质的咸水的碰撞，携带了独特的沉积物和精神智慧。",al={"为何选择入海口的水","湿地的咸淡水","淡水与盐水的汇合"}},{q="瀑布附近潜伏着什么危险？",a="黑铁矮人已经潜入北方的湿地，对于试图进入沼泽和瀑布的旅行者和元素寻求者来说，他们构成了现实的威胁。",al={"湿地里的黑铁矮人","为什么黑铁矮人会在这里","黑铁矮人的威胁"}},{q="成为一名“容器”意味着什么？",a="“容器”是指已经开始积极寻求水的智慧，并携带大自然的水作为祭品，以发展更深层次元素调和的修行者。",al={"什么是容器","水的容器"}},{q="空的棕色水囊有什么用途？",a="空的棕色水囊是赫瓦娜提供的容器，用于从沼泽瀑布底部收集咸淡水样本。",al={"空的棕色水囊的使用方法","使用了什么水囊"}}},fp="13,176,20.273.0,26.308.0,20.248.0,18.191.0,16.149.0,52.128.0,38.136.0,37.126.0,43.116.0"}
P.entries["quest:94499"] = {n="水之召唤",s="“水之召唤”是一项任务，要求旅行者前往赤脊山的石堡瀑布，调查止水湖的流水是否存在污染。萨满祭司需要装满一个空的红色水囊并将其带回湿地的赫尔达娜·萨格伦德，从而揭示当地鱼人变异的真正原因，并为他们的精神试炼获得一种关键试剂。",h="“水之召唤”是一项任务，要求旅行者前往赤脊山的石堡瀑布，调查止水湖的流水是否存在污染。萨满祭司需要装满一个空的红色水囊并将其带回湿地的赫尔达娜·萨格伦德，从而揭示当地鱼人变异的真正原因，并为他们的精神试炼获得一种关键试剂...",kw={"水之召唤","赫尔达娜·萨格伦德","止水湖","夜行鱼人","赤脊山","药剂","暗影巫师","石堡瀑布","湿地"},ang={["class:Shaman"]="这项任务是酿造水之药剂的关键一步，在与水之灵沟通之前，考验萨满祭司跨越遥远水域的奉献精神和感知力。"},sec={{t="可疑的瀑布",b="位于湿地的赫尔达娜·萨格伦德派遣有志成为萨满祭司的冒险者前往赤脊山，调查从石堡瀑布倾泻而下的水流。虽然止水湖为湖畔镇的居民提供了纯净的水源，但潜伏在瀑布底部的鱼人却变得异常巨大且扭曲。赫尔达娜怀疑是毒素、邪恶法术或者上方古老堡垒的渗漏导致了这一切，因此要求旅行者用空的红色水囊采集样本。"},{t="污染的真正源头",b="在检查了装满的水囊后，赫尔达娜发现从止水湖倾泻而下的水完全干净，并未受到任何污染。当地夜行鱼人所表现出的身体扭曲并非由受到污染的水源引起，而是石堡周围潜伏的暗影巫师所施展的黑暗法术所致。该样本既证明了瀑布的纯净，也考验了萨满祭司的奉献精神，它是酿造精神药剂所必需的关键试剂。"}},faq={{q="谁发布了这个任务，他们位于何处？",a="位于湿地的赫尔达娜·萨格伦德发布了此项任务。她致力于研究水资源以及酿造萨满祭司精神试炼所需药剂的试剂。",al={"谁发布水之召唤","任务发布者赫尔达娜"}},{q="为什么会被派去从石堡瀑布采集水？",a="赫尔达娜怀疑奇怪的毒素、黑暗魔法或污染可能正从上方的旧堡垒渗透过石堡瀑布，导致瀑布底部的鱼人畸变。她需要一份新鲜的样本来进行检查。",al={"为什么要在赤脊山装满水囊","石堡瀑布的目的"}},{q="石堡瀑布的水真的受到污染了吗？",a="没有，水本身证明是完全纯净且未受污染的。赫尔达娜断定，当地鱼人的扭曲状态是源于当地暗影巫师施展的黑暗魔法，而不是因为受污染的径流。",al={"石堡的水是否受到污染","止水湖是否受到腐蚀"}},{q="为什么石堡瀑布周围的鱼人如此巨大且扭曲？",a="与洛克湖或湿地的鱼人相比，瀑布底部的夜行鱼人更为巨大且扭曲。赫尔达娜得出结论，这种变化是当地暗影巫师的邪恶魔法所导致的。",al={"为什么赤脊山的鱼人会变异","石堡鱼人的不同之处"}},{q="水样本是用来做什么的？",a="药剂是一种仪式性的混合物，能让萨满祭司穿透帷幕，感知元素之灵。赫尔达娜从各种水域收集纯净样本，以酿造你需要的那种试剂。",al={"什么是药剂","水之召唤奖励的用途"}},{q="诺瑞克是谁？",a="诺瑞克是参与萨满试炼的伙伴或导师，赫尔达娜提到他会对你成功取回纯净水样本感到满意。",al={"谁是诺瑞克","诺瑞克水之召唤"}}},fp="13,154,17.377.0,29.321.1,48.155.0,56.206.0,50.111.0,65.166.0,34.165.0,14.135.0"}
P.entries["quest:945"] = {n="护送瑟瑞露尼",s="在黑海岸南部，一位名叫瑟瑞露尼的年轻暗夜精灵误入了阴森的主宰之剑挖掘场，并被敌对的邪教徒包围。需要联盟护送她到安全地带，并将她幸存的消息告诉她担忧的姐姐瑟瑞希尔，她正在艾森娜神殿休息。",h="在黑海岸南部，一位名叫瑟瑞露尼的年轻暗夜精灵误入了阴森的主宰之剑挖掘场，并被敌对的邪教徒包围。需要联盟护送她到安全地带，并将她幸存的消息告诉她担忧的姐姐瑟瑞希尔，她正在艾森娜神殿休息。",kw={"灰谷","邪教徒","护送","主宰之剑","艾森娜神殿","瑟瑞露尼","瑟瑞希尔","暮光之锤"},ang={["faction:Alliance"]="帮助像瑟瑞露尼这样受困的旅人，能巩固联盟在保卫灰谷的暗夜精灵中的存在感和善意。",["race:NightElf"]="主宰之剑是卡利姆多历史上的一道古老伤疤。看到你的同胞卡多雷毫无防备地闯入邪教徒的挖掘场，是一个令人清醒的警示，提醒着灰谷内部潜伏的威胁。"},sec={{t="危险的漫步",b="主宰之剑是黑海岸最令人不安的地标之一，那里有一具被巨大的石刃贯穿的古代怪物的巨大头骨。尽管山谷中弥漫着恐惧，瑟瑞露尼还是误闯进了峡谷深处。她很快就被暮光之锤的邪教徒困住，仅凭敏捷的反应和在崎岖地形中隐藏的天赋才得以幸存。"},{t="送往神殿的消息",b="瑟瑞露尼的姐姐瑟瑞希尔住在遥远的南方，平静的艾森娜神殿。虽然瑟瑞露尼以爱冒险且不介意弄脏衣服而闻名，但她冒险进入主宰之剑那令人不适的挖掘场，这让她的亲人都感到震惊。带来瑟瑞露尼平安的消息可以宽慰她那深受困扰的姐姐，她深知目前正在黑海岸的古老土地上挖掘的黑暗势力。"}},faq={{q="瑟瑞露尼是谁？",a="瑟瑞露尼是一位爱冒险的年轻暗夜精灵，她误入了黑海岸南部主宰之剑危险的挖掘场。她是瑟瑞希尔的妹妹。",al={"瑟瑞露尼","这个女孩是谁","受困的精灵"}},{q="瑟瑞希尔是谁？",a="瑟瑞希尔是瑟瑞露尼的姐姐，驻扎在灰谷宁静的艾森娜神殿。得知她的妹妹竟然游荡到如此黑暗且被污染的地方附近，她感到非常不安。",al={"瑟瑞希尔","瑟瑞露尼的姐姐"}},{q="为什么主宰之剑如此危险？",a="主宰之剑是一处古老且不祥的峡谷，很久以前有一位古老的“古老领主”陨落于此。暮光之锤的邪教徒蜂拥至该区域，大肆挖掘遗迹并攻击任何入侵者。",al={"主宰之剑的危险","主宰之剑的邪教徒"}},{q="瑟瑞露尼需要被护送到哪里？",a="瑟瑞露尼需要护送以离开主宰之剑的直接包围圈前往安全地带，之后拯救者必须前往艾森娜神殿通知她的姐姐。",al={"护送目的地","瑟瑞露尼去哪了"}},{q="艾森娜神殿位于哪里？",a="艾森娜神殿位于灰谷西南部，阿斯特兰纳以西，是供奉森林之魂艾森娜的圣地。",al={"艾森娜神殿的位置","瑟瑞希尔在哪"}},{q="瑟瑞露尼在邪教徒的包围下是如何幸存的？",a="瑟瑞露尼能在周围的暮光之锤邪教徒发现她之前，找到岩石和地形间一个隐蔽的藏身处，从而得以避免被抓。",al={"瑟瑞露尼如何躲藏"}}},fp="18,189,17.304.0,18.371.0,17.159.0,16.156.0,40.167.0,41.143.0,39.130.0,49.129.0"}
P.entries["quest:94500"] = {n="Call of Water",s="水之召唤要求冒险者深入灰谷翠绿的树冠之下，从环抱阿斯特兰纳的湖泊中采集纯净而古老的水。这是最后一步采集任务，完成后，旅人便会被派回Norric那里。",h="水之召唤要求冒险者深入灰谷翠绿的树冠之下，从环抱阿斯特兰纳的湖泊中采集纯净而古老的水。这是最后一步采集任务，完成后，旅人便会被派回Norric那里。",kw={"灰谷","阿斯特兰纳","奥伯丁","水之召唤","米奈希尔","诺里克","南海镇","水囊"},ang={["faction:Alliance"]="这项任务引导旅行者沿着联盟的航海路线从东部王国前往卡利姆多，连接了米奈希尔港、奥伯丁以及暗夜精灵的定居点阿斯特兰纳。",["race:NightElf"]="这项任务指引旅人前往阿斯特兰纳周围的纯净水域，那里是卡多雷在灰谷的腹地之一，古老的废墟至今仍未受到侵扰。"},sec={{t="寻找纯净之水",b="水之召唤要求冒险者用灰谷未受污染的水装满水囊。寻水者必须前往阿斯特兰纳，这处庇护之所坐落在清澈而古老的湖水之间，湖水轻拍着往昔时代沉入水中的废墟。这份纯净的水样是任务给予者所需的最后一种液体，随后旅人便会被派往Norric那里。"},{t="通往阿斯特兰纳之路",b="要抵达灰谷深处，必须从东部王国渡海而行。建议旅人乘坐从米奈希尔港驶往奥伯丁的船只，途中会在南海镇停靠。从奥伯丁的码头出发，道路通向内陆，延伸至灰谷翠绿的枝叶之下，旅人被告诫要在林间窥伺的阴影中保持警惕。"}},faq={{q="水之召唤是什么任务？",a="水之召唤是一项要求旅人带着空水囊深入灰谷古老森林的任务。目标是从环抱阿斯特兰纳聚落的湖泊中，采集一份纯净、古老且可能蕴含魔力的水样，再将其交还给任务给予者。",al={"什么是水之召唤","水之召唤任务","水之召唤任务目标"}},{q="这项任务的水要在哪里采集？",a="必须从灰谷深处环绕阿斯特兰纳的湖泊中取水。那里的水依然未受污染，在往昔时代沉入水中的古老废墟间流淌。",al={"哪里有纯净之水","在哪里装满水囊","水之召唤地点"}},{q="如何前往灰谷完成这项任务？",a="建议旅行者从米奈希尔港搭乘船只前往奥伯丁，途中会在南海镇停留。从黑海岸的奥伯丁出发，向南前往灰谷深邃的翡翠森林，即可抵达阿斯特兰纳。",al={"如何前往阿斯特兰纳","前往灰谷","乘船前往阿斯特兰纳"}},{q="阿斯特兰纳的水有何特别之处？",a="环抱阿斯特兰纳的湖泊以水质未受污染而闻名。水面之下，沉没的石质废墟隐约诉说着精灵文明遥远的古老时代，也赋予这里的水纯净且可能蕴含魔力的特质。",al={"阿斯特兰纳的哪个湖泊","阿斯特兰纳水中废墟","阿斯特兰纳湖中废墟"}},{q="诺里克是谁？",a="采集完这最后一份液体样本后，等待旅人的便是诺里克。任务给予者将这份纯净的灰谷之水作为最后一种材料收下，随后便会派冒险者回到诺里克那里。",al={"诺里克是谁","返回诺里克处"}},{q="灰谷中有哪些危险？",a="灰谷是一片古老而茂密的森林，危机四伏。任务给予者告诫旅人时刻保持警惕，提醒他们在翠绿的树冠下行进时，林中有些眼睛始终注视着他们，从不眨眼。",al={"灰谷的危险","灰谷的威胁"}}},fp="13,126,25.233.0,21.285.0,32.174.0,44.137.0,44.197.0,42.188.0,14.146.0,42.147.0"}
P.entries["quest:94501"] = {n="Call of Water",s="“水之召唤”是萨满祭司追求神圣水之图腾仪式时的一场精神试炼。求道者需要将受Hervdana祝福的纯净水送到洛克莫丹的Norric Lochthane手中，以此准备与斯特登的池塘中的灵魂沟通所需的元素水之灵药。",h="“水之召唤”是萨满祭司追求神圣水之图腾仪式时的一场精神试炼。求道者需要将受Hervdana祝福的纯净水送到洛克莫丹的Norric Lochthane手中，以此准备与斯特登的池塘中的灵魂沟通所需的元素水之灵药。",kw={"水之召唤","赫芙达娜","洛克莫丹","月溪镇","诺里克·洛克塞恩","萨满祭司","斯特登的池塘","一瓶最纯净的水","水之灵契","水之图腾"},ang={["class:Shaman"]="这场试炼是与元素沟通以获得水之图腾仪式，并制作看见元素灵魂所需的水之灵药的关键一步。",["faction:Alliance"]="联盟萨满祭司跨越洛克莫丹和西部荒野，寻求与东部大地的水元素灵魂进行沟通。",["race:Dwarf"]="这段旅程将矮人萨满候选人与像Norric Lochthane这样遍布卡兹莫丹的元素导师连接了起来。"},sec={{t="通往水之图腾之路",b="“水之召唤”是渴望与水元素达成和谐的萨满祭司必须经历的精神感应试炼。踏上这条道路，需要收集由Hervdana亲自祝福的水，在将容器带给洛克莫丹的Norric Lochthane之前，以证明求道者对灵魂的耐心与敬畏。"},{t="水之灵药的诞生",b="在收到受祝福的容器后，Norric透露这些神圣的液体旨在酿造一种水之灵药。这种药水能让求道者洞穿虚妄，见到居住在月溪镇附近斯特登的池塘中的水元素灵魂。每一滴水都被视为珍宝，因为即使是湿润的塞子在神圣仪式中也大有用处。"}},faq={{q="谁是诺里克·洛克萨恩？",a="诺里克·洛克萨恩是一位居住在洛克莫丹的导师，他引导候选人完成元素感应。他负责监督获得水之图腾所需的准备工作和仪式。",al={"谁是诺里克","诺里克 洛克莫丹","谁是诺里克·洛克萨恩"}},{q="谁是赫芙达娜？",a="赫芙达娜·赛格伦德是湿地的向导，她与家人住在南部瀑布旁的一个洞穴里，她负责祝福求道者收集的神圣之水，使其拥有酿造水之灵药所需的精神纯度。",al={"谁是赫芙达娜","受赫芙达娜祝福","赫芙达娜的水"}},{q="水之灵药有什么用？",a="水之灵药是一种使用神圣之水调制而成的元素药水。饮用它能让萨满祭司洞穿面纱，感知到存在于天然水池中的隐秘水元素灵魂。",al={"什么是水之灵药","水之灵药的用途","水之灵药的作用"}},{q="斯特登的池塘在哪里？",a="斯特登的池塘位于西部荒野，靠近月溪镇。萨满祭司在饮用准备好的水之灵药后，必须前往那里寻找栖息在其中的水元素灵魂。",al={"斯特登的池塘在哪里","斯特登的池塘位置","斯特登的水元素灵魂"}},{q="为什么一瓶最纯净的水很重要？",a="一瓶最纯净的水中装有酿造水之灵药和进行获得水之图腾所需神圣仪式必不可少的受祝福之水。诺里克告诫说，即使一滴也不能浪费。",al={"为什么要纯净水","一瓶最纯净的水的用途"}},{q="什么是水之图腾仪式？",a="水之图腾仪式是萨满祭司为了与水元素达成共鸣而进行的精神试炼，通过这些仪式证明自己的尊重与平衡，从而获得水之图腾。",al={"什么是水之图腾仪式","如何获得水之图腾"}}},fp="13,168,27.150.0,18.228.1,24.159.0,16.165.0,25.123.0,32.133.0,42.162.0,31.137.0"}
P.entries["quest:94502"] = {n="水之召唤",s="水之召唤是一项元素任务，要求从洛克莫丹前往西部荒野，以恢复一处被腐蚀的泉水的平衡。通过净化斯特登的池塘中的受污染实体，并在遗忘的神龛处执行古老的仪式，请求者可以获得水之灵魂的青睐以及他们的水之图腾。",h="水之召唤是一项元素任务，要求从洛克莫丹前往西部荒野，以恢复一处被腐蚀的泉水的平衡。通过净化斯特登的池塘中的受污染实体，并在遗忘的神龛处执行古老的仪式，请求者可以获得水之灵魂的青睐以及他们的水之图腾。",kw={"水之召唤","洛克莫丹","月溪镇","诺里克","萨满","斯特登的池塘","水之图腾","西部荒野"},ang={["class:Shaman"]="这项试炼是与水之灵魂建立联系并获得水之图腾的关键仪式，展现了对元素力量的和谐与掌控。",["faction:Alliance"]="联盟的萨满必须穿越他们的领土，从洛克莫丹冒险进入动荡的西部荒野，以净化被腐蚀的水域。"},sec={{t="被暗影侵蚀的泉水",b="在月溪镇的阴影之下坐落着斯特登的池塘，这里曾经是一处清澈纯净的泉水。横扫西部荒野的黑暗影响已经玷污了它宁静的水域，迫使当地的水之灵魂陷入了沉寂。岸边矗立着一座古老的神龛，被尘土和蛛网覆盖，废弃已久，等待着有人来唤醒其中沉睡的力量。"},{t="净化仪式",b="位于洛克莫丹的诺里克会指引请求者完成恢复平衡所需的仪式。该仪式要求面对污染斯特登的池塘的邪恶实体，获取其护腕，并将它们与几滴炼金药水一起供奉在石制神龛上。当咒语被念出时，蒸气会召唤出一个被净化的灵魂，它将传授智慧，并证明携带者有资格获得水之图腾。"}},faq={{q="水之召唤是什么任务？",a="水之召唤是一项针对萨满的灵性试炼，旨在与水的元素进行沟通。该任务要求请求者净化西部荒野中斯特登的池塘的腐蚀，利用那里的古老神龛召唤一个被净化的水之灵魂，并获得他们的水之图腾。",al={"水之召唤是什么","水之图腾任务","西部荒野水之任务"}},{q="谁发布了这个任务？",a="该任务由洛克莫丹的导师诺里克发布。他指导请求者进行元素仪式，提供特殊的药水，并引导他们净化被腐蚀的元素水域。",al={"谁发布水之召唤","洛克莫丹 诺里克","任务发布者"}},{q="斯特登的池塘在哪里？",a="斯特登的池塘位于西部荒野西南部的月溪镇外。它曾经是一处纯净的泉水，但在黑暗、腐蚀力量的影响下，如今已变得死寂而浑浊。",al={"斯特登的池塘在哪里","斯特登的池塘位置","月溪镇附近的池塘"}},{q="如何净化斯特登的池塘的腐蚀？",a="要净化水域，你必须击败斯特登的池塘中的腐蚀存在，取走它的护腕，并将它们与剩余的药水一起放置在古老的神龛上，同时念诵诺里克传授的咒语。",al={"如何净化池塘","净化斯特登的池塘","神龛仪式"}},{q="完成此任务能获得什么奖励？",a="完成试炼并将净化的证明带回给洛克莫丹的诺里克，请求者将获得他们的水之图腾，从而获得对水之元素力量的掌控权。",al={"水之召唤有什么奖励","水之图腾奖励"}},{q="为什么斯特登的池塘会被腐蚀？",a="黑暗的来源尚不确定。池塘呈现出反常的停滞状态，周围散布着野兽的白骨，这引发了人们的担忧：它究竟是被西部荒野蔓延的苦难所毒害，还是其本身就是腐蚀的源头。",al={"为什么斯特登的池塘会被腐蚀","什么腐蚀了池塘"}}},fp="13,212,26.284.0,21.359.1,32.235.0,21.168.0,24.152.0,52.195.0,43.169.0,32.211.0"}
P.entries["quest:94503"] = {n="水之召唤",s="水之召唤是一个位于西部荒野的任务，要求冒险者净化受污染的元素力量。玩家通过用圣光驱散不安的灵魂，与水之魂进行沟通，以守护该地区日渐衰弱的生命力。",h="水之召唤是一个位于西部荒野的任务，要求冒险者净化受污染的元素力量。玩家通过用圣光驱散不安的灵魂，与水之魂进行沟通，以守护该地区日渐衰弱的生命力。",kw={"水之召唤","净化","腐蚀","元素","水之魂","水之灵魂","西部荒野"},ang={["class:Shaman"]="与原始元素沟通并净化受污染的水之灵魂是元素的基本仪式，提醒萨满他们平衡自然的永恒职责。",["faction:Alliance"]="该显现居住在西部荒野，这是一个联盟领土，当地的灵魂正承受着侵蚀这片土地的蔓延枯萎。"},sec={{t="净化受污染的水域",b="在西部荒野那片饱受风霜的土地上，自然的水之平衡正面临着受腐蚀灵魂的侵害。被称为水之召唤的仪式需要面对这些邪恶，诵读圣言唤出耀眼的光芒，将这些躁动、污秽的本质驱散为无害的灰烬与平静的薄雾。"},{t="灵魂的警告",b="随着腐蚀实体被击退，水之魂可以安全地现身进行沟通。虽然眼前的腐蚀已有所减退，但灵魂警告说，这片土地的生命能量仍在不断衰弱，提醒勇士们守护生命是一场永无止境的守望。"}},faq={{q="水之召唤是什么？",a="水之召唤是西部荒野的一场灵魂试炼，通过爆发圣光的仪式驱逐腐蚀的灵魂，净化受困的水域，并允许玩家与水之魂沟通。",al={"什么是 水之召唤","水之召唤 西部荒野","西部荒野水任务"}},{q="水之魂在哪里可以找到？",a="水之魂位于西部荒野。它会在周围的腐蚀灵魂被镇压并驱散后出现，等待与那些帮助过水域的人交谈。",al={"水之魂在哪里","显现位置","西部荒野水之灵魂"}},{q="净化腐蚀的灵魂后会发生什么？",a="随着咒语的结束，耀眼的光芒爆发并驱散了腐蚀的灵魂，使它们污秽的本质瓦解并如灰烬般消散，而水流则嘶嘶作响，化作柔和的薄雾。",al={"仪式期间发生了什么","水之召唤 腐蚀灵魂"}},{q="完成任务后，这片土地完全恢复了吗？",a="眼前的腐蚀已被击退并逐渐消退，但元素警告说生命力仍在衰弱，守护生命的重任仍落在凡人手中。",al={"腐蚀消失了吗","我们拯救了水域吗"}},{q="谁被召唤来协助这一显现？",a="该任务认可了玩家的使命，感谢他们的职业挺身而出，净化灵魂并肩负起保护衰弱生命的责任。",al={"谁能执行 水之召唤","水任务职业要求"}},{q="为什么西部荒野的水之灵魂会被腐蚀？",a="腐蚀的灵魂扰乱了西部荒野沿岸的自然水域。虽然这种污染的确切起源尚不明确，但它们恶意的存在直接汲取了该地区的生命活力。",al={"为什么西部荒野的水被腐蚀了","西部荒野水的问题"}}},fp="13,113,28.166.0,20.184.0,22.203.0,52.163.0,53.149.0,53.155.0,47.147.0,49.153.0"}
P.entries["quest:94505"] = {n="水之召唤",s="水之召唤是一项元素试炼，萨满祭司通过它学会与水之灵交流并运用其恢复力量。通过从西部荒野为洛克莫丹的诺里克·洛克萨恩取回水灵碎片，试炼者证明了自己的奉献精神并获得了他们的水之图腾。",h="水之召唤是一项元素试炼，萨满祭司通过它学会与水之灵交流并运用其恢复力量。通过从西部荒野为洛克莫丹的诺里克·洛克萨恩取回水灵碎片，试炼者证明了自己的奉献精神并获得了他们的水之图腾。",kw={"水之召唤","洛克莫丹","诺里克·洛克萨恩","萨满祭司","水灵碎片","水之图腾","西部荒野"},ang={["class:Shaman"]="这项试炼标志着一个基本的通过仪式，赋予萨满祭司与水之灵的交流能力以及用于治愈和维持生命的水之图腾。",["faction:Alliance"]="与卡利姆多的部落萨满祭司不同，联盟的试炼者向洛克莫丹的诺里克·洛克萨恩之类的导师汇报，并面对像西部荒野这样的地方的试炼。"},sec={{t="水之道",b="水之召唤是萨满祭司为了与水元素建立联系而进行的一项至关重要的精神试炼。试炼者被派往西部荒野，并将水灵碎片带回洛克莫丹交给诺里克·洛克萨恩。通过展现他们对水之生命本质及其在净化腐蚀中作用的理解，萨满祭司赢得了他们的水之图腾，并迈出了元素旅程中重要的一步。"},{t="生命赋予者",b="这项试炼传授了一条基础的元素真理：水即生命，而腐蚀则终结生命。萨满祭司肩负着运用水的恢复力量来保护弱小和维持生命的使命。正如导师诺里克·洛克萨恩在收到水灵碎片时所观察到的，水的纯净馈赠远不止简单的肉体修复，还触及了耐力、复苏和精神平衡。"}},faq={{q="诺里克·洛克萨恩是谁？",a="诺里克·洛克萨恩是一位驻守在洛克莫丹的萨满祭司导师。他引导试炼者通过试炼以了解水之灵，通过前往西部荒野的旅程考验他们的决心，并在他们交出交流证明时为他们颁发水之图腾。",al={"诺里克·洛克萨恩是谁","谁给予水之图腾","诺里克 洛克莫丹"}},{q="什么是水灵碎片？",a="水灵碎片是证明试炼者已从西部荒野归来交给洛克莫丹诺里克·洛克萨恩的实物凭证。它标志着试炼者已经与水进行了交流，掌握了其赋予生命的本质，并学会了对抗腐蚀。",al={"什么是水灵碎片","水灵碎片的用途","水灵碎片任务物品"}},{q="为什么试炼会前往西部荒野？",a="试炼者被派往西部荒野是为了理解水赋予生命的力量以及腐蚀是如何威胁它的。即使在那个动荡之地取得的微小胜利，对于证明试炼者保护生命的能力来说也具有重要的意义。",al={"为什么要去西部荒野","西部荒野水任务","前往西部荒野 水之召唤"}},{q="水之图腾的意义是什么？",a="水之图腾体现了萨满祭司与水元素的联系。虽然它主要以通过净水来抚慰和治愈伤口而闻名，但其精神馈赠远超基础的治疗，涵盖了保存与活力。",al={"水之图腾有什么作用","萨满祭司为什么需要水之图腾","水之图腾背景"}},{q="这项试炼关于水传授了什么课程？",a="试炼期间教授的元素哲学强调水赋予生命，而腐蚀则会阻碍生命。萨满祭司肩负着用水的元素力量在任何腐蚀威胁生命的地方进行滋养、保护和恢复平衡的使命。",al={"什么是水即生命","水之召唤哲学","萨满祭司水之教导"}},{q="完成水之召唤后会发生什么？",a="诺里克·洛克萨恩指出，萨满祭司的下一个元素试炼不会立刻到来。他鼓励萨满祭司花时间练习并探索水更深层的奥秘，然后再进行进一步的试炼。",al={"接下来是什么试炼","下一个萨满祭司试炼","水之召唤之后发生什么"}}},fp="13,163,17.305.0,13.267.0,24.236.0,27.193.0,36.173.0,44.145.0,45.201.0,46.170.0"}
P.entries["quest:94532"] = {n="Gnoll Infestation",s="洛格玛的 Neza Bloodsnout 请你驱赶西南丘陵中的豺狼人。他们的存在扰乱了贸易和旅途，但暮光势力的侵袭已使他们的数量减少。",h="洛格玛的 Neza Bloodsnout 请你驱赶西南丘陵中的豺狼人。他们的存在扰乱了贸易和旅途，但暮光势力的侵袭已使他们的数量减少。",kw={"蛮兵","豺狼人肆虐","豺狼人","神秘者","neza bloodsnout","赤脊山","洛格玛","设陷者","暮光"},sec={{t="丘陵中的豺狼人",b="暮光势力侵袭后，赤脊山的豺狼人数量虽已减少，仍在洛格玛西南的丘陵中为患。Neza Bloodsnout 请你清除这项威胁，为盟友扫清道路。豺狼人盘踞期间，贸易和旅人仍会受到阻碍。"}},faq={{q="豺狼人为何是个麻烦？",a="洛格玛西南丘陵中的豺狼人扰乱贸易，也给旅人带来麻烦。",al={"豺狼人扰乱贸易","为何清除豺狼人","豺狼人威胁"}},{q="豺狼人在哪里？",a="他们盘踞在西南方的丘陵中。",al={"豺狼人丘陵","赤脊山豺狼人在哪里"}},{q="谁让我去对付他们？",a="洛格玛的 Neza Bloodsnout 请你消除豺狼人的威胁。",al={"谁发布了豺狼人肆虐任务","neza 任务"}},{q="豺狼人的数量减少了吗？",a="是的。暮光势力侵袭后，他们的数量减少了，但威胁依然存在。",al={"豺狼人数量","暮光豺狼人"}},{q="有哪些豺狼人？",a="提到的豺狼人有 Redridge Mystics、Redridge Trappers 和 Redridge Brutes。",al={"豺狼人种类","神秘者、设陷者、蛮兵"}}},fp="17,187,19.268.0,29.81.0,21.39.0,30.63.0,27.86.0,31.78.0"}
P.entries["quest:94533"] = {n="Snargl's Snout",s="Neza Bloodsnout想把Snargl的鼻子当作战利品。年长的豺狼人发出的刺耳声响，困扰着刺毛丘陵的盟友和侦察兵。",h="Neza Bloodsnout想把Snargl的鼻子当作战利品。年长的豺狼人发出的刺耳声响，困扰着刺毛丘陵的盟友和侦察兵。",kw={"刺毛丘陵","豺狼人","neza bloodsnout","snargl","snargl的鼻子","鼻子","战利品"},sec={{t="送给Neza的战利品",b="Neza Bloodsnout想为收藏品添一件纪念品，而她点名要的是Snargl。你被派往刺毛丘陵取回他的鼻子。Neza希望你动作迅速；进入那片区域的盟友和侦察兵都受到Snargl的声响困扰。"}},faq={{q="Snargl是谁？",a="Snargl是Neza Bloodsnout西南方刺毛丘陵的一名年长豺狼人。",al={"snargl","snargl 豺狼人","年长豺狼人"}},{q="Neza为什么想要Snargl的鼻子？",a="Neza想把Snargl的鼻子作为纪念品，收入她的战利品收藏。",al={"为什么要鼻子","snargl 战利品","neza 收藏"}},{q="Snargl在哪里？",a="Snargl在Neza Bloodsnout西南方的刺毛丘陵。",al={"snargl 位置","snargl 在哪里","刺毛丘陵 豺狼人"}},{q="Snargl带来了什么麻烦？",a="Snargl发出的刺耳声响会困扰进入刺毛丘陵的盟友和侦察兵。",al={"snargl 声响","侦察兵为什么受困扰","豺狼人噪声"}},{q="你回来时Neza会说什么？",a="Neza会说这件战利品比她预想的更重，并欢迎它加入收藏。",al={"snargl 任务完成","neza 反应","鼻子交付"}}},fp="14,133,17.247.0,14.75.0,34.63.0,16.61.0,31.90.0,35.95.0"}
P.entries["quest:94535"] = {n="Bristle Hills Bandits",s="Kreza Darkthorn派你前往刺毛丘陵，那里有豺狼人袭击了盟友矿工。你需要从他们的营地夺回被盗的矿石。",h="Kreza Darkthorn派你前往刺毛丘陵，那里有豺狼人袭击了盟友矿工。你需要从他们的营地夺回被盗的矿石。",kw={"盟友矿工","强盗","刺毛丘陵","豺狼人","kreza darkthorn","被盗的矿石"},sec={{t="丘陵中的矿石",b="盟友矿工报告称，Kreza Darkthorn以南的丘陵中发生了豺狼人袭击。你需要找到刺毛丘陵中的营地，夺回被盗的矿石。矿工们的损失尚待挽回。"},{t="夺回矿石之后",b="Kreza Darkthorn说矿石已经夺回，火焰会抹去留下的任何痕迹或气味。"}},faq={{q="是谁派我去追回被盗的矿石？",a="Kreza Darkthorn让你追回从盟友矿工那里偷走的矿石。",al={"kreza是谁","交付矿石的人"}},{q="强盗在哪里？",a="豺狼人的营地位于刺毛丘陵，在Kreza Darkthorn以南。",al={"豺狼人营地","强盗在哪里"}},{q="是谁偷走了矿石？",a="刺毛丘陵中的豺狼人袭击了盟友矿工，并抢走了他们的矿石。",al={"偷矿石的人","是谁拿走的"}},{q="矿工们遭遇了什么？",a="在南部丘陵工作的盟友矿工报告称，他们遭到豺狼人多次袭击。",al={"矿工遭袭","为何偷矿石"}}},fp="21,139,18.187.0,18.98.1,34.70.0,22.71.0,18.70.0,28.83.0"}
P.entries["quest:94556"] = {n="Jom-jom's Escape",s="Jom-jom想回家，请你护送他去Bolder'ok找Clugfist。",h="Jom-jom想回家，请你护送他去Bolder'ok找Clugfist。",kw={"bolder'ok","clugfist","护送","朋友","家","jom-jom"},sec={{t="回家的路",b="Jom-jom踏上了寻找朋友的旅程。现在，他需要你带他去Bolder'ok找Clugfist，这样他就能回家了。"}},faq={{q="Jom-jom是谁",a="Jom-jom来这里寻找一位朋友，如今想回家。",al={"jom-jom是谁","jom-jom"}},{q="Jom-jom想去哪里",a="Jom-jom想回家，有人请你护送他去Bolder'ok找Clugfist。",al={"jom-jom要去哪里","jom-jom回家"}},{q="Clugfist是谁",a="Jom-jom要在Bolder'ok去找Clugfist。",al={"clugfist","clugfist是谁"}},{q="Jom-jom为什么来这里",a="Jom-jom来这里寻找一位朋友。",al={"jom-jom为何在这里","jom-jom来了"}},{q="Jom-jom把你当朋友吗",a="你救下Jom-jom后，他称你为朋友。",al={"jom-jom的朋友","小家伙"}}},fp="16,81,12.107.0,15.59.0,30.87.0,16.62.0,26.34.0,35.47.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="《The Cult's True Plans》讲述了一位邪教叛逃者不幸身亡后的余波。随着线人死亡且其秘密丢失，调查人员必须咨询Talaanis 影歌，以制定对抗该邪教的新策略。",h="《The Cult's True Plans》讲述了一位邪教叛逃者不幸身亡后的余波。随着线人死亡且其秘密丢失，调查人员必须咨询Talaanis 影歌，以制定对抗该邪教的新策略。",kw={"邪教","叛逃者","维和人员","塔拉尼斯·影歌","教派的真正计划","变节者"},sec={{t="被噤声的叛逃者",b="一名内部人员因对邪教日益临近的阴谋感到恐惧而选择叛逃，希望能寻求外界的帮助。不幸的是，这名叛逃者在分享他所知的信息之前就被杀害了，留下了不详的警告，但关于邪教打算释放什么却没有任何具体细节。"},{t="重新思考应对方案",b="随着主要线人身亡，领导层必须咨询Talaanis Shadowsong以重新评估他们的策略。让维和人员与邪教进行正面交锋被认为是一场必败之战，这迫使那些调查威胁的人寻找另一条前进的道路。"}},faq={{q="在这个任务中提到的变节者是谁？",a="一名邪教叛逃者因对邪教正在策划的事情感到恐惧而寻求援助。不幸的是，他在透露其阴谋细节之前就被杀害了，将宝贵的情报带进了坟墓。",al={"在《教派的真正计划》中谁死了","死去的变节者是谁","变节者的邪教秘密"}},{q="塔拉尼斯·影歌是谁？",a="塔拉尼斯·影歌是在线人突然死亡后，商讨如何应对邪教的关键联络人。你见证了与塔拉尼斯进行的一次战略性谈话，以确定下一步的行动方针。",al={"塔拉尼斯·影歌的角色","塔拉尼斯·影歌是谁","与塔拉尼斯交谈"}},{q="为什么维和人员不能直接攻击邪教？",a="将维和人员直接部署到与邪教势力的正面战斗中被认为风险太大，因为维和人员在正面冲突中表现预计不会很好。因此需要一种更巧妙或替代的策略。",al={"为什么不与邪教战斗","维和人员对阵邪教","直接袭击邪教"}},{q="邪教的真正计划是什么？",a="由于线人在分享他所知信息之前就已死亡，邪教计划的具体性质仍然笼罩在迷雾中。无论他们的目标是什么，其恐怖程度足以让一名成员绝望地选择叛逃。",al={"邪教在策划什么","邪教阴谋","《教派的真正计划》的含义"}},{q="与塔拉尼斯交谈后的下一步是什么？",a="在意识到正面战斗行不通且主要情报来源已死之后，领导层必须设计一种替代方法来揭露并挫败邪教的阴谋。",al={"《教派的真正计划》之后会发生什么","邪教任务的后续步骤"}},{q="在《邪教的真正计划》中发生了什么？",a="你与塔拉尼斯·影歌交谈并观察了一场关于局势的商议。讨论的中心是线人死亡后的余波，并评估为何不能依靠正规军事力量来阻止该邪教。",al={"《教派的真正计划》任务概要","你在《教派的真正计划》中做什么"}}},fp="21,139,19.170.0,23.268.1,45.146.0,27.161.0,55.145.0,33.163.0,51.142.0,42.178.0"}
P.entries["quest:94613"] = {n="My Kingdom for a Horse",s="附近的一座农场丢失了马匹，导致 Farholde 在对抗部落的战役中没有骑兵。你被派往 Wheeler’s Grange 与 Benjy 谈谈。",h="附近的一座农场丢失了马匹，导致 Farholde 在对抗部落的战役中没有骑兵。你被派往 Wheeler’s Grange 与 Benjy 谈谈。",kw={"benjy","部落","失踪的马匹","我愿以王国换一匹马","farholde 骑兵","战马","wheeler’s grange"},sec={{t="失踪的马匹",b="Farholde 的战马来自附近的两座农场，但 Wheeler’s Grange 的马匹全都不见了。原因尚不清楚，而没有马匹，Farholde 就没有骑兵参加对抗部落的战役。你被派去农场与 Benjy 谈谈，了解他的说法。"}},faq={{q="Farholde 为什么需要这些马？",a="Farholde 依靠战马组建骑兵，并认为骑兵是对抗部落的战役所必需的。",al={"为何需要马匹","需要战马","farholde 骑兵"}},{q="Wheeler’s Grange的马匹出了什么事？",a="Wheeler家所有的马匹都不见了，原因尚不清楚。",al={"失踪的马匹","马匹去了哪里","wheeler家的马"}},{q="Benjy是谁？",a="Benjy在Wheeler’s Grange，你被派去向他打听失踪的马匹。",al={"benjy","wheeler’s grange的人","该找谁交谈"}},{q="Farholde 的战马存放在哪里？",a="Farholde 的战马来自附近的两座农场。其中一座是 Wheeler 家族拥有的 Wheeler’s Grange。",al={"养马农场","马匹来自哪里","战马农场"}}},fp="22,159,17.278.0,34.110.0,50.73.0,13.83.0,38.107.0"}
P.entries["quest:94615"] = {n="Foal Play",s="在 Wheeler's Grange，马厩里的马匹不见了。你四处寻找线索，想查明发生了什么。",h="在 Wheeler's Grange，马厩里的马匹不见了。你四处寻找线索，想查明发生了什么。",kw={"土狼","farholde","小马嬉戏","马匹","失踪的马匹","鱼人","马厩","wheeler's grange"},sec={{t="在庄园搜寻",b="Wheeler's Grange 的马厩或许藏有马匹失踪的线索。马夫说，他起床准备喂马时，马匹就已经不见了。Farholde 郊外的野兽、鱼人、兽人或其他危险都可能是罪魁祸首。你在马厩附近搜寻，试图缩小调查范围。"}},faq={{q="马匹去了哪里？",a="马匹从 Wheeler's Grange 消失了，你在马厩附近寻找它们去向的证据。",al={"失踪的马匹","马匹不见了","马匹去向"}},{q="什么东西可能带走了马匹？",a="马夫认为，Farholde 郊外的野兽、鱼人、兽人或其他危险都可能是罪魁祸首。",al={"谁带走了马匹","马匹失踪的罪魁祸首","是什么带走了它们"}},{q="马匹为何如此重要？",a="马匹是马夫赖以谋生的本钱。",al={"马匹为何重要","马匹谋生","马匹生意"}},{q="我该去哪里找线索？",a="在 Wheeler's Grange 的马厩附近搜寻，寻找与失踪马匹有关的证据。",al={"马厩线索","搜寻地点","小马嬉戏"}}},fp="9,116,22.266.0,24.110.0,33.100.0,29.47.0,30.82.0"}
P.entries["quest:94616"] = {n="水之灵契",s="“水之萨普塔”是一种仪式性的药剂，用于使人的灵魂视觉能够感知到水中隐藏的灵魂和腐化。持有此药剂的人会被派往西部荒野的田野中，寻找被污染的池塘水，以调查元素失衡的情况。",h="“水之萨普塔”是一种仪式性的药剂，用于使人的灵魂视觉能够感知到水中隐藏的灵魂和腐化。持有此药剂的人会被派往西部荒野的田野中，寻找被污染的池塘水，以调查元素失衡的情况。",kw={"元素协调","萨普塔","萨满试炼","被污染的池塘","水之灵契","水之灵魂","西部荒野"},ang={["class:Shaman"]="萨普塔是一种炼金或仪式药剂，被萨满用来调整他们的灵魂感官，以感知那些在普通视觉下无法看见的元素灵魂。",["faction:Alliance"]="调查西部荒野内被腐蚀的水域，将元素净化仪式带到了联盟领地的中心。"},sec={{t="水之视觉",b="在萨满的元素传统中，萨普塔是一种专门调制出的仪式药剂，用来穿透物质领域与灵魂领域之间的面纱。“水之萨普塔”专门将使用者的感官与水元素协调一致，从而赋予他们感知元素扰动和隐形灵魂所需的灵视能力。如果没有这种协调，普通的旅行者即使直视元素显现，也只能看到寻常的涟漪。"},{t="西部荒野的扰动",b="使用“水之萨普塔”的指令会将持有者指引至西部荒野。这片饱受动乱和荒废之苦的联盟土地上，有一处池塘的水遭到了灵魂层面的污染。在萨普塔赋予的感知的引导下，持有者必须找出这些被污染的水域，揭开其中的扰动，并恢复当地水之灵魂的和谐。"}},faq={{q="什么是水之萨普塔？",a="水之萨普塔是为萨满与元素沟通而特制的精神药剂。饮用或使用萨普塔可以暂时开启使用者的感知，使其能看到凡人肉眼无法察觉的元素实体和灵魂失衡。",al={"什么是水之萨普塔","水之萨普塔的目的","水之萨普塔的作用"}},{q="西部荒野的被污染池塘在哪里？",a="被污染的池塘水位于西部荒野境内。萨满们会被指引前往那里，手持水之萨普塔寻找受腐蚀的水源，并解决该地区内滋生的任何灵魂扰动。",al={"被污染的池塘在哪","西部荒野被污染的池塘","被污染的池塘位置"}},{q="为什么水之萨普塔会指引去西部荒野？",a="即使是在像西部荒野这样以农业为主、遭受旱灾的人类土地上，元素之水也可能遭受污染或邪恶腐化的侵袭。任务要求你寻找被污染的池塘水，以调查并恢复当地不安灵魂的平衡。",al={"为什么要去西部荒野","西部荒野水体腐化","为什么西部荒野的水会被污染"}},{q="谁会使用水之萨普塔？",a="水之萨普塔被授予正在接受元素沟通试炼的萨满。通过服用萨普塔，修行者会将他们的感官与水之灵魂协调，从而使其能够感知到隐藏的元素生物或检查被污染的水池。",al={"谁喝水之萨普塔","谁使用水之萨普塔","萨满饮用萨普塔"}},{q="当你带着萨普塔来到被污染的池塘时会发生什么？",a="在西部荒野的被污染池塘附近使用水之萨普塔后，你将获得元素视觉，从而显现出水的灵魂状态，或是召唤出与当地水之试炼相关的隐藏灵魂。",al={"使用萨普塔后会发生什么","萨普塔元素视觉"}},{q="元素萨普塔在萨满传统中是如何运作的？",a="萨普塔将大地的试剂与元素的祝福结合成一种仪式性的药剂。萨满在试炼中依靠它们来与特定的元素——土、火、水或气——达成协调，从而跨越物质世界与灵魂领域之间的鸿沟。",al={"萨普塔如何运作","萨普塔背景知识"}}},fp="11,183,23.267.0,23.267.0,22.127.0,38.138.0,42.163.0,25.180.0,58.170.0,51.171.0"}
P.entries["quest:94618"] = {n="Wheeler's Fleeing Steeds",s="Benjy请你找回一匹马。它在郊狼袭击后逃离了Wheeler's Grange。喂它一些饲料，让它信任你，再牵它回去。",h="Benjy请你找回一匹马。它在郊狼袭击后逃离了Wheeler's Grange。喂它一些饲料，让它信任你，再牵它回去。",kw={"benjy","郊狼","饲料","逃跑的马","马","wheeler's fleeing steeds","wheeler's grange"},sec={{t="逃离庄园",b="Wheeler's Grange的Benjy需要你帮忙，寻找一匹在郊狼袭击后逃跑的马。郊狼叼走了几匹马，其他马则因害怕而逃散。给一匹马喂些饲料，让它信任你，再牵它回去。"}},faq={{q="马匹遭遇了什么？",a="郊狼叼走了大部分马匹，还有一些马因害怕而逃离了Wheeler's Grange。",al={"wheeler's grange的马","遭郊狼袭击的马"}},{q="是谁在求助？",a="Benjy请你找回一匹逃离Wheeler's Grange的马。",al={"是谁给我的","benjy的马"}},{q="这些饲料该怎么用？",a="给一匹马喂些饲料，让它信任你，这样你就能牵它回去。",al={"怎么使用袋子","喂马"}},{q="为什么要寻找这些马？",a="Benjy说，得在郊狼回来之前找到逃跑的马。",al={"为何寻找马匹","它们去了哪里"}}},fp="24,127,20.231.0,28.78.0,23.58.0,31.70.0,32.72.0"}
P.entries["quest:94638"] = {n="Strength and Mercy",s="Ur'endra陷入疯狂，迷失了自我，她的伴侣请求你结束她的痛苦。你的决心为你赢得了一份祝福，让你能化为他同族的形态。",h="Ur'endra陷入疯狂，迷失了自我，她的伴侣请求你结束她的痛苦。你的决心为你赢得了一份祝福，让你能化为他同族的形态。",kw={"德鲁伊祝福","阵风浆果低地","shape of the claw","申达尔高地","strength and mercy","ur'endra","风之魔法"},ang={["class:Druid"]="身为德鲁伊，你需要先证明自己的决心，才能获得化为那位德鲁伊同族形态的祝福。"},sec={{t="沉重的恳求",b="一位德鲁伊请求你结束申达尔高地的Ur'endra的痛苦。她是他的伴侣，但疯狂让她开始攻击自己的同族。风之魔法的消失让许多生灵迷失了自我，Ur'endra也是其中之一。她的巢穴位于此地以西的一个洞穴中，就在申达尔高地与阵风浆果低地之间的峭壁上。"},{t="祝福",b="在申达尔高地，Ur'endra的伴侣为失去她而悲伤，却也认为这是维持平衡所必需的。他看到了你接受如此惨痛代价的决心。他赐予你一份祝福，让你能化为他同族的形态，并嘱咐你扶助弱者，保护需要帮助的人。"}},faq={{q="Ur'endra是谁？",a="Ur'endra是那位请求你结束她痛苦的德鲁伊的伴侣。",al={"ur'endra","urendra是谁","德鲁伊的伴侣"}},{q="Ur'endra为什么攻击自己的同族？",a="Ur'endra陷入疯狂，迷失了自我。风之魔法的消失让许多生灵迷失了自我。",al={"urendra为何疯狂","urendra攻击","urendra怎么了"}},{q="Ur'endra的巢穴在哪里？",a="Ur'endra的巢穴位于那位德鲁伊以西的一个洞穴中，就在申达尔高地与阵风浆果低地之间的峭壁上。",al={"urendra洞穴","urendra在哪里","shen'dar洞穴"}},{q="那位德鲁伊要我做什么？",a="那位德鲁伊请求你结束Ur'endra的痛苦。",al={"urendra任务","要做什么","杀死urendra"}},{q="那位德鲁伊赐予什么祝福？",a="那位德鲁伊赐予你一份祝福，让你能化为他同族的形态。",al={"形态祝福","way of the claw","德鲁伊祝福"}},{q="那位德鲁伊为什么提出这个请求？",a="那位德鲁伊认为，结束Ur'endra的痛苦是维持平衡所必需的。",al={"为何杀死urendra","为何必须如此","平衡"}}},fp="18,141,12.353.0,12.293.1,16.68.0,34.112.0,25.125.0,33.47.0,35.72.0,32.74.0"}
P.entries["quest:94668"] = {n="Bloodmaster's Ring",s="在Bloodmaster's Ring，你击败暮光食人魔证明了自己，随后向Jezap报告。Bloodmaster已准备好判断你是否够格。",h="在Bloodmaster's Ring，你击败暮光食人魔证明了自己，随后向Jezap报告。Bloodmaster已准备好判断你是否够格。",kw={"bloodmaster","bloodmaster's ring","地精","jezap","力量巅峰","暮光食人魔"},sec={{t="Ring中",b="Bloodmaster's Ring的挑战让你来到了这座竞技场的地精Jezap面前。击败暮光食人魔后，你向他报告，Bloodmaster和Jezap都在一旁注视着。他们正在判断，你是否有资格跻身那些敢于逼近力量巅峰边缘的人之列。"}},faq={{q="在Bloodmaster's Ring，我该向谁报告？",a="你要在Bloodmaster's Ring向Jezap报告。",al={"谁是jezap","向jezap报告","bloodmaster's ring地精"}},{q="我来这里之前做了什么？",a="你击碎了那些被判定为弱者的暮光食人魔。",al={"之前发生了什么","暮光食人魔","ring的前置步骤"}},{q="Bloodmaster在寻找什么？",a="Bloodmaster正在判断你是否够格接近力量巅峰。",al={"证明自己","bloodmaster想要什么","我够格吗"}}},fp="18,147,11.267.0,45.46.0,33.49.0,36.72.0"}
P.entries["quest:94669"] = {n="Pay to Play",s="收货人要求你先交一笔押金，才能进入 Bloodmaster's Ring。付清后，你便有资格在那里证明自己的实力。",h="收货人要求你先交一笔押金，才能进入 Bloodmaster's Ring。付清后，你便有资格在那里证明自己的实力。",kw={"bloodmaster's ring","clugfist","付费参赛","证明实力","竞技场","押金"},sec={{t="入场的代价",b="想进入 Bloodmaster's Ring，你得先交一笔押金。收货人说，交押金是为了保障你的安全。若你不交，他们就威胁要告诉 Clugfist，说你拒绝向欢迎你加入的队伍证明实力。你的选择将决定你是否有资格进入竞技场。"}},faq={{q="我为什么得交钱？",a="收货人说，交押金是为了保障你的安全，也是获得进入 Bloodmaster's Ring 资格的必要条件。",al={"为什么交钱","押金","付费参赛任务"}},{q="Clugfist 是谁？",a="Clugfist 是收货人威胁说要告知你拒绝付款之事的人。",al={"谁是 clugfist","clugfist","老 clugfist"}},{q="如果我拒绝呢？",a="收货人说，他们会告诉 Clugfist，你不愿证明自己的实力。",al={"不交钱","拒交押金","不交押金"}},{q="交钱后我能获得什么资格？",a="交纳押金后，你便有资格进入 Bloodmaster's Ring。",al={"获得什么资格","进入竞技场","bloodmaster's ring"}}},fp="11,132,18.294.0,21.106.0,16.76.0,25.90.0,32.67.0"}
P.entries["quest:94670"] = {n="Bloodmaster's Ring",s="Bloodmaster's Ring挑战让你迎战Buzzbeak，赢得名声的机会就在眼前。擂台上的地精觉得这场战斗很轻松。",h="Bloodmaster's Ring挑战让你迎战Buzzbeak，赢得名声的机会就在眼前。擂台上的地精觉得这场战斗很轻松。",kw={"bloodmaster","bloodmaster's ring","buzzbeak","名声","恶魔","战斗","擂台"},sec={{t="踏入擂台",b="擂台上的地精让Buzzbeak登上擂台与你交手。地精说，第一场战斗应该很轻松，但据说这个恶魔会击倒对手并夺走他们的财物。踏入擂台的人都将获得名声。"}},faq={{q="我在Bloodmaster's Ring要和谁战斗？",a="你将在Bloodmaster's Ring迎战Buzzbeak。",al={"bloodmaster战斗","buzzbeak是谁","擂台对手"}},{q="据说Buzzbeak会做什么？",a="据描述，Buzzbeak是个飘忽不定的恶魔，能击倒你并夺走你的财物。",al={"buzzbeak攻击","buzzbeak会做什么","擂台上的恶魔"}},{q="为什么要参加擂台挑战？",a="擂台上的地精承诺，踏入擂台便能赢得名声。",al={"擂台名声","bloodmaster名声","为什么和buzzbeak战斗"}},{q="这场战斗本该很轻松吗？",a="擂台上的地精称，这是轻松的第一场战斗。",al={"轻松的擂台战斗","bloodmaster轻松","buzzbeak难对付"}}},fp="18,129,13.212.0,41.44.0,32.90.0,19.54.0,31.55.0"}
P.entries["quest:94672"] = {n="Encroaching Twilight",s="Tran'gul警告说，暮光之锤袭击了洛格玛以西的一处人类定居点。你被派往阳光林地削弱邪教徒的力量，以免他们在附近站稳脚跟。",h="Tran'gul警告说，暮光之锤袭击了洛格玛以西的一处人类定居点。你被派往阳光林地削弱邪教徒的力量，以免他们在附近站稳脚跟。",kw={"暮光逼近","人类定居点","洛格玛","阳光林地","tran'gul","暮光新信徒","暮光袭击者","暮光之锤"},sec={{t="近在咫尺的威胁",b="西边的人类定居点已经遭到蹂躏，洛格玛可能成为下一个目标。Tran'gul派你前往阳光林地。暮光之锤已在那里开始征讨他们口中的异端。邪教的袭击者和新信徒正威胁着要在洛格玛附近站稳脚跟。"},{t="战斗之后",b="邪教徒的人数减少后，Tran'gul便能追查其空前扩张的源头。"}},faq={{q="Tran'gul担心谁？",a="Tran'gul担心暮光之锤。这个邪教正在攻击他们认定的异端。",al={"威胁是谁","暮光之锤的威胁"}},{q="那个人类定居点遭遇了什么？",a="暮光之锤蹂躏了洛格玛以西的一处人类定居点。",al={"西边的定居点","西边发生了什么"}},{q="我为什么要去阳光林地？",a="Tran'gul派你前往阳光林地，削弱暮光之锤的力量。",al={"为何去阳光林地","阳光林地有什么"}},{q="邪教接下来可能会袭击谁？",a="西边的人类定居点遭袭后，Tran'gul担心洛格玛可能成为下一个目标。",al={"下一个是谁","洛格玛会是下一个吗"}}},fp="20,173,15.274.0,15.96.1,30.75.0,38.65.0,29.74.0,31.74.0"}
P.entries["quest:94679"] = {n="Snargl's Snout",s="Southern Watch的Cedric Dalton想要一只来自刺毛丘陵的Snargl的鼻子。他认为，杀死一只强大的豺狼人会削弱赤脊山的兵力，并吓住他们。",h="Southern Watch的Cedric Dalton想要一只来自刺毛丘陵的Snargl的鼻子。他认为，杀死一只强大的豺狼人会削弱赤脊山的兵力，并吓住他们。",kw={"刺毛丘陵","cedric dalton","豺狼人","赤脊山","snargl","snargl的鼻子","southern watch"},sec={{t="丘陵中的豺狼人",b="在Southern Watch，Cedric Dalton请你处理Snargl。Snargl是刺毛丘陵一处巢穴中的恶名昭著的豺狼人。Cedric Dalton认为，豺狼人最看重力量，因此Snargl之死或许能削弱赤脊山的兵力，并让他们心生恐惧。Cedric Dalton要你带回Snargl的鼻子。"},{t="归还战利品",b="Cedric Dalton收下Snargl的鼻子作为战利品，并说很快就会派上用场。杀死这只豺狼人，是为了让赤脊山的兵力心生恐惧。"}},faq={{q="Snargl是谁？",a="Snargl是刺毛丘陵一处巢穴中的恶名昭彰的豺狼人。",al={"snargl是谁","snargl豺狼人","刺毛丘陵豺狼人"}},{q="谁想要Snargl的鼻子？",a="Southern Watch的Cedric Dalton要你把Snargl的鼻子带给他。",al={"谁要snargl的鼻子","cedric dalton的请求","southern watch鼻子"}},{q="Cedric Dalton为什么想杀死Snargl？",a="Cedric Dalton认为豺狼人最看重力量，杀死他们中最强大的家伙会削弱他们，并吓住他们。",al={"为什么杀死snargl","豺狼人力量","吓住赤脊山"}},{q="Snargl在哪里？",a="Snargl在刺毛丘陵的一处巢穴中。",al={"snargl的位置","snargl在哪里","刺毛丘陵巢穴"}}},fp="14,159,20.287.0,17.144.1,14.61.0,25.69.0,33.122.0,16.43.0"}
P.entries["quest:94680"] = {n="Twilight Missives",s="Tran'gul想弄清暮光之锤的教徒为何在阳光林地周边日渐增多。他请你带回他们的密信，以便查明他们的目的。",h="Tran'gul想弄清暮光之锤的教徒为何在阳光林地周边日渐增多。他请你带回他们的密信，以便查明他们的目的。",kw={"教徒","密信","洛格玛","阳光林地","tran'gul","暮光密信","暮光 shadowmancers","暮光之锤"},sec={{t="势力渐长",b="Tran'gul发现，暮光之锤的教徒比以往更多地出现在这一带。他们的暮光 Shadowmancers 是教团中受信任的成员，或许掌握着教团行动的情报。Tran'gul请你带回他们的密信，以便查明这个教团的目的。"}},faq={{q="谁在索要暮光密信？",a="洛格玛的 Tran'gul 请你从阳光林地的暮光 Shadowmancers 手中取回密信。",al={"谁要密信","tran'gul的请求","tran'gul是谁"}},{q="我在哪里能找到暮光 Shadowmancers？",a="暮光 Shadowmancers 位于阳光林地。",al={"暗影施法者的位置","暮光教徒在哪里","阳光林地的密信"}},{q="Tran'gul为什么想要这些密信？",a="Tran'gul想进一步了解这些教徒及其目的。",al={"为何要取回密信","tran'gul想知道什么","教徒的文书"}},{q="Tran'gul为何担心这些教徒？",a="Tran'gul发现暮光之锤的教徒比以往更多，他们似乎也更有恃无恐，想要扩大自己的影响力。",al={"暮光教徒为何在此","教徒日渐增多","暮光教徒人数"}}},fp="17,171,18.258.0,35.91.0,44.45.0,36.67.0,45.128.0"}
P.entries["quest:947"] = {n="洞中的蘑菇",s="“洞穴蘑菇”是暗夜精灵巴瑞萨斯·月影在奥伯丁发布的一项联盟任务。在配制某种特制药剂时，巴瑞萨斯委托一位冒险者前往峭壁之泉背后的一处隐秘洞穴，采集珍稀真菌，并核实古树之林所感应到的不安预兆。",h="“洞穴蘑菇”是暗夜精灵巴瑞萨斯·月影在奥伯丁发布的一项联盟任务。在配制某种特制药剂时，巴瑞萨斯委托一位冒险者前往峭壁之泉背后的一处隐秘洞穴，采集珍稀真菌，并核实古树之林所感应到的不安预兆。",kw={"奥伯丁","巴瑞萨斯·月影","洞穴蘑菇","峭壁之泉","黑海岸","毒帽蘑菇","古树之林","欧努","粗糙柄菇"},ang={["faction:Alliance"]="奥伯丁是联盟在卡利姆多海岸的主要堡垒，东部山脉中蔓延的邪恶直接威胁着整个海岸的稳定。",["profession:Herbalism"]="采集者和草药师会喜欢搜寻毒帽蘑菇和粗糙柄菇的过程，尽管这些特殊的样本生长在阴暗的洞穴里，而不是茂密的林地土壤中。",["race:NightElf"]="古树之林始终与黑海岸的自然平衡保持着深刻的共鸣，因此他们在瀑布之下探测到的任何骚动，对卡多雷来说都是需要紧急关注的问题。"},sec={{t="瀑布后的配方",b="巴瑞萨斯·月影需要特定的配料来调制强力药剂：粗糙柄菇和一种难以寻觅的毒帽蘑菇。这些特殊的真菌生长在黑海岸东北部、峭壁之泉后方隐蔽的阴暗潮湿洞穴中。虽然炼金本身很精细，但收集这些样本要比采集普通的林地草药危险得多。"},{t="古树的警告",b="巴瑞萨斯并非因为懒惰而不去那座洞穴。古树之林的古老树木守护者发出了严厉的警告，感应到一股邪恶的力量开始在山洞中筑巢。月影派遣一位强健的探险者而非亲自调查，正是为了确认长老们关于黑海岸北部潜伏着一股邪恶力量的预感是否属实。"}},faq={{q="这项任务在哪里开始？",a="你可以从巴瑞萨斯·月影那里接到这项任务，他居住在黑海岸中部的暗夜精灵沿海定居点奥伯丁。",al={"如何接取洞穴蘑菇任务","巴瑞萨斯·月影的位置","洞穴蘑菇任务起始"}},{q="蘑菇在哪里？",a="它们生长在峭壁之泉后面隐藏的洞穴里，位于奥伯丁东北部的山坡上。",al={"哪里有粗糙柄菇","毒帽蘑菇位置","黑海岸瀑布后的洞穴"}},{q="为什么巴瑞萨斯·月影不亲自去取蘑菇？",a="古树之林明确建议巴瑞萨斯远离那处瀑布。伟大的古树们感觉到一股非自然的邪恶力量正在那个洞穴中栖身。",al={"为什么巴瑞萨斯不去","为什么巴瑞萨斯留在奥伯丁"}},{q="需要哪些特定的蘑菇？",a="月影需要五株粗糙柄菇，外加一株极度危险的毒帽蘑菇才能完成他的药剂。",al={"所需蘑菇","月影需要的真菌"}},{q="这项差事接下来会指向哪里？",a="一旦确认了洞穴中的异状并交付了真菌，旅程将转向南方，前往古树之林寻找远古保护者欧努。",al={"洞穴蘑菇后的后续任务","欧努后续"}},{q="为什么古树们会担心峭壁之泉？",a="古树之林警告巴瑞萨斯，瀑布后的洞穴中可能潜伏着一股日益壮大的邪恶力量。他请求一位旅行者去采集蘑菇并调查这一警告。",al={"古树对峭壁之泉的警告","为什么侦察洞穴"}}},fp="14,210,25.227.0,21.252.1,27.115.0,32.104.0,61.156.0,35.87.0,35.141.0,55.161.1"}
P.entries["quest:94727"] = {n="Digging for Answers",s="暮光之锤正在河林挖掘，寻找某种未知的能量源泉。你被派往阳光林地，盘问他们的一名矿工。",h="暮光之锤正在河林挖掘，寻找某种未知的能量源泉。你被派往阳光林地，盘问他们的一名矿工。",kw={"digging for answers","矿工","河林","source of power","阳光林地","暮光之锤"},sec={{t="阳光林地的矿工",b="暮光之锤派人在阳光林地挖掘，你被派去盘问其中一名矿工。他们的搜寻指向某种能量源泉，但其本质仍然未知。这些狂热分子守口如瓶，矿工或许知道他们在寻找什么。"}},faq={{q="暮光之锤在挖掘什么？",a="暮光之锤似乎正在河林寻找某种能量源泉，但具体是什么仍然未知。",al={"他们在挖掘什么","暮光之锤挖掘","source of power"}},{q="为什么要盘问矿工？",a="暮光之锤的狂热分子守口如瓶，因此你被派往阳光林地盘问他们的一名矿工。",al={"为何盘问矿工","与矿工交谈","寻求答案任务"}},{q="矿工在哪里？",a="矿工正在河林境内的阳光林地挖掘。",al={"阳光林地在哪里","矿工位置","河林挖掘"}}},fp="19,148,20.255.0,42.119.0,29.112.0,21.61.0"}
P.entries["quest:94733"] = {n="Our Ogre Friend",s="一名地精请你去Bolder'ok寻找Gobam，并为Chub'chob的宠物野猪Snufflesnout带些食物。Gobam愿意帮忙，因为Chub'chob是他的朋友。",h="一名地精请你去Bolder'ok寻找Gobam，并为Chub'chob的宠物野猪Snufflesnout带些食物。Gobam愿意帮忙，因为Chub'chob是他的朋友。",kw={"bolder'ok","chub'chob","据点","gobam","地精","我们的食人魔朋友","宠物野猪","snufflesnout"},sec={{t="朋友的请求",b="在你赢下几场战斗后，那名地精请你去Bolder'ok寻找Gobam。他需要为Chub'chob的宠物野猪Snufflesnout找些食物，却说工作缠身，抽不开身。Gobam就在Clugfist的据点以东，地精希望你能找到他。"}},faq={{q="Gobam是谁？",a="Gobam是那名地精派你去Bolder'ok寻找的害羞家伙。",al={"gobam是谁","谁是gobam"}},{q="我在哪里能找到Gobam？",a="Gobam就在Bolder'ok的Clugfist据点以东。",al={"gobam位置","gobam在哪里"}},{q="Snufflesnout是谁？",a="Snufflesnout是Chub'chob的宠物野猪，地精请你为它带些食物。",al={"snufflesnout","野猪食物"}},{q="地精为什么需要帮忙？",a="地精说工作缠身，所以请你为Snufflesnout寻找食物。",al={"为何帮助地精","地精很忙"}},{q="Gobam为什么愿意帮忙？",a="Gobam说他不喜欢那名地精，但他会帮助Chub'chob，因为他们是好朋友。",al={"gobam帮忙","gobam为何帮忙"}}},fp="15,157,20.242.0,13.66.0,23.51.0,20.83.0,30.86.0,20.92.0"}
P.entries["quest:94734"] = {n="A Boar's Delight",s="Gobam请你为Chub'chob的宠物Snufflesnout采集甜浆果和河边植物。这些食材能做成特别的美味。",h="Gobam请你为Chub'chob的宠物Snufflesnout采集甜浆果和河边植物。这些食材能做成特别的美味。",kw={"浆果","gobam","宠物","河草","snufflesnout","甜浆果","美味"},sec={{t="宠物的美味",b="Gobam想为爱吃美食的Snufflesnout做些特别的东西。他请你带回甜浆果和河草，作为制作美味的食材。"}},faq={{q="Gobam是谁",a="Gobam请你带回食材，为Chub'chob的宠物Snufflesnout制作特别的美味。",al={"gobam是谁","谁要浆果"}},{q="Snufflesnout是谁",a="Snufflesnout是Chub'chob的宠物，喜欢美食。",al={"snufflesnout宠物","gobam的宠物"}},{q="Gobam想要哪些食材",a="Gobam请你采集甜浆果和河草，为Snufflesnout制作美味。",al={"浆果和植物","什么食物"}},{q="Gobam为什么想要浆果",a="Gobam想用甜浆果和河草为Snufflesnout制作特别的美味。",al={"为什么要浆果","浆果用来做什么"}}},fp="16,133,13.150.0,13.95.0,20.52.0,33.76.0,28.81.0"}
P.entries["quest:94739"] = {n="Bloodmaster's Ring",s="Bloodmaster's Ring的地精把你送进角斗场的坑中，与Kronk一决高下。观众已经迫不及待地等着下一场较量。",h="Bloodmaster's Ring的地精把你送进角斗场的坑中，与Kronk一决高下。观众已经迫不及待地等着下一场较量。",kw={"解说员","bloodmaster","bloodmaster's ring","较量","参赛者","kronk","斗坑"},sec={{t="下一场较量",b="解说员正在调动观众的情绪，Kronk则作为下一位参赛者等候着。你奉命进入斗坑迎战他，随着这场较量即将开始，周围的喧闹声也越来越响。"}},faq={{q="Kronk是谁？",a="Kronk是Bloodmaster's Ring的下一位参赛者。解说员说他们相识已久，并称Kronk是个强壮的斗士。",al={"kronk","kronk是谁","kronk bloodmaster"}},{q="Bloodmaster要我做什么？",a="你被送进Bloodmaster's Ring的坑中，迎战Kronk。",al={"该做什么","角斗场任务","bloodmaster's ring"}},{q="我为什么要和Kronk交手？",a="解说员介绍Kronk是下一位参赛者，较量将在Bloodmaster's Ring举行。",al={"为什么是kronk","与kronk战斗","kronk战斗"}},{q="较量在哪里举行？",a="较量将在Bloodmaster's Ring的斗坑中举行。",al={"战斗在哪里","斗坑","角斗场位置"}},{q="我进入斗坑后会发生什么？",a="你在斗坑中做好准备时，解说员正准备介绍Kronk。",al={"进入之后","角斗场下一位","接下来会发生什么"}},{q="解说员怎么评价Kronk？",a="解说员说Kronk不太聪明，但很擅长痛打挡在他面前的一切。",al={"kronk的背景","kronk是什么样的人","解说员 kronk"}}},fp="18,136,13.160.0,13.130.0,40.66.0,24.101.0,31.58.0,35.78.0,40.91.0"}
P.entries["quest:94744"] = {n="The Wayward Warrior",s="Krom'rosh请你前往洛格玛以西的暮光之锤据点，与他的兄弟Dag'rosh会合。暮光之锤在阳光林地的据点已衰弱，战斗正转向他们的据点。",h="Krom'rosh请你前往洛格玛以西的暮光之锤据点，与他的兄弟Dag'rosh会合。暮光之锤在阳光林地的据点已衰弱，战斗正转向他们的据点。",kw={"dag'rosh","krom'rosh","食人魔战士","洛格玛","阳光林地","迷途的战士","暮光之锤"},sec={{t="兄弟先行",b="Krom'rosh派你去寻找Dag'rosh，他已和一支侦察队先行出发。你要去洛格玛以西的丘陵寻找他。Krom'rosh说，暮光之锤在阳光林地已失去据点，食人魔战士也倒戈反抗他们。如今战斗正转向邪教据点，他希望你陪在兄弟身边。"}},faq={{q="是谁让我去找Dag'rosh？",a="Krom'rosh请你前往暮光之锤据点，与他的兄弟Dag'rosh会合。",al={"是谁派我去","krom'rosh","谁要找dag'rosh"}},{q="我在哪里能找到Dag'rosh？",a="Krom'rosh说，要去洛格玛以西的丘陵寻找Dag'rosh。",al={"dag'rosh在哪里","dag'rosh的位置","寻找da'grosh"}},{q="Dag'rosh是谁？",a="Dag'rosh是Krom'rosh的兄弟。他已和一支侦察队先行出发。",al={"dag'rosh的来历","krom'rosh的兄弟","dag'rosh是谁"}},{q="暮光之锤在阳光林地遭遇了什么？",a="暮光之锤在阳光林地的据点已衰弱，食人魔战士也倒戈反抗他们。",al={"阳光林地的邪教","暮光之锤的据点","食人魔发生了什么"}}},fp="19,191,15.334.0,34.84.0,26.65.0,16.73.0,53.104.0"}
P.entries["quest:94773"] = {n="Divine Grace",s="名为 Divine Grace 的课程感谢你为圣光效力。你为身处险地的旅人树立了榜样。",h="名为 Divine Grace 的课程感谢你为圣光效力。你为身处险地的旅人树立了榜样。",kw={"险地","divine grace","课程","圣光","旅人"},sec={{t="感恩之课",b="你效力之后，人们赞颂圣光，也赞扬你为身处险地的旅人树立的榜样。为感谢你的付出，他们将传授你一课。"}},faq={{q="Divine Grace 讲的是什么？",a="Divine Grace 感谢你为圣光效力，并为身处险地的旅人树立榜样。",al={"divine grace","divine grace 是什么","divine grace 任务"}},{q="这堂课是为谁准备的？",a="这堂课是为感谢你效力圣光而传授给你的。",al={"谁能听这堂课","给我的课程","divine grace 奖励"}},{q="我树立了什么榜样？",a="你成为了身处险地及其他地方的旅人们的榜样。",al={"我的榜样","光辉榜样","我做了什么"}}},fp="12,116,18.159.0,27.102.0,23.69.0,23.65.0"}
P.entries["quest:94774"] = {n="Divine Grace",s="你的导师已批准你接受进一步训练，高阶牧师劳瑞娜因此召你前往暴风城的光明大教堂。你对圣光之道的学习即将开始。",h="你的导师已批准你接受进一步训练，高阶牧师劳瑞娜因此召你前往暴风城的光明大教堂。你对圣光之道的学习即将开始。",kw={"光明大教堂","divine grace","高阶牧师劳瑞娜","圣光","圣光的仆从","暴风城","训练"},ang={["class:Priest"]="身为牧师，你已获导师批准，可以进一步修习圣光之道。"},sec={{t="暴风城的召唤",b="你的导师认为你已证明了自己，便派你前往暴风城的光明大教堂。在那里，高阶牧师劳瑞娜已准备好指导你进一步修习。她说，每一位圣光的仆从都有必须学习的课程，而她已准备好与你探讨这些课程。"}},faq={{q="为什么派我去暴风城？",a="你的导师认为你已证明了自己，并已批准你进一步修习圣光之道。",al={"为什么去暴风城","被派往大教堂","为什么去那里"}},{q="高阶牧师劳瑞娜是谁？",a="高阶牧师劳瑞娜就在暴风城的光明大教堂，已准备好指导你修习。",al={"laurena是谁","谁是laurena","高阶牧师"}},{q="在哪里能找到高阶牧师劳瑞娜？",a="高阶牧师劳瑞娜就在暴风城的光明大教堂。",al={"laurena的位置","laurena在哪里","大教堂位置"}},{q="Laurena会提供什么训练？",a="Laurena已准备好与你探讨所有圣光仆从都必须学习的课程。",al={"圣光训练","什么课程","学习圣光之道"}}},fp="12,181,19.290.0,33.108.0,30.101.0,39.65.0,34.81.0"}
P.entries["quest:94789"] = {n="天空的召唤",s="一名萨满祭司被派往阿拉希高地北部的群山，去找Veyric Thundervein。他会传授更多驾驭空气的知识。",h="一名萨满祭司被派往阿拉希高地北部的群山，去找Veyric Thundervein。他会传授更多驾驭空气的知识。",kw={"空气","阿拉希高地","天空的召唤","萨满祭司","空气之灵","veyric thundervein","风系法术"},sec={{t="北部群山",b="一名萨满祭司派你北上，前往阿拉希高地寻找Veyric Thundervein。空气元素难以驾驭，而他能传授你更多知识。日益精进的技艺让你走到了这一步；如今，你的训练将转向风与空气之灵。"}},faq={{q="Veyric Thundervein是谁？",a="Veyric Thundervein就在阿拉希高地北部的群山中，他能在那里传授你更多关于空气的知识。",al={"veyric","veyric是谁","空气训练师"}},{q="在哪里能找到Veyric？",a="前往阿拉希高地北部的群山，寻找Veyric Thundervein。",al={"veyric的位置","veyric在哪","阿拉希空气训练师"}},{q="天空的召唤讲的是什么？",a="一名萨满祭司派你去找Veyric Thundervein，让他传授你更多关于空气元素的知识。",al={"天空的召唤任务","空气训练","风系法术"}},{q="为什么要去阿拉希高地？",a="Veyric Thundervein就在阿拉希高地北部的群山中，他会传授你更多关于空气的知识。",al={"为何去阿拉希","北上任务","寻找veyric"}},{q="Veyric会教些什么？",a="Veyric会教你集中施放风系法术，并召唤空气之灵。",al={"veyric的训练","空气之灵","集中施放风系法术"}}},fp="11,125,18.245.0,26.103.0,23.66.0,26.91.0,35.102.0,23.73.0"}
P.entries["quest:94792"] = {n="Taming the Beast",s="驯服野兽是一项入门级的试炼，有志向的冒险者将在此学习安抚野兽并与其建立羁绊的艺术。在 Josephine Carson 的指导下，新手们会带着一根驯兽棒进入森林，去驯服一只岩皮野猪并练习必要的生存技能。这项任务旨在证明，只要尊重并维护微妙的自然平衡，有了一只忠诚的野兽伙伴，在严酷的荒野中生存就会变得轻松许多。",h="驯服野兽是一项入门级的试炼，有志向的冒险者将在此学习安抚野兽并与其建立羁绊的艺术。在 Josephine Carson...",kw={"动物伙伴","自然的平衡","野兽驯服","猎人宠物","约瑟芬·卡森","岩皮野猪","驯兽棒","驯服野兽"},ang={["class:Druid"]="虽然德鲁伊不像猎人那样保留动物伙伴，但任务中对维护微妙的自然平衡的强调，反映了德鲁伊的核心教义。以关怀和克制的态度与森林中的野生生物互动，就是对他们发誓要保护的自然平衡的尊重。",["class:Hunter"]="对于猎人来说，掌握驯服野生野兽的艺术是一个决定性的成人礼，它从根本上改变了他们在荒野中的生存方式。忠诚的伙伴提供了必要的战斗保护和警觉，在追踪者与野兽之间铸就了持久的伙伴关系。"},sec={{t="与野兽建立羁绊",b="对于许多荒野漫游者来说，独自深入未经开垦的领地无异于自寻死路。一只动物伙伴不仅能在战斗中提供凶猛的保护，还能在艰苦的旅途中给予坚定不移的陪伴。学习如何建立这种羁绊，对于任何立志成为猎人或追踪者的人来说，都是一个至关重要的里程碑。在 Josephine Carson 的指引下，新手们会获赠一根特制的驯兽棒，并被要求前往森林中寻找一只岩皮野猪。安抚并驾驭这种生物是一项基础试炼，它能证明旅行者是否具备引导野兽所需的专注与镇定，而不会因恐惧而失控，或引发不必要的流血冲突。"},{t="自然的平衡",b="驾驭野生动物肩负着深远的道德和生态责任。正如 Josephine Carson 提醒她的学生们所言，将野兽纳入麾下绝不能沦为鲁莽的剥削，因为自然的平衡是脆弱的，必须时刻加以维护。驯服的过程并非为了残忍或统治，而是为了在野兽与主人之间建立和谐与纪律。使用这根附魔的驯兽棒，新手可以在不永久性消耗当地野生动物的前提下，安全地练习驾驭像岩皮野猪这样强大的生物。一旦掌握了指挥和安抚野兽的基础知识，驯兽棒就需要归还，这体现了对自然秩序的尊重高于个人的傲慢。"}},faq={{q="驯服野兽任务的目的是什么？",a="这项任务是为寻求与野生生物建立羁绊的冒险者提供的基础训练。在 约瑟芬·卡森 的指导下，新手将学习如何使用特制的驯兽棒接近并安抚一只野生的岩皮野猪。该练习教导有志成为猎人的冒险者，动物伙伴如何帮助他们在荒野中生存，同时也强调了尊重自然平衡的重要性。",al={"驯服野兽 任务","驯服野兽 是什么","猎人宠物任务"}},{q="约瑟芬·卡森 是谁？",a="约瑟芬·卡森 是一位导师，她指导冒险者掌握管理动物伙伴的微妙艺术。她会提供驯兽棒，并指派学生在附近的树林里用岩皮野猪练习他们的能力。约瑟芬 强调，学会与野兽共事需要耐心、实践以及对自然微妙平衡的深刻认识。",al={"约瑟芬·卡森","谁发布 驯服野兽","驯兽棒任务发布者"}},{q="驯兽棒有什么用？",a="驯兽棒是 约瑟芬·卡森 提供的一种特制工具，用于辅助动物训练。冒险者带着这根棒子进入森林，去安抚并驯服一只野生的岩皮野猪。它能让新手在不伤害当地动物群的前提下，安全地练习指挥野兽，且在试炼完成后必须将其归还给 约瑟芬。",al={"驯兽棒","驯兽棒的作用","如何使用驯兽棒"}},{q="猎人为什么需要动物伙伴？",a="独自在荒野中穿行会让旅行者面临严重的危险和伏击。动物伙伴可以提供可靠的保护、共同的警惕以及战斗中强有力的援助，让危险的环境变得更容易应对。在穿越荒地的漫长而危险的旅途中，忠诚的野兽既是凶猛的前线卫士，也是值得信赖的伙伴。",al={"为什么要获取宠物","野兽伙伴的好处","为什么要驯服野兽"}},{q="在此次试炼中需要驯服什么生物？",a="此次试炼要求冒险者深入森林，使用提供的驯兽棒驯服一只岩皮野猪。这些强壮的野兽是练习基础动物操控技能的理想测试对象，教导旅行者在面对具有攻击性的野生动物时如何保持镇定和纪律，然后返回向 约瑟芬·卡森 报告进度。",al={"我要驯服哪种野猪","岩皮野猪目标","驯服野兽 怪物"}},{q="为什么 约瑟芬·卡森 强调自然的平衡？",a="约瑟芬·卡森 警告说，驯服野生野兽时必须时刻保持谨慎和尊重，而不是贪婪或强迫。自然秩序是脆弱的，鲁莽地破坏当地的野生动物或虐待生物会打破生态平衡。对野兽真正的驾驭，需要理解并尊重它们在生态系统中的位置，而不是仅仅将它们视为可随意丢弃的工具。",al={"自然平衡的含义","自然平衡与驯服","为什么要尊重自然"}}},fp="16,181,19.403.0,21.405.0,50.234.0,24.231.0,32.240.0,38.186.0,46.237.0,58.205.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="训练野兽是年轻猎人的基础任务，引导他们前往闪金镇寻找老练的林务员 Isaac Chan。通过完成这一步骤，猎人将学会如何适当地训练、喂养和复活他们的野兽伙伴，将一头刚驯服的野兽转变为忠诚的战斗伙伴。",h="训练野兽是年轻猎人的基础任务，引导他们前往闪金镇寻找老练的林务员 Isaac Chan。通过完成这一步骤，猎人将学会如何适当地训练、喂养和复活他们的野兽伙伴，将一头刚驯服的野兽转变为忠诚的战斗伙伴。",kw={"艾尔文森林","喂养宠物","闪金镇","猎人宠物","艾萨克·陈","宠物训练","复活宠物","训练野兽","林务员"},ang={["class:Hunter"]="这项任务标志着成长中猎人的重要成人礼，从仅仅是捕捉野兽转变为通过喂养、复活和训练它们来建立持久、纪律严明的羁绊。",["faction:Alliance"]="在艾尔文森林活动的联盟猎人依靠像闪金镇的 Isaac Chan 这样的老练林务员来掌握野兽驯养的基础知识。"},sec={{t="狩猎的责任",b="学会驯服野生生物只是准猎人的第一步；维持持久的伙伴关系需要纪律和知识。该任务引导初出茅庐的猎人去寻找驻扎在闪金镇的经验丰富的林务员 Isaac Chan，以获取野兽训练的必备技能。如果没有适当的指导，驯服的野兽将只是难以管教的野生动物，而非荒野中坚定的盟友。"},{t="林务员的指导",b="到达闪金镇后，Isaac Chan 会传授照料野兽伙伴所需的技能。这些指导超越了简单的战斗指令，包括喂养伙伴以保持其满足感的重要职责，以及学习在伙伴倒下时将其复活的仪式。Chan 提醒他的学生，拥有驾驭野兽的力量同时也意味着有责任尊重自然平衡，并对周围的世界怀有敬畏之心。"}},faq={{q="艾萨克·陈 是谁？",a="艾萨克·陈 是一位资深的、终身的林务员，居住在艾尔文森林的闪金镇。他因对野生动物和荒野生存的深刻理解而备受尊敬，并教导新手猎人如何适当地引导、喂养、复活他们的野兽伙伴，并传授它们技能。",al={"艾萨克·陈 是谁","闪金镇野兽训练师","艾萨克·陈 背景故事"}},{q="训练野兽的目的是什么？",a="虽然猎人可能已经知道如何驯服野兽，但该任务提供了维持这种羁绊的必要知识。它指导猎人如何喂养他们的伙伴，在伙伴战斗中倒下时将其复活，并教给它们新的战斗技能。",al={"这个任务有什么用","为什么要训练野兽","训练野兽 的目的"}},{q="在哪里可以找到 艾萨克·陈？",a="艾萨克·陈 位于闪金镇，这是艾尔文森林的中心城镇，位于北郡山谷正南方，暴风城西南方。",al={"艾萨克·陈 在哪里","我在哪里交这个任务","艾萨克·陈 位置"}},{q="艾萨克·陈 教授什么技能？",a="艾萨克·陈 传授宠物照料和训练的核心原则。这包括喂养野兽以维持其健康，在它战斗中死亡时将其复活，以及在它随你成长时教给它新的能力。",al={"能学到什么技能","学习的宠物技能","艾萨克·陈 教什么"}},{q="为什么 艾萨克·陈 提醒猎人要尊重自然？",a="艾萨克·陈 强调，驾驭野兽需要谦逊而非支配。他敦促猎人尊重自然界的平衡，并对周围的自然怀有敬畏之心，确保猎人和野兽之间的伙伴关系建立在守护而非剥削的基础上。",al={"为什么尊重自然","猎人尊重平衡"}},{q="谁会执行这个任务？",a="训练野兽是专门为那些已经获得了驯服野兽的初始能力，并且需要维持和训练野兽伙伴所需的林地纪律的猎人量身定制的。",al={"谁可以做这个任务","训练野兽 是猎人专属吗"}}},fp="18,184,32.248.0,21.284.0,18.217.0,42.181.0,30.129.0,34.194.0,53.207.0,26.115.0"}
P.entries["quest:948"] = {n="安努",s="这个任务要求旅行者从奥伯丁出发向南前往古树之林，去拜见奥努。在探查了峭壁之泉后的洞穴后，你的发现已经引起了黑海岸最古老的守护者之一的密切关注。",h="这个任务要求旅行者从奥伯丁出发向南前往古树之林，去拜见奥努。在探查了峭壁之泉后的洞穴后，你的发现已经引起了黑海岸最古老的守护者之一的密切关注。",kw={"知识古树","奥伯丁","巴瑞萨斯·月影","峭壁之泉","黑海岸","古树之林","奥努"},ang={["class:Druid"]="德鲁伊们深切地尊崇古树，视其为自然智慧的化身。按照奥努的要求调查奇怪的洞穴生长物，完全符合塞纳里奥议会的职责。",["faction:Alliance"]="对于帮助保卫黑海岸的联盟旅行者来说，获得当地古树的信任与洞见，对于在卡利姆多神秘的北部荒野中穿行至关重要。",["race:NightElf"]="知识古树是卡多雷神圣的伙伴，自从大分裂之前就一直指引着你们的人民。回应奥努的召唤，是维护黑海岸神圣不可侵犯的一项庄严职责。"},sec={{t="来自古树的召唤",b="在带着从峭壁之泉深处采集的真菌样本返回奥伯丁后，巴瑞萨斯·月影意识到，这些发现的意义绝非仅仅是植物学上的好奇。被污染的洞穴的消息很快传到了奥努耳中，这是一位扎根于镇南古树之林那片宁静圣所中的知识古树。尽管古树生物天性耐心且深沉，但奥努如此急切地想要商议，表明黑海岸水道中蔓延的腐蚀可能触及了一些古老而令人不安的力量。"},{t="前往树林",b="沿着奥伯丁南下的道路前行，便可远离海岸遗迹，深入内陆，向山坡走去。古树之林是自然之力的祖传堡垒，在很大程度上躲避了侵蚀海岸线的腐朽蔓延。在这里，奥努等待在参天的石冢和同类灵体之间，准备指引盟友前往荒野边缘那些更深、更可怕的枯萎之源。"}},faq={{q="奥努是谁？",a="奥努是一位知识古树，是一个巨大的、有思想的树人守护者，致力于收集和保存知识。他坐镇在黑海岸南部的古树之林，为这片土地的保卫者提供智慧和指引。",al={"奥努是谁","奥努的身份","奥努是什么"}},{q="为什么奥努想和我谈谈？",a="你最近深入峭壁之泉下的洞穴，为巴瑞萨斯·月影采集了真菌样本。在那里发现的奇特事物引起了博物学家的警觉，促使奥努请求会面，以应对日益严重的腐蚀问题。",al={"为什么奥努召唤我","谈话原因","为什么要去见奥努"}},{q="古树之林在哪里？",a="古树之林位于奥伯丁以南，坐落在东部山脉的山麓边。沿着黑海岸的主路向南走，然后向东前往山坡，就能找到奥努。",al={"奥努的位置","古树之林在哪里","如何找到奥努"}},{q="知识古树是什么样的生物？",a="知识古树是与暗夜精灵及塞纳里奥议会结盟的古老树人生物。它们因其深厚的智慧和记忆而备受尊崇，是自然魔法和历史秘密的活体宝库。",al={"知识古树","奥努是什么生物","树人和古树的区别"}},{q="为什么奥努的召唤被认为是紧急的？",a="众所周知，古树的行事风格深思熟虑、从容不迫，很少会匆忙行事。正如巴瑞萨斯·月影所指出的，如果像奥努这样耐心且有条理的生物主动要求与你商议，那么黑海岸面临的威胁一定非常严重。",al={"为什么紧急","奥努是否担心","巴瑞萨斯的警告"}},{q="与奥努会面后会发生什么？",a="在你到达古树之林后，奥努会请求你的协助，去调查海岸以南更远处的巨大威胁：围绕着主宰之剑正在进行的险恶挖掘活动。",al={"奥努之后的下一个任务","接下来会发生什么","奥努让你去哪里"}}},fp="3,166,27.409.0,20.339.0,11.167.0,35.197.0,35.190.0,44.180.0,39.132.0,34.167.1"}
P.entries["quest:94819"] = {n="Contingency Plan",s="有人派你前往铁炉堡会见 High Priestess Mims。你的下一场试炼即将到来，她正在秘法区等你。",h="有人派你前往铁炉堡会见 High Priestess Mims。你的下一场试炼即将到来，她正在秘法区等你。",kw={"应急计划","high priestess mims","铁炉堡","light","秘法区","下一场试炼","仪式"},sec={{t="等候会面",b="在铁炉堡，High Priestess Mims 正在秘法区等你前去交谈。你的下一场试炼即将到来，而派你前来的人无法离开自己的岗位，见证你们族人的仪式。你前去会见 Mims 时，对方祝愿 Light 与你同行。"}},faq={{q="我应该去见谁？",a="High Priestess Mims 正在铁炉堡的秘法区等你前去交谈。",al={"谁在等候","会见 mims","mims"}},{q="我在哪里能找到 Mims？",a="Mims 应该在铁炉堡的秘法区。",al={"mims 在哪里","mims 的位置","秘法区"}},{q="我为什么要去铁炉堡？",a="High Priestess Mims 想在那里与你交谈，而你的下一场试炼即将到来。",al={"为什么去铁炉堡","铁炉堡有什么","会面"}},{q="派我来的人对我们族人的仪式说了什么？",a="派你来的人希望能见证你们族人的仪式，但表示自己必须留在原处。",al={"我们族人的仪式","特殊仪式","他们为什么不能来"}},{q="对我的旅途有什么祝愿？",a="派你来的人祝愿 Light 与你同行。",al={"light 的祝福","light 与我同行","旅途祝福"}}},fp="16,129,18.253.0,23.76.0,22.47.0,28.82.0,49.97.0,30.61.0"}
P.entries["quest:94822"] = {n="Confounding Flash",s="你的上级派你前往铁炉堡，跟随High Priestess Mims继续接受训练。你为Light所做的贡献已引起他们的注意。",h="你的上级派你前往铁炉堡，跟随High Priestess Mims继续接受训练。你为Light所做的贡献已引起他们的注意。",kw={"confounding flash","hall of mysteries","high priestess mims","铁炉堡","light","上级","训练"},sec={{t="进一步的教导",b="你的上级派你去铁炉堡的秘法大厅寻找High Priestess Mims。他们认为，你所做的贡献已让你具备接受进一步训练的资格。Mims将指导你，只待你抵达便可开始授课。"},{t="拜见Mims",b="High Priestess Mims在铁炉堡接见了你，并指出你来迟了。念及你为Light所做的贡献，她原谅了你的迟到，随后请你用心听取她的教导。"}},faq={{q="是谁派我去铁炉堡的？",a="你的上级让你前往铁炉堡的秘法大厅，接受进一步的训练。",al={"谁派我来的","我的上级是谁"}},{q="High Priestess Mims是谁？",a="High Priestess Mims就是你的上级指示你去铁炉堡寻找的人。她能指导你继续接受训练。",al={"mims是谁","mims"}},{q="为什么派我去接受训练？",a="你的上级认为，你为Light所做的贡献已证明了你的能力。",al={"为什么接受训练","为什么选我"}},{q="在哪里能找到High Priestess Mims？",a="前往铁炉堡的秘法大厅寻找High Priestess Mims。",al={"mims在哪里","hall of mysteries"}}},fp="17,139,16.203.0,11.169.0,25.94.0,27.115.0,33.82.0,36.63.0"}
P.entries["quest:94824"] = {n="Confounding Flash",s="一封信让你前往铁炉堡与高阶女祭司 Mims 谈话。她在 Hall of Mysteries 等你，但信中没有说明缘由。",h="一封信让你前往铁炉堡与高阶女祭司 Mims 谈话。她在 Hall of Mysteries 等你，但信中没有说明缘由。",kw={"confounding flash","hall of mysteries","高阶女祭司 mims","铁炉堡","与 mims 谈话","召见"},sec={{t="铁炉堡的召唤",b="前方的路通往铁炉堡，高阶女祭司 Mims 正在 Hall of Mysteries 等候。信中让你亲自前去与她谈话，却没有说明召见的缘由。信中猜测你的事迹进展顺利，但具体情况还得由 Mims 解释。"}},faq={{q="谁要和我谈话？",a="高阶女祭司 Mims 想让你来铁炉堡与她谈话。",al={"谁召见我","mims 召见","高阶女祭司 mims"}},{q="我该去哪里？",a="有人请你前往铁炉堡的 Hall of Mysteries，与高阶女祭司 Mims 谈话。",al={"mims 在哪里","hall of mysteries 位置","前往铁炉堡"}},{q="Mims 为什么要见我？",a="信中没有说明高阶女祭司 Mims 想与你谈话的原因。",al={"mims 召见我的原因","她想要什么","召见缘由"}},{q="要我做什么？",a="有人请你前往铁炉堡与高阶女祭司 Mims 谈话。",al={"任务是什么","与 mims 谈话","mims 的请求"}}},fp="17,148,19.277.0,27.66.0,14.86.0,29.77.0,28.67.0"}
P.entries["quest:94841"] = {n="Lost Shipping Crate",s="一只标有 Friz Frazzlespark 收件信息的货箱在河林失踪了。标签要求将它送回爆破引线港。",h="一只标有 Friz Frazzlespark 收件信息的货箱在河林失踪了。标签要求将它送回爆破引线港。",kw={"货箱","friz frazzlespark","标签","遗失的货箱","地图","爆破引线港","河林"},sec={{t="带有标记的货箱",b="Friz Frazzlespark 的货箱上贴着一张手写标签，写明目的地是河林的爆破引线港。地图标出一处东南海岸，位于一座四面环水的神庙以北，附近还有带翅膀的生物。标签警告，未经监督不得打开货箱，并注明由 Friz 接收。"}},faq={{q="这只货箱属于谁？",a="标签上写着，货箱属于 Friz Frazzlespark。",al={"货箱主人","谁拥有它"}},{q="我该把货箱送到哪里？",a="标签要求将货箱送到河林的爆破引线港，交给 Friz Frazzlespark。",al={"货箱送货地点","货箱递送"}},{q="货箱上的标签写了什么？",a="标签注明了 Friz Frazzlespark 和爆破引线港，警告未经监督不得打开货箱，并写明了河林的送还地点。",al={"货箱标签","上面写了什么"}},{q="可以安全地打开货箱吗？",a="标签写着，未经监督不得打开货箱。",al={"打开货箱","货箱警告"}}},fp="19,137,14.300.0,28.55.0,30.94.0,32.153.0,26.50.0"}
P.entries["quest:94863"] = {n="Taming the Beast",s="“驯服野兽”是一项由Josephine Carson监督的猎人训练课程。在学习了驯服野猪的野兽掌控基础知识后，有抱负的猎人必须使用驯兽棒来赢得一只更凶猛的灰森林狼的信任。",h="“驯服野兽”是一项由Josephine Carson监督的猎人训练课程。在学习了驯服野猪的野兽掌控基础知识后，有抱负的猎人必须使用驯兽棒来赢得一只更凶猛的灰森林狼的信任。",kw={"野兽驯服","灰森林狼","猎人","猎人训练","约瑟芬·卡森","驯兽棒","驯服野兽"},ang={["class:Hunter"]="这项训练标志着猎人成长过程中的重要仪式，教会了猎人与荒野中凶猛的掠食者交流所需的耐心与尊重。"},sec={{t="猎人之道",b="猎人与荒野的联系不仅仅需要追踪和射击技巧，更需要赢得野生生物信任所需的尊重与耐心。在通过简单的野猪证明了自己的基础技能后，有抱负的猎人们将面临一项更严峻的挑战：深入森林，驯服一只灰森林狼。在训练师Josephine Carson的注视下，猎人将被授予一根附魔的驯兽棒，用以安抚这只掠食者，并学习猎人与野兽之间微妙的平衡。"},{t="本能与信任的考验",b="Josephine Carson为猎人提供了一根特制的驯兽棒，旨在引导一种能够让猎人接近危险野生动物的安抚力量。这项任务需要耐心和精确，因为必须在不使用致命武力的情况下接近狼，并温和地克服其天生的攻击性。一旦建立了联系，且猎人证明了自己能够与野兽的精神和谐相处，驯兽棒就会归还给Josephine，作为猎人对荒野掌控力日益增强的证明。"}},faq={{q="什么是“驯服野兽”任务？",a="“驯服野兽”是一项猎人训练试验，训练师会要求有抱负的猎人使用附魔的驯兽棒追踪并驯服一只灰森林狼。",al={"驯服野兽任务","灰森林狼任务","驯狼课程"}},{q="谁发布并完成这个任务？",a="约瑟芬·卡森担任这项试验的指导员。她提供驯兽棒，并在任务完成后评估你与森林野兽之间的联系，随后收回驯兽棒。",al={"谁发布驯服野兽","约瑟芬·卡森是谁","驯服野兽交任务地点"}},{q="你需要驯服什么生物？",a="你的任务是驯服一只灰森林狼，这比你之前练习驯服的野猪更进一步，难度也更高。",al={"我要驯服什么","什么野兽","驯服野兽的目标"}},{q="驯兽棒有什么用？",a="驯兽棒是约瑟芬·卡森提供的一种教学工具，旨在帮助见习猎人安抚野生的灰森林狼并与之建立临时的联系，而不会造成永久性的伤害。",al={"驯兽棒的作用","为什么要用驯兽棒","驯兽棒背景故事"}},{q="猎人在这次试验前驯服了什么？",a="在面对灰森林狼之前，你通过掌握如何驯服一只森林野猪，展示了你对野兽掌控的初步能力。",al={"之前的驯服课程","在狼之前驯服了什么"}},{q="灰森林狼会成为永久的伙伴吗？",a="不会，这项试验旨在作为掌握野兽羁绊技巧的集中课程。当你练习完技巧后，需要将驯兽棒归还给约瑟芬·卡森。",al={"狼会保留吗","狼是永久宠物吗"}}},fp="16,174,22.331.0,28.279.0,35.112.0,35.99.0,34.107.0,32.133.0,43.73.0,58.94.0"}
P.entries["quest:94864"] = {n="驯服野兽",s="驯服野兽是猎人在艾尔文森林初期训练的最终考验，由约瑟芬·卡森负责监督。在证明了驯服野猪和狼的能力后，猎人们需要使用驯兽棒来安抚一头森林幼熊，并赢得它的信任。这项最终试炼加深了猎人与野兽之间的协调，并通过尊重与技巧来维护林地的自然平衡。",h="驯服野兽是猎人在艾尔文森林初期训练的最终考验，由约瑟芬·卡森负责监督。在证明了驯服野猪和狼的能力后，猎人们需要使用驯兽棒来安抚一头森林幼熊，并赢得它的信任。这项最终试炼加深了猎人与野兽之间的协调，并通过尊重与技巧来维护林...",kw={"与野兽协调","野兽训练","艾尔文森林","猎人任务","约瑟芬·卡森","驯兽棒","驯服野兽","森林幼熊"},ang={["class:Hunter"]="这项试炼标志着学徒猎人的一个重要成年仪式，将简单的追踪技巧转化为与荒野野兽之间深刻的共情与协调。",["faction:Alliance"]="熟练的兽王猎人加强了联盟的荒野侦察力量，他们提供的训练有素的同伴能够保卫家园并巡逻暴风城领地内的贸易道路。",["race:Human"]="对于在艾尔文森林训练的人类猎人来说，驯服当地野生生物教会了他们与王国的天然掠食者共存的重要性，而不是仅仅将其消灭。"},sec={{t="狩猎的最终试炼",b="艾尔文森林的准猎人们需要接受严格的训练，以了解与他们共享这片土地的野生生物。在已经展示了对狡猾的狼和强韧的野猪的控制力后，猎人们将面临勇气与耐心的终极测试。约瑟芬·卡森指导他们去面对森林幼熊，这是森林中最强壮、最威猛的常见掠食者。这项仪式旨在考验猎人能否承受熊的原始力量，并赢得它的信任，而不是单纯的征服。"},{t="艾尔文森林的尊重与平衡",b="驯服艾尔文森林野生生物的课程核心在于尊重，而非支配。森林熊代表了林地的力量与活力，在维护自然秩序方面发挥着至关重要的作用。通过使用专门制作的驯兽棒，猎人学会了平息野兽的侵略性，并建立起一种真正的相互理解的纽带。成功安抚这种强大的动物不仅能加深猎人对荒野的精神协调，也完成了他们在卡森指导下的基础课程。"}},faq={{q="是谁向猎人指派这项试炼的？",a="约瑟芬·卡森负责监督艾尔文森林猎人的这项试炼。在猎人成功驯服次级野兽后，她会对猎人的进度进行评估，并提供驯服森林熊所需的指导和驯兽棒。试炼完成后，猎人会直接将棒子交还给她，以标志训练的圆满完成。",al={"谁给予驯服野兽任务","驯服野兽任务发布者","约瑟芬·卡森任务"}},{q="在挑战这项试炼之前必须驯服哪些野兽？",a="在进行驯服森林幼熊的挑战之前，猎人必须先通过驯服野猪和狼来证明自己的技巧与耐心。这些初步试炼证明了猎人在尝试面对艾尔文森林熊的强大力量之前，已经能够应对好斗的野兽和群体性野兽。",al={"驯服任务的前置野兽","驯服熊之前驯服什么","在此之前驯服的野兽"}},{q="为什么要让猎人去寻找森林幼熊？",a="森林幼熊代表了艾尔文森林野生生物的力量与威猛。野猪和狼测试了猎人处理敏捷或顽强野兽的能力，而熊则是对忍耐力、尊重和身体勇气的终极考验。赢得这种强大掠食者的信任，证明了猎人已经完全掌握了基础的野兽驯服技巧。",al={"为什么驯服森林幼熊","森林幼熊的目的","为什么艾尔文有熊"}},{q="驯兽棒的用途是什么？",a="驯兽棒是约瑟芬·卡森提供的一种特殊训练工具，用于帮助猎人安抚野生动物。它能引导猎人集中精神，在不杀死森林幼熊的情况下平息其攻击性，从而建立起和平的纽带。试炼结束后，随着训练完成，驯兽棒会被交还给卡森。",al={"驯兽棒的作用","驯兽棒的功能","为什么要使用驯兽棒"}},{q="驯服野兽如何帮助艾尔文森林？",a="驯服野生生物被视为维护艾尔文森林自然平衡的一项必要实践。通过以尊重和克制而非狩猎的方式对待掠食者，猎人有助于保护当地生态系统与整个地区的人类定居点之间的和谐，确保危险的野兽得到和平引导，而不是被消灭。",al={"为什么艾尔文的平衡很重要","艾尔文森林平衡","驯服与森林平衡"}},{q="完成这门课程对猎人意味着什么？",a="完成这项最终任务加深了猎人与荒野野兽之间内在的协调。通过赢得艾尔文森林最强大生物的信任，猎人超越了简单的狩猎技巧，掌握了与艾泽拉斯各地的动物同伴建立终身伙伴关系所需的精神连接。",al={"驯服熊之后会发生什么","猎人训练完成","与野兽协调的意义"}},{q="在哪里可以找到森林幼熊？",a="森林幼熊在艾尔文森林的林区中游荡，与狼和蜘蛛一起生活在茂密的树林中。从附近定居点出发的猎人必须在森林的灌木丛中追踪这些强壮的生物，以便使用驯兽棒并完成卡森的最终指令。",al={"森林幼熊位置","在艾尔文哪里找熊","艾尔文森林熊"}}},fp="16,291,27.363.0,29.396.0,34.219.0,49.184.0,47.224.0,38.240.0,42.245.0,54.219.0,35.246.0"}
P.entries["quest:94873"] = {n="Buying Friendship: 吉尔吉斯",s="一名外来者在吉尔吉斯村送给吉尔吉斯氏族一包图腾。他们的军需官认为这份礼物能帮助他们对抗玛格拉姆氏族。",h="一名外来者在吉尔吉斯村送给吉尔吉斯氏族一包图腾。他们的军需官认为这份礼物能帮助他们对抗玛格拉姆氏族。",kw={"购买友谊","半人马","吉尔吉斯","吉尔吉斯氏族","吉尔吉斯村","玛格拉姆","molkar","图腾包"},sec={{t="送给吉尔吉斯人的礼物",b="有人准备了一包图腾，让你带给吉尔吉斯村的吉尔吉斯军需官。吉尔吉斯人正被玛格拉姆人步步逼退，他们与世隔绝的处境或许会让他们愿意接受外界的帮助。这份礼物旨在提升你在氏族中的声望。"}},faq={{q="为什么要给吉尔吉斯人送一包图腾？",a="这份礼物旨在提升你在吉尔吉斯氏族中的声望，而他们正被玛格拉姆人步步逼退。",al={"图腾包","为何送图腾","吉尔吉斯人的礼物"}},{q="这包图腾要交给谁？",a="吉尔吉斯村的吉尔吉斯军需官会收下这包图腾。",al={"吉尔吉斯军需官","谁收下图腾包","图腾接收者"}},{q="吉尔吉斯人面临什么困境？",a="吉尔吉斯人正处于对抗玛格拉姆人的劣势一方，而玛格拉姆氏族一反常态地凶残。",al={"吉尔吉斯人的困境","玛格拉姆与吉尔吉斯","为何落败"}},{q="Molkar是谁？",a="Molkar是收下这包图腾的吉尔吉斯军需官。",al={"吉尔吉斯人molkar","军需官molkar","molkar是谁"}}},fp="25,137,21.259.0,38.102.0,22.61.0,32.92.0,14.57.0"}
P.entries["quest:94890"] = {n="Bring Me His Head",s="军士长Riftan派你重返暮光之帷，霸主Kilgar仍藏身于他的要塞中。获救的士兵已准备好战斗，Riftan要你击败Kilgar。",h="军士长Riftan派你重返暮光之帷，霸主Kilgar仍藏身于他的要塞中。获救的士兵已准备好战斗，Riftan要你击败Kilgar。",kw={"把他的头带给我","兽人","霸主kilgar","获救的士兵","军士长riftan","暮光之帷"},sec={{t="重返要塞",b="获救的士兵跃跃欲试，军士长Riftan说，你的力量助攻势推进至今。兽人霸主Kilgar藏身于暮光之帷的要塞深处。Riftan要你击败他，把他的头带回来。"}},faq={{q="霸主Kilgar是谁？",a="霸主Kilgar是兽人首领，藏身于暮光之帷的要塞深处。",al={"kilgar","kilgar是谁","兽人首领"}},{q="为什么要我重返暮光之帷？",a="获救的士兵已准备好战斗，军士长Riftan说攻势应当继续。他要你返回暮光之帷，把霸主Kilgar的头带回来。",al={"为何返回","暮光之帷任务","接下来做什么"}},{q="谁要Kilgar的头？",a="军士长Riftan要你把霸主Kilgar的头带给他。",al={"riftan要什么","谁要杀kilgar","把他的头带给我"}},{q="Kilgar藏在哪里？",a="霸主Kilgar藏身于暮光之帷的要塞深处。",al={"kilgar的位置","霸主在哪里","kilgar的要塞"}}},fp="17,185,16.255.0,23.86.0,50.180.0,24.61.0,23.72.0"}
P.entries["quest:94891"] = {n="News to Farholde",s="法霍德要塞的Ashe Amberhall正等着你汇报与Sergeant Riftan共事的结果。你的归来将证明这次行动是否成功。",h="法霍德要塞的Ashe Amberhall正等着你汇报与Sergeant Riftan共事的结果。你的归来将证明这次行动是否成功。",kw={"ashe amberhall","法霍德要塞","kilgar","法霍德的消息","报告","sergeant riftan"},sec={{t="向Ashe汇报",b="Sergeant Riftan让你带着报告回法霍德要塞，交给Ashe Amberhall。他把Kilgar的头交给你带上。Ashe说，你离开期间，她开始怀疑自己的判断，如今却称赞你的本领。"}},faq={{q="该向谁汇报？",a="法霍德要塞的Ashe Amberhall正等着你汇报。",al={"该向谁汇报","ashe的报告","法霍德汇报"}},{q="Riftan给了我什么？",a="Sergeant Riftan把Kilgar的头交给你，让你带给Ashe Amberhall。",al={"riftan扔回了什么","kilgar的头","我带着什么"}},{q="我回来时Ashe说了什么？",a="Ashe说，她开始担心自己看错了你的本领，随后又说你确实适合这份差事。",al={"amberhall的反应","ashe的对话","ashe是否担心"}},{q="Ashe怎么评价Riftan？",a="Ashe问Riftan是否还在附近，并说她原以为你们俩会相处融洽。",al={"riftan还活着吗","sergeant riftan怎么样了","ashe和riftan"}}},fp="16,141,17.222.0,21.59.0,25.66.0,33.98.0,32.84.0"}
P.entries["quest:94892"] = {n="Dying Wish",s="Ryan元帅濒临死亡，请你将他的纹章带给骑士指挥官Demar Brant。他最后的话语转向了家乡和Abigail。",h="Ryan元帅濒临死亡，请你将他的纹章带给骑士指挥官Demar Brant。他最后的话语转向了家乡和Abigail。",kw={"abigail","纹章","遗愿","法霍德要塞","骑士指挥官demar brant","ryan元帅","ryan"},sec={{t="Ryan的遗言",b="Ryan的目光渐渐黯淡，他提起家乡和Abigail。元帅把纹章交给你，请你警告骑士指挥官Demar Brant。你带着象征他军衔的纹章前往法霍德要塞，指挥官正在那里等候。"}},faq={{q="谁濒临死亡？",a="Ryan元帅濒临死亡时，请你把他的纹章带给骑士指挥官Demar Brant。",al={"遗愿 谁","ryan元帅"}},{q="Ryan要我做什么？",a="Ryan请你把他的纹章带给骑士指挥官Demar Brant，并警告他。",al={"ryan的请求","纹章怎么处理"}},{q="Abigail是谁？",a="Ryan的遗言提到了Abigail，并说他本该回家。",al={"abigail ryan","abigail是谁"}},{q="我该把纹章带到哪里？",a="把Ryan元帅的纹章带给法霍德要塞里的骑士指挥官Demar Brant。",al={"纹章在哪","demar brant位置"}}},fp="10,132,19.218.0,13.89.0,29.78.0,15.68.0,26.75.0"}
P.entries["quest:94893"] = {n="Delivering Closure",s="Demar请你把元帅 Ryan 的徽章交给暴风城的 Abigail Lawson。Ryan 的死留下了一封信，写给他曾打算迎娶的女人。",h="Demar请你把元帅 Ryan 的徽章交给暴风城的 Abigail Lawson。Ryan 的死留下了一封信，写给他曾打算迎娶的女人。",kw={"abigail lawson","教堂广场","了结遗憾","demar","法霍德要塞","元帅 ryan","ryan 的徽章","暴风城"},sec={{t="暴风城的留言",b="Abigail Lawson 在教堂广场等候，你替 Demar 把元帅 Ryan 的徽章带给她。Ryan 和 Demar 建立法霍德要塞时，她没有加入他们。Ryan 和 Abigail 曾有分歧，但 Demar 不知道原因。他认为自己若在场，她不会欢迎，因此只能让徽章代他传达心意。"},{t="未曾说出口的话",b="Ryan 的家人在兽人入侵期间丧生，他对抗部落的责任感也变成了仇恨。Demar 曾劝他去暴风城与 Demar 的父母同住，但 Ryan 拒绝了。他发誓要留下，直到把兽人赶出自己的家园。此后，Ryan 和 Abigail 便再也没有交谈。"},{t="收下徽章",b="你带来徽章时，Abigail 谈起 Ryan 不肯离开家园，也谈起他们之间漫长的沉默。她称 Demar 是英雄，却提醒你，英雄常会给身边的人带来危险。随后，她将 Ryan 的徽章紧紧握在胸前，骂他是个傻瓜。"}},faq={{q="Abigail Lawson 是谁？",a="Abigail Lawson 曾与元帅 Ryan 订下婚约。她住在暴风城，Ryan 和 Demar 在法霍德要塞时，她没有加入他们。",al={"abigail 是谁","谁是 abigail","ryan 的未婚妻"}},{q="是谁让我带去 Ryan 的徽章？",a="Demar 请你把元帅 Ryan 的徽章交给暴风城的 Abigail Lawson。他认为她不会欢迎自己在场。",al={"是谁派我来的","demar 的徽章","谁要我送徽章"}},{q="Ryan 为什么留下？",a="Ryan 的家人在兽人入侵期间丧生后，他对抗部落的责任感变成了仇恨。他发誓要留下，直到把兽人赶出自己的家园。",al={"ryan 留下的原因","ryan 和兽人","他的家人"}},{q="Abigail 和 Ryan 为什么不再交谈？",a="Abigail 和 Ryan 曾有分歧，但 Demar 不清楚具体缘由。此后，他们便再也没有交谈。",al={"他们为何不再交谈","abigail 和 ryan","他们的分歧"}},{q="Ryan 的徽章有什么用？",a="Demar 请你把元帅 Ryan 的徽章交给暴风城教堂广场的 Abigail Lawson。",al={"元帅的徽章","ryan 的徽章","我要带什么"}}},fp="18,150,22.324.0,17.284.0,18.252.1,22.126.0,36.131.0,25.162.0,39.102.0,27.101.0"}
P.entries["quest:94894"] = {n="The Twilight Threat",s="Farholde请求暴风城出手，抵御暮光之锤活动的突然增加。你将证据带给伯瓦尔·弗塔根，但联盟还有其他战事需要应对。",h="Farholde请求暴风城出手，抵御暮光之锤活动的突然增加。你将证据带给伯瓦尔·弗塔根，但联盟还有其他战事需要应对。",kw={"伯瓦尔·弗塔根","brant","farholde","部落","kilgar","河林","暴风要塞","暮光之锤"},ang={["faction:Alliance"]="作为联盟冒险者，你将Farholde的证据带给伯瓦尔·弗塔根。Farholde的居民则寻求援助，以对抗暮光之锤和部落。"},sec={{t="Farholde的恳求",b="Amberhall女士听说你与暮光之锤打过交道后，Farholde的居民便向你求助。他们发起行动，意在将部落赶出故土，但邪教徒的活动已急剧增加。他们担心，在Farholde腹背受敌之前，暴风城不会回应他们的请求。你将证据带到暴风要塞，交给伯瓦尔·弗塔根。"},{t="暴风城的答复",b="在暴风要塞，伯瓦尔·弗塔根听取了Farholde传来的警告。他说，联盟已经卷入规模大得多的战争，无法把力量耗费在一个小村庄的私人恩怨上。部落摧毁的家园，比河林一带遭到摧毁的还要多。伯瓦尔认为，Brant很可能不会放下傲气，派骑兵来援助联盟。"}},faq={{q="谁在请求暴风城援助？",a="暮光之锤活动日益猖獗，Farholde因此请求暴风城援助。",al={"谁在求助","farholde的恳求","谁派我来"}},{q="Farholde为何担忧？",a="Farholde担心，如果暴风城不回应他们的请求，他们就会腹背受敌，难以招架。",al={"farholde出了什么事","邪教徒的问题","为何担忧"}},{q="我带着什么证据？",a="你将Kilgar's Head带到暴风要塞，交给伯瓦尔·弗塔根。",al={"什么证据","kilgar的头颅","送交头颅"}},{q="伯瓦尔在听取谁的消息？",a="伯瓦尔·弗塔根收到了Farholde的消息。Farholde发起行动，意在将部落赶出故土。",al={"谁传来消息","farholde的报告","伯瓦尔的问题"}},{q="暴风城为何无法支援Farholde？",a="伯瓦尔说，联盟正在应对规模大得多的战争，没有足够的资源支援Farholde解决私人恩怨。",al={"为何没有援助","暴风城支援","伯瓦尔拒绝"}}},fp="19,175,15.357.0,18.365.1,30.69.0,24.100.0,25.62.0,27.105.0,37.120.0"}
P.entries["quest:94895"] = {n="Lost Shipping Crate",s="Friz Frazzlespark 的货箱从河林的爆破引线港失踪了。标签警告，未经看管不得打开，并请你将货箱归还给 Friz。",h="Friz Frazzlespark 的货箱从河林的爆破引线港失踪了。标签警告，未经看管不得打开，并请你将货箱归还给 Friz。",kw={"货箱标签","货箱地图","friz frazzlespark","遗失的货箱","爆破引线港","河林","警告"},sec={{t="有标记的货箱",b="一张地图和一则警告标明了你带着穿过河林的货箱。标签上写着 Friz Frazzlespark 和爆破引线港的名字，并注明货箱遗失时应送回那里。你正把货箱送回主人手中。"}},faq={{q="谁是货箱的主人？",a="标签上写明，货箱的主人是 Friz Frazzlespark。",al={"货箱主人","谁拥有这个","friz 的货箱"}},{q="我该把货箱送到哪里？",a="货箱应送回河林爆破引线港的 Friz Frazzlespark 手中。",al={"货箱归还地点","货箱目的地","爆破引线港"}},{q="标签上有什么警告？",a="标签警告不得擅自处理货箱，并说明未经看管不得打开。",al={"货箱警告","可以打开吗","打开货箱"}},{q="货箱的地图上标记了什么？",a="地图上，东南方海岸边有一个红圈；它位于一座画得很粗糙、四周环水且有飞翼生物盘旋的神庙以北。",al={"货箱地图","地图上有什么","地图上的红圈"}}},fp="19,188,14.214.0,28.69.0,30.87.0,31.85.0,34.131.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="“Aid For The Refugees”聚焦于班艾萨尔的流离失所的幸存者们，这是一个深藏在影风森林中的定居点，在深夜时分被突然疏散。随着他们的家园坠入天空，周围的荒野也变得太过危险而无法进入，难民们只能依靠勇敢的旅行者来找回他们不得不留下的财物。",h="“Aid For The...",kw={"援助难民","班艾萨尔","财物","伊拉妮","难民","影风森林"},sec={{t="绝望的恳求",b="“Aid for the Refugees”是Ealaane和她流离失所的村民同伴们发出的求助。在险些逃离了深藏于影风森林的家园后，幸存者们聚集在一起，几乎一无所有，希望路过的旅行者能勇闯他们留下的危险之地。"},{t="班艾萨尔的灾难",b="班艾萨尔定居点在深夜遭遇了难以想象的命运，整个村庄突然开始坠入天空。这场怪异而恐怖的灾难只给居民们留下了片刻的逃生时间，迫使他们在周围森林变得充满敌意和危险时，不得不放弃了他们的个人财物。"}},faq={{q="伊兰妮是谁？",a="伊兰妮是班艾萨尔的一名难民，在他们的定居点开始崩塌时，她与其他幸存者一起逃了出来。她请求路过并前往影风森林的冒险者们找回留在废墟中的个人财物。",al={"谁发布了援助难民","援助难民任务发布者","伊拉妮"}},{q="班艾萨尔发生了什么？",a="班艾萨尔是深藏于影风森林中的一处定居点。由于一场突如其来的离奇灾难，其居民最近被迫在深夜进行了疏散。",al={"什么是班艾萨尔","班艾萨尔在哪里","班艾萨尔村"}},{q="村民们为什么要疏散班艾萨尔？",a="疏散行动在深夜突然触发，当时班艾萨尔开始坠入天空。村庄和周围的森林变得太过危险，以至于居民们无法留下或返回。",al={"为什么要疏散班艾萨尔","坠入天空","班艾萨尔灾难"}},{q="村民们为什么要请求找回他们的财物？",a="这场灾难在深夜突然降临，迫使村民们在几乎一无所有的情况下逃命。由于森林和废墟现在充满了危险，他们只能依靠有能力的冒险者来取回留下的东西。",al={"为什么要找回财物","被遗弃的财物","为何要回收财物"}},{q="什么是影风森林？",a="影风森林是拥有班艾萨尔定居点的林区。在撕裂了村庄的离奇灾难发生后，这片森林对普通人来说已经变得极其危险。",al={"影风森林在哪里","影风森林背景故事"}},{q="难民们能回到他们的家园吗？",a="不能。据伊兰妮所说，无论是影风森林还是班艾萨尔废墟，对于流离失所的居民来说都太过危险，他们无法独自返回。",al={"难民能回去吗","班艾萨尔安全吗"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="\"The Fate of a Loved One\" 是一项关于 Resaan 的任务，他冒险进入危险的班艾萨尔废墟搜寻补给，却一去不回。一周多过去了，他悲痛的伴侣请求前往该废墟的旅人们查明他的下落，要么带他回家，要么寻回他珍视的传家宝。",h="\"The Fate of a Loved One\" 是一项关于 Resaan...",kw={"班艾萨尔","传家宝","雷萨恩","班艾萨尔废墟","补给","挚爱之人的命运"},sec={{t="绝望的恳求",b="\"The Fate of a Loved One\" 的核心是一位绝望者的请求，他的伴侣 Resaan 冒险重回了班艾萨尔废墟。尽管曾恳切地劝他留下，Resaan 还是执意要闯入废墟寻找补给，留下某人在痛苦的未知中等待。"},{t="消失在废墟中",b="自 Resaan 出发以来已经过去了一周多，这远远超出了能够迅速返回的预期。前往班艾萨尔废墟的旅人们受托在废墟中寻找他——如果他还活着，就指引他回来；如果只剩下不幸的结果，就寻回他的家族传家宝。"}},faq={{q="雷萨恩 是谁？",a="雷萨恩 是一名冒险回到班艾萨尔废墟搜集补给的人，尽管他曾被苦苦哀求留下。在一周多没有音讯后，他的爱人担心他在废墟中遭遇了不幸。",al={"雷萨恩 是谁","雷萨恩 在哪里","寻找 雷萨恩"}},{q="班艾萨尔废墟是什么地方？",a="班艾萨尔废墟是一处危险之地，雷萨恩 冒险前往那里寻找必要的补给。他的爱人认为这趟旅程极其凶险，独自在那里生存一周的可能性微乎其微。",al={"班艾萨尔是什么","班艾萨尔废墟背景故事","班艾萨尔在哪里"}},{q="为什么 雷萨恩 要回到班艾萨尔废墟？",a="雷萨恩 回到班艾萨尔废墟是为了取回补给。尽管他的爱人恳求他不要去，他还是选择了踏上这段危险的旅程。",al={"为什么 雷萨恩 要回去","为什么 雷萨恩 在班艾萨尔废墟"}},{q="任务发布者请求你带回什么？",a="如果 雷萨恩 还活着，任务发布者请求将他平安带回家。如果他已在废墟中遇难，任务发布者请求寻回他的私人传家宝作为最后的纪念。",al={"任务发布者想要什么","如果 雷萨恩 死了会怎样"}},{q="雷萨恩 失踪了多久？",a="自出发前往班艾萨尔废墟以来，雷萨恩 已经失踪了一周多。考虑到该地区的危险，这段漫长的沉默让他的爱人担心发生了最坏的情况。",al={"雷萨恩 失踪了多久","雷萨恩 离开了多久"}},{q="谁发布了这个任务？",a="该任务由 雷萨恩 悲痛的伴侣或爱人发布，他们渴望得到一个了结，并愿意向途经此处前往班艾萨尔废墟的旅人寻求帮助。",al={"谁发布了 挚爱之人的命运","挚爱之人的命运 任务发布者"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="暮光之锤的营地",s="暮光营地是联盟的一项侦察任务，旨在调查在黑海岸南部主宰之剑周围安营扎寨的神秘邪教徒。调查员通过观察水晶球窥见了他们的祭坛，必须潜入挖掘现场，查明暮光之锤试图挖掘出什么东西。",h="暮光营地是联盟的一项侦察任务，旨在调查在黑海岸南部主宰之剑周围安营扎寨的神秘邪教徒。调查员通过观察水晶球窥见了他们的祭坛，必须潜入挖掘现场，查明暮光之锤试图挖掘出什么东西。",kw={"黑海岸","主宰之剑","欧努","观察水晶球","暮光营地","暮光典籍","暮光之锤"},ang={["class:Druid"]="揭露邪教的研究对于塞纳里奥哨兵来说至关重要，他们致力于让那些带有腐蚀性的远古实体安全地保持埋藏状态。",["faction:Alliance"]="阻止邪教诡异的挖掘活动，可以防止一个正在形成的威胁破坏卡利姆多北部的稳定。",["race:NightElf"]="暮光之锤在黑海岸远古树林的枝叶下，用黑暗巫术玷污了神圣的卡利姆多土地。"},sec={{t="探测挖掘点",b="主宰之剑长久以来一直矗立在黑海岸南部的崎岖山丘上，是一个令人不安的石化谜团，但暮光之锤邪教的突然到来，让这处远古奇观变成了一个现实的威胁。在利用观察水晶球窥探了他们的防御工事后，斥候们被派往营地深处，以便在敌人采取防御措施之前查明他们的真实意图。"},{t="插图典籍",b="搜查营地后发现，这些邪教徒并非仅仅是拾荒者或强盗，他们的行动受到深奥神秘学研究的指引。在他们北部营地的深处，放置着一本古老且精心手绘的典籍，里面配有精湛却令人不安的插图。这本典籍证明，暮光之锤正在蓄意调查埋藏在地下的巨大实体。"}},faq={{q="“暮光营地”任务的目标是什么？",a="你必须潜入黑海岸南部主宰之剑附近的暮光之锤营地，并找回一份详述他们动机的线索——具体来说，就是存放在他们营地中的一本手绘仪式典籍。",al={"暮光营地任务目标","暮光营地要做什么"}},{q="是谁派你去调查营地的？",a="该任务直接从主宰之剑上方眺望台的观察水晶球处获取，延续了代表远古守护者欧努所发起的调查。",al={"谁给予暮光营地任务","暮光营地任务发布者"}},{q="在营地哪里可以找到线索？",a="有效的线索是位于营地北部的暮光典籍。营地中的其他典籍可能是危险的诱饵，会向闯入者释放防护魔法。",al={"书在哪里","暮光典籍位置","寻找暮光营地线索"}},{q="暮光之锤为什么会在主宰之剑？",a="这些邪教徒痴迷于上古之神及其仆从的远古黑暗力量。他们正在挖掘被那把巨大的石剑钉住的巨大石化尸骸，试图研究或唤醒残留在其中的任何远古邪恶。",al={"为什么邪教徒在主宰之剑","暮光之锤在黑海岸的目的"}},{q="找到典籍后会发生什么？",a="找回典籍后会引出“重回欧努身边”任务，指示你将发现的文书带往北部的古树之林，交给那里的远古树人。",al={"暮光营地后续任务","找到暮光典籍后去哪里"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="一位天空之裔同伴看到了你在德鲁伊之道上的潜力，便指引你去雷霆崖找图拉克·符文图腾。他能教你如何前往月光林地的塞纳里奥议会要塞。",h="一位天空之裔同伴看到了你在德鲁伊之道上的潜力，便指引你去雷霆崖找图拉克·符文图腾。他能教你如何前往月光林地的塞纳里奥议会要塞。",kw={"塞纳里奥议会","自然之子","德鲁伊","月光林地","天空之裔","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="作为一名德鲁伊，有人指引你去找图拉克·符文图腾，他能教你如何前往月光林地的塞纳里奥议会。",["race:Skyborne"]="作为一名天空之裔，有人告诉你塞纳里奥议会的德鲁伊会欢迎你，并与你分享他们的知识。"},sec={{t="德鲁伊的欢迎",b="你的导师相信塞纳里奥议会的德鲁伊会欢迎你，并与你分享他们的知识。雷霆崖的图拉克·符文图腾可以教你如何前往他们在月光林地的要塞。"}},faq={{q="我该找谁谈谈？",a="去雷霆崖找图拉克·符文图腾。他能教你如何前往月光林地。",al={"该和谁谈","图拉克·符文图腾","图拉克是谁"}},{q="塞纳里奥议会的要塞在哪里？",a="塞纳里奥议会的要塞位于卡利姆多的月光林地。",al={"议会在哪里","塞纳里奥议会位置","月光林地"}},{q="为什么要派我去月光林地？",a="塞纳里奥议会的德鲁伊可以将他们的知识传授给你。",al={"为何去月光林地","学习德鲁伊之道","德鲁伊训练"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="暴风城的沙德拉斯·月树可以教你如何前往塞纳里奥议会的大本营月光林地。古老教团的德鲁伊有许多智慧可以传授给自然之子。",h="暴风城的沙德拉斯·月树可以教你如何前往塞纳里奥议会的大本营月光林地。古老教团的德鲁伊有许多智慧可以传授给自然之子。",kw={"塞纳里奥议会","自然之子","德鲁伊","卡利姆多","月光林地","沙德拉斯·月树","天翔者","暴风城"},ang={["class:Druid"]="作为一名德鲁伊，你被指引前往塞纳里奥议会。这个古老教团的成员修习德鲁伊之道。",["race:Skyborne"]="作为一名 Skyborne，你将成为最早抵达艾泽拉斯的族人之一，受到欢迎。"},sec={{t="遥远的大本营",b="你被指引去寻找暴风城的暗夜精灵沙德拉斯·月树。他可以教你如何前往卡利姆多的月光林地，那里是塞纳里奥议会的大本营。塞纳里奥议会是一个古老的教团，成员是自然学者和德鲁伊之道的修习者，他们有许多知识可以传授给你。"}},faq={{q="沙德拉斯·月树是谁？",a="沙德拉斯·月树是暴风城的一名暗夜精灵，可以教你如何前往月光林地。",al={"沙德拉斯","暴风城的暗夜精灵","谁教我去月光林地"}},{q="塞纳里奥议会是什么？",a="塞纳里奥议会是一个古老的教团，成员是自然学者和德鲁伊之道的修习者。",al={"塞纳里奥议会","德鲁伊教团","自然教团"}},{q="塞纳里奥议会的大本营在哪里？",a="塞纳里奥议会的大本营位于卡利姆多的月光林地。",al={"塞纳里奥大本营","月光林地在哪里","月光林地"}},{q="我能从塞纳里奥议会学到什么？",a="塞纳里奥议会的德鲁伊有许多智慧可以传授给你。",al={"塞纳里奥教诲","他们能教什么","德鲁伊智慧"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="月光林地",s="一位德鲁伊导师为你指引前往月光林地的道路，让你拜会德迪利特·星焰。在那里，你可以与他谈谈自己刚刚踏上的道路。",h="一位德鲁伊导师为你指引前往月光林地的道路，让你拜会德迪利特·星焰。在那里，你可以与他谈谈自己刚刚踏上的道路。",kw={"熊形态","德迪利特·星焰","德鲁伊","守护者雷姆洛斯","月光林地","永夜港","传送"},ang={["class:Druid"]="作为一名德鲁伊，你的导师欢迎你来到月光林地，并教你一个可以前往那里的法术。"},sec={{t="初次受教",b="你的导师欢迎所有德鲁伊来到月光林地，守护者雷姆洛斯照看着在此休憩的人。你学会了法术“传送：月光林地”，寻求此地的知识或慰藉时，便可前往那里。你的第一课是前往永夜港，与德迪利特·星焰谈谈自己踏上的道路。"},{t="熊形态",b="德迪利特看出你已经掌握了熊形态。他认为你进展顺利。"}},faq={{q="我该在月光林地与谁交谈？",a="前往永夜港村庄，与德迪利特·星焰谈谈你正在走的道路。",al={"该和谁交谈","德迪利特·星焰","永夜港德鲁伊"}},{q="我该如何前往月光林地？",a="你的导师教会你法术“传送：月光林地”，可以将你传送到那里。",al={"月光林地传送","如何前往月光林地","传送法术"}},{q="谁在月光林地守护德鲁伊？",a="守护者雷姆洛斯是月光林地的守护者，照看着在此休憩的德鲁伊。",al={"守护者雷姆洛斯","月光林地守护者","谁守护月光林地"}},{q="德迪利特如何评价我的进展？",a="德迪利特看出你已经掌握了熊形态。",al={"熊形态","是否掌握熊形态","德迪利特的回应"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94923"] = {n="Hats Off",s="Robbie请你去河边鱼人附近找回他丢失的生日帽。他担心家人会知道他去过那里。",h="Robbie请你去河边鱼人附近找回他丢失的生日帽。他担心家人会知道他去过那里。",kw={"生日帽","ellie","帽子","遗失的帽子","鱼人","河流","robbie"},sec={{t="遗失的帽子",b="Robbie在河边玩耍时，弄丢了姐姐送给他的生日帽。他不许靠近鱼人，所以不能请父亲或Ellie帮忙。他猜是某个鱼人捡到了帽子。你需要沿着河边找找看。"}},faq={{q="Robbie是谁？",a="Robbie是个男孩。他在河边玩耍时，弄丢了姐姐送给他的生日帽。",al={"robbie","robbie是谁"}},{q="Robbie丢了什么？",a="Robbie丢了姐姐送给他的生日帽。",al={"robbie的帽子","遗失的帽子"}},{q="Robbie在哪里丢了帽子？",a="Robbie在河里玩耍时弄丢了帽子，请你去鱼人附近的河边找找。",al={"帽子的位置","帽子在哪里"}},{q="Robbie为什么不能请家人帮忙？",a="Robbie不许靠近鱼人。请父亲或Ellie帮忙，就会暴露他去过哪里。",al={"为什么不问爸爸","为什么要隐瞒"}},{q="Robbie知道是不是鱼人拿走了帽子吗？",a="Robbie猜是某个鱼人捡到并留下了他的帽子。",al={"鱼人的帽子","鱼人拿走了吗"}}},fp="8,125,10.268.0,14.89.0,21.55.0,30.111.0,41.111.0,42.62.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="瓦拉纳尔的一位法师会送你从泽风岛前往达拉然城，那里有法师等候你族人的到来。达拉然是探索艾泽拉斯的起点，但若未做好准备、缺乏经验，城外的土地便危机四伏。",h="瓦拉纳尔的一位法师会送你从泽风岛前往达拉然城，那里有法师等候你族人的到来。达拉然是探索艾泽拉斯的起点，但若未做好准备、缺乏经验，城外的土地便危机四伏。",kw={"教派","达拉然","达拉然城","达纳里斯·星风","法师","天空切割者号","瓦拉纳尔","泽风岛"},ang={["race:Skyborne"]="身为天穹之裔，你正从泽风岛前往达拉然，与等候你族人到来的法师会合。"},sec={{t="抵达达拉然",b="近期与教派有关的事件让讲述者留在瓦拉纳尔，而几位法师正在达拉然等候你族人到来。你将前往旅店外的码头，乘坐天空切割者号前往达拉然城。抵达后，请与Danaaris Stargale交谈。你族人仍在城中安顿下来，而离开达拉然的安全范围后，周边地区可能危机四伏。"}},faq={{q="谁在达拉然等候？",a="几位法师正在达拉然等候你族人到来。抵达后，你需要与达纳里斯·星风交谈。",al={"达拉然的法师","达拉然有哪些人","达拉然法师"}},{q="我该从哪里出发？",a="你将从泽风岛出发，在旅店外码头乘坐天空切割者号前往达拉然城。",al={"如何前往达拉然","从泽风岛出发","天空切割者号"}},{q="讲述者为何留在瓦拉纳尔？",a="近期与教派有关的事件改变了讲述者的计划，因此他们打算暂时留在瓦拉纳尔。",al={"为何留在瓦拉纳尔","教派改变计划","瓦拉纳尔法师"}},{q="达拉然城外安全吗？",a="若未做好准备、缺乏经验，达拉然城外的土地便危机四伏。",al={"达拉然城外安全吗","达拉然附近的危险","达拉然郊外"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="“Welcome to Azeroth”标志着天裔旅客通过Skyborne Portal抵达人类首都暴风城。在向暴风要塞报到后，新来者将获得伯瓦尔·弗塔根公爵的正式认可与许可，得以在联盟领土上自由旅行。",h="“Welcome to Azeroth”标志着天裔旅客通过Skyborne Portal抵达人类首都暴风城。在向暴风要塞报到后，新来者将获得伯瓦尔·弗塔根公爵的正式认可与许可，得以在联盟领土上自由旅行。",kw={"伯瓦尔·弗塔根","高等精灵","高阶会","肯瑞托","传送门","天翔者","暴风要塞","欢迎来到艾泽拉斯"},ang={["faction:Alliance"]="伯瓦尔·弗塔根公爵代表安度因·乌瑞恩国王正式欢迎高阶会，并授予他们自由穿行联盟领土的许可。",["race:Skyborne"]="对于天裔来说，这次觐见正式为通过传送门抵达的高等精灵旅客打开了暴风城和联盟领土的大门。"},sec={{t="抵达首都",b="旅客通过神秘的Skyborne Portal抵达，直接踏入了繁华的暴风城首都。作为报到任务的一部分，新来者穿过城市的大道，前往暴风要塞，向摄政王报到。"},{t="觐见摄政王",b="站在宏伟的王座大厅里，伯瓦尔·弗塔根公爵在收到肯瑞托信使的预先通知后，迎接了到来的高阶会成员。摄政王提到，已经有很长一段时间没有高等精灵走在暴风要塞的走廊里了，他慷慨地接受他们作为客人，并代表国王授予他们在所有联盟领土上自由通行的权利。"}},faq={{q="这个任务是关于什么的？",a="“欢迎来到艾泽拉斯”是一个引导任务，旅行者通过天裔传送门进入暴风城，并在暴风要塞向伯瓦尔·弗塔根公爵报到。",al={"欢迎来到艾泽拉斯是什么","欢迎来到艾泽拉斯任务"}},{q="伯瓦尔·弗塔根是谁？",a="伯瓦尔·弗塔根公爵担任暴风城王位的摄政王，在国王瓦里安失踪期间，代表年轻的安度因·乌瑞恩国王在暴风要塞治理国家。",al={"伯瓦尔 弗塔根是谁","暴风城摄政王"}},{q="为什么伯瓦尔要接待天裔？",a="一位来自肯瑞托的信使通知了伯瓦尔·弗塔根，高阶会成员即将抵达。伯瓦尔接受他们作为王室的客人，并允许他们在联盟领土上自由探索和旅行。",al={"为什么天裔在暴风城","暴风城高等精灵"}},{q="什么是高阶会？",a="高阶会代表了与天裔高等精灵相关的派系或团体，他们的到来是由肯瑞托向暴风城的领导层通报的。",al={"高阶会是谁","高阶会背景故事"}},{q="天裔传送门通向哪里？",a="天裔传送门将旅客直接带入人类首都暴风城，让新来者可以直接前往暴风要塞寻求觐见王室。",al={"天裔传送门目的地","传送门去哪"}},{q="天裔可以在联盟领土内自由活动吗？",a="伯瓦尔·弗塔根代表国王正式欢迎天裔作为客人，并明确允许他们在联盟全境畅行无阻。",al={"天裔是联盟吗","天裔加入联盟"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="与 Bonegnaw 的战斗，是你在 Bloodmaster's Ring 成为冠军之路上的下一场较量。食人魔们正等着看你能否带来一场精彩的战斗。",h="与 Bonegnaw 的战斗，是你在 Bloodmaster's Ring 成为冠军之路上的下一场较量。食人魔们正等着看你能否带来一场精彩的战斗。",kw={"bloodmaster","bloodmaster's ring","bonegnaw","较量","冠军","战斗","食人魔"},sec={{t="下一场较量",b="你的胜利还不足以让你成为冠军，竞技场里的地精还想再安排一场战斗。你的对手是Bonegnaw，地精还承诺会有惊喜。食人魔们正在观战，下一场比斗就是为取悦他们而准备的。"},{t="战斗之后",b="地精对这场比斗给自己带来的名声很不满意。不过，食人魔们似乎看得很开心，他警告你别为结果沾沾自喜。"}},faq={{q="我的对手是谁？",a="你在 Bloodmaster's Ring 的对手是 Bonegnaw。",al={"与 bonegnaw 战斗","对手是谁"}},{q="我已经是冠军了吗？",a="竞技场里的地精说，你的胜利还不足以让你成为冠军。",al={"bloodmaster 冠军","成为冠军"}},{q="谁在观看这场战斗？",a="食人魔们正在观看 Bloodmaster's Ring 的这场较量。",al={"食人魔观看","谁看得尽兴"}}},fp="18,170,13.226.0,15.151.1,19.52.0,20.66.0,26.54.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="一名擂台主持人召唤你前往 Bloodmaster’s Ring 与 Mog’thar 对决。观众正等待下一位挑战者登场。",h="一名擂台主持人召唤你前往 Bloodmaster’s Ring 与 Mog’thar 对决。观众正等待下一位挑战者登场。",kw={"主持人","bloodmaster’s ring","挑战者","观众","mog’thar","擂台"},sec={{t="下一位挑战者",b="主持人一直在调动观众的热情，现在又宣布 Mog’thar 将成为下一位挑战者。你被召唤到 Bloodmaster’s Ring，观众正等着看接下来会发生什么。"}},faq={{q="我在 Bloodmaster’s Ring 要面对谁？",a="你被召唤到 Bloodmaster’s Ring 与 Mog’thar 对决。",al={"与 mog’thar 对决","下一位挑战者是谁","bloodmaster’s ring 对手"}},{q="主持人怎么评价 Mog’thar？",a="主持人说 Mog’thar 可不是好惹的。",al={"mog’thar 是谁","下一位挑战者","mog’thar 是闹着玩的吗"}},{q="为什么要派我进擂台？",a="主持人想再介绍一位挑战者，让观众继续兴奋起来。",al={"为什么要和 mog’thar 对决","擂台对决原因","主持人想做什么"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94968"] = {n="Eye of Mugg",s="暮光教派的据点比预想中更大，Krom'rosh便派你前往克罗多克要塞。他要你带回首领已死的证据。",h="暮光教派的据点比预想中更大，Krom'rosh便派你前往克罗多克要塞。他要你带回首领已死的证据。",kw={"洞穴","教派首领","eye of mugg","克罗多克要塞","krom'rosh","牺牲","暮光教派"},sec={{t="克罗多克要塞",b="Krom'rosh担心，若暮光教派继续蹂躏这片土地，更多盟友将会被牺牲。进入洞穴的人寥寥无几能活着回来，教派的据点也比他想象的更大。现在，你要进入克罗多克要塞，带回首领已死的证据。"}},faq={{q="是谁派我进入克罗多克要塞？",a="Krom'rosh派你前往克罗多克要塞，带回暮光教派首领已死的证据。",al={"谁派我去","krom'rosh的要求"}},{q="要塞出了什么问题？",a="暮光教派的据点比Krom'rosh预想的更大，他们一直在蹂躏这片土地，并牺牲盟友。",al={"那里发生了什么","暮光教派的问题"}},{q="Krom'rosh为什么要我进去？",a="Krom'rosh想阻止教派继续蹂躏这片土地、牺牲盟友。",al={"为什么进去","为何进入要塞"}},{q="Krom'rosh要什么证据？",a="他要你带回暮光教派首领已死的证据。",al={"需要的证据","要带回什么"}},{q="进入洞穴的人有很多活下来吗？",a="设法进入洞穴的人，只有少数活着回来。",al={"洞穴幸存者","谁活着出来"}}},fp="11,150,19.268.0,46.105.0,32.119.0,36.98.0,34.58.0,38.43.0"}
P.entries["quest:94973"] = {n="Krol'dok Moulding",s="在洛格玛附近发现的模具似乎是钥匙的一部分。聚居地里或许有人知道它能打开什么。",h="在洛格玛附近发现的模具似乎是钥匙的一部分。聚居地里或许有人知道它能打开什么。",kw={"钥匙","krol'dok moulding","模具","洛格玛","要塞"},sec={{t="奇怪的模具",b="你有一块似乎是为钥匙制作的模具。洛格玛或许有人知道这块东西有什么用。如果它来自要塞，那可能很重要。"}},faq={{q="这块模具有什么用？",a="这块模具似乎是用来制作钥匙的。",al={"模具碎片","这是什么模具","钥匙模具"}},{q="谁能辨认这块模具？",a="洛格玛或许有人了解这块模具。",al={"谁了解这块模具","询问模具","把模具带去哪里"}},{q="它为什么可能很重要？",a="如果这块模具来自要塞，那它一定很重要。",al={"模具重要吗","要塞模具","为什么在意模具"}}},fp="17,108,15.151.0,25.37.0,30.44.0,20.61.0"}
P.entries["quest:94974"] = {n="Key Ingredients",s="Kreza Darkthorn需要皮革和铁来制作钥匙模具。她看着余烬，你去收集材料。",h="Kreza Darkthorn需要皮革和铁来制作钥匙模具。她看着余烬，你去收集材料。",kw={"余烬","iron bar","钥匙","钥匙材料","kreza darkthorn","模具","thick leather"},sec={{t="制作模具的材料",b="Kreza Darkthorn有一个磨损的模具，或许还能用来打造钥匙。她看着余烬，你给她带来四块Thick Leather和十二根Iron Bar。模具应该还能用，Kreza已经准备好看看能做些什么。"}},faq={{q="Kreza需要什么？",a="Kreza让你带来四块Thick Leather和十二根Iron Bar。",al={"需要什么材料","钥匙材料","kreza需要什么"}},{q="这些材料有什么用？",a="这些材料用来用一个粗糙破旧的模具打造钥匙。",al={"为何需要皮革和铁","钥匙用来做什么","模具材料"}},{q="谁在看着余烬？",a="Kreza Darkthorn说，她会看着余烬，你去收集材料。",al={"谁看着余烬","kreza看余烬","余烬保持炽热"}},{q="Kreza怎么评价这个模具？",a="Kreza说，这个模具粗糙又破旧，但仍可能用来打造钥匙。",al={"模具状况","模具还能用吗","钥匙模具"}}},fp="15,115,26.225.0,21.63.0,27.67.0,30.81.0,39.82.0"}
P.entries["quest:94975"] = {n="A Token of Vengeance",s="一位盟友请你前往克罗多克要塞附近的洞穴网络，寻找藏身于其中的暮光之锤教徒。他们的袭击伤害了你的盟友，也威胁着这片土地。",h="一位盟友请你前往克罗多克要塞附近的洞穴网络，寻找藏身于其中的暮光之锤教徒。他们的袭击伤害了你的盟友，也威胁着这片土地。",kw={"复仇信物","教徒之耳","教徒","隐秘洞穴","克罗多克要塞","暮光之锤"},sec={{t="隐秘洞穴",b="斥候报告称，暮光之锤教徒正在克罗多克要塞附近崎岖的地面下活动。你的盟友说，他们的袭击造成了巨大的伤痛，教徒们还在侵占这片土地。盟友请你找到他们的藏身之处，带回十五只教徒之耳，以示复仇。"}},faq={{q="我要找谁？",a="你要寻找藏身在克罗多克要塞附近洞穴网络中的暮光之锤教徒。",al={"这些教徒是谁","暮光之锤在此","教徒之耳"}},{q="为什么要追捕这些教徒？",a="委托者说，这些教徒伤害了他们的盟友，还在侵占这片土地。",al={"为何复仇","为何与他们战斗","他们做了什么"}},{q="斥候发现了什么？",a="斥候报告称，北方崎岖的地形下有教徒活动，那里有一处隐秘的洞穴网络。",al={"斥候报告","教徒在哪里","教徒动向"}},{q="要我带回什么？",a="你需要从克罗多克要塞的暮光之锤教徒身上收集十五只 Cultist Ears。",al={"要收集什么","教徒之耳任务","需要多少只耳朵"}}},fp="20,158,16.328.0,21.99.0,34.90.0,24.99.0,30.98.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale教你了解野兽与主人之间的羁绊。你的第一个挑战，是在Zephras的水边驯服一只Windsong Crawler。",h="Quel'ana Quickgale教你了解野兽与主人之间的羁绊。你的第一个挑战，是在Zephras的水边驯服一只Windsong Crawler。",kw={"驯服野兽","奎尔安娜·疾风","驯兽棒","瓦拉纳尔","风歌爬行者","泽弗拉斯"},sec={{t="初次羁绊",b="你将从驯兽棒和一只Windsong Crawler开始。在水边驯服一只，练习你的技能，然后把驯兽棒交还给瓦拉纳尔的Quel'ana Quickgale。眼下，你的精进之路将从这只生物开始。"}},faq={{q="奎尔安娜让我驯服什么？",a="奎尔安娜让你在泽弗拉斯的水边驯服一只风歌爬行蟹。",al={"什么野兽","驯服目标","爬行者任务"}},{q="驯兽棒有什么用？",a="驯兽棒用于驯服风歌爬行蟹。",al={"驯兽棒用法","驯服工具","驯兽棒任务"}},{q="在哪里能找到风歌爬行蟹？",a="在泽弗拉斯的水边可以找到风歌爬行蟹。",al={"爬行者位置","爬行者在哪","泽弗拉斯野兽"}},{q="是谁给了我驯兽棒？",a="瓦拉纳尔的奎尔安娜·迅风给了你驯兽棒。",al={"任务给予者","奎尔安娜是谁","奎尔安娜·迅风"}},{q="我为什么要学习驯服野兽？",a="了解野兽与主人之间的羁绊，是你的职业迈向精通的第一步。",al={"为什么驯服爬行者","野兽精通","初次驯服"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="Quel'ana Quickgale请你在阵风浆果低地驯服一只疾风踏行鸟。在开阔地带磨练技艺，将为你迎接后续考验做好准备。",h="Quel'ana Quickgale请你在阵风浆果低地驯服一只疾风踏行鸟。在开阔地带磨练技艺，将为你迎接后续考验做好准备。",kw={"疾风踏行鸟","阵风浆果低地","暴躁的疾风踏行鸟","奎尔安娜·疾风","驯兽棒","驯服野兽","瓦拉纳尔","泽弗拉斯"},sec={{t="穿越平原",b="你已经证明自己能够驯服河中的爬行兽。Quel'ana Quickgale现在交给你一根驯兽棒，并让你前往Zephras的低地寻找一只疾风踏行鸟。这种骄傲的有翼生物在平原上疾驰。赢得它的信任，练习你的本领，然后把驯兽棒带回瓦拉纳尔交给Quel'ana。"}},faq={{q="奎尔安娜想让我驯服什么？",a="奎尔安娜让你在阵风浆果低地驯服一只暴躁的疾风踏行鸟。",al={"驯服什么","驯服疾风踏行鸟","什么野兽"}},{q="我在哪里能找到疾风踏行鸟？",a="暴躁的疾风踏行鸟位于泽弗拉斯平原上的阵风浆果低地。",al={"疾风踏行鸟在哪里","疾风踏行鸟位置","低地在哪里"}},{q="驯兽棒有什么用？",a="奎尔安娜给你驯兽棒，让你驯服一只暴躁的疾风踏行鸟。",al={"驯兽棒用途","驯兽棒有什么用","如何驯服野兽"}},{q="是谁交给我这项任务？",a="瓦拉纳尔的奎尔安娜·迅风让你驯服一只暴躁的疾风踏行鸟，并归还驯兽棒。",al={"是谁派我来的","奎尔安娜是谁","迅风"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:94980"] = {n="Krol'dok Moulding",s="Krol'dok 模具看起来像是钥匙的模具。法霍德要塞里或许有人知道更多。",h="Krol'dok 模具看起来像是钥匙的模具。法霍德要塞里或许有人知道更多。",kw={"法霍德要塞","钥匙","krol'dok 模具","模具"},sec={{t="钥匙模具",b="你拿到一个看起来是用来制作钥匙的模具。法霍德要塞里或许有人知道它的用途，你便带着它去打听详情。"}},faq={{q="Krol'dok 模具是什么？",a="Krol'dok 模具看起来是用来制作钥匙的。",al={"kroldok 模具","krol'dok 模具","这是什么模具"}},{q="谁可能了解这个模具？",a="法霍德要塞里或许有人了解这个模具。",al={"谁了解这个模具","模具专家","询问模具"}},{q="带上模具后会怎么样？",a="你带去询问的人说，会看看能用它做些什么。",al={"模具结果","他们怎么说","钥匙模具"}}},fp="17,107,13.146.0,30.46.0,31.50.0,39.71.0"}
P.entries["quest:94981"] = {n="Key Ingredients",s="Alphonse Dumas需要一些材料，才能用粗糙的模具制作一把钥匙。你需要为他带去Thick Leather和Iron Bars。",h="Alphonse Dumas需要一些材料，才能用粗糙的模具制作一把钥匙。你需要为他带去Thick Leather和Iron Bars。",kw={"alphonse dumas","余烬","iron bars","钥匙","钥匙材料","模具","thick leather"},sec={{t="钥匙所需材料",b="你收集所需材料时，Alphonse Dumas一直让余烬保持炽热。模具虽然粗糙，但合适的材料或许能让他制作出一把钥匙。"}},faq={{q="Alphonse需要什么？",a="Alphonse Dumas请你带去四块Thick Leather和十二根Iron Bars。",al={"所需材料","要带什么","钥匙材料"}},{q="Alphonse在制作什么？",a="Alphonse希望用合适的材料，通过粗糙的模具制作一把钥匙。",al={"他在制作什么","钥匙有什么用","钥匙模具"}},{q="我该把材料交给谁？",a="把Thick Leather和Iron Bars带给Alphonse Dumas。",al={"谁要这些材料","材料要交给谁"}}},fp="15,126,21.141.0,24.73.0,24.80.0,30.56.0"}
P.entries["quest:94983"] = {n="Twilight Mementos",s="侦察兵确认暮光之锤的藏身处后，Sergeant Riftan 派你北上前往克罗多克要塞。他要你带回邪教徒落败的证据。",h="侦察兵确认暮光之锤的藏身处后，Sergeant Riftan 派你北上前往克罗多克要塞。他要你带回邪教徒落败的证据。",kw={"洞穴","邪教徒手镯","邪教徒藏身处","克罗多克要塞","侦察兵","sergeant riftan","暮光纪念品","暮光之锤"},sec={{t="侦察兵的报告",b="侦察兵带给 Sergeant Riftan 关于邪教徒藏身处的严峻消息。他们的报告证实了其他人的说法。北边有个洞穴，隐蔽在周围环境之中。Riftan 认为，这让邪教徒得以在群山深处立足。他派你前往克罗多克要塞，带回暮光之锤邪教徒已被击败的证据。"}},faq={{q="是谁派我去北边？",a="Sergeant Riftan 要你前往克罗多克要塞，寻找暮光之锤邪教徒，并带回他们落败的证据。",al={"谁派我去","sergeant riftan"}},{q="侦察兵发现了什么？",a="侦察兵的报告证实了邪教徒藏身处的消息，北边有个隐蔽的洞穴。",al={"侦察兵报告","他们发现了什么"}},{q="藏身处在哪里？",a="藏身处位于北边一个隐蔽在周围环境中的洞穴里。Riftan 认为那里是他们在群山深处的据点。",al={"邪教徒洞穴","邪教徒在哪里"}},{q="Riftan 想要什么证据？",a="Riftan 要你带回克罗多克要塞的邪教徒已被击败的证据。",al={"什么证据","邪教徒证据"}},{q="这些邪教徒是什么人？",a="他们是暮光之锤的成员，侦察兵的报告已经证实了他们藏身处的位置。",al={"暮光教徒","暮光之锤"}}},fp="17,161,15.350.0,29.129.0,25.96.0,21.125.0,28.96.0,21.99.0"}
P.entries["quest:94992"] = {n="Rescue Roundup",s="Wheeler请你把他走失的马Biscuit带回Wheeler's Grange。她回来后，农庄便能重新开张。",h="Wheeler请你把他走失的马Biscuit带回Wheeler's Grange。她回来后，农庄便能重新开张。",kw={"biscuit","demar","马","走失的马","营救马匹","马厩同伴","wheeler's grange"},sec={{t="Biscuit归来",b="Wheeler走失的马名叫Biscuit。她低下头，轻轻蹭了蹭你的手臂。你把她带回Wheeler's Grange。Wheeler很感激Biscuit回到了身边，不过她觉得这匹马暂时还得独自待着。农庄重新开张了。"}},faq={{q="Biscuit是谁？",a="Biscuit是Wheeler的马。她走失了，需要被带回Wheeler's Grange。",al={"biscuit的马","走失的马","biscuit是谁"}},{q="Biscuit要去哪儿？",a="Biscuit需要被带回Wheeler's Grange。",al={"把马带去哪儿","biscuit的位置","马的目的地"}},{q="Wheeler为什么感激？",a="因为你把Biscuit带回了农庄，Wheeler很感激。",al={"为什么感谢","救回biscuit","wheeler的感谢"}},{q="Biscuit是独自待着吗？",a="Wheeler说Biscuit暂时会独自待着，并希望能找到她的一些马厩同伴。",al={"biscuit独自待着","马厩同伴在哪儿","其他马匹"}},{q="Wheeler's Grange开张了吗？",a="Biscuit回来后，Wheeler's Grange重新开张了。",al={"农庄开张","wheeler重新营业","农庄重新开张"}}},fp="14,125,15.260.0,15.95.0,30.53.0,24.65.0,17.90.0,25.56.0"}
P.entries["quest:94997"] = {n="Lingering Essence",s="Riftan请你把一袋被诅咒的纪念物送到法霍德要塞，交给Ashe Amberhall。他希望她能通过研究，查明这些物品蕴含着何种能量。",h="Riftan请你把一袋被诅咒的纪念物送到法霍德要塞，交给Ashe Amberhall。他希望她能通过研究，查明这些物品蕴含着何种能量。",kw={"ashe amberhall","邪教徒","被诅咒的纪念物","能量","法霍德要塞","残留的精华","riftan","satchel of cursed mementos"},sec={{t="在要塞",b="在法霍德要塞，Ashe Amberhall从你手中接过袋子，得知是Riftan派你送来的。她说，Riftan与邪教徒长期斗争，疲惫或许已蒙蔽了他的判断。尽管如此，她也承认他的担忧可能并非空穴来风，于是开始检查那些物品。"}},faq={{q="是谁让我送这袋东西？",a="Riftan请你把Satchel of Cursed Mementos送给Ashe Amberhall。",al={"谁派我来的","riftan的袋子","riftan是谁"}},{q="Ashe Amberhall是谁？",a="Ashe Amberhall是一位备受尊敬的学者，她的研究领域或许能帮助她查明这些物品蕴含的能量。",al={"ashe是谁","amberhall"}},{q="我要把纪念物送到哪里？",a="把Satchel of Cursed Mementos送到法霍德要塞，交给Ashe Amberhall。",al={"袋子要送到哪里","法霍德要塞","袋子的送达地点"}},{q="袋子里装着什么？",a="袋子里装着被诅咒的纪念物，Riftan希望Ashe检查它们蕴含着何种能量。",al={"袋子里有什么","被诅咒的纪念物","袋中物品"}},{q="Riftan为什么要让Ashe检查这些东西？",a="Riftan希望Ashe通过研究，查明这些物品蕴含着何种能量。",al={"为什么找ashe","袋子是做什么的","残留的精华"}},{q="Ashe怎么看待Riftan的担忧？",a="Ashe担心，Riftan与邪教徒长期斗争后的疲惫可能会影响他的判断，不过她也说他的担忧或许有根据。",al={"ashe信任riftan吗","riftan疲惫","ashe的看法"}}},fp="17,153,11.279.0,38.73.0,22.108.0,29.72.0,23.95.0,42.86.0,41.132.0"}
P.entries["quest:94998"] = {n="Curios of Curiosity",s="你带着一袋不同寻常的纪念品去找 Melanie Sable。它们做工精巧，或许派得上用场。",h="你带着一袋不同寻常的纪念品去找 Melanie Sable。它们做工精巧，或许派得上用场。",kw={"做工","奇珍异宝","melanie sable","纪念品","遗存","一袋纪念品"},sec={{t="给 Melanie 的一袋纪念品",b="检查过这些纪念品的人让你把袋子送给 Melanie Sable。他们认为这些物品很安全，但仍不知道它们的来历。它们的做工别具一格，Melanie 或许能找到用途。"}},faq={{q="我该把这些纪念品交给谁？",a="按检查者的要求，把这袋纪念品交给 Melanie Sable。",al={"把袋子送到哪里","melanie sable 是谁"}},{q="这些纪念品是什么？",a="它们是某种事物的遗存，但检查者也不清楚具体是什么。",al={"袋子里有什么","这些奇珍是什么"}},{q="这些纪念品为何与众不同？",a="据说它们的做工相当独特而精巧。",al={"它们有什么特别之处","奇珍的做工"}},{q="这些纪念品安全吗？",a="检查者让你告诉 Melanie，这些纪念品很安全。",al={"袋子安全吗","它们有危险吗"}}},fp="19,104,21.217.0,34.68.0,22.76.0,29.63.0,22.65.0"}
P.entries["quest:95"] = {n="斯温的复仇",s="出于悲痛与复仇的驱使，隐士斯温·约根请求过往旅人回到他位于暮色森林南部的破败农场。尽管他多年来一直在追捕屠杀他家人的暗影骑士，但曾有一个可疑的身影在他的谷仓附近埋下了某样东西，那可能藏着真相。",h="出于悲痛与复仇的驱使，隐士斯温·约根请求过往旅人回到他位于暮色森林南部的破败农场。尽管他多年来一直在追捕屠杀他家人的暗影骑士，但曾有一个可疑的身影在他的谷仓附近埋下了某样东西，那可能藏着真相。",kw={"暗影骑士","逆风小径","暮色森林","松散的土堆","树桩","斯温·约根","斯温的复仇","约根农场"},ang={["class:Paladin"]="来自逆风小径的邪恶势力对无辜者的残酷屠杀，必须得到正义的制裁，为死者讨回公道。",["faction:Alliance"]="约根一家的惨剧是暮色森林与世隔绝的又一例证，展示了在没有暴风城常规军队巡逻的情况下，黑暗势力的触角延伸得有多远。"},sec={{t="农场的惨剧",b="斯温·约根曾是一名在暮色森林东南部耕作的普通农夫。在他外出时，从逆风小径策马而下的兜帽暗影骑士袭击了他的家园，屠杀了他的家人，他的人生由此破碎。斯温回到家看到屠杀现场时，瞥见一个不知名的人影在谷仓附近鬼鬼祟祟，慌忙地在土里埋着什么东西。斯温选择了复仇，他立即出发去追杀凶手，将那个被掩埋的东西丢在了身后。"},{t="挖掘秘密",b="如今，心怀愤怒的斯温在西部的山丘上安营扎寨，他需要有人回到约根农场。在农舍和破败谷仓之间的一截老树桩后，有一堆匆忙堆起的松散泥土。找回埋在那里的东西，是了解为何那些暗影骑士会对一位宁静的暮色森林农夫下手的关键第一步。"}},faq={{q="谁是斯温·约根？",a="斯温·约根曾是一位居住在暮色森林东南部，靠近逆风小径边缘的普通农夫。在回家发现家人被邪恶的骑士杀害后，他抛弃了农场，变成了一个一心只想向凶手复仇的隐士。",al={"斯温是谁","斯温背景故事","斯温人物传记"}},{q="斯温的农场发生了什么？",a="斯温的农场遭到了来自逆风小径的神秘暗影骑士的突袭。他们在斯温赶回防守之前就屠杀了他全家，并将农场洗劫一空。",al={"约根农场惨剧","斯温农场发生了什么","为什么斯温的农场被摧毁"}},{q="谁在谷仓后埋了东西？",a="屠杀刚刚发生后，斯温看到一个暗影般的身影潜伏在谷仓附近埋藏物品。为了追击暗影骑士，斯温逃向了荒野，没能抓住那个陌生人，也没能挖掘出被隐藏的东西。",al={"谁埋了那个东西","斯温农场的暗影人影","谁挖了土堆"}},{q="那堆松散的泥土在哪里？",a="那堆松散的泥土位于暮色森林东南部的约根农场，就在谷仓和破败农舍之间的一截老树桩的正后方。",al={"土堆在哪里","土堆位置","树桩在哪里"}},{q="暗影骑士是什么人？",a="暗影骑士是骑马从逆风小径中出来的邪恶兜帽骑士。关于他们的起源知之甚少，但他们在暮色森林的暴力入侵只会留下死亡与废墟。",al={"暗影骑士是什么","暗影骑士背景","逆风小径的骑士"}},{q="为什么斯温自己不挖出那个埋藏的物品？",a="当斯温回到家看到那个人埋藏物品时，他被悲痛所吞噬，立即去追赶撤退的暗影骑士了。等他建立起隐藏的营地时，农场已经被洗劫一空，对他来说那是一个过于痛苦、无法直接重返的地方。",al={"为什么斯温不去检查泥土","斯温为何离开"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="向安努回复",s="“返回奥努身边”是一个联盟任务，它终结了对黑海岸沿岸扎营的邪教徒的初步调查。在突袭了邪教徒的营地并尝试阅读《暮光宝典》后，冒险者获得了一张令人发狂的书页，需要将其交给古树之林里的知识古树奥努。",h="“返回奥努身边”是一个联盟任务，它终结了对黑海岸沿岸扎营的邪教徒的初步调查。在突袭了邪教徒的营地并尝试阅读《暮光宝典》后，冒险者获得了一张令人发狂的书页，需要将其交给古树之林里的知识古树奥努。",kw={"黑海岸","古树之林","令人发狂的书页","古神","奥努","暮光宝典","暮光之锤"},ang={["class:Druid"]="涂鸦中混乱且不自然的共鸣，代表了对自然秩序的亵渎，而德鲁伊正致力于与像奥努这样的树人共同维护这些秩序。",["faction:Alliance"]="调查黑海岸沿岸的邪教活动，可以确保像奥伯丁这样的暗夜精灵定居点免受隐秘威胁的侵害。",["race:NightElf"]="黑暗邪教徒对黑海岸海岸的亵渎威胁到了知识古树们所守护的平衡，这使得奥努的警告与卡多雷息息相关。"},sec={{t="疯狂的一瞥",b="在暮光之锤的营地中发现《暮光宝典》后，任何窥视书中内容的人都会立刻感受到感官遭受的冲击。书写的文字在羊皮纸上游动舞动，原本华丽的卷轴装饰变成了怪诞的图形。精神上的压力如此巨大，以至于凡人的心智在屈服于眩晕之前，只能忍受撕下这一页胡乱涂写的笔记。"},{t="古老的疑虑",b="当这张碎片被送到奥努手中时，这位高大的古树辨认出了弥漫在其上的不自然气息。羊皮纸散发出一种混乱、原始的魔法，奥努将其直接归因于埋藏在地底的古老阴影力量。虽然这些潦草的涂鸦难以辨认，但它们证实了暮光之锤在黑海岸的存在并非单纯的强盗行径，而是某种更深层、更亵渎的计划的一部分。"}},faq={{q="从《暮光宝典》中取出的书页是什么？",a="这张书页被简单地称为“令人发狂的书页”，它是从该邪教的圣书中撕下来的一页。注视它会引起严重的精神痛苦，因为上面的文字会扭曲成与原始虚空魔法相连的怪诞、变幻的图形。",al={"令人发狂的书页","什么是涂鸦","暮光宝典书页"}},{q="奥努是谁？",a="奥努是一棵扎根于黑海岸南部古树之林的知识古树。他作为长者守护者和学者，引导暗夜精灵和联盟盟友对抗森林中出现的腐蚀。",al={"奥努是谁","奥努黑海岸","树人奥努"}},{q="奥努从这些涂鸦中学到了什么？",a="奥努感知到了从书页中散发出的混乱、原始的能量，并确认了古老邪恶实体的影响。这些文字表明暮光之锤的邪教徒正在黑海岸各处积极寻找遗迹地点和掩埋的力量。",al={"奥努发现了什么","涂鸦的含义"}},{q="为什么暮光之锤会出现在黑海岸？",a="该邪教被吸引到黑海岸是为了挖掘精灵遗迹，发掘与原始黑暗和古神有关的远古力量的痕迹，并利用这片土地上的混乱来掩盖他们的仪式。",al={"黑海岸的邪教徒","暮光之锤为何在此"}},{q="这项调查接下来会引向何处？",a="在发现邪教的存在后，奥努将注意力转向了北方的玛塞斯特拉废墟，指挥冒险者在邪教徒夺取这些古代遗物之前将其保护起来。",al={"下一个任务是什么","返回奥努身边后的后续"}},{q="为什么阅读宝典会导致头晕？",a="《暮光宝典》上刻有虚空和混乱的黑暗、疯狂魔法。这些符文会主动迷惑凡人的心智，引起幻觉和昏厥，从而阻止外人解开它们的秘密。",al={"为何宝典导致头晕","暮光宝典的效果"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani派你前往菲拉斯的莫沙彻营地，向巫医尤克里求助。尤克里以魔法闻名，也是一名猎人。",h="Tan'jani派你前往菲拉斯的莫沙彻营地，向巫医尤克里求助。尤克里以魔法闻名，也是一名猎人。",kw={"莫沙彻营地","菲拉斯","猎人","魔法","另一边","tan'jani","巫医尤克里"},sec={{t="Tan'jani的朋友",b="穿越菲拉斯，你可以在莫沙彻营地找到巫医尤克里，他是Tan'jani的老朋友。Tan'jani说尤克里精通魔法，也是一名猎人。你受命去和他谈谈，告别了广阔的平原。"}},faq={{q="是谁派我去找尤克里？",a="Tan'jani派你去找老朋友巫医尤克里。",al={"tan'jani派我去","谁是老tan'jani"}},{q="我在哪里能找到尤克里？",a="巫医尤克里在菲拉斯的莫沙彻营地。",al={"尤克里的位置","巫医在哪里"}},{q="我为什么要去找尤克里？",a="Tan'jani说尤克里正在寻求帮助，请你去和他谈谈。",al={"为什么找尤克里谈话","tan'jani想要什么"}},{q="尤克里是做什么的？",a="巫医尤克里精通魔法，也是一名猎人。",al={"尤克里的职业","巫医猎人"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="瑟伯切尔的Lumina Windsinger讲述了那场让Banon身受重伤的袭击。她说，在路上袭击他们的是一个狼人。",h="瑟伯切尔的Lumina Windsinger讲述了那场让Banon身受重伤的袭击。她说，在路上袭击他们的是一个狼人。",kw={"banon","豺狼人","lumina windsinger","路上的袭击","瑟伯切尔","the debt","狼人"},sec={{t="路上的伤痛",b="瑟伯切尔的Lumina Windsinger向你讲述了路上发生的事。一个体形巨大、形似狼的狼人袭击了她的队伍，杀死了随行的卫兵。Banon挡在那怪物和Lumina之间，Lumina则用一道法术将它赶走。那时，Banon已经被严重咬伤。他催她丢下自己离开，但她留了下来，两人一瘸一拐地继续前行，随后被豺狼人发现。"},{t="Banon的最后时刻",b="瑟伯切尔的Banon在转而攻击Lumina之前，已被豺狼人的利刃刺中多处。她看得出，他仍然认得她，却无法控制自己。Lumina相信，是那个狼人害了他，并发誓要杀死它，不让它给其他生灵带来同样的恐怖。"}},faq={{q="是谁在路上袭击了Lumina和Banon？",a="一个体形巨大、形似狼的狼人在路上袭击了Lumina和Banon。",al={"什么袭击了他们","狼人袭击","路上的袭击者"}},{q="卫兵们怎么样了？",a="狼人杀死了陪同Lumina和Banon的卫兵。",al={"卫兵的命运","卫兵怎么样了","路上的卫兵"}},{q="Lumina是怎么赶走狼人的？",a="Lumina设法施放了一道法术，惊吓了狼人，使它逃走了。",al={"狼人为何逃走","lumina的法术","什么吓跑了它"}},{q="Banon为什么会被咬伤？",a="Banon为了保护Lumina，奋不顾身地挡在狼人面前，被那怪物严重咬伤。",al={"banon被咬伤","banon如何受伤","banon发生了什么事"}},{q="Lumina在哪里向你讲述事情的经过？",a="Lumina Windsinger在瑟伯切尔向你讲述事情的经过。",al={"哪里能找到lumina","lumina的位置","瑟伯切尔"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan警告说，狼人威胁着银松森林，并指出Old Fire-Eye是个敌人，凭借未知魔法抗拒死亡。他请你查明打造一把特殊利刃所需的材料。",h="Trevan警告说，狼人威胁着银松森林，并指出Old Fire-Eye是个敌人，凭借未知魔法抗拒死亡。他请你查明打造一把特殊利刃所需的材料。",kw={"月吻之刃","利刃材料","old fire-eye","银松森林","特殊武器","trevan","狼人"},sec={{t="铁匠的清单",b="Old Fire-Eye是袭击Trevan及其同伴的狼人。Trevan会给你一份清单，列出打造对付他的武器所需的材料。材料备齐后，Trevan相信自己认识一位能打造这把利刃的铁匠。"}},faq={{q="Old Fire-Eye是谁？",a="Old Fire-Eye是体型最大、最凶狠的狼人，他袭击了Trevan及其同伴。",al={"old fire-eye","火眼狼人","大型狼人"}},{q="为什么Old Fire-Eye总能回来？",a="未知魔法让Old Fire-Eye无法真正死去。",al={"fire-eye为什么不会死","old fire-eye的魔法","不会死透的狼人"}},{q="Trevan需要我做什么？",a="Trevan会给你一份清单，列出打造特殊武器所需的材料。",al={"trevan想要什么","trevan的清单","利刃材料"}},{q="为什么需要特殊利刃？",a="Old Fire-Eye凭借未知魔法抗拒死亡，因此Trevan说必须用特殊武器才能彻底击倒他。",al={"月吻之刃为什么","对付old fire-eye的武器","杀死fire-eye"}},{q="谁能打造这把利刃？",a="Trevan相信自己认识一位能打造这把利刃的铁匠。",al={"打造利刃的铁匠","谁打造月刃","利刃铁匠"}}},fp="19,185,14.239.0,20.97.0,39.51.0,30.74.0,30.108.0,24.57.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="Data Hoarders是居住在铁炉堡的一名流亡侏儒耶玛所委托的任务。在诺莫瑞根绝望的大撤退期间，她将家族最珍贵的档案复制到了打孔卡上，却不慎在城市大门外的冰雪漂流中弄丢了几张。找回这些丢失的数据卡意味着要抢救从先进海军工程图纸到无可替代的家族食谱等一切重要资料。",h="Data...",kw={"数据囤积者","丹莫罗","诺莫瑞根","铁炉堡","耶玛","打孔卡","第二次战争","潜艇船体"},ang={["faction:Alliance"]="联盟非常依赖侏儒的独创性；帮助流离失所的难民保存战时工程记录，可以确保宝贵的联盟技术知识不会永远丢失。",["profession:Cooking"]="和世界级的工程图纸放在一起的，还有Quikswitch奶奶的个人辣椒食谱，这证明了美食与军事科学一样，具有同样的情感价值。",["profession:Engineering"]="工程师们可以体会到隐藏在这些卡片中的巨大价值，其中包括真实的第二次战争潜艇船体蓝图和复杂的奥术技术方程。",["race:Gnome"]="对于侏儒冒险者来说，找回这些打孔卡是文化保护的问题，确保重要的发明和家族记忆不会因为他们家园的放射性废墟而遗失。"},sec={{t="冰雪中的混乱",b="当穴居人入侵和随后的核辐射灾难迫使侏儒离开诺莫瑞根时，成千上万的人带着在混乱中抢到的任何物品逃离。耶玛采取了谨慎的措施，将几代人的家族知识转录到实体打孔卡档案中。不幸的是，一个破损的背包将几张关键卡片散落在了这座沦陷城市周围的雪原上。没有这些丢失的打孔卡，剩余的数据就会显示为无法解读的乱码，这可能会抹去她家族的知识遗产。"},{t="方程与辣椒",b="侏儒的数据档案反映了他们文明所侧重的奇异广度。Quikswitch家族的记录包括深奥的奥术技术领域方程、至关重要的第二次战争潜艇船体蓝图，以及Quikswitch奶奶的秘制辣椒食谱。对外人来说，将军事工程与家庭烹饪结合起来似乎很奇怪，但对于在铁炉堡幸存的难民来说，保存家庭生活的美好与保存技术奇迹同样重要。"}},faq={{q="耶玛是谁？",a="耶玛是一位设法逃脱诺莫瑞根陷落的侏儒难民，现在安全地居住在铁炉堡的矮人大厅中。",al={"耶玛","谁发布了数据囤积者","数据囤积者任务发布者"}},{q="丢失的卡片上存储了什么数据？",a="这些打孔卡保存着快换家族的档案，包括奥术技术方程、可追溯到第二次战争的潜艇船体图纸，以及快换奶奶的辣椒食谱。",al={"什么是打孔卡","卡片上有什么","快掣家族档案"}},{q="数据卡是在哪里丢失的？",a="它们在洁娜逃离诺莫瑞根时从她背包的破洞里滑落，埋在了丹莫罗这座地下城市大门外的雪地里。",al={"卡片在哪里","数据卡位置","她在哪里弄丢了卡片"}},{q="为什么没有丢失的卡片，洁娜就无法阅读幸存的卡片？",a="洁娜说，如果没有丢失的打孔卡，数据太乱了，无法恢复。任务中没有解释这些卡片是如何编码或组织这些信息的。",al={"为什么要找回所有卡片","乱码数据","打孔卡数据"}},{q="侏儒在第二次战争中对潜艇发挥了什么作用？",a="在第二次战争期间，侏儒通过先进的工程技术为联盟的军事行动做出了巨大贡献，特别是设计并驾驶潜水艇来对抗部落的海军部队。",al={"侏儒潜艇 第二次战争","潜艇船体设计"}},{q="为什么侏儒难民住在铁炉堡？",a="在诺莫瑞根因穴居人入侵和灾难性辐射而突然陷落后，幸存的侏儒逃离了他们的地下家园，并得到了国王麦格尼·铜须在邻近的矮人城市铁炉堡提供的庇护。",al={"为什么侏儒在铁炉堡","侏儒与矮人同住"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="灰谷的被遗忘者Ulric Frostveil发现，你在寻找科尔宝石，这对联盟施法者来说是再熟悉不过的差事。他指引你前往黑暗深渊，那里的纳迦仍在使用这些宝石。",h="灰谷的被遗忘者Ulric Frostveil发现，你在寻找科尔宝石，这对联盟施法者来说是再熟悉不过的差事。他指引你前往黑暗深渊，那里的纳迦仍在使用这些宝石。",kw={"灰谷","黑暗深渊","被遗忘者","科尔宝石","纳迦","乌尔里克·霜幕"},sec={{t="灰谷中的宝石",b="Ulric让你从灰谷北面的黑暗深渊废墟带回一枚科尔宝石。他说，下面的纳迦仍在使用这些宝石，它们可以强化魔法武器和器具。他警告你不要独自前往。"},{t="Ulric的意图",b="Ulric察觉到宝石中有腐化之力，并说他能驱散纳迦女巫注入其中的邪恶。他还问你是否愿意把宝石卖给他，用于学术研究。"}},faq={{q="乌尔里克·霜幕是谁？",a="乌尔里克·霜幕是灰谷的一名被遗忘者，他请你给他带回一枚科尔宝石。",al={"乌尔里克·霜幕","乌尔里克是谁","灰谷的被遗忘者"}},{q="我在哪里能找到科尔宝石？",a="乌尔里克指引你向北前往黑暗深渊，纳迦仍在那里使用科尔宝石。",al={"科尔宝石位置","宝石在哪里","黑暗深渊宝石"}},{q="科尔宝石有什么用途？",a="科尔宝石有时会被用来强化魔法武器和器具。",al={"科尔宝石用途","宝石魔法","科尔宝石有什么作用"}},{q="乌尔里克为什么想要科尔宝石？",a="乌尔里克请你给他带回一枚科尔宝石，并说他可能会将其用于学术研究。",al={"乌尔里克想要宝石","为什么要宝石","霜幕的宝石"}},{q="还有谁在使用科尔宝石？",a="黑暗深渊的纳迦仍在使用科尔宝石。",al={"纳迦宝石","谁在使用科尔宝石","黑暗深渊纳迦"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="一名地精有一件货物要送给法霍德要塞的骑士指挥官 Demar Brant。你受托将 Frazzlespark's Crate 送给他。",h="一名地精有一件货物要送给法霍德要塞的骑士指挥官 Demar Brant。你受托将 Frazzlespark's Crate 送给他。",kw={"箱子","demar brant","法霍德要塞","frazzlespark","frazzlespark's crate","地精的货物","骑士指挥官"},sec={{t="送往要塞的货物",b="Frazzlespark 让你前往西南方的法霍德要塞，骑士指挥官 Demar Brant 正在那里等候。箱子是送给他的，地精特意说出了他的全名。到了要塞，Demar 称地精不过是达成目的的手段，是他所说的那些交易的一部分；他声称，这些交易能确保自己族人的安全与成功。"}},faq={{q="谁在等着收箱子？",a="骑士指挥官 Demar Brant 正在法霍德要塞等着收 Frazzlespark's Crate。",al={"谁要这个箱子","demar brant 的货物"}},{q="我该把 Frazzlespark's Crate 送到哪里？",a="把 Frazzlespark's Crate 送到法霍德要塞，交给骑士指挥官 Demar Brant。要塞位于 Frazzlespark 西南方。",al={"箱子的位置","法霍德要塞在哪里"}},{q="为什么 Demar 要求别人叫他的全名？",a="Frazzlespark 提到，Demar 总让这名地精叫他的全名，但没有说明原因。",al={"demar 的全名","为什么是骑士指挥官"}},{q="为什么 Frazzlespark 称它为特别货物？",a="Frazzlespark 称这是一件特别货物，并说 Demar Brant 正在法霍德要塞等着收货。",al={"箱子交付","箱子有什么特别之处"}},{q="这件货物为什么重要？",a="Demar Brant 说，为了确保自己族人的安全与成功，有些交易非做不可；他称那名地精不过是达成目的的手段。",al={"为什么要送箱子","地精的安全"}}},fp="20,126,19.303.0,29.82.0,37.102.0,39.95.0,49.98.0,30.152.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="“Fishin' Time”是吉尔伯特·格雷（Gilbert Gray）发布的一项简单的跑腿任务。这位年迈的垂钓者正悠闲地坐在暴风城港口，享受着迷人的海岸风光。就在鱼群开始上钩时，他的鱼饵用完了，因此他请求路过的冒险者前往城内的运河区，帮他补给鱼饵盒。",h="“Fishin' Time”是吉尔伯特·格雷（Gilbert...",kw={"运河","凯瑟琳·莱兰","钓鱼时间","吉尔伯特·格雷","夜行虫","发光的浮漂","暴风城港口","贸易区"},ang={["faction:Alliance"]="花时间协助像吉尔伯特·格雷这样的老市民，体现了维持暴风城生活与士气的点滴日常琐事。",["race:Human"]="对于以暴风城为家的人类来说，帮助邻里长辈度过一个宁静的午后钓鱼时光，是远离王国政治纷争的一种惬意调剂。"},sec={{t="水边的一天",b="并非暴风城里的每个人都沉浸在政治、战争或迫在眉睫的阴谋之中。在港口边，吉尔伯特·格雷度过着平静的日子，享受着海风，看着浮漂在潮汐中起舞。但狂热的垂钓者很容易忘了查看自己的渔具，而鱼群一阵接一阵地上钩，很快就会耗尽哪怕是准备最充分的饵料罐。与其放弃他珍视的鲈鱼，这位老人转向好心的冒险者请求补给，希望能补充必需品。"},{t="运河边的补给",b="暴风城的本地垂钓需求都经由凯瑟琳·莱兰（凯瑟琳·利兰）满足。她在繁忙的贸易区以西，沿着石砌运河经营着一家知名的渔具店。莱兰为全城的渔民供应鱼饵和诱饵，确保像吉尔伯特·格雷这样的老顾客永远不会因为缺少发光的浮漂或扭动的夜行虫而不得不提前收竿。"}},faq={{q="吉尔伯特·格雷是谁？",a="吉尔伯特·格雷是一位年迈的渔夫，驻守在暴风城港口的水边。他满足于在海边度过抛竿垂钓的日子，当补给不足时，他会请路过的冒险者帮忙去取新鲜的鱼饵和诱饵。",al={"吉尔伯特·格雷","老格雷","谁发布的任务"}},{q="凯瑟琳·莱兰是谁？",a="凯瑟琳·莱兰是暴风城的常驻渔具供应商。她的商店位于贸易区以西的城市运河沿岸，在那里她向王国的垂钓者出售渔具和鱼饵。",al={"凯瑟琳·莱兰","暴风城渔具供应商","莱兰 暴风城"}},{q="吉尔伯特·格雷在哪里钓鱼？",a="吉尔伯特·格雷位于暴风城港口的水边，在那里他可以避开拥挤的城市街道，欣赏广阔的海景。",al={"吉尔伯特·格雷位置","吉尔伯特·格雷在哪里","港口渔夫"}},{q="吉尔伯特·格雷需要什么补给？",a="吉尔伯特·格雷需要夜行虫作为鱼饵，还需要一个发光的浮漂作为诱饵，这两样东西都可以从运河边的凯瑟琳·莱兰那里买到。",al={"钓鱼时间任务物品","格雷需要什么鱼饵"}},{q="为什么吉尔伯特·格雷不自己去取补给？",a="当你与他交谈时，鱼正咬钩咬得欢，他不想为了跑回城里补货而错过这个绝佳的垂钓点或放跑好鱼。",al={"为什么格雷不能自己买鱼饵","为什么格雷需要帮助"}},{q="凯瑟琳·莱兰的商店在运河哪里？",a="她的商店位于贸易区以西，正对着运河水域，可以直接从横跨城市水道网的石砌人行道到达。",al={"凯瑟琳·莱兰位置","莱兰的商店在哪里","贸易区运河"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="玛塞斯特拉遗物",s="这个任务指引联盟探险者沿着黑海岸的海岸线向北，去搜寻杂草丛生的玛塞斯特拉废墟。欧努，一位扎根于古树之林的知识古树，正在寻找这些古老的卡多雷神器，以了解暮光之锤教派是如何利用暗夜精灵魔法来举行邪恶仪式的。",h="这个任务指引联盟探险者沿着黑海岸的海岸线向北，去搜寻杂草丛生的玛塞斯特拉废墟。欧努，一位扎根于古树之林的知识古树，正在寻找这些古老的卡多雷神器，以了解暮光之锤教派是如何利用暗夜精灵魔法来举行邪恶仪式的。",kw={"黑海岸","古树之林","主宰之剑","玛塞斯特拉","欧努","遗物","玛塞斯特拉废墟","暮光之锤"},ang={["class:Druid"]="帮助欧努可以让德鲁伊侍奉自然界最伟大的长者哨兵之一，保护黑海岸的古老历史不被黑暗教徒所扭曲。",["faction:Alliance"]="防止暮光之锤将古代魔法武器化，对于保护卡利姆多北部免受黑暗地下势力的侵害至关重要。",["race:NightElf"]="对于暗夜精灵来说，看着他们大分裂前辉煌时期的遗物被从土里挖出来，这既是对文明衰落的沉痛提醒，也是一个令人震惊的警告：他们祖先的强大技艺正被末日疯子所利用。"},sec={{t="一项令人不安的发现",b="在探险者从潜伏在名为“主宰之剑”的巨大纪念碑周围的教徒手中找回一份被污染的羊皮纸后，欧努解读出了一个令人不安的真相。上面的文字并非本土教派的经文，而是一段被诅咒的古暗夜精灵文字残片。这份被暮光之锤污染的羊皮纸揭示，这些末日狂热者正在利用被遗忘的精灵魔法来唤醒或召唤他们古老的主人回到凡间。"},{t="陨落的壁垒",b="为了对抗这一邪恶企图，欧努指引英雄们前往位于黑海岸东北岸的玛塞斯特拉废墟。很久以前，玛塞斯特拉曾是上层精灵文明的一座辉煌壁垒，但在大分裂中毁于一旦。虽然这座城市已经沦为瓦砾、杂草丛生并遭到纳迦的入侵，但其最初奥术和精神魔法的强大残余仍萦绕在散落于石基之上的破碎骨灰瓮和古代遗物中。"},{t="洞悉黑暗阴谋",b="通过从废墟杂草丛生的瓦砾中收集幸存的工艺品，黑海岸的守卫者们希望揭开教徒们打算利用的具体手段。欧努研究着注入在这些遗物中的残留魔法，与时间赛跑，试图在暮光之锤完全扭曲古老的卡多雷魔法以解放其地下主人之前，解读出教派的计划。"}},faq={{q="什么是黑暗深渊遗物？",a="它们是遗留在玛塞斯特拉废墟中的附魔陶器、骨灰瓮和工艺品的碎片。它们创造于大分裂前古暗夜精灵文明的鼎盛时期，至今仍散发着残留的魔法能量。",al={"什么是遗物","黑暗深渊遗物背景","玛塞斯特拉精灵遗物"}},{q="欧努为什么想要这些遗物？",a="欧努发现暮光之锤教派正在利用古老的精灵魔法，试图将他们的黑暗主人带回这个世界。通过研究从玛塞斯特拉找回的完整遗物，欧努希望了解该教派打算如何操纵那股古老的力量。",al={"欧努为何需要遗物","黑暗深渊遗物的用途"}},{q="玛塞斯特拉废墟位于何处？",a="废墟位于黑海岸的东北海岸线沿途，在亚米萨兰和巴莎兰废墟以北，刚过奥萨拉克斯之塔。",al={"玛塞斯特拉在哪里","玛塞斯特拉位置"}},{q="暮光之锤试图召回谁？",a="该教派崇拜古老而邪恶的主人；欧努警告说，他们正在使用古老的精灵魔法将那些古老的主人带回艾泽拉斯。",al={"暮光之锤的主人是谁","黑海岸教派主人"}},{q="玛塞斯特拉在成为废墟之前是什么？",a="玛塞斯特拉曾是数千年前暗夜精灵的一座伟大壁垒和城市。它在大分裂期间沦为废墟，此后被荒野、鬼魂以及像纳迦这样邪恶的沿海生物所占据。",al={"玛塞斯特拉历史","玛塞斯特拉是什么"}},{q="谁提供了“黑暗深渊遗物”任务？",a="该任务由欧努提供，这是一位扎根于黑海岸中南部古树之林的远古树人，在调查过主宰之剑后即可领取。",al={"谁发布黑暗深渊遗物任务","黑暗深渊遗物任务发放者"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="银松森林的Trevan Rol请你把材料带给塔伦米尔的奥特，并请他承接一份定制委托。他打造的简易刀刃令幽暗城的铁匠们刮目相看，这份委托给了他展示手艺的机会。",h="银松森林的Trevan Rol请你把材料带给塔伦米尔的奥特，并请他承接一份定制委托。他打造的简易刀刃令幽暗城的铁匠们刮目相看，这份委托给了他展示手艺的机会。",kw={"委托","定制刀刃","奥特","铁匠","塔伦米尔","幽暗城","武器匠"},sec={{t="铁匠的机会",b="Trevan Rol请你把材料带给塔伦米尔的奥特，并请他承接一份委托。奥特以向旅人出售简易刀刃而闻名。Trevan买了一把，后来带到幽暗城保养，当地铁匠对它的品质感到惊讶。他们以为那是出自名匠之手，没想到竟是奥特的作品。如今，你要给他一个机会，让他按你的要求锻造一把刀刃。"},{t="奥特的答复",b="奥特说，以前从没人请他承接定制委托。他通常按自己的风格打造朴实实用的武器，并表示自己并不追求名声。虽然愿意一试，但他不明白，你为何选择他，毕竟幽暗城也有铁匠承接定制委托。"}},faq={{q="奥特是谁？",a="奥特是塔伦米尔的一名武器匠，向旅人出售简易刀刃。",al={"奥特 铁匠","奥特是谁","塔伦米尔铁匠"}},{q="为什么幽暗城的铁匠要我去找奥特？",a="那名铁匠买过奥特打造的刀刃，听到幽暗城的铁匠称赞它的品质后感到惊讶。他想给奥特一个机会，让他打造一件特别的作品。",al={"为什么找奥特","幽暗城铁匠委托","奥特 委托"}},{q="我要给奥特带什么？",a="你要把材料带给塔伦米尔的奥特，并请他承接委托，为你锻造一把刀刃。",al={"给奥特的材料","我要带什么","奥特 材料"}},{q="奥特会打造定制武器吗？",a="奥特说，以前从没人请他承接定制委托，但他很乐意一试。",al={"奥特 定制刀刃","奥特能为我锻造吗","奥特 定制委托"}},{q="为什么奥特问我为何选择他？",a="奥特说幽暗城也有铁匠承接定制委托，他不明白你为何舍近求远来找他。",al={"为什么选奥特","奥特纳闷原因","为什么不找幽暗城铁匠"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="一名港口管理员请你清剿东风海岸的鱼人。水手、渔夫，甚至他的孩子们，都一直在抱怨这些麻烦家伙。",h="一名港口管理员请你清剿东风海岸的鱼人。水手、渔夫，甚至他的孩子们，都一直在抱怨这些麻烦家伙。",kw={"东风海岸","渔夫","murloc","murloc oracle","murloc warrior","港口管理员","水手","saltwater savages"},sec={{t="港口的抱怨",b="港口管理员听够了水手、渔夫，甚至自己孩子们的抱怨。鱼人让他头疼，但他还得经营港口。他请你去东风海岸杀掉一些鱼人，希望周围的喧闹能消停一阵。"}},faq={{q="港口管理员为什么要杀鱼人？",a="水手、渔夫和港口管理员的孩子们总在抱怨鱼人。他称它们是麻烦，并希望经营港口时能清静一些。",al={"为何杀鱼人","鱼人骚扰港口"}},{q="他指的是哪些鱼人？",a="他请你去东风海岸杀掉 Murloc Oracles 和 Murloc Warriors。",al={"鱼人种类","预言者和战士"}},{q="鱼人在哪里？",a="港口管理员告诉你去东风海岸找鱼人。",al={"东风海岸的鱼人","鱼人在哪里"}},{q="杀掉这些鱼人能解决问题吗？",a="港口管理员料想很快会有更多鱼人回来，但他希望它们死后，自己能清静一阵。",al={"鱼人会回来","事情结束了吗"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="码头主管Whizzbuzz悬赏征求Old Rot-Chum死亡的证据。这只好斗的鱼人一直在南部海域袭击小船。",h="码头主管Whizzbuzz悬赏征求Old Rot-Chum死亡的证据。这只好斗的鱼人一直在南部海域袭击小船。",kw={"鱼人","鱼人岛屿","old rot-chum","划艇","小船","南部海域","码头主管whizzbuzz"},sec={{t="海上威胁",b="南部海域的水手和游泳者经常遭到袭击，目标是划艇和其他小船。当地渔夫称袭击者为Old Rot-Chum，这是一只好斗的鱼人。码头主管Whizzbuzz悬赏征求它死亡的证据，并请你把证据带给他。"}},faq={{q="Old Rot-Chum是谁？",a="Old Rot-Chum是当地渔夫给一只格外好斗的鱼人起的绰号。",al={"old rot-chum","rot-chum","谁是rot-chum"}},{q="在哪里见过Old Rot-Chum？",a="有人在南部海域见过Old Rot-Chum，那里靠近鱼人横行的岛屿。",al={"old rot-chum在哪里","rot-chum的位置","鱼人在哪里"}},{q="Old Rot-Chum袭击什么？",a="Old Rot-Chum一直在袭击划艇和其他小船。",al={"rot-chum袭击什么","船只遇袭","鱼人与划艇"}},{q="谁提供悬赏？",a="码头主管Whizzbuzz悬赏征求Old Rot-Chum死亡的证据。",al={"谁要rot-chum的证据","码头主管的悬赏","谁悬赏抓old rot-chum"}},{q="Whizzbuzz要什么证据？",a="码头主管Whizzbuzz请你带来Old Rot-Chum死亡的证据。",al={"rot-chum的什么证据","带来证据","死亡的证据"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz想为他的水上咖啡馆新炖菜准备新鲜海鲜。你收集当地食材，为菜单换换花样。",h="Fimbo Greasemitz想为他的水上咖啡馆新炖菜准备新鲜海鲜。你收集当地食材，为菜单换换花样。",kw={"海滩","咖啡馆","fimbo greasemitz","鱼","鱼人眼睛","烤野猪肉","sand crawler的肉","海鲜炖菜"},ang={["profession:Cooking"]="作为一名厨师，你看得出Fimbo正在寻找新鲜的本地食材，准备做一道海鲜炖菜。"},sec={{t="一道新菜",b="Fimbo Greasemitz经营着一家水上咖啡馆，每天的菜单上都有烤野猪肉和鱼。他想试做一道海鲜炖菜，请你从附近的海滩带回鱼人的眼睛和Sand Crawler的肉。"}},faq={{q="Fimbo Greasemitz是谁？",a="Fimbo Greasemitz经营着一家水上咖啡馆，想在菜单上添一道海鲜炖菜。",al={"fimbo是谁","fimbo咖啡馆","fimbo grease­mitz"}},{q="Fimbo需要什么食材？",a="Fimbo请你为他的海鲜炖菜带回鱼人的眼睛和Sand Crawler的肉。",al={"炖菜食材","什么肉","鱼人眼睛"}},{q="Fimbo为什么想做海鲜？",a="他想用一道新的海鲜炖菜给咖啡馆每天供应的烤野猪肉和鱼换换花样。",al={"为什么炖菜","新菜单","咖啡馆食物"}},{q="在哪里能找到这些食材？",a="Fimbo说，附近的海滩上能找到鱼人的眼睛和Sand Crawler的肉。",al={"哪里有肉","哪里有食材","海滩上的东西"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95125"] = {n="Ott's Masterwork",s="奥特已准备好用上好的材料为你锻造一把利刃。你受邀观看他的工作。",h="奥特已准备好用上好的材料为你锻造一把利刃。你受邀观看他的工作。",kw={"铁匠","利刃","锻造","杰作","材料","奥特"},sec={{t="在锻炉旁",b="奥特认为这些材料品质上乘，也希望自己的作品能达到你的期望。他为你锻造利刃，随后将其交给你，供你踏上旅途。"}},faq={{q="谁在为我锻造利刃？",a="奥特正在用你提供的上好材料锻造利刃。",al={"谁在锻造","奥特的利刃","奥特铁匠"}},{q="我能观看奥特锻造吗？",a="奥特请你退后一些，随后开始锻造；你要做的是观看他工作。",al={"观看奥特锻造","看利刃如何制成","锻造过程"}},{q="利刃完成后，奥特会说什么？",a="奥特称这把利刃是他的得意之作，并希望它在你的旅途中能派上用场。",al={"奥特完工","奥特说什么","利刃完成"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="Trevan Rol请你将Ott's Masterwork带给他，地点在银松森林。这把剑是他面对野兽前完成的最后一件作品。",h="Trevan Rol请你将Ott's Masterwork带给他，地点在银松森林。这把剑是他面对野兽前完成的最后一件作品。",kw={"野兽","露米娜","月银之刃","奥特","奥特的杰作","银松森林","特雷文·罗尔"},sec={{t="这把剑",b="奥特感谢你给了他这个机会，并请你代他向Trevan转达谢意。你将Ott's Masterwork带回银松森林，交给Trevan Rol。"},{t="Trevan的认可",b="Trevan检查了这把剑，认可奥特的手艺。他说接下来只剩下杀死野兽，并让你准备好后去找Lumina。"}},faq={{q="是谁打造了奥特的杰作？",a="奥特打造了这把剑，并让你把它送给特雷文·罗尔。",al={"谁打造了这把剑","奥特的剑","杰作打造者"}},{q="特雷文·罗尔是谁？",a="特雷文·罗尔负责在银松森林接收并检查奥特的杰作。",al={"特雷文是谁","特雷文的剑","特雷文·罗尔"}},{q="我该把这把剑带到哪里？",a="把奥特的杰作带到银松森林交给特雷文·罗尔。",al={"剑要送到哪里","把奥特的杰作带到哪里","剑的去处"}},{q="特雷文觉得这把剑怎么样？",a="特雷文检查了这把剑，说它很合用。",al={"特雷文喜欢这把剑吗","奥特的剑好吗","特雷文的认可"}},{q="特雷文之后我该和谁交谈？",a="特雷文让你准备好后去找露米娜。",al={"接下来做什么","露米娜是谁","找露米娜交谈"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger让你在银松森林用月银之刃猎杀Old Fire-Eye。塑风者正等着他毙命，Lumina希望这把剑能助你一臂之力。",h="Lumina Windsinger让你在银松森林用月银之刃猎杀Old Fire-Eye。塑风者正等着他毙命，Lumina希望这把剑能助你一臂之力。",kw={"巴农","吉尔尼斯","露米娜·风歌","月银之刃","老火眼","银松森林","塑风者"},sec={{t="剑的使命",b="你已从塑风者那里得到月银之刃。当地人说，Old Fire-Eye常在此地以南一带广阔的区域出没，通常就在通往吉尔尼斯的大门附近。Lumina让你找到他，用这把剑了结他。塑风者的感激全系于此。"},{t="狩猎归来",b="你回来后，Lumina向你道谢，并说Banon终于可以安息了。随后，她将一丝族人的魔力施加在染血的剑刃上，希望风能引领它前行。"}},faq={{q="是谁让我去猎杀老火眼？",a="露米娜·风歌让你用月银之刃猎杀老火眼。",al={"谁派我来","露米娜的任务","风之歌唱者"}},{q="我在哪里能找到老火眼？",a="当地人说，老火眼在露米娜以南的一大片区域出没，通常在通往吉尔尼斯的大门附近。",al={"火眼的位置","老火眼在哪里","吉尔尼斯大门"}},{q="我该用什么对付老火眼？",a="露米娜让你用月银之刃了结老火眼。",al={"对付火眼的剑","月银武器","用什么武器"}},{q="露米娜为什么要杀死老火眼？",a="露米娜说，老火眼死后，塑风者会感激你。",al={"为何杀死火眼","为何猎杀他","火眼的缘由"}},{q="巴农是谁？",a="露米娜说，老火眼被杀后，巴农就能安息了。",al={"巴农是谁","巴农安息","谁是巴农"}},{q="露米娜对剑做了什么？",a="露米娜将一丝族人的魔力施加在染血的月银之刃上。",al={"剑的魔力","露米娜为剑附魔","风之魔法"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="一名兽人指引你前往洛格玛，这座哨站坐落在战火纷飞的河林。去向Krom'rosh报到，他的经验帮助哨站一次次抵御了袭击。",h="一名兽人指引你前往洛格玛，这座哨站坐落在战火纷飞的河林。去向Krom'rosh报到，他的经验帮助哨站一次次抵御了袭击。",kw={"袭击","东海岸","krom'rosh","哨站","河林","洛格玛","斯通纳德"},sec={{t="屹立不倒的哨站",b="河林位于斯通纳德东北方，沿东海岸延伸。许多人都曾试图夺取这片土地，成功者却寥寥无几。洛格玛是一座屡遭袭击却存留下来的小哨站。你奉命前往那里向Krom'rosh报到。这位老盟友的作战经验帮助哨站一次次抵御袭击。"}},faq={{q="洛格玛在哪里？",a="洛格玛位于河林，在斯通纳德东北方，沿东海岸而建。",al={"洛格玛位置","洛格玛在哪里","洛格玛哨站"}},{q="我该向谁报到？",a="你要前往洛格玛哨站向Krom'rosh报到。",al={"向谁报到","krom'rosh是谁","krom'rosh"}},{q="洛格玛是什么地方？",a="洛格玛是河林中的一座小哨站，曾抵御过无数次袭击。",al={"洛格玛是什么","河林哨站","小哨站"}},{q="Krom'rosh为何在洛格玛？",a="Krom'rosh与敌人作战的经验帮助哨站坚持了下来。",al={"krom'rosh为何在那里","krom'rosh的职责","谁管理洛格玛"}},{q="河林是怎样的一片土地？",a="河林位于斯通纳德东北方，沿东海岸而伸展，是一片饱经战火的土地。",al={"河林","河林是什么样的地方","饱经战火的土地"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="一位旅人请你寻找他的兄弟 Tan'jani。消息称他在洛克莫丹以南，最新的线索指向河林的洛格玛。",h="一位旅人请你寻找他的兄弟 Tan'jani。消息称他在洛克莫丹以南，最新的线索指向河林的洛格玛。",kw={"血迹斑斑的信","洛克莫丹","失踪的兄弟","河林","洛格玛","tan jani","tan'jani"},sec={{t="失踪的兄弟",b="一位旅人的兄弟 Tan'jani 外出寻找某样未知的东西。一条消息称他在洛克莫丹以南的某处。一封血迹斑斑的信提到了更南边的河林和洛格玛，旅人请你去那里寻找他。"}},faq={{q="Tan'jani 是谁？",a="Tan'jani 是请你寻找他的那位旅人的兄弟。",al={"tan'jani","tan jani","失踪的兄弟"}},{q="最后一次提到 Tan'jani 是在哪里？",a="一封血迹斑斑的信提到了河林和洛格玛，那里比洛克莫丹更靠南。",al={"tan'jani 在哪里","tan'jani 的位置","洛格玛"}},{q="Tan'jani 在寻找什么？",a="Tan'jani 总是在寻找某样东西，但他的兄弟不知道那是什么。",al={"他在寻找什么","tan'jani 在寻找什么","他为什么离开"}},{q="消息里说了什么？",a="一位旅人说，他曾在洛克莫丹以南的某处遇见 Tan'jani。一封血迹斑斑的信提到了河林和洛格玛，但信上大部分内容都无法辨认。",al={"tan'jani 的消息","血迹斑斑的信","信后来怎么样了"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
